import java.util.Scanner
import Math.max

object Main extends App {
  val sc = new Scanner(System.in)

  val fene = "Fennec"
  val snuke = "Snuke"

  val N = sc.nextInt()
  val edges = Array.fill[List[Int]](N+1)(Nil)
  for (_ <- 1 to N-1) {
    val a, b = sc.nextInt()
    edges(a) = b :: edges(a)
    edges(b) = a :: edges(b)
  }


  // fenec
  val stack = new scala.collection.mutable.Stack[(Int, Int)]
  val dp = new Array[Boolean](N+1)
  dp(1) = true

  var feneMax = 0

  for(e <- edges(1)) {
    stack.push((e, 1))
    dp(e) = true
  }

  while(!stack.isEmpty) {
    val (node, score) = stack.pop

    node match {
      case N =>
        if((score-1) % 2 == 1) feneMax = max(feneMax, score-1)
      case _ =>
        feneMax = max(feneMax, score)
        var flag = true
        for(e <- edges(node)) {
          if(!dp(e)) {
            flag = false
            stack.push((e, score+1))
            dp(e) = true
          }
        }
        if(flag) feneMax = max(feneMax, score)
    }
  }


  // snuke
  for(i <- 1 to N)
    dp(i) = false
  dp(N) = true

  var snukeMax = 0

  for(e <- edges(N)) {
    stack.push((e, 1))
    dp(e) = true
  }

  while(!stack.isEmpty) {
    val (node, score) = stack.pop

    node match {
      case 1 =>
        if((score-1) % 2 == 1) snukeMax = max(snukeMax, score-1)
      case _ =>
        snukeMax = max(snukeMax, score)
        var flag = true
        for(e <- edges(node)) {
          if(!dp(e)) {
            flag = false
            stack.push((e, score+1))
            dp(e) = true
          }
        }
        if(flag) snukeMax = max(snukeMax, score)
    }
  }

  if(feneMax > snukeMax)
    println(fene)
  else
    println(snuke)
}

import java.util.Scanner
import Math.max

object Main extends App {
  val sc = new Scanner(System.in)

  val fene = "Fennec"
  val snuke = "Snuke"

  val N = sc.nextInt()
  val edges = Array.fill[List[Int]](N+1)(Nil)
  for (_ <- 1 to N-1) {
    val a, b = sc.nextInt()
    edges(a) = b :: edges(a)
    edges(b) = a :: edges(b)
  }


  //
  sealed trait Color
  case object B extends Color
  case object W extends Color

  val q = new scala.collection.mutable.Queue[(Int, Color)]
  val dp = new Array[Boolean](N+1)

  dp(1) = true; dp(N) = true

  for(e <- edges(1)) {
    q.enqueue((e, B))
  }
  for(e <- edges(N)) {
    q.enqueue((e, W))
  }

  var fenScore = 0; var snuScore = 0
  while(!q.isEmpty) {
    val (node, color) = q.dequeue
    if (!dp(node)) {
      dp(node) = true
      color match {
        case B => fenScore += 1
        case W => snuScore += 1
      }

      for(e <- edges(node)) {
        q.enqueue((e, color))
      }
    }
  }

  if(fenScore > snuScore)
    println(fene)
  else
    println(snuke)

}

