using namespace std;

struct Node
{
    vector<int> edges;
    int father = -1;
    int depth = 0;
    int size = 0;
};

using Tree = vector<Node>;

int FindSizes(Tree &t, int node)
{
    t[node].size = 1;
    for (const auto &son : t[node].edges) {
        if (son != t[node].father) {
            t[son].father = node;
            t[son].depth = t[node].depth + 1;
            t[node].size += FindSizes(t, son);
        }
    }
    return t[node].size;
}

int KthAncestor(const Tree &t, int node, int k)
{
    while (k > 0) {
        node = t[node].father;
        k -= 1;
    }
    return node;
}

bool FirstWins(Tree &t, int first, int second)
{
    auto total_size = FindSizes(t, first);
    auto distance = t[second].depth - 1;

    auto root_second = KthAncestor(t, second, distance / 2);
    auto turns_second = t[root_second].size;
    auto turns_first = total_size - turns_second;

    return turns_first > turns_second;
}

int main()
{
    int nodes;
    cin >> nodes;

    Tree tree(nodes);
    for (int i = 1; i < nodes; i += 1) {
        int a, b;
        cin >> a >> b;
        tree[a - 1].edges.push_back(b - 1);
        tree[b - 1].edges.push_back(a - 1);
    }

    cout << (FirstWins(tree, 0, nodes - 1) ? "Fennec" : "Snuke") << "\n";
    return 0;
}

