using namespace std;
using Graph = vector<vector<int>>;
typedef long long ll;
typedef pair<int,int> P;

vector<int> depth;
vector<int> subtree_size;
void dfs(const Graph &G, int v, int p, int d) {
    depth[v] = d;
    for (auto nv : G[v]) {
        if (nv == p) continue; // nv が親 p だったらダメ
        dfs(G, nv, v, d+1);
    }

    // 帰りがけ時に、部分木サイズを求める
    subtree_size[v] = 1; // 自分自身
    for (auto c : G[v]) {
        if (c == p) continue;
        subtree_size[v] += subtree_size[c]; // 子のサイズを加える
    }
}

int main(){
    int N; cin >> N;

    // グラフ入力受取
    Graph G(N);
    for (int i = 0; i < N-1; ++i) {
        int a, b;
        cin >> a >> b;
        G[a - 1].push_back(b - 1);
        G[b - 1].push_back(a - 1);
    }

    ll f[N], s[N];

    // 探索
    int root = 0; // 仮に頂点 0 を根とする
    depth.assign(N, 0);
    subtree_size.assign(N, 0);
    dfs(G, root, -1, 0);
    // 結果
    for (int v = 0; v < N; ++v) {
        // cout << v << ": depth = " << depth[v] << ", subtree_size = " << subtree_size[v] << endl;
        f[v] = depth[v];
    }

    // 探索
    root = N - 1; // 仮に頂点 0 を根とする
    depth.assign(N, 0);
    subtree_size.assign(N, 0);
    dfs(G, root, -1, 0);
    // 結果
    for (int v = 0; v < N; ++v) {
        // cout << v << ": depth = " << depth[v] << ", subtree_size = " << subtree_size[v] << endl;
        s[v] = depth[v];
    }

    ll F = 0, S = 0;
    rep(i, N){
        if (f[i] <= s[i]) F++;
        else S++;
    }

    if (F >= S) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;
}

