ll N;
vector<ll> g[MAX];
ll d[2][MAX];

void dijkstra(ll s, ll idx) {
    ll clr[MAX]={};
    ll u, v, i;

    for(i=0; i<N; i++) d[idx][i]=INF;
    d[idx][s]=0;
    priority_queue<P> q;
    q.push(P(0, s));
    while(q.size()) {
        P f=q.top(); q.pop();
        u=f.sc;
        clr[u]=1;
        if(d[idx][u]<-f.ft) continue;
        for(i=0; i<g[u].size(); i++) {
            v=g[u][i];
            if(clr[v]) continue;
            if(d[idx][v]>d[idx][u]+1) {
                d[idx][v]=d[idx][u]+1;
                q.push(P(-d[idx][v], v));
            }
        }
    }

}

int main(void) {
    cin >> N;
    ll i;
    for(i=0; i<N-1; i++) {
        ll a, b;
        cin >> a >> b;
        a--; b--;
        g[a].pb(b);
        g[b].pb(a);
    }

    dijkstra(0, 0);
    dijkstra(N-1, 1);

    ll x=0, y=0;
    for(i=0; i<N; i++) {
        if(d[0][i]<=d[1][i]) x++;
        else y++;
    }

    if(x>y) puts("Fennec");
    else puts("Snuke");

}

