};

node nodes[100005];

void dfs(int id,int p)
{
	nodes[id-1].x=1;
	nodes[id-1].p=p;
	if(p==-1)
		nodes[id-1].d=0;
	else
		nodes[id-1].d=nodes[p-1].d+1;
	for(int i=1;i<=con[id-1].size();i++)
		if(con[id-1][i-1]!=p)
		{
			dfs(con[id-1][i-1],id);
			nodes[id-1].x+=nodes[con[id-1][i-1]-1].x;
		}
}

int par(int id,int n)
{
	if(n==0)
		return id;
	else if(n==1)
		return nodes[id-1].p;
	else
		return par(nodes[id-1].p,n-1);
}



