int n;
vector<vector<int>> to;
bool d[100000];
int route[100000];
int dfs(int i,int goal){
	if(i==goal) return 0;
	int ret=0;
	d[i]=true;
	rep(j,to[i].size()){
		int v=to[i][j];
		if(d[v]) continue;
		ret+=dfs(v,goal)+1;
	}
	d[i]=false;
	return ret;
}
int dfs2(int i,int count){
	if(i==0) return count;
	int ret=0;
	d[i]=true;
	rep(j,to[i].size()){
		int v=to[i][j];
		if(d[v]) continue;
		int tmp=dfs(v,count+1);
		ret=max(ret,tmp);
		if(tmp>0) route[i]=count;
	}
	d[i]=false;
	return ret;
}
signed main(){

