		a--;b--;
		to[a].push_back(b);
		to[b].push_back(a);
	}
	int f=dfs(0,n-1),s=dfs(n-1,0);
	if(f>s) cout<<"Fennec"<<endl;
	else if(f==s&&f!=n) cout<<"Snuke"<<endl;
