deque<int> bfs(int s, int n) {

	unordered_map<int, deque<int>> path;

	vector<bool> visited(n + 1, 0);

	queue<int> q;

	q.push(s);

	while (q.size()) {

		int current = q.front();

		q.pop();

		if (current == n) return path[current];

		for (auto child : adjList[current]) {

			if (visited[child]) continue;

			visited[child] = 1;

			q.push(child);

			path[child] = path[current];

			path[child].emplace_back(current);


		}

	}

}

void dfs(int n) {

	for (auto child : adjList[n]) {

		if (visited[child]) continue;

		visited[child] = 1;

		dfs(child);

	}
}

