        int a, b; cin >> a >> b; a--;b--;
        V[a].push_back(b);
        V[b].push_back(a);
    } 
    bool grid[N];
    memset(grid, false, sizeof(grid));
    grid[0] = true;
    queue<pair<int, int>> Q;
    Q.push(make_pair(0, 0));
    ll count = 1;
    ll path;

    while(!Q.empty()){
        int v = Q.front().first, cnt = Q.front().second; Q.pop();
        //cout << v << endl;
        for(auto u : V[v]){
            //cout << " " << u << endl;
            if(!grid[u]){
                grid[u] = true;
                if(u == N-1){
                    path = cnt;
                    continue;
                }
                Q.push(make_pair(u, cnt+1));
                count++;
            }
        }
    }

    ll b = count-path;
    ll w = N - path - b;
    b += path-path/2;
    w += path/2;
    if(b >= w) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

}

