        G[a-1].pb(edge{b-1, 1});
        G[b-1].pb(edge{a-1, 1});
    }
    dijkstra(0);
    vector<int> ppath;
    set<int> sn;
    set<int> fn;
    vector<int> used(N);
    int pr = N-1;
    ppath.pb(N-1);
    while(ppath[ppath.size()-1] != 0) {
        ppath.pb(pre[pr]);
        pr = pre[pr];
        // cout << pr << endl;
    }
    reverse(ppath.begin(), ppath.end());
    int fnd = 1;
    int snd = 2;
    int cnt = 0;
    int th = (int)ppath.size()/2 + ppath.size()%2;
    int fncnt = 0;
    int sncnt = 0;
    for(auto x: ppath) {
        if (cnt+1 <= th) {
            used[x] = fnd;
            fncnt++;
            REP(i,G[x].size()) {
                fn.insert(G[x][i].to);
            }
        } else {
            used[x] = snd;
            sncnt++;
            REP(i,G[x].size()) {
                sn.insert(G[x][i].to);
            }
        }
        cnt++;
    }
    for(auto x: fn) {
        if(used[x]==0) {
            fncnt++;
        }
    }
    for(auto x: sn) {
        if(used[x]==0) {
            sncnt++;
        }
    }

    if(sncnt < fncnt) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }

    return 0;
}

