struct Node{
    int no;
    int par;
    int dist;
    int sum;
    bool par_n;
    vector<Node*> child;
    void build(int i){
        no=i;
        par=i;
        dist=0;
        sum=1;
        par_n=false;
    }
};
struct Tree{
    int n;
    vector<Node> node;
    Tree(int k){
        n=k;
        node.resize(n+1);
        for(int i=1;i<=n;++i){
            node[i].build(i);
        }
    }
    void input(int k){
        for(int i=0;i<k;++i){
            int a,b;cin>>a>>b;
            node[a].child.push_back(&node[b]);
            node[b].child.push_back(&node[a]);
        }
    }
    void BFS(int s){
        queue<Node> que;
        que.push(node[s]);
        while(!que.empty()){
            Node buf=que.front();que.pop();
            int num=buf.child.size();
            for(int i=0;i<num;++i){
              if(buf.child[i]->no==n){
                buf.child[i]->par_n=true;
              }
                if(buf.child[i]->no!=buf.par){
                    buf.child[i]->par=buf.no;
                    buf.child[i]->dist=buf.dist+1;
                    que.push(*buf.child[i]);
                }
            }
        }
    }
    void DFS(Node& node){
        if(node.child.size()==1&&node.par!=node.no){
            return;
        }
        else{
            int num=node.child.size();
            for(int i=0;i<num;++i){
                if(node.child[i]->no!=node.par){
                    DFS(*node.child[i]);
                    node.sum+=node.child[i]->sum;
                    if(node.child[i]->par_n)node.par_n=true;
                }
            }
        }
    }
};
