    edge[k2].pb(k1);
  }
  REP(i,n+1) d1[i] = INF;
  REP(i,n+1) d2[i] = INF;
  d1[1] = 0;
  d2[n] = 0;
  dfs1(1);
  dfs2(n);
  int ans = 0;
  FOR(i,n){
    if(d1[i] > d2[i])
    ans ++;
  }
  if(n-ans>ans) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;
  return 0;
}

