}

// 最大公約数
ll gcd(ll a,ll b){
   if (a%b == 0) return(b);
   else return(gcd(b, a%b));
}

// 最小公倍数
ll lcm(ll a, ll b){
    return a/gcd(a, b) * b;
}

ll N;
ll len=0;
ll total=0;

vector<ll> dist;  // 各頂点の加算カウント
vector<bool> seen;  // 訪問済みの点

// BFSのための再帰関数
void dfs(const Graph &G, int v, int counter) {
    total++;
    seen[v] = true;
    dist[v] = counter;
    for (auto next_v : G[v]) { 
        if (seen[next_v]) continue;
        if(next_v == N-1){
            len = counter+1;
            continue; // N-1のノードに達したら終了
        }
        dfs(G, next_v, counter+1); // 再帰的に値を追加していく
    }
}

int main()
{
    cout << fixed << setprecision(15);
