    dist.assign(N, 0);

    REP(i, N-1){
        ll a, b;
        cin >> a >> b;
        G[a-1].push_back(b-1);
        G[b-1].push_back(a-1);
    }

    dfs(G, 0, 0);

    // cout << "len:" << len << endl;
    // cout << "total:" << total << endl;

    ll F = total-len+(len/2);
    ll S = N-2-F;

    // cout << "F:" << F << endl;
    // cout << "S:" << S << endl;
    if(F>S){
        cout << "Fennec" << endl;
    }
    else{
        cout << "Snuke" << endl;
    }

    return 0;
}

