void dijkstra(ll x,vector<ll> &d,vector<bool> &vis){
    rep(i,len(d)){
        d[i]=INF;
    }
    priority_queue<P,vector<P>,greater<P>> que;
    d[x]=0;
    que.push(P(0,x));
    while(!que.empty()){
        P p=que.top();
        que.pop();
        ll v=p.second;
        if(d[v]<p.first||vis[v]){
            continue;
        }
        vis[v]=true;
        rep(i,len(g[v])){
            edge e=g[v][i];
            if(d[e.to]>d[v]+e.cost){
                d[e.to]=d[v]+e.cost;
                que.push(P(d[e.to],e.to));
            }
        }
    }
}

