int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int n; cin>>n;
  vector<int> tree[n];
  for (int i = 0; i < n-1; i++) {
    int a,b; cin>>a>>b; a--; b--;
    tree[a].push_back(b);
    tree[b].push_back(a);
  }

  vector<int> dist(n, n);
  queue<int> qs;
  qs.push(n-1);
  dist[n-1] = 0;
  while (not qs.empty()) {
    auto q = qs.front(); qs.pop();
    int d = dist[q];
    for (auto t:tree[q]) {
      if (dist[t] < d)
        continue;
      qs.push(t);
      dist[t] = d+1;
    }
  }
  vector<int> path;
  path.push_back(0);
  int d = dist[0];
  while (d > 0) {
    int nxt;
    for (auto t:tree[path.back()]) {
      if (dist[t] == d-1) {
        nxt = t;
        break;
      }
    }
    path.push_back(nxt);
    d--;
  }
  vector<int> color(n, 0);
  color[0] = 1;
  color[n-1] = 2;
  color[path[(path.size()+1)/2-1]] = 1;
  color[path[(path.size()+1)/2]] = 2;

  qs = {};
  qs.push(0);
  qs.push(n-1);
  while (not qs.empty()) {
    auto q = qs.front(); qs.pop();
    auto c = color[q];
    for (auto t:tree[q]) {
      if (color[t] != 0) continue;
      color[t] = c;
      qs.push(t);
    }
  }

  int bs = 0;
  for (auto c:color)
    if (c == 1)
      bs++;

  if (bs > n-bs) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }

  return 0;
}

