void build(int x)
{
	size[x] = 1;
	for (auto y : v[x])
	{
		if (y == pre[x]) continue;
		pre[y] = x;
		build(y);
		size[x] += size[y];
	}
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i < n; ++ i)
	{
