		v[x].push_back(y);
		v[y].push_back(x);
	}
	build(1);
	vector<int> p;
	for (int i = n; i; i = pre[i])
		p.push_back(i);
	reverse(p.begin(), p.end());
	int x = p[(p.size()+1)/2];
	int b = size[x];
	int a = n-b;
	puts(a > b ? "Fennec" : "Snuke");
	return 0;
}

