	rep(i, n - 1) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	int nl, nr;
	nl = nr = 1;
	vector<bool>splat(n, false);// 色塗り済みかどうかを格納
	splat[0] = splat[n - 1] = true;

	// 点0と点n-1の2点から交互にBFSを進めて、
	// 片方の探索が続けられなくなったら、
	// 塗れる点の数を数えて勝敗を出力する
	queue<int>sl, sr;
