			int l = sl.front();
			sl.pop();
			for (auto v : g[l]) {
				if (splat[v] == false) {
					splat[v] = true;
					sl.push(v);
					nl++;
				}
			}
		}
		if (!sr.empty()) {
			int r = sr.front();
			sr.pop();
			for (auto v : g[r]) {
				if (splat[v] == false) {
					splat[v] = true;
					sr.push(v);
					nr++;
				}
			}
		}
	}


	if (nl > nr) cout << "Fennec" << endl;
	else cout << "Snuke" << endl;


	return 0;
}

