using namespace std;

int count_from_v(const vector<vector<int>> &graph, int v, int except)
{
    int sum = 1;

    const auto &edges = graph[v];

    REP(i, edges.size())
    {
        if( edges[i] == except ) continue;

        sum += count_from_v(graph, edges[i], v);
    }

    return sum;
}

int main() {
    int N;
    cin >> N;

    vector<vector<int>> graph(N);

    REP(i, N - 1) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;

        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    vector<int> distance_from_f(N, -1);

    // vertex, current_cost
    queue<pair<int, int>> next;
    next.push(make_pair(0, 0));

    while(!next.empty())
    {
        auto front = next.front(); next.pop();

        if( distance_from_f[front.first] != -1 ) continue;
        distance_from_f[front.first] = front.second;

        const auto &edges = graph[front.first];

        REP(i, edges.size())
        {
            int next_vertex = edges[i];
            next.push(make_pair(next_vertex, front.second + 1));
        }
    }

    int current = N - 1;
    vector<int> route; route.reserve(N);
    while(true)
    {
        route.push_back(current);

        const auto &edges = graph[current];
        int prev_v = -1;

        REP(i, edges.size())
        {
            if( distance_from_f[edges[i]] + 1 == distance_from_f[current] )
            {
                prev_v = edges[i];
                break;
            }
        }

        if( prev_v == -1 )
        {
            // reached
            break;
        }
        else
        {
            current = prev_v;
        }
    }

    reverse(ALL(route));

    int fennec = 0;
    REP(i, route.size() / 2 + route.size() % 2)
    {
        fennec += count_from_v(graph, route[i], route[i+1]);
    }
    int snuke = N - fennec;

    if( fennec > snuke )
    {
        cout << "Fennec" << endl;
    }
    else
    {
        // equal -> 先攻が塗れなくなるので，後攻が勝つ
        cout << "Snuke" << endl;
    }

    return 0;
}

