#include <bits/stdc++.h>
using namespace std;

int main(){
  int N; cin >> N;
  vector<vector<int>> edge(N,vector<int>());
  for(int i=0; i<N-1; i++){
    int a,b; cin >> a >> b;
    a--; b--;
    edge[a].push_back(b);
    edge[b].push_back(a);
  }

  // 0からN-1の最短を求める
  // 初めに求めたルートで息の根を止めるのが最適
  // その後埋めていき生き残ったほうが勝ち

  vector<int> pre(N,-1);
  queue<int> q;
  q.push(0);
  pre[0]=0;
  while(!q.empty()){
    int a=q.front(); q.pop();
    for(int x:edge[a]){
      if(pre[x]<0){
        q.push(x);
        pre[x]=a;
      }
    }
  }
  vector<int> route={N-1};
  for(int i=0; i<N; i++){
    route.push_back(pre[route[i]]);
    if(pre[route[i]]==0) break;
  }
  reverse(route.begin(),route.end());

  vector<int> color(N,-1);
  // 0 黒 1 白
  queue<int> q0;
  queue<int> q1;
  for(int i=0; i<(int)route.size(); i++){
    if(i%2==0){
      color[route[i/2]]=0;
      q0.push(route[i/2]);
    }else{
      color[route[route.size()-1-i/2]]=1;
      q1.push(route[route.size()-1-i/2]);
    }
  }
  while(!q0.empty()){
    int a=q0.front(); q0.pop();
    for(int x:edge[a]){
      if(color[x]<0){
        color[x]=0;
        q0.push(x);
      }
    }
  }
  while(!q1.empty()){
    int a=q1.front(); q1.pop();
    for(int x:edge[a]){
      if(color[x]<0){
        color[x]=1;
        q1.push(x);
      }
    }
  }
  int c0=0,c1=0;
  for(int i=0; i<N; i++){
    if(color[i]==0) c0++;
    else c1++;
  }
  if(c0>c1) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;
}

