void dfs_b(int now,int pre,int count){
    if(pre==-1)b[now]=count;
    for(auto u:v[now]){
        if(u!=pre){
            b[u]=count+1;
            dfs_b(u,now,count+1);
        }
    }
}
void dfs_w(int now,int pre,int count){
    if(pre==-1)w[now]=count;
    for(auto u:v[now]){
        if(u!=pre){
            w[u]=count+1;
            dfs_w(u,now,count+1);
        }
