//dijkstra
/////////
ll N;
static const ll MAX = 100001;
static const ll INFTY = (ll)1 << 55;
static const int WHITE = 1;
static const int GRAY = 2;
static const int BLACK = 3;
vector<pair<ll, ll>>adj[MAX];
ll d[MAX];
ll pre[MAX];

priority_queue<pair<ll, ll>>PQ;
ll color[MAX];
ll n;
void dijkstra(ll x) {
	repe(i, 1, n) {
		d[i] = INFTY;
		color[i] = WHITE;
		pre[i] = -1;
	}

	d[x] = 0;
	PQ.push(make_pair(x, x));
	color[x] = GRAY;
	while (!PQ.empty()) {
		pair<ll, ll> f = PQ.top(); PQ.pop();
		ll u = f.second;
		color[u] = BLACK;

		if (d[u] < f.first * (-1))continue;

		rep(j, 0, adj[u].size()) {
			ll v = adj[u][j].first;
			if (color[v] == BLACK)continue;
			if (d[v] > d[u] + adj[u][j].second) {
				d[v] = d[u] + adj[u][j].second;
				pre[v] = u;
				PQ.push(make_pair(d[v] * (-1), v));

				color[v] = GRAY;
			}
		}
	}
}
vector<ll> get_path(ll t) {
	vector<ll> path;
	for (; t != -1; t = pre[t])path.push_back(t);
	reverse(path.begin(), path.end());
	return path;
}
ll F_P;
ll S_P;
bool vis[100001] = {};
void dfs(ll k, bool isF) {
	if (isF && (k == n || k == F_P))return;
	if (!isF && (k == 1 || k == S_P))return;
	if (vis[k])return;

	vis[k] = true;

	for (vector<pair<ll, ll>>::iterator it = adj[k].begin(); it != adj[k].end(); it++) {
		dfs(it->first, isF);
	}
}

int main() {
	cin >> n;
	rep(i, 0, n - 1) {
		ll a, b; cin >> a >> b;
		adj[a].push_back(make_pair(b, 1));
		adj[b].push_back(make_pair(a, 1));
	}

	dijkstra(1);
	ll dis = d[n];
	vector<ll> t = get_path(n);
	F_P = t[dis / 2 + 1];
	S_P = t[dis / 2];

	repe(i, 1, n)vis[i] = false;
	dfs(1, true);
	ll fenec = 0;
	repe(i, 1, n) {
		if (vis[i]) fenec++;
	}

	repe(i, 1, n)vis[i] = false;
	dfs(n, false);
	ll sunuke = 0;
	repe(i, 1, n) {
		if (vis[i]) sunuke++;
	}

	cout << ((fenec > sunuke) ? "Fennec" : "Snuke") << endl;;

	return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAX_N = (int)1e5 + 5;

int n;
int a, b;

vector<vector<int>> graph(MAX_N);

int pathF[MAX_N];
int pathS[MAX_N];

int cF;
int cS;

void bfs(int begin, int end, int (&path)[MAX_N]) {
  queue<pair<int, int>> que;
  que.push(make_pair(begin, 0));

  while (!que.empty()) {
    int cvt = que.front().first;
    int ccost = que.front().second;
    que.pop();

    path[cvt] = ccost;

    for (int i = 0; i < graph[cvt].size(); ++i) {
      int nvt = graph[cvt][i];
      if (path[nvt] == -1) {
        que.push(make_pair(nvt, ccost + 1));
      }
    }

  }

  return;
}

int main(void){
  // Here your code !
  scanf("%d", &n);

  for (int i = 0; i < n - 1; ++i) {
    scanf("%d %d", &a, &b);
    graph[a].push_back(b);
    graph[b].push_back(a);
  }

  fill(pathF, pathF + n + 5, -1);
  fill(pathS, pathS + n + 5, -1);

  bfs(1, n, pathF);
  bfs(n, 1, pathS);

  for (int i = 1; i <= n; ++i) {
    if (pathF[i] > pathS[i]) cS += 1;
    else if (pathF[i] < pathS[i]) cF += 1;
  }

  if (cF > cS) printf("Fennec\n");
  else if (cF < cS) printf("Snuke\n");
  else printf("Snuke\n");

  return 0;
}

