void dfs(int i, std::vector<std::vector<int> >& from, std::vector<int>& went, int to, std::vector<int>& parent) {
	went[i] = 1;
	for(int r:from[i]) {
		if(went[r]==0) {
			parent[r]=i;
			dfs(r,from,went,to,parent);
		}
	}
}

signed main() {
	int n;
	std::cin >> n;
	std::vector<std::vector<int> > from(n);
	rep(i,n-1) {
		int a,b;
		std::cin >> a >> b;
		a--;b--;
		from[a].emplace_back(b);
		from[b].emplace_back(a);
	}
	int p1count; // first, start at 0
	int p2count; // second, start at n-1
	std::vector<int> went(n,0);
	std::vector<int> path;
	std::vector<int> parent(n);
	dfs(n-1,from,went,0,parent);
	int inde = 0;
	while(inde!=n-1) {
		path.emplace_back(inde);
		inde = parent[inde];
	}
	path.emplace_back(n-1);

	int cut1,cut2;
	int temp = path.size();
	if(temp&1)temp++;
	cut1 = path[temp/2-1];
	cut2 = path[temp/2];


	p1count = 0;
	p2count = 0;

	std::queue<int> que;
	que.emplace(0);
	std::vector<int> went1(n,0);
	while(!que.empty()) {
		int i = que.front();que.pop();
		went1[i] = 1;
		p1count++;
		for(int j:from[i]) {
			if(went1[j]==0&&j!=cut2)que.emplace(j);
		}
	}
	que.emplace(n-1);
	std::vector<int> went2(n,0);
	while(!que.empty()) {
		int i = que.front();que.pop();
		went2[i] = 1;
		p2count++;
		for(int j:from[i]) {
			if(went2[j]==0&&j!=cut1)que.emplace(j);
		}
	}

	if(p1count>p2count) {
		print("Fennec");
		return 0;
	}
	if(p1count<=p2count) {
		print("Snuke");
		return 0;
	}
	return 0;
}

