		dist1[i]=INF,dist2[i]=INF;
	queue<int> q;
	q.push(0);
	dist1[0]=0;
	while(!q.empty())
	{
		int f=q.front();
		q.pop();
		for(int i=0;i<g[f].size();i++)
		{
			int s=g[f][i];
			if(dist1[s]==INF)
			{
				dist1[s]=dist1[f]+1;
				q.push(s);
			}
		}
	}
	q.push(n-1);
	dist2[n-1]=0;
	while(!q.empty())
	{
