        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    queue<int> q;
    VI parent(n, inf);
    q.push(0);
    parent[0] = -1;
    while(!q.empty()){
        int v = q.front(); q.pop();
        for(int d: g[v]){
            if (parent[d] != inf) continue;
            parent[d] = v;
            q.push(d);
        }
    }

    VI gg;
    int i = n-1;
    while(parent[i] != -1){
        gg.push_back(i);
        i = parent[i];
    }
    gg.push_back(0);
    reverse(all(gg));

    int p1, p2;
    if (sz(gg) % 2 == 1){
        p1 = gg[sz(gg) / 2];
        p2 = gg[sz(gg) / 2 + 1];
    }else{
        p1 = gg[sz(gg) / 2 - 1];
        p2 = gg[sz(gg) / 2];
    }

    g[p1].erase(remove(all(g[p1]), p2), g[p1].end());
    g[p2].erase(remove(all(g[p2]), p1), g[p2].end());

    UnionFind uf(n);
    rep(i,n){
        for(int d: g[i]){
            uf.unite(i, d);
        }
    }

    int cnt1 = uf.size(0);
    int cnt2 = uf.size(n-1);

    if (cnt1 > cnt2) view("Fennec");
    else view("Snuke");

    return 0;
}

