struct tree_distance{
    int n;
    vector<vector<int>> g;
    vector<int> d;
    int s;
    tree_distance(int _n,int _s){
        n = _n;
        g.resize(n);
        d.resize(n);
        for (int i = 0; i < n; ++i)
        {
            d[i] = -1;
        }
        s = _s;
    }
    void add(int a,int b){
        g[a].push_back(b);
    }
    void init(){
        dfs(s,0);
    }
    void dfs(int x,int dis){
        d[x] = dis;
        for(int i : g[x]){
            if(d[i] < 0){
                dfs(i,dis+1);
            }
        }
    }
};

