vector<int> V[110000];

int mycount=0;
int N,a,b;
ll dis[110000];

void dfs(int x){
  mycount++;

  for(int i=0;i<(int)V[x].size();i++){
    int nx=V[x][i];

    if(dis[nx]==-1){
      dis[nx]=dis[x]+1;
      if(nx==N) continue;;
      dfs(nx);
    }
  }
}

int main(){
  cin>>N;
  //cout<<"unko"<<endl;
  for(int i=0;i<N-1;i++){
    cin>>a>>b;
    V[a].push_back(b);
    V[b].push_back(a);
  }

  for(int i=0;i<110000;i++) dis[i]=-1;
  dis[1]=0;
  dfs(1);
  if(N%2==0 && mycount+dis[N]/2==N/2) cout<<"Snuke"<<endl;
  else if(mycount+dis[N]/2>N/2) cout<<"Fennec"<<endl;
  else cout<<"Snuke"<<endl;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100009;

int n, a = 1, b = 1, mark[N]={};
bool pass[N]={};
vector<int> adj[N], S;

bool find_route(int u){
    S.push_back(u);
    pass[u] = true;

    if(u == n) return true;

    bool found = false;
    for(int v : adj[u])
        if(!pass[v]) found = find_route(v);

    if(!found) S.pop_back();
    return found;
}

void dfs(int u, int color){
    mark[u] = color; pass[u] = true;

    for(int v : adj[u])
        if(!pass[v] && (!mark[v] || mark[v] == color)){
            if(color == 1 && !mark[v]) a++;
            if(color == 2 && !mark[v]) b++;
            dfs(v,color);
        }
}

int main(){
    scanf("%d", &n);
    for(int i = 0; i < n-1; i++){
        int x, y; scanf("%d %d", &x, &y);
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    memset(pass, 0, sizeof pass);
    find_route(1);

    if(S.size() % 2 != 0){
        a = S.size() / 2 + 1;
        b = S.size() / 2;
    }else a = b = S.size() / 2;

    for(int i = 0; i < S.size(); i++)
        if(i < a) mark[S[i]] = 1;
        else mark[S[i]] = 2;

    memset(pass, 0, sizeof pass);
    dfs(1,1);
    dfs(n,2);

    fprintf(stderr, "%d %d\n", a, b);
    printf("%s\n", a > b? "Fennec":"Snuke");
    return 0;
}

