template<class T = lint>
struct Edge {
	int to;
	T cost;
	Edge() {}
	Edge(int to, T cost = 1) : to(to), cost(cost) {}
	bool operator>(const Edge &r) const { return this->cost > r.cost; }
};

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;


	int u, v;
	vector<vector<Edge<int>>> edges(N);
	for (int i = 0; i < N - 1; i++) {
		cin >> u >> v;
		u--, v--;
		edges[u].emplace_back(v);
		edges[v].emplace_back(u);
	}


	auto dfs = [&](auto &&f, int now, int par, int ban, vector<int> &visited) -> int {

		visited[now] = 1;
		int res = 1;
		for (const auto &e : edges[now]) {
			if (e.to != par && e.to != ban && !visited[e.to]) {
				res += f(f, e.to, now, ban, visited);
			}
		}

		return res;

	};

	vector<int> vis1(N), vis2(N);
	int Fennec = dfs(dfs, 0, -1, N - 1, vis1);
	int Snuke  = dfs(dfs, N - 1, -1, 0, vis2);

	if (Fennec > Snuke) cout << "Fennec" << "\n";
	else cout << "Snuke" << "\n";

	return 0;
}

//どうしてもフェネちゃん VS きすけくん にしたかった..........

/*  include  */
#include <cstdio>

/*  using namespace  */
using namespace std;

/*  local var  */
vector<int> グラフ[100005];

/*  define  */
#define loop(i,j) for(int i = 0; i < j; i++)

/*  typedef  */
typedef long long ll;

/*  function  */
void dfs(int マス,int 前回いた場所,int 距離差,int 距離配列[])
{
	/*  距離差の設定  */
	距離配列[マス]=距離差;
	loop(i,sizeof(グラフ[マス])){
		/*  前回いた場所でなければ行ってないので行く  */
		if(グラフ[マス][i] != 前回いた場所 ) dfs(グラフ[マス][i],マス,距離差+1,距離配列);
	}
}

/*  main program  */
int main()
{	
	int フェネック[100005];	
	int きすけ[100005];
	int マス数;
	int 連結A,連結B;
	int フェネちゃんが塗れるマス数=0;

	scanf("%d",&マス数);

	loop(i,マス数-1){
		scanf("%d %d",&連結A,&連結B);
		連結A--,連結B--;		 //連結A 連結Bの数を一つ減らし、0からマス数-1の数で表現
		グラフ[連結A].push_back(連結B);	 //グラフに辺を追加する この時点では「有向グラフ(AからBにしか行けない)」
		グラフ[連結B].push_back(連結A);	 //上記同様。「BからAへの辺を追加して無向グラフにする」
	}

	dfs(0,-1,0,フェネック);			 //フェネちゃんはマス0からスタート。スタートなので前回いたところは -1 とする。 距離差はもちろん0
	dfs(マス数-1,-1,0,きすけ);		 //上記同様。ただし きすけくんはマス数-1の数からのスタートなので マス数-1からスタートする。
	loop(i,マス数){
		 //フェネちゃんは先手だから「自分がiマス目に到着する手数が相手の手数"以下"であれば良い。」
		(フェネック[i]<=きすけ[i])?フェネちゃんが塗れるマス数++:フェネちゃんが塗れるマス数--;
	}
	/*後は塗った数が同数であった場合、フェネちゃんが塗れなくなるためきすけくんの勝利とすればよい。*/
	printf("%s\n",(フェネちゃんが塗れるマス数>0)?"Fennec":"Snuke");

}

