void dfs( long curr, long count[2] )
{
    if(vis[curr]) return;
    vis[curr] = 1;

    long i;
    for(i=0; i<(long)x[curr].size(); i++) {
        long count0[2]={0};
        dfs( x[curr][i], count0 );

        count[0] += count0[0];
        count[1] += count0[1];
