void DFS(int V,vector<vector<int> >&GRAPH,vector<int>&dist,int depth)
{
  dist[V] = depth;
  for (int i = 0; i < GRAPH[V].size(); i++)
  {
    if(dist[GRAPH[V][i]] == -1)
    {
      DFS(GRAPH[V][i],GRAPH,dist,depth+1);
    }
  }
  return;
}
void solve(void)
{
  int N;
  cin>>N;
  vector<vector<int> >GRAPH(N);
  for (int i = 0; i < N-1; i++)
  {
    int A,B;
    cin>>A>>B;
    A--;B--;
    GRAPH[A].push_back(B);
    GRAPH[B].push_back(A);
  }
  vector<int> dist0(N,-1);
  vector<int> distN(N,-1);

  DFS(0,GRAPH,dist0,0);
  dist0[0] = 0;
  distN[N-1] = 0;
  DFS(N-1,GRAPH,distN,0);

  int count = 0;
  for (int i = 0; i < N; i++)
  {
    if(dist0[i] < distN[i])
    {
      count++;
    }
  }

  if(count*2 > N)
  {
    cout<<"Fennec"<<endl;
  }
  else
  {
    cout<<"Snuke"<<endl;
  }





  return; 
}


