using namespace std;

vector<int>v[100005];
int parent[100005], child[100005], depth[100005];

int dfs(int a)
{
    child[a] = 1;
    for(int i=0; i<v[a].size(); ++i) {
        if(v[a][i] == parent[a])    continue;

        parent[ v[a][i] ] = a;
        depth[ v[a][i] ] = depth[a] + 1;
        dfs(v[a][i]);
        child[a] += child[ v[a][i] ];
    }

}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int n, a, b;
    cin>>n;
    for(int i=0; i<n-1; ++i){
        cin>>a>>b;
        v[a].push_back(b);
        v[b].push_back(a);
    }

    parent[1] = 1, depth[1] = 1;
    dfs(1);

    int mid = (depth[n]-2) / 2, midpoint = n;
    for(int i=0; i<mid; ++i){
        midpoint = parent[midpoint];
    }
    if(child[midpoint] >= n-child[midpoint])
        cout<<"Snuke\n";
    else
        cout<<"Fennec\n";

    return 0;
}

