vi par;
vvi ch;
int snk = 0;

void rec(int u, vvi &g, vi &dis) {
	for (int v : g[u]) {		
		if (dis[v] != -1) continue;
		ch[u].push_back(v); par[v] = u;
		dis[v] = dis[u] + 1;		
		rec(v, g, dis);
	}
}
void dfs(int s, vvi &g, vi &dis) {
	dis[s] = 0;
	rec(s, g, dis);
}

void efs(int u, vvi &ch, vb &r) { // その頂点を根とする部分木の頂点数を数える
	r[u] = true; snk++;
	for (int v : ch[u]) {
		if (r[v]) continue;
		efs(v, ch, r);
	}	
}

int main() {
	// 0-ind
	int N; cin >> N;
	vvi g(N);
	rep0(N - 1) {
		int a, b; cin >> a >> b; a--; b--;
		g[a].push_back(b); g[b].push_back(a);
	}
	vi dis(N, -1);
	par.assign(N, -1); ch.assign(N, {});
	dfs(0, g, dis);
	// dbvv(g); dbvv(dis); dbl(par); dbvv(ch);
	int org = N - 1;
	rep0((dis[N - 1] - 1) / 2) org = par[org];

	vector<bool> r(N);
	efs(org, ch, r);

	if (snk < N - snk) print("Fennec");
	else print("Snuke");	
}

