using namespace std;

int N;
vector<int> t[100000] = {};
vector<int> route;
bool flg[100000] = {};
bool is_end = false;

void get_route(int b, int n, stack<int>& s)
{
	if (is_end) return;
	flg[n] = true;

	s.push(n);

	if (n == b)
	{
		is_end = true;
		while (s.size() > 0)
		{
			route.push_back(s.top());
			s.pop();
		}
		reverse(route.begin(), route.end());
		return;
	}

	for (int m : t[n])
	{
		if (!flg[m])
		{
			get_route(b, m, s);
			if (is_end) return;
		}
	}

	s.pop();
}

bool map[100000] = {};

int count(queue<int>& q)
{
	int cnt = q.size();

	while (q.size() > 0)
	{
		int qs = q.size();
		for (int i = 0; i < qs; i++)
		{
			int n = q.front();
			q.pop();
			for (int m : t[n])
			{
				if (!map[m])
				{
					map[m] = true;
					cnt++;
					q.push(m);
				}
			}
		}
	}

	return cnt;
}


signed main()
{
	cin >> N;
	REP(i, N - 1)
	{
		int a, b;
		cin >> a >> b;
		t[a - 1].push_back(b - 1);
		t[b - 1].push_back(a - 1);
	}

	stack<int> s;
	get_route(N - 1, 0, s);

	int sunuke_n = route.size() / 2;;
	int fene_n = route.size() - route.size() / 2;

	for (int i = 0; i < route.size(); i++)
	{
		map[route[i]] = true;
	}

	queue<int> q1;
	for (int i = 0; i < fene_n; i++)
	{
		q1.push(route[i]);
	}
	int cnt1 = count(q1);

	queue<int> q2;
	for (int i = fene_n; i < route.size(); i++)
	{
		q2.push(route[i]);
	}
	int cnt2 = count(q2);

	if (cnt1 <= cnt2)
	{
		cout << "Snuke" << endl;
	}
	else
	{
		cout << "Fennec" << endl;
	}
}

