#include<bits/stdc++.h>
using namespace std;

struct Node{
    int num, cost;
};

vector<int> tree[100005];
int d[2][100005];
int n;

void bfs(int p, int s){
    for(int i=1;i<=n;++i)d[p][i] = INT_MAX;
    d[p][s] = 0;
    queue<Node> que;
    que.push((Node){s, 0});
    while(!que.empty()){
        Node curr = que.front(); que.pop();
        for(int next : tree[curr.num]){
            int newcost = curr.cost + 1;
            if(newcost < d[p][next]){
                d[p][next] = newcost;
                que.push((Node){next, newcost});
            }
        }
    }
}

int main(){
    cin >> n;
    for(int i=0;i<n-1;++i){
        int a, b;
        cin >> a >> b;
        tree[a].push_back(b);
        tree[b].push_back(a);
    }
    bfs(0, 1);
    bfs(1, n);
    int fennec = 0, snuke = 0;
    for(int i=1;i<=n;++i){
        if(d[0][i] <= d[1][i])fennec++;
        else snuke++;
    }

    cout << (fennec > snuke ? "Fennec" : "Snuke") << endl;

    return 0;
}

