const int MAX = 1 << 29;
int N;
vector<vector<int>> load(100001);

struct SearchResult {
    int stepsToN;
    int centerCityIdx;
};


SearchResult calcStepsToN(int last, int curr, int steps) {
    if (curr == N) {
        return {steps, 0};
    }
    SearchResult m = {MAX, 0};
    for (int a : load[curr]) {
        if (a == last) continue;
        SearchResult d = calcStepsToN(curr, a, steps + 1);
        if (d.stepsToN < m.stepsToN) {
            m = d;
        }
    }
    if (m.stepsToN == MAX) {
        return m;
    }
    if (m.stepsToN / 2 + 1 == steps) {
        m.centerCityIdx = curr;
    }
    return m;
}
int countCitys(int last, int curr, int centerCity) {
    if (curr == N) {
        return 0;
    }
    if (curr == centerCity) {
        return 0;
    }
    int count = 1;
    for (int a : load[curr]) {
        if (a == last) continue;
        int c = countCitys(curr, a, centerCity);
        count += c;
    }
    return count;
}

int main() {
    cin >> N;
    rep(i, N - 1) {
        int a, b;
        cin >> a >> b;
        load[a].push_back(b);
        load[b].push_back(a);
    }
    SearchResult r = calcStepsToN(-1, 1, 0);
    int count = countCitys(-1, 1, r.centerCityIdx);
    if (count > N / 2) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
    return 0;
}

