struct Maze {
  int id;
  int parent;
  int cost;
};
int N;

vec< vec< int > > g;
vec< int > c;
queue< Maze > q;
vec< int > parent;

int bfs() {
  Maze s = {N - 1, N - 1, 0};
  parent[N - 1] = N - 1;
  q.push(s);
  while (!q.empty()) {
    Maze now = q.front();
    q.pop();
    if (now.id == 0) {

      return now.cost;
    }
    FORA(e, g[now.id]) {
      Maze next = {e, now.id, now.cost + 1};
      if (parent[e] == -1) { //  注意
        parent[e] = now.id;
        q.push(next);
      }
    }
  }
  return -1;
}
void dfs(int id, int color) {
  c[id] = color;
  FORA(e, g[id]) {
    if (c[e] == -1) {
      dfs(e, color);
    }
  }
}
