using namespace std;

int cnt(vector<int> *v,int a,int b, int end)
{
	map<int,int>m;
	queue<int> q;
	q.push(a);
	while(!q.empty())
	{
		int y = q.front();
		q.pop();
		m[y]++;
		for(int i: v[y])
		{
			if(i==b)
				continue;
			else if(m[i]==0)
			{
				m[i]++;
				q.push(i);
			}
		}
	}
	return m.size();
}

void printPath(vector<int> stack, vector<int> *v) 
{ 
	int black=0, white = 0, n = (stack.size()+1)/2;
	black = cnt(v,1,stack[n],stack[n+1]);
	white = stack[stack.size()-1]-black;
	if(black>white)
		cout<<"Fennec"<<endl;
	else
		cout<<"Snuke"<<endl; 
} 

void DFS(vector<int> *v, bool *vis, int x, int y, vector<int> stack) 
{ 
	stack.push_back(x); 
	if (x == y) {
		printPath(stack,v); 
		return;
	} 
	vis[x] = true;
	int flag = 0; 
	if (!v[x].empty()) { 
		for (int j = 0; j < v[x].size(); j++) {
			if (vis[v[x][j]] == false) { 
				DFS(v, vis, v[x][j], y, stack); 
				flag = 1; 
			} 
		} 
	} 
	if (flag == 0) { 
		stack.pop_back(); 
	} 
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	int n;
	cin>>n;
	vector<int> v[n+1], stack;
	for(int i = 0 ,j,k; i<n-1; i++)
	{
		cin>>j>>k;
		v[k].push_back(j);
		v[j].push_back(k);
	}
	bool vis[n+1];
	memset(vis,false,sizeof(vis));
	DFS(v,vis,1,n,stack);
	return 0;
}

