struct TreeNode {
  vector<TreeNode *> children;
  TreeNode *par;
  int val;
  string color;
};

void dfs(TreeNode* prev, TreeNode* now, string color){
  if (!now) return;
  for (auto elem : now->children){
    if (elem == prev || elem->color.size() != 0) continue;
    elem->color = color;
    dfs(now, elem, color);
  }
}

