    --b;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  vector<TreeNode*> nodes;
  REP(i,n){
    TreeNode* tmp = new TreeNode();
    tmp->val = i;
    nodes.push_back(tmp);
  }
  vector<bool> memo(n,false);
  queue<int> que;
  que.push(0);
  memo[0] = true;
  while (que.size()) {
    int now = que.front();que.pop();
    for (int elem : G[now]){
      if (!memo[elem]){
        nodes[now]->children.push_back(nodes[elem]);
        nodes[elem]->par = nodes[now];
        que.push(elem);
        memo[elem] = true;
      }
    }
  }
  int cnt = 0;
  TreeNode* ch = nodes[n-1];
  while (ch->par != nodes[0]){
    ch = ch->par;
