struct node {
  node *parent_;
  int value_;
  int level_;
  int num_nodes_;
  std::vector<node*> children_;

  node(node *parent, int value) : parent_(parent), value_(value), level_(0), num_nodes_(1) {
    level_ = parent ? parent->level_ + 1 : 0;
  }

  node* build_tree_and_search(int search_target,
                              const std::vector<std::list<int>> &edges) {
    node *target_node = nullptr;
    for (auto it = edges[value_].begin(); it != edges[value_].end(); ++it) {
      if (parent_ == nullptr || *it != parent_->value_) {
        auto p = new node(this, *it);
        auto target_in_child = p->build_tree_and_search(search_target, edges);
        if (target_node == nullptr) {
          target_node = (*it == search_target) ? p : target_in_child;
        }
        children_.push_back(p);
        num_nodes_ += p->num_nodes_;
      }
    }

    return target_node;
  }


  ~node() {
    for (auto it : children_) {
      delete it;
    }
  }

  void dump() {
    printf("l:%d n:%d v:%d\n", level_, num_nodes_, value_);
  }
};

int main(int argc, char **argv) {
  int N;
  scanf("%d", &N);

  std::vector<std::list<int>> edges(N + 1, std::list<int>());
  for (int i = 1; i < N; ++i) {
    int a, b;
    scanf("%d %d", &a, &b);
    edges[a].push_back(b);
    edges[b].push_back(a);
  }

  node root(nullptr, 1);
  node *node_N = root.build_tree_and_search(N, edges);
  node *border = node_N;
  while (border->parent_->level_ > node_N->level_ / 2) {
     border = border->parent_;
  }

//  root.dump();
//  node_N->dump();
//  border->dump();

  int pt_f = root.num_nodes_ - border->num_nodes_;
  int pt_s = border->num_nodes_;
  printf("%s\n", pt_f > pt_s ? "Fennec" : "Snuke");

  return 0;
}

