void searchDistance(DWORD start, DWORD *adwField)
{
	queue<DWORD> que;
	BOOL	abIsVisit[N_MAX + 1] = {};

	que.push(start);
	adwField[start] = 0;
	abIsVisit[start] = true;
	while(!que.empty()) {
