int count_node(int player, int parent, int node) {
  int ans = 1;
  iter(it, edge[node]) {
    int to = *it;
    if (to == parent)
      continue;
    if (player != NONE && to == start[1 - player])
      return INF;
    ans += count_node(player, node, to);
  }
  return ans;
}
