    };
    dfs(0, -1);


    vi snuke(n);
    snuke[0] = 1;
    snuke[n-1] = -1;
    int i = 0, j = n-1;
    queue<int> que;
    que.push(0);
    que.push(n-1);
    vector<bool> ch(n);
    ch[0] = true;
    ch[n-1] = true;
    while(true) {

        for(int ne:G[i]) {
            if(ne == j) i = j;
            if(check[ne] and !ch[ne]){
                snuke[ne] = 1;
                ch[i] = true;
                i = ne;
                que.push(i);
                break;
            }
        }
        if(i == j) break;

        for(int ne:G[i]) {
            if(check[ne] and !ch[ne]) {
                snuke[ne] = -1;
                ch[j] = true;
                j = ne;
                que.push(j);
                break;
            }
        }
    }



    int fennec = 0;
    while(!que.empty()) {
        int now = que.front();
        que.pop();

        for(int ne:G[now]) {
            if(!snuke[ne]) {
                snuke[ne] = snuke[now];
                que.push(ne);
            }
        }
        if(snuke[now] == 1) fennec++;
    }


    cout << (fennec > n-fennec ? "Fennec":"Snuke") << endl;
}

