void solve(int N, vi a, vi b) {
  vvi adj(N);
  rep(i, N - 1){
    adj[a[i]].push_back(b[i]);
    adj[b[i]].push_back(a[i]);
  }
  vb c(N);
  c[0] = true;
  c[N - 1] = true;
  vi f_pre = {0}, s_pre = {N - 1};
  int f_sum = 0;
  int s_sum = 0;
  while (!f_pre.empty() && !s_pre.empty()) {
    vi f_tmp;
    each(x, f_pre) {
      each(next, adj[x]) {
        if(!c[next]) {
          c[next] = true;
          f_sum++;
          f_tmp.push_back(next);
        }
      }
    }
    f_pre = f_tmp;
    vi s_tmp;
    each(x, s_pre) {
      each(next, adj[x]) {
        if(!c[next]) {
          c[next] = true;
          s_sum++;
          s_tmp.push_back(next);
        }
      }
    }
    s_pre = s_tmp;
  }
  COUT(f_sum > s_sum ? "Fennec" : "Snuke");
}


