// 距離の計算
void CalcDist(ll c, ll id, ll prev, ll dist) {
    //printf("id: %lld prev: %lld dist: %lld\n", id, prev, dist);
    if(c == Black) { C[id].first = dist; }
    else { C[id].second = dist; }
    for(auto& node : G[id]) {
        if(node == prev) { continue; }
        CalcDist(c, node, id, dist+1);
    }
}

// 色をカウント
void Cnt(ll& fennec, ll& snuke, ll id, ll prev) {
    if(C[id].first > C[id].second) { snuke++; }
    else { fennec++; }
    for(auto& node : G[id]) {
        if(node == prev) { continue; }
        Cnt(fennec, snuke, node, id);
    }
}

