signed main(){
    int START_TIME = clock();
    cin.tie(nullptr);
    ios::sync_with_stdio(false);   //cin cout 高速化
    // cout << fixed << setprecision(15);

    /**
     * 1 ~ n の最短距離をまず陣取りのように埋める。
     * この距離が奇数なら->A、偶数なら->B。
     * 後は他の場所を埋めてく。先に尽きた方が負けなので、それをカウント。
     * A: 先にすぬけからとりはじめる
     * B: 先にフェネックからとり始める
     */

    cin >> n;
    tree.resize(n);
    seen.assign(n, 0);
    dist.assign(n, -1);
    rep(i,n-1) {
        cin >> a >> b;
        --a, --b;
        tree[a].push_back(b);
        tree[b].push_back(a);
    }

    bfs(0);
    int dist_fennec_snuke = dist[n-1]+1;
//    debug(dist_fennec_snuke);
    for(int v = n-1; ; ) {
        seen[v] = 1;
        if(!v) break;
        int u;
        for(int pv : tree[v]) if(dist[pv] + 1 == dist[v]) u = pv;
        v = u;
    }

    int fennec_num = 0;
    dist.assign(n, -1);
    bfs(0);
    rep(i,n) if(!seen[i] && dist[i]!=-1) ++fennec_num;

    int snuke_num = 0;
    dist.assign(n, -1);
    bfs(n-1);
    rep(i,n) if(!seen[i] && dist[i]!=-1) ++snuke_num;

    if(dist_fennec_snuke%2==1) {  // A
        if(snuke_num <= fennec_num) cout << "Fennec" << '\n';
        else cout << "Snuke" << '\n';
    }
    else {  // B
        if(fennec_num <= snuke_num) cout << "Snuke" << '\n';
        else cout << "Fennec" << '\n';
    }

    // printf("ExecutionTime: %d /ms\n",1000*(int)((clock()-START_TIME)/CLOCKS_PER_SEC));
}

