signed main() {
    int N;
    cin >> N;
    vector<vector<int>>ki(N);
    for(int i = 0; i < N-1; i++) {
        int a,b;
        cin >> a >> b;
        a--;b--;
        ki[a].push_back(b);
        ki[b].push_back(a);
    }
    vector<int>cnt(N,INF);
    queue<int>que;
    que.push(0);
    cnt[0] = 0;
    vector<int>road;
    while(!que.empty()) {
        int x = que.front();
        que.pop();
        for(int i = 0; i < ki[x].size(); i++) {
            if(cnt[ki[x][i]] == INF) {
                cnt[ki[x][i]] = cnt[x]+1;
                que.push(ki[x][i]);
            }
        }
    }
    que.push(N-1);
    while(!que.empty()) {
        int x = que.front();
        que.pop();
        for(int i = 0; i < ki[x].size(); i++) {
            if(cnt[ki[x][i]] == cnt[x]-1) {
                road.push_back(ki[x][i]);
                que.push(ki[x][i]);
            }
        }
    }
    int now = 0;
    vector<bool>used(N,false);
    used[0] = true;
    for(int i = 1; i < road.size()+1/2; i++) {
        for(int j = 0; j < (int)ki[now].size(); j++) {
            queue<int>que;
            que.push(ki[now][j]);
            while(!que.empty()) {
                int x = que.front();
                que.pop();
                for(int k = 0; k < ki[x].size(); k++) {
                    if(!used[ki[x][k]]) {
                        used[ki[x][k]] = true;
                        que.push(ki[x][k]);
                    }
                }
            }
        }
        now = road[i];
        used[now] = true;
    }
    int res = 0;
    for(int i = 0; i < N; i++) {
        if(used[i]) {
            res++;
        }
    }
    if(res >= (N+1)/2) {
        cout << "Fennec" << endl;
    }
    else {
        cout << "Snuke" << endl;
    }
}

