vector<int> bfs(int to, vector<int> dist){
  queue<pair<int,int>> que;
  int c = 0;
  que.emplace(to,c);

  while(!que.empty()){
    to = que.front().first;
    c = que.front().second;
    que.pop();
    dist[to] = c;

    for(auto v:g[to]){
      if(dist[v]==-1){
        que.emplace(v,c+1);
      }
    }   
  }
  return dist;
}

