using namespace std;

int main() {
  ints(n);
  VV<int> to(n);
  rep(n - 1) {
    ints(a, b);
    --a, --b;
    to[a].push_back(b);
    to[b].push_back(a);
  }
  int dist = Fix([&](auto dfs, int node, int parent) -> int {
    if (node == n - 1) return 0;
    rep(i, sz(to[node])) {
      int child = to[node][i];
      if (child == parent) continue;
      int d = dfs(child, node);
      if (d >= 0) return d + 1;
    }
    return -1;
  })(0, -1);
  --dist;
  dbg(dist);

  auto dfs = Fix([&](auto dfs, int node, int parent) -> int {
    int ret = 1;
    rep(i, sz(to[node])) {
      int child = to[node][i];
      if (child == parent) continue;
      if (child == 0 || child == n - 1) continue;
      ret += dfs(child, node);
    }
    return ret;
  });

  bool fennec;
  int f = dfs(0, -1), s = dfs(n - 1, -1);
  if (dist % 2 == 0) {
    fennec = f > s;
  } else {
    --f;
    fennec = f >= s;
  }
  wt(fennec ? "Fennec" : "Snuke");
}

