#define lpsbd(i, s, b, d) for(size_t i = (s); i < (b); i+=(d))
#define lpsb(i, s, b) for(size_t i = (s); i < (b); i++)
#define lpn(i, n) for(size_t i = 0; i < (n); i++)
#define fa(i, x) for(auto &i: x)
#define vcd(t, n, d) vector<t>(n, d)
#define vc(t, n) vector<t>(n)
#define all(x) (x).begin(), (x).end()

using namespace std;
using ll = long long;

const ll MOD = 1000000007;

vector<unordered_set<int>> tree;

void dfsp(int v, int p, vector<int> *ans)
{
    fa(i, tree[v])
    {
        if (i == p) continue;
        if (i == 0)
        {
            ans->push_back(0);
            return;
        }
        dfsp(i, v, ans);
        if (!ans->empty())
        {
            ans->push_back(i);
            return;
        }
    }
}

void dfsc(int v, int p, vector<int> *color)
{
    fa(i, tree[v])
    {
        if (i == p || (*color)[i] != -1) continue;
        (*color)[i] = (*color)[v];
        dfsc(i, v, color);
    }
}

int main(void)
{
    int N;
    cin >> N;
    tree.resize(N);
    int a, b;
    lpsb(i, 1, N)
    {
        cin >> a >> b;
        a--;
        b--;
        tree[a].insert(b);
        tree[b].insert(a);
    }
    vector<int> path;
    dfsp(N-1, -1, &path);
    path.push_back(N-1);
    auto color = vcd(int, N, -1);
    auto s = path.size();
    lpn(i, s) color[path[(i % 2) ? s-1 - i/2 : i/2]] = i % 2;
    fa(i, path)
    {
        dfsc(i, -1, &color);
    }
    int count = 0;
    fa(i, color) if (i) count++;
    cout << (count * 2 >= N ? "Snuke" : "Fennec") << endl;
    return 0;
}

