int n, d1[max_n], d2[max_n], d3[max_n], path[max_n], mx1[max_n], mx2[max_n], d11[max_n], d22[max_n], d33[max_n];
vector<int> v[max_n], g;

struct tree {
    int t[max_n * 4];
    void build(int v, int a[], int b[], int tl, int tr) {
        if (tl == tr) {
            t[v] = a[tl] + b[tl];
            return;
        }
        int mid = (tl + tr) / 2;
        build(v * 2, a, b, tl, mid);
        build(v * 2 + 1, a, b, mid + 1, tr);
        t[v] = max(t[v * 2], t[v * 2 + 1]);
    }
    int get(int v, int tl, int tr, int l, int r) {
        if (tl == l && tr == r) {
            return t[v];
        }
        int mid = (tl + tr) / 2;
        if (mid >= r) {
            return get(v * 2, tl, mid, l, r);
        }
        if (mid < l) {
            return get(v * 2 + 1, mid + 1, tr, l, r);
        }
        return max(get(v * 2, tl, mid, l, mid),
                get(v * 2 + 1, mid + 1, tr, mid + 1, r));
    }
};

tree t1, t2;

int dfs(int x, int p) {
    if (x == n - 1) {
        path[x] = 1;
        d2[x] = 0;
        for (int i = 0; i < v[x].size(); ++i) {
            if (v[x][i] == p) continue;
            d3[x] = max(d3[x], dfs(v[x][i], x));
        }
        g.push_back(x);
        return 0;
    }
    for (int i = 0; i < v[x].size(); ++i) {
        if (v[x][i] == p) {
            continue;
        }
        d1[v[x][i]] = d1[x] + 1;
        int k = dfs(v[x][i], x);
        if (path[v[x][i]]) {
            path[x] = 1;
            d2[x] = d2[v[x][i]] + 1;
            g.push_back(x);
        } else {
            d3[x] = max(d3[x], k);
        }
    }
    return d3[x] + 1;
}

