void bfs() {
    queue<int> S;
    queue<int> F;
    F.push(0);
    S.push(N - 1);
    v[0] = 1;
    v[N - 1] = 2;
    bool check = true;
    while (check) {
        check = false;
        queue<int> S_next;
        queue<int> F_next;
        while (!F.empty()) {
            int k = F.front();
            F.pop();
            for (int i = 0; i < G[k].size(); i++) {
                if (v[G[k][i]] == 0) {
                    v[G[k][i]] = 1;
                    F_next.push(G[k][i]);
                    check = true;
                }
            }
        }
        F = F_next;
        while (!S.empty()) {
            int k = S.front();
            S.pop();
            for (int i = 0; i < G[k].size(); i++) {
                if (v[G[k][i]] == 0) {
                    v[G[k][i]] = 2;
                    S_next.push(G[k][i]);
                    check = true;
                }
            }
        }
        S = S_next;
    }
}

