std::vector<int> calcDistance(int nodeNum, std::vector<std::pair<int, int>> edge, int startIndex){
    std::vector<int> ret;
    ret.resize(nodeNum, -1);
    ret[startIndex] = 0;

    std::queue<int> queue;
    queue.push(startIndex);

    while(!queue.empty()){
        int node = queue.front();
        queue.pop();
        for(auto iter:edge){
            if(iter.first == node && ret[iter.second] == -1 && iter.second != startIndex){
                ret[iter.second] = ret[iter.first] + 1;
                queue.push(iter.second);
            }
            if(iter.second == node && ret[iter.first] == -1 && iter.first != startIndex){
                ret[iter.first] = ret[iter.second] + 1;
                queue.push(iter.first);
            }
        }
    }

    return ret;
}

