void dijkstra(int start, vector<int>&arr){
    priority_queue<P,vector<P>,greater<P>> Q;
    arr[start]=0;
    Q.push(make_pair(0,start));
    while(!Q.empty()){
        P p=Q.top();
        Q.pop();
        int v=p.second;
        if(arr[v]<p.first)continue;
        REPA(i,G[v]){
            int e=G[v][i];
            if(arr[e]>arr[v]+1){
                arr[e]=arr[v]+1;
                Q.push(make_pair(arr[e],e));
            }
        }
    }
}
