#define loop(i,j) for(int i = 0; i < j; i++)

/*  typedef  */
typedef long long ll;

/*  function  */
void dfs(int マス,int 前回いた場所,int 距離差,int f)
{
	/*  距離差の設定  */
	if(f)フェネック[マス]=距離差;
	else きすけ[マス]=距離差;
	loop(i,グラフ[マス].size()){
		/*  前回いた場所でなければ行ってないので行く  */
		if(グラフ[マス][i] != 前回いた場所 ) dfs(グラフ[マス][i],マス,距離差+1,f);
	}
}

/*  main program  */
int main()
{	
	int マス数;
	int 連結A,連結B;
	int フェネちゃんが塗れるマス数=0;

	scanf("%d",&マス数);

	loop(i,マス数-1){
		scanf("%d %d",&連結A,&連結B);
		連結A--,連結B--;		 //連結A 連結Bの数を一つ減らし、0からマス数-1の数で表現
		グラフ[連結A].push_back(連結B);	 //グラフに辺を追加する この時点では「有向グラフ(AからBにしか行けない)」
		グラフ[連結B].push_back(連結A);	 //上記同様。「BからAへの辺を追加して無向グラフにする」
	}

	dfs(0,-1,0,1);			 //フェネちゃんはマス0からスタート。スタートなので前回いたところは -1 とする。 距離差はもちろん0
	dfs(マス数-1,-1,0,0);		 //上記同様。ただし きすけくんはマス数-1の数からのスタートなので マス数-1からスタートする。
	loop(i,マス数){
		 //フェネちゃんは先手だから「自分がiマス目に到着する手数が相手の手数"以下"であれば良い。」
		(フェネック[i]<=きすけ[i])?フェネちゃんが塗れるマス数++:フェネちゃんが塗れるマス数--;
	}
	/*後は塗った数が同数であった場合、フェネちゃんが塗れなくなるためきすけくんの勝利とすればよい。*/
	printf("%s\n",(フェネちゃんが塗れるマス数>0)?"Fennec":"Snuke");

}

