#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MAX_N = 1e5+10;
int N, a[MAX_N], b[MAX_N];
vector<int> G[MAX_N];
bool vis[MAX_N];
int prevv[MAX_N];
int col[MAX_N];

void add_edge(int from, int to)
{
	G[from].push_back(to);
	G[to].push_back(from);
}

void dfs(int x)
{
	vis[x] = true;
	for(int i=0;i<G[x].size();++i){
		int y = G[x][i];
		if(!vis[y]){
			prevv[y]=x;
			dfs(y);
		}
	}
}

int dfs2(int x, int c)
{
	int res = 1;
	vis[x] = true;
	col[x] = c;
	for(int i=0;i<G[x].size();++i){
		int y = G[x][i];
		if(!vis[y] && (col[y] == -1 || col[y] == c)) res += dfs2(y, c);
	}
	return res;
}

void solve()
{
	memset(prevv, -1, sizeof(prevv));
	dfs(1);
	int t=N;
	int len=0;
	while(t!=-1){
		len++;
		t=prevv[t];
	}
	memset(col, -1, sizeof(col));
	t = N;
	int cnt = len/2;
	while(cnt--){
		col[t] = 0;
		t=prevv[t];
	}
	while(t!=-1){
		col[t]=1;
		t=prevv[t];
	}
	memset(vis,false,sizeof(vis));
	int bc = dfs2(1, 1);
	memset(vis,false,sizeof(vis));
	int wc = dfs2(N, 0);
	if(bc > wc) cout << "Fennec\n";
	else cout << "Snuke\n";
}

int main()
{
	cin >> N;
	for(int i=0;i<N-1;++i){
		cin >> a[i] >> b[i];
		add_edge(a[i], b[i]);
	}
	solve();
	return 0;
}

