	vis[now] = true;

	for( int i:vec[now] ){
		if( !vis[i] ){
			size += DFS(i);
		}
	}
	return sz[now] = size+1;
}

int count(int fix)
{
	int now = N;
	for(int i=step[N];i>fix;i--){
		for(int next:vec[now]){
			if( step[next] == i-1 ){
				now = next;
				break;
			}
		}
	}
	return sz[now];
}

