int tbfs(int s){
    queue<int> que;
    que.push(s);
    int cnt = 0;
    while(!que.empty()){
        auto v = que.front(); que.pop();
        for(auto e: G[v]) if(!visited[e]) {
            visited[e] = true;
            que.push(e);
            cnt++;
        }
    }
    return cnt;
}

