vector<int> bfs(int n, int s){
    vector<int> mini(n + 1, INF);
    mini[s] = 0;
    queue<pair<int,int>> que;
    que.push(make_pair(s, 0));

    while(!que.empty()){
        pair<int, int> curr = que.front(); que.pop();
        for(auto to : graph[curr.first]){
            if(mini[to] < curr.second + 1)continue;
            mini[to] = curr.second + 1;
            que.push(make_pair(to, curr.second + 1));
        }
    }

    return mini;
