vector<int> v;
set<int> pathv;

bool dfs(int from, int parent) {
    for (int to : graph[from]) {
        if (to == n) {
            if (from != 1) {
                v.push_back(from);
                pathv.insert(from);
            }
            return true;
        } else if (to != parent) {
            if (dfs(to, from)) {
                if (from != 1) {
                    v.push_back(from);
                    pathv.insert(from);
                }
                return true;
            }
        }
    }
    return false;
}

int count(int from, int parent) {
    int cnt = 1;
    for (int to : graph[from]) {
        if (pathv.count(to) || to == parent)
            continue;
        cnt += count(to, from);
    }
    return cnt;
}

