        --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    dfs(0, -1);
    pathv.insert(0);
    pathv.insert(n - 1);
    int score = count(0, -1);
    for (int i = 1; i <= (v.size() + 1) / 2; ++i) {
        score += count(v[n - i], -1);
    }
    if (score * 2 > n) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
    return 0;
}

