const double pi = 3.14159265358979323846264;
vector<vector<ll>> g(100010, vector<ll>());
vector<bool> seen(100010, false);
vector<ll> color(100010, 0);
ll n;
ll cnt = 0;
void dfs(ll v, vector<ll> path)
{
    seen[v] = true;
    path.push_back(v);
    if (v == n - 1)
    {
        for (ll i = 0; i < path.size() / 2; i++)
        {
            color[path[i]] = 1;
        }
        for (ll i = path.size() / 2; i < path.size(); i++)
        {
            color[path[i]] = 2;
        }
        return;
    }
    for (auto f : g[v])
    {
        if (seen[f])
        {
            continue;
        }
        dfs(f, path);
    }
}
void dfs2(ll v)
{
    color[v] = 1;
    cnt++;
    for (auto f : g[v])
    {
        if (color[f] != 0)
        {
            continue;
        }
        dfs2(f);
    }
}
