		a--; b--;
		edge e1, e2;
		e1.to = b;
		e1.cost = 1;
		G[a].push_back(e1);
		e2.to = a;
		e2.cost = 1;
		G[b].push_back(e2);
	}

	dijkstra(0);
	ll tmp[V];
	rep(i, 0, V) tmp[i] = d[i];
	dijkstra(V - 1);
	ll res = 0;
	rep(i, 0, V) {
		if(tmp[i] > d[i]) res--;
		else if(tmp[i] < d[i]) res++;
	}

	if(res >= 0) cout << "Fennec" << endl;
	else cout << "Snuke" << endl; 

}

