void bfs(){
    queue <pii> qb,qw;
    qb.push(mp(1,0));
    qw.push(mp(n,0));

    bool moving = true;
    while(moving){
        moving = false;

        int cur = qb.front().se;
        while(!qb.empty()){
            moving = true;
            int node = qb.front().fi;
            int steps = qb.front().se;

            //cout<<"BLAC "<<node<<" "<<steps<<newl;
            if(steps>cur)break;
            else{
                qb.pop();

                visb[node]=true;
                for(int i=0;i<adj[node].size();i++){
                    int nex = adj[node][i];
                    //cout<<"blacknex : "<<node<<" "<<nex<<newl;
                    if(!visb[nex] && !visw[nex] && nex != n){
                        //cout<<"OK\n";
                        visb[nex]=true;
                        qb.push(mp(nex,steps+1));
                    }
                }
            }
        }

        cur = qw.front().se;
        while(!qw.empty()){
            moving = true;
            int node = qw.front().fi;
            int steps = qw.front().se;

            //cout<<"WHIT "<<node<<" "<<steps<<newl;
            if(steps>cur)break;
            else{
                qw.pop();

                visw[node]=true;
                for(int i=0;i<adj[node].size();i++){
                    int nex = adj[node][i];
                    if(!visb[nex] && !visw[nex] && nex != 1){
                        qw.push(mp(nex,steps+1));
                        visw[nex]=true;
                    }
                }

            }
        }
    }
}

