		lld to=gr[s][i];
		if(used[to]==0){
			ans+=(dfs(to));
		}
	}	
	return ans;
}

lld find_path(lld s,lld par,lld dest,vector<lld > &path){
	if(s==dest){
		path.push_back(s);
		return 1;
	}
	path.push_back(s);
	for(lld i=0;i<gr[s].size();i++){
		lld to=gr[s][i];
		if(to!=par){
			if(find_path(to,s,dest,path)==1){
				return 1;
			}
		}
	}
	path.pop_back();	
	return 0;
}

