    vector<int> d(n, 1e9);
    color[0] = 1;
    color[n-1] = -1;
    REP(i, 0, n-1){
        int a, b; cin >> a >> b;
        a--; b--;
        tree[a].pb(b);
        tree[b].pb(a);
    }
