    while(!q.empty()){
        int now = q.front();
        q.pop();
        REP(i, 0, tree[now].size()){
            int next = tree[now][i];
            if(d[next] != 1e9){continue;}
            d[next] = d[now] + 1;
            q.push(next);
        }
