        s1.push(now);
        REP(i, 0, tree[now].size()){
            int next = tree[now][i];
            if(color[next] == -2){
                ss1.push(now);
            }
        }
    }
    ss2.push(n-1);
    count /= 2;
    REP(i, 0, 1+count){
        int now = ss2.top();
        ss2.pop();
        sc++;
        color[now] = -1;
        s2.push(now);
        REP(i, 0, tree[now].size()){
            int next = tree[now][i];
