	int E=V-1;//辺の数
	for (int i = 0; i < E; ++i) {
		int a, b, c=1;
		cin >> a >> b ;
		a--; b--;
		//the route a to b costs c
		edge e = { b, c };
		G[a].push_back(e);
        edge e2={a,c};
        G[b].push_back(e2);
		//有効グラフの場合であり、無向グラフなら e{a,c}も必要
	}
	dijkstra(0);
    vector<int>d1(V-1),d2(V-1);
	//dijkstra(int s); nからの最短距離を計算
	//d[i]はsからiまでの最短距離が保存される the path from s to i costs d[i]
    rep(i,V-1){
        d1[i]=d[i];
    }
    dijkstra(V-1);
    rep(i,V-1){
        d2[i]=d[i];
    }
    vector<bool>iswhite(V-1,true);
    rep(i,V-1){
        if(d1[i]<=d2[i]){
