void build(int x, int y)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
}
void get_path(int x)
{
	path[++tot] = x;
	if(x == 1) return;
	int ed = last[x], dr;
	while(ed != -1) {
		dr = other[ed];
		if(deep[dr] < deep[x]){
			get_path(dr);
		}
		ed = pre[ed];
	}
}
void get_deep(int x, int fa)
{
	deep[x] = deep[fa] + 1;
	int ed = last[x], dr;
	while(ed != -1) {
		dr = other[ed];
		if(dr != fa)
			get_deep(dr, x);
		ed = pre[ed];
	}
}
void dfs(int x, int fa)
{
	int ed = last[x], dr;
	vis[x] = 1;
	while(ed != -1) {
		dr = other[ed];
		if(dr != fa) 
			dfs(dr, x);
		ed = pre[ed];
	}
}
