vector<vector<int>> G;
vector<bool> used;
int dfs(auto cur) {
  auto sum = 1;
  used[cur] = true;
  if(cur==G.size()-1) return 0;
  for(auto nex: G[cur]) if(!used[nex]) sum += dfs(nex);
  return sum;
}

int main() {
  int N;
  cin >> N;

  G.resize(N);
  for(auto i=1; i<N; ++i) {
    int a, b;
    cin >> a >> b;
    --a; --b;
    G[a].emplace_back(b);
    G[b].emplace_back(a);
  }

  auto Fennec = 0;
  auto Snuke = 0;
  auto share = 0;
  used.assign(N, false);

  used[0] = true;
  for(auto v: G[0]) {
    auto dup = used[N-1];
    auto sum = dfs(v);
    if(dup!=used[N-1]) share += sum;
    else               Fennec += sum;
  }
  for(auto v: G[N-1]) if(!used[v]) Snuke += dfs(v);

  if(Fennec+(share&1)>Snuke) cout << "Fennec" << endl;
  else                        cout << "Snuke" << endl;
}

