ll modc(ll a, char op, ll b, ll _mod=mod)
{
        a %= _mod; b %= _mod; ll res = 1;
        switch (op) {
        case '+': res = (a + b) % _mod; break;
        case '-': res = (a - b) % _mod; break;
        case '*': res = a * b % _mod; break;
        case '/': res = modc(a, '*', modc(b, '^', _mod-2, _mod), _mod); break;
        case '^': res = intpow(a, b, _mod); break;
        case 'P': rep(i, a-b+1, a+1) res = modc(res, '*', i, _mod); break;
        case 'C': res = modc(modc(a, 'P', b, _mod), '/', modc(b, 'P', b, _mod)); break;
        } 
        if (res < 0) { res += _mod; } return res;
}

const ll MAX = 100010;        // Set
using Vertex = pair<ll, ll>;  // (dist, id)
class Edge
{
public:
    ll to;
    ll cost;
    Edge() : to{0}, cost{0} {}
    Edge(ll a, ll b) : to{a}, cost{b} {}
};

vector<vector<Edge> > Graph(MAX, vector<Edge>(0));
vll dist(MAX, inf);

void dijkstra(ll s)
{
    fill(dist.begin(), dist.end(), inf);
    dist[s] = 0;
    priority_queue<Vertex, vector<Vertex>, greater<Vertex> > pq;    

    pq.push(Vertex(0, s));
    while(! pq.empty()) {
        // Enqueue first node
        Vertex now = pq.top(); pq.pop();
        ll vertex = now.second;
        if (dist[vertex] < now.first) continue;
        // Check for each adjacent node
        for (Edge edge : Graph[now.second]) {
            if (dist[edge.to] > dist[now.second] + edge.cost) {
                dist[edge.to] = dist[now.second] + edge.cost;
                pq.push(Vertex(dist[edge.to], edge.to));
            }
        }
    }
}

int main()
{
        ll N;
        cin >> N;      
        rep(i, 0, N-1) {
                ll a, b;
                cin >> a >> b;
                Graph[a].push_back(Edge{b, 1});
                Graph[b].push_back(Edge{a, 1});
        }  

        dijkstra(1);

        ll nodes = dist[N] - 1;
        ll others = N - nodes;
        ll total = nodes + others;
        if (odd(total)) {
                cout << "Fennec" << endl;
        } else {
                cout << "Snuke" << endl;
        }
}

