int get_nodes(int cur)
{
	visited[cur] = true;
	int ret = 1;

	for (int i = 0; i < adj[cur].size(); i++)
	{
		auto next = adj[cur][i];
		if (visited[next]) continue;
		ret += get_nodes(next);
	}
	return ret;
}

bool traversal(int cur, int target, int len)
{
	visited[cur] = true;
	if (cur == target)
	{
		length = len;  return true;
	}

	for (int i = 0; i < adj[cur].size(); i++)
	{
		auto next = adj[cur][i];
		if (visited[next]) continue;
		if (traversal(next, target, len + 1))
			return true;
	}
	visited[cur] = false;
	return false;
}


