inline void solve(){
	queue<int> que;
	int depth=0,f_num=1,flag=1,d[100001];
	que.push(1);
	fill(d,d+n+2,INF);
	d[1]=-1;
	while(!que.empty()){
		int v=que.front();
		que.pop();
		rep(i,edg[v].size()){
			d[edg[v][i]]=min(d[edg[v][i]],d[v]+1);
