				used[edg[v][i]]=1;
				que.push(edg[v][i]);
				++f_num;
			}
		}
	}
	int fe=f_num-d[n]/2;
	int su=n-fe;
	if(fe>su) cout<<"Fennec";
	else cout<<"Snuke";
	return;
}

