template< typename T >
void dijkstra(WeightedGraph< T > &g, vector< T > &dist, vector< T > &prev, vector< T > &num, int s) {
	T N = g.size();
	dist.resize(N, INF);
	prev.resize(N, -1); // 初期化
	num.resize(N, 0);
	using Pi = pair< T, int >;
	priority_queue< Pi, vector< Pi >, greater< Pi > > que;
	dist[s] = 0;
	que.emplace(dist[s], s);
	while(!que.empty()) {
	T cost;
	int idx;
	tie(cost, idx) = que.top();
	que.pop();
	if(dist[idx] < cost) continue;
	for(auto &e : g[idx]) {
		auto next_cost = cost + e.cost;
		if(dist[e.to] < next_cost) continue;
		if (dist[e.to] == next_cost) {
			num[e.to] += num[idx];
			num[e.to] %= MOD;
			continue;
		}
		dist[e.to] = next_cost;
		prev[e.to] = idx; // 頂点 v を通って e.to にたどり着いた
		num[e.to] = num[idx];
		que.emplace(dist[e.to], e.to);
	}
	}
	return;
}

/* get_path(prev, t)
	入力：dijkstra で得た prev, ゴール t
	出力： t への最短路のパス
*/
template< typename T >
vector<T> get_path(const vector<T> &prev, T t) {
	vector<T> path;
	for (T cur = t; cur != -1; cur = prev[cur]) {
		path.push_back(cur);
	}
	reverse(path.begin(), path.end()); // 逆順なのでひっくり返す
	return path;
}


int main()
{
  ll N;
	cin >> N;
	WeightedGraph<ll> G(N);
	REP(i, N-1) {
		ll a, b;
		cin >> a >> b;
		a--; b--;
		G[a].emplace_back(b,1);
		G[b].emplace_back(a,1);
	}
	vector<ll> dist, prev, num;
	dijkstra(G, dist, prev, num, 0);
	vector<ll> path = get_path(prev, N-1);
	vector<bool> vi(N);
	vector<bool> color(N);
	REP(i, path.size()) {
		if (i % 2 == 0) {
			vi[path[i/2]] = true;
			color[path[i/2]] = true;
		} else {
			vi[path[path.size()-1 - i/2]] = true;
		}
	}

	vector<bool> visited = vi;
	REP(i, N) {
		if (visited[i]) {
			stack<ll> sta;
			sta.push(i);
			while(!sta.empty()) {
				ll t = sta.top();
				sta.pop();
				REP(j, G[t].size()) {
					if (!vi[G[t][j]]) {
						sta.push(G[t][j]);
						vi[G[t][j]] = true;
						color[G[t][j]] = color[i];
					}
				}
			}
		}
	}
	ll cnt = 0;
	REP(i, N) {
		cnt += color[i];
	}
	if (cnt > N-cnt) PRINT("Fennec");
	else PRINT("Snuke");
	return 0;
}

