void _BG(const char * s) {
}

template<typename T, typename ... TT>
void _BG(const char * s, T a, TT...b) {
    for (int c = 0; *s && (c || *s != ','); ++s) {
        cerr << *s;
        switch (*s) {
            case '(':
            case '[':
            case '{':
                ++c;
                break;
            case ')':
            case ']':
            case '}':
                --c;
                break;
        }
    }
    cerr << " = " << a;
    if (*s) {
        cerr << ", ";
        _BG(++s, b...);
    } else
        cerr << endl;
}
#define BG(...) do { \
        cerr << __PRETTY_FUNCTION__ << ':' << __LINE__ << ": "; \
        _BG(#__VA_ARGS__,__VA_ARGS__); \
} while(0)

