ll gcd(ll a, ll b) {
    while (b > 0) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long int nCm(long long int n, long long int m) {
    if (m == 1) {
        return n;
    } else {
        return n * nCm(n - 1, m - 1) / m;
    }
}

long long int npm(long long int n, long long int m) {
    if (m == 1) {
        return n;
    } else
        if (m == 0) {
        return 1;
    } else {
        return n * npm(n, m - 1);
    }
}

