template<class Int, Int mod>
class ModInt {
public:
    Int x;

    ModInt() : x(0) {
    }

    ModInt(int a, bool m = 1) {
        if (m) {
            x = a % mod;
            if (x < 0)x += mod;
        } else x = a;
    }

    ModInt(LL a, bool m = 1) {
        if (m) {
            x = a % mod;
            if (x < 0)x += mod;
        } else x = a;
    }

    inline ModInt &operator+=(ModInt that) {
        if ((x += that.x) >= mod) x -= mod;
        return *this;
    }

    inline ModInt &operator-=(ModInt that) {
        if ((x += mod - that.x) >= mod) x -= mod;
        return *this;
    }

    inline ModInt &operator*=(ModInt that) {
        x = LL(x) * that.x % mod;
        return *this;
    }

    inline ModInt &operator/=(ModInt that) {
        return *this *= that.inverse();
    }

    inline ModInt operator-() const {
        return ModInt(-this->x);
    }

    ModInt inverse() const {
        LL a = x, b = mod, u = 1, v = 0;
        while (b) {
            LL t = a / b;
            a -= t*b;
            u -= t*v;
            swap(a, b);
            swap(u, v);
        }
        return ModInt(u);
    }

    inline friend ostream& operator<<(ostream &out, ModInt m) {
        return out << m.x;
    }

#define op(o1,o2) ModInt operator o1(ModInt that) const { return ModInt(*this) o2 that; }
    op(+, +=) op(-, -=) op(*, *=) op( /, /=)
#undef op
#define op(o) bool operator o(ModInt that) const { return x o that.x; }
    op( ==) op( !=) op(<) op( <=) op(>) op( >=)
#undef op
};

