#include "cpp-pyprint/pyprint.h"

#endif

struct edge {
    int from, to;
    ll cost;
};

class Dijkstra {
    int V;
    vector<vector<edge>> edges;
    vector<ll> dist;
    vector<ll> prev;
    vector<ll> route_count;

public:
    Dijkstra(int v) : V(v) {
        edges.resize(V);
        dist.resize(V, INF);
        prev.resize(V, INF);
        route_count.resize(V, 0);
    }

    void add_edge(int from, int to, ll cost) {
        edges[from].push_back({from, to, cost});
    }

    /**
     * @param goal 0-indexed
     * @return return cost to reach the goal. return INF if the goal is unreachable.
     */
    ll get_cost(int goal) {
        return dist[goal];
    }

    /**
     * @param goal 0-indexed
     * @return return total route count to reach the goal ( result value % MOD )
     */
    ll get_route_count(int goal) {
        return route_count[goal];
    }

    /**
     * @param goal 0-indexed
     * @return return route from start to goal
     */
    vector<ll> get_route(int goal) {
        vector<ll> res;
        res.push_back(goal);
        ll dest = goal;
        while (prev[dest] != INF) {
            res.push_back(prev[dest]);
            dest = prev[dest];
        }
        reverse(res.begin(), res.end());
        return res;
    }

    void exec(int start) {
        dist[start] = 0;
        route_count[start] = 1;
        priority_queue<P, vector<P>, greater<>> queue;
        queue.push({dist[start], start});
        while (!queue.empty()) {
            P p = queue.top();
            queue.pop();
            ll prev_cost = p.first;
            ll src = p.second;
            if (dist[src] < prev_cost) continue;

            for (edge &e : edges[src]) {
                ll to = e.to;
                ll cost = e.cost;
                if (cost != INF && dist[to] > dist[src] + cost) {
                    dist[to] = dist[src] + cost;
                    queue.push({dist[to], to});
                    prev[to] = src;
                    route_count[to] = route_count[src];
                } else if (dist[to] == dist[src] + cost) {
                    route_count[to] += route_count[src];
                    route_count[to] %= MOD;
                }
            }
        }
    }
};

void Main() {
    int N;
    cin >> N;
    Graph graph(N);
    Dijkstra dijkstra(N);
    rep(i, N - 1) {
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        graph[a].push_back(b);
        graph[b].push_back(a);
        dijkstra.add_edge(a, b, 1);
        dijkstra.add_edge(b, a, 1);
    }

    dijkstra.exec(0);
    vector<ll> route = dijkstra.get_route(N - 1);
    queue<ll> f;
    queue<ll> s;
    rep(i, route.size()) {
        if (i <= (route.size() - 1) / 2) {
            f.push(route[i]);
        } else {
            s.push(route[i]);
        }
    }
    set<ll> F;
    set<ll> S;
    vector<bool> visited(N, false);
    ll bound = f.back();
    while (!f.empty()) {
        ll p = f.front();
        f.pop();
        F.insert(p);
        for (ll v : graph[p]) {
            if (!visited[v] && v != s.front()) {
                f.push(v);
                visited[v] = true;
            }
        }
    }
    while (!s.empty()) {
        ll p = s.front();
        s.pop();
        S.insert(p);
        for (ll v : graph[p]) {
            if (!visited[v] && v != bound) {
                s.push(v);
                visited[v] = true;
            }
        }
    }
    if (F.size() > S.size()) {
        cout << "Fennec" << '\n';
    } else {
        cout << "Snuke" << '\n';
    }
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    Main();
    return 0;
}

