void dfs(int v, int e, int p = -1) {
	++depth;
	visited[v] = true;
	for (int u : path[v]) {
		if (u == p)continue;
		if (visited[u])continue;
		if (u == e) {
			endepth = depth-1;
			continue;
		}
		dfs(u, e, v);
		--depth;
	}
}
