void execute()
{
	int N;
	cin >> N;
	vector<vector<int>> root(N);
	vector<int> depth(N, -1);
	int current;
	queue<int> next;

	for (int i = 0; i < N - 1; i++)
	{
		int from, to;
		cin >> from >> to;
		root[from - 1].push_back(to - 1);
		root[to - 1].push_back(from - 1);
	}

	depth[N - 1] = 0;
	next.push(N - 1);
	for (; !next.empty();)
	{
		current = next.front();
		next.pop();

		for (auto to : root[current])
		{
			if (depth[to] == -1)
			{
				depth[to] = depth[current] + 1;
				next.push(to);
			}
		}
	}
	vector<int> shortest_root;
	shortest_root.push_back(0);

	current = 0;

	for (; current != N - 1;)
	{
		for (auto to : root[current])
		{
			if (depth[to] == depth[current] - 1)
			{
				shortest_root.push_back(to);
				current = to;
				break;
			}
		}
	}

	depth.assign(N, -1);
	reverse(all(shortest_root));

	for (int i = 0; i < shortest_root.size() / 2; i++)
	{
		depth[shortest_root[i]] = -2;
	}

	depth[0] = 0;
	next.push(0);
	int count = 1;
	for (; !next.empty();)
	{
		current = next.front();
		next.pop();

		for (auto to : root[current])
		{
			if (depth[to] == -1)
			{
				count++;
				depth[to] = depth[current] + 1;
				next.push(to);
			}
		}
	}

	if (N - count < count)
	{
		cout << "Fennec" << endl;
	}
	else
	{
		cout << "Snuke" << endl;
	}

	return;
}

