        g[a].push_back({b, 1});
        g[b].push_back({a, 1});
    }
    auto dist1 = dijkstra(g, 0);
    auto dist2 = dijkstra(g, n - 1);

    int num1 = dist1[n - 1] / 2 + 1;
    int num2 = dist1[n - 1] / 2;
    loop(i, 1, n - 1) {
        if (dist1[i] < dist2[i]) ++num1;
        else ++num2;
    }
    if (num1 > num2) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
}

