#include <bits/stdc++.h>
using namespace std;
using ll=long long;
#define MOD 1000000007
#define MAX 2100000
#define INF 1001000000
using Graph=vector<vector<int>>;

vector<int> parent;

int dfs1(Graph &G,vector<int> &counter,int v,int p){
  int ans=0;
  for(auto nv:G.at(v)){
    if(nv==p){
      continue;
    }
    parent.at(nv)=v;
    ans+=dfs1(G,counter,nv,v);
  }
  return counter.at(v)=ans+1;
}

void dfs2(Graph &G,vector<int> &depth,int v,int p){
  for(auto nv:G.at(v)){
    if(nv==p){
      continue;
    }
    depth.at(nv)=depth.at(v)+1;
    dfs2(G,depth,nv,v);
  }
}

int main(){
  int N;
  cin>>N;
  Graph G(N);
  for(int i=0;i<N-1;i++){
    int a,b;
    cin>>a>>b;
    a--;
    b--;
    G.at(a).push_back(b);
    G.at(b).push_back(a);
  }

  vector<int> counter(N),depth(N);
  depth.at(0)=0;
  parent.resize(N);
  parent.at(0)=-1;
  dfs1(G,counter,0,-1);
  dfs2(G,depth,0,-1);

  int Fennec,Snuke;
  int x=N-1;
  for(int i=0;i<(depth.at(x)-1)/2;i++){
    x=parent.at(x);
  }
  Snuke=counter.at(x);
  Fennec=N-counter.at(x);
  if(Fennec>Snuke){
    cout<<"Fennex"<<endl;
  }else{
    cout<<"Snuke"<<endl;
  }
}

