enum{
    BLACK=-1,
    NONE=0,
    WHITE=1,
    BBIT=1,
    WBIT=2
};

typedef struct road{
    int l,r;
}Road;

int main(){
    int n;
    cin >> n;
    list<Road> g;
    int color[100000];
    int cbit[100000];
    int teban=BLACK;
    int rest=n-2;
    for(int i=0;i<n-1;i++){
        int a=0,b=0;
        cin >> a;
        cin >> b;
        Road d;
        d.l=a-1;
        d.r=b-1;
        g.push_back(d);
        color[i]=NONE;
        cbit[i]=0;
    }
    color[0]=BLACK;
    color[n-1]=WHITE;

    while(rest>0){
        //erabu
        rest=0;
        for(int i=0;i<n-1;i++){
            cbit[i]=0;
        }
        for(list<Road>::iterator i=g.begin();i!=g.end();){
            int l=color[i->l];
            int r=color[i->r];
            if (l==BLACK && r == NONE){
                cbit[i->r]+=BBIT;
            }
            if (l==WHITE && r == NONE){
                cbit[i->r]+=WBIT;
            }
            if (r==BLACK && l == NONE){
                cbit[i->l]+=BBIT;
            }
            if (r==WHITE && l == NONE){
                cbit[i->l]+=WBIT;
            }
            i++;
        }
        for(list<Road>::iterator i=g.begin();i!=g.end();){
            int l=color[i->l];
            int r=color[i->r];
//            cout << l << " " << r <<endl;
            if(cbit[i->r]==3){
                color[i->r]=teban;
                rest++;
                break;
            }else if(cbit[i->l]==3){
                color[i->l]=teban;
                rest++;
                break;
            }else{
                if(r==NONE&&l==teban){
                    color[i->r]=teban;
                    rest++;
                    break;
                }
                if(l==NONE&&r==teban){
                    color[i->l]=teban;
                    rest++;
                    break;
                }
                if (l!=NONE &&r!=NONE){
                    i=g.erase(i);
                }else{
                    i++;
                }
            }
        }
        //kaeru
        teban*=-1;
    }

    if (teban==BLACK){
        cout << "Fennec" << endl;
    }else{
        cout << "Sunuke" << endl;
    }
    return 0;
}

