struct edge{long long to,cost;};
typedef pair<long long,long long> P;

vector<edge> G[200010];// 隣接リスト表現
long long d[200010];
long long ds[200010];

void dijkstra(int s,int n){
    priority_queue<P,vector<P>,greater<P> > que;// 距離が小さい順に取り出せるようgreater<P>を指定
    fill(d,d+n,INF);
    d[s]=0;
    que.push(P(0,s));

    while(!que.empty()){
        P p=que.top();que.pop();
        int v=p.second;// 更新した頂点の中で距離が最小の頂点v
        if(d[v]<p.first)continue;
        for(auto e:G[v]){// 頂点vから出る辺eを走査
            if(d[e.to]>d[v]+e.cost){
                d[e.to]=d[v]+e.cost;
                que.push(P(d[e.to],e.to));
            }
        }
    }
}
void dijkstra2(int s,int n){
    priority_queue<P,vector<P>,greater<P> > que;// 距離が小さい順に取り出せるようgreater<P>を指定
    fill(ds,ds+n,INF);
    ds[s]=0;
    que.push(P(0,s));

    while(!que.empty()){
        P p=que.top();que.pop();
        int v=p.second;// 更新した頂点の中で距離が最小の頂点v
        if(ds[v]<p.first)continue;
        for(auto e:G[v]){// 頂点vから出る辺eを走査
            if(ds[e.to]>ds[v]+e.cost){
                ds[e.to]=ds[v]+e.cost;
                que.push(P(ds[e.to],e.to));
            }
        }
    }
}
