       cin>>a[i]>>b[i];
       a[i]--;b[i]--;
       G[a[i]].push_back({b[i],1});
       G[b[i]].push_back({a[i],1});
   }

   dijkstra(0,n);dijkstra2(n-1,n);
   int fe=0,sn=0;
