int main() {
  int n;
  scanf("%d", &n);
  vector<vector<int>> r(n);
  for(int i = 0; i < n - 1; i++) {
    int a, b;
    scanf("%d %d", &a, &b);
    r[--a].push_back(--b);
    r[b].push_back(a);
  }
  vector<P> used(n, P(0, 1000000));
  used[0] = P(1, 0), used[n - 1] = P(2, 0);
  queue<int> que;
  que.push(0);
  while(que.size()) {
    int q = que.front();
    que.pop();
    for(auto c : r[q]) {
      if(used[c].first == 0) {
        used[c] = P(1, used[q].second + 1);
        que.push(c);
      }
    }
  }
  que.push(n - 1);
  while(que.size()) {
    int q = que.front();
    que.pop();
    for(auto c : r[q]) {
      if(used[c].first == 0) {
        used[c] = P(2, used[q].second + 1);
        que.push(c);
      } else if(used[c].first == 1 && used[q].second + 1 < used[c].second) {
        used[c] = P(2, used[q].second + 1);
        que.push(c);
      }
    }
  }
  int f = 0, s = 0;
  for(auto x : used) {
    f += x.first & 1;
    s += x.first / 2 & 1;
  }
  if(f > s)
    printf("Fennec\n");
  else
    printf("Snuke\n");
}

