    }

    auto dij1 = Dijkstra(g, 0);
    auto dij2 = Dijkstra(g, n-1);
    map<string, ll> cnt;
    rep(i, n) (dij1[i] <= dij2[i]) ? cnt["Fennec"]++ : cnt["Snuke"]++;
    if(cnt["Fennec"] > cnt["Snuke"]) cout << "Fennec" << endl;
    else if(cnt["Fennec"] <= cnt["Snuke"]) cout << "Snuke" << endl;
}

