vector<int> cnt(100001, 0);
vector<int> root(100001, 0);

int rec(int corrent = 1, int count = 0){
    if(C == -1){
        root[count] = corrent;
        if(corrent == N) C = count;
    }
    for(int i = 0; i < graph[corrent].size(); ++i){
        int next = graph[corrent][i];
        if(!bit[next]){
            bit[next] = true;
            cnt[corrent] += rec(next, count + 1);
        }
    }
    return (cnt[corrent]) ? cnt[corrent] + 1 : 1;
}

int main(void){

