    for(int i = 0; i <= C / 2; ++i){
        int a = cnt[root[i]] + 1, b = cnt[root[i + 1]] + 1;
        black += (a >= b) ? a - b : 0;
    }
    int white = cnt[root[C / 2 + 1]] + 1;

    if(black > white) printf("Fennec\n");
    else printf("Snuke\n");

    return 0;
