int n ;
vector<vector<int> > g ;
int dfs(int x, int p){
    int ans = 1 ;
    for(int &c : g[x]){
        if ( c == p ) continue ;
        ans += dfs(c, x) ;
    }
    return ans ;
}
signed main(){
    fastio
    cin >> n ;
    g = vector<vector<int> >(n) ;
    for(int i = 0; i < n - 1; i++){
        int x , y ;
        cin >> x >> y ; 
        x--, y--;
        g[x].emplace_back(y) ;
        g[y].emplace_back(x) ; 
    }
    vector<int> dist(n, INF) ;
    vector<int> from(n, -1) ;
    dist[0] = 0 ;
    from[0] = 0 ;
    queue<int> q ;
    q.push(0) ;
    while(not q.empty()){
        int f = q.front() ; q.pop() ;
        for(int &c : g[f]){
            if ( dist[c] > dist[f] + 1 ){
                dist[c] = dist[f] + 1; 
                from[c] = f ;
                q.push(c) ;
            }
        }
    }
    int start = n - 1  ;
    vector<int> t ;
    while(from[start] != start){
        t.push_back(from[start]) ;
        start = from[start] ;
    }
    t.pop_back() ;
    debug() << imie(t) ;
    set<int> s ;
    for(int &c : t) s.insert(c) ;
    int m = (int) t.size() ;
    int ans = 0 ;
    for(int i = 0; i < m / 2; i++){
        int v = t[m - i - 1] ;
        int cnt = 1 ;
        for(int &c : g[v]){
            if ( s.count(c) ) continue ;
            cnt += dfs(c, v) ;
        }
        ans += cnt ;
    }
    debug() << imie(t) ;
    if (not t.empty()) {
        ans += dfs(n - 1, t.back()) ;
        ans-- ;
    }
    else{
        ans += dfs(n - 1, 0) ;
        ans--;
    }
    int rest = n - ans - 1 ;
    debug() << imie(ans) imie(rest) ;
    if ( rest >= ans ) {
        cout << "Fennec" << endl;
    }
    else cout << "Snuke" << endl;
    return 0; 
}

