const int MAX_N = int(1e5 + 5);
#define REP(i, n) for (int i = 0; i < n; i++)

int n, d[2][MAX_N];
vector<vector<int> > G;

void bfs(int k){
    queue<P> que;
    int s = (k?n-1:0);
    que.push({s,0});
    while(!que.empty()){
        P p = que.front();
        que.pop();
        int v = p.first;
        if(d[k][v]!=-1)continue;
        d[k][v] = p.second;
        for(auto u : G[v]){
            if(d[k][u]!=-1)continue;
            que.push({u,p.second+1});
        }
    }
}

int main() {
    cin >> n;
    G.resize(n);
    REP(i,n-1){
        int a, b;
        cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    REP(i,2) fill(d[i],d[i]+n,-1);
    REP(i,2) bfs(i); // 各頂点とFennec,Snukeの距離を求める
    int cnt = 0; // Fennecのとれる数
    REP(i,n){
        if(d[0][i]<=d[1][i])cnt++; // Fennecに近い
    }
    cout << (cnt > n/2 ? "Fennec":"Snuke") << endl; // とれる個数が過半数なら勝ち
    return 0;
}

