void ds1(){
	for(int i = 1; i <= N; i++) d1[i] = 9999999;
	priority_queue<P, vector<P>, greater<P>> que;
	d1[1] = 0;
	que.push(P(0, 1));
	while(!que.empty()){
		P p = que.top(); que.pop();
		int v = p.second;
		if(d1[v] < p.first) continue;
		for(auto i :G[v]){
			if(d1[i] > d1[v]+1){
				d1[i] = d1[v]+1;
				que.push(P(d1[i], i));
			}
		}
	}
}

void dsN(){
	for(int i = 1; i <= N; i++) dN[i] = 9999999;
	priority_queue<P, vector<P>, greater<P>> que;
	dN[N] = 0;
	que.push(P(0, N));
	while(!que.empty()){
		P p = que.top(); que.pop();
		int v = p.second;
		if(dN[v] < p.first) continue;
		for(auto i :G[v]){
			if(dN[i] > dN[v]+1){
				dN[i] = dN[v]+1;
				que.push(P(dN[i], i));
			}
		}
	}
}

