int main() {
    int n; std::cin >> n;
    std::vector<std::vector<int>> edg(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b; std::cin >> a >> b;
        a--; b--;
        edg[a].push_back(b);
        edg[b].push_back(a);
    }
    auto dijkstra = [&](int start, auto &dist) {
        std::deque<int> que;
        que.emplace_back(start);
        dist[start] = 0;
        while (!que.empty()) {
            int pos = que.front();
            que.pop_front();
            for (int u : edg[pos]) {
                if (dist[u] <= dist[pos] + 1) continue;
                dist[u] = dist[pos] + 1;
                que.emplace_back(u);
            }
        }
    };
    std::vector<int> distf(n, 1e9), dists(n, 1e9);
    dijkstra(0, distf);
    dijkstra(n - 1, dists);
    int s = 0;
    for (int i = 0; i < n; i++) {
        s += distf[i] <= dists[i];
    }
    std::cout << (s > (n - s) ? "Fennec" : "Snuke") << std::endl;
    return 0;
}

