ll D1(){
    ll res = 1;
    ll d[100010];
    fill(d,d+100010,0);
    queue<ll> Q;
    Q.push(0);
    while(Q.size()){
        ll x = Q.front();
        ll n = G[x].size();
        d[x] = 1;
        Q.pop();
        rep(i,n){
            if(!d[G[x][i]] && path[G[x][i]] != 1){
                res++;
                Q.push(G[x][i]);
            }
        }
    }
    return res;
}

ll D2(){
    ll res = 1;
    ll d[100010];
    fill(d,d+100010,0);
    queue<ll> Q;
    Q.push(0);
    while(Q.size()){
        ll x = Q.front();
        ll n = G[x].size();
        d[x] = 1;
        Q.pop();
        rep(i,n){
            if(!d[G[x][i]] && path[G[x][i] != 2]){
                res++;
                Q.push(G[x][i]);
            }
        }
    }
    return res;
}

bool dfs(ll x,ll m,ll p = -1){

    if(x == N-1){
        cnt++;
        L = m;
        path[x] = 1;
        return true;
    }
    ll n = G[x].size();
    rep(i,n){
        if(G[x][i] == p) continue;
        if(dfs(G[x][i],m+1,x)){
            m++;
            if(cnt < L / 2) path[x] = 1;
            else path[x] = 2;
            cnt++;
            return true;
        }
    }
    return 0;
}

