#include <iostream>
#include <vector>
#include <deque>
using namespace std;

int main() {
  int N;
  cin >> N;

  vector<vector<int>> nvec;
  int check[100010];
  for (int i = 0; i < N; i++) {
    vector<int> temp;
    nvec.push_back(temp);
    check[i] = 0;
  }
  check[0] = check[N-1] = 1;

  for (int i = 0; i < N-1; i++) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    nvec.at(a).push_back(b);
    nvec.at(b).push_back(a);
  }

  deque<int> vB, vW;
  vB.push_back(0);
  vW.push_back(N-1);
  int cB, cW;
  cB = cW = 1;
  while(1) {
    /*
    cout << "vB: ";
    for (auto x: vB) cout << x << " ";
    cout << endl;
    cout << "vW: ";
    for (auto x: vW) cout << x << " ";
    cout << endl;
    cout << "----" << endl;
    */

    int tempB, tempW;
    tempB = tempW = 0;
    for (auto x: vB)
      for (auto y: nvec.at(x))
	if (check[y] == 0) {
	  vB.push_back(y);
	  check[y] = 1;
	  tempB++;
	}
    int del_size = vB.size() - tempB;
    for (int i = 0; i < del_size; i++) vB.pop_front();

    for (auto x: vW)
      for (auto y: nvec.at(x))
	if (check[y] == 0) {
	  vW.push_back(y);
	  check[y] = 1;
	  tempW++;
	}
    del_size = vW.size() - tempW;
    for (int i = 0; i < del_size; i++) vW.pop_front();

    if (tempB == 0 && tempW == 0) break;
    else {
      cB += tempB;
      cW += tempW;
    }
  }

  if (cB <= cW) {
    cout << "Snuke" << endl;
  } else {
    cout << "Fennec" << endl;
  }

  return 0;
}

#include<iostream>
#include<vector>
#include<queue>


int main() {
	int n;
	std::cin >> n;

	std::vector<std::vector<int>> tab(n);

	for (int i{}; i < n - 1; ++i) {
		int a, b;
		std::cin >> a >> b;
		--a; --b;
		tab[a].emplace_back(b);
		tab[b].emplace_back(a);
	}

	std::vector<int> check(n, 1);


	auto wcount = 0;
	std::queue<int> wq;
	wq.emplace(n-1);
	check[n-1] *= 2;


	while (!wq.empty()) {

		auto vtx = wq.front(); wq.pop();

		for (auto e : tab[vtx]) {

			if (check[e] % 2 == 0 || e == 0)
				continue;

			wq.emplace(e);
			check[e] *= 2;
			++wcount;

		}
	}


	decltype(wcount) bcount{};
	decltype(wq) bq;
	bq.emplace(0);
	check[0] *= 3;

	while (!bq.empty()) {

		auto vtx = bq.front(); bq.pop();
		for (auto e : tab[vtx]) {

			if (check[e] % 3 == 0 || e == n - 1)
				continue;

			bq.emplace(e);
			check[e] *= 3;
			++bcount;
		}
	}

	auto c = std::count(std::begin(check), std::end(check), 6);
	bcount += c % 2;
//	std::cout << c << " " << wcount << " " << bcount << "\n";
	std::cout << (wcount <= bcount ? "Fennec" : "Snuke") << "\n";

	return 0;
}

