//マスに色を塗った回数の多いプレイヤーの勝ち、同数の場合は後手の勝ちというゲームを
//考えることにする。元のゲームでどちらかのプレイヤーが敗北したあとも色を塗ることが
//可能であると考えると新しいゲームの勝敗と元のゲームの勝敗が一致することがわかる
//この時二人の目的は自分が色を塗る回数を最大化し相手が色を塗る回数を最小化することである
//与えられてるグラフが木であることから二人の最善戦略はマス１からNへのパス上に色が塗られていない
//マスが存在するならば色を塗るであることが示される。これらをふまえて探索する
int N;
vector<vector<int>>G;
bool visited1[100100];
bool visited2[100100];
int key1[100100];//フェネックから見た距離
int key2[100100];//すぬけから見た距離
int main() {
	cin >> N;
	G.resize(N);
	REP(i, N) {
		visited1[i] = false;
		visited2[i] = false;
		key1[i] = 0;
		key2[i] = 0;
	}
	for (int i = 0; i < N-1; ++i) {
		int a, b; cin >> a >> b;
		a--, b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	//0からとN-1からの両方からbfsを行う。同じ距離なら黒く塗る。どちらかに近いなら近いほうの色で塗る
	queue<int>Q1, Q2;
	Q1.push(0);
	Q2.push(N-1);
	visited1[0] = true;
	visited2[N - 1] = true;
	while (!Q1.empty()) {
	    int p = Q1.front();
		Q1.pop();
		for (int a : G[p]) {
			if (!visited1[a]) {
				key1[a] = key1[p] + 1;
				visited1[a] = true;
				Q1.push(a);
			}
		}
	}
	while (!Q2.empty()) {
		int p = Q2.front();
		Q2.pop();
		for (int a : G[p]) {
			if (!visited2[a]) {
				key2[a] = key2[p] + 1;
				visited2[a] = true;
				Q2.push(a);
			}
		}
	}
	int cntF = 0;
	int cntS = 0;
	for (int i = 0; i < N; ++i) {
		if (key1[i] <= key2[i]) {
			cntF++;
		}
		else {
			cntS++;
		}
	}
	if (cntF <= cntS)cout << "Snuke" << endl;
	else cout << "Fennec" << endl;
	return 0;
}

