#include <iostream>
#include <vector>
#include <utility>
#include <queue>
#include <set>

using namespace std;

struct Node {
  std::set<int> out;
  std::set<int> in;
};

using Tree = std::vector<Node>;

std::vector<int> bfs(Tree& tree, int from, int dst, std::vector<bool>& visited) {
  std::queue<std::vector<int>> q;
  q.push({from});
  while (q.size() > 0) {
    std::vector<int>& route = q.front();
    for (auto n : tree[route.back()].out) {
      if (visited[n])
        continue;
      std::vector<int> next = route;
      next.push_back(n);
      if (n == dst)
        return next;
      q.emplace(std::move(next));
    }
    for (auto n : tree[route.back()].in) {
      if (visited[n])
        continue;
      std::vector<int> next = route;
      next.push_back(n);
      if (n == dst)
        return next;
      q.emplace(std::move(next));
    }
    q.pop();
  }
  return {};
}

int counts(Tree& tree, int v) {
  int sum = 1;
  std::set<int> tmp = tree[v].out;
  for (int a : tmp) {
    tree[v].out.erase(a);
    tree[a].in.erase(v);
    sum += counts(tree, a);
  }
  tmp = tree[v].in;
  for (int a : tmp) {
    tree[v].in.erase(a);
    tree[a].out.erase(v);
    sum += counts(tree, a);
  }
  return sum;
}

int main() {
  int n;
  cin >> n;
  Tree tree(n);
  for (int i = 0; i < n - 1; i++) {
    int in, out;
    cin >> in >> out;
    tree[in - 1].out.insert(out - 1);
    tree[out - 1].in.insert(in - 1);
  }

  int black = 0;
  int white = n - 1;
  std::vector<bool> visited(n);
  std::vector<int> route = bfs(tree, black, white, visited);
  int half = route.size() / 2;
  int black_side_id = route[route.size() - half - 1];
  int white_side_id = route[route.size() - half];

  Node& black_side = tree[black_side_id];
  black_side.out.erase(white_side_id);
  black_side.in.erase(white_side_id);

  Node& white_side = tree[white_side_id];
  white_side.out.erase(black_side_id);
  white_side.in.erase(black_side_id);

  int black_num = counts(tree, black_side_id);
  int white_num = counts(tree, white_side_id);

  std::cout << (black_num > white_num ? "Fennec" : "Snuke") << std::endl;
  return 0;
}

