	vector<int> path;
	while (key != -2) {
		path.push_back(key);
		key = parent[key];
	}
	//cout << parent[3] << endl;
	int left = path[(path.size() - 1) / 2];
	int right = path[path.size() / 2];
	int size = v[left].size();
	REP(i, size) {
		int k = v[left][0];
		v[left].erase(v[left].begin());
		if (k != right) {
			v[left].push_back(k);
		}
	}
	size = v[right].size();
	REP(i, size) {
		int k = v[right][0];
		v[right].erase(v[right].begin());
		if (k != left) {
			v[right].push_back(k);
		}
	}

	REP(i, N) {
