void solve() {
  ll N;
  cin >> N;

  VVL edgeList(N, VL(0));

  rep(i, N - 1) {
    ll a, b;
    cin >> a >> b;
    a--, b--;
    edgeList[a].push_back(b);
    edgeList[b].push_back(a);
  }

  VL colors(N, -1);  // B: 0, W: 1
