  queue<ll> wq;
  wq.push(N - 1);

  while (!bq.empty() || !wq.empty()) {
    auto rec = [&](queue<ll>& q, ll color) {
      if (q.empty()) return;

      queue<ll> next_q;

      while (!q.empty()) {
        ll next = q.front();
        q.pop();

        for (auto to : edgeList[next]) {
          if (colors[to] != -1) continue;
          colors[to] = color;
          next_q.push(to);
        }
      }

      q = next_q;
    };

    rec(bq, 0);
    rec(wq, 1);
  }

  ll bct = 0, wct = 0;
  for (auto c : colors) {
    if (c == 0)
      bct++;
    else
      wct++;
  }

  if (bct <= wct) {
    cout << "Snuke" << endl;
  } else {
    cout << "Fennec" << endl;
  }
}

