lli dup_count = 0;

lli rec1(lli start, lli end, lli cur) {
    if (cur == end)
        return 0;

    if (done_1[cur])
        return 0;
    done_1[cur] = true;

    lli total = 0;
    REP(i, 0, G[cur].size()) {
        total += rec1(start, end, G[cur][i]) + 1;
    }
    return total;
}
lli rec2(lli start, lli end, lli cur) {
    if (cur == end)
        return 0;

    if (done_2[cur])
        return 0;
    done_2[cur] = true;
    if (done_1[cur])
        dup_count++;

    lli total = 0;
    REP(i, 0, G[cur].size()) {
        total += rec2(start, end, G[cur][i]) + 1;
    }
    return total;
}

