int main() {
    int N;
    cin >> N;

    vector<vector<int>> graph(N);

    REP(i, N - 1) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;

        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    int total;
    {
        total = 0;
        vector<bool> visited(N, false);
        // visiting N - 1 is illegal.
        visited[N - 1] = true;

        queue<int> next;
        next.push(0);

        while (!next.empty()) {
            int current = next.front();
            next.pop();

            if (visited[current]) continue;

            visited[current] = true;
            total++;

            REP(i, graph[current].size()) {
                next.push(graph[current][i]);
            }
        }
    }
    int fennec_reserved = total - 1;

    {
        total = 0;
        vector<bool> visited(N, false);
        // visiting 0 is illegal.
        visited[0] = true;

        queue<int> next;
        next.push(N - 1);

        while (!next.empty()) {
            int current = next.front();
            next.pop();

            if (visited[current]) continue;

            visited[current] = true;
            total++;

            REP(i, graph[current].size()) {
                next.push(graph[current][i]);
            }
        }
    }
    int snuke_reserved = total - 1;

    if( fennec_reserved < snuke_reserved )
        cout << "Snuke" << endl;
    else if( fennec_reserved > snuke_reserved )
        cout << "Fennec" << endl;
    else
    {
        // same -> 先行が有利
        cout << "Fennec" << endl;
    }

    return 0;
}

