#include <bits/stdc++.h>
using namespace std;
int V;
vector<int> G[111111];
int parent[111111];
int visit[111111];
int cnt,depth;
void dfs(int x){
    if(x==V)depth=cnt;
    cnt++;
    for(int i:G[x]){
        if(!parent[i]){
            parent[i]=x;
            dfs(i);
        }
    }
    cnt--;
}
int dfs2(int x){
    visit[x]++;
    int find=1;
    for(int i:G[x])
        if(!visit[i])
            find+=dfs2(i);
    return find;
}
int main(){
    ios_base::sync_with_stdio(false);cin.tie(NULL);
    cin>>V;
    for(int i=0;i<V-1;i++){
