        cin>>x>>y;
        G[x].push_back(y);
        G[y].push_back(x);
    }
    parent[1]=-1;
    dfs(1);
    int dist = (depth+1)/2;
    int middle=V;
    while(dist--){
        middle=parent[middle];
    }
    visit[middle]++;
    int find = dfs2(V);
    if(find<V-find){
        cout<<"Fennec";
    }
    else cout<<"Snuke";
    return 0;
}

