	std::cin >> n;

	std::vector<std::vector<int>> tab(n);

	for (int i{}; i < n - 1; ++i) {
		int a, b;
		std::cin >> a >> b;
		--a; --b;
		tab[a].emplace_back(b);
		tab[b].emplace_back(a);
	}

	std::vector<int> check(n, 1);


	auto wcount = 0;
	std::queue<int> wq;
	wq.emplace(n-1);
	check[n-1] *= 2;


	while (!wq.empty()) {

		auto vtx = wq.front(); wq.pop();

		for (auto e : tab[vtx]) {

			if (check[e] % 2 == 0 || e == 0)
				continue;

			wq.emplace(e);
			check[e] *= 2;
			++wcount;

		}
	}


	decltype(wcount) bcount{};
	decltype(wq) bq;
	bq.emplace(0);
	check[0] *= 3;

	while (!bq.empty()) {

		auto vtx = bq.front(); bq.pop();
		for (auto e : tab[vtx]) {

			if (check[e] % 3 == 0 || e == n - 1)
				continue;

			bq.emplace(e);
			check[e] *= 3;
			++bcount;
		}
	}

	auto c = std::count(std::begin(check), std::end(check), 6);
	bcount += c % 2;
//	std::cout << c << " " << wcount << " " << bcount << "\n";
	std::cout << (wcount < bcount ? "Fennec" : "Snuke") << "\n";

	return 0;
