      p[v[c][i]] = p[c] + 1;
      q.push(v[c][i]);
    }
  }
  int u = p[n] - 1;
  int black = count - u + u / 2;
  int white = n - black;
  if (black > white) printf("Fennec\n");
  else printf("Snuke\n");

  return 0;
}

