const int MAX=1e5+1;

vector<vector<int>> g(100005);

bool used[MAX];

bool bfs(int f,int l){
    memset(used,false,sizeof(used));
    queue<int> quef;
    queue<int> quel;
    quef.push(f);
    quel.push(l);
    used[f]=true;
    used[l]=true;
    while(!quef.empty()&&!quel.empty()){
        int u=quef.front(); quef.pop();
        int v=quel.front(); quel.pop();
        for(auto it=g[u].begin();it!=g[u].end();it++){
            int next=*it;
            if(!used[next]){
                used[next]=true;
                quef.push(next);
            }
        }
        for(auto it=g[v].begin();it!=g[v].end();it++){
            int next=*it;
            if(!used[next]){
                used[next]=true;
                quel.push(next);
            }
        }
    }
    if(quef.empty()) return false;
    else return true;
}

