  SnukeQueue.push_back(n);
  int fennec_score = 1, snuke_score = 1;
  while (!FennecQueue.empty() || !SnukeQueue.empty()) {
    std::vector<int> FennecSearch = FennecQueue;
    FennecQueue.erase(FennecQueue.begin(), FennecQueue.end());
    for (auto x : FennecSearch) {
      for (auto y : node[x].to) {
        if (node[y].owner == None) {
          FennecQueue.push_back(y);
          node[y].owner = Fennec;
          fennec_score++;
        }
      }
    }
    std::vector<int> SnukeSearch = SnukeQueue;
    SnukeQueue.erase(SnukeQueue.begin(), SnukeQueue.end());
    for (auto x : SnukeSearch) {
      for (auto y : node[x].to) {
        if (node[y].owner == None) {
          SnukeQueue.push_back(y);
          node[y].owner = Snuke;
          snuke_score++;
        }
      }
    }
  }
  if (snuke_score > fennec_score) {
    cout << "Snuke";
  } else {
    cout << "Fennec";
  }
  cout << endl;

  return 0;
}

