#include <iostream>
#include <cstdio>
#include <vector>
using namespace std;

const int MAX = 1e5;
const int INF = 1e9;
int N;
vector<vector<int> > edge(MAX);
int d1[MAX]; // マス1から各マスへの最短距離
int dN[MAX]; // マスNから各マスへの最短距離

// n:どのマスにいるか、d:始点からの距離
void dfs(int n, int d, bool flag) {
  for (int i = 0; i < edge[n].size(); i++) {
    if (flag) {
      if (edge[n][i] == N - 1) continue;
      if (d1[edge[n][i]] < INF) continue;
      d1[edge[n][i]] = d;
      dfs(edge[n][i], d + 1, true);
    } else {
      if (edge[n][i] == 0) continue;
      if (dN[edge[n][i]] < INF) continue;
      dN[edge[n][i]] = d;
      dfs(edge[n][i], d + 1, false);
    }
  }
}

int main() {
  cin >> N;
  int a, b;
  for (int i = 0; i < N - 1; i++) {
    scanf("%d %d", &a, &b);
    a--; b--;
    edge[a].push_back(b);
    edge[b].push_back(a);
  }

  // 深さ優先探索で1のマスからの各マスへの距離と、Nのマスから各マスへの距離を計算する
  fill(d1, d1 + MAX, INF);
  fill(dN, dN + MAX, INF);
  dfs(0, 1, true);
  dfs(N - 1, 1, false);

  // 各マスにおいて、d1 <= dNならば黒、そうでないなら白に塗られる
  // 全マスで計算して、多い方の勝ち。同じ場合は後手が勝つ
  int black, white;
  black = white = 1;
  for (int i = 1; i < N - 1; i++) {
    if (d1[i] <= dN[i]) black++;
    else white++;
  }

  // 解答
  cout << (black > white ? "Fennec" : "Snuke") << endl;

  return 0;
}

