        q=x;
        F=0;
        rep(i,n){
            if(x[i]==3){
                rep(j,n-1) {
                    if(a[j]==i && q[b[j]]==0) q[b[j]]=3,F=1;
                    if(b[j]==i && q[a[j]]==0) q[a[j]]=3,F=1;
                }
                q[i]=1;
            }
            if(x[i]==4){
                rep(j,n-1) {
                    if(a[j]==i && q[b[j]]==0) q[b[j]]=4,F=1;
                    if(b[j]==i && q[a[j]]==0) q[a[j]]=4,F=1;
                }
                q[i]=2;
            }
        }
        x=q;
    }
    for(int i:x) f+=(i%2);

    if(f<(n-f)) cout<<"Snuke\n";
    else cout<<"Fennec\n";

     return 0;
}

