		path[a].insert(b);
		path[b].insert(a);
	}

	vector<int> fenn(N);
	vector<int> snuke(N);

	calc_dist(0, fenn);
	calc_dist(N - 1, snuke);

	set<int> fenq;
	set<int> snukeq;

	fenq.insert(0);
	snukeq.insert(N - 1);

	while (fenq.size() && snukeq.size()) {
