		int fen_next = -1;

		for (auto f : fenq) {
			if (fen_max > snuke[f] && fenn[f] != -1) {
				fen_max = snuke[f];
				fen_next = f;
			}
		}

		if (fen_next == -1) {
			// fen failed.
			cout << "Snuke" << endl;
			return 0;
		}
		fenn[fen_next] = -1;
		snuke[fen_next] = -1;
		fenq.erase(fen_next);
		snukeq.erase(fen_next);

		for (auto f : path[fen_next]) {
			if (fenn[f] != -1) {
				fenq.insert(f);
			}
		}

		// snuke
		// fenn first
		int snuke_max = 100001;
		int snuke_next = -1;

		for (auto f : snukeq) {
			if (snuke_max > fenn[f] && snuke[f] != -1) {
				snuke_max = fenn[f];
				snuke_next = f;
			}
		}

		if (snuke_next == -1) {
			// snuke failed.
			cout << "Fennec" << endl;
			return 0;
		}

		fenn[snuke_next] = -1;
		snuke[snuke_next] = -1;
		fenq.erase(snuke_next);
		snukeq.erase(snuke_next);

		for (auto f : path[snuke_next]) {
			if (snuke[f] != -1) {
				snukeq.insert(f);
			}
		}

	}

	if (fenq.size() == 0) {
		cout << "Snuke" << endl;
	} else {
		cout << "Fennec" << endl;
	}

	return 0;
}

