void printPath(vector<int> stack, vector<int> *v) 
{ 
	int black=0, white = 0, n = (stack.size()+1)/2;
	for(int i = 0; i<n; i++)
		black += v[stack[i]].size();

	for(int i = n;i<stack.size(); i++)
		white += v[stack[n]].size();
	if(black>white)
		cout<<"Fennec"<<endl;
	else
		cout<<"Snuke"<<endl; 
} 

void DFS(vector<int> *v, bool *vis, int x, int y, vector<int> stack) 
{ 
	stack.push_back(x); 
	if (x == y) {
		printPath(stack,v); 
		return; 
	} 
	vis[x] = true;
	int flag = 0; 
	if (!v[x].empty()) { 
		for (int j = 0; j < v[x].size(); j++) {
			if (vis[v[x][j]] == false) { 
				DFS(v, vis, v[x][j], y, stack); 
				flag = 1; 
			} 
		} 
	} 
	if (flag == 0) { 
		stack.pop_back(); 
	} 
} 
