int dfs(int from, int dist, const vector<vector<int>>& E, vector<bool>& visited) {
    if (from == E.size() - 1) {
        return dist;
    }
    visited[from] = true;
    int ret = -1;
    for (int to : E[from]) {
        if (!visited[to]) {
            ret = max(dfs(to, dist + 1, E, visited), ret);
        }
    }
    if (ret >= 0 && dist > (ret+1)/2) {
        visited[from] = false;
    }
    return ret;
}

