inline void solve(){
	queue<int> que;
	int depth=0,f_num=1,flag=1;
	que.push(1);
	while(!que.empty()){
		int v=que.front();
		que.pop();
		rep(i,edg[v].size()){
			if(edg[v][i]==n){ flag=0; continue; }
			if(!used[edg[v][i]]){
				used[edg[v][i]]=1;
				que.push(edg[v][i]);
				++f_num;
			}
		}
		depth+=flag;
	}
	int fe=f_num-depth/2;
	int su=n-fe;
	if(fe>su) cout<<"Fennec";
	else cout<<"Snuke";
	return;
}

