const int maxn = 100005;

int n, dep[maxn], siz[maxn];
int head[maxn], adj[maxn * 2], nxt[maxn * 2], total;
bool hav[maxn];

inline void addedge(int u, int v){
	++total, adj[total] = v, nxt[total] = head[u], head[u] = total;
}

void dfs(int u, int f){
	siz[u] = 1, hav[u] |= (u == n);
	for(int i = head[u]; i; i = nxt[i])
		if(adj[i] != f){
			dep[ adj[i] ] = dep[u] + 1;
			dfs(adj[i], u);
			hav[u] |= hav[ adj[i] ];
			siz[u] += siz[ adj[i] ];
		}
}

