#include <iostream>
#include <vector>
using namespace std;
#define MAX_SIZE 100001

vector<int> tree[MAX_SIZE+1];
int parent[MAX_SIZE] = {};
int score[MAX_SIZE] = {};

bool debugFlag = false;

int dfs(int v, int p)
{
    int result = 0;
    parent[v] = p;
    for(int i = 0; i < static_cast<int>(tree[v].size()); ++i)
    {
        int nv = tree[v].at(i);
        if(nv == p)
        {
            continue;
        }
        result += dfs(nv, v);
    }
    ++result;
    if(debugFlag)
    {
        cout << v <<" score : " << result << endl;
    }
    score[v] = result;
    return result;
}

int calcPathNum(int n)
{
    int pathNum = 0;
    int p = n;
    if(debugFlag)
    {
        cout << "calcPathNum" << endl;
    }

    while(p != 1)
    {
        pathNum += 1;
        p = parent[p];
    }

    int result = pathNum/2;

    return result;
}

int ScoreDec(int n)
{
    if(debugFlag)
    {
        cout << "ScoreDec" << endl;
        cout << "n : " << n << endl;
    }
    int result = 0;
    int pathNum = calcPathNum(n);
    int p = n;

    for(int i = 0; i < pathNum-1; ++i)
    {
        p = parent[p];
    }
    result = score[p];
    if(debugFlag)
    {
        cout << "2p scr : "<< result << endl;
    }
    return result;
}

