vector<vector<int>> h;
vector<int> color;
vector<int> path;
int count_d;

bool search(int u, int v) {
  for (int x : h.at(u)) {
    if (d.at(x))
      continue;
    d.at(x) = true;
    if (x == v) {
      path.push_back(x);
      return true;
    }
    if (search(x, v)) {
      path.push_back(x);
      return true;
    }
  }
  return false;
}

void dfs(int u, int v) {
  if (u == v)
    return;
  d.at(u) = true;
  count_d++;
  for (int x : h.at(u)) {
    if (!d.at(x))
      dfs(x, v);
  }
}

