  for (int i = 0; i < N + 1; i++)
    d.at(i) = false;
  for (int i = 0; i < N - 1; i++) {
    cin >> u >> v;
    h.at(u).push_back(v);
    h.at(v).push_back(u);
  }
  d.at(1) = true;
  search(1, N);
  for (int i = 0; i < N + 1; i++)
    d.at(i) = false;
  d.at(1) = true;
  dfs(1, path.at((path.size() + 1) / 2 - 1));
