    REP(i, N - 1) {
        i64 a, b; cin >> a >> b;
        a--, b--;
        G[a].pb(b);
        G[b].pb(a);
    }

    auto bfs = [&](i64 s) {
        vector<i64> d(N, -1);
        queue<i64> que;
        d[s] = 0;
        que.push(s);
        while (!que.empty()) {
            i64 u = que.front(); que.pop();
            for (i64 v : G[u]) {
                if (d[v] != -1) continue;
                d[v] = d[u] + 1;
                que.push(v);
            }
        }
        return d;
    };

