    */

    int tempB, tempW;
    tempB = tempW = 0;
    for (auto x: vB)
      for (auto y: nvec.at(x))
	if (check[y] == 0) {
	  vB.push_back(y);
	  check[y] = 1;
	  tempB++;
	}
    int del_size = vB.size() - tempB;
    for (int i = 0; i < del_size; i++) vB.pop_front();

    for (auto x: vW)
      for (auto y: nvec.at(x))
	if (check[y] == 0) {
	  vW.push_back(y);
