#include <bits/stdc++.h>
using namespace std;

vector<int> getPath(vector<vector<int>>& es){
  int n = es.size();
  int s = 0,t = n-1;

  queue<int> que;
  vector<int> prev(n,-1);
  prev[s] = 1;
  que.push(s);
  while(!que.empty()){
    int now = que.front();que.pop();
    for(int i=0;i<es[now].size();i++){
      int nxt = es[now][i];
      if(prev[nxt] != -1)continue;
      prev[nxt] = now;
      que.push(nxt);
    }
  }
  vector<int> path;
  path.push_back(t);
  int now = t;
  while(now != s) {
    now = prev[now];
    path.push_back(now);
  }
  reverse(path.begin(),path.end());
  return path;
}

bool draw(vector<int>& path, vector<int>& color, vector<vector<int>>& es,int c,int s){
  int n = color.size();

  for(int i=1;i<path.size()-1;i++){
    int now = path[i];
    if( color[now] == 0 ){
      color[now] = c;
      return true;
    }
  }

  queue<int> que;
  vector<int> used(n);
  used[s] = 1;
  que.push(s);
  while(!que.empty()){
    int now = que.front();que.pop();
    if(color[now] )
    for(int i=0;i<es[now].size();i++){
      int nxt = es[now][i];
      if(used[nxt] != 0)continue;
      if(color[nxt] == 0) {
        color[nxt] = c;
        return true;
      }
      if(color[nxt] == c){
        used[nxt] = 1;
        que.push(nxt);
      }
    }
  }
  return false;
}

int main(void) {
  int N;
  cin >> N;
  vector<vector<int>> es(N);
  for(int i=0;i<N-1;i++){
    int a,b;
    cin >> a >> b;
    a--;b--;
    es[a].push_back(b);
    es[b].push_back(a);
  }

  // 相手の方に近づく方向に塗るだけ
  vector<int> color(N);
  color[0] = 1;
  color[N-1] = -1;

  vector<int> path = getPath(es);
  // cerr << "path" << endl;
  // for(int i=0;i<path.size();i++){
  //   cerr << path[i] << " ";
  // }cerr << endl;

  int c = 1;
  for(;;){
    bool ret = false;
    if(c == 1)
      ret = draw(path,color,es,c,0);
    else
      ret = draw(path,color,es,c,N-1);

    if(!ret){
      if(c == 1)cout << "Snuke" << endl;
      else cout << "Fennec" << endl;
      break;
    }
    reverse(path.begin(),path.end());
    c = -c;
    for(int i=0;i<N;i++){
      cerr << color[i] << " ";
    }cerr << endl;
  }

  return 0;
}

