        adj[b].push_back(a);
    }

    depth(0,0);
    int d = color[n-1];
    REP(i,101010) {
        if (color[i] == d / 2) initb = i;
        if (color[i] == d / 2 + 1) initw = i;
    }

    REP(i,101010) color[i] = -1;
    color[initb] = 0;
    color[initw] = 1;
    c(0, initb);
