    while (!s.empty()) {
        pair<int, int> p = s.back();
        s.pop_back();
        visited[p.first] = true;
        dist[p.first] = p.second;
        for (auto &node : tree[p.first]) {
            if (!visited[node]) {
                s.push_back({node, p.second + 1});
            }
        }
    }
}

