using graph_type = std::vector<std::vector<int32_t>>;

void calc_dist(int32_t start, std::vector<int32_t>& res, graph_type& Graph) {
  res[start] = 0;
  //BFS
  std::queue<int32_t> nexts;
  for (auto i : Graph[start]) {
    nexts.push(i);
    res[i] = res[start] + 1;
  }
  while (!nexts.empty()) { 
    int32_t cur = nexts.front();
    nexts.pop();
    for (auto child : Graph[cur]) {
      if (res[child] == -1) {
        nexts.push(child);
        res[child] = res[cur] + 1;
      }
    }
  }
  return;
}

int main(){
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);

  int32_t N;
  std::cin >> N;;
  graph_type Graph(N);
  for (int32_t i = 0; i< N-1; i++) {
    int32_t a,b;
    std::cin >> a >> b;
    Graph[a-1].emplace_back(b-1);
    Graph[b-1].emplace_back(a-1);
  }

  std::vector<int32_t> dist_from1(N, -1);
  std::vector<int32_t> dist_fromN(N, -1);
  calc_dist(0, dist_from1, Graph);
  calc_dist(N-1, dist_fromN, Graph);

  int32_t close_to_1 = 0;
  for (int32_t i = 0; i < N; i++) {
    //std::cout << "dist[0," << i << "] = " << dist_from1[i] << std::endl; 
    //std::cout << "dist[N-1," << i << "] = " << dist_fromN[i] << std::endl; 
    if (dist_from1[i] <= dist_fromN[i]) close_to_1++;
  }
  int32_t close_to_N = N - close_to_1;
  if (close_to_1 > close_to_N) { 
    std::cout << "Fennec" << std::endl;
  } else {
    std::cout << "Snuke" << std::endl;
  }

  return 0;
}

