bool dfs(vector<vector<int>> &tr, int parent, int cur, vector<int> &path) {
    if (cur == tr.size() - 1) {
        path.push_back(cur);
        return true;
    }
    for (auto nxt : tr[cur]) {
        if (nxt == parent) continue;
        if (dfs(tr, cur, nxt, path)) {
            path.push_back(cur);
            return true;
        }
    }
    return false;
}

void dfs2(vector<vector<int>> &tr, int cur, vector<int> &col) {
    for (auto nxt : tr[cur]) {
        if (col[nxt]) continue;
        col[nxt] = col[cur];
        dfs2(tr, nxt, col);
    }
}

