int N;
vector<vector<int>> graph;

int kid(int root, int opponent) {
    queue<int> task;
    bool vis[N];
    fill(vis, vis + N, false);
    vis[root] = true;
    task.push(root);
    int res = 0;
    while(!task.empty()) {
        int from = task.back(); task.pop();
        for(int i = 0; i < graph[from].size(); ++i) {
            int to = graph[from][i];
            if(vis[to] || to == opponent) continue;
            vis[to] = true;
            task.push(to);
            ++res;
        }
    }
    return res;
}

int main()
{
    scanf("%d", &N);
    graph.resize(N);
    for(int i = 0; i < N-1; ++i) {
        int a, b;
        scanf("%d %d", &a, &b);
        --a, --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    if(kid(0, N-1) >= kid(N-1, 0)) printf("Fennec\n");
    else printf("Snuke\n");
    return 0;
}

