    E=V-1;
    for(int i = 0;i < E;i++){
        cin >> s>>t;
        c=1;
        G[s-1].pb((edge){t-1,c});
        G[t-1].pb((edge){s-1,c});
    }

    start=0;
    goal=V-1;


    for(int i = 0;i < V;i++){
        col[i]=0;
    }


    dijkstra(start);

    int disH;
    disH = (d[goal]+1)/2;

    int numB=0,numW=0;
    for(int i = 0;i < V;i++){
        if(d[i]<=disH){
            col[i]=1;
            numB++;
        }
    }

    queue<int> que;
    que.push(goal);
    numW++;

     col[goal]=1;

    while(!que.empty()){
        int q;
        q=que.front();que.pop();
        for(int i = 0;i < G[q].size();i++){
            if(col[G[q][i].to] != true){
                que.push(G[q][i].to);
                numW++;
                col[G[q][i].to]=1;
            }
        }
    }
    if(numW>=(V+1)/2){
        cout<< "Snuke"<< endl;
    }else{
        cout<< "Fennec"<< endl;
    }


    return 0;
}

