int main(void) {
  int N;
  cin >> N;
  vector<vector<int>> G(N);
  rep(i, N - 1) {
    int a, b;
    cin >> a >> b;
    --a;
    --b;
    G[a].emplace_back(b);
    G[b].emplace_back(a);
  }

  vector<int> Visit(N, 0);
  queue<int> fque;
  fque.emplace(0);
  Visit[0] = 1;
  queue<int> sque;
  sque.emplace(N - 1);
  Visit[N - 1] = 2;
  int root = N - 1;
  while (!fque.empty() && !sque.empty()) {
    int v;
    v = fque.front();
    fque.pop();
    for (auto nv : G[v]) {
      if (Visit[nv] == 1)
        continue;
      else if (Visit[nv] == 2) {
        root = nv;
        break;
      } else {
        Visit[nv] = 1;
        fque.emplace(nv);
      }
    }
    if (root != -1) break;

    v = sque.front();
    sque.pop();
    for (auto nv : G[v]) {
      if (Visit[nv] == 2)
        continue;
      else if (Visit[nv] == 1) {
        root = v;
        break;
      } else {
        Visit[nv] = 2;
        sque.emplace(nv);
      }
    }
    if (root != -1) break;
  }

  int count = 0;
  stack<int> sdfs;
  sdfs.emplace(root);
  Visit[root] = 1;
  while (!sdfs.empty()) {
    int v = sdfs.top();
    sdfs.pop();
    ++count;
    for (auto nv : G[v]) {
      if (Visit[nv] == 1) continue;
      Visit[nv] = 1;
      sdfs.emplace(nv);
    }
  }
  // cout << "root=" << root << " count=" << count << endl;
  if (count < (N - count))
    cout << "Fennec" << endl;
  else
    cout << "Snuke" << endl;
  return 0;
}

