        if (turn == 1) {
            int fcur, flag = 0;
            while (!fennec.empty()) {
                fcur = fennec.front();
                fennec.pop();
                if (!visited[fcur]) {
                    flag = 1;
                    break;
                }
            }
            if (flag == 0) {
                cout << "Snuke" << endl;
                break;
            }
            visited[fcur] = true;

            for (int i = 0; i < adjList[fcur].size(); ++i) {
                fennec.push(adjList[fcur][i]);
            }
        } else {
            int scur, flag = 0;
            while (!snuke.empty()) {
                scur = snuke.front();
                snuke.pop();
                if (!visited[scur]) {
                    flag = 1;
                    break;
                }
            }
            if (flag == 0) {
                cout << "Fennec" << endl;
                break;
            }
            visited[scur] = true;
            for (int i = 0; i < adjList[scur].size(); ++i) {
                snuke.push(adjList[scur][i]);
            }
        }
        turn *= -1;
    }
    return 0;
}

