        // if(d[i]==INF) cout << "INF" << endl;
        // else cout << d[i] << endl;
    }

    // 頂点rから頂点tまでの最短経路
    int t = V - 1;
    vector<int> pp = get_path(t);
    // for(int i:pp) cout << i << ' ';
    // cout << endl;

    int ps = pp.size();
    for(int i=1; i<ps; i++){
      cost[pp[i]][pp[i-1]] = INF;
