int dfs2(int now, int ng){
    used[now] = true;
    int ret = 0;
    for (int i = 0;i < G[now].size();i++){
        if(G[now][i] != ng && !used[G[now][i]]) ret += dfs2(G[now][i],ng);
    }
    used[now] = false;
    return ret+1;
}

