#define	MOD 1000000007

int	main() {
	int N;
	cin >>N;
	vector<vector<vector<int>>> node(N+1);
	for (int i=1; i<=N-1; i++) {
		int f;
		int t;
		cin >>f >>t;
		node.at(f).push_back({t, 1});
		node.at(t).push_back({f, 1});
	}
	vector<int> d1(N+1, INF);
	vector<bool> fixed(N+1, false);
	vector<int> q;
	int ixq;
	d1.at(1)=0;
	q.push_back(1);
	ixq=0;
	while(N!=ixq) {
		int f=q.at(ixq);
		fixed.at(f)=true;
		for (int i=0; i<node.at(f).size(); i++) {
			int t=node.at(f).at(i).at(0);
			int dd=node.at(f).at(i).at(1);
			if (!fixed.at(t)) {
				d1.at(t)=d1.at(f)+dd;
				q.push_back(t);
			}
		}
		ixq++;
	}
	vector<int> d2(N+1, INF);
	for (int i=0; i<fixed.size(); i++)
		fixed.at(i)=false;
	q.erase(q.begin(), q.end());
	d2.at(N)=0;
	q.push_back(N);
	ixq=0;
	while(N!=ixq) {
		int f=q.at(ixq);
		fixed.at(f)=true;
		for (int i=0; i<node.at(f).size(); i++) {
			int t=node.at(f).at(i).at(0);
			int dd=node.at(f).at(i).at(1);
			if (!fixed.at(t)) {
				d2.at(t)=d2.at(f)+dd;
				q.push_back(t);
			}
		}
		ixq++;
	}
	int f=0;
	int s=0;
	for (int i=1; i<=N; i++)
		if (d1.at(i)<=d2.at(i))
			f++;
		else
			s++;
	if (f>s)
		cout <<"Fennec" <<endl;
	else
		cout <<"Snuke" <<endl;
	return 0;
}

