            if(lsu < level) break;
            su.pop();
            ssu++;
            for(int i = 0; i < L[v].size(); i++){
                int next = L[v][i];
                if(isvisit[next]) continue;
                isvisit[next] = true;
                su.push(make_pair(next, lsu+1));
            }
        }
        lfe++;
        lsu++;
    }
    //printf("sfe:%d, ssu:%d\n", sfe, ssu);

    if(sfe <= ssu){
        cout << "Snuke" << endl;
    }
    else{
        cout << "Fennec" << endl;
    }
    return 0;

}

