#define REP(i, n) for(int (i)=0;(i)<(n);++(i))
#define MOD 1000000007

typedef long long ll;

using namespace std;

void calcDist(vector<int> *g, int st, int *dist, int currentDist, bool *visited)
{
    dist[st] = currentDist;
    visited[st] = true;
    currentDist++;
    for (int i = 0; i < g[st].size(); ++i)
    {
        int node = g[st][i];
        if(!visited[node])
        {
            calcDist(g, node, dist, currentDist, visited);
        }
    }
}

int main()
{
    int N;
    cin >> N;
    vector<int> G[N];
    REP(i, N - 1)
    {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    // マス1, N からそれぞれのマスへの距離を計算
    int distF[N] = {0}, distS[N] = {0};
    bool visitedF[N] = {false}, visitedS[N] = {false};
    // マス1からの距離
    int st = 0;
    int dist = 0;
    calcDist(G, st, distF, dist, visitedF);

    // マスN からの距離
    st = N - 1;
    dist = 0;
    calcDist(G, st, distS, dist, visitedS);

    // マス1からの方が近いマスの数と、マスN からの方が近い点を数える
    int countF = 0, countS = 0;
    REP(i, N)
    {
        if(distF[i] <= distS[i])
        {
            countF++;
        }
        else
        {
            countS++;
        }
    }

    if (countF > countS)
    {
        cout << "Fennec" << endl;
    }
    else
    {
        cout << "Snuke" << endl;
    }

}

