struct edge{
    int to;
    int cost;
};
int dist[100010];
int area[100010];
vector<edge>graph[100010];
vector<int>e;
vector<int>ans;
int n;

void dfs(int s,int r){
    for(int i=0;i<(int)graph[s].size();i++){
        int next=graph[s][i].to;
        if(r==next)continue;
        if(area[next]==1) continue;
        if(area[next]==-1){
            area[next]=0;
            dfs(next,s);
        }
        if(area[next]==0){
            dfs(next,s);
        }
    }
    return;
}

void solve(int s,int g){
    for(int i=0;i<n;i++){
        dist[i]=1000000;
        area[i]=-1;
    }
    dist[0]=0;
    e.push_back(0);
    queue<P>que;
    que.push(P(s,e));
    while(!que.empty()){
        bool flag=false;
        P p=que.front();
        que.pop();
        int now=p.first;
        for(int i=0;i<(int)graph[now].size();i++){
            int next=graph[now][i].to;
            int c=graph[now][i].cost;
            if(dist[next]>dist[now]+c){
                dist[next]=dist[now]+c;
                vector<int> k=p.second;
                k.push_back(next);
                if(next==g){
                    ans=k;
                    flag=true;
                    break;
                }
                else{
                    que.push(P(next,k));
                }
            }
        }
        if(flag)break;
    }
    for(int i=0;i<(int)ans.size();i++){
        if(((int)ans.size()%2==0)){
            if(i<((int)ans.size()/2))area[ans[i]]=0;
            else area[ans[i]]=1;
        }
        else{
            if(i<=((int)ans.size()/2))area[ans[i]]=0;
            else area[ans[i]]=1;
        }
    }
    dfs(0,0);
    int value=0;
    for(int i=0;i<n;i++){
        if(area[i]==0)value++;
    }
    if(value==n-value){
        cout<<"Snuke"<<endl;
    }
    else{
        if(value>n-value)cout<<"Fennec"<<endl;
        else cout<<"Snuke"<<endl;
    }
    return;
}

int main(void){
    int a,b;
    cin>>n;
    for(int i=0;i<n-1;i++){
        cin>>a>>b;
        a--;
        b--;
        graph[a].push_back({b,1});
        graph[b].push_back({a,1});
    }
    solve(0,n-1);
    return 0;
}

