#define rALL(c) (c).rbegin(), (c).rend()
ll INF = 1e18;

struct edge {
  ll to, cost;
  edge(ll t, ll c) : to(t), cost(c) {}
};

class Dijkstra {
 public:
  ll n_;
  vector<vector<edge>> G_;
  vl d_;
  vl prev_;

 public:
  Dijkstra(ll n) : n_(n), G_(n), d_(n, INF), prev_(n, -1) {}
  void addEdge(ll v, ll to, ll cost) { G_[v].push_back(edge(to, cost)); }
  void exec(ll s) {
    priority_queue<pll, vector<pll>, greater<pll>> que;
    d_[s] = 0;
    que.push({0, s});

    while (!que.empty()) {
      pll p = que.top();
      que.pop();
      ll v = p.second;
      if (d_[v] < p.first) continue;
      for (auto& e : G_[v]) {
        if (d_[e.to] > d_[v] + e.cost) {
          d_[e.to] = d_[v] + e.cost;
          prev_[e.to] = v;
          que.push({d_[e.to], e.to});
        }
      }
    }
  }
  ll dist(ll g) { return d_[g]; }
  ll prev(ll v) { return prev_[v]; }
};

int main() {
  //
  ll n;
  cin >> n;
  Dijkstra g(n);
  rep(i, n - 1) {
    ll a, b;
    cin >> a >> b;
    a--, b--;
    g.addEdge(a, b, 1);
    g.addEdge(b, a, 1);
  }
  // cout << g.G_[0].size() << endl;
  g.exec(0);
  ll dist = g.dist(n - 1);
  // cout << dist << endl;
  ll v = n - 1;
  vl color(n, -1);
  vl path;
  path.emplace_back(n - 1);
  while (v > 0) {
    v = g.prev(v);
    path.emplace_back(v);
  }
  reverse(ALL(path));
  rep(i, path.size()) {
    if (i <= (path.size() - 1) / 2) {
      color[path[i]] = 0;
    } else {
      color[path[i]] = 1;
    }
  }
  // rep(i, n) { cout << color[i] << endl; }
  queue<ll> que;
  rep(i, n) {
    if (color[i] == 0) {
      que.push(i);
    }
  }
  // cout << que.size() << endl;
  while (!que.empty()) {
    ll v = que.front();
    que.pop();
    for (auto& e : g.G_[v]) {
      ll to = e.to;
      if (color[to] == -1) {
        // cout << to << endl;
        color[to] = 0;
        que.push(to);
      }
    }
  }
  ll cnt0 = 0;
  rep(i, n) {
    if (color[i] == 0) {
      cnt0++;
    }
  }
  cout << cnt0 << endl;
  if (cnt0 > (n - cnt0)) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }
  return 0;
}

