int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int n; cin>>n;
  vector<int> graph[n];
  for (int i = 0; i < n-1; i++) {
    int a,b; cin>>a>>b; a--; b--;
    graph[a].push_back(b);
    graph[b].push_back(a);
  }
  vector<int> dist(n);
  vector<int> path;
  auto set_dist = [&graph, &dist, n, &path](auto& f, int s, int p, int d) -> bool {
    dist[s] = d;
    bool leached = s == n-1;
    for (auto t:graph[s]) {
      if (t == p) continue;
      leached |= f(f, t, s, d+1);
    }
    if (leached)
      path.push_back(s);
    return leached;
  };
  set_dist(set_dist, 0, -1, 0);
  reverse(path.begin(), path.end());
  vector<int> color(n, -1);
  for (int i = 0; i < (path.size()+1)/2; i++) {
    color[path[i]] = 0;
  }
  for (int i = path.size()-1; i >= (path.size()+1)/2; i--) {
    color[path[i]] = 1;
  }
  auto set_color = [&color, &graph](auto& f, int s, int p, int c) -> void {
    color[s] = c;
    for (auto t:graph[s]) {
      if (t == p) continue;
      if (color[t] == -1) {
        f(f, t, s, c);
      }
    }
  };
  for (auto p:path) {
    set_color(set_color, p, -1, color[p]);
  }
  int bs = 0, ws = 0;
  for (auto c:color) {
    if (c == 0)
      bs++;
    else
      ws++;
    assert(c != -1);
  }
  cout << (bs > ws ? "Fennec" : "Snuke") << endl;

  return 0;
}

