pair<ll, ll> dfs1(const vector<vector<ll>> &G, ll v, ll count) {
    seen[v] = true; // v を訪問済にする
    count++;
    // v から行ける各頂点 next_v について
    for (auto next_v : G[v]) {
    	if (next_v == 0) {
    		continue;
    	}
        if (seen[next_v]) {
        	continue;
        } // next_v が探索済だったらスルー
        if (next_v == G.size()-1){
        	return make_pair(count, 1);
        }
        return dfs1(G, next_v, count); // 再帰的に探索
    }
    return make_pair(count, 0);
}
