void recur(int player,int fd,int sd)
{
	if (f[fd].size() == 0 && s[sd].size() == 0) return;
	if(player == 1 && f[fd].size() > 0){
		for (int i = 0; i < f[fd].size(); i++)
		{
			int from = f[fd][i];
			for (int j = 0; j < tree[from].size(); j++)
			{
				int to = tree[from][j];
				if (used[to] == -1) {
					used[to] = 1;
					f[fd + 1].push_back(to);
				} 
			}
		}
		fd++;
	}
	else if(player == -1 && s[sd].size() > 0){
		for (int i = 0; i < s[sd].size(); i++)
		{
			int from = s[sd][i];
			for (int j = 0; j < tree[from].size(); j++)
			{
				int to = tree[from][j];
				if (used[to] == -1) {
					used[to] = 2;
					s[sd + 1].push_back(to);
				}
			}
		}
		sd++;
	}
	recur(-player, fd, sd);
}
void FennecVSSnuke(){

	cin >> n;
	for (size_t i = 1; i <= n; i++)
	{
		used[i] = -1;
	}
	for (size_t i = 1; i < n; i++)
	{
		int a, b;
		cin >> a >> b;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}

	used[1] = 1;
	used[n] = 2;
	f[0].push_back(1);
	s[0].push_back(n);
	recur(1, 0, 0);
	int count = 0;
	for (size_t i = 1; i <= n; i++)
	{
		count += (used[i] == 1);
	}
	int fne = count;
	int snu = n - fne;
	if (fne > snu) {
		cout << "Fennec" << endl;
	}
	else {
		cout << "Snuke" << endl;
	}
}

