void dfs(int here, int col)
{
	colour[here] = col;
	visited[here] = true;
	for(auto there : adj[here])
		if((colour[there] == -1 || colour[there] == col) 
		&& !visited[there])
			dfs(there, col);
}

const int INF = (int)1e9;
void bfs(int start, VI& parent, VI& dist)
{
	parent = VI(n, -1);
	dist = VI(n, INF);
	queue<int> q;

	dist[start] = 0;
	parent[start] = start;
	q.push(start);

	while(q.empty() == false)
	{
		int here = q.front();
		q.pop();

		for(int there : adj[here])
		{
			if(parent[there] == -1)
			{
				parent[there] = here;
				dist[there] = dist[here] + 1;
				q.push(there);
			}
		}
	}
}

bool FennecWins()
{
	VI parent, dist;
	bfs(0, parent, dist);

	int dest = n - 1;
	VI order(1, dest);
	while(parent[dest] != dest)
	{
		dest = parent[dest];
		order.emplace_back(dest);
	} 

	reverse(ALL(order));

	colour.assign(n, -1);
	colour[0] = 0, colour[n - 1] = 1;
	for(int i = 0, j = sz(order) - 1; i <= j; ++i, --j)
	{
		colour[order[i]] = 0;
		if(colour[order[j]] == -1)
			colour[order[j]] = 1;
	}

	visited = VB(n, false);
	dfs(0, 0);
	visited = VB(n, false);
	dfs(n - 1, 1);

	int fennec = 0, snuke = 0;
	for(int col : colour)
	{
		fennec += col == 0;
		snuke += col == 1;
	}

	assert(snuke + fennec == n);
	return snuke < fennec;
}

