//--------------------------------------//
int N;
vector<int> G[100000];

int d[100000];
int pre[100000];
void solve(){
	queue<int> q;
	q.push(0);
	reps(i, N - 1){
		d[i] = INF;
	}
	while(!q.empty()){
		int n = q.front(); q.pop();
		rep(i, G[n].size()){
			int to = G[n][i];
			if(d[to] > d[n] + 1){
				d[to] = d[n] + 1;
				pre[to] = n;
				q.push(to);
			}
		}
	}
	int cost = (d[N - 1] - 1) / 2;
	int lim = N - 1;
	while(cost--){
		lim = pre[lim];
	}
	q.push(0);
	reps(i, N - 1){
		d[i] = INF;
	}
	int cnt = 1;
	while(!q.empty()){
		int n = q.front(); q.pop();
		rep(i, G[n].size()){
			int to = G[n][i];
			if(to == lim) continue;
			if(d[to] > d[n] + 1){
				d[to] = d[n] + 1;
				cnt++;
				q.push(to);
			}
		}
	}
	if(2 * cnt >= N)
		cout<<"Fennec"<<endl;
	else
		cout<<"Snuke"<<endl;
}

