template <typename T> // T: type of cost
struct base_tree
{
    int n;
    vector<vector<int>> to; // edge
    vector<vector<T>> co;   // cost
    vector<T> cost1;        // cost
    vector<T> cost2;        // cost
    base_tree(int n) : n(n), to(n), co(n), cost1(n), cost2(n)
    {
        rep(i, n)
        {
            cost1[i] = -1;
            cost2[i] = -1;
        }
    }

    void addEdge(int a, int b, T c = 0)
    {
        to[a].push_back(b);
        co[a].push_back(c);
        to[b].push_back(a);
        co[b].push_back(c);
    }
    void dfs(int v, vector<T> &cost, int d = 0)
    {
        for (int i = 0; i < to[v].size(); ++i)
        {
            int u = to[v][i];
            if (cost[u] >= 0)
                continue;
            cost[u] = d;
            dfs(u, cost, d + 1);
        }
    }
    void run()
    {
        cost1[1] = 0;
        dfs(1, cost1);
        cost2[n - 1] = 0;
        dfs(n - 1, cost2);
    }
};

