int INF = INT_MAX/2;

// 頂点sから各頂点の最短距離を求める
void dijkstra(int start){

    fill(d, d+V, INF);
    fill(used, used+V, false);
    fill(pre, pre+V, -1);
    d[start]=0;

    while(true){
        int v = -1;
        for(int u=0;u<V;u++){
            if(!used[u] and (v==-1 or d[u]<d[v])) v=u;
        }
        if(v==-1)break;
        used[v]=true;

        for(int u=0; u<V;u++){
            if(d[u] > d[v]+cost[v][u]) {
                d[u] = d[v]+cost[v][u];
                pre[u] = v;
            }
        }
    }
}

// 頂点tへの最短路
vector<int> get_path(int t){
    vector<int> path;
    for(;t!=-1;t=pre[t])path.push_back(t); // tがsになるまでprev[t]を辿っていく
    // このままだとt->sの順になっているので逆順にする
    reverse(path.begin(),path.end());
    return path;
}


