vector<int> bfs(vector<vector<int>> &G, int start) {
    int n = (int)G.size();
    vector<int> res(n);

    queue<int> que;
    vector<bool> visited(n, false);
    que.push(start);
    visited[start] = true;
    while (!que.empty()) {
        int u = que.front(); que.pop();
        for (int v : G[u]) {
            if (visited[v]) continue;
            visited[v] = true;
            res[v] = res[u] + 1;
            que.push(v);
        }
    }

    return res;
}

