using namespace std;
typedef int64_t ll;
typedef vector<ll> vll;
struct UnionFind {
    static const int MAX_N = 100005;
    int par[MAX_N]; // 親
    int rank[MAX_N]; // 木の深さ
    UnionFind() {
    }
    // n要素で初期化
    void init(int n) {
        for (int i = 0; i < n; i++) {
            par[i] = i;
            rank[i] = 0;
        }
    }
    // 木の根を求める
    int find(int x) {
        if (par[x] == x) {
            return x;
        }
        else {
            return par[x] = find(par[x]);
        }
    }
    // xとyの属する集合を併合
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) {
            return;
        }
        if (rank[x] < rank[y]) {
            par[x] = y;
        }
        else {
            par[y] = x;
            if (rank[x] == rank[y]) {
                rank[x]++;
            }
        }
    }
    // xとyが同じ集合に属するか否か
    bool same(int x, int y) {
        return find(x) == find(y);
    }
};
UnionFind uf;
struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll N;
        in >> N;
        vll a(N), b(N);
        uf.init(N);
        rep (i, N) {
            in >> a[i] >> b[i];
            if (a[i] != 1 && b[i] != N) {
                uf.unite(a[i], b[i]);
            }
            else if (a[i] == 1 || b[i] == 1) {
                if (!uf.same(N, a[i]) && !uf.same(N, b[i])) {
                    uf.unite(a[i], b[i]);
                }
            }
            else if (a[i] == N || b[i] == N){
                if (!uf.same(1, a[i]) && !uf.same(1, b[i])) {
                    uf.unite(a[i], b[i]);
                }
            }
        }
        ll fe = 0, su = 0;
        reu(i, 2, N) {
            fe += uf.same(1, i);
            su += uf.same(N, i);
        }
        out << (fe >= su ? "Fennec" : "Snuke") << endl;
    }
};
void solve(std::istream& in, std::ostream& out)
{
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
