    ki[b].push_back(a);
  }
  vector<int>cnt(N,INF);
  queue<int>que;
  que.push(0);
  cnt[0] = 0;
  vector<int>road;
  while(!que.empty()) {
    int x = que.front();
    que.pop();
    for(int i = 0; i < (int)ki[x].size(); i++) {
      if(cnt[ki[x][i]] == INF) {
        cnt[ki[x][i]] = cnt[x]+1;
        que.push(ki[x][i]);
      }
    }
  }
  que.push(N-1);
  while(!que.empty()) {
    int x = que.front();
    que.pop();
    for(int i = 0; i < (int)ki[x].size(); i++) {
      if(cnt[ki[x][i]] == cnt[x]-1) {
        road.push_back(ki[x][i]);
        que.push(ki[x][i]);
      }
    }
  }
  int now = 0;
  vector<bool>used(N,false);
  used[0] = true;
  for(int i = 0; i < ((int)road.size()+1/2)-1; i++) {
    for(int j = 0; j < (int)ki[now].size(); j++) {
      queue<int>que;
