void build(int x,int y){
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
}

void dfs(int x,int fa,int deep){
	int dt = last[x];
	while(dt != -1){
		int dr = other[dt];
		if(dr != fa){
			if(dr == n) ans = deep;
			father[dr] = x;
			dfs(dr,x,deep + 1);
			d[x] += d[dr] + 1;
		}
		dt = pre[dt];
	}
}

