    while (!q.empty()) {
        auto f = q.front(); q.pop();
        int cur = f.first;
        int count = f.second;
        c[cur] = count;
        for (int v : bitree[cur]) {
            if (!reached[v]) {
                q.push({v, count + 1});
                reached[v] = true;
            }
        }
    }
}

