    else if ('0' <= c && c <= '9')  x = c - '0';

    while (true)
    {
        c = getchar_unlocked();

        if (c < '0' || c > '9') break;
        x = x * 10 + (c - '0');
    }

    if (s) x = -x;
}

struct edge
{
    // 頂点 最短時間
    int a;
    int cost;

    edge() {};
    edge(int a, int cost)
        : a(a), cost(cost) {}

    bool operator> (const edge &edge) const
    {
        return cost > edge.cost;
    }
};

// 道情報 行き 配列
vector< vector<edge> > goList;

// 所要時間 行き 配列
vector<int> goAry;

// 行ったことある、ない
vector<bool> gone;

void bfs(int start)
{
    queue<edge> que;

    // スタート地点をキューに入れる
    que.push(edge(start, 0));

    // 距離を0にする
    goAry[start] = 0;

    // 行ったことがある
    gone[start] = true;

    while (que.size())
    {
        edge q = que.front();
        que.pop();

        for (int i = 0; i < (signed)goList[q.a].size(); i++)
        {
            edge e = goList[q.a][i];

            // 行ったことがない
            if (gone[e.a] == false)
            {
                goAry[e.a] = goAry[q.a] + e.cost;
                // push 頂点 時間
                que.push(edge(e.a, goAry[e.a]));
                // 行ったことがある
                gone[e.a] = true;
            }
        }
    }
}

int main()
{
    const char *Fennec = "Fennec";
    const char *Snuke = "Snuke";

    int N;
    if (scanf("%d", &N) < 1) return 0;

    goList.resize(N);

    for (int i = 0; i < N - 1; i++)
    {
        int a, b;

        gc(a);

        gc(b);

        // 0-indexed
        a--;
        b--;

        goList[a].push_back(edge(b, 1));
        goList[b].push_back(edge(a, 1));
    }

    goAry.resize(N);
    gone.resize(N);

    for (int i = 0; i < N; i++)
    {
        // 初期化
        goAry[i] = 0;
        // 行ったことがない
        gone[i] = false;
    }

    // 幅優先探索 Breadth-First Search
    bfs(0);

    vector<int> tmp;
    copy(goAry.begin(), goAry.end(), back_inserter(tmp));

    for (int i = 0; i < N; i++)
    {
        // 初期化
        goAry[i] = 0;
        // 行ったことがない
        gone[i] = false;
    }

    bfs(N - 1);

    int first = 0;
    int second = 0;
    for (int i = 0; i < N; i++)
    {
        if (tmp[i] < goAry[i]) first++;
        else second++;
    }

    printf("%s\n", first < second ? Snuke : Fennec);
    return 0;
}

