    }
    dfs(0, -1);
    reverse(g.begin(), g.end());
    for (int i = 0; i < g.size(); ++i) {
        mx1[i] = d1[g[i]] + d3[g[i]];
        int x = g[g.size() - 1 - i];
        mx2[i] = d2[x] + d3[x];
        if (i) {
            mx1[i] = max(mx1[i], mx1[i - 1]);
        }
        if (x != g.size() - 1) {
            mx2[x] = max(mx2[x], mx2[x + 1]);
        }
    }
    //for (int i = 0;)
    int x = 0, y = g.size() - 1;
    bool win = 1 - g.size() % 2, turn = 0;
    t1.build(1, d1, d2, 0, g.size() - 1);
    t2.build(1, d3, d2, 0, g.size() - 1);
    while (x != y) {
        if (!turn) {
            if (d3[g[x]] > t2.get(1, 0, g.size() - 1, x + 1, y) - d2[g[y]]) {
                write(0);
                return 0;
            }
            x++;
