            if (d3[g[y]] > t1.get(1, 0, g.size() - 1, x, y - 1) - d1[g[x]]) {
                write(1);
                return 0;
            }
            y--;
        }
        turn = 1 - turn;
    }
    if (turn) {
        write(1);
    } else write(0);
    return 0;
}

