void add_edge(int u, int v) {
  G[u].push_back(v);
  G[v].push_back(u);
}

bool dfs(int p, int v, int dest) {
  if (v == dest) {
    path.push_back(v);
    return true;
  }
  for (int u : G[v]) {
    if (u == p) continue;
    if (dfs(v, u, dest)) {
      path.push_back(v);
      return true;
    }
  }
  return false;
}

void dfs2(int p, int v, int c) {
  if (color[v] * c < 0) return;
  color[v] = c;
  if (c > 0) vf++;
  else vs++;
  for (int u : G[v]) {
    if (u == p) continue;
    dfs2(v, u, c);
  }
}

