  dfs(-1, N - 1, 0);
  // DUMP(path, path.size());
  bool sen = true;
  int s = 0;
  int t = path.size() - 1;
  while (s <= t) {
    if (sen) {
      color[path[s++]] = 1;
    } else {
      color[path[t--]] = -1;
    }
    sen = !sen;
  }
  dfs2(-1, 0, 1);
  dfs2(-1, N - 1, -1);
  // DUMP(color, N);
  puts(vf > vs ? "Fennec" : "Snuke");
}

