    a--; b--;
    edge[a].eb(b);
    edge[b].eb(a);
  }

  int dist = dfs1(0, 0, N - 1, 0);

  board[0] = 1;
  board[N - 1] = 2;
  dfs2(0, 0, 1, 0, dist / 2);
  dfs2(N - 1, N - 1, 2, 0, dist / 2);
  dfs2(0, 0, 1, 0, INF);
  dfs2(N - 1, N - 1, 2, 0, INF);

  int cnt1 = 0, cnt2 = 0;
  rep (i, N) {
    if (board[i] == 1) cnt1++;
    if (board[i] == 2) cnt2++;
  }

