queue<int> s_bfs(queue<int> q_v) {
    queue<int> next_v;
    while (!q_v.empty()) {
        int v = q_v.front();
        q_v.pop();
        rep(i, G[v].size()) {
            if (!f_seen[G[v][i]] && !s_seen[G[v][i]]) {
                next_v.push(G[v][i]);
