struct edge{int to; ll cost;};
int N;
vector<edge> G1[100001], G2[100001];
int dist1[100001], dist2[100001];

void F_Dijkstra(int s) {
	priority_queue<P, vector<P>, greater<P> > que;
	fill(dist1, dist1 + N, INF);
	dist1[0] = 0;
	que.push(P(0, s));

	while(!que.empty()) {
		P p = que.top(); que.pop();
		int v = p.second;
		if(dist1[v] < p.first) continue;
		for(int i = 0; i < G1[v].size(); ++i) {
			edge e = G1[v][i];
			if(dist1[e.to] > dist1[v] + e.cost) {
				dist1[e.to] = dist1[v] + e.cost;
				que.push(P(dist1[e.to], e.to));
			}
		}
	}
}

void S_Dijkstra(int s) {
	priority_queue<P, vector<P>, greater<P> > que;
	fill(dist2, dist2 + N, INF);
	dist2[0] = 0;
	que.push(P(0, s));

	while(!que.empty()) {
		P p = que.top(); que.pop();
		int v = p.second;
		if(dist2[v] < p.first) continue;
		for(int i = 0; i < G2[v].size(); ++i) {
			edge e = G2[v][i];
			if(dist2[e.to] > dist2[v] + e.cost) {
				dist2[e.to] = dist2[v] + e.cost;
				que.push(P(dist2[e.to], e.to));
			}
		}
	}
}

int main() {
	scanf("%d", &N);
	rep(i, N - 1) {
		int a, b;
		scanf("%d %d", &a, &b);
		--a, --b;
		G1[a].push_back((edge){b, 1});
		G1[b].push_back((edge){a, 1});
		a = N - 1 - a; b = N - 1 - b;
		G2[a].push_back((edge){b, 1});
		G2[b].push_back((edge){a, 1});
	}
	F_Dijkstra(0);
	S_Dijkstra(0);
	int fennec = 0, snuke = 0;
	rep(i, N) {
		(dist1[i] <= dist2[N - 1 - i]) ? fennec++ : snuke++;
	}
	(fennec > snuke) ? printf("Fennec\n") : printf("Snuke\n");
	return 0;
}

