using namespace std;
typedef std::vector<std::vector<int>> graph;

bool isPath[100000] = {};
int n;

int dfs(int s, int parent, int length, const graph &g) {
  length++;
  if (s == n - 1) {
    return length;
  }
  isPath[s] = true;
  for (auto v : g[s]) {
    if (v == parent)
      continue;
    isPath[v] = true;
    int len = dfs(v, s, length, g);
    if (len != -1)
      return len;
    isPath[v] = false;
  }
  return -1;
}

int dfs2(int s, int parent, int res, const graph &g) {
  if (isPath[s] && res <= 0)
    return 0;
  if (isPath[s])
    res--;

  int val = 1;
  for (auto v : g[s]) {
    if (v == parent)
      continue;
    val += dfs2(v, s, res, g);
  }
  return val;
}

int main() {
  cin >> n;
  graph g(n);
  REP(i, n - 1) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  int len = dfs(0, -1, 0, g);
  isPath[0] = false;
  int ans = dfs2(0, -1, (len - 1) / 2, g);
  if (2 * ans > n) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }
}

