string bfs(int n)
{
    queue<int>f;
    f.push(1);
    lvl[1]=1;
    par[1]=-1;
    string ans;
    while(1)
    {
        int top=f.front();
        f.pop();
        if(top==n)break;
        for(int i=0;i<adj[top].size();i++)
        {
            int chi=adj[top][i];
            if(lvl[chi]==0)
            {
                par[chi]=top;
                lvl[chi]=lvl[top]+1;
                f.push(chi);
            }
        }
    }
    int a=(lvl[n]+1)/2+1;
    int x=n;
    while(par[x]!=-1)
    {
        if(lvl[x]==a)
        {
            vis[x]=2;
            break;
        }
        x=par[x];
    }
    queue<int>q;
    q.push(1);
    vis[1]=1;
    while(!q.empty())
    {
        int top=q.front();
        q.pop();
        for(int i=0;i<adj[top].size();i++)
        {
            int chi=adj[top][i];
            if(vis[chi]==0)
            {
                vis[chi]=1;
                q.push(chi);
            }
        }
    }
    int cnt=0;
    for(int i=1;i<=n;i++)
        if(vis[i]==1)cnt++;
    if(cnt>n-cnt)ans="Fennec";
    else ans="Snuke";
