ll N;
ll len=0;
ll total=0;

vector<bool> seen;  // 訪問済みの点
vector<bool> seen2;  // 訪問済みの点

// BFSのための再帰関数
void dfs(const Graph &G, int v, int counter) {
    seen[v] = true;
    for (auto next_v : G[v]) { 
        if (seen[next_v]) continue;
        if(next_v == N-1){
            len = counter+1;
            continue; // N-1のノードに達したら終了
        }
        dfs(G, next_v, counter+1); // 再帰的に値を追加していく
    }
}

// BFSのための再帰関数
void dfs2(const Graph &G, int v, int counter) {
    seen2[v] = true;
    for (auto next_v : G[v]) { 
        if(seen2[next_v]) continue;
        if((len-1)/2 == counter) continue;
        dfs2(G, next_v, counter+1); // 再帰的に値を追加していく
    }
}

// BFSのための再帰関数
void dfs3(const Graph &G, int v, int counter) {
    total++;
    seen2[v] = true;
    for (auto next_v : G[v]) { 
        if(seen2[next_v]) continue;
        dfs3(G, next_v, counter+1); // 再帰的に値を追加していく
    }
}

