int main() {
  int n;
  cin >> n;
  vector<vector<int>> T(n);
  for (int i = 0; i < n - 1; i++) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    T[a].push_back(b);
    T[b].push_back(a);
  }

  vector<int> color(n);
  queue<pair<int, int>> Qb, Qw;
  Qb.push({0, 0});
  Qw.push({n - 1, 0});

  int black = 1, white = 1;
  int cost = 0;

  while (!Qb.empty() || !Qw.empty()) {
    while (!Qb.empty() && Qb.front().second == cost) {
      int x = Qb.front().first;
      Qb.pop();

      if (color[x] == -1) continue;

      color[x] = 1;
      black++;
      for (auto node: T[x]) {
        if (color[node] == 0) {
          Qb.push({node, cost + 1});
        }
      }
    }

    while(!Qw.empty() && Qw.front().second == cost) {
      int x = Qw.front().first;
      Qw.pop();

      if (color[x] == 1) continue;

      color[x] = -1;
      white++;
      for (auto node: T[x]) {
        if (color[node] == 0) {
          Qw.push({node, cost + 1});
        }
      }
    }
    cost++;
  }

  if (black > white) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;

  return 0;
}

