int dfs(int x, int level){
  if(c[x] == 2){ 
    final_level = level;
    return 1;
  }
  int res = 0;
  for(auto nxt: Edge[x]){
    if(visit(nxt)) continue;
    v[nxt] = V;
    res += dfs(nxt, level+1);
  }
  if(res == 1){
    c[x] = (level>(final_level/2))?2:1;
  }
  return res;
}

