vector<int> bfs(vector<vector<int>> &G, int s) {
	vector<bool> used(N);
	vector<int> d(N);
	queue<pi> q;

	d[s] = 0;
	used[s] = true;
	q.push({s,0});

	while (!q.empty()) {
		int cx = q.front().first;
		int ct = q.front().second;
		q.pop();
		used[cx] = true;
		d[cx] = ct;

		for (int i = 0; i < G[cx].size(); i++) {
			int nx = G[cx][i];
			if (!used[nx])
				q.push({nx,ct+1});
		}
	}
	return d;
}

