	void solve(std::istream& in, std::ostream& out) {
        int n, a, b;
        in >> n;
        vector<int> g[100010];
        rep(i, n-1){
            in >> a >> b;
            a--; b--;
            g[a].push_back(b);
            g[b].push_back(a);
        }

        vector<int> fennec(n, 1e6);

        queue<int> q;
        q.push(0);
        int cnt = 0;
        fennec[0] = 0;
        while(!q.empty()){
            int u = q.front(); q.pop();
            ++cnt;
            for(auto const& e : g[u]){
                if(fennec[e] != 1e6 || e == n-1) continue;
                fennec[e] = cnt;
                q.push(e);
            }
        }

        q.push(n-1);
        cnt = 0;
        vector<int> snuke(n, 1e6);
        snuke[n-1] = 0;
        while(!q.empty()){
            int u = q.front(); q.pop();
            ++cnt;
            for(auto const& e : g[u]){
                if(snuke[e] != 1e6 || e == 0) continue;
                snuke[e] = cnt;
                q.push(e);
            }
        }

        int res = 0;
        bool eq_flg = true;
        int eq = 0;
