int solve(void)
{
	int a, b;
	fill(color, color + 100001, 0);
	while (1)
	{
		bool flag = false;
		while (s1.size() != 0)
		{
			a = s1.front();
			if (color[a] == 0)
			{
				flag = true;
				color[a] = 1;
				s1.pop();
				break;
			}
			s1.pop();
		}

		if (flag == false)
		{
			return 2;
		}

		flag = false;
		while (s2.size() != 0)
		{
			b = s2.front();
			if (color[b] == 0)
			{
				flag = true;
				color[b] = 2;
				s2.pop();
				break;
			}
			s2.pop();
		}

		if (flag == false)
		{
			return 1;
		}
		for (int i = 0; i < adj[a].size(); i++)
		{
			if (color[adj[a][i]] == 0)
			{
				s1.push(adj[a][i]);
			}
		}

		for (int i = 0; i < adj[b].size(); i++)
		{
			if (color[adj[b][i]] == 0)
			{
				s2.push(adj[b][i]);
			}
		}

		if (s1.size() == 0 || s2.size() == 0)
		{
			break;
		}
	}

	if (s1.size() == 0)
	{
		return 2;
	}

	return 1;
}

