	function<void(int, int, int, const VVI&, VL&) > dfs = [&](int v, int p, int d, const VVI& G, VL &dist) {
		dist[v] = d;
		for (auto nx : G[v]) {
			if (nx == p)continue;
			dfs(nx, v, d + 1, G, dist);
		}
	};
	dfs(0, -1, 0, G, dist0);
	dfs(N - 1, 0, -1, G, distN);
	LL ans = 0;
	FOR(i, 0, N) {
		if (dist0[i] < distN[i])ans++;
		else ans--;
	}
	cout << (ans > 0 ? "Fennec" : "Snuke") << endl;

	return 0;
}

