int d[100000]; //S→Gのcost
int preva[100000];
bool used[100000];
priority_queue<P> que;
int path;
bool use[100000];

void dijkstra(int s){
	fill(d,d+100000,INF);
	fill(used,used+100000,false);
	d[s]=0;
	que.push(P(s,0));

	while(!que.empty()){

		int Rto=que.top().first, Rcost=que.top().second; //中継点(Relay),S→Rのcost
		que.pop();
		if(used[Rto]) continue;
		if(Rcost > d[Rto]) continue;
		used[Rto]=true;

		for(int i=0;i<table[Rto].size();i++){
			int to=table[Rto][i].first, cost=table[Rto][i].second; //目的地(G),R→Gのcost
			if(d[to] > cost + Rcost){
				d[to] = cost + Rcost;
				que.push( P(to,d[to]) );
				preva[to]=Rto;
			}
		}

	}
}

int dfs(int s){
	int res=0;
	for(int i=0;i<table[s].size();i++){
		if(use[table[s][i].first]) continue;
		use[table[s][i].first]=true;
		res++;
		res+=dfs(table[s][i].first);
	}
	return res;
}

