const int maxn = 2e5 + 5;
int father[maxn],other[maxn],pre[maxn],last[maxn],d[maxn];
int all = -1,ans = 0,n;

void build(int x,int y){
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
}

int dfs(int x,int fa,int deep){
	int dt = last[x];
	int res = 0;
	while(dt != -1){
		int dr = other[dt];
		if(dr != fa){
			if(dr == n) ans = deep;
			father[dr] = x;
			res++;
			res += dfs(dr,x,deep + 1);
			d[x] = res;
			//d[x] += d[dr] + 1;
		}
		dt = pre[dt];
	}
	return res;
}

