struct edge{ int to, cost;};
typedef pair<int,int> P;//firstは最短距離,secondが頂点の番号

int V;
vector<edge> G[MAX_V];
int d[MAX_V];
int Prev[MAX_V];

void dijkstra(int s){
    //greater<P>によって、firstが小さい順に取り出せるようになる
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d + V, INF);
    fill(Prev, Prev + V, -1);
    d[s] = 0;
    que.push(P(0,s));

    while( !que.empty()){
        P p = que.top(); que.pop();//最短距離が小さい順に取り出していく
        int v = p.second;//現在の頂点番号
        if( d[v] < p.first) continue;//もし現在の頂点の最短距離が現在の最短距離と一致しない場合はむし
        for(int i = 0; i < G[v].size(); i++){
            edge e = G[v][i];//見てる頂点から伸びる辺がe
            if(d[e.to] > d[v] + e.cost){//もし、eの伸びる先の頂点の最短距離がvから見た最短距離よりも大きい場合
                d[e.to] = d[v] + e.cost;
                Prev[e.to] = v;
                que.push(P(d[e.to], e.to));//仮の最短距離とその頂点番号
            }
        }
    }
}

// 頂点tへの最短路
vector<int> get_path(int t){
    vector<int> path;
    for(; t != -1; t = Prev[t]) path.push_back(t);//tがsになるまで辿っていく
    reverse(path.begin(), path.end());
    return path;
}

bool visited[MAX_V];

int bfs(int s){
    queue<int> que;
    que.push(s);
    int cnt = 0;
    while(!que.empty()){
        int v = que.front(); que.pop();
        for(auto e: G[v]){
            int u = e.to;
            if(visited[u])continue;
            cnt++;
            que.push(u);
            visited[u] = true;
        }
    }
    return cnt;
}

