using namespace std;

struct Node {
  std::vector<int> neighbor;
};

using Tree = std::vector<Node>;

std::vector<int> bfs(Tree& tree, int from, int dst) {
  std::vector<bool> visited(tree.size());
  visited[from] = true;
  std::queue<std::vector<int>> q;
  q.push({from});
  while (!q.empty()) {
    const std::vector<int>& r = q.front();
    for (int v : tree[r.back()].neighbor) {
      if (visited[v])
        continue;
      visited[v] = true;
      std::vector<int> next = r;
      next.push_back(v);
      if (v == dst)
        return next;
      q.emplace(std::move(next));
    }
    q.pop();
  }
  return {};
}

std::vector<int> route(Tree& tree, int from, int dst, std::vector<bool>& visited) {
  if (from == dst)
    return {dst};
  for (int v : tree[from].neighbor) {
    if (visited[v])
      continue;
    visited[v] = true;
    std::vector<int> r = route(tree, v, dst, visited);
    if (!r.empty()) {
      r.push_back(from);
      return r;
    }
  }
  return {};
}

std::vector<int> route(Tree& tree, int from, int dst) {
  std::vector<bool> visited(tree.size(), false);
  visited[from] = true;
  return route(tree, from, dst, visited);
}

int counts(Tree& tree, int v, std::vector<bool>& visited) {
  int sum = 1;
  for (int a : tree[v].neighbor) {
    if (visited[a])
      continue;
    visited[a] = true;
    sum += counts(tree, a, visited);
  }
  return sum;
}

int counts(Tree& tree, int v, int skip) {
  std::vector<bool> visited(tree.size(), false);
  visited[v] = true;
  visited[skip] = true;
  return counts(tree, v, visited);
}

void erase(std::vector<int>& v, int num) {
  for (auto it = v.begin(); it < v.end(); it++) {
    if (*it == num) {
      v.erase(it);
      return;
    }
  }
}

int main() {
  int n;
  cin >> n;
  Tree tree(n);
  for (int i = 0; i < n - 1; i++) {
    int in, out;
    cin >> in >> out;
    tree[in - 1].neighbor.push_back(out - 1);
    tree[out - 1].neighbor.push_back(in - 1);
  }

  int black = 0;
  int white = n - 1;
  // std::vector<int> r = route(tree, black, white);
  std::vector<int> r = bfs(tree, white, black);
  int half = r.size() / 2;
  int black_side_id = r[half];
  int white_side_id = r[half - 1];
  int black_num = counts(tree, black_side_id, white_side_id);
  int white_num = n - black_num;

  std::cout << (black_num > white_num ? "Fennec" : "Snuke") << std::endl;
  return 0;
}

