vector<int> edges_to[100001];

typedef struct Node{
    int parent;
    vector<int> child;
} Node;

void construct_ki(Node *ki, int now, int p){
    ki[now].parent = p;
    rep(i, edges_to[now].size()){
        int c = edges_to[now][i];
        if(c != p) {
            ki[now].child.push_back(c);
            construct_ki(ki, c, now);
        }
    }
}

int num_nodes(Node *ki, int now){
    if(ki[now].child.size() == 0) return 1;

    int acc = 0;
    rep(i, ki[now].child.size()) acc += num_nodes(ki, ki[now].child[i]);
    return acc + 1; //子の部分木の節点の合計+自分
}

int main(void){
