    int dist_from_n_to_root = 0;
    int op = N;
    while(ki[op].parent != 1) {
        dist_from_n_to_root++;
        op = ki[op].parent;
    }

    int snuke_start;
    op = N;
    dist_from_n_to_root >>= 1;
    rep(i, dist_from_n_to_root) op = ki[op].parent;
