vector<int> bfs(int s,vector<vector<int> > G,int n)
{
	vector<int> d(n,INF);
	d[s]=0;
	queue<int> que;
	que.push(1);
	while(que.size()){
		int u=que.front();
		for(int v=0;v<G.size();v++){
			if(d[v]>d[u]+1){
				d[v]=d[u]+1;
				que.push(v);
			}
		}
		que.pop();
	}
	return d;
}
int main()
{
	int n;
	cin>>n;
	vector<vector<int> > G(n);
	n--;
	for(int i=0;i<n;i++){
		int a,b;
		cin>>a>>b;
		a--;
		b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	vector<int> d1=bfs(0,G,n);
	vector<int> d2=bfs(n-1,G,n);
	int F=0,S=0;
	for(int i=0;i<n;i++){
		if(d1[i]>d2[i]){
			F++;
		}
		else{
			S++;
		}
	}
	cout<<(F>S?"Snuke":"Fennec");
	return 0;
}

