void dfs(vvi &tree, vi &cost, int v = 0) {

	rep(i, tree[v].size()) {
		if (cost[tree[v][i]] == -1) {
			cost[tree[v][i]] = cost[v] + 1;
			dfs(tree, cost, tree[v][i]);
		}
	}
}

