#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

#define rep(i, N) for(ll i=0; i<N; ++i)

ll max(ll a, ll b) {return a < b ? b : a; }

int main() {
  //ポイントとしては幅優先探索を二回やるということ
  int N;
  cin >> N;
  //隣接行列 => グラフが密な場合に有利
  //頂点配列 => 木などグラフが疎な場合に有利
  vector<vector<int>> edges(N+1);
  for(int i=0; i<N-1; ++i) {
    int a, b;
    cin >> a >> b;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }

  vector<int> gcolf(N+1);
  vector<int> gcols(N+1);

  {
    queue<int> q;
    q.push(1);
    gcolf[1] = 0;
    while(!q.empty()) {
      int n = q.front(); q.pop();
      for(int e : edges[n]) {
        if(gcolf[e] != -1) continue;
        //次を見る時にもう経路の長さを数える
        gcolf[e] = gcolf[n] + 1;
        q.push(e);
      }
    }
  }

  {
    queue<int> q;
    q.push(N);
    gcols[N] = 0;
    while(!q.empty()) {
      int n = q.front(); q.pop();
      for(int e : edges[n]) {
        if(gcols[e] != -1) continue;
        //次を見る時にもう経路の長さを数える
        gcols[e] = gcols[n] + 1;
        q.push(e);
      }
    }
  }

  //数える
  int fcount = 0;
  for(int i=1; i<=N; ++i) {
    if(gcolf[i] < gcols[i]) {
      ++fcount;
    }
  }

  if(fcount >= N - fcount) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }

  return 0;
}

