        first[u] = p;
        node[p] = v;
        ++p;
        next[p] = first[v];
        first[v] = p;
        node[p] = u;
        ++p;
    }
}

bool dfs(int x, int deep)
{
    vis[x] = true;
    if (x == n)
    {
        len = deep >> 1;
        fs[n] = 2;
        ++ans[2];
        return true;
    }
    int t = first[x];
    while (t)
    {
        if (!vis[node[t]])
        {
            if (dfs(node[t], deep + 1))
            {
                if (deep > len)
                {
                    fs[x] = 2;
                    ++ans[2];
                }
                else
                {
                    fs[x] = 1;
                    ++ans[1];
                }
                return true;
            }
        }
        t = next[t];
    }
    return false;
}

void ddfs(int x)
{
    int t = first[x];
    while (t)
    {
        if (fs[node[t]] == 0)
        {
            ++ans[m];
            fs[node[t]] = m;
            ddfs(node[t]);
        }
        t = next[t];
    }
}

void init()
{
    memset(first, 0, sizeof first);
    memset(ans, 0, sizeof ans);
    memset(fs, 0, sizeof fs);
    memset(vis, false, sizeof vis);
}

int main()
{
    while (scanf("%d", &n) != EOF)
    {
        readin(n);
        dfs(1, 0);
        for (int i = 1; i <= n; ++i)
        {
            if (fs[i])
            {
                m = fs[i];
                ddfs(i);
            }
        }
        printf("%s\n", ans[1] > ans[2] ? "Fennec" : "Snuke");
        init();
    }
}

