#include <bits/stdc++.h>
using namespace std;

int N;
vector<vector<int>> graph(100010);
vector<int> visit(100010,-1);
int s=0;

void BFS_f(){
	queue<int> q;
	visit[0]=0;
	q.push(0);
	while(q.empty()==0){
		int f=q.front();
		q.pop();
		for(auto t:graph[f]){
			if(visit[t]==-1){
				visit[t]=visit[f]+1;
				q.push(t);
			}
		}
	}
}

void BFS_s(){
	queue<int> q;
	visit[N-1]=0;
	q.push(N-1);
	s++;
	while(q.empty()==0){
		int f=q.front();
		q.pop();
		for(auto t:graph[f]){
			if(visit[t]>visit[f]+1){
				visit[t]=visit[f]+1;
				s++;
				q.push(t);
			}
		}
	}
}

int main(){
	cin >> N;
	for(int i=0;i<N-1;i++){
		int a,b;
		cin >> a >> b;
		a--;b--;
		graph[a].push_back(b);
		graph[b].push_back(a);
	}

	BFS_f();
	BFS_s();

	if(s>=N/2)cout << "Snuke" << endl;
	else cout << "Fennec" << endl;
	return 0;
}

