void dfs(int now,int par, int cnt, int last) {
    if(now==last) {
        if(last==0) snu += (cnt-1)/2;
        else {
            if((cnt-1)%2==0) fen += (cnt-1)/2;
            else fen += (cnt-1)/2 + 1;
        }
