using namespace std;
struct NODE{
	int id;
	vector<NODE*> lnkNodes;
	int color;
	NODE(){
		lnkNodes.clear();
		id=-1;
		color=0;
	}
	void AddLnkNode(NODE &node){
		lnkNodes.push_back(&node);
	}
	void SetColor(int _color){
		color=_color;
	}
};
bool Find(vector<NODE> &Nodes,int color)
{
	int i;
	for (i=0;i<Nodes.size();i++){
		if (Nodes[i].color==color){
			for (int j=0;j<Nodes[i].lnkNodes.size();j++){
				if (Nodes[i].lnkNodes[j]->color==0){
					Nodes[i].lnkNodes[j]->color=color;
					return true;
				}
			}
			Nodes[i].lnkNodes.clear();
		}
	}
	return false;
}
int main(int argc, char* argv[])
{
	int N;
	cin>>N;
	vector<NODE> Nodes(N);
	Nodes[0].color=1;
	Nodes[N-1].color=2;
	int i;
	int node1,node2;
	for (i=0;i<N-1;i++){
		cin>>node1>>node2;
		node1--;
		node2--;
		Nodes[node1].id=node1;
		Nodes[node2].id=node2;
		Nodes[node1].AddLnkNode(Nodes[node2]);
		Nodes[node2].AddLnkNode(Nodes[node1]);
	}
	int color=1;
	while (true){
		if (!Find(Nodes,color)){
			switch(color){
			case 1:
				cout<<"Snuke"<<endl;
				return 0;
			case 2:
				cout<<"Fennec"<<endl;
				return 0;
			}
		}
		color++;
		if (color==3){
			color=1;
		}
	}
	return 0;
}

