using namespace std;

bool dfs(vector<vector<int>> &tr, int parent, int cur, vector<int> &path) {
    if (cur == tr.size() - 1) {
        path.push_back(cur);
        return true;
    }
    for (auto nxt : tr[cur]) {
        if (nxt == parent) continue;
        if (dfs(tr, cur, nxt, path)) {
            path.push_back(cur);
            return true;
        }
    }
    return false;
}

void dfs2(vector<vector<int>> &tr, int cur, vector<int> &col) {
    for (auto nxt : tr[cur]) {
        if (col[nxt]) continue;
        col[nxt] = col[cur];
        dfs2(tr, nxt, col);
    }
}

int main() {
    int n;
    cin >> n;
    vector<vector<int>> tr(n);
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        tr[a].push_back(b);
        tr[b].push_back(a);
    }
    vector<int> path;
    dfs(tr, -1, 0, path);
    vector<int> col(n);
    for (int i = 0; i < path.size() / 2; ++i) {
        col[path[i]] = 1;
    }
    for (int i = path.size() / 2; i < path.size(); ++i) {
        col[path[i]] = 2;
    }
    for (auto r : path) {
        dfs2(tr, r, col);
    }
    array<int, 2> cnts;
    for (auto c : col) {
        ++cnts[c - 1];
    }
    cout << (cnts[0] > cnts[1] ? "Snuke" : "Fennec") << endl;
    return 0;
}

