using namespace std;

int n;
map<int, set<int>> edge;

bool bfs(int start, int goal) {
  vector<int> cost = vector<int>(n + 1, 1e9);
  queue<pair<int, int>> q;
  cost[start] = 0;
  cost[goal] = 0;
  q.push(make_pair(start, 0));
  q.push(make_pair(goal, 1));
  int black = 0, white = 0;
  while (!q.empty()) {
    auto p = q.front();
    int u = p.first, color = p.second;
    q.pop();
    for (auto v: edge[u]) {
      if (cost[v] != 1e9) {
        continue;
      }
      if (color == 0) {
        black++;
      } else {
        white++;
      }
      cost[v] = cost[u] + 1;
      q.push(make_pair(v, color));
    }
  }
  return black > white;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> n;
  for (int i = 0; i < n - 1; i++) {
    int a, b;
    cin >> a >> b;
    edge[a].insert(b);
    edge[b].insert(a);
  }
  if (bfs(1, n)) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }
  return 0;
}

