void solve() {
  ll N;
  input(N);
  graph<ll> G;
  for (auto &&i : range(N - 1)) {
    ll a, b;
    input(a, b);
    G[a].insert(b);
    G[b].insert(a);
  }
  auto prev = dijkstra_path((ll)1, G, [&](ll, ll) { return (ll)1; },
                            u_set<ll>(begin(1), end(N + 1)));
  dump(G);
  dump(prev);
  vecl path;
  {
    ll v = N;
    while (v != 1) {
      path.push_back(v);
      v = prev[v];
    }
    path.push_back(1);
    reverse(path.begin(), path.end());
  }
  dump(path);
  ll M = path.size();
  list<ll> vF(path.begin(), path.begin() + (M + 1) / 2);
  list<ll> vS(path.begin() + (M + 1) / 2, path.end());
  dump(vF, vS);

  u_map<ll, ll> color;
  {
    for (auto const &v : vF)
      color[v] = 0;
    for (auto const &v : vS)
      color[v] = 1;
  }
  dfs(G, (ll)1, [&](auto p, auto c) {
    if (color.find(c) != color.end())
      return;
    if (!p)
      return;
    color[c] = color[p.value()];
  });
  dump(color);
  ll nF = count_if(color.begin(), color.end(),
                   [&](auto const &c) { return c.second == 0; });
  ll nS = count_if(color.begin(), color.end(),
                   [&](auto const &c) { return c.second == 1; });
  print(nF > nS ? "Fennec"s : "Snuke"s);
}

