#define o5 100100
using namespace std;

vector<ll> G[o5];
vector<ll> path;
vector<bool> V(o5, false);

void find_path(ll n)
{
    stack<ll> S;
    vector<bool> vis(n, false);
    ll tp;
    bool found = false;
    S.push(0);
    while (true)
    {
        tp = S.top();
        if (vis[tp])
        {
            S.pop();
        }
        else
        {
            vis[tp] = true;
            for (ll i = 0; i < G[tp].size(); i++)
            {
                ll tmp = G[tp][i];
                if (!vis[tmp])
                {
                    S.push(tmp);
                }
                if (tmp == n)
                {
                    vis[tmp] = true;
                    found = true;
                    break;
                }
            }
            if (found)
                break;
        }
    }
    while (!S.empty())
    {
        if (vis[S.top()])
            path.push_back(S.top());
        S.pop();
    }
}

ll count_child(ll root)
{
    ll count = 1;
    stack<ll> S;
    S.push(root);
    V[root] = false;
    while (!S.empty())
    {
        ll tp = S.top();
        if (V[tp])
        {
            S.pop();
        }
        else
        {
            V[tp] = true;
            for (ll i = 0; i < G[tp].size(); i++)
            {
                ll el = G[tp][i];
                if (!V[el])
                {
                    S.push(el);
                    count++;
                }
            }
        }
    }
    return count;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    ll n, x, y;
    cin >> n;
    for (ll i = 0; i < n - 1; i++)
    {
        cin >> x >> y;
        x--;
        y--;
        G[x].push_back(y);
        G[y].push_back(x);
    }

    find_path(n - 1);
    vector<ll> childs;
    for (auto i : path)
    {
        V[i] = true;
    }
    for (auto i : path)
    {
        childs.push_back(count_child(i));
    }
    ll ln = path.size() / 2;
    y = accumulate(childs.begin(), childs.begin() + ln, 0);
    x = accumulate(childs.begin() + ln, childs.end(), 0);
    if (x > y)
    {
        cout << "Fennec" << endl;
    }
    else
    {
        cout << "Snuke" << endl;
    }
}

