    queue<ll> wQ = queue<ll>();
    ll sumB = 0;
    ll sumW = 0;
    for (int i = 0; i < route.size(); ++i) {
        col[route[route.size() - i - 1]] = 0;
        bQ.push(route[route.size() - i - 1]);
        sumB++;
        if(col[route[i]] == -1){
            col[route[i]] = 1;
