    }
    while(!wQ.empty()){
        ll current = wQ.front();wQ.pop();
        for (int i = 0; i < G[current].first.size(); ++i) {
            ll next = G[current].first[i];
            if(col[next] != -1){
                continue;
            }
            wQ.push(next);
            col[next] = 1;
            sumW++;
        }
    }
    while(!bQ.empty()){
        ll current = bQ.front();bQ.pop();
        for (int i = 0; i < G[current].first.size(); ++i) {
            ll next = G[current].first[i];
            if(col[next] != -1){
                continue;
            }
            bQ.push(next);
            col[next] = 0;
            sumB++;
        }
    }

    if(sumB > sumW){
        cout << "Fennec" << endl;
    }else{
        cout << "Snuke" << endl;
    }




}

