using Edge = int; //頂点
using Graph = vector<vector<Edge>>;
Graph G;
void rec(const Graph &G, int current, int parent, long long sum,
         vector<long long> &dist) {
    dist[current] = sum;
    //木なので親では無かったら子供でしかない
    for(auto child : G[current]) {
        // cout << current << parent << endl;
        if(child == parent) {
            continue;
        } else {
            rec(G, child, current, sum + 1, dist);
        }
    }
}

int main() {
    long long N;
    cin >> N;
    G.resize(N);
    vector<long long> a(N - 1), b(N - 1);
    REP(i, N - 1) {
        cin >> a[i] >> b[i];
        a[i]--;
        b[i]--;
        G[a[i]].push_back(b[i]);
        G[b[i]].push_back(a[i]);
    }
    vector<long long> adist(N, 0);

    rec(G, 0, -1, 0, adist);

    vector<long long> Ndist(N, 0);
    rec(G, N - 2, N - 1, 0, Ndist);

    long long cnt = 0;
    REP(i, N) {
        if(adist[i] >= Ndist[i]) {
            cnt++;
        }
    }
    if(cnt >= N / 2) {
        cout << "Snuke" << endl;
    } else {
        cout << "Fennec" << endl;
    }
    return 0;
}

