int N;
VI F(100100),S(10010);
VVI X(100100);

void dfs(int B){
  if(B==0) F[0]=0;
  rep(i,X[B].size()){
    if(F[X[B][i]]==-1){
      F[X[B][i]]=F[B]+1;
      dfs(X[B][i]);
    }
  }
}

void dfs2(int B){
  if(B==N-1) S[N-1]=0;
  rep(i,X[B].size()){
    if(S[X[B][i]]==-1){
      S[X[B][i]]=S[B]+1;
      dfs2(X[B][i]);
    }
  }
}

int main(){
  cin>>N;
  VI A(N-1),B(N-1);
  rep(i,N-1) cin>>A[i]>>B[i];
  rep(i,N-1){
    X[A[i]-1].pb(B[i]-1);
    X[B[i]-1].pb(A[i]-1);
  }
  rep(i,10010) F[i]=-1;
  rep(i,10010) S[i]=-1;
  dfs(0);
  dfs2(N-1);
  int ans=0;
  rep(i,N) if(F[i]<=S[i]) ans++;
  if(ans>N-ans) cout<<"Fennec"<<endl;
  else cout<<"Snuke"<<endl;
}

