/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, a, b;
gr tree[MAX_N];
bool visited[MAX_N];
ll nto1;

pl dfs(str player, ll source){
    if (visited[source]) return mp(0, 0);
    visited[source] = true;

    ll val_white, val_black;
    if (player == "white"){
        val_white = 1; val_black = 0;
    }else {
        val_white = 0; val_black = 1;
    }
    pl vals;
    rep(i, tree[source].size()){
        ll target = tree[source][i].to;
        if (target == n - 1) vals = dfs("white", target);
        else if (target == 0) vals = dfs("black", target);
        else vals = dfs(player, target);
        val_black += vals.e1; val_white += vals.e2;
    }
    return mp(val_black, val_white);
}

void solve(){
    rep(i, n - 1){
        in2(a, b); a--; b--;
        tree[a].pb({b, 0});
        tree[b].pb({a, 0});
    }

    pl v1, v2;
    v1 = dfs("black", 0);
    rep(i, n) visited[i] = false;
    v2 = dfs("white", n - 1);
    nto1 = v1.e1 - v2.e1;
    ll b = v2.e1 + (nto1 + 1) / 2;
    ll w = v1.e2 + nto1 / 2;
    // prl4(v1.e1, v1.e2, v2.e1, v2.e2);
    if (b > w) prl("Fennec");
    else prl("Snuke");
}

int main(void){
    in1(n);
    // assert(n <= 999);
    solve();
    return 0;
}

