template<typename T>
std::ostream &operator<<(std::ostream &out, const std::vector<T> &v) {
    if (!v.empty()) {
        out << '[';
        std::copy(v.begin(), v.end(), std::ostream_iterator<T>(out, ", "));
        out << "\b\b]";
    }
    return out;
}

const int INF = 1 << 29;

auto solve() {
    int N;
    cin >> N;

    vector<vi> edges(N);
    REP(i, N - 1) {
        int a, b;
        cin >> a >> b;
        --a, --b;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    // kind of dijkstra
    vi d(N, INF);
    d[0] = 0;
    vi bef(N, -1);
    function<void(int, int)> best_route = [&](int n, int v) {
        d[n] = v;
        for (auto &&e : edges[n]) {
            if (d[e] == INF) {
                bef[e] = n;
                best_route(e, v + 1);
            }
        }
    };

    best_route(0, 0);

    // traverse
    vi route;
    {
        int v = N - 1;
        while (v != 0) {
            route.push_back(v);
            v = bef[v];
        }
        route.push_back(0);
        reverse(all(route));
    }

    // find #way
    function<int(int, int, int)> num_way = [&](int n, int next, int prev) {
        int v = 1;
        for (auto &&e : edges[n]) {
            if (e != next && e != prev) {
                v += num_way(e, -1, n);
            }
        }
        return v;
    };

    int fen_res = 0;
    REP(i, (route.size() + 1) / 2) {
        int cur, prev, nex;
        cur = route[i];
        if (i == 0)
            prev = -1;
        else
            prev = route[i - 1];
        nex = route[i + 1];

        fen_res += num_way(cur, nex, prev);
    }

    int snuke_res = 0;
    FOR(i, (route.size() + 1) / 2, route.size()) {
        int cur, prev, nex;
        cur = route[i];
        prev = route[i - 1];
        if(i == route.size()-1) nex = -1;
        else nex = route[i + 1];

        snuke_res += num_way(cur, nex, prev);
    }

    if(fen_res > snuke_res) {
        return "Fennec";
    } else {
        return "Snuke";
    }
}


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cout << solve() << endl;
//    solve();
    return 0;
}

