template<typename T>
int dfs(T& t_arr, int current, int parent, int length, int dest, int& cut_node){
  int ans_length = length;
  if(current != dest){
    ans_length = -1;
    for(auto&& it: t_arr[current]){
      if(it == parent) continue;
      ans_length = std::max(ans_length, dfs(t_arr, it, current, length+1, dest, cut_node));
    }
  }
  if(ans_length != -1 and length == ((ans_length+1)/2)) cut_node = current;
  return ans_length;
}

template<typename T>
int dfs_size(T& t_arr, int current, int parent, int cut_node){
  int ans_size = 1;
  for(auto&& it: t_arr[current]){
    if(it == parent || it == cut_node) continue;
    ans_size += dfs_size(t_arr, it, current, cut_node);
  }
  return ans_size;
}


