	rep(i, n - 1) {
		cin >> a >> b;
		e.to = a;
		e.cost = 1;
		G[b].push_back(e);
		e.to = b;
		e.cost = 1;
		G[a].push_back(e);
	}

	int d1[MAX_V], dn[MAX_V];
	dijkstra(1);
	rep1(i, n) {
		d1[i] = d[i];
	}
	dijkstra(n);
	rep1(i, n) {
		dn[i] = d[i];
	}

	ll cnt = 0;
	rep1(i, n) {
		if (d1[i] <= dn[i]) {
			cnt++;
		}
	}

	if (cnt >= n - cnt) {
		cout << "Fennec\n";
	}
	else {
		cout << "Snuke\n";
	}
}

