    for (int i = 1; i <= N; i++) {
        if (i != from && graph[pre][i] == 1) {
            vector<int> copy = v;
            copy.push_back(i);
            if (i == N) {
                return copy;
            }
            vector<int> res = Find1toN(copy);
            if (res[res.size() - 1] == N) {
                return res;
            }
        }
    }

    return v;
}

int GetChildrenCount(int node, int preNode, int count, int except) {
    int currentCount = count + 1;
    for (int i = 1; i <= N; i++) {
        if (i != preNode && i != except && graph[node][i] == 1) {
            currentCount = GetChildrenCount(i, node, currentCount, -1);
        }
    }

    return currentCount;
}

int main() {
    cin >> N;

    for (int i = 0; i <= N; i++) {
        graph.push_back(vector<int>(N+1, 0));
    }
    for (int i = 1; i <= N-1; i++) {
        int a, b;
        cin >> a >> b;
        graph[a][b] = 1;
        graph[b][a] = 1;
    }

    vector<int> temp;
    temp.push_back(1);

    auto route1toN = Find1toN(temp);

    int fIndex = route1toN.size(), sIndex = -1;
    int fCount = 0, sCount = 0;
    while (fIndex > sIndex) {
        fIndex--;
        if (fIndex > sIndex) {
            if (fIndex < route1toN.size() - 1) {
                fCount += GetChildrenCount(route1toN[fIndex], route1toN[fIndex + 1], 0, route1toN[fIndex - 1]);
            }
            else {
                fCount += GetChildrenCount(route1toN[fIndex], -1, 0, route1toN[fIndex - 1]);
            }
        }

        sIndex++;
        if (fIndex > sIndex) {
            if (sCount > 0) {
                sCount += GetChildrenCount(route1toN[sIndex], route1toN[sIndex-1], 0, route1toN[sIndex + 1]);
            }
            else {
                sCount += GetChildrenCount(route1toN[sIndex], -1, 0, route1toN[sIndex + 1]);
            }
        }
    }


    if (fCount > sCount) {
        cout << "Snuke" << endl;
    }
    else {
        cout << "Fennec" << endl;
    }
    return 0;
}

