const long long LINF = 1e18;

void solve(void){
    int N;
    cin >> N;
    vector<vector<int>> G(N);
    for(int i = 0; i < N-1; i++){
        int a, b;
        cin >> a >> b;
        G[a-1].push_back(b-1);
        G[b-1].push_back(a-1);
    }

    queue<int> que;
    vector<int> fennec(N, INF), sunuke(N, INF);
    fennec[0] = 0;
    que.push(0);

    while(!que.empty()){
        int cur = que.front();
        que.pop();
        for(int next : G[cur]){
            if(fennec[next] == INF){
                fennec[next] = fennec[cur] + 1;
                que.push(next);
            }
        }
    }

    sunuke[N-1] = 0;
    que.push(N-1);
    while(!que.empty()){
        int cur = que.front();
        que.pop();
        for(int next : G[cur]){
            if(sunuke[next] == INF){
                sunuke[next] = sunuke[cur] + 1;
                que.push(next);
            }
        }
    }

    int cnt = 0;
    for(int i = 0; i < N; i++){
        if(fennec[i] <= sunuke[i]) cnt++;
        else cnt--;
    }
    if(cnt > 0) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;
}
