void distance(int p, int d, vvi &tree, vi &visited){
	// printf("p %d  d %d\n",p,d);//
	if(visited[p] > 0){
		// printf("visited p %d\n", p);//
		return;
	}
	// printf("set visited p %d d %d\n", p,d);//
	visited[p] = d;
	for(auto c: tree[p]){
		distance(c, d+1, tree, visited);
	}
}

string solve(int N, vi &A, vi &B){
	vvi tree(N+1, vi());
	rp(i, 0, N-1){
		tree[A[i]].push_back(B[i]);
		tree[B[i]].push_back(A[i]);
	}
	// vvprn(tree);//
	vi f(N+1), s(N+1);
	distance(1, 1, tree,f);
	distance(N, 1, tree,s);
	// vprn(f);//
	// vprn(s);//
	int c = 0;
	rp(i, 1, N+1){
		c += f[i]==s[i]? 0: f[i]<s[i]? 1: -1;
	}
	return c>0? "Fennec": "Snuke";
}

