//各スタート位置から対戦相手のノードに到るまで繋がっているノードの総数
ll Fennec = -1;
ll Snuke = -1;
//取り合うことで勝負が決まる　ノードとノードで挟まれた回廊
ll battleZone[1145141];
ll N = 0;

//flg = 1 すでに到達済み 0＝まだ到達していない
//player == 0 Fennec, player == 1 sunuke
ll dfs(ll idx, ll player,  ll from = -1){

    //計算終了
    if(player == 0){

        if(idx == N){
            //伝搬させておくと楽
            battleZone[idx] = battleZone[from];
            return 0;
        }

        if(from != -1){
            //はじめ以外伝搬
            battleZone[idx] = battleZone[from] + 1;
        }  

        if(f_flg[idx] == 1){
            return 0;
        }
        f_flg[idx] = 1;
        Fennec++; 
    }else if(player == 1){
        if(idx == 1){
            return 0;
        }

        if(s_flg[idx] == 1){
            return 0;
        }
        s_flg[idx] = 1;
        Snuke++;

    }
    //cout << from << endl;
    for(ll i = 0; i < G[idx].size(); i++){
        //次の行き先は？
        ll to = G[idx][i];
        //同じだったらもう処理しない
        if(to == from){
            continue;
        }

        dfs(to, player, idx);

    }

    return 0;
}

