    battleZone[1] = 0;
    //Fennecが塗りつぶせる数 スタート：ノード１
    dfs(1, 0);
    dfs(N, 1);

    //cout << battleZone[N] << "," << Fennec << "," << Snuke << endl;
    //勝者は？？
    //最終的に取れるノード
    Fennec = Fennec - battleZone[N] + battleZone[N] / 2 + battleZone[N] % 2;
    Snuke = Snuke - battleZone[N] + battleZone[N] / 2;
    if(Fennec > Snuke){
        cout << "Fennec" << endl;
    }else{
        cout << "Snuke" << endl;
    }


}

