#include <bits/stdc++.h>
using namespace std;
#define modulo 1000000007
#define mod(mod_x) ((((long long)mod_x+modulo))%modulo)
#define Inf 10000000



int main(){

	int N;
	cin>>N;

	vector<vector<int>> E(N,vector<int>());

	for(int i=0;i<N-1;i++){
		int a,b;
		cin>>a>>b;
		a--;b--;

		E[a].push_back(b);
		E[b].push_back(a);
	}

	vector<int> dis(N,Inf);
	dis[0]=0;
	queue<int> Q;
	Q.push(0);

	while(Q.size()!=0){
		int from = Q.front();
		Q.pop();
		for(int i=0;i<E[from].size();i++){
			int to = E[from][i];
			if(dis[to]!=Inf)continue;
			dis[to] = dis[from]+1;
			Q.push(to);
		}
	}

	deque<int> L(0);
	int now = N-1;
	while(true){
		for(int i=0;i<E[now].size();i++){
			int to = E[now][i];
			if(dis[to]==dis[now]-1){
				now=to;
				break;
			}
		}
		if(dis[now]==0)break;
		L.push_back(now);
	}

	vector<string> color(N,"");
	color[0]="black";
	color[N-1]="white";

	for(int i=0;i<N;i++){
		if(L.size()==0)break;
		if(i%2==0){
			color[L.front()]="black";
			L.pop_front();
		}
		else{
			color[L.back()]="white";
			L.pop_back();
		}
	}

	for(int i=0;i<N;i++){
		string s = color[i];
		if(s=="")continue;
		Q.push(i);
		while(Q.size()!=0){
			int from = Q.front();
			Q.pop();
			for(int j=0;j<E[from].size();j++){
				int to = E[from][j];
				if(color[to]!="")continue;
				color[to]=s;
				Q.push(to);
			}
		}
	}

	int b=0,w=0;

	for(int i=0;i<N;i++){
		assert(color[i]!="");
		if(color[i]=="black")b++;
		else w++;
	}

	if(b>w){
		cout<<"Fennec"<<endl;
	}
	else{
		cout<<"Snuke"<<endl;
	}

    return 0;
}

