#include<bits/stdc++.h>
using namespace std;

struct edge{int to,cost;};
typedef pair<int,int> P;

int V;
vector<edge> g[100010];
int d[100010];
int inf = 2000000007;
int pre[100010];
int fen = 0,snu = 0;
vector<int> keiro;
bool used[100010];

void dijkstra(int s){
  priority_queue<P,vector<P>,greater<P>> que;
  for(int i = 0;i <= V;i++){
    d[i] = inf;
  }
  d[s] = 0;
  que.push(P(0,s));

  while(!que.empty()){
    P p = que.top();
    que.pop();
    int v = p.second;
    if(d[v] < p.first) continue;
    for(int i = 0;i < g[v].size();i++){
      edge e = g[v][i];
      if(d[e.to] > d[v] + e.cost){
        d[e.to] = d[v] + e.cost;
        que.push(P(d[e.to],e.to));
        pre[e.to] = v;
        //cout << 'v' << v << endl;
      }
    }
  }
}

vector<int> get_path(int t){
  vector<int> path;
  for(;t != 1;t = pre[t]){
    path.push_back(t);
    //cout << 't' << t << endl;
  }
  path.push_back(1);
  reverse(path.begin(),path.end());
  return path;
}

void dfs(int s,string player,int j){
  used[s] = true;
  //cout << s << endl;
  if(player == "Fennec"){
    fen++;
  }
  else if(player == "Snuke"){
    snu++;
  }
  for(int i = 0;i < g[s].size();i++){
    edge e = g[s].at(i);
    if(used[e.to] != true){
      if(j != keiro.size() - 1 && e.to != keiro.at(j+1)){
        dfs(e.to,player,j);
      }
      else if(j == keiro.size() - 1){
        dfs(e.to,player,j);
      }
    }
  }
}

