  ll dist = g.dist(n - 1);
  // cout << dist << endl;
  ll v = n - 1;
  vl color(n, -1);
  ll cnt = 1;
  color[0] = 0;
  color[n - 1] = 1;
  while (v > 0) {
    v = g.prev(v);
    // cout << v << endl;
    cnt++;
    if (cnt > dist / 2) {
      color[v] = 0;
    } else {
      color[v] = 1;
    }
  }
  // rep(i, n) { cout << color[i] << endl; }
  queue<ll> que;
  rep(i, n) {
    if (color[i] == 0) {
      que.push(i);
    }
  }
  // cout << que.size() << endl;
  while (!que.empty()) {
    ll v = que.front();
    que.pop();
    for (auto& e : g.G_[v]) {
      ll to = e.to;
      if (color[to] == -1) {
