using namespace std;

vector<int> dfs(int curr, int target, vector<int> path, const map<int, set<int> >& tree, vector<bool> reached) {
    if (curr == target) {
        path.push_back(target);
        return path;
    }
    reached[curr] = true;
    path.push_back(curr);
    vector<int> ans;
    for (auto e : tree.at(curr)) {
        if (!reached[e]) {
            vector<int> pathTo = dfs(e, target, path, tree, reached);
            if (pathTo.size() > 0) {
                ans = pathTo;
            }
        }
    }
    return ans;
}

void dfsc(int curr, const map<int, set<int> >& tree, vector<int>& color, int addColor) {
    for (auto e : tree.at(curr)) {
        if (color[e] < 0) {
            color[e] = addColor;
            dfsc(e, tree, color, addColor);
        }
    }
}

void Main() {
    int N;
    cin >> N;
    map<int, set<int> > tree;
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        tree[a].insert(b);
        tree[b].insert(a);
    }

    vector<int> color(N, -1);
    color[0] = 1;
    color[N - 1] = 0;

    // find path from 0 to N-1
    vector<bool> reached(N, false);
    vector<int> path0ToNm1 = dfs(0, N - 1, vector<int>(), tree, reached);
    for (int i = 0; i < path0ToNm1.size(); ++i) {
        if (i % 2 == 0) {
            if (color[path0ToNm1[i / 2]] >= 0) {
                break;
            }
            color[path0ToNm1[i / 2]] = 1;
        }
        else {
            if (color[path0ToNm1[N - 1 - (i - 1) / 2]] >= 0) {
                break;
            }
            color[path0ToNm1[N - 1 - (i - 1) / 2]] = 0;
        }
    }

    if (path0ToNm1.size() % 2 == 0) {
        // next is black
        dfsc(0, tree, color, 1);
        dfsc(N - 1, tree, color, 0);
    }
    else {
        // next is white
        dfsc(N - 1, tree, color, 0);
        dfsc(0, tree, color, 1);
    }
    int nbBlack = 0;
    for (int i = 0; i < N; ++i) {
        if (color[i] == 1) {
            ++nbBlack;
        }
    }
    int nbwhite = N - nbBlack;
    cout << (nbBlack > nbwhite ? "Fennec" : "Snuke") << endl;
}

int main() {
    std::cout << std::fixed << std::setprecision(15);
    Main();
    return 0;
}

