#define NOCOLOR 0
#define BLACK 1 //Fennec
#define WHITE 2 //Snuke
#define N 100000
using namespace std;

int n;
int M[N][N];
int color[N];

void bfs(int s1, int s2){
    queue<int> q1,q2;
    q1.push(s1); //init state(fennec)
    q2.push(s2); //init state(snuke)
    for(int i = 0; i < n; i++) color[i]=NOCOLOR;
    color[0]=BLACK;
    color[n-1]=WHITE;
    int u1,u2;
    while(!q1.empty() && !q2.empty()){
        // cout<<"Fennec's Turn"<<endl;
        u1=q1.front(); q1.pop();
        for(int v = 0; v < n; v++){
            if(M[u1][v]==0) continue;
            if(color[v]!=NOCOLOR) continue;
            color[v] = BLACK;
            // cout<<"proceed"<<v<<endl;
            q1.push(v);
        }
        u2=q2.front(); q2.pop();
        // cout<<"Snuke's Turn"<<endl;
        for(int v = 0; v < n; v++){
            if(M[u2][v]==0) continue;
            if(color[v]!=NOCOLOR) continue;
            color[v] = WHITE;
            // cout<<"proceed"<<v<<endl;
            q2.push(v);
        }
    }
    if(!q1.empty()) cout<<"Fennec"<<endl;
    else cout<<"Snuke"<<endl;
}
