	int from,to,dis;
};

struct node 
{
	int u,d;
	bool operator < (const node &a) const 
	{
	  return d > a.d;
	}
};

vector<Edge>  edge;
vector<int> g[N];
vector<int> gg[N];
int dis[N];
int vis[N];
int pre[N];
int col[N];
void addedge(int u,int d,int dis)
{
   edge.push_back((Edge){u,d,dis});
   int s=edge.size();
   s--;
   g[u].push_back(s);
}

void dij(int s)
{
   priority_queue<node> q;
   memset(dis,INF,sizeof(dis));
   memset(vis,0,sizeof(vis));
   q.push((node){s,0});
   dis[s]=0;
   while(!q.empty())
   {
   	node x=q.top();
   	int u=x.u;
   	q.pop();
   	if(vis[u]==1)continue;
   	vis[u]=1;
   	for(int i=0;i<g[u].size();i++)
   	{
   		Edge e=edge[g[u][i]];
   	    if(dis[e.to]>dis[u]+e.dis)
		   {
		   	dis[e.to]=dis[u]+e.dis;
		   	pre[e.to]=u;
		   	q.push((node){e.to,dis[e.to]});
		}	
	}
   }	
}
int sum;
void dfs(int u,int fa)
{
	int l=gg[u].size();
	if(col[u]==1)return ;
	//printf("u %d\n",u);
	sum++;
	for(int i=0;i<l;i++)
	{
		int v=gg[u][i];
		if(v==fa)continue;
		dfs(v,u);
	}
	return;
}

int main()
{
	while(~scanf("%d",&n))
	{
		edge.clear();
		for(int i=0;i<=n;i++)g[i].clear();
		for(int i=1;i<=n-1;i++)
		{
			int u,v;
			scanf("%d%d",&u,&v);
			addedge(u,v,1);
			addedge(v,u,1);
			gg[u].push_back(v);
			gg[v].push_back(u);
		}
		for(int i=1;i<=n;i++)pre[i]=i;
		dij(1);
		int x=n;
		int dd=dis[n]+1;
		//printf("%d\n",dd);
		memset(col,0,sizeof(col));
		for(int i=1;i<=dd/2;i++)
		{
			//printf("x %d\n",x);
			col[x]=1;
			x=pre[x];
		}
		sum=0;
		dfs(1,-1);
		//printf("%d\n",sum);
		if(sum>n-sum)printf("Fennec\n");
		else printf("Snuke\n");
	}
	return 0;
}

