const int mxN = 1e5;
vt<int> t[mxN], path;
int n;
int sz[mxN];


int dfs(int nd, int p = -1) {
    int val = 0;
    for (int i:t[nd]) {
        if (i != p) {
            val += 1 + dfs(i, nd);
        }
    }
    sz[nd] = val;
    return val;
}

bool dfs2(int nd, int p = -1) {
    if (nd == n - 1) {
        path.pb(n - 1);
        return true;
    }

    for (int i:t[nd]) {
        if (i == p) continue;
        if (dfs2(i, nd)) {
            path.pb(nd);
            return true;
        }
    }

    return false;
}

void solve() {
    read(n);

    FOR(n - 1) {
        int x, y;
        read(x, y);
        x--;
        y--;
        t[x].pb(y);
        t[y].pb(x);
    }
    dfs(0);
    dfs2(0);
    reverse(all(path));
//    print();
//
//    FOR(n) {
//        print(i + 1, sz[i]);
//    }

    int f, s;
    bool ok = 1;
    if (path.size() == 2) {
        s = sz[n - 1];
        f = n - s - 2;
    }
    else if (path.size() & 1) {
        int x = path.size() / 2;
        x++;
        x = path[x];
        s = sz[x] - 1;
        f = n - sz[n - 1] - path.size();
        ok = 0;
    }
    else{
        int x = path.size() / 2;
        x = path[x];
        s = sz[x] - 1;
        f = n - sz[n - 1] - path.size();
    }

    if (f > s) {
        print("Fennec");
    }
    else if (f < s) {
        print("Snuke");
    }
    else{
        print(ok ? "Snuke" : "Fennec");
    }


}

