    while(!Q.empty()){
        ll idx = Q.front();
        Q.pop();
        for(ll i = 0; i < path[idx].size(); i++){
            ll nxt = path[idx][i];
            if(from[nxt] == 0){
                from[nxt] = 1 + from[idx];
                Q.push(nxt);
            }
        }
    }
    for(ll i = from[N]; i > 1;i = from[i])priori[i] = 1;

    priority_queue<P>PQ[2];
    PQ[0].push(P(1, 1));
    PQ[1].push(P(1, N));
    for(ll i = 0; ; i++){
        ll p = i % 2;
        ll idx = -1;
        while(!PQ[p].empty()){
            ll nxt = PQ[p].top().second;
            PQ[p].pop();
            if(flg[nxt])continue;
            idx = nxt;
            break;
        }
        if(idx == -1){
            if(p == 0)cout << "Snuke" << endl;
            else cout << "Fennec" << endl;
            return 0;
        }
        flg[idx] = 1;
        for(ll j = 0; j < path[idx].size(); j++){
            ll nxt = path[idx][j];
            if(flg[nxt])continue;
            if(priori[nxt])PQ[p].push(P(1, nxt));
            else PQ[p].push(P(0, nxt));
        }
    }


    return 0;
}

