int dfs(int nd, int p = -1) {
    int val = 1;
    for (int i:t[nd]) {
        if (i != p) {
            val += dfs(i, nd);
        }
    }
    sz[nd] = val;
    return val;
}

bool dfs2(int nd, int p = -1) {
    if (nd == n - 1) {
        path.pb(n - 1);
        return true;
    }

    for (int i:t[nd]) {
        if (i == p) continue;
        if (dfs2(i, nd)) {
            path.pb(nd);
            return true;
        }
    }

    return false;
}

void solve() {
    read(n);

    FOR(n - 1) {
        int x, y;
        read(x, y);
        x--;
        y--;
        t[x].pb(y);
        t[y].pb(x);
    }
    dfs(0);
    dfs2(0);
    reverse(all(path));
    int n1 = path.size();
    int white;
    if (n1 & 1)
        white = sz[path[n1 / 2 + 1]];
    else
        white = sz[path[n1 / 2]];

    int black = n - white;

    if (black > white) {
        print("Fennec");
    }
    else{
        print("Snuke");
    }
}

