void wfs(int start, vector<int>& dist, const vector<vector<int>>& edge)
{
	vector<bool> table(edge.size(), true);

	queue<pair<int, int>> que;
	que.push(make_pair(0, start));

	while(que.empty() != true)
	{
		int term = que.front().first;
		int index = que.front().second;
		que.pop();

		if(table[index] == false)
			continue;

		dist[index] = term;
		table[index] = false;

		for(auto it=edge[index].begin(); it!=edge[index].end(); it++)
			que.push(make_pair(term+1, *it));
	}
}

