using namespace std;

typedef vector<vector<int>> Graph;

stack<int> dfs(Graph &g, int s, int t)
{ 
  vector<bool> flag(g.size(), false);
  stack<int> st;
  flag[s] = true;
  st.push(s);
  while(!st.empty())
  {
    int current = st.top();
    if(current == t)
    {
      return st;
    }else{
      bool nv = false;
      for(int i = 0; i < g[current].size(); i++)
      {
        int next = g[current][i];
        if(!flag[next])
        {
          nv = true;
          flag[next] = true;
          st.push(next);
          break;
        }
      }
      if(!nv)
      {
        st.pop();
      }
    }
  }
  return st;
}

void draw_non_path(Graph &g, vector<int> &draw, vector<int> mem, int s, int color)
{
  vector<bool> flag(g.size(), false);
  queue<int> q;
  flag[s] = true;
  q.push(s);
  while(!q.empty())
  {
    int current = q.front();
    q.pop();
    for(int i = 0; i < g[current].size(); i++)
    {
      int next = g[current][i];
      if(mem[next] != 0) continue;
      if(flag[next]) continue;
      flag[next] = true;
      q.push(next);
      draw[next] = color;
    }
  }
}

void draw_in_path(Graph &g, vector<int> &draw, int s, int color)
{
  vector<bool> flag(g.size(), false);
  queue<int> q;
  flag[s] = true;
  q.push(s);
  while(!q.empty())
  {
    int current = q.front();
    q.pop();
    for(int i = 0; i < g[current].size(); i++){
