void DFS(const int s, const vector<vector<int>> &adList, vector<int> &dists)
{
    dists[s] = 0;
    deque<int> Q{ s };
    while (!Q.empty())
    {
        int v = Q.front(); Q.pop_front();
        for (const int n : adList[v])
        {
            if (dists[n] > dists[v] + 1)
            {
                dists[n] = dists[v] + 1;
                Q.push_back(n);
            }
        }
    }
}

