const int N = 1e5 + 10;
int n, f1, f2;
vector<vector<int>> adj;
bool seen[N];

int first(int u, int dist) {
    seen[u] = true;
    for (int v : adj[u]) {
        if (seen[v]) continue;
        if (v == n - 1) {
            if (u != 0) f1 = u;
            else f1 = v;
            f2 = u;
            return dist;
        }
        int d = first(v, dist + 1);
        if (d > 0) {
            if (u != 0) f1 = u;
            return d;
        }
    }
    return -1;
}

int dfs(int u) {
    seen[u] = true;
    int cnt = 1;
    for (int v : adj[u]) {
        if (seen[v]) continue;
        cnt += dfs(v);
    }
    return cnt;
}

