            mark[cur] = col;

            for(auto v: G[cur]) {
                if(v == prev) continue;
                dfs(dfs, v, cur, col);
            }
        };

        dfs(dfs, 0, -1, 1);
        dfs(dfs, n-1, -1, 2);
    }

