vector<int> getPath(vector<vector<int>>& es){
  int n = es.size();
  int s = 0,t = n-1;

  queue<int> que;
  vector<int> prev(n,-1);
  prev[s] = 1;
  que.push(s);
  while(!que.empty()){
    int now = que.front();que.pop();
    for(int i=0;i<es[now].size();i++){
      int nxt = es[now][i];
      if(prev[nxt] != -1)continue;
      prev[nxt] = now;
      que.push(nxt);
    }
  }
  vector<int> path;
  path.push_back(t);
  int now = t;
  while(now != s) {
    now = prev[now];
    path.push_back(now);
  }
  reverse(path.begin(),path.end());
  return path;
}

