        int u = que1.front(); que1.pop();
        for (int i = 0; i < G[u].size(); i++) {
            int v = G[u][i];
            if (dist1[v] != INF) continue;
            que1.push(v);
            dist1[v] = dist1[u] + 1;
        }
    }

    queue<int> que2;
    vector<int> dist2(N, INF);
    que2.push(N - 1);
    dist2[N - 1] = 0;
    while (!que2.empty()) {
        int u = que2.front(); que2.pop();
        for (int i = 0; i < G[u].size(); i++) {
            int v = G[u][i];
            if (dist2[v] != INF) continue;
            que2.push(v);
            dist2[v] = dist2[u] + 1;
        }
    }

    int f_cnt = 0, s_cnt = 0;
