vi visited;
int dist;

int dfs(int v, int depth) {
    if (depth != 0 && (v == N - 1 || v == 0)) {
        dist = depth;
        return -1;
    }

    visited[v] = true;
    int size = 1;

    for (const int next : graph[v]) {
        if (!visited[next]) {
            int ret = dfs(next, depth + 1);

            if (ret < 0 && depth >= (dist + 1) / 2) size = -1;
            else if (ret > 0 && size > 0) size += ret;
        }
    }

    return size;
}

