    vector<edge> G[MAX_V];
    rep(i,v-1){
        int s,t;
        cin>>s>>t;
        s--,t--;
        G[s].pb(edge{t,1});
        G[t].pb(edge{s,1});
    }

    vector<int> d1(v),d2(v);

    dijkstra(0,d1,G);
    dijkstra(v-1,d2,G);

    int sum = 0;
    rep(i,v){
        if(d1[i]<=d2[i]){
            sum++;
        }
    }
    if(sum>v/2)cout<<"Fennec"<<endl;
    else cout<<"Snuke"<<endl;
}

