    vector<int> res;
    rep(i, E[cur].size()) {
        if (D[E[cur][i]-1] != -1) continue;
        path.emplace_back(E[cur][i]);
        D[E[cur][i]-1] = D[cur] + 1;
        if (dfs(E[cur][i], to, path)) return true;
        path.pop_back();
    }
    return false;
}

void paint(int from, int mine, vector<int>& used) {
    vector<int> e = E[from];
    rep(i, e.size()) {
        if (e[i] != from && used[e[i] - 1] == 0) {
            used[e[i] - 1] = mine;
            paint(e[i], mine, used);
        }
    }
}

int main() {
    int N; cin >> N;
    rep(i, N-1) {
        int a,b; cin >> a >> b;
        E[a].emplace_back(b);
        E[b].emplace_back(a);
    }
    vector<int> path;
    path.emplace_back(1);
    fill(D, D+100000, -1);
    D[0] = 0;
    int s = dfs(1, N, path);
    if (s == 0) {
        fprintf(stderr, "No path to N found.");
        exit(1);
    }

    vector<int> used(N);
    used[0] = 1;
    used[N-1] = -1;
    int fs = 1;
    int ss = 1;

    int tmp = path.size();
    for (int i = 1; i < (tmp + 1) / 2; i++) {
        used[path[i] - 1] = 1; fs++;
        if (used[path[tmp -1 - i] - 1] == 0) {
            used[path[tmp -1 - i] - 1] = -1; ss++;
        }
    }

    int fp = 1;
    int fonp = 0;
    int sp = N;
    int sonp = path.size() - 1;
    while (used[fp - 1] != -1) {
        paint(fp, 1, used);
        fonp++;
        fp = path[fonp];
    }

    while (used[sp - 1] != 1) {
        paint(sp, -1, used);
        sonp--;
        sp = path[sonp];
    }

    fs = std::count(used.begin(), used.end(), 1);
    ss = used.size() - fs;
    if (fs > ss) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
}

