#include <bits/stdc++.h>
using namespace std;

int main(){
    int n, m;// number of nodes & edges
    cin >> n;
    m = n-1;

    vector<vector<int>> graph(n);
    vector<pair<int,int>> edge;
    for(int i=0; i<m; i++){
        int a, b;
        cin >> a >> b;
        a -= 1;
        b -= 1;
        graph[a].push_back(b);
        graph[b].push_back(a);
        edge.push_back({a,b});// equiv: edge.emplace_back(a,b)
    }

    vector<int> depth1(n,0), depthN(n,0);
    queue<int> que;

    // root
    depth1[0] = 1;
    que.push(0);

    while(!que.empty()){
        int current = que.front();
        que.pop();

        for(int adjacent : graph[current]){
            if(depth1[adjacent]!=0) continue;// already visited
            que.push(adjacent);
            depth1[adjacent] = depth1[current] + 1;
        }
    }

    depthN[n-1] = 1;
    que.push(n-1);

    while(!que.empty()){
        int current = que.front();
        que.pop();

        for(int adjacent : graph[current]){
            if(depthN[adjacent]!=0) continue;// already visited
            que.push(adjacent);
            depthN[adjacent] = depthN[current] + 1;
        }
    }
    int count1 = 0, countN = 0;
    for(int i=0; i<n; i++){
        if(depth1[i] <= depthN[i]) count1 += 1;
        if(depth1[i] >  depthN[i]) countN += 1;
    }
    if(count1 >  countN) cout << "Fennec" << endl;
    if(count1 <= countN) cout << "Snuke" << endl;
    return 0;
}

