void treeDfs(const vector <vector < int > >& adj, vector <pair <ll, bool> >& nodeInfo, ll depth, int now, int prev = NG)
{
	nodeInfo[now].first = depth;
	nodeInfo[now].second = SZ(adj[now]) == 1 ? true : false;

	for (const auto& next : adj[now])
	{
		if (next != prev)
		{
			treeDfs(adj, nodeInfo, depth + 1, next, now);
		}
	}
}

int treeDfs(const vector <vector < int > >& adj, const vector <pair <ll, bool> >& nodeInfo, int now)
{
	int ret = 0;

	for (int next : adj[now])
	{
		if (nodeInfo[next].first > nodeInfo[now].first)
		{
			ret += treeDfs(adj, nodeInfo, next);
