    }
    return res;
}

int countO(int on, int par){
    int res = 1;
    int mid = path[(path.size()+1)/2 - 1];
    for(int &to:E[on]){
        if(to!= mid && to!=par){
            res += countX(to, on);
        }
    }
    return res;
}

