class Node {
public:
  std::vector<int> neighbor;
};

std::vector<int> bfs(std::vector<Node>& graph, const int& n, int s) {
  std::vector<int> dist(n+1, -1);
  dist[s] = 0;
  std::queue<int> visit;
  visit.push(s);
  while (!visit.empty()) {
    int u = visit.front(); visit.pop();
    for (int node : graph[u].neighbor) {
      if (dist[node] == -1) {
        dist[node] = dist[u] + 1;
        visit.push(node);
      }
    }
  }
  return dist;
}

int main() {
