int dfs(int p1, int p2, vvi &tree, vi &visited){//return number of children
	if(p1 == p2){
		return 0;
	}
	if(visited[p1]){
		return 0;
	}
	visited[p1] = true;

	int count = 1;

	for(auto c: tree[p1]){
		count += dfs(c, p2, tree, visited);
	}
	visited[p1] = false;
	return count;
}

string solve(int N, vi &A, vi &B){
	vvi tree(N+1, vi());
	rp(i, 0, N-1){
		tree[A[i]].push_back(B[i]);
		tree[B[i]].push_back(A[i]);
	}

	// vvprn(tree);//

	vi visited(N);
	int f = dfs(1, N, tree, visited);
	int s = dfs(N, 1, tree, visited);
	// printf("f %d s %d\n",f,s);//
	return f>s? "Fennec": "Snuke";
}
