void searchDistance(DWORD start, DWORD *adwField)
{
	queue<DWORD> que;
	BOOL	abIsVisit[N_MAX + 1] = {};

	que.push(start);
	adwField[start] = 0;
	abIsVisit[start] = true;
	while(!que.empty()) {
		DWORD dwDst = que.front();	que.pop();
		for (auto iter = vecList[dwDst].begin(); iter != vecList[dwDst].end(); ++iter) {
			if (!abIsVisit[*iter]) {
				adwField[*iter] = adwField[dwDst] + 1;
				que.push(*iter);
				abIsVisit[*iter] = true;
			}
		}
	}
}

