    rep(i, SZ(g[node])){
        if(!visited[g[node][i]]){
            if(dfs(g[node][i], depth+1)) ret = 1;
        }
    }
    if(ret == 1) visited[node] = 2;
    return ret;
}
ll path = 0;
void dfs2(ll node, ll depth){
    if(node == n){
        return;
    }
    if(depth <= (path+1)/2){
        color[node] = 1;
    }else{
        color[node] = 2;
    }
    rep(i, SZ(g[node])){
        if(visited[g[node][i]] == 2){
            dfs2(g[node][i], depth+1);
        }
    }
}
void dfs3(ll node, ll c){
    color[node] = c;
    rep(i, SZ(g[node])){
        if(!color[g[node][i]]){
            dfs3(g[node][i], c);
        }
    }
}

