		if(min(a,b)>0)e.unite(a,b);
		if(max(a,b)<n-1)d.unite(a,b);
	}		
	rep(1,i,n-1){
		if(e.root(i)==e.root(0))f++;
		if(d.root(i)==d.root(n-1))s++;
	}	
	int t=f+s+2-n;
	if(f>s)c("Fennec")
	else if(s<f)c("Snuke")
