    G.at(B).push_back(A);
  }

  //フェネック
  vector<int> Fdist(N, -1);
  queue<int> que;

  Fdist.at(0) = 0;
  que.push(0);

  while( !que.empty() ){
    int v = que.front();
    que.pop();

    for( int nv : G.at(v) ){
      if( Fdist.at(nv) != -1 ) continue;
      Fdist.at(nv) = Fdist.at(v)+1;
      que.push(nv);
    }
  }

  //すぬけ
  vector<int> Sdist(N, -1);
  Sdist.at(N-1) = 0;
  que.push(N-1);

  while( !que.empty() ){
    int v = que.front();
    que.pop();

    for( int nv : G.at(v) ){
      if( Sdist.at(nv) != -1 ) continue;
      Sdist.at(nv) = Sdist.at(v)+1;
      que.push(nv);
    }
  }

  int snuke = 0;
  int fenne = 0;
  for( int i = 0; i < N; i++ ){
    if( Sdist.at(i) < Fdist.at(i) ) snuke++;
    else fenne++;
  }

  if( fenne > snuke ) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;
}

