    int n;
    cin >> n;
    vector<int> v[100100];
    rep(i, n-1){
        int a, b;
        cin >> a >> b;
        a--; b--;
        v[a].push_back(b);
        v[b].push_back(a);
    }
    int d[100100];
    d[0] = 0;
    fill(d, d + 100100, -1);
    queue<int> q;
    q.push(0);
    while(!q.empty()){
        int current_place = q.front();
        q.pop();
        for(int x : v[current_place]){
            if(d[x] >= 0) continue;
            d[x] = d[current_place] + 1;
            q.push(x);
        }
    }
    int color[100100];
    fill(color, color + 100100, -1);
    color[0] = 0;
    color[n-1] = 1;
    vector<int> path;
    path.push_back(n-1);
    while(!q.empty()) q.pop();
    q.push(n-1);

    //経路復元
    while(!q.empty()){
        int current_place = q.front();
        if(current_place == 0) break;
        q.pop();
        for(int x : v[current_place]){
            if(d[x] == d[current_place] - 1){
                q.push(x);
                path.push_back(x);
                break;
            }
        }
    }
    path.push_back(0);
    reverse(all(path));

    for(size_t i = 0; i < (path.size() + 1)/2; i++){
        color[path[i]] = 0;
    }
    for(size_t i = (path.size() + 1)/2; i < path.size(); i++){
        color[path[i]] = 1;
    }

    //着色
    int cnt_b = 1, cnt_w;
    while(!q.empty()) q.pop();
    q.push(0);
    bool used[100000];
    fill(used, used + 100000, false);
    used[0] = true;
    while(!q.empty()){
        int current_place = q.front();
        q.pop();
        for(int x : v[current_place]){
            if(color[x] == 1 || used[x]) continue;
            cnt_b++;
            color[x] = 0;
            q.push(x);
            used[x] = true;
        }
    }
    rep(i, n) if(color[i] == -1) color[i] = 1;
    cnt_w = n - cnt_b;
    if(cnt_w >= cnt_b) cout << "Snuke" << endl;
    else cout << "Fennec" << endl;
    //rep(i, n) printf("%d : %d\n", i+1, color[i]);
}

