struct edge {
    int to, cost;
    edge(int to, int cost): to(to), cost(cost) {}
};

constexpr double EPS = 1e-10;
//constexpr double PI  = acos(-1.0);
constexpr int INF = 10000000;

template<class T> inline T sqr(T x) {return x*x;}

template <typename T = pair<int, int>>
void Dijkstra(int s, vector<vector<edge>> g, VI &d) {
    int numv = d.size();
    priority_queue<T, vector<T>, greater<T>> q;
    for (int i = 0; i < numv; ++i) d[i] = INF;
    d[s] = 0;
    q.emplace(0,s);

    while (!q.empty()) {
        T p = q.top(); q.pop();
        int v = p.second; // vertex
        if (d[v] < p.first) continue;
        for (int i = 0; i < g[v].size(); ++i) {
            edge e = g[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                q.emplace(d[e.to], e.to);
            }
        }
    }
}

void solve() {
    int n;
    cin >> n;
    vector<vector<edge>> es(n);
    VI d1(n), d2(n);
    int a,b;
    REP(i,0,n-1) {
        cin >> a >> b;
        es[a-1].pb(b-1,1);
        es[b-1].pb(a-1,1);
    }
    Dijkstra(0,es,d1);
    Dijkstra(n-1,es,d2);
    int cnt[2] = {};
    //REP(i,0,n) cerr << d1[i] << " " << d2[i] << endl;
    REP(i,0,n) cnt[d1[i] <= d2[i] ? 0 : 1]++;
    if (cnt[0] >= cnt[1]) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;
}

int main() {
    solve();

    return 0;
}

