		if(min(a,b)>0)d.unite(a,b);
		if(max(a,b)<n-1)e.unite(a,b);
	}		
	rep(1,i,n-1){
		if(e.root(i)==e.root(0))f++;
		if(d.root(i)==d.root(n-1))s++;
	}	
	int t=(f+s+2)-n;
	f-=t,s-=t;
	if(f>s)c("Fennec")
	else if(s<f)c("Snuke")
	else{
		c(s/(t-t))
		if(t%2==0)c("Snuke")
		else c("Fennec")
	}
}

