struct edge {
    int to;
};

int N;

vector<vector<edge>> v;

bool search(vector<int>& p, int par) {
    int cur = p.back();
    if(cur == N-1) return true;
    for(auto& it : v[cur]){
        if(it.to == par) continue;
        p.push_back(it.to);
        if(search(p, cur)) return true;
        p.pop_back();
    }
    return false;
}

int count(int cur, int par, int wh) {
    if(cur == wh) return 0;
    int a = 0;
    for(auto& it : v[cur]){
        if(it.to == par) continue;
        a += count(it.to, cur, wh);
    }
    return a+1;
}

