        v[a].push_back(edge{b});
        v[b].push_back(edge{a});
    }
    // search a path from 0 to N-1
    vector<int> path;
    path.push_back(0);
    search(path, -1);
    int wh = (path.size()+1)/2; // bound
    int f = count(0, -1, path[wh]);
    int s = N-f;
    cout << (f > s ? "Fennec" : "Snuke") << endl;
    return 0;
}

