        ll a, b; cin >> a >> b;
        a--; b--;
        ed[a].pb({b,1}); ed[b].pb({a,1});
    }
    auto df = dijkstra(0);
    auto ds = dijkstra(N-1);

    ll cnt = 0;
    REP(i, N){
        if(df[i] <= ds[i]) cnt++;
    }
    cout << (cnt >= N/2+1 ? "Fennec" : "Snuke") << endl;
    return 0;
}

