class D {
	vvi g;
	int n;
	vi col;
	vi from;
	deque<int> sf;
public:
	D()
	{
		cin >> n;
		g.resize(n);
		from.resize(n, -1);
		col.resize(n, -1);

		REP(i, n - 1)
		{
			int a, b;
			cin >> a >> b;
			a--; b--;
			g[a].PB(b);
			g[b].PB(a);
		}
	}

	void dfs_path(int v, int frm)
	{

		from[v] = frm;

		if (v == n - 1)
			return;

		for (int nxt : g[v])
			if (nxt != frm)
				dfs_path(nxt, v);
	}


	void dfs(int v, bool p, int frm)
	{
		col[v] = p;

		for (int nxt : g[v])
			if (nxt != frm && col[nxt] != (!p) )
				dfs(nxt, p, v);
	}

	void solve()
	{
		dfs_path(0, -1);

		int v = n - 1;
		while (v != 0)
		{
			sf.push_front(v);
			v = from[v];

		}
		sf.push_front(0);

		bool p = false;
		while (!sf.empty())
		{
			if (!p)
			{
				col[sf.front()] = p;
				sf.pop_front();
			}

			else
			{
				col[sf.back()] = p;
				sf.pop_back();
			}

			p = !p;
		}


		dfs(0, 0, -1);
		dfs(n - 1, 1, -1);

		int cnt0, cnt1;
		cnt0 = cnt1 = 0;

		REP(i, n)
		{
			if (col[i] == 0)
				++cnt0;
			else
