            int nxt_v=g[now_v][i];

            if(visited[nxt_v] == false){
                visited[nxt_v]=true;
                que.push(P(nxt_v, cost+1));
            }
        }
    }
}

void black_paint(int x){
    queue<P> que;
    que.push(P(0, 0));
    black[0]=true;

    while(!que.empty()){
        P q=que.front(); que.pop();
        int now_v=q.first, cost=q.second;

        if(cost == x) continue;

        for(int i=0; i<g[now_v].size(); i++){
            int nxt_v=g[now_v][i];

            if(black[nxt_v] == false){
                black[nxt_v]=true;
                que.push(P(nxt_v, cost+1));
            }
        }
    }
}

int white_paint(){
    queue<int> que;
    que.push(n-1);
    white[n-1]=true;

    int cnt=1;
    while(!que.empty()){
        int now_v=que.front(); que.pop();

        for(int i=0; i<g[now_v].size(); i++){
            int nxt_v=g[now_v][i];

            if(white[nxt_v] == false && black[nxt_v] == false){
                cnt++;
                white[nxt_v]=true;
                que.push(nxt_v);
            }
        }
    }
    return cnt;
}

