vector<ll> bfs(vector<ll> path, ll v, vector<ll> visited) {
	queue<ll> q = queue<ll>();
	path.push_back(v);
	visited[v] = 0;
 	for (auto& nv : edge[v]) {
		if (nv == edge.size() - 1) {
			path.push_back(nv);
			return path;
		}
		if (visited[nv] == -1) {
			q.push(nv);
		}
	}
	while (q.size() > 0) {
		ll nv = q.front();
		visited[nv] = 0;
		vector<ll> p = bfs(path, nv,visited);
		visited[nv] = -1;
		q.pop();
		if (p[0] != -1) return p;
	}
	return vector<ll>(1, -1);

}

