		edge[a - 1].push_back(b - 1);
		edge[b - 1].push_back(a - 1);
	}
	vector<ll> path = bfs(vector<ll>(), 0, vector<ll>(n,-1));
	vector<ll> vOwner = vector<ll>(n,-1);
	ll length = path.size();
	rep(i, 0, length - length / 2) {
		vOwner[path[i]] = 0;
	}
	rep(i, 0, length / 2) {
		vOwner[path[length - 1 - i]] = 1;
	}
	queue<ll> q = queue<ll>();
	for (auto& v : edge[0]) {
		q.push(v);
	}

	while (q.size() > 0) {
		ll v = q.front();
		q.pop();
		if (vOwner[v] != 1) {
			if (vOwner[v] == -1) {
				for (auto& nv : edge[v]) {
					q.push(nv);
				}
			}			
			vOwner[v] = 0;

		}
	}

    q = queue<ll>();
	for (auto& v : edge[n-1]) {
		q.push(v);
	}

	while (q.size() > 0) {
		ll v = q.front();
		q.pop();
		if (vOwner[v] != 0) {
			if (vOwner[v] == -1) {
				for (auto& nv : edge[v]) {
					q.push(nv);
				}
			}
			vOwner[v] = 1;

		}
	}

	ll fCount = 0;
	ll sCount = 0;
	rep(i, 0, n) {
		if (vOwner[i] == 0)fCount++;
		else if(vOwner[i] == 1)sCount++;
	}
	if (fCount > sCount) cout << "Fennec" << endl;
	else cout << "Sunuke" << endl;
}

