bool used[MAX_N];

int search(int me,int enemy){
  //自分の領地と相手との領域を探索する
  fill(used,used+MAX_N,false);
  stack<P> st;
  st.push(P(me,0));
  int cnt=0;
  while(!st.empty()){
    P p = st.top();
    int x=p.first;
    st.pop();
    if(used[x]||x==enemy||dist[x]<=p.second) continue;
    used[x]=true;
    dist[x]=p.second;
    cnt++;
    for(auto y:graph[x]) st.push(P(y,p.second+1));
  }
  return cnt;
}

