	g.resize(n);
	depth_f.resize(n);
	depth_s.resize(n);

	rep(i,n) {
		depth_f[i] = -1;
		depth_s[i] = -1;
	}

	rep(i, n - 1) {
		int a, b;
		cin >> a >> b;
		a--, b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	queue <int> q;
	depth_f[0] = 0;
	q.push(0);

	while (!q.empty()) {
		int nd = q.front();
		q.pop();

		rep(i,g[nd].size()) {
			if (depth_f[g[nd][i]] < 0) {
				depth_f[g[nd][i]] = depth_f[nd] + 1;
				q.push(g[nd][i]);
			}
		}
	}


	depth_s[n-1] = 0;
	q.push(n-1);
	while (!q.empty()) {
		int nd = q.front();
		q.pop();

		rep(i, g[nd].size()) {
			if (depth_s[g[nd][i]] < 0) {
				depth_s[g[nd][i]] = depth_s[nd] + 1;
				q.push(g[nd][i]);
			}
		}
	}


	int f = 0;
	int s = 0;


	rep(i, n) {
		if (depth_s[i] >= depth_f[i]) {
			f++;
		}
		else {
			s++;
		}
	}
	cout << f << " " << s << endl;

	if (f > s) {
		cout << "Fennec" << endl;
	}
	else {
		cout << "Snuke" << endl;
	}





	return 0;
}

