const int max_n = 100011, log_n = 32, max_m = 111, mod = 1000000007, inf = 1000111222;

int n, d1[max_n], d2[max_n], d3[max_n], path[max_n], mx1[max_n], mx2[max_n];
vector<int> v[max_n], g;

int dfs(int x, int p) {
    if (x == n - 1) {
        path[x] = 1;
        d2[x] = 0;
        for (int i = 0; i < v[x].size(); ++i) {
            if (v[x][i] == p) continue;
            d3[x] = max(d3[x], dfs(v[x][i], x));
        }
        g.push_back(x);
        return 0;
    }
    for (int i = 0; i < v[x].size(); ++i) {
        if (v[x][i] == p) {
            continue;
        }
        d1[v[x][i]] = d1[x] + 1;
        int k = dfs(v[x][i], x);
        if (path[v[x][i]]) {
            path[x] = 1;
            d2[x] = d2[v[x][i]] + 1;
            g.push_back(x);
        } else {
            d3[x] = max(d3[x], k);
        }
    }
    return d3[x] + 1;
}

