        f--; g--;
        v[f].push_back(g);
        v[g].push_back(f);
    }
    dfs(0, -1);
    reverse(g.begin(), g.end());
    for (int i = 0; i < g.size(); ++i) {
        mx1[i] = d1[g[i]] + d3[g[i]];
        int x = g[g.size() - 1 - i];
        mx2[i] = d2[x] + d3[x];
        if (i) {
            mx1[i] = max(mx1[i], mx1[i - 1]);
        }
        if (x != g.size() - 1) {
            mx2[x] = max(mx2[x], mx2[x + 1]);
        }
    }
    //for (int i = 0;)
    bool win;
    if (g.size() % 2 == 1) {
        win = 0;
    } else {
        win = 1;
    }

    if (g.size() % 2 == 1) {
        for (int i = g.size() - 1; i >= g.size() / 2 + 1; --i) {
            int x = g[i];
            if (d2[x] + d3[x] >= mx1[i - 1]) {
                win = 1;
            }
        }
        write(win);
    } else {
        for (int i = 0; i < g.size() / 2; ++i) {
            int x = g[i];
            if (d1[x] + d3[x] > mx2[i + 1]) {
                win = 0;
            }
        }
        write(win);
    }
    return 0;
}

