    vector<vector<ll>> G(N);
    for(int i = 0; i < N-1;i++){
        ll a,b; cin >> a >> b;
        a--; b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    vector<ll> Fennec(N,-1),Snuke(N,-1);
    dfs(0,0,Fennec,G);
    dfs(N-1,0,Snuke,G);

    ll Fennec_have = 0, Snuke_have = 0;
    for(int i = 0; i < N;i++){
        if(Fennec[i] <= Snuke[i]) Fennec_have++;
        else Snuke_have++;
    }
    if(Fennec_have > Snuke_have){
        cout << "Fennec" << endl;
    }else{
        cout << "Snuke" << endl;
    }
    return 0;
}

