void init()
{
	for(int i = 1; i <= n ;i ++){
		G[i].clear();
		fa[i] = -1;
		co[i] = 0;				//无色 
		visit[i] = false;
		flag = 0;
	}
	co[1] = -1;					//黑 
	co[n] = 1;					//白 
}

void dfs(int x)
{
	if(x == n){
		flag = 1;				//找到了 
		return ;	
	}	

	int tmp;
	for(int i = 0; i < G[x].size() ;i ++){
		if(flag == 1){
			break;
		}

		tmp = G[x][i];
		if(visit[tmp] == true){
			continue;
		}
		fa[tmp]	= x;
		visit[tmp] = true;
		dfs(tmp);	
		//visit[tmp] = false;
	}
} 

void dfs1(int x)
{
	int tmp;
	for(int i = 0; i <G[x].size() ;i ++){
		tmp = G[x][i];
		if(visit[tmp] == false && (co[tmp] == 0 || co[tmp] == -1)){
			ans1 ++;
			co[tmp] = -1;
			visit[tmp] = true;
			dfs(tmp);
		}
	}

} 

void dfs2(int x)
{
	int tmp;
	for(int i = 0; i <G[x].size() ;i ++){
		tmp = G[x][i];
		if(visit[tmp] == false && (co[tmp] == 0 || co[tmp] == 1)){
			ans2 ++;	
			co[tmp] = 1;
			visit[tmp] = true;
			dfs(tmp);
		}
	}

}

