void dfs(lint node, vec<vec<lint>>& adj, vec<lint>& dist) {
    for (const auto neighbor : adj.at(node)) {
        if (dist.at(neighbor) == -1) {
            dist.at(neighbor) = dist.at(node) + 1;
            dfs(neighbor, adj, dist);
        }
    }
    return;
}

int main() {
    cin.tie(0); cout.tie(0);
    ios::sync_with_stdio(false);
    lint N;
    cin >> N;
    vec<vec<lint>> adj(N, vec<lint>());
    range(i, 0, N - 1) {
        lint a, b;
        cin >> a >> b;
        a--; b--;
        adj.at(a).emplace_back(b);
        adj.at(b).emplace_back(a);
    }
    vec<lint> dist_from_broot(N, -1), dist_from_wroot(N, -1);
    dist_from_broot.at(0) = 0;
    dist_from_wroot.at(N - 1) = 0;
    dfs(0, adj, dist_from_broot);
    dfs(N - 1, adj, dist_from_wroot);
    lint black_territory = 0, white_territory = 0;
    bool midpoint_exists = false;
    range(i, 0, N) {
        lint db = dist_from_broot.at(i);
        lint dw = dist_from_wroot.at(i);
        if (db < dw) black_territory += 1;
        else if (db > dw) white_territory += 1;
        else midpoint_exists = true;
    }
    bool fennec_wins;
    if (black_territory != white_territory) {
        fennec_wins = black_territory > white_territory;
    } else {
        fennec_wins = midpoint_exists;
    }
    cout << (fennec_wins ? "Fennec" : "Snuke") << "\n";
}

