const int INF = 20000000;

int main() {
  int n;in(n);
  vector<int> G[n];
  loop(i,0,n-1) {
    int a, b; in(a),in(b);
    a--;b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  int s = 0, t = n-1;
  vector<int> fromS(n, INF), fromT(n, INF);
  {
    queue<int> Q;
    Q.push(0);
    fromS[0] = 0;
    while (Q.size()) {
      int v = Q.front(); Q.pop();
      for (auto &&u: G[v]) {
        if (fromS[u] != INF) continue;
        fromS[u] = fromS[v] + 1;
      }
    }
  }
  {
    queue<int> Q;
    Q.push(0);
    fromT[t] = 0;
    while (Q.size()) {
      int v = Q.front(); Q.pop();
      for (auto &&u: G[v]) {
        if (fromT[u] != INF) continue;
        fromT[u] = fromT[v] + 1;
      }
    }
  }

  vector<bool> done(n, false);
  priority_queue<pair<int, int> > Qs, Qt;
  Qs.push({ fromT[s], s });
  Qt.push({ fromS[t], t });
  while (Qs.size() and Qt.size()) {
    auto qs = Qs.top(); Qs.pop();
    auto qt = Qt.top(); Qt.pop();
    done[qs.second] = true;
    done[qt.second] = true;
    // print("Fennec", " ");
    // print(qs.second);
    // print("Snuke", " ");
    // print(qt.second);
    {
      for (auto &&u: G[qs.second]) {
        if (done[u]) continue;
        Qs.push({ fromT[u], u }); // Tに近い方から取る.
      }
    }
    {
      for (auto &&u: G[qt.second]) {
        if (done[u]) continue;
        Qt.push({ fromS[u], u }); // Sに近い方から取る.
      }
    }
  }

  if (Qs.size()) print("Fennec");
  else print("Snuke");
  return 0;
}

