    for (int i = 0; i < G[u].size(); i++) {
        if (d[G[u][i]] == -1) {
            d[G[u][i]] = d[u] + 1;
            dfs(G[u][i],d,G,N);
        }
    }
}


int main() {
    int N; cin >> N;
    int res = 0;
    vector<vector<int> > G(N, vector<int> {});
    vector<int> d1(N,-1), d2(N,-1);
    for (int i = 0; i < N-1; i++) {
        int a, b; cin >> a >> b;
        G[a-1].push_back(b-1);
        G[b-1].push_back(a-1);
    }

    d1[0] = d2[N-1] = 0;
    dfs(0,d1,G,N);
    dfs(N-1,d2,G,N);
    for (int i = 0; i < N; i++) {
        if (d1[i] > d2[i]) res++;
    }
    if (N % 2 == 0) {
    if (res < N/2) {
        cout << "Fennec\n";
    } else {
        cout << "Snuke\n";
    }
    } else {
    if (res <= N/2) {
        cout << "Fennec\n";
    } else {
        cout << "Snuke\n";
    }
    }
}

