// 木上のクエリを処理
// ・作成(O(n log n))
// ・ノード間の距離(O(log n))
// ・直径・中心(O(log n))
// ・最小共通素性(O(log n))
// ・ノード間の最大の重み(O(log n))
class QueryOnTree {
private:
    int n;

    int log_v = 0;
    std::vector<std::unordered_map<int, int>> parent;        // 2^k個上の親
    std::vector<std::unordered_map<int, int>> max_weight;    // 2^k個上の親までにでてくる最大の重み
    std::unordered_map<int, int> depth;                      // 各頂点についての根からの深さ
    std::unordered_map<int, long long> distance_from_root;   // 根からの距離
    bool done = false;

public:
    std::unordered_map<int, std::vector<std::pair<int, int>>> tree;

public:
    QueryOnTree() {

    }

    // 無向グラフの場合はu->vとv->uの両方をいれること
    void set_tree(const std::unordered_map<int, std::vector<std::pair<int, int>>> &t) {
        assert(not done);
        this->tree = t;
    }

    // 無向グラフの場合はu->vとv->uの両方をいれること
    void add_edge(int u, int v, int w) {
        assert(not done);
        tree[u].emplace_back(std::make_pair(v, w));
    }

    void build(int root) {
        this->done = true;

        this->n = tree.size();
        if (n == 0) {
            return ;
        }

        this->log_v = int(log2(n)) + 1;
        this->parent = std::vector<std::unordered_map<int, int>>(log_v);
        this->max_weight = std::vector<std::unordered_map<int, int>>(log_v);
        this->distance_from_root[root] = 0;

        dfs(root, -1, 0, 0);

        for (int k = 0; k + 1 < this->log_v; k++) {
            for (const auto &p : tree) {
                int u = p.first;
                if (parent[k][u] < 0) {
                    parent[k + 1][u] = -1;
                }
                else {
                    parent[k + 1][u] = parent[k][parent[k][u]]; // uの2^k個上のノードの2^k上のノードはuの2^(k+1)個上のノード
                    if (parent[k + 1][u] >= 0) {
                        max_weight[k + 1][u] = std::max(max_weight[k][u], max_weight[k][parent[k][u]]);
                    }
                }
            }
        }
    }

    // uとvの距離
    long long distance(int u, int v) {
        return distance_from_root[u] + distance_from_root[v] - 2 * distance_from_root[lca(u, v)];
    }

    // 木の直径
    long long diameter() {
        // node 0から一番遠いnode
        int u = 0;
        long long max_distance = -1;
        for (const auto &p : tree) {
            auto node = p.first;
            auto dist = this->distance(0, node);
            if (dist > max_distance) {
                max_distance = dist;
                u = node;
            }
        }

        // node uから一番遠いnode
        long long diameter = 0;
        for (const auto &p : tree) {
            auto node = p.first;
            auto dist = this->distance(u, node);
            if (dist > diameter) {
                diameter = dist;
            }
        }

        return diameter;
    }

    // 木の直径のパス
    std::vector<int> diameter_route() {
        // node 0から一番遠いnode
        int u = 0;
        long long max_distance = -1;
        for (const auto &p : tree) {
            auto node = p.first;
            auto dist = this->distance(0, node);
            if (dist > max_distance) {
                max_distance = dist;
                u = node;
            }
        }

        // node uから一番遠いnode
        long long diameter = 0;
        int v = -1;
        for (const auto &p : tree) {
            auto node = p.first;
            auto dist = this->distance(u, node);
            if (dist > diameter) {
                diameter = dist;
                v = node;
            }
        }

        return this->route(u, v);
    }

    // uからvへいくルートを取得 O(n)
    std::vector<int> route(const int u, const int v) {

        // get v -> u path
        std::unordered_map<int, int> prev;
        std::unordered_map<int, long long> dist;
        dist[v] = 0;
        std::stack<int> nodes;
        nodes.push(v);
        while (not nodes.empty()) {
            const auto node = nodes.top(); nodes.pop();
            if (node == u) {
                break;
            }

            for (const auto &p : tree[node]) {
                if (prev.find(p.first) == prev.end()) {
                    prev[p.first] = node;
                    dist[p.first] = dist[node] + p.second;
                    nodes.push(p.first);
                }
            }
        }

        std::vector<int> route = {u};
        int now = u;
        while (prev[now] != v) {
            now = prev[now];
            route.emplace_back(now);
        }
        route.emplace_back(v);

        return route;
    }

    // 木の中心
    int center() {
        std::vector<int> route = this->diameter_route();
        return route[route.size() / 2];
    }

    // uとvの間で出現する最大の重み
    int maximum_weight(int u, int v) {
        int lca = this->lca(u, v);
        return std::max(this->maximum_weight_ancestor(u, lca), this->maximum_weight_ancestor(v, lca));
    }

    // uとvの最近共通祖先(O(log n))
    int lca(int u, int v) {
        if (depth[u] > depth[v]) {
            std::swap(u, v);
        }
        for (int k = 0; k < this->log_v; ++k) {
            if ((depth[v] - depth[u]) >> k & 1) {
                v = parent[k][v];
            }
        }

        if (u == v) {
            return u;
        }

        for (int k = this->log_v - 1; k >= 0; --k) {
            if (parent[k][u] != parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }

private:
    // 各頂点について，1つ上の親，1つ上の重み，根からの深さ，根からの距離を求める
    void dfs(int u, int p, int d, int w) {
        parent[0][u] = p;
        max_weight[0][u] = w;
        depth[u] = d;

        for (const auto &a : tree[u]) {
            int v = a.first;
            int dist = a.second;
            if (v != p) {
                distance_from_root[v] = distance_from_root[u] + dist;
                dfs(v, u, d + 1, dist);
            }
        }
    }

    // uとuの祖先の間の最大の重みを取得
    int maximum_weight_ancestor(int u, int ancestor) {
        int res = -INF;
        int d = depth[u] - depth[ancestor];
        for (int k = 0; k < log_v; k ++) {
            if ((d >> k) & 1) {
                res = std::max(res, max_weight[k][u]);
                u = parent[k][u];
            }
        }
        return res;
    }
};

