vector<int> color;

bool DFS(int v, int parent, vector<int>& vertices) {
  for (int i = 0; i < G[v].size(); i++) {
    int v2 = G[v][i];
    if (v2 == parent) continue;
    if (v2 == N - 1) {
      vertices.push_back(v2);
      vertices.push_back(v);
      return true;
    } else {
      if (DFS(v2, v, vertices)) {
        vertices.push_back(v);
        return true;
      }
    }
  }
  return false;
}

void DFS2(int v, int parent, int c) {
  for (int i = 0; i < G[v].size(); i++) {
    int v2 = G[v][i];
    if (v2 == parent or color[v2] != -1) continue;
    color[v2] = c;
    DFS2(v2, v, c);
  }
}

