  reverse(vertices.begin(), vertices.end());

  int K = vertices.size();
  for (int i = 0; i < K; i++) color[vertices[i]] = (i < (K + 1) / 2) ? 0 : 1;
  for (int i = 0; i < K; i++) DFS2(vertices[i], -1, color[i]);
  DFS2(0, -1, 0);
  DFS2(N - 1, -1, 1);

  int count0 = 0;
