const int INF = 20000000;

int main() {
  int n;in(n);
  vector<int> G[n];
  loop(i,0,n-1) {
    int a, b; in(a),in(b);
    a--;b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  int s = 0, t = n-1;
  vector<int> fromS(n, INF), fromT(n, INF);
  {
    queue<int> Q;
    Q.push(s);
    fromS[s] = 0;
    while (Q.size()) {
      int v = Q.front(); Q.pop();
      for (auto &&u: G[v]) {
        if (fromS[u] != INF) continue;
        fromS[u] = fromS[v] + 1;
      }
    }
  }
  {
    queue<int> Q;
    Q.push(t);
    fromT[t] = 0;
    while (Q.size()) {
      int v = Q.front(); Q.pop();
      for (auto &&u: G[v]) {
        if (fromT[u] != INF) continue;
        fromT[u] = fromT[v] + 1;
      }
    }
  }

  int cnt = 0;
  loop(i,0,n) {
    // TよりもSに近いところはFが取れる.
    cnt += fromS[i] <= fromT[i];
  }
  int cntT = n-cnt;
  if (cnt > cntT) print("Fennec");
  else print("Snuke");
  return 0;

  vector<bool> done(n, false);
  priority_queue<pair<int, int> > Qs, Qt;
  Qs.push({ fromT[s], s });
  Qt.push({ fromS[t], t });
  while (Qs.size() and Qt.size()) {
    auto qs = Qs.top(); Qs.pop();
    while (done[qs.second] and Qs.size()) {
      qs = Qs.top(); Qs.pop();
    }
    if (done[qs.second]) {
      print("Snuke");
      return 0;
    }
    done[qs.second] = true;

    auto qt = Qt.top(); Qt.pop();
    while (done[qt.second] and Qt.size()) {
      qt = Qt.top(); Qt.pop();
    }
    if (done[qt.second]) {
      print("Fennec");
      return 0;
    }
    done[qt.second] = true;

    // print("Fennec", " ");
    // print(qs.second+1);
    // print("Snuke", " ");
    // print(qt.second+1);
    {
      for (auto &&u: G[qs.second]) {
        if (done[u]) continue;
        Qs.push({ -fromT[u], u }); // Tに近い方から取る.
      }
    }
    {
      for (auto &&u: G[qt.second]) {
        if (done[u]) continue;
        Qt.push({ -fromS[u], u }); // Sに近い方から取る.
      }
    }
  }

  if (Qs.size()) print("Fennec");
  else print("Snuke");
  return 0;
}

