                {
                    if (color[next] != 0) continue;
                    color[next] = 1;
                    q1.Enqueue(next);
                }
            }
            if (q2.Count > 0)
            {
                var now = q2.Dequeue();
                foreach (var next in g[now])
                {
                    if (color[next] != 0) continue;
                    color[next] = 2;
                    q2.Enqueue(next);
                }
            }
        }

        var c1 = color.Count(c => c == 1);
        var c2 = N - c1;
        if (c1 > c2)
        {
            Console.WriteLine("Fennec");
        }
        else
        {
            Console.WriteLine("Sunuke");
        }

    }

    static Scanner sc = new Scanner();
}
