int dijkstra(){
	pq<P, vector<P>, greater<P>> que;
	REP(i,0,n) min_cost[i]=INF;
	que.emplace(0,0);
	min_cost[0]=0;

	while(!que.empty()){
		auto p=que.top(); que.pop();
		if(p.first>min_cost[p.second]) continue;

		for(auto e:g[p.second]){
			if(p.first+e.second>=min_cost[e.first]) continue;
			min_cost[e.first]=p.first+e.second;
			que.emplace(min_cost[e.first], e.first);
		}
	}

	return 0;
}

int dijkstra2(){
	pq<P, vector<P>, greater<P>> que;
	REP(i,0,n) min_cost2[i]=INF;
	que.emplace(0,n-1);
	min_cost2[n-1]=0;

	while(!que.empty()){
		auto p=que.top(); que.pop();
		if(p.first>min_cost2[p.second]) continue;

		for(auto e:g[p.second]){
			if(p.first+e.second>=min_cost[e.first]) continue;
			min_cost2[e.first]=p.first+e.second;
			que.emplace(min_cost[e.first], e.first);
		}
	}

	return 0;
}

