	dijkstra(); dijkstra2();

	int c=0,f=0,s=0;
	REP(i,0,n){
		if(min_cost[i]==min_cost2[i]) c++;
		else if(min_cost[i]<min_cost2[i]) f++;
		else if(min_cost[i]>min_cost2[i]) s++;
	}

