	return 0;
}

#include <bits/stdc++.h>

using namespace std;

void dijkstra(int start, vector<int> &costs,
              unordered_map<int, vector<int>> &edges) {
  priority_queue<pair<int, int>, vector<pair<int, int>>,
                 greater<pair<int, int>>>
      q;
  costs[1] = start;
  q.push(make_pair(0, start));
  while (!q.empty()) {
    auto v = q.top();
    q.pop();
    for (const auto &e : edges[v.second]) {
      if (v.second + 1 < costs[e]) {
        costs[e] = v.second + 1;
        q.push(make_pair(costs[e], e));
      }
    }
  }
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);

  int n;
  cin >> n;
  unordered_map<int, vector<int>> e;
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;
    e[a].emplace_back(b);
    e[b].emplace_back(a);
  }
  vector<int> white(n + 1, INT_MAX);
  dijkstra(1, white, e);
  vector<int> black(n + 1, INT_MAX);
  dijkstra(n, black, e);

  vector<int> board(n + 1, 0);
  for (int i = 1; i < n + 1; ++i) {
    if (white[i] < black[i]) {
      board[i] = 2;
    } else {
      board[i] = 1;
    }
  }

  int blacks = count(board.begin(), board.end(), 1),
      whites = count(board.begin(), board.end(), 2);
  if (whites < blacks) {
    cout << "Fennec\n";
  } else {
    cout << "Snuke\n";
  }
}

