int main() {
  int N;
  cin >> N;

  vector<vector<int>> nvec;
  int check[100000];
  for (int i = 0; i < N; i++) {
    vector<int> temp;
    nvec.push_back(temp);
    check[i] = 0;
  }
  check[0] = check[N-1] = 1;

  for (int i = 0; i < N-1; i++) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    nvec.at(a).push_back(b);
    nvec.at(b).push_back(a);
  }

  set<int> vB, vW;
  vB.insert(0);
  vW.insert(N-1);
  int cB, cW;
  cB = cW = 1;
  while(1) {
    /*
    cout << "vB: ";
    for (auto x: vB) cout << x << " ";
    cout << endl;
    cout << "vW: ";
    for (auto x: vW) cout << x << " ";
    cout << endl;
