    for (auto x: vB) {
      bool isfound = false;
      for (auto y: nvec.at(x)) {
	if (check[y] == 0) {
	  isfound = true;
	  vB.insert(y);
	  check[y] = 1;
	  tempB++;
	}
      }
      if (!isfound) delB.push_back(x);
    }
    for (auto x: delB) vB.erase(x);

    for (auto x: vW) {
      bool isfound = false;
