	color[N]=-1;

	int ret1=0;
	int ret2=0;
	int Fennec_pos=1;
	int Snuke_pos=N;

	int turn=0;

	while(1){
		if(turn%2==0){
			ret1=root(0,Fennec_pos);
			if(ret1!=-1){Fennec_pos=ret1;}
		}
		else{
			ret2=root(1,Snuke_pos);
			if(ret2!=-1){Snuke_pos=ret2;}
		}
		if(ret1==-1&&ret2==-1){break;}
		turn++;
	}

	dfs2(1,Fennec_pos);
	dfs2(1,1);
	dfs2(0,Snuke_pos);
	dfs2(0,N);

	int ans=0;

	for(i=1;i<=N;i++){
		ans+=color[i];
	}
	if(ans>0){printf("Fennec\n");}
	else{printf("Snuke\n");}

	return 0;
}

