bool bio[N];
int count(int u) {
	bio[u] = true;
	int ret = 1;
	for (int v: g[u]) {
		if (bio[v]) continue;
		if (u == b && c[1][v] < c[1][u]) continue;
		ret += count(v);
	}
	return ret;
}

void solve() {
	int n; scanf("%d", &n);
	for (int i = 0; i < n-1; ++i) {
		int a, b; scanf("%d%d", &a, &b);
		g[--a].push_back(--b);
		g[b].push_back(a);
	}
	dfs(0, 0);
	dfs(n-1, 1);
	for (int i = 1; i < n-1; ++i) {
		if (c[0][i] == c[1][i]) {
			b = i;
			break;
		}
		if (c[1][i]-c[0][i] == 1) {
			b = i;
			break;
		}
	}
	int ans = count(0);
	debug(ans);
	printf(ans>n-ans?"Fennec":"Snuke");
}

int main() {
	init();
	int t = 1; //scanf("%d", &t);
	while (t--) {
		solve();
	}
	return 0;
}

