using EDGE = vector<vector<ll>>;

enum class Color {
    None,
    Black,
    White,
};

void solve(long long N, std::vector<long long> a, std::vector<long long> b)
{
    EDGE edges(N + 1);
    for (ll i = 0; i < N - 1; i++) {
        edges[a[i]].push_back(b[i]);
        edges[b[i]].push_back(a[i]);
    }

    vector<Color> colors(N + 1, Color::None);
    queue<pair<ll, Color>> que;

    auto mov = [&que, &colors](ll v, Color c) {
        que.emplace(v, c);
        colors[v] = c;
    };

    mov(1, Color::Black);
    mov(N, Color::White);

    while (!que.empty()) {
        auto a = que.front();
        que.pop();
        auto v = a.first;
        auto c = a.second;
        for (auto&& e : edges[v]) {
            if (colors[e] == Color::None) {
                mov(e, c);
            }
        }
    }

    auto black = count(begin(colors), end(colors), Color::Black);
    auto white = count(begin(colors), end(colors), Color::White);
    if (black > white) {
        cout << "Fennec\n";
    } else {
        cout << "Snuke\n";
    }
}

