using namespace std;

class Leaf{
public:
	// その葉(節点)の番号
	int x;
	// 親
	int parent;
	// 親+子のリスト
	vector<int> pc;
	// 訪問された？
	bool visit;
	// 1からの距離
	int fromone;
	// nからの距離
	int fromn;

	Leaf(int x){
		this->x = x;
		visit = false;
		parent = -1;
	}
};

vector<Leaf> depthFirstSerch(vector<Leaf> v, int x){
	vector<int> stack;
	int p = x - 1;
	v[p].visit = true;
	// 根だけは例外処理
	// 自身の親を自身にし、距離を-1に(のちのループで0になる)
	v[p].parent = p;
	if (x == 1) {
		v[p].fromone = -1;
	} else {
		v[p].fromn = -1;
	}
	// スタック
	stack.push_back(v[p].x);

	while (!stack.empty()) {
		p = stack[stack.size()-1];
		stack.pop_back();
		// 処理
		if (x == 1) {
			v[p].fromone = v[v[p].parent].fromone + 1;
		} else {
			v[p].fromn = v[v[p].parent].fromn + 1;
		}
		// pに接続している接点
		for (size_t i = 0; i < v[p].pc.size(); i++) {
			// 訪問されてなかったら
			if (!v[v[p].pc[i]].visit) {
				// 親の設定
				v[v[p].pc[i]].parent = p;
				// 訪問済みにする
				v[v[p].pc[i]].visit = true;
				// スタックに積む
				stack.push_back(v[p].pc[i]);
			}
		}
	}

	return v;
}

int main(int argc, char const *argv[]) {
	int n,temp1,temp2;
	cin >> n;
	vector<Leaf> v;
	for (size_t i = 0; i < n; i++) {
		v.push_back(Leaf(i));
	}
	for (size_t i = 0; i < n-1; i++) {
		cin >> temp1 >> temp2;
		temp1--;
		temp2--;
		v[temp1].pc.push_back(temp2);
		v[temp2].pc.push_back(temp1);
	}

	// 1から深さ優先探索
	v = depthFirstSerch(v, 1);
	// 親と訪問済みを初期化
	for (size_t i = 0; i < n; i++) {
		v[i].parent = -1;
		v[i].visit = false;
	}
	// nから深さ優先探索
	v = depthFirstSerch(v, n);

	int white,black;
	white = black = 0;
	for (size_t i = 0; i < n; i++) {
		if (v[i].fromone <= v[i].fromn) {
			black++;
		}
		else {
			white++;
		}
	}
	if (black > white) {
		cout << "Fennec" << '\n';
	}
	else {
		cout << "Snuke" << '\n';
	}
	return 0;
}

