void solve(){
    queue<int> q;
    q.push(1);
    vector<int> used(N+1,-1);
    used[1] = 0;
    while(!q.empty()){
        int now = q.front();q.pop();
        for(int next : adj[now]){
            if(used[next]==-1){
                used[next] = now;//どこからやってきたのかを格納
                q.push(next);
            }
        }
    }

    //フェネックとすぬけくんの初期位置の距離を求める
    //きた道を逆にたどって距離を求める
