        now = used[now];
        dist_1_to_N++;
    }

    queue<int> p;

    vector<int> color(N+1,-1);//0なら黒、1なら白とする
    color[1] = 0;color[N] = 1;
    //フェネックとすぬけくんの間に色を塗る
    int vertex = N;
    int numof_white = dist_1_to_N/2;
    while(vertex!=1){
        vertex = used[vertex];
        color[vertex] = (numof_white>=1);
        if(numof_white>=1) p.push(vertex);
        numof_white--;
    }

    p.push(N);
    while(!p.empty()){
        int now = p.front();p.pop();
