#include <bits/stdc++.h>
using namespace std;

template<typename T> class Dijkstra {
public:
  struct edge {
    int to; T cost;
  };
  int V;
  vector<vector<edge>> G;
  vector<T> dist;
  vector<int> pre;
  using pti = pair<T,int>;
  Dijkstra(int n) : V(n), G(V), dist(V, numeric_limits<T>::max()), pre(V) {}
  void add(int u, int v, T cost) {
    G.at(u).push_back((edge) {v, cost});
  }
  void solve(int s) {
    priority_queue<pti, vector<pti>, greater<pti>> Q;
    dist.at(s) = 0;
    Q.push(pti(0, s));
    while (!Q.empty()) {
      pti p = Q.top();
      Q.pop();
      int v = p.second;
      if (dist.at(v) < p.first) continue;
      for (auto &w : G.at(v)) {
        if (dist.at(w.to) > dist.at(v) + w.cost) {
          dist.at(w.to) = dist.at(v) + w.cost;
          pre.at(w.to) = v;
          Q.push(pti(dist.at(w.to), w.to));
        }
      }
    }
  }
  vector<int> route(int from, int to) {
    vector<int> res;
    while (true) {
      res.push_back(to);
      if (to == from) break;
      to = pre.at(to);
    }
    reverse(res.begin(), res.end());
    return res;
  }
};

int cnt;
void dfs(int pre, int v, int ng, vector<vector<int>> &G) {
  cnt++;
  for (auto next : G.at(v)) {
    if (next == pre) continue;
    if (next == ng) continue;
    dfs(v, next, ng, G);
  }
}

int main() {
  int N;
  cin >> N;
  Dijkstra<int> D(N);
  vector<vector<int>> G(N);
  for (int i = 0; i < N - 1; i++) {
    int a, b;
    cin >> a >> b;
    D.add(--a, --b, 1);
    D.add(b, a, 1);
    G.at(a).push_back(b);
    G.at(b).push_back(a);
  }
  D.solve(0);
  auto res = D.route(0, N - 1);
  int tmp = res.size();
  int f = res.at(tmp - tmp / 2 - 1);
  int s = res.at(tmp - tmp / 2);
  dfs(-1, 0, s, G);
  int F = cnt;
  cnt = 0;
  dfs(-1, N - 1, f, G);
  int S = cnt;
  cout << ((F > S) ? "Fennec" : "Snuke") << "\n";
}

