		vr[a].push_back(b);  //頂点aは頂点bへの道をもつ、その逆も
		vr[b].push_back(a);
	}

	//頂点0から頂点n-1への頂点の個数を数える(頂点0,n-1も含める)
		//0からn-1への道順
	road();
	//0からn-1にc個の点があるかを調べる
	int c = 0, s = n - 1;
	while (pre[s] != -1) {
		c++;
		s = pre[s];
	}
	c++;

	//Snukeは0からn-1のうち最後からc(下で更新)個の点を塗る

	if (c % 2 == 0) {
		c = c / 2;
	}
	else {
		c = (c - 1) / 2;
	}

	//後ろからc個をsfにつめる
	s = n - 1;
	int att;
	fill(used, used + n, false);
	used[n - 1] = true;
	for (int i = 0; i < c; i++) {
		sf.push(s);
		used[s] = true;
		s = pre[s];
		if (i == c - 1)att = s;
	}
	//後ろから詰めた点から派生する点はSnukeが塗る 得点sp
	//点attはフェネックが塗るから含んではいけない
	used[att] = true;
	int sp = 0;
	while (sf.size()) {
		int v = sf.front(); sf.pop(); sp++;
		for (int i = 0; i < vr[v].size(); i++) {
			if (!used[vr[v][i]]) {
