using namespace std;
void tree(vector<set<int>> &g,vector<vector<int>> &t,int x){
  while(!g.at(x).empty()){
    int c=*g.at(x).begin();
    g.at(x).erase(c);
    g.at(c).erase(x);
    t.at(x).push_back(c);
    tree(g,t,c);
  }
  return;
}
bool path(vector<vector<int>> &t,vector<int> &p,int b,int e){
  p.push_back(b);
  if(b==e)
    return 1;
  bool f=0;
  for(int c:t.at(b))
    f|=path(t,p,c,e);
  if(!f)
    p.pop_back();
  return f;
}
int child(vector<vector<int>> &t,int x,int b){
  if(x==b)
    return 0;
  int s=1;
  for(int c:t.at(x))
    s+=child(t,c,b);
  return s;
}
