void dijkstra(int start, int num){
    priority_queue<int, vector<int>, greater<int> > q;

    d[num][start] = 0;
    q.push(start);

    while(!q.empty()){
        int now = q.top();
        q.pop();
        for(int j = 0; j < edge[now].size(); j++){
            int next = edge[now][j].first;
            int nextd = d[num][now] + edge[now][j].second;
            if(nextd < d[num][next]){
                d[num][next] = nextd;
                q.push(next);
            }
        }
    }
}

