    }
    FindCentroids();
    int c1 = centroids[0], c2 = -inf;
    if(sz(centroids) == 2) c2 = centroids[1];
    dist_1 = dist(0, c1, c2);
    dist_n = dist(N - 1, c1, c2);
    if(dist_1 < dist_n){
        cout << "Fennec" << endl;
    }
    else if(dist_1 > dist_n) cout << "Snuke" << endl;
    else{
        if(sz(centroids) == 2) cout << "Snuke" << endl;
        else cout << "Fennec" << endl;
    }
}

