    a--;
    b--;
    G[a].pb(b);
    G[b].pb(a);
  }
  queue<int> q;
  q.push(0);
  int d[n], p[n] = { };
  REP(i, n) d[i] = 1000000;
  d[0] = 0;
  while(q.size()){
    int f = q.front();
    q.pop();
    for(int v: G[f]){
      if(d[v] > d[f]+1){
