  while(cur != 0){
    sp.pb(p[cur]);
    cur = p[cur];
  }
  int path[sp.size()];
  int i = 0;
  for(int v: sp){
    path[sp.size()-1-i] = v;
    i++;
  }
  int pt[sp.size()] = { };
  bool x[n] = { };
  REP(i, sp.size()){
    queue<int> qq;
