using namespace std;

struct Node {
    vector<int> to;
    bool b_done, w_done;
    int b_dist, w_dist;
};

void b_dfs(int pos, vector<Node> &node) {
    node[pos].b_done = true;
    for (int i = 0; i < node[pos].to.size(); i++) {
        int next = node[pos].to[i];
        if (node[next].b_done == false) {
            node[next].b_dist = node[pos].b_dist + 1;
            b_dfs(next, node);
        }
    }
}

void w_dfs(int pos, vector<Node> &node) {
    node[pos].w_done = true;
    for (int i = 0; i < node[pos].to.size(); i++) {
        int next = node[pos].to[i];
        if (node[next].w_done == false) {
            node[next].w_dist = node[pos].w_dist + 1;
            w_dfs(next, node);
        }
    }
}

int main() {
    int N;
    cin >> N;

    vector<Node> node(N);
    for (int i = 0; i < N; i++) {
        node[i].b_done = false;
        node[i].w_done = false;
    }
    for (int i = 0; i < N - 1; i++) {
        int a, b; cin >> a >> b; a--; b--;
        node[a].to.push_back(b);
        node[b].to.push_back(a);
    }

    node[0].b_dist = 0;
    node[N - 1].w_dist = 0;
    b_dfs(0, node);
    w_dfs(N - 1, node);

    int fennec = 0, snuke = 0;
    for (int i = 0; i < N; i++) {
        if (node[i].b_dist <= node[i].w_dist) fennec++;
        else snuke++;
    }

    if (fennec > snuke) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

    return 0;
}

