int f(const vector<vector<int>> &edges, vector<int> &costs, vector<int> &path, int n, int c)
{
    if (c == n)
    {
        path.push_back(n);
        return true;
    }
    rep(i, edges[c].size())
    {
        int u = edges[c][i];
        if (costs[u] >= 0)
            continue;
        costs[u] = costs[i] + 1;
        if (f(edges, costs, path, n, u))
        {
            path.push_back(c);
            return true;
        }
    }
    return false;
}

int f2(const vector<vector<int>> edges, vector<int> &costs,vector<int> &vals, int c)
{
    if (vals[c] != 0)
    {
        return vals[c];
    }
    rep(i, edges[c].size())
    {
        int u = edges[c][i];
        if(costs[u]>=0)continue;
        costs[u]= costs[c]+1;
        int v = f2(edges, costs,vals, u);
        if (v != 0)
        {
            vals[c] = v;
            return v;
        }
    }
    return 0;
}

