    int r = path.size() - 1;
    while (l < r)
    {
        vals[l] = 1;
        l += 1;
        if (l == r)
            break;
        vals[r] = -1;
        r -= 1;
    }
    int ans;
    rep(i,n){
        vector<int> costs(n, -1);
        costs[i]=0;
        f2(edge,costs,vals,i);
        ans += vals[i];
    }
    if(ans<=0){
        print("Snuke");
    }else{
        print("Fennec");

    }

    return 0;
}

