using namespace std;

struct PathData
{
    long long pos;
    vector<long long> vec;
};

int main()
{
    unordered_map<long long, vector<long long>> checkMap;

    long long N;
    cin >> N;

    long a, b;
    for (long long i = 0; i < N - 1; i++)
    {
        cin >> a >> b;
        a--;
        b--;
        checkMap[a].push_back(b);
        checkMap[b].push_back(a);
    }

    stack<PathData> PQueue;
    bool flag = false;
    long long halfPoint;
    for (long long i = 0; i < checkMap[0].size(); i++)
    {
        if (checkMap[0][i] == N - 1)
        {
            halfPoint = N - 1;
            flag = true;
            break;
        }
        PathData pd;
        pd.pos = checkMap[0][i];
        pd.vec.push_back(pd.pos);
        PQueue.push(pd);
    }
    if (!flag)
    {
        vector<long long> pathVec;
        while (!PQueue.empty())
        {
            PathData pd = PQueue.top();
            PQueue.pop();

            for (long long i = 0; i < checkMap[pd.pos].size(); i++)
            {
                if (checkMap[pd.pos][i] == N - 1)
                {
                    flag = true;
                    break;
                }
                else if (find(pd.vec.begin(), pd.vec.end(), checkMap[pd.pos][i]) == pd.vec.end())
                {
                    PathData pd_new;
                    pd_new.pos = checkMap[pd.pos][i];
                    pd_new.vec.push_back(pd_new.pos);
                    PQueue.push(pd_new);
                }
            }
            if (flag)
            {
                pathVec = pd.vec;
                break;
            }
        }

        if (pathVec.size() == 0)
        {
            halfPoint = N - 1;
        }
        else
        {
            halfPoint = pathVec[(pathVec.size() - 1) / 2 + (pathVec.size() - 1) % 2];
        }
    }

    long long fennec = 1;

    while (!PQueue.empty())
    {
        PQueue.pop();
    }

    for (long long i = 0; i < checkMap[0].size(); i++)
    {
        if (checkMap[0][i] != halfPoint)
        {
            PathData pd;
            pd.pos = checkMap[0][i];
            pd.vec.push_back(0);
            PQueue.push(pd);
        }
    }

    while (!PQueue.empty())
    {
        PathData pd = PQueue.top();
        PQueue.pop();

        fennec++;

        for (long long i = 0; i < checkMap[pd.pos].size(); i++)
        {
            if (find(pd.vec.begin(), pd.vec.end(), checkMap[pd.pos][i]) == pd.vec.end() && checkMap[pd.pos][i] != halfPoint)
            {
                PathData pd_new;
                pd_new.pos = checkMap[pd.pos][i];
                pd_new.vec.push_back(pd.pos);
                PQueue.push(pd_new);
            }
        }
    }

    if (fennec * 2 > N)
    {
        cout << "Fennec" << endl;
    }
    else
    {
        cout << "Snuke" << endl;
    }

    return 0;
}

