{
        if(a[node1].UP==NULL)        {a[node1].UP=&a[node2];a[node2].DOWN=&a[node1];}
	else if(a[node1].DOWN==NULL) {a[node1].DOWN=&a[node2];a[node2].UP=&a[node1];}
	else if(a[node1].LEFT==NULL) {a[node1].LEFT=&a[node2];a[node2].RIGHT=&a[node1];}
	else if(a[node1].RIGHT==NULL){a[node1].RIGHT=&a[node2];a[node2].LEFT=&a[node1];}
	else cout<<"木が足りません！"<<endl;
}
