		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	vector<int> parent(n + 1, -1), s(n + 1, 1);
	queue<int> q;
	stack<int> st;
	parent[1] = 0;
	q.push(1);
	while (!q.empty()) {
		int id = q.front();
		q.pop();
		for (auto p : adj[id]) {
			if (parent[p] == -1) {
				parent[p] = id;
				st.push(p);
				q.push(p);
			}
		}
	}

	while (!st.empty()) {
		int id = st.top();
		st.pop();
		s[parent[id]] += s[id];
	}

	vector<int> path;
	x = n;
	do {
		path.push_back(x);
		x = parent[x];
	} while (x > 0);

	m = path.size();
	if (m % 2 == 0) x = path[(m - 1) / 2];
	else x = path[m / 2 + 1];

	b = s[x];
	a = n - b;

	if (a > b) cout << "Fennec\n";
	else cout << "Snuke\n";

	return 0;
}

