        cost = c;
    }
};

typedef vector<vector<Edge>> Graph;

Graph G;
vector<int> seen;

// 1 fennec, 2 sunuke
vector<ll> c;

ll searchS(ll node, ll depth) {
    if (c[node] == 2) {
        return depth;
    }
    seen[node] = 1;
    ll res = 0;
    for (Edge e: G[node]) {
        if (seen[e.to] == 0) {
            res = max(res, searchS(e.to, depth + 1));
        }
    }

    if (res > 0) {
        if (depth <= res / 2) {
            c[node] = 1;
        }
        else {
            c[node] = 2;
        }
    }

    return res;
}


ll paint(ll node, ll v) {
    c[node] = v;
    ll res = 0;
    for (Edge e: G[node]) {
        // 未着色
        if (c[e.to] == 0) {
            paint(e.to, v);
        }
    }

    return res;
}

