bool used[100005];
int N;
vector<int> G[100005];
vector<int> way;

bool dfs(int now){
    used[now] = true;
    way.push_back(now);
    if(now == N) return true;
    for (int i = 0;i < G[now].size();i++){
        if(!used[G[now][i]] && dfs(G[now][i])) return true;
    }
    used[now] = false;
    way.pop_back();
    return false;
}

int dfs2(int now, int mid){
    used[now] = true;
    int ret = 0;
    if(now == mid) return 0;
    for (int i = 0;i < G[now].size();i++){
        if(!used[G[now][i]]) ret += dfs2(G[now][i],mid);
    }
    used[now] = false;
    return ret+1;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N;

    for (int i = 0;i < N-1;i++){
        int a,b; cin >> a >> b;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    memset(used,0,sizeof(used));
    dfs(1);

    memset(used,0,sizeof(used));
    int mid = way[(way.size()+1)/2];
    int fsum = dfs2(1,mid);
    //cout << mid << " " <<  fsum << endl;

    if(fsum > N-fsum) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

    return 0;

}

