void pfs(int s){
	d[s]=0;q.push({0,s});
	lint cd,cv;
	while(q.size()){
		cd=q.top().first;
		cv=q.top().second;
		q.pop();
		if(cd>d[cv])continue;
		for(edge &e:g[cv])if(d[e.to]>cd+e.cost){
			d[e.to]=cd+e.cost;
			prv[e.to]=cv;
			q.push({d[e.to],e.to});
		}
	}return;
}

class UnionFind{
public://par,rank,init,uf,uf,root,same,unite
	int par[MAXN],rank[MAXN],sum[MAXN];
	void init(int n){
		rep(i,n)par[i]=i,rank[i]=0,sum[i]=1;
	}
	UnionFind(int n){
		init(n);
	}UnionFind(){}
	int root(int x){
		return x==par[x]?x:par[x]=root(par[x]);
	}
	bool same(int x,int y){
		return root(x)==root(y);
	}
	void unite(int x,int y){
		x=root(x);
		y=root(y);
		if(x==y)return;
		if(rank[x]<rank[y]){
			par[x]=y;
			sum[y]+=sum[x];
		} else{
			par[y]=x;
			sum[x]+=sum[y];
			if(rank[x]==rank[y])++rank[x];
		}
	}
};

