std::map<int, int> calcDistance(int nodeNum, std::vector<std::pair<int, int>> edge, int startIndex){
    std::map<int, int> ret;
    ret[startIndex] = 0;

    std::queue<int> queue;
    queue.push(startIndex);

    while(!queue.empty()){
        int node = queue.front();
        queue.pop();
        for(auto iter:edge){
            if(iter.first == node && ret.count(iter.second) == 0){
                ret[iter.second] = ret[iter.first] + 1;
                queue.push(iter.second);
            }
            if(iter.second == node && ret.count(iter.first) == 0){
                ret[iter.first] = ret[iter.second] + 1;
                queue.push(iter.first);
            }
        }
    }

    return ret;
}

