int main(){
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(nullptr);

  cin >> n;
  rep(i, n - 1) {
    int a, b; cin >> a >> b;
    graph[a].emplace_back(b);
    graph[b].emplace_back(a);
  }

  bool visited1[n + 1] = {};
  int level1[n + 1] = {};
  level1[1] = 0;
  visited1[1] = true;
  queue<int> q1;
  q1.push(1);
  while (!q1.empty()) {
    int top = q1.front(); q1.pop();
    for (int next : graph[top]) {
      if (visited1[next]) continue;
      visited1[next] = true;
      q1.push(next);
      level1[next] = level1[top] + 1;
    }
  }

  bool visited2[n + 1] = {};
  int level2[n + 1] = {};
  level2[n] = 0;
  visited2[n] = true;
  queue<int> q2;
  q2.push(n);
  while (!q2.empty()) {
    int top = q2.front(); q2.pop();
    for (int next : graph[top]) {
      if (visited2[next]) continue;
      visited2[next] = true;
      q2.push(next);
      level2[next] = level2[top] + 1;
    }
  }
  int cnt1 = 0, cnt2 = 0;

  for (int i = 2; i <= n - 1; ++i) {
    if (level1[i] <= level2[i]) ++cnt1;
    else ++cnt2;
  }

  if (cnt1 > cnt2) {
    cout << "Fennec" << '\n';
  } else {
    cout << "Snuke" << '\n';
  }

  return 0;
}

