int n, a, b, fc, sc, sharec;
vector<int> ftree[100001], stree[100001];
bool gonef[100001], gones[100001];

void solvef(int edge){
    if(!gonef[edge]){
        gonef[edge] = true;
        fc++;
        for(int i = 0; i < ftree[edge].size(); i++){
            solvef(ftree[edge][i]);
        }
    }
}

void solves(int edge){
    if(!gones[edge]){
        gones[edge] = true;
        sc++;
        if(gonef[edge]) sharec++;
        for(int i = 0; i < stree[edge].size(); i++) solves(stree[edge][i]);
    }
}

int main(){
    cin >> n;
    for(int i = 0; i < n-1; i++){
        cin >> a >> b;
        ftree[a].push_back(b);
        ftree[b].push_back(a);
        stree[a].push_back(b);
        stree[b].push_back(a);
    }

    for(int i = 0; i < n; i++){
        for(int j = 0; j < ftree[i].size(); j++){
            if(ftree[i][j] == n)    ftree[i][j] = 0;
            if(stree[i][j] == 1)    stree[i][j] = 0;
        }
    }

    solvef(1);
    solves(n);
    fc--;
    sc--;
    sharec--;
    fc -= sharec/2;
    sc -= (sharec+1)/2;
    if(fc > sc){
        cout << "Fennec\n";
    }
    else{
        cout << "Snuke\n";
    }
    //cout << fc << ' ' << sc << ' ' << sharec << endl;
}

