struct UnionFind{
  vector<int> par;
  vector<int> treerank;

  UnionFind(int n){
    init(n);
  }

  void init(int n){
    par.resize(n); treerank.resize(n);
    rep(i, n) par[i] = i, treerank[i] = 0;
  }

  int find(int x){
    if(par[x] == x) return x;
    return par[x] = find(par[x]);
  }

  void unite(int x, int y){
    x = find(x); y = find(y);
    if(x == y) return;
    if(treerank[x] < treerank[y]) swap(x, y);
    if(treerank[x] == treerank[y]) treerank[x]++;
    par[y] = x;
    return;
  }

  bool same(int x, int y){
    return find(x) == find(y);
  }
};

int main(){
  int n; cin >> n;
  vector<int> to[n];
  rep(i, n-1){
    int a, b; cin >> a >> b;
    to[a-1].push_back(b-1); to[b-1].push_back(a-1);
  }
  int prev[n]; rep(i, n) prev[i] = -1;
  queue<int> que;
  que.push(0);
  prev[0] = 0;
  while(!que.empty()){
    int now = que.front(); que.pop();
    rep(i, to[now].size()){
      if(prev[to[now][i]] >= 0) continue;
      prev[to[now][i]] = now;
      que.push(to[now][i]);
    }
    if(prev[n-1] >= 0) break;
  }
  vector<int> route;
  int i = n-1;
  while(i != 0){
    route.push_back(i);
    i = prev[i];
  }
  int ng1 = route[(int)route.size() / 2 - 1];
  int ng2 = route[(int)route.size() / 2];
  UnionFind uf(n);
  rep(i, n)rep(j, to[i].size())if((i!=ng1 || to[i][j]!=ng2) && (i!=ng2 || to[i][j]!=ng1)){
    uf.unite(i, to[i][j]);
  }
  int cnt = 0;
  rep(i, n)if(uf.same(0, i)) cnt++;
  cout << (cnt*2 > n ? "Fennec" : "Snuke") << endl;
}

