int N;
vector<int> graph[100010];
int memo[100010];
int solve(int indx, bool fennec) {
    if (memo[indx] != -1) {
        return memo[indx];
    }
    memo[indx] = 0;
    int enemy = N-1;
    if (!fennec) {
        enemy = 0;
    }
    if (indx == enemy) {
        return memo[indx] = 0;
    }
    bool flg = false;
    for (int i = 0; i < graph[indx].size(); ++i) {
        if (memo[graph[indx][i]] == -1) {
            flg = true;
            break;
        }
    }
    if (!flg) {
        return memo[indx] = 0;
    }
    int ans = 0;
    for (int i = 0; i < graph[indx].size(); ++i) {
        if (memo[graph[indx][i]] == -1) {
            ans += solve(graph[indx][i], fennec) + 1;   
        }
    }
    return memo[indx] = ans;
}
int main() {
    cin >> N;
    for (int i = 0; i < N-1; ++i) {
        int a,b;
        cin >> a >> b;
        --a; --b;
        graph[a].emplace_back(b);
        graph[b].emplace_back(a);
    }

    // Fennec
    memset(memo, -1, sizeof(memo));
    int x = solve(0, true);
    //cout << x << endl;

    // Snuke
    memset(memo, -1, sizeof(memo));
    int y = solve(N-1, false);
    //cout << y << endl;
    puts(x>=y?"Fennec":"Snuke");  

    return 0;
}

