    }

    return 0;
}
std::vector<int> calcDistance(int nodeNum, std::map<int, vector<int>> edge, int startIndex){
    std::vector<int> ret;
    ret.resize(nodeNum, -1);
    ret[startIndex] = 0;

    std::queue<int> queue;
    queue.push(startIndex);

    while(!queue.empty()){
        int node = queue.front();
        queue.pop();

        for(auto iter:edge[node]){
            if(ret[iter] == -1){
                ret[iter] = ret[node] + 1;
                queue.push(iter);
            }
        }
    }

    return ret;
}

