  vector<vector<int>> graph(N);
  REP(i, N-1){
    int u, v;
    cin >> u >> v;
    u--; v--;
    graph[u].emplace_back(v);
    graph[v].emplace_back(u);
  }

  auto dist1 = bfs(0, N, graph);
  auto dist2 = bfs(N-1, N, graph);

  int cnt = 0;
  REP(i, N){
    if(dist1[i] <= dist2[i]) cnt++;
    else cnt--;
  }

  if(cnt > 0) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;

  return 0;
}

