void bfs(int id,int s){
    for (int i = 0; i < n; i++) visit[i] = false;
    que.push(s);
    visit[s] = true;
    dist[id][s] = 0;
    while (que.size() != 0){
        int now = que.front(); que.pop();
        for (int i = 0; i < v[now].size(); i++){
            int next = v[now][i];
            if (!visit[next]){
                dist[id][next] = dist[id][now] + 1;
                visit[next] = true;
                que.push(next);
            }
        }
    }
}
