int par[100005];

int color[100005];
int n;

void bfs() {
  queue<int> q;
  for(int i = 1; i <= n; i++) if(color[i]) q.push(i);
  while(!q.empty()) {
    int curr = q.front();
    q.pop();
    for(int out: edges[curr]) {
      if(color[out] == 0) {
        color[out] = color[curr];
        q.push(curr);
      }
    }
  }
}

void solve() {
  cin >> n;
  for(int i = 1; i < n; i++) {
    int a, b;
    cin >> a >> b;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }
  for(int i = 2; i <= n; i++) dp[i] = 1e9;
  queue<int> q;
  q.push(1);
  while(!q.empty()) {
    int curr = q.front();
    q.pop();
    for(int out: edges[curr]) {
      if(dp[out] == 1e9) {
        dp[out] = dp[curr] + 1;
        par[out] = curr;
        q.push(out);
      }
    }
  }
  vector<int> v;
  v.push_back(n);
  int curr = n;
  while(curr != 1) {
    curr = par[curr];
    v.push_back(curr);
  }
  reverse(v.begin(), v.end());
  for(int i = 0; i < v.size(); i++) {
    if(color[v[i]] == 0) color[v[i]] = 1;
    if(color[v[v.size()-1-i]] == 0) color[v[v.size()-1-i]] = -1;
  }
  bfs();
  int pos = 0;
  for(int i = 1; i <= n; i++) pos += color[i];
  if(pos > 0) cout << "Fennec\n";
  if(pos == 0) cout << "Snuke\n";
  if(pos < 0) cout << "Snuke\n";
}

