const int INF = 1 << 28;

int main() {
    int N;
    cin >> N;
    vvi edge(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    vi distF(N + 1, INF);
    vi distS(N + 1, INF);
    distF[1] = 0;
    distS[N] = 0;
    deque<pii> queF; // node, distance
    queF.emplace_back(1, 0);
    while (queF.size()) {
        auto node = queF.front();
        queF.pop_front();
        for (auto n : edge[node.first]) {
            if (distF[n] == INF) {
                distF[n] = node.second + 1;
                queF.emplace_back(n, distF[n]);
            }
        }
    }
    deque<pii> queS; // node, distance
    queS.emplace_back(N, 0);
    while (queS.size()) {
        auto node = queS.front();
        queS.pop_front();
        for (auto n : edge[node.first]) {
            if (distS[n] == INF) {
                distS[n] = node.second + 1;
                queS.emplace_back(n, distS[n]);
            }
        }
    }
    int f(0), s(0);
    for (int i = 2; i < N; ++i) {
        if (distF[i] <= distS[i])
            f++;
        else
            s++;
    }
    if (f > s)
        cout << "Fennec" << endl;
    else
        cout << "Snuke" << endl;
    return 0;
}

