    vector<vector<int>> G(N+1);
    vector<int> dist(N+1,-1);

    rep(i,N-1){
        int a,b;
        cin >> a >> b;
        G[a].push_back(b);
        G[b].push_back(a);
    } 

    int fennec = N-1;
    int snuke = 1;
    queue<int> Q;
    Q.push(1);
