#include <bits/stdc++.h>
using namespace std;
using Edge = struct{
  int from;
  int to;
};
vector<int> edge[100000];
vector<int> path;
queue<Edge> e;
int cnt = 1;

void dfs_path(int f, int p, int s) {
  if (f == s)
    return ;
  if (p == -1)
    path.push_back(0);
  for (auto &e: edge[f]) {
    if (e == p)
      continue;
    path.push_back(e);
    dfs_path(e, f, s);
    path.pop_back();
  }
}

void bfs_cnt(int fb, int sb) {
  while (!e.empty()) {
    Edge ele = e.front();
    e.pop();
    int eFrom = ele.from, eTo = ele.to;
    if (eFrom == fb && eTo == sb)
      continue;
    cnt++;
    for (auto &a: edge[eTo]) {
      if (a == eFrom)
        continue;
      e.push({eTo, a});
    }
  }
  return ;
}

