    edge[a].push_back(b);
    edge[b].push_back(a);
  }
  dfs_path(0, -1, N-1);
  int d = path.size(), fb, sb;
  fb = path[(d+1)/2-1];
  sb = path[(d+1)/2];
  for (auto &n: edge[0])
    e.push({0, n});
  bfs_cnt(fb, sb);
  if (N-2*cnt<0)
    cout << "Fennec\n";
  else
    cout << "Snuke\n";
  return 0;
}

