	for (int i = 0; i < G[u].size(); ++i) {
		int t = G[u][i];
		if (!used[t] && dfs(t)) {
			V.push_back(u);
			return 1;
		}
	}
	return 0;
}

int col[N];

void dfs2(int u, int c) {
	col[u] = c;
	for (int i = 0; i < G[u].size(); ++i) {
		int v = G[u][i];
		if (col[v]) continue;
		dfs2(v, c);
	}
}

