	for (int i = V.size() / 2; i < V.size(); ++i) col[V[i]] = 1;
	for (int i = 0; i < V.size(); ++i) dfs2(V[i], col[V[i]]);
	int cnt1 = 0, cnt2 = 0;
	for (int i = 1; i <= n; ++i) if (col[i] == 1) cnt1++; else cnt2++;
