const int INF = 1000000000;
int N;

vector<int> bfs(vector<int> G[N], int s) {
    queue<int> que;
    vector<int> dist(N, INF);
    que.push(s);
    dist[s] = 0;
    while (!que.empty()) {
        int u = que.front(); que.pop();
        for (int i = 0; i < G[u].size(); i++) {
            int v = G[u][i];
            if (dist[v] != INF) continue;
            dist[v] = dist[u] + 1;
            que.push(v);
        }
    }
    return dist;
}

int main() {
    cin >> N;
    vector<int> G[N];
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    vector<int> dist1 = bfs(G, 0);
    vector<int> dist2 = bfs(G, N - 1);

    int cnt_f = 0, cnt_s = 0;
    for (int i = 0; i < N; i++) {
        if (dist1[i] <= dist2[i]) cnt_f++;
        else cnt_s++;
    }

    if (cnt_f > cnt_s) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
    return 0;
}

