int prev[100010];
queue<int> q;
void get_path()
{
	memset(prev,-1,sizeof(prev));
	queue<int> tmp;
	swap(q,tmp);

	q.push(1);
	prev[1]=sthFun;
	while(!q.empty())
	{
		int u=q.front(); q.pop();
		if(u==N)
		{
			save_path();
			return;
		}
		for(int i=0;i<e[u].size();i++)
		{
			int& v=e[u][i];
			if(prev[v]==-1)
			{
				prev[v]=u;
				q.push(v);
			}
		}
	}
}
void save_path()
{
	int now=N;
	while(prev[now]!=sthFun)
	{
		path.pb(now);
		now=prev[now];
	}
	path.pb(1);
	reverse(path.begin(),path.end());
}

void get_col()
{
	memset(col,-1,sizeof(col));
	for(int i=0,j=path.size()-1;i<=j;i++,j--)
	{
		col[path[j]]=2;
		col[path[i]]=1;
	}
	for(int i=0;i<path.size();i++)
	{
		paint_col(path[i],col[path[i]]);
	}
}
