vector<vector<ll>> edge;

vector<ll> bfs(vector<ll> path, ll v) {
	queue<ll> q = queue<ll>();
	path.push_back(v);
	for (auto& nv : edge[v]) {
		if (nv == edge.size() - 1) {
			path.push_back(nv);
			return path;
		}
		if (find(path.begin(), path.end(), nv) == path.end()) {
			q.push(nv);
		}
	}
	while (q.size() > 0) {
		vector<ll> p = bfs(path, q.front());
		q.pop();
		if (p[0] != -1) return p;
	}
	return vector<ll>(1, -1);

}

