int n;
int num;

bool dfs(int curr){
	if (curr == n)
		return true;

	for (int i = 0; i < edge[curr].size(); i++){
		if (dist[edge[curr][i]] == -1){
			path.push_back(edge[curr][i]);
			dist[edge[curr][i]] = dist[curr] + 1;
			if(dfs(edge[curr][i]))
				return true;
			else {
				path.pop_back();
			}
		}
	}

	return false;
}

void dfs2(int curr){
	num += color[curr];
	for (int i = 0; i < edge[curr].size(); i++){
		if (color[edge[curr][i]] == -1){
			color[edge[curr][i]] = color[curr];
			dfs2(edge[curr][i]);
		}
	}
}


