bool used[maxn];
int n;
int pre[maxn];

void road(int s = 0) {
	fill(used, used + n, false);
	pre[0] = -1;
	used[0] = true;
	q.push(s);
	bool key = false;
	//点を詰めて、そこからのばす
	while (!key) {          //n-1を含むまで続ける
		int v = q.front(); q.pop();
		for (int i = 0; i < vr[v].size(); i++) {
			if (!used[vr[v][i]]) {   //行先の頂点は未使用である
				used[vr[v][i]] = true;
				//cout << "行先" << vr[v][i] << endl;
				q.push(vr[v][i]);  //点vからのびる点を詰める
				pre[vr[v][i]] = v;  //詰められた点は点vから伸びている
				if (vr[v][i] == n - 1) {  //のびた点がn-1の時に終わり
					key = true;
					break;
				}
			}
		}
	}

	return;
}

