	rep(i, n-1) {
		int a, b; cin >> a >> b;
		a--; b--;
		vr[a].push_back(b);  //頂点aは頂点bへの道をもつ、その逆も
		vr[b].push_back(a);
	}

	//頂点0から頂点n-1への頂点の個数を数える(頂点0,n-1も含める)
	    //0からn-1への道順
	road();
	    //0からn-1にc個の点があるかを調べる
	int c = 0; int s = n - 1;
	while (pre[s] != -1) {
		//cout << "点" << s << "の帰り先は" << pre[s] << endl;
		c++;
		s = pre[s];
	}
	c++;

	//Snukeは0からn-1のうち最後からc(下で更新)個の点を塗る

	if (c % 2 == 0) {
		c = c / 2;
	}
	else {
		c = (c - 1) / 2;
	}

	//後ろからc個をsfにつめる
	//cout << "Snukeは点n-1を含めて" << c << "個をぬれる" << endl;
	s = n - 1;
	int att;
	for (int i = 0; i < c; i++) {
		sf.push(s);
		s = pre[s];
		if (i == c - 1)att = s;
	}
	//後ろから詰めた点から派生する点はSnukeが塗る 得点sp
	//点sはフェネックが塗るから含んではいけない
	fill(used, used + n, false);
	used[n - 1] = true; used[att] = true;
	int sp = 0;
	//cout << "点"<<att<<"より先は進んではいけない" << endl;
	while (sf.size()) {
		int v = sf.front(); sf.pop(); sp++;
		for (int i = 0; i < vr[v].size(); i++) {
			//cout << "点" << v << "から点" << vr[v][i] << "へのびる" << endl;
			if (!used[vr[v][i]]) {
				//cout << "点" << vr[v][i] << "をつめる" << endl;
				used[vr[v][i]] = true;
				sf.push(vr[v][i]);
			}
		}
	}

	if (sp < n - sp) {
		cout << "Fennec" << endl;
	}
	else {
		cout << "Snuke" << endl;
	}

	return 0;
}

