/**
 *  target までのパスを探す
 */
bool searchPath(
    const vector<SQWORD> *pvecEdge, 
    SQWORD sqParent, 
    SQWORD sqCur,
    SQWORD sqTarget,
    vector<SQWORD> &vecsqPath) 
{
    if (sqTarget == sqCur) {
        vecsqPath.emplace_back(sqCur);
        return true;
    }

    for (auto next: pvecEdge[sqCur]) {
        if (sqParent != next) {
            if (searchPath(pvecEdge, sqCur, next, sqTarget, vecsqPath)) {
                vecsqPath.emplace_back(sqCur);
                return true;
            }
        }
    }

    return false;
}

/**
 *  ノードの数を数える
 */
SQWORD countNode(
    const vector<SQWORD> *pvecEdge, 
    SQWORD sqParent, 
    SQWORD sqCur)
{
    SQWORD sqCnt = 1;
    for (auto next: pvecEdge[sqCur]) {
        if (sqParent != next) {
            sqCnt += countNode(pvecEdge, sqCur, next);
        }
    }
    return sqCnt;
}


