string sente = "Fennec";
string gote = "Snuke";

int N;
vector<int> G[210000];


int dist[210000];
int pre[210000];

int num[210000];

int rec(int v, int p) {
  int res = 1;
  for (int i = 0; i < G[v].size(); ++i) {
	int to = G[v][i];
	if (num[to] != -1) continue;
	if (to == p) continue;
	rec(to, v);
	res += num[to];
  }
  return num[v] = res;
}

string solve() {
  memset(dist, -1, sizeof(dist));
  dist[0] = 0;
  memset(pre, -1, sizeof(pre));
  queue<int> que;
  que.push(0);
  while (!que.empty()) {
	int cur = que.front();
	que.pop();
	for (int i = 0; i < G[cur].size(); ++i) {
	  int to = G[cur][i];
	  if (dist[to] != -1) continue;
	  dist[to] = dist[cur] + 1;
	  que.push(to);
	  pre[to] = cur;
	}
  }
  vector<int> load;
  int cur = N-1;
  while (true) {
	load.push_back(cur);
	cur = pre[cur];
	if (cur == -1) break;
  }

  reverse(load.begin(), load.end());
  int res = 0;
  memset(num, -1, sizeof(num));
  for (int i = 0; i < load.size(); ++i) {
	num[load[i]] = 1;
  }
  for (int i = 0; i <= (int)(load.size() - 1) / 2; ++i) {
	res += rec(load[i], -1);
  }

  if (res > N/2) return sente;
  else return gote;
}


int main() {
  while (cin >> N) {
	for (int i = 0; i < 210000; ++i) G[i].clear();
	for (int i = 0; i < N-1; ++i) {
	  int a, b;
	  cin >> a >> b;
	  --a, --b;
	  G[a].push_back(b);
	  G[b].push_back(a);
	}
	cout << solve() << endl;
  }
}

