int traversal(int cur)
{
	visited[cur] = true;
	int ret = 1;

	for (int i = 0; i < adj[cur].size(); i++)
	{
		auto next = adj[cur][i];
		if (visited[next]) continue;
		ret += traversal(next);
	}
	return ret;
}


int main(void)
