void dfs(int u, int p = -1) {
    if (u == n - 1) {
        k = depth - 1;
    }
    tin[u] = timer++;
    for (int i = 0; i < v[u].size(); i++) {
        if (v[u][i] != p) {
            depth++;
            dfs(v[u][i], u);
            depth--;
            d[u] += d[v[u][i]];
        }
    }
    if (v[u].size() == 0) {
        d[u] = 1;
    }
    tout[u] = timer++;
}

bool check(int a, int b) {
    return tin[a] <= tin[b] && tout[b] <= tout[a];
}

