#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
typedef long long ll;

vector<int> g[100000+10];
int parentOf[100000+10];
int color[100000+10];


int main(void) {
  memset(parentOf, -1, sizeof parentOf);
  memset(color, -1, sizeof color);
  int n;
  scanf("%d", &n);
  REP(i, n-1) {
    int a, b;
    scanf("%d%d", &a, &b);
    --a;
    --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  queue<int> q;
  q.push(0);
  parentOf[0] = 0;
  while(!q.empty()) {
    int u = q.front(); q.pop();
    REP(i, g[u].size()) {
      int v = g[u][i];
      if(parentOf[v] < 0) {
        parentOf[v] = u;
        q.push(v);
      }
    }
  }
  // REP(i, n) {
  //   cerr  << "parent of " << i+1 << " is " << parentOf[i]+1 << endl;
  // }
  deque<int> path;
  for(int cur = n-1; cur != 0; cur = parentOf[cur]) {
    path.push_front(cur);
  }
  path.push_front(0);

  for(int turn = 0; !path.empty(); turn ^= 1) {
    int v;
    if(turn == 0) {
      v = path.front(); path.pop_front();
    } else {
      v = path.back(); path.pop_back();
    }
    color[v] = turn;
    q.push(v);
  }
  while(!q.empty()) {
    int u = q.front(); q.pop();
    REP(i, g[u].size()) {
      int v = g[u][i];
      if(color[v] == -1) {
        color[v] = color[u];
        q.push(v);
      }
    }
  }
  // REP(i, n) {
  //   cerr  << "color of " << i+1 << " is " << color[i] << endl;
  // }
  int cnt[2] = {};
  REP(i, n) {
    assert(color[i] >= 0);
    cnt[color[i]]++;
  }
  puts(cnt[0] <= cnt[1] ? "Snuke" : "Fennec");
  return 0;
}

