pll findMid(int t, int d) {
  int pre = t;
  while (true) {
    for (auto it : edges[pre]) {
      int cur = it.ss;
      if (depth[cur] == d) {
        return mp(cur, pre);
      }
      if (depth[cur] == depth[pre]-1) {
        pre = cur;
        break;
      }
    }
  }
}

int calcNum(int node, int pre) {
  int num = 1;
  for (auto it : edges[node]) {
    int next_node = it.ss;
    if (next_node != pre) {
      num += calcNum(next_node, node);
    }
  }
