    int v = que.front();
    que.pop();
    for(auto nv:G[v]){
      if(d2[nv]>d2[v]+1){
        d2[nv]=d2[v]+1;
        que.push(nv);
      }
    }
  }
  int fennec=0,snuke=0;
  rep(i,n){
    if(d1[i]<d2[i])fennec++;
    else snuke++;
  }

  if(fennec>=snuke) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;
  return 0;
}

