    cin >> n;
    vector<vector<int>> edge(n);
    for(int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    vector<int> par(n, -1);
    dfs(0, -1, edge, par);
    vector<int> keiro;
    int p = n - 1;
    while(p != 0) {
        keiro.push_back(p);
        p = par[p];
    }
    keiro.push_back(0);
    reverse(all(keiro));
    int u = keiro[(keiro.size() - 1) / 2];
    int v = keiro[(keiro.size() - 1) / 2 + 1];
    UnionFind uf(n);
    for(int i = 0; i < n; i++) {
        for(auto e : edge[i]) {
            if(i == u && e == v) {
                continue;
            }
            if(i == v && e == u) {
                continue;
            }
            uf.unite(i, e);
        }
    }
    if(uf.size(0) > uf.size(n - 1)) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
}

