    a--; b--;
    G[a][b] = 1;
    G[b][a] = 1;
  }

  int s = 0;
  int g = n-1;

  vector<int> d1 = bfs(G, s);
  vector<int> d2 = bfs(G, g);

  int l = 0;
  int r = 0;

  rep (i, n) {
    if (d1[i] <= d2[i]) l++;
    else r++;
  }

  if (l > r) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;
  return 0;
}

