  while(!q.empty()){
    int v = q.front();
    q.pop();

    for(auto u :e[v]){
      if(d2[u] > d2[v] + 1){
        d2[u] = d2[v] + 1;
        q.push(u);
      }
    }
  }

  int s = 0, f = 0;
  for(int i = 0; i < n; i++){
    if(d1[i] <= d2[i]) s++;
    else f++;
  }

  if(f >= s) cout << "Snuke" << endl;
  else cout << "Fennec" << endl;

  return 0;
}

