	dis[0]=0;
	queue<int> Q;
	Q.push(0);

	while(Q.size()!=0){
		int from = Q.front();
		Q.pop();
		for(int i=0;i<E[from].size();i++){
			int to = E[from][i];
			if(dis[to]!=Inf)continue;
			dis[to] = dis[from]+1;
			Q.push(to);
		}
	}

	deque<int> L(0);
	int now = N-1;
	while(true){
		for(int i=0;i<E[now].size();i++){
			int to = E[now][i];
			if(dis[to]==dis[now]-1){
				now=to;
				break;
			}
		}
		if(dis[now]==0)break;
		L.push_back(now);
	}

	vector<string> color(N,"");
	color[0]="black";
	color[N-1]="white";

	for(int i=0;i<N;i++){
		if(L.size()==0)break;
		if(i%2==0){
			color[L.front()]="black";
			L.pop_front();
		}
		else{
			color[L.back()]="white";
			L.pop_back();
		}
