class union_find{
private:
  int p[200000];
  int r[200000];


public:
  union_find(int n){
    for(int i=0;i < n;i++){
      p[i] = i;
      r[i] = 0;
    }
  }
  int find(int x){
    if(p[x] == x){
      return x;
    }else{
      return p[x] = find(p[x]);
    }
  }
  void unite(int x, int y){
    x = find(x);
    y = find(y);
    if(x == y) return;

    if(r[x] < r[y]){
      p[x] = y;
    }else{
      p[y] = x;
      if(r[x] == r[y]) r[x]++;
    }
  }
  bool same(int x, int y){
    return find(x) == find(y);
  }
};

