    if(a[i] == 0 && b[i] == n-1){
      b[i] = 0;
    }
    if(a[i] == 0 || a[i] == n-1){
      checker[b[i]]++;
    }
    if(b[i] == 0 || b[i] == n-1){
      checker[a[i]]++;
    }
  }

  int dame = -1;
  rep(i, n){
    if(checker[i] == 2){
      dame = i;
      break;
    }
  }
  union_find node(n);
  rep(i, n-1){
    if(a[i] != dame && b[i] != dame) node.unite(a[i], b[i]);
  }
  int fen = 0, snu = 0, mid = 0;
  for(int i = 1; i < n-1; i++){
    if(node.same(0, i)) fen++;
    else if(node.same(n-1, i)) snu++;
    else mid++;
  }
  if(mid%2 != 0) fen++;
  cout << (fen > snu ? "Fennec" : "Snuke") << endl;

