    G[b].push_back(a);
  }
  queue<int> q;
  vector<bool> visited(N),colored(N);
  int d1[N],d2[N];
  set<int> Fennec,Snuke,both;
  d1[0] = 0;
  d2[N-1] = 0;
  for (q.push(0); !q.empty(); q.pop()) {
    for (int n : G[q.front()]) {
      if (!visited[n]) {
        visited[n] = true;
        d1[n] = d1[q.front()]+1;
        q.push(n);
      }
    }
  }
  visited = vector<bool>(N);
  for (q.push(N-1); !q.empty(); q.pop()) {
    for (int n : G[q.front()]) {
      if (!visited[n]) {
        visited[n] = true;
        d2[n] = d2[q.front()]+1;
        q.push(n);
      }
    }
  }
  for (int i = 0; i < N; i++) {
    moves1[d1[i]].push_back(i);
    moves2[d2[i]].push_back(i);
  }
  Fennec.insert(0);
  Snuke.insert(N-1);
  for (int i = 1; ; i++) {
    if (Fennec.empty() && both.empty()) {
      cout<<"Snuke";
      return 0;
    }
    if (both.empty()) {
      colored[*Fennec.begin()] = true;
      Fennec.erase(Fennec.begin());
    } else {
      colored[*both.begin()] = true;
      both.erase(both.begin());
    }
    if (Snuke.empty() && both.empty()) {
      cout<<"Fennec";
      return 0;
    }
    if (both.empty()) {
      colored[*Snuke.begin()] = true;
      Snuke.erase(Snuke.begin());
    } else {
      colored[*both.begin()] = true;
      both.erase(both.begin());
    }
    for (int n : moves1[i]) {
      if (Snuke.count(n) && !colored[n]) {
        Snuke.erase(n);
        both.insert(n);
      } else if (!colored[n]) {
        Fennec.insert(n);
      }
    }
    for (int n : moves2[i]) {
      if (Fennec.count(n) && !colored[n]) {
        Fennec.erase(n);
        both.insert(n);
      } else if (!colored[n]) {
        Snuke.insert(n);
      }
    }
  }
}

