#define MOD 1000000007
#define DEBUG 0
#define REP(i,n) for(int i=0;i<n;i++)

#define F 1
#define S 2

int main(){

	lli n;
	map<lli,vector<lli>> m;

	cin>>n;
	REP(i,n-1){
		lli a,b;
		cin>>a>>b;
		m[a].push_back(b);
		m[b].push_back(a);
	}

	/* 1からNまで幅優先探索を行う*/
	/* この時どんな経路をたどったか覚えておく必要がある*/
	/* フェネックすぬけくん順番順番に行う */
	/* ターン数を覚えておき、新しいターンになったら次の人に手番を回す */
	lli flag[100010];
	REP(i,100010)flag[i]=0;

	queue<lli> f,s;
	queue<lli> fsize,ssize;

	f.push(1);
	s.push(n);

	fsize.push(0);
	ssize.push(0);
	flag[1]=F;
	flag[n]=S;

	while(f.size()!=0 || s.size()!=0){
		/*まずfのターン*/
		lli cnt=0;
		lli before;
		while(f.size()!=0){
			lli nowSize = fsize.front();
			if(cnt!=0){
				if(before!=nowSize)break;
			}
			lli ftop = f.front();
			f.pop();
			fsize.pop();
			for(auto e:m[ftop]){
				if(flag[e]!=0)continue;
				flag[e]=F;
				f.push(e);
				fsize.push(nowSize+1);
			}
			cnt++;
		}

		/*次にSのターン*/
		cnt=0;
		while(s.size()!=0){
			lli nowSize = ssize.front();
			if(cnt!=0){
				if(before!=nowSize)break;
			}
			lli stop = s.front();
			s.pop();
			ssize.pop();
			for(auto e:m[stop]){
				if(flag[e]!=0)continue;
				flag[e]=S;
				s.push(e);
				ssize.push(nowSize+1);
			}
			cnt++;
		}
	}

	/*最終結果はFとSのそれぞれ多い方*/

	lli ansF=0,ansS=0;

	REP(i,100010){
		if(flag[i]==F)ansF++;
		else if(flag[i] == S)ansS++;
		else;
	}
	if(ansF > ansS)cout<<"Fennec"<<endl;
	else cout << "Snuke"<<endl;

	return 0;
}

