int comb_max = 1000;
vector<long long> comb = vector<long long>(comb_max * comb_max, -1);

long long combination(long long n, long long r) {
	if (n == 1 || n == 0)return 1;
	if (n == r)	return 1;
	else if (r == 0)return 1;
	else if (r == 1)return n;
	else if (comb[comb_max * (n - 1) + (r - 1)] != -1) return comb[comb_max * (n - 1) + (r - 1)];
	else {
		auto res = combination(n - 1, r - 1) + combination(n - 1, r);
		comb[comb_max * (n - 1) + (r - 1)] = res;
		return res;
	}
}


struct Node {
	int Number;
	int Level;
	vector<int> connected{ vector<int>() };
	bool operator<(const Node& n) { return Number < n.Number; }
};

void get_level(vector<Node>& tree, vector<bool> visited, int level, Node& n) {
	n.Level = level;
	visited[n.Number] = true;
	for (size_t i = 0; i < n.connected.size(); i++) {
		if (!visited[n.connected[i]]) {
			get_level(tree, visited, level + 1, tree[n.connected[i]]);
		}
	}
}

int main() {
	int N; cin >> N;
	auto tree = vector<Node>(N);
	for (size_t i = 0; i < N; i++) tree[i].Number = i;
	int from, to;
	for (size_t i = 0; i < N - 1; i++) {
		cin >> from >> to;
		tree[from - 1].connected.push_back(to - 1);
		tree[to - 1].connected.push_back(from - 1);
	}
	sort(tree.begin(), tree.end());

	//Fennecからの距離とSunukeからの距離を計算。
	//距離が同じかFennecの方が小さい時はFennecのマスになる。
	get_level(tree, vector<bool>(N, false), 0, tree[0]);
	auto dist_f = vector<int>(N);
	for (size_t i = 0; i < N; i++) dist_f[i] = tree[i].Level;
	get_level(tree, vector<bool>(N, false), 0, tree[N - 1]);
	auto dist_s = vector<int>(N);
	for (size_t i = 0; i < N; i++) dist_s[i] = tree[i].Level;
//	for (size_t i = 0; i < N; i++) cout << dist_f[i] << " "; cout << endl;
//	for (size_t i = 0; i < N; i++) cout << dist_s[i] << " "; cout << endl;
	int f_count = 0;
	int s_count = 0;
	for (size_t i = 0; i < N; i++) {
		if (dist_f[i] <= dist_s[i])f_count++;
		else s_count++;
	}
	cout << (f_count > s_count ? "Fennec" : "Sunuke") << endl;
}

