int main() {

	int n;
	cin >> n;
	vi G[100005];
	rep(i, n-1) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	vi color(n, 0);
	color[0] = 1;
	color[n - 1] = -1;
	vi d(n,-1);
	d[0] = 0;
	queue<int> que;
	que.push(0);
	while (!que.empty()) {
		int v = que.front(); que.pop();
		for (int next : G[v]) {
			if (d[next] != -1) continue;
			d[next] = d[v] + 1;
			if (next == n - 1) break;
			que.push(next);
		}
	}
	int tmp = n - 1;
	int nokori = (d[n - 1]-1) / 2;
	while (tmp != 0) {
		for (int next : G[tmp]) {
			if (d[next] == d[tmp] - 1) {
				if (nokori > 0) {
					color[next] = -1;
					nokori--;
				}
				else {
					color[next] = 1;
				}
				tmp = next;
				break;
			}
		}
	}
	rep(i, n) {
		if (color[i] != 0) {
			queue<int> nuru;
			nuru.push(i);
			while (!nuru.empty()) {
				int v = nuru.front();
				nuru.pop();
				for (int next : G[v]) {
					if (color[next] == 0) {
						color[next] = color[i];
						nuru.push(next);
					}
				}
			}
		}
	}
	int nb = 0, nw = 0;
	rep(i, n) {
		if (color[i] == 1)nb++;
		else nw++;
	}
	if(nb <= nw) {
		P("Snuke");
	}
	else {
		P("Fennec");
	}
	return 0;
}

