typedef pair<int, int> P;

const int INF = 1001001001;

int dist1[100005];      // 頂点0からの距離
int dist2[100005];      // 頂点n-1からの距離

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> graph(n);
    for(int i = 0; i < n-1; ++i){
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    fill(dist1, dist1 + n, INF);
    dist1[0] = 0;
    queue<P> que;
    que.push(P(0, 0));
    while(!que.empty()){
        P p = que.front();
        que.pop();
        int v = p.first;
        int d = p.second;

        for(int i = 0; i < graph[v].size(); ++i){
            int v1 = graph[v][i];
            if(v1 == n-1)   continue;

            if(d + 1 < dist1[v1]){
                dist1[v1] = d + 1;
                que.push(P(v1, d + 1));
            }
        }
    }

    fill(dist2, dist2 + n, INF);
    dist2[n-1] = 0;
    que.push(P(n-1, 0));
    while(!que.empty()){
        P p = que.front();
        que.pop();
        int v = p.first;
        int d = p.second;

        for(int i = 0; i < graph[v].size(); ++i){
            int v1 = graph[v][i];
            if(v1 == 0)     continue;

            if(d + 1 < dist2[v1]){
                dist2[v1] = d + 1;
                que.push(P(v1, d + 1));
            }
        }
    }

    int cnt1 = 0, cnt2 = 0;
    for(int i = 1; i < n-1; ++i){
        if(dist1[i] <= dist2[i])    ++cnt1;
        else                        ++cnt2;
    }

    if(cnt1 > cnt2){
        cout << "Fennec\n";
    }
    else{
        cout << "Snuke\n";
    }
}

