    vector<int> path;
    que.push((Node){1, 0, vector<int>()});
    for(int i=0;i<n;++i){
        Node now = que.front(); que.pop();
        now.path.push_back(now.n);
        if(now.n == n){
            path = now.path;
            break;
        }
        for(int j=0;j<tree[now.n].size();++j){
            if(now.cost == 0 || tree[now.n][j] != now.path[now.cost-1]){
                vector<int> p = now.path;
                que.push((Node){tree[now.n][j], now.cost+1, p});
            }
        }
    }
    int mi = path.size() / 2, mi2;
    if((path.size() & 1) == 0){
        mi2 = mi - 1;
    }else{
        mi2 = mi + 1;
    }
    tree[path[mi]].erase(find(tree[path[mi]].begin(), tree[path[mi]].end(), path[mi2]));
    tree[path[mi2]].erase(find(tree[path[mi2]].begin(), tree[path[mi2]].end(), path[mi]));

    set<int> fennec, snuke;
    queue<int> quef, ques;
    quef.push(1);
    ques.push(n);
    while(!quef.empty() || !ques.empty()){
        if(!quef.empty()){
            int nowf = quef.front(); quef.pop();
            fennec.insert(nowf);
            for(int j=0;j<tree[nowf].size();++j){
                if(fennec.count(tree[nowf][j]) == 0){
                    quef.push(tree[nowf][j]);
                }
            }
        }
        if(!ques.empty()){
            int nows = ques.front(); ques.pop();
            snuke.insert(nows);
            for(int j=0;j<tree[nows].size();++j){
                if(snuke.count(tree[nows][j]) == 0){
                    ques.push(tree[nows][j]);
                }
            }
        }
    }
    string winner;
    if((path.size()&1) == 0){
        if(fennec.size() > snuke.size())winner = "Fennec";
        else winner = "Snuke";
    }else{
        if(fennec.size() >= snuke.size())winner = "Fennec";
        else winner = "Snuke";
    }
    cout << winner << endl;

    return 0;
}

