typedef long long ll;
typedef pair<int,int> P;

bool used[100005];
int N;
vector<int> G[100005];
vector<int> way;

bool dfs(int now){
    used[now] = true;
    way.push_back(now);
    if(now == N) return true;
    for (int i = 0;i < G[now].size();i++){
        if(!used[G[now][i]] && dfs(G[now][i])) return true;
    }
    used[now] = false;
    way.pop_back();
    return false;
}

int dfs2(int now, int ng1, int ng2){
    used[now] = true;
    int ret = 0;
    for (int i = 0;i < G[now].size();i++){
        if(G[now][i] != ng1 && G[now][i] != ng2 && !used[G[now][i]]) ret += dfs2(G[now][i],ng1,ng2);
    }
    used[now] = false;
    return ret+1;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N;

    for (int i = 0;i < N-1;i++){
        int a,b; cin >> a >> b;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    memset(used,0,sizeof(used));
    dfs(1);

    int fidx = 0, sidx = way.size()-1;
    int fsum = 0, ssum = 0;

    while(fidx < sidx){
        memset(used,0,sizeof(used));
        if(fidx != 0)fsum += dfs2(way[fidx],way[fidx+1],way[fidx-1]);
        else fsum += dfs2(way[fidx],way[fidx+1],-1);
        fidx++;
        if(fidx != way.size()-1)ssum += dfs2(way[sidx],way[sidx-1],way[sidx]+1);
        else ssum += dfs2(way[sidx],way[sidx-1],-1);
        sidx--;
    }
    if(fidx == sidx)fsum += dfs2(way[fidx],way[fidx+1],-1);

    if(fsum > ssum) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

    return 0;

}

