vector<int> bfs(vector<vector<int>> &G, int s) {
  vector<bool> used(G.size());
  vector<int> d(G.size());
  queue<pair<int, int>> que;

  d[s] = 0;
  used[s] = true;
  que.push(make_pair(s, 0));

  while (!que.empty()) {
    pair<int, int> q = que.front(); que.pop();
    int cx = q.first;
    int ct = q.second;
    used[cx] = true;
    d[cx] = ct;

    rep (i, G[cx].size()) {
      int nx = G[cx][i];
      if (!used[nx]) {
        que.push(make_pair(nx, ct+1));
      }
    }
  }
  return d;
}

