void search_path(int node, int snuke_s, int path_length, vector<int> path)
{
    if(node == snuke_s){
        fennec_to_snuke = path;
    }
    else {
        int m;
        if(node != 1){fennec_paintable.insert(node);}
        m = v[node].size();
        for(int i=0; i<m; ++i){
            if(path_length == 0 || (path_length >= 1 && path[path_length-1] != v[node][i])){
                vector<int> new_path(path);
                new_path.push_back(v[node][i]);
                search_path(v[node][i], snuke_s, path_length + 1, new_path);
            }
        }
    }
    return;
}

string fennec_vs_snuke(){
    set<int> tmp, tmp2;
    if((int)(fennec_to_snuke.size()) % 2 == 0){
        for (int i=0; i<(int)(fennec_to_snuke.size()) / 2; ++i){
            fennec_get.insert(fennec_to_snuke[i]);
            fennec_paintable.erase(fennec_to_snuke[i]);
            snuke_get.insert(fennec_to_snuke[(int)(fennec_to_snuke.size() - 1) - i]);
        }
        set_union(fennec_get.begin(), fennec_get.end(), fennec_paintable.begin(), fennec_paintable.end(), inserter(tmp, tmp.end()));
        set_union(tmp.begin(), tmp.end(), snuke_get.begin(), snuke_get.end(), inserter(tmp2, tmp2.end()));
