            return "Fennec";
        }
        else {
            return "Snuke";
        }
    }
    else {
        for (int i=0; i<((int)(fennec_to_snuke.size()) + 1) / 2; ++i){
            fennec_get.insert(fennec_to_snuke[i]);
            fennec_paintable.erase(fennec_to_snuke[i]);
