void dfs(int d,int type,int pos){
	if(depth[type][pos]>=0){return;}

	depth[type][pos]=d;

	int i;
	for(i=0;i<E[pos].size();i++){
		if(depth[type][E[pos][i]]==-1){
			parent[type][E[pos][i]]=pos;
			child[type][pos].push_back(E[pos][i]);
			dfs(d+1,type,E[pos][i]);
		}
	}
}
void dfs2(int type,int pos){

	int i;

	for(i=0;i<child[type][pos].size();i++){
		if(color[child[type][pos][i]]==0){
			if(type==0){
			color[child[type][pos][i]]=-1;
			}
			else{
			color[child[type][pos][i]]=1;
			}
			dfs2(type,child[type][pos][i]);
		}
	}

}

int simulation(int type,int pos){


	if(color[parent[1-type][pos]]==0){
		if(type==0){
			color[parent[1][pos]]=1;
			return parent[1][pos];
		}
		else{
			color[parent[0][pos]]=-1;
			return parent[0][pos];
		}
	}
	else{
		return -1;
	}


}

