    std::fill(painted, painted + n, false);
    for (int i = 0; i < n - 1; i++)
    {
        int a, b;
        scanf("%d%d", &a, &b);
        a--; b--;
        tree[a].edge.push_back(b);
        tree[b].edge.push_back(a);
    }

    opening(0, 0);
    std::fill(painted, painted + n, false);
    if (dfs(0) > dfs(n - 1)) printf("Fennec\n");
    else printf("Snuke\n");

    delete[] tree;
    delete[] painted;
    return 0;
}

int opening(int pos, int depth)
{
    if (painted[pos]) return -1;
    if (pos == n - 1) return depth;
    painted[pos] = true;
    for (auto &e: tree[pos].edge)
    {
        int snuke_depth = opening(e, depth + 1);
        if (snuke_depth == -1) continue;
        if (depth != snuke_depth / 2) return snuke_depth;
        std::swap(tree[e].edge.back(), *std::find(tree[e].edge.begin(), tree[e].edge.end(), pos));
        tree[e].edge.pop_back();
        std::swap(tree[pos].edge.back(), *std::find(tree[pos].edge.begin(), tree[pos].edge.end(), e));
        tree[pos].edge.pop_back();
        return snuke_depth;
    }
    return -1;
}

int dfs(int pos)
{
    if (painted[pos]) return 0;
    painted[pos] = true;
    int count{1};
    for (auto &e : tree[pos].edge)
    {
        count += dfs(e);
    }
    return count;
}

