    for (int i = 0; i < int(W.at(T).size()); i++) {
      if (A.at(W.at(T).at(i)) > A.at(T) + 1) {
        A.at(W.at(T).at(i)) = A.at(T) + 1;
        Q.push(W.at(T).at(i));
        ans++;
      }
    }
  }
  if (N % 2 == 1) {
    if (ans > (N - 2) / 2) {
      cout << "Snuke" << endl;
    }
    else {
      cout << "Fennec" << endl;
    }
  }
  else {
    if (ans >= (N - 2) / 2) {
      cout << "Snuke" << endl;
    }
    else {
      cout << "Fennec" << endl;
    }
  }
}

