vector<int> bfs(int s){
    vector<int> dist(n+1, -1);
    queue<int> q;
    q.push(s);
    dist[s] = 0;

    while(!q.empty()){
       int t = q.front(); q.pop();
       for(int i: tree[t]){
           if(dist[t] == -1){
               dist[t] = dist[t]+1;
               q.push(t);
           }
       } 
    }
    return dist;
}


