using namespace std;

const int maxn = 2e5 + 5;
int father[maxn],other[maxn],pre[maxn],last[maxn],d[maxn];
int all = -1,ans = 0,n;

void build(int x,int y){
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
}

void dfs(int x,int fa,int deep){
	int dt = last[x];
	while(dt != -1){
		int dr = other[dt];
		if(dr != fa){
			if(dr == n) ans = deep;
			father[dr] = x;
			dfs(dr,x,deep + 1);
			d[x] += d[dr] + 1;
		}
		dt = pre[dt];
	}
}

int main(){
	while(~scanf("%d",&n)){
		memset(last,-1,sizeof(last));
		for(int i = 1;i <= n - 1;i++){
			int x,y;
			scanf("%d %d",&x,&y);
			build(x,y);
			build(y,x);
		}	
		dfs(1,0,0);
		ans = ans / 2;
		int x = n;
		for(int  i = 1;i <= ans;i++) x = father[x];
		if(d[x] >= n - d[x] - 2) printf("Snuke\n");
		else printf("Fennec\n");
	}
}

