void func(int k,vector<int>& d){
  queue<int> q;
  q.push(k); //スタート地点を入れる
  while(!q.empty()){
    int t = q.front(); q.pop();
    for(auto x:tree[t]){//現在地tから行ける全ての行き先xについて調べる
