#define NOCOLOR 0
#define BLACK 1 //Fennec
#define WHITE 2 //Snuke
#define N 100000
using namespace std;

int n;
int** M;
int* color;

void bfs(int s1, int s2){
    queue<int> q1,q2;
    q1.push(s1);
    q2.push(s2);
    for(int i = 0; i < n; i++) color[i]=NOCOLOR;
    color[0]=BLACK;
    color[n-1]=WHITE;
    int u1,u2;
    while(!q1.empty() && !q2.empty()){
        u1=q1.front(); q1.pop();
        for(int v = 0; v < n; v++){
            if(M[u1][v]==0) continue;
            if(color[v]!=NOCOLOR) continue;
            color[v] = BLACK;
            q1.push(v);
        }
        u2=q2.front(); q2.pop();
        for(int v = 0; v < n; v++){
            if(M[u2][v]==0) continue;
            if(color[v]!=NOCOLOR) continue;
            color[v] = WHITE;
            q2.push(v);
        }
    }
    if(!q1.empty()) cout<<"Fennec"<<endl;
    else cout<<"Snuke"<<endl;
}
