int n;
vector<int> v[100001];
int color[100001];
bool past1[100001];
int d[100001];
inline int bfs(int s,int nowcolor) {
	priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> p;
	fill(d, d + n, inf);
	p.push(pair<int, int>(0, s));
	int res = 0;
	while (!p.empty()) {
		int cost = p.top().first;
		int now = p.top().second;
		p.pop();
		res = max(res, cost);
		if (color[now] == -nowcolor) {
			continue;
		}
		if (d[now] < cost)continue;
		for (int i = 0; i < v[now].size(); i++) {
			if (d[v[now][i]] > d[now] + 1) {
				d[v[now][i]] = d[now] + 1;
				p.push(pair<int, int>(d[v[now][i]], v[now][i]));
			}
		}
	}
	return res;
}
int main() {
	cin >> n;
	for (int i = 0; i < n; i++) {
		int to, from;
		cin >> from >> to;
		from--; to--;
		v[from].push_back(to);
		v[to].push_back(from);
	}
	color[0] = 1;
	color[n - 1] = -1;
	for (int i = 0; i < n; i++)past1[i] = 0;
	past1[0] = 1;
	int f = bfs(0, 1);
	for (int i = 0; i < n; i++)past1[i] = 0;
	past1[n - 1] = 1;
	int s = bfs(n - 1, -1);
	if (s > f) {
		cout << "Snuke" << endl;
	}
	else if (f > s) {
		cout << "Fennec" << endl;
	}
	else {
		cout << ((f & 1) ? "Fennec" : "Snuke" )<< endl;
	}
}

