bool used[100010];
int tr[100010];
vector <int> tree[100010];
int d[100010];
int n;
queue <int> q;
int cnt1=0,cnt2=0,cnt0=0;
int tmp1=0;

void dfs(int x){
	for (int i=0;i<tree[x].size();i++){
		int u=tree[x][i];
		if (!used[u]){
			tmp1++;
			used[u]=true;
			dfs(u);	
		}
	}
	return;
}

void trace(int x){
	cnt0++;
	if (x==0) return;
	used[x]=true;
	int tmp=tr[x];
	if (tmp==-1) return;
	used[tmp]=true;
	for (int i=0;i<tree[tmp].size();i++){
		int u=tree[tmp][i];
		if (cnt0>cnt2) dfs(u);
	}
	trace(tmp);
	return;
}

int main(){
	memset(used,false,sizeof(used));
	cin>>n;
	for (int i=0;i<n-1;i++){
		int x,y;
		cin>>x>>y;
		x--;y--;
		tree[x].push_back(y);
		tree[y].push_back(x);
	} 
	q.push(0);
	memset(d,-1,sizeof(d));
	d[0]=0;
	memset(tr,-1,sizeof(tr));
	while(!q.empty()){
		int p=q.front();
		q.pop();
		if (p==n-1) {
			trace(n-1);
			break;
		}
		for (int i=0;i<tree[p].size();i++){
			int tmp=tree[p][i];
			if (d[tmp]==-1||d[tmp]>d[p]+1){
				tr[tmp]=p;
				d[tmp]=d[p]+1;
				q.push(tmp);
			}
		}
	}
	int dis=d[n-1]-1;
	cnt2+=dis/2;
	cnt1+=dis-cnt2+tmp1;
	cnt2=n-cnt1;
	if (cnt1>cnt2) cout<<"Fennec";
	else cout<<"Snuke";
}

