using namespace std;

void dfs(vector<vector<int> > &G, int s, vector<int> &dist, int c) {
    dist[s] = c;
    for (auto u: G[s]) {
        if (dist[u] != -1)
            continue;

        dist[u] = c + 1;
        dfs(G, u, dist, c+1);
    }
}

int main() {
