        G[a-1].push_back(b-1);
        G[b-1].push_back(a-1);
    }
    vector<int> dist1(n, -1), distn(n, -1);
    dfs(G, 0, dist1, 0);
    dfs(G, n-1, distn, 0);

    int cnt1 = 0, cntn = 0;
    for (int i = 0; i < n; i++) {
        if (dist1[i] <= distn[i])
            cnt1++;
        else 
            cntn++;
    }

    if (cnt1 > cntn)
