int fennec[MAX_N]; //node 0からnode iまでの距離
int snuke[MAX_N];  //node N-1からnode iまでの距離

void init() {
    queue<pair<int,int>> task;
    bool vis[N];
    fill(vis, vis + N, false);
    vis[0] = true;
    fennec[0] = 0;
    task.push(make_pair(0, 0));
    while(!task.empty()) {
        int from = task.front().first;
        int d = task.front().second;
        task.pop();
        for(int i = 0; i < graph[from].size(); ++i) {
            int to = graph[from][i];
            if(vis[to]) continue;
            vis[to] = true;
            fennec[to] = d + 1;
            task.push(make_pair(to, d + 1));
        }
    }

    fill(vis, vis + N, false);
    vis[N-1] = true;
    snuke[N-1] = 0;
    task.push(make_pair(N-1, 0));
    while(!task.empty()) {
        int from = task.front().first;
        int d = task.front().second;
        task.pop();
        for(int i = 0; i < graph[from].size(); ++i) {
            int to = graph[from][i];
