struct PathData
{
    long long pos;
    long long dist;
    unordered_set<long long> set;
};

int main()
{
    unordered_map<long long, vector<long long>> checkMap;
    unordered_map<long long, long long> fennecMap;

    long long N;
    cin >> N;

    long a, b;
    for (long long i = 0; i < N - 1; i++)
    {
        cin >> a >> b;
        a--;
        b--;
        checkMap[a].push_back(b);
        checkMap[b].push_back(a);
    }

    queue<PathData> PQueue;
    for (long long i = 0; i < checkMap[0].size(); i++)
    {
        PathData pd;
        pd.pos = checkMap[0][i];
        pd.dist = 1;
        pd.set.emplace(0);
        PQueue.push(pd);
    }
    fennecMap[0] = 0;

    while (!PQueue.empty())
    {
        PathData pd = PQueue.front();
        PQueue.pop();

        fennecMap[pd.pos] = pd.dist;

        for (long long i = 0; i < checkMap[pd.pos].size(); i++)
        {
            if (pd.set.find(checkMap[pd.pos][i]) == pd.set.end())
            {
                PathData pd_new;
                pd_new.pos = checkMap[pd.pos][i];
                pd_new.dist = pd.dist + 1;
                pd_new.set = pd.set;
                pd_new.set.emplace(pd.pos);
                PQueue.push(pd_new);
            }
        }
    }

    while (!PQueue.empty())
    {
        PQueue.pop();
    }

    for (long long i = 0; i < checkMap[N - 1].size(); i++)
    {
        PathData pd;
        pd.pos = checkMap[N - 1][i];
        pd.dist = 1;
        pd.set.emplace(N - 1);
        PQueue.push(pd);
    }

    long long fennec = 0;
    while (!PQueue.empty())
    {
        PathData pd = PQueue.front();
        PQueue.pop();

        if (pd.dist >= fennecMap[pd.pos])
        {
            fennec++;
        }

        for (long long i = 0; i < checkMap[pd.pos].size(); i++)
        {
            if (pd.set.find(checkMap[pd.pos][i]) == pd.set.end())
            {
                PathData pd_new;
                pd_new.pos = checkMap[pd.pos][i];
                pd_new.dist = pd.dist + 1;
                pd_new.set = pd.set;
                pd_new.set.emplace(pd.pos);
                PQueue.push(pd_new);
            }
        }
    }

    if (fennec * 2 > N)
    {
        cout << "Fennec" << endl;
    }
    else
    {
        cout << "Snuke" << endl;
    }

    return 0;
}

