    tree[a].push_back(b);
    tree[b].push_back(a);
  }

  for (uint32_t i = 1; i < num; i++) {
    status[i] = WHITE;
    distance_from0[i] = 0;
  }
  dist(1, 0, callback0);

  for (uint32_t i = 1; i < num; i++) {
    status[i] = WHITE;
    distance_fromN[i] = 0;
  }
  dist(num, 0, callbackN);

  uint32_t black = 0, white = 0;
  for (uint32_t i = 1; i <= num; i++) {
    // cout << i << " " << distance_from0[i] << " " << distance_fromN[i];
    if (distance_from0[i] <= distance_fromN[i]) {
