        int a, b;
        cin >> a >> b;
        a--;
        b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    // BFS のためのデータ構造
    vector<int> dist(N, -1); // 全頂点を「未訪問」に初期化
    queue<int> que;

    // 初期条件 (頂点 0 を初期ノードとする)
    dist[0] = 0;
    que.push(0); // 0 を橙色頂点にする

    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        int v = que.front(); // キューから先頭頂点を取り出す
        que.pop();

        // v から辿れる頂点をすべて調べる
        for (int nv : G[v]) {
            if (dist[nv] != -1) continue; // すでに発見済みの頂点は探索しない

            // 新たな白色頂点 nv について距離情報を更新してキューに追加する
            dist[nv] = dist[v] + 1;
            que.push(nv);
        }
    }

    int num=dist[N-1]-1;
    vector<int> a(num+2);
    que.push(N-1);
    int cnt=num+1;
    while(!que.empty()){
        int cur=que.front();
        a[cnt]=cur;
        que.pop();
        for(int nv:G[cur]){
            if(dist[nv]<dist[cur]){
                que.push(nv);
                break;
            }
        }
        cnt--;
    }


    int a1=a[num-num/2];
    int a2=a[num-num/2+1];
    REP(i,G[a1].size()){
        if(G[a1][i]==a2){
            G[a1].erase(G[a1].begin()+i);
            break;
        }
    }
    REP(i,G[a2].size()){
        if(G[a2][i]==a1){
            G[a2].erase(G[a2].begin()+i);
            break;
        }
    }



    int cnt_0=0;
    int cnt_1=0;
    // BFS のためのデータ構造
    REP(i,N) dist[i]=-1;
    // 初期条件 (頂点 0 を初期ノードとする)
    dist[0] = 0;
    que.push(0); // 0 を橙色頂点にする


    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        int v = que.front(); // キューから先頭頂点を取り出す
        que.pop();

        // v から辿れる頂点をすべて調べる
        for (int nv : G[v]) {
            if (dist[nv] != -1) continue; // すでに発見済みの頂点は探索しない

            // 新たな白色頂点 nv について距離情報を更新してキューに追加する
            dist[nv] = dist[v] + 1;
            que.push(nv);
            cnt_0++;
        }
    }



    // BFS のためのデータ構造
    REP(i,N) dist[i]=-1;

    // 初期条件 (頂点 0 を初期ノードとする)
    dist[N-1] = 0;
    que.push(N-1); // 0 を橙色頂点にする


    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        int v = que.front(); // キューから先頭頂点を取り出す
        que.pop();

        // v から辿れる頂点をすべて調べる
        for (int nv : G[v]) {
            if (dist[nv] != -1) continue; // すでに発見済みの頂点は探索しない

            // 新たな白色頂点 nv について距離情報を更新してキューに追加する
            dist[nv] = dist[v] + 1;
            que.push(nv);
            cnt_1++;
        }
    }

    if(cnt_0>cnt_1){
        cout << "Fennec" << endl;
    }else{
        cout << "Snuke" <<endl;
    }



}

