  std::vector<int> gap = sphere(0, d / 2, v);

  int white = count(n - 1, gap, v);
  if(n % 2 == 0 && white >= n / 2 || n % 2 == 1 && white >= n / 2 + 1){
    std::cout << "Snuke" << '\n';
  }else{
    std::cout << "Fennec" << '\n';
  }

  return 0;
}

