std::map<int, int> calcDistance(int nodeNum, std::vector<std::pair<int, int>> edge, int startIndex){
    std::map<int, int> ret;
    ret[startIndex] = 0;

    std::queue<int> queue;
    queue.push(startIndex);

    std::vector<std::pair<int, int>> tempedge = edge;

    while(!queue.empty()){
        int node = queue.front();
        queue.pop();
        for(int i=tempedge.size()-1;i>=0;i--){
            if(tempedge[i].first == node && ret.count(tempedge[i].second) == 0 && tempedge[i].second != startIndex){
                ret[tempedge[i].second] = ret[tempedge[i].first] + 1;
                queue.push(tempedge[i].second);
                tempedge.erase(tempedge.begin() + i);
            }
