int main(){
  int N; cin >> N;

  vector < vector<int> > graph(N);
  for (int i = 0; i < N - 1; i++){
    int A, B; cin >> A >> B;
    A--; B--;
    graph[A].push_back(B);
    graph[B].push_back(A);
  }

  vector <int> D1j(N), DNj(N);

  queue <int> que;
  que.push(0);
  vector <bool> C1(N), C2(N);
  C1[0] = true; C2[N - 1] = true;

  while (!que.empty()){
    int start = que.front(); que.pop();
    for (int i = 0; i < graph[start].size(); i++){
      int next = graph[start][i];
      if (C1[next] == false){
        que.push(next);
        C1[next] = true;
        D1j[next] = D1j[start] + 1;
      }
    }
  }

  que.push(N - 1);
  while (!que.empty()){
    int start = que.front(); que.pop();
    for (int i = 0; i < graph[start].size(); i++){
      int next = graph[start][i];
      if (C2[next] == false){
        que.push(next);
        C2[next] = true;
        DNj[next] = DNj[start] + 1;
      }
    }
  }

  int Fennec = 0, Snuke = 0;
  for (int i = 0; i < N; i++){
    if (D1j[i] < DNj[i]){
      Fennec ++;
    }else{
      Snuke++;
    }
  }

  if (Fennec > Snuke) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;

  return 0;
}

