struct Dijkstra{
private:
    const ll inf = 1LL<<60;
    int n;
    vector<vector<pair<ll, ll>>> adj;
    vector<ll> dist;

public:
    Dijkstra(int _n) :n(_n) {
        adj.resize(n);
        dist.resize(n, inf);
    }

    void add_edge(int from, int to, ll cost){ adj[from].push_back(make_pair(to, cost)); }

    void dijkstra(int s){
        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
        pq.push(make_pair(0, s));
        dist[s] = 0;

        while(!pq.empty()){
            int now = pq.top().second;
            int d = pq.top().first;
            pq.pop();
            if(dist[now] < d) continue;
            for(auto edge : adj[now]){
                int to = edge.first;
                int w = edge.second;
                if(dist[to] > dist[now] + w){
                    dist[to] = dist[now] + w;
                    pq.push(make_pair(dist[to], to));
                }
            }
        }
    }

    ll const & getdist(int v) const { return dist[v]; }
};

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n; cin >> n;
    Dijkstra fen(n);
    Dijkstra snu(n);

    rep(i, n-1){
        int a, b; cin >> a >> b;
        --a; --b;
        fen.add_edge(a, b, 1);
        fen.add_edge(b, a, 1);
        snu.add_edge(a, b, 1);
        snu.add_edge(b, a, 1);
    }

    fen.dijkstra(0);
    snu.dijkstra(n-1);

    int fscore = 0, sscore = 0;
    rep(i, n){
        if(fen.getdist(i) <= snu.getdist(i)) ++fscore;
        else ++sscore;
    }

    cout << (fscore > sscore? "Fennec":"Snuke") << endl;

    return 0;
}

