int main(){
#if DEBUG
    std::ifstream in("input.txt");
    std::cin.rdbuf(in.rdbuf());
#endif

    int N;
    cin >> N;

    vector <vector <int>> G(N);

    REP(i,N-1)
    {
        int a, b;
        cin >> a >> b;
        --a;--b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    //0からの最短経路と最短経路でNを使用するか
    vector <int> d(N, N + 100);
    vector <int> prev(N);
    vector <int> guard(N);

    d[0] = 0;

    //0からN-1を経由して到達できる箇所を調べる
    queue <int> que;
    que.push(0);
    int from, to;
    while(!que.empty())
    {
        from = que.front();
        que.pop();

        for(int i = 0; i < G[from].size(); ++i)
        {
            to = G[from][i];
            if(d[from] + 1 < d[to])
            {
                d[to] = d[from] + 1;
                prev[to] = from;
                que.push(to);
            }
        }
    }

    //snukeは Nから1に向かって、(d[N-1] - 1) / 2回移動できる
    int pos = N-1;
    guard[pos] = 1;
    guard[0] = 1;
    REP(i, (d[N-1] - 1) / 2)
    {
        pos = prev[pos];
        guard[pos] = 1;
    }

    int fen = 0;
    que.push(0);
    while(!que.empty())
    {
        from = que.front();
        que.pop();

        for(int i = 0; i < G[from].size(); ++i)
        {
            to = G[from][i];
            if(guard[to] == 1)continue;
            guard[to] = 1;
            ++fen;
            que.push(to);
        }
    }

    //fen 塗れるマス N - 2 - fen 
    string res;
    //奇数個の場合
    if( fen > N - 2 - fen)
    {   
        res = "Fennec";
    }
    else
    {
        res = "Snuke";
    }

    cout << res << endl;
    return 0;
}

