    rept(N) {
        int a, b; cin >> a >> b;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    int dist[100001]; ZERO(dist);
    dist[1] = 1;
    queue<int> Q;
    Q.push(1);

    while(!Q.empty()) {
        int src = Q.front(); Q.pop();
        for(auto&& e: edge[src]) {
            if (e != N && dist[e] == 0) {
                Q.push(e);
                dist[e] = dist[src] + 1;
            }
            if (e == N) dist[e] = dist[src] + 1;
        }
    }

    int snuke = (dist[N] - 2) / 2;
    reps(i, N) {
        if (dist[i] == 0) {
            snuke++;
        }
    }
    int fe = N - 2 - snuke;

    if (fe > snuke) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
    return 0;
}

