using namespace std;

using ll = long long;

void FindPath(int cur, int p, int dst, auto &pre, auto &adj) {
    pre[cur] = p;
    if (cur == dst) return ;

    for (int u : adj[cur])
        if (u != p && pre[u] == -1) FindPath(u, cur, dst, pre, adj);
}

void Paint(int cur, int p, int c, auto &paint, auto &adj) {
    paint[cur] = c;
    for (auto u : adj[cur])
        if (u != p && paint[u] == -1) Paint(u, cur, c, paint, adj);
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    int n;
    cin >> n;
    vector<vector<int>> adj(n);
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        cin >> a >> b;
        adj[a - 1].push_back(b - 1);
        adj[b - 1].push_back(a - 1);
    }

    vector<int> pre(n, -1);
    FindPath(0, n, n - 1, pre, adj);

    vector<int> path;
    for (int cur = n - 1; pre[cur] != n; cur = pre[cur])
        path.push_back(cur);
    path.push_back(0);

    int size = path.size();
    vector<int> c(n, -1);
    for (int i = 0; i < size / 2; ++i) c[path[i]] = 1;
    for (int i = size / 2; i < size; ++i) c[path[i]] = 0;

    cout << endl;
    for (auto v : path) cout << v << " ";
    cout << endl;
    for (int v = 0; v < n; ++v)
        cout << v << " " << c[v] << endl;
    cout << endl;

    Paint(0, -1, 0, c, adj);

    for (int v = 0; v < n; ++v)
        cout << v << " " << c[v] << endl;

    int black = 0, white = 0;
    for (int v = 0; v < n; ++v) {
        if (c[v] == 0) ++black;
        else ++white;
    }

    if (white < black) cout << "Fennec\n";
    else cout << "Snuke\n";

    return 0;
}

