void dfs(vi &dis, int n) {
    int cnt = 0;
    rep(i, G[n].size()) {
        if(dis[G[n][i]]==INF) {
            dis[G[n][i]] = dis[n]+1;
            dfs(dis, G[n][i]);
            cnt++;      
        }
    }
