void ftos(vi &fdis, vi &sdis,  int n) {
    if(fdis[n] <= sdis[n]) colored[n] = 1;
    else colored[n] = 2;
    if(n==N-1) return; 
    rep(i, G[n].size()) {
        if(sdis[n] > sdis[G[n][i]]) {
            ftos(fdis, sdis, G[n][i]);
        }
    }
}

void fill(int n, int c) {
    rep(i, G[n].size()) {
        if(colored[G[n][i]]==0 || colored[G[n][i]]==c) {
            if(!counted[G[n][i]]) {
                counted[G[n][i]] = true;
                colored[G[n][i]] = c;
                fill(G[n][i], c);
            }
        }
    }
}

