ll n;
vvl to;

tl dfs(ll v, ll p, ll d) {
    if (v == n - 1) {
        if (d <= 2) return tl(v, p, 2);
        return tl(d, 0, 1);
    }

    tl res = tl(0, 0, 0);
    for (auto nv : to[v]) {
        if (nv == p) continue;
        tl ret = dfs(nv, v, d + 1);
        if (get<2>(ret) != 0) res = ret;
    }
    if (get<2>(res) == 1) {
        ll nd = get<0>(res) - 1;
        ll nh = get<1>(res) + 1;
        if (nd == nh + 2 || nd == nh + 1) return tl(v, p, 2);
        return tl(nd, nh, 1);
    }
    return res;
}

ll cnt(ll v, ll p, ll c) {
    if (v == c) return 0;

    ll res = 1;
    for (auto nv : to[v]) {
        if (nv == p) continue;
        res += cnt(nv, v, c);
    }
    return res;
}

