int bfs(int start, int end) {
    queue<int> q;
    int cnt=0;
    q.push(start);
    while (q.size()) {
        int p = q.front(); q.pop();
        visited[p] = true;
        cnt++;
        for (int next: edge[p]) {
            if (next==end) continue;
            if (next==p) continue;
            if (visited[next]) continue;
            q.push(next);
        }
    }
    return cnt;
}

