void dfs_fn(int node, int dst)
{
	int i;

    if (vst_fn[node])
		return;

	vst_fn[node] = 1;
	fn[node] = dst;

	for (i = 0; i < v[node].size(); i++)
		dfs_fn(v[node][i], dst + 1);
}

void dfs_sk(int node, int dst)
{
	int i;

    if (vst_sk[node])
		return;

	vst_sk[node] = 1;
	sk[node] = dst;

	for (i = 0; i < v[node].size(); i++)
		dfs_sk(v[node][i], dst + 1);
}

int main(void)
{
