	scanf("%d" ,&n);
	for (i = 1; i < n; i++)
	{
		int a, b;

		scanf("%d %d" ,&a, &b);

		v[a].push_back(b);
		v[b].push_back(a);
	}

	dfs_fn(1, 0);
	dfs_sk(n, 0);

	int fn_cl = 0, sk_cl = 0, same = 0;

	for (i = 1; i <= n; i++)
        if (fn[i] < sk[i])
			fn_cl++;
		else if (fn[i] > sk[i])
			sk_cl++;
		else
			same++;

    fn_cl += same;

    if (fn_cl > sk_cl)
		puts("Fennec");
	else
		puts("Snuke");
	return 0;
}

