int main(){
    int n;
    cin >> n;
    vector<vector<int>> node(n);
    for (int i = 0; i < n-1; i++){
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        node[a].push_back(b);
        node[b].push_back(a);
    }
    vector<int> f_distance(n);
    vector<bool> f_check(n, true);
    queue<int> que;
    que.push(0);
    f_distance[0] = 0;
    f_check[0] = false;
    while (que.size() > 0){
        int x = que.front(); que.pop();
        int y = (int)node[x].size();
        for (int i = 0; i < y; i++) {
            if (f_check[node[x][i]]){
                f_check[node[x][i]] = false;
                f_distance[node[x][i]] = f_distance[x] + 1;
                que.push(node[x][i]);
            }
        }
    }

    vector<int> s_distance(n);
    vector<bool> s_check(n, true);
    que.push(n-1);
    s_distance[n-1] = 0;
    s_check[n-1] = false;
    while (que.size() > 0){
        int x = que.front(); que.pop();
        int y = (int)node[x].size();
        for (int i = 0; i < y; i++) {
            if (s_check[node[x][i]]){
                s_check[node[x][i]] = false;
                s_distance[node[x][i]] = s_distance[x] + 1;
                que.push(node[x][i]);
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < n; i++){
        if (f_distance[i] <= s_distance[i]) ans++;
    }
    if (ans * 2 > n) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;
}

