int bfs(int x,int y)
{
    node2 n1,n2;
    queue<node2>m;
    n1.date=x;
    m.push(n1);
    while(!m.empty())
    {
        n1=m.front();
        sum[n1.step]++;
        if(n1.date==y)
            return n1.step;
        m.pop();
        for(int i=0;i<node[n1.date].size();++i)
        {
            if(flag[node[n1.date][i]]==0)
            {
                flag[node[n1.date][i]]=1;
                n2.date=node[n1.date][i];
                n2.step=n1.step+1;
                m.push(n2);
            }
        }
    }
    return -1;
}
