// dijkstra
struct edge{int to, cost;};

struct dijkstra {
    int V;
    vint d;
    vector<vector<edge>> G;

    dijkstra(int n) {init(n);} 

    void init(int n) {
        V = n;
        G.resize(V);
        d.resize(V);
        rep(i,V) d[i] = inf;
    }

    void add_edge(int s, int t, int cost) {
        s--; t--;
        edge e;
        e.to = t; e.cost = cost;
        G[s].push_back(e);
    }

    void run(int s) {
        s--;
        priority_queue<P, vector<P>, greater<P>> q;
        d[s] = 0;
        q.push(P(0,s));
        while (!q.empty()) {
            P e = q.top(); q.pop();
            int v = e.second;
            if (d[v] < e.first) continue;
            for (auto e: G[v]) {
                if (chmin(d[e.to],d[v]+e.cost)) {
                    q.push(P(d[e.to],e.to));
                }
            }
        }
    }
};

int main() {
    int n; cin >> n;
    dijkstra dj_f(n);
    dijkstra dj_s(n);
    rep(i,n-1) {
        int a, b; cin >> a >> b;
        dj_f.add_edge(a,b,1);
        dj_f.add_edge(b,a,1);
        dj_s.add_edge(b,a,1);
        dj_s.add_edge(a,b,1);
    }
    dj_f.run(1); dj_s.run(n);
    int ct_f = 0; int ct_s = 0;
    rep(i,n) {
        if (dj_f.d[i] <= dj_s.d[i]) ct_f++;
        else ct_s++;
    }
    if (ct_f <= ct_s) cout << "Snuke" << endl;
    else cout << "Fennec" << endl;
}

