void dfs(int node, vector<int> &pre, const vector<vector<int>> &graph) {
    for(auto n : graph.at(node)) {
        if (pre.at(n) == -1) {
            pre.at(n) = node;
            dfs(n, pre, graph);
        }
    }
}

