    int now = 0;
    while (now != N - 1) {
        route.emplace_back(now);
        now = pre.at(now);
    }
    route.emplace_back(N - 1);

    vector<int> color(N, -1);
    FOR(i, 0, route.size()) {
        if (i < ceil((int)route.size(), 2)) {
            color.at(route.at(i)) = 1;
        }
