    for(int i=0;i<n-1;i++){
        int a,b; cin>>a>>b; a--; b--;
        G[a].push_back({b,1});
        G[b].push_back({a,1});
    }
    dijkstra(0, d1);
    dijkstra(n-1, d2);
    int feneko=0, snuke=0;
    for(int i=0;i<n-1;i++){
            if(d1[i]>d2[i]) snuke++;
            else feneko++;
    }
    if(feneko>snuke) cout<<"Fennec"<<endl;
    else cout<<"Snuke"<<endl;
}

