using namespace std;

typedef struct {
	int fromIdx;
	int nowIdx;
} S;
int main()
{
	int N;

	cin >> N;
	vector<vector<int>> v(N);
	for (int i = 0; i < N - 1; i++) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		v[a].emplace_back(b);
		v[b].emplace_back(a);
	}
	vector<int> dst_f(N);
	dst_f[0] = 0;

	queue<S> que;
	que.push(S{ 0, 0 });

	/* fennecからの距離 */
	while (que.size()) {
		S s = que.front();
		que.pop();
		int dst = dst_f[s.nowIdx] + 1;
		for (int i : v[s.nowIdx]) {
			if (s.fromIdx != i) {
				que.push(S{ s.nowIdx, i });
				dst_f[i] = dst;
			}
		}
	}
	/* snukeが近い箇所をカウント */
	int s_point = 1;
	dst_f[N - 1] = 0;
	que.push(S{ N - 1, N - 1 });
	while (que.size()) {
		S s = que.front();
		que.pop();
		int dst = dst_f[s.nowIdx] + 1;
		for (int i : v[s.nowIdx]) {
			if ((dst < dst_f[i]) && (s.fromIdx != i)) {
				que.push(S{ s.nowIdx, i });
				s_point++;
				dst_f[i] = dst;
			}
		}
	}
	if (2 * s_point >= N) {
		cout << "Snuke";
	} else {
		cout << "Fennec";
	}
}

