#include <bits/stdc++.h>
using namespace std;


const int N = 1e5 + 10;
int n, f1, f2;
vector<vector<int>> adj;
bool seen[N];

int first(int u, int dist) {
    seen[u] = true;
    if (u == n - 1) {
        if (dist <= 2) f1 = u;
        return dist;
    }
    for (int v : adj[u]) {
        if (seen[v]) continue;
        int d = first(v, dist + 1);
        if (d > 0) {
            if (dist == d / 2 + 1) f1 = u;
            else if (dist == d / 2) f2 = u;
            return d;
        }
    }
    return -1;
}

int dfs(int u) {
    seen[u] = true;
    int cnt = 1;
    for (int v : adj[u]) {
        if (seen[v]) continue;
        cnt += dfs(v);
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n;
    adj.resize(n);
    for (int i = 0; i < n-1; i++) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    memset(seen, false, n);
    first(0, 0);

    int cnt1 = 0;
    memset(seen, false, n);
    seen[f1] = true;
    cnt1 += dfs(0) - 1;

    int cnt2 = 0;
    memset(seen, false, n);
    seen[f2] = true;
    cnt2 += dfs(n-1) - 1;

    if (cnt1 > cnt2) {
        cout << "Fennec" << '\n';
    }
    else {
        cout << "Snuke" << '\n';
    }
    return 0;
}

