template<class T> bool chmax(T &a, const T &b) { if(a < b) { a = b; return true; } return false; }
template<class T> bool chmin(T &a, const T &b) { if(a > b) { a = b; return true; } return false; }

int N;
vvi G;

void dfs(int n, vi& v)
{
    for(int e : G[n])
    {
        if(chmin(v[e], v[n]+1)) dfs(e, v);
    }
}

signed main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(20);

    cin >> N;
    G.resize(N);
    REP(i, N-1)
    {
        int a, b; cin >> a >> b;
        a--; b--;
        G[a].pb(b);
        G[b].pb(a);
    }

    vi f(N, INF), s(N, INF);
    f[0] = 0;
    dfs(0, f);

    s[N-1] = 0;
    dfs(N-1, s);

    int m;
    REP(i, N) if(f[i] == s[i]) m = i;

    vb check(N, false);
    queue<int> q;
    q.push(N-1);
    check[N-1] = true;
    while(!q.empty())
    {
        int p = q.front(); q.pop();
        check[p] = true;
        for(int e : G[p])
        {
            if(!check[e] && e != m) q.push(e);
        }
    }

    int c = accumulate(ALL(check), 0);
    if(c <= N-c) cout << "Fennec" << endl;
    else cout << "Sunuke" << endl;
}

