int CalcGrundy(V vec,bool turn){//引数にはcolorとターン

  if(grundy.count(mp(vec,turn))) return grundy[mp(vec,turn)];

  S set_;

  REP(i,n){
    if( vec[i] == (turn?1:2)){//塗る対象の色なら
      FOREACH(ed,edges[i]){
        if(vec[ed.first] == 0){//先が塗られていないなら
          V next_color = vec;
          next_color[ed.first] = (turn?1:2);//色を塗る
          set_.insert(CalcGrundy(next_color,!turn));
        }
      }
    }
  }

  int num=0;
  while(set_.count(num))num++;
  return (grundy[mp(vec,turn)] = num);
}

