  }
  dfs(0, 0);
  int now = N - 1;
  vector<int> v;
  while (now != 0) {
    v.PB(now);
    now = par[now];
  }
  v.PB(now);

  int b = 0, w = 0;
  REP(i, v.size()) {
    if (i <= (v.size() - 1) / 2) {
      for (auto to : vv[v[i]]) {
        if ((i > 0 && to == v[i - 1]) || (i < N - 1 && to == v[i + 1])) continue;
