using namespace std;

int color[100001];
vector <int> adj[100001];
queue <int> s1, s2;

int solve(void)
{
	int a, b;
	int res;
	fill(color, color + 100001, 0);
	while (1)
	{
		bool ok = false;
		while (s1.size() != 0)
		{
			a = s1.front();
			if (color[a] == 0)
			{
				ok = true;
				color[a] = 1;
				s1.pop();
				break;
			}
			s1.pop();
		}

		if (ok == false)
		{
			res = 2;
			break;
		}

		ok = false;
		while (s2.size() != 0)
		{
			b = s2.front();
			if (color[b] == 0)
			{
				ok = true;
				color[b] = 2;
				s2.pop();
				break;
			}
			s2.pop();
		}

		if (ok == false)
		{
			res = 1;
			break;
		}

		for (int i = 0; i < adj[a].size(); i++)
		{
			if (color[adj[a][i]] == 0)
			{
				s1.push(adj[a][i]);
			}
		}

		for (int i = 0; i < adj[b].size(); i++)
		{
			if (color[adj[b][i]] == 0)
			{
				s2.push(adj[b][i]);
			}
		}
	}

	return res;
}

int main()
{
	int a, b, flag, n;

	cin >> n;

	for (int i = 0; i < n - 1; i++)
	{
		cin >> a >> b;
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	s1.push(1);
	s2.push(n);
	flag=solve();

	if (flag == 1)
	{
		cout << "Fennec" << endl;
	}
	else
	{
		cout << "Snuke" << endl;
	}

	return 0;
}

