int dfs(int c,int r){
    for(int i = 0;i < G[r].size();i ++){
        int x = G[r][i];
        if(visited[c][x]) continue;
        d[c][x] = d[c][r] + 1;
        visited[c][x] = 1;
        dfs(c,x);
    }
}

