    visited[1][n-1] = 1;

    dfs(0,0);
    dfs(1,n-1);

    for(int i = 0;i < n;i ++){
        if(d[0][i]<=d[1][i]) cnt ++;
    }
    if(cnt>n/2) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

    return 0;
}

