#include <bits/stdc++.h>
using namespace std;

const int N=110000;
struct Edge {
    int go,next;
} eg[N<<1];
int last[N],tot;
int fa[N],dis[N],sz[N];

void addedge(int x,int y)
{
    eg[tot]={y,last[x]};
    last[x]=tot++;
}

void dfs(int u,int f,int d)
{
    fa[u]=f;dis[u]=d;sz[u]=1;
    for (int i=last[u];i!=-1;i=eg[i].next) {
        int v=eg[i].go;
        if (v==f) continue;
        dfs(v,u,d+1);
        sz[u]+=sz[v];
    }
}

int main()
{
    int n;
    scanf("%d",&n);
    tot=0;
    memset(last,-1,sizeof(last));
    for (int i=1;i<n;i++) {
        int x,y;
        scanf("%d%d",&x,&y);
        addedge(x,y);
        addedge(y,x);
    }
    dfs(1,0,0);
//    for (int i=1;i<=n;i++) {
//        printf("%d ",dis[i]);
//    }
//    puts("");
//    for (int i=1;i<=n;i++) {
