//    }
//    puts("");
//    for (int i=1;i<=n;i++) {
//        printf("%d ",sz[i]);
//    }
//    puts("");
    int d=dis[n];
    int h=0,x=n;
    while ((h+1+h+1)<=d) {
        x=fa[x];++h;
    }
    puts(n-sz[x]>sz[x]?"Fennec":"Snuke");
    return 0;
}

