int n,s1[MAXN],s2[MAXN],s3[MAXN];
vector<vector<int> > g(MAXN);
bool vis[MAXN],inP[MAXN];
vector<int> path;
void dfs1(int v){
	vis[v]=1;
	s1[v]=0;
	if(inP[v] || v==n-1)return;
	for(auto u:g[v])if(!vis[u]){dfs1(u);s1[v]+=s1[u];}
	s1[v]++;
}
void dfs2(int v){
	vis[v]=1;
	s2[v]=0;
	if(inP[v] || !v)return;
	for(auto u:g[v])if(!vis[u]){dfs2(u);s2[v]+=s2[u];}
	s2[v]++;
}
void dfs3(int v){
	vis[v]=1;
	s3[v]=1;
	for(auto u:g[v])if(!vis[u] && !inP[u] && u!=0 && u!=n-1){dfs3(u);s3[v]+=s3[u];}
}
int get_path(int v,int par){
	if(v==(n-1))return 1;
	for(auto u:g[v])if(u!=par && get_path(u,v)){if(v)path.pb(v);return 1;}
	return 0;
}
