		g[t1].pb(t2);
		g[t2].pb(t1);
	}
	REP(i,n)inP[i]=0;
	get_path(0,-1);
	for(auto u:path)inP[u]=1;
	reverse(path.begin(),path.end());
	REP(i,n)vis[i]=0;
	dfs1(0);
	REP(i,n)vis[i]=0;
	dfs2(n-1);
	REP(i,n)vis[i]=0;
	for(auto u:path)dfs3(u);
	for(int i=0;i<(path.size()+1)/2;i++)s1[0]+=s3[path[i]];
	for(int i=(path.size()+1)/2;i<path.size();i++)s2[n-1]+=s3[path[i]];
	cout << (s1[0]>s2[n-1]?"Fennec":"Snuke") << '\n';
	return 0;
}

