const int INF = 10e9;
vector<int> tree[100050];
ll fv = 0;
ll com = 0;
int n;
bool used[100050];
void recur(int v, int c) {

	used[v] = true;
	if (v == n) {
		com = c;
	}
	else {
		bool next = false;
		for (size_t i = 0; i < tree[v].size(); i++)
		{
			if (!used[tree[v][i]]) {

				recur(tree[v][i], c + 1);
				next = true;
			}
		}
		if (!next) {
			fv += c;
		}
	}

}
void FennecVSSnuke(){

	cin >> n;
	for (size_t i = 1; i < n - 1; i++)
	{
		int a, b;
		cin >> a >> b;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}

	recur(1, 0);
	ll sv = (n - 1) - com - fv;
	if (com % 2 == 0) {
		if (fv == sv || fv > sv) {
			cout << "Fennec" << endl;
		}
		else {
			cout << "Snuke" << endl;
		}
	}
	else {
		if (fv == sv || fv < sv) {
			cout << "Snuke" << endl;
		}
		else if (fv > sv) {
			cout << "Fennec" << endl;
		}
	}

}

