void find_way(int v){
    way.push_back(v);
    if(v==0)return;
    rep(i,G[v].size())if(dist.at(G[v].at(i))<dist.at(v))find_way(G[v].at(i));
}

int count(int v, int u){
    if(G[v].size()==1)return 1;
    int cnt=1;
    rep(i,G[v].size())if(G[v].at(i)!=u)cnt+=count(G[v].at(i),v);
    return cnt;
}

signed main(){

    cin>>n;
    rep(i,n-1){
        int a,b; cin>>a>>b;
        a--; b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    dist=vector<int>(n,-1);
    dist.at(0)=0;
    queue<int> que;
    que.push(0);
    while(que.size()){
        int p=que.front(); que.pop();
        rep(i,G[p].size()){
            if(dist.at(G[p].at(i))==-1){
                dist.at(G[p].at(i))=dist.at(p)+1;
                que.push(G[p].at(i));
            }
        }
    }

    find_way(n-1);
    reverse(all(way));
    int mid=way.at((way.size()-1)/2),mid2=way.at((way.size()+1)/2);
    int cnt=count(mid,mid2);
    cout<<(cnt>n-cnt?"Fennec":"Snuke")<<endl;

}

