using namespace std;
void dfs(vector<int> *G, int &n, int m, int u, vector<bool> &visited) {
  visited[u] = true;
  n++;
  for (int v : G[u]) {
    if (!visited[v] && v != m) {
      visited[v] = true;
      dfs(G,n,m,v,visited);
    }
  }
}
int main() {
  int N,a,b,n1=0,n2=0,m1,m2;
  cin >> N;
  vector<int> G[N];
  vector<bool> visited(N);
  int d[N],p[N];
  for (int i = 1; i < N; i++) {
    cin >> a >> b;
    G[--a].push_back(--b);
    G[b].push_back(a);
  }
  queue<int> q;
  for (q.push(0), d[0] = 0, p[0] = -1; !q.empty(); q.pop()) {
    for (int v : G[q.front()]) {
      if (!visited[v]) {
        visited[v] = true;
        d[v] = d[q.front()]+1;
        q.push(v);
        p[v] = q.front();
      }
    }
  }
  m1 = N-1;
  m2 = p[m1];
  for (int n = (d[N-1]-1)/2; n; n--, m1 = m2, m2 = p[m2]);
  visited = vector<bool>(N);
  dfs(G,n1,m1,m2,visited);
  visited = vector<bool>(N);
  dfs(G,n2,m2,m1,visited);
  if (n1 > n2) {
    cout << "Fennec";
  } else {
    cout << "Snuke";
  }
}

