const int MAX_N = 100050;
int a[MAX_N], b[MAX_N];
int N;
int parent[MAX_N];
std::vector<int> adj[MAX_N];

int main(int argc, char **argv) {
    std::cin >> N;

    for (int i = 1; i <= N - 1; i++) {
        std::cin >> a[i] >> b[i];
    }

    for (int i = 1; i <= N - 1; i++) {
        adj[a[i]].push_back(b[i]);
        adj[b[i]].push_back(a[i]);
    }

    for (int i = 1; i <= N; i++) {
        parent[i] = -1;
    }

    std::queue<int> que;
    que.push(1);
    parent[1] = 1;

    while (!que.empty()) {
        int tmp = que.front();
        que.pop();
        for (auto ad : adj[tmp]) {
            if (parent[ad] == -1) {
                parent[ad] = tmp;
                que.push(ad);
            }
        }
    }

    std::vector<int> path;
    int tmp = N;
    while (true) {
        path.push_back(tmp);
        if (tmp == 1) {
            break;
        }
        tmp = parent[tmp];
    }

    int center = path.size() / 2;
    int e1 = path[center];
    int e2 = path[center-1];

    int bridge = -1;
    for (int i = 1; i <= N - 1; i++) {
        if ((a[i] == e1 && b[i] == e2) ||
            (a[i] == e2 && b[i] == e1)
        ) {
            bridge = i;
            break;
        }
    }

    for (int i = 1; i <= N; i++) {
        parent[i] = -1;
    }

    int num = 0;
    que.push(1);
    parent[1] = 1;
    num++;

    while (!que.empty()) {
        int tmp = que.front();
        que.pop();
        for (auto ad : adj[tmp]) {
            if ((a[bridge] == tmp && b[bridge] == ad) ||
                (b[bridge] == tmp && a[bridge] == ad)
            ) {
                continue;
            }
            if (parent[ad] == -1) {
                parent[ad] = tmp;
                que.push(ad);
                num++;
            }
        }
    }

    if (N - num < num) {
        std::cout << "Fennec" << std::endl;
    } else {
        std::cout << "Snuke" << std::endl;
    }

    return 0;
}

