bool dfs(int curr){
	visited[curr] = true;
	if(curr==n){
		path.push_back(n);
		return true;
	}
	bool ret = 0;
	for(int i=0; i<tree[curr].size(); i++){
		int nxt = tree[curr][i];
		if(!visited[nxt]){
			ret|=dfs(nxt);
		}
	}
	if(ret) path.push_back(curr);
}
void black(int curr){
	visited[curr] = true;
	color[curr] = 1;
	for(int i=0; i<tree[curr].size(); i++){
		int nxt = tree[curr][i];
		if(!visited[nxt] && color[nxt]!=2) black(nxt);
	}
}
void white(int curr){
	visited[curr] = true;
	color[curr] = 2;
	for(int i=0; i<tree[curr].size(); i++){
		int nxt = tree[curr][i];
		if(!visited[nxt] && color[nxt]!=1) white(nxt);
	}
}

