struct Node {
	public:
		vector <ll> edge_to; //接続されているノードID
		vector <ll> edge_cost; //エッジのコスト
		bool done;
		ll id, cost;
};

bool operator < (const Node &a, const Node &b){
	return (a.cost < b.cost);
}
bool operator > (const Node &a, const Node &b){
	return (a.cost > b.cost);
}


vector<Node> node;
