vector<ll> y_cost;
void dijkstra(ll s) {
	priority_queue<Node, vector<Node>, greater<Node> > pq;
	node[s].cost = 0;
	pq.push(node[s]);
	while(!pq.empty()){
		Node n = pq.top(); pq.pop();
		for (ll i = 0; i < n.edge_to.size(); i++) {
			if (!node[n.edge_to[i]].done) {
				if (node[n.edge_to[i]].cost > n.cost + n.edge_cost[i]) {
					node[n.edge_to[i]].cost = n.cost + n.edge_cost[i];
				}
				pq.push(node[n.edge_to[i]]);
			}
		}
		node[n.id].done = true;
	}
}

