#include<bits/stdc++.h>
using namespace std;

vector<vector<int>> edge(100'000);
vector<int> ranks(100'000, 0);
vector<int> num(100'000, 0);
vector<int> parent(100'000, 0);
vector<bool> visited(100'000, false);

int dfs(int u){
    visited[u] = true;
    int tmp = 1;
    for (int i = 0; i < edge[u].size(); i++){
        if (visited[edge[u][i]]) continue;
        ranks[edge[u][i]] = ranks[u] + 1;
        parent[edge[u][i]] = u;
        tmp += dfs(edge[u][i]);
    }
    num[u] = tmp;
    return tmp;
}

int main(){
    int n;
    cin >> n;
    int a, b;
    for (int i = 1; i < n; i++){
        cin >> a >> b;
        a--; b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    dfs(0);
    int g = (ranks[n - 1] + 1) / 2;
    int s = n - 1;
    while (ranks[s] > g) s = parent[s];
    if (num[s] * 2 >= n) cout << "Snuke" << endl;
