vii tree;
/*FUNCs=================================================*/
vec<int> dist;
queue<int> que;
void bfs(int s) {
    que.push(s);
    dist[s] = 0;
    while(que.size()) {
        int v = que.front(); que.pop();
        for(int nv : tree[v]) {
            if(dist[nv]!=-1) continue;
            if(seen[nv]) continue;
            dist[nv] = dist[v] + 1;
            que.push(nv);
        }
    }
    return;
}

