signed main(){
    int START_TIME = clock();
    cin.tie(nullptr);
    ios::sync_with_stdio(false);   //cin cout 高速化
    // cout << fixed << setprecision(15);

    /**
     * 1 ~ n の最短距離をまず陣取りのように埋める。
     * 後は他の場所を埋めてく。先に尽きた方が負けなので、それをカウント。
     */

    cin >> n;
    tree.resize(n);
    seen.assign(n, 0);
    dist.assign(n, -1);
    rep(i,n-1) {
        cin >> a >> b;
        --a, --b;
        tree[a].push_back(b);
        tree[b].push_back(a);
    }

    // find the shortest route from 0 to n-1
    bfs(0);
    int dist_fennec_snuke = dist[n-1]+1;
//    debug(dist_fennec_snuke);
    for(int v = n-1; ; ) {
        seen[v] = 1;
        if(!v) break;
        int u;
        for(int pv : tree[v]) if(dist[pv] + 1 == dist[v]) u = pv;
        v = u;
    }

    vi filled(n, -1);
    int f = 0, s = n-1;
    filled[f] = 1;  // fennec
    filled[s] = 0;  // snuke
    while(1) {
        int nf;
        for(int tmp : tree[f]) if(seen[f] && seen[tmp]) nf = tmp;
        if(filled[nf]!=-1) break;
        f = nf;
        filled[f] = 1;
        int ns;
        for(int tmp : tree[s]) if(seen[s] && seen[tmp]) ns = tmp;
        if(filled[ns]!=-1) break;
        s = ns;
        filled[s] = 0;
    }

    // fennec_fill  fill with 11
    que.push(0);
    filled[0] = 11;
    while(que.size()) {
        f = que.front(); que.pop();
        for(int nf : tree[f]) {
            if(filled[nf]==11) continue;
            if(filled[nf]==0) continue;
            filled[nf] = 11;
            que.push(nf);
        }
    }

    // fennec_fill  fill with 10
    que.push(n-1);
    filled[n-1] = 10;
    while(que.size()) {
        s = que.front(); que.pop();
        for(int ns : tree[s]) {
            if(filled[ns] == 10) continue;
            if(filled[ns] == 11) continue;  // <- 忘れずに！
            if(filled[ns] == 1) continue;
            filled[ns] = 10;
            que.push(ns);
        }
    }

    // count
    int snuke_cnt = 0;
    int fennec_cnt = 0;

    rep(i,n) {
        if(filled[i] == 11) ++fennec_cnt;
        else ++snuke_cnt;
    }

    if(fennec_cnt<=snuke_cnt) cout << "Snuke" << '\n';
    else cout << "Fennec" << '\n';

    // printf("ExecutionTime: %d /ms\n",1000*(int)((clock()-START_TIME)/CLOCKS_PER_SEC));
}

