    if(flag == 0) distW[s] = 0;

    while(!que.empty()){
        int from = que.front();
        que.pop();

        for(auto to : G[from]){
            if(flag == 1){
                if(distB[to] == INF){
                    distB[to] = distB[from] + 1;
                    que.push(to);
                }
            }
            if(flag == 0){
                if(distW[to] == INF){
                    distW[to] = distW[from] + 1;
                    que.push(to);
                }
            }
        }
    }
}

