ll dfs(int s, WeightedGraph<ll>& adj_list) {
  ll ret = !visited[s];
  visited[s] = true;
  rep(i, 0, sz(adj_list[s])) {
    int to = adj_list[s][i].to;
    if (visited[to]) continue;
    ret += dfs(to, adj_list);
  }

  return ret;
}

