const ll inf = 1LL<<60;
const ll mod = 1000000007;

template<typename T>
struct Dijkstra {
  int n;
  WeightedGraph<T> es;
  vector<T> dist;
  vector<int> prev;
  Dijkstra(int _n, WeightedGraph<T> _es) {
    init(_n, _es);
  }
  void init(int _n, WeightedGraph<T> _es) {
    n = _n; es = _es;
  }
  void reset() {
    dist.assign(n, inf);
    prev.assign(n, -1);
  }
  void run(int s) {
    reset();
    dist[s] = 0;
    using P = pair<T, int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.push(P(0, s));
    while (!pq.empty()) {
      P p = pq.top(); pq.pop();
      T v = p.second;
      if (dist[v] < p.first) continue;
      for (int i=0; i<(int)es[v].size(); i++) {
        edge<T> e = es[v][i];
        if (dist[e.to] > dist[v] + e.cost) {
          dist[e.to] = dist[v] + e.cost;
          pq.push(P(dist[e.to], e.to));
          prev[e.to] = v;
        }
      }
    }
  }
  vector<int> getpath(int t) {
    vector<int> path;
    if (dist[t] == inf) return path;
    for (; t!=-1; t=prev[t]) path.push_back(t);
    reverse(path.begin(), path.end());
    return path;
  }
};

int main()
{
  ll n; cin>>n;
  WeightedGraph<ll> g(n);
  rep(i, n-1) {
    ll a,b; cin>>a>>b; a--; b--;
    g[a].push_back(edge<ll>(b, 1));
    g[b].push_back(edge<ll>(a, 1));
  }

  Dijkstra dij1(n, g);
  Dijkstra dij2(n, g);

  dij1.run(0);
  dij2.run(n-1);

  ll aa = 0;
  ll bb = 0;
  rep(i, n) {
    if (dij1.dist[i] <= dij2.dist[i]) aa++;
    else bb++;
  }

  if (aa >= bb) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;

  return 0;
}

