{
  uint32_t num;
  cin >> num;

  for (uint32_t i = 1; i < num; i++) {
    uint32_t a, b;
    cin >> a >> b;
    tree[a].push_back(b);
    tree[b].push_back(a);
  }

  for (uint32_t i = 1; i <= num; i++) {
    status[i] = WHITE;
    distance_from0[i] = 0;
  }
  dist(1, 0, callback0);

  for (uint32_t i = 1; i <= num; i++) {
    status[i] = WHITE;
    distance_fromN[i] = 0;
  }
  dist(num, 0, callbackN);

  uint32_t black = 0, white = 0;
  for (uint32_t i = 1; i <= num; i++) {
    if (distance_from0[i] <= distance_fromN[i]) {
      black++;
    } else {
      white++;
    }
  }

  if (white <= black) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }

  return 0;
}

