int cnt(vector<int> *v,int a,int b, int end)
{
	unordered_set<int>s;
	queue<int> q;
	q.push(a);
	while(!q.empty())
	{
		int y = q.front();
		q.pop();
		s.insert(y);
		for(int i: v[y])
		{
			if(i==b)
				continue;
			else if(s.count(i)==0)
			{
				s.insert(i);
				q.push(i);
			}
		}
	}
	return s.size();
}

void printPath(vector<int> stack, vector<int> *v) 
{ 
	int black=0, white = 0, n = (stack.size()+1)/2;
	black = cnt(v,1,stack[n],stack[n+1]);
	white = stack[stack.size()-1]-black;
	if(black>white)
		cout<<"Fennec"<<endl;
	else
		cout<<"Snuke"<<endl; 
} 

void DFS(vector<int> *v, bool *vis, int x, int y, vector<int> stack) 
{ 
	stack.push_back(x); 
	if (x == y) {
		printPath(stack,v); 
		return;
	} 
	vis[x] = true;
	int flag = 0; 
	if (!v[x].empty()) { 
		for (int j = 0; j < v[x].size(); j++) {
			if (vis[v[x][j]] == false) { 
				DFS(v, vis, v[x][j], y, stack); 
				flag = 1; 
			} 
		} 
	} 
	if (flag == 0) { 
		stack.pop_back(); 
	} 
}

