#define MAX_SIZE 100001

vector<int> tree[MAX_SIZE+1];
int parent[MAX_SIZE] = {};
int score[MAX_SIZE] = {};

bool debugFlag = false;

int dfs(int v, int p)
{
    if(debugFlag)
    {
        cout << "dfs" << endl;
    }
    int result = 0;
    parent[v] = p;
    for(int i = 0; i < static_cast<int>(tree[v].size()); ++i)
    {
        int nv = tree[v].at(i);
        if(nv == p)
        {
            continue;
        }
        result += dfs(nv, v);
    }
    ++result;
    score[v] = result;
    return result;
}

int calcPathNum(int n)
{
    if(debugFlag)
    {
        cout << "calcPathNum" << endl;
    }
    int pathNum = 1;
    int p = parent[n];
    while(p != 1)
    {
        if(debugFlag)
        {
            cout << "parent : " << p << endl;

        }
        pathNum += 1;
        p = parent[p];
    }
    if(pathNum%2 != 0)
    {
        pathNum /= 2;
        ++pathNum;
    }
    else
    {
        pathNum /= 2;
    }

    return pathNum;
}

int ScoreDec(int n)
{
    if(debugFlag)
    {
        cout << "ScoreDec" << endl;
    }
    int result = 0;
    int pathNum = calcPathNum(n);
    int p = n;

    for(int i = 0; i < pathNum; ++i)
    {
        result += score[p];
        p = parent[p];
    }
    if(debugFlag)
    {
        cout << "2p scr : "<< result << endl;
    }
    return result;
}

