vector<int> bfs(int s,const graph &g){
    int _size = g.size();
    vector<int> c(_size,-1);
    c[s] = 0;
    queue<int> que;
    que.push(s);
    while(!que.empty()){
        int x = que.front();
        que.pop();
        for(auto nx: g[x]){
            if(c[nx]<0){
                que.push(nx);
                c[nx] = c[x]+1;
            }
        }
    }
    return c;
}

