int dfs(vector<vector<int>> &G,int v,int p,vector<int> &number,vector<int> &parent,vector<int> &depth){
  int ans=1;
  parent.at(v)=p;
  for(auto nv:G.at(v)){
    if(nv==p){
      continue;
    }
    depth.at(nv)=depth.at(v)+1;
    ans+=dfs(G,nv,v,number,parent,depth);
  }
  return number.at(v)=ans;
}

