#define REP(i, a, n) for(int i=a; i<n; i++)
#define RREP(i, a, n) for(int i=n-1; i>=a; i--)
#define ll long long

int main()
{
	int N;
	cin >> N;

	vector<vector<int>> v(N);
	REP(i, 0, N - 1) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		v[a].push_back(b);
		v[b].push_back(a);
	}

	stack<int> stkF, stkS;
	int sumF = 0, sumS = 0;
	bool hist[100001];
	REP(i, 0, N) hist[i] = 0;

	// Fennec
	stkF.push(0);
	while (!stkF.empty()) {
		int cur = stkF.top();
		stkF.pop();

		if (!hist[cur]) {
			hist[cur] = true;
			sumF++;
			REP(i, 0, v[cur].size()) {
				if (v[cur][i] != N - 1) stkF.push(v[cur][i]);
			}
		}
	}

	REP(i, 0, N) hist[i] = 0;
	// Snuke
	stkS.push(N - 1);
	while (!stkS.empty()) {
		int cur = stkS.top();
		stkS.pop();

		if (!hist[cur]) {
			hist[cur] = true;
			sumS++;
			REP(i, 0, v[cur].size()) {
				if (v[cur][i] != 0)stkS.push(v[cur][i]);
			}
		}
	}

	sumF--;
	sumS--;

	if (sumF >= sumS) cout << "Fennec" << endl;
	else cout << "Snuke" << endl;

	return 0;
}

