const int maxn = 200005;
int n;
struct Node{
	vector<int> to;
}node[maxn];

bool vis[maxn];
int tree[maxn];
bool flag=false;
void dfs(int be,int en)
{
	vis[be]=true;
	if(be==en)
	{
		flag=true;
		return;
	}
	int len=node[be].to.size();
	for(int i=0;i<len;i++)
	{
		if(!vis[node[be].to[i]]&&!flag)
		{
			dfs(node[be].to[i],en);
			if(!flag)vis[node[be].to[i]]=false;
		}
	}
}
int temp=0;
void go(int be)
{
	vis[be]=true;
	int len=node[be].to.size();
	for(int i=0;i<len;i++)
	{
		if(!vis[node[be].to[i]])
		{
			temp++;
			go(node[be].to[i]);
		}
	}
}
int main()
{

	cin>>n;
	for(int i=0;i<n-1;i++)
	{
		int a,b;
		scanf("%d%d",&a,&b);
		node[a].to.push_back(b);
		node[b].to.push_back(a);
	}
	dfs(1,n);
	int l=1;
	tree[0]=1;
	for(int i=2;i<n;i++)
	{
		if(vis[i])
		{
			tree[l++]=i;
		}
	}
	tree[l++]=n;
	int ansa=0;
	int ansb=0;
	for(int i=0;i<l/2;i++)
	{
		temp=0;
		go(tree[i]);
		ansa+=temp+1;
		temp=0;
		go(tree[l-1-i]);
		ansb+=temp+1;	
	}
	if(l%2)
	{
		temp=0;
		go(tree[l/2]);
		ansa+=temp+1;
	}
	//cout<<ansa<<endl<<ansb<<endl;
	if(ansa>ansb)printf("Fennec\n");
	else printf("Snuke\n");

}

