using namespace std;
typedef long long ll;

int n;
vector<int>g[100005];

int dfs(int u, int p, int now, int bad){
    if(u != bad) return -1;
    bool ex = false;
    for(int v : g[u]){
        if(v==p) continue;
        ex = true;
        return dfs(v, u, now+1, bad);
    }
    if(!ex) return now;
}

int dist(int u, int p, int now, int goal){
    if(u == goal) return now;
    for(int v : g[u]){
        if(v==p) continue;
        return dfs(v, u, now+1, goal);
    }
}

