    for(auto u : g[0]){
        int k = dfs(u, 0, 1, n-1);
        if(k == -1) continue;
        else mb++;
    }
    for(auto u : g[n-1]){
        int k = dfs(u, n-1, 1, 0);
        if(k == -1) continue;
        else mw++;
    }
    if((distance+1)/2+mb>distance-(distance+1)/2+mw){
