template< typename T >
using WeightedGraph = vector< Edges< T > >;
using UnWeightedGraph = vector< vector< int > >;
template< typename T >
using Matrix = vector< vector< T > >;

ll dfs(UnWeightedGraph &G, vector<bool> &vi, vector<ll> &num, ll n) {
	ll cnt = 1;
	REP(i, G[n].size()) {
		if (!vi[G[n][i]]) {
			vi[G[n][i]] = true;
			cnt += dfs(G, vi, num, G[n][i]);
		}
	}
	return num[n] = cnt;
}

ll dfs2(UnWeightedGraph &G, vector<bool> &vi, vector<bool> &ex, ll t, ll n) {
	bool flag = false;
	if (n == t) flag = true;
	REP(i, G[n].size()) {
		if (!vi[G[n][i]]) {
			vi[G[n][i]] = true;
			flag |= dfs2(G, vi, ex, t, G[n][i]);
		}
	}
	ex[n] = flag;
	return ex[n];
}

