        G[b].push_back(a);
    }

    using P = std::pair<int, int>;  // (頂点, プレイヤー)
    std::queue<P> Q;

    memset(color, -1, sizeof(color));

    int counter[2] = {};

    auto push = [&](int v, int c) {
        Q.push(P(v, c));
        color[v] = c;

        counter[c]++;
    };

    push(0, 0);
    push(N - 1, 1);

    while (!Q.empty()) {
        int v = Q.front().first,
            c = Q.front().second; Q.pop();

        for (int to : G[v]) {
            if (color[to] < 0) push(to, c);
        }
    }

    if (counter[0] > counter[1]) {
        std::cout << "Fennec" << std::endl;
    } else {
        std::cout << "Snuke" << std::endl;
    }

    return 0;
}

