      if (child == parent) continue;
      if (child == 0 || child == n - 1) continue;
      ret += dfs(child, node);
    }
    return ret;
  });

  bool fennec;
  int f = dfs(0, -1), s = dfs(n - 1, -1);
  if (dist % 2 == 0) {
