bool visited[100000]={};
int prev_node[100000], n_cost, n;
void DFS(int i, int cost, vvi tree)
{
	visited[i]=true;

	if(i==n-1) n_cost=cost;

	rep(j, tree[i].size()){
		if(visited[tree[i][j]]) continue;
		prev_node[tree[i][j]]=i;
		DFS(tree[i][j], cost+1, tree);
	}

}
int main(void)
{
	cin>>n;

	vvi tree(n);

	rep(i, n-1){
		int a, b;
		cin>>a>>b;
		tree[a-1].push_back(b-1);
		tree[b-1].push_back(a-1);
	}
	prev_node[0]=-1;
	rep(i, n) visited[i]=false;

	DFS(0, 0, tree);

	int j=n-1, cnt=0;
	while(1){
		cnt++;
		if(cnt>=(int)(n_cost/2+n_cost%2)) break;
		j=prev_node[j];
	}
	rep(k, tree[j].size()){
		if(tree[j][k]==prev_node[j]){
			tree[j].erase(tree[j].begin()+k);
		}
	}
	rep(k, tree[prev_node[j]].size()){
		if(tree[prev_node[j]][k]==j){
			tree[prev_node[j]].erase(tree[prev_node[j]].begin()+k);
		}
	}
	rep(i, n) visited[i]=false;

	DFS(0, 0, tree);

	int ans=0;
	rep(i, n){
		if(visited[i]) ans++;
	}
	if(ans>n-ans){
		cout<<"Fennec"<<endl;
	}else{
		cout<<"Snuke"<<endl;
	}
}

