void dfs(int on, int par){
    if(on == N-1){
        f = true;
        path.push_back(on);
        return;
    }
    for(int &to:E[on]){
        if(to==par || f) continue;
        dfs(to, on);
    }
    if(f) path.push_back(on);
    return;
}

int countX(int on, int par){
    int res = 1;
    int mid = path[(path.size()+1)/2];
    for(int &to:E[on]){
        if(to!= mid && to!=par){
            res += countX(to, on);
        }
    }
    return res;
}

int countO(int on, int par){
    int res = 1;
    int mid = path[(path.size()+1)/2 - 1];
    for(int &to:E[on]){
        if(to!= mid && to!=par){
            res += countO(to, on);
        }
    }
    return res;
}

