int search(int s) {
  queue<int> q;
  int count = 0;
  q.push(s);
  while(!q.empty()) {
    count++;
    int c = q.front(); q.pop();
    for (int i = 0; i < v[c].size(); i++) {
      //printf("%d\t%d\n", c, p[v[c][i]]);
      if (p[v[c][i]] <= p[s]) continue;
      p[v[c][i]] = -1;
      q.push(v[c][i]);
    }
  }
  p[s] = -1;
  return count;
}

