using namespace std;
using LLONG = long long;
const LLONG MOD = 1000000007;

int main()
{
    // 互いに相手からの距離が最短の頂点を塗っていくのが最適？
    int N; cin >> N;
    vector<vector<int>> adList(N);
    for (int i = 0; i < N - 1; ++i)
    {
        int ai, bi; cin >> ai >> bi; --ai; --bi;
        adList[ai].push_back(bi);
        adList[bi].push_back(ai);
    }
    // 互いに相手のスタート地点に向かうパス上を塗っていく:O(N)
    vector<int> parents(N, -1);
    vector<int> dists(N, 1e9);
    dists[0] = 0;
    deque<int> Q{ 0 };
    while (!Q.empty())
    {
        int v = Q.front(); Q.pop_front();
        for (const int n : adList[v])
        {
            if (dists[n] > dists[v] + 1)
            {
                dists[n] = dists[v] + 1;
                parents[n] = v;
                Q.push_back(n);
            }
        }
    }
    deque<int> path{ N - 1 };
    int parent = parents[N - 1];
    for (;;)
    {
        path.push_front(parent);
        if (parent == 0) break;
        parent = parents[parent];
    }
    // パス上を交互に塗っていく:O(N)
    vector<int> colors(N, 0);
    while (!path.empty())
    {
        colors[path.front()] = 1; path.pop_front();
        if (path.empty()) break;
        colors[path.back()] = -1; path.pop_back();
    }
    // パス以外のマスを塗っていく:O(N)
    vector<bool> notVisited(N, true);
    Q.push_back(0);
    notVisited[0] = false;
    notVisited[N - 1] = false;
    while (!Q.empty())
    {
        int v = Q.front(); Q.pop_front();
        for (const int n : adList[v])
        {
            if (colors[n] != -1 && notVisited[n])
            {
                colors[n] = 1;
                notVisited[n] = false;
                Q.push_back(n);
            }
        }
    }
    Q.push_back(N - 1);
    while (!Q.empty())
    {
        int v = Q.front(); Q.pop_front();
        for (const int n : adList[v])
        {
            if (colors[n] != 1 && notVisited[n])
            {
                colors[n] = -1;
                notVisited[n] = false;
                Q.push_back(n);
            }
        }
    }
    // より多くのマスを塗れる方が勝者
    cout << (count(colors.begin(), colors.end(), 1) >
        count(colors.begin(), colors.end(), -1) ? "Fennec" : "Snuke") << endl;
}

