	ll cnt = 1;
	REP(i, G[n].size()) {
		if (!vi[G[n][i]]) {
			vi[G[n][i]] = true;
			cnt += dfs(G, vi, num, G[n][i]);
		}
	}
	return num[n] = cnt;
}

