  V<int> color(n, -1);
  color[0] = 0;
  color[n - 1] = 1;
  auto solve = [&]() {
    dbg(color);

    Fix([&](auto rec, int node, int parent) -> int {
      if (node == n - 1) return 0;
      for (int child : to[node]) {
        if (child == parent) continue;
        int d = rec(child, node);
        if (d >= 0) {
          if (color[node] == -1) {
            color[node] = (d % 2) == 0 ? 0 : 1;
          }
          return d + 1;
        }
      }
      return -1;
    })(0, -1);
    dbg(color);

    rep(i, n) if (color[i] != -1) {
      Fix([&](auto rec, int node, int parent) -> void {
        for (int child : to[node]) {
          if (child == parent) continue;
          if (color[child] != -1) continue;
          dbg(node, color[node], child);
          color[child] = color[node];
          rec(child, node);
        }
      })(i, -1);
      dbg(i, color);
    }
    dbg(color);

    int f = count(all(color), 0);
    int s = count(all(color), 1);
    assert(f + s == n);

    wt((f > s) ? "Fennec" : "Snuke");
  };
  solve();
}

