typedef long long ll;
using Graph = vector<vector<ll>>;
const ll mod = 1000000007;

int main() {
    int n;
    cin >> n;

    Graph to(n), cost(n);
    rep(i, n-1) {
        ll a, b;
        cin >> a >> b;
        a--;  b--;
        to[a].push_back(b);
        to[b].push_back(a);
        cost[a].push_back(1LL);
        cost[b].push_back(1LL);
    }

    vector<ll> dist0(n, -1LL), distN(n, -1LL);
    queue<ll> Q0, QN;

    dist0[0] = 0;
    Q0.push(0);
    while(!Q0.empty()) {

        ll v = Q0.front();
        Q0.pop();

        rep(i, to[v].size()) {

            ll u = to[v][i];

            if(dist0[u] != -1) {
                continue;
            }

            dist0[u] = dist0[v] + cost[v][i];
            Q0.push(u);
        }
    }

    distN[n-1] = 0;
    QN.push(n-1);
    while(!QN.empty()) {

        ll v = QN.front();
        QN.pop();

        rep(i, to[v].size()) {

            ll u = to[v][i];

            if(distN[u] != -1) {
                continue;
            }

            distN[u] = distN[v] + cost[v][i];
            QN.push(u);
        }
    }

    int cnt0 = 0, cntN = 0;
    rep(i, n) { 
        if(dist0[i] <= distN[i]) {
            cnt0++;
        }
        else {
            cntN++;
        }
    }

    if(cnt0 > cntN) {
        cout << "Fennec";
    }
    else {
        cout << "Snuke";
    }

    cout << endl;
    return 0;
}

