    int N;
    std::cin >> N;

    Graph g(N, Graph::Edge::Type::Undirected, INF);

    REP(i, N - 1) {
        int a, b;
        std::cin >> a >> b;
        a--; b--;
        g.addEdge(a, b, 1);
    }

    g.setCostToSpecificVertex(0, 0);
    DFS(g, 0, INF);
    auto fennec = g.getVertices();

    g.setCostToAllVertex(INF);
    g.setCostToSpecificVertex(N - 1, 0);
    DFS(g, N - 1, INF);
    auto& snuke = g.getVertices();

    int num = 0;
    REP(i, N) {
        if(fennec[i].cost < snuke[i].cost) num++;
    }

    std::cout << ((N / 2 <= num) ? "Fennec" : "Snuke") << std::endl;

    return 0;
}

