int par[100000];     //親
int Rank[100000];    //木の深さ

void init(int n) {
    for(int i = 0; i < n; ++i) {
        par[i] = i;
        Rank[i] = 0;
    }
}

int find(int x) {
    return (par[x] == x) ? x : par[x] = find(par[x]);
}

void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if(x == y) return;

    if(Rank[x] < Rank[y]) par[x] = y;
    else {
        par[y] = x;
        if(Rank[x] == Rank[y]) ++Rank[x];
    }
}

bool same(int x, int y) {
    return find(x) == find(y);
}

