int n;
int cnt1=0,cnt2=0;
queue<int> q;
vector<int> v[100010];
int d[100010][2];

void bfs(int x,int y){
	for (int i=0;i<n;i++) d[i][y]=10010;
	d[x][y]=0;
	q.push(x);
	while(!q.empty()){
		int u=q.front();
		q.pop();
		for (int i=0;i<v[u].size();i++){
			int tmp=v[u][i];
			if (d[tmp][y]>d[u][y]+1){
				d[tmp][y]=d[u][y]+1;
				q.push(tmp);
			}
		}
	}

}

int main(){
	cin>>n;
	for (int i=1;i<n;i++){
		int x,y;
		cin>>x>>y;
		x--;y--;
		v[x].push_back(y);
		v[y].push_back(x);
	}
	bfs(0,0);
	bfs(n-1,1);
	for (int i=0;i<n;i++){
		if (d[i][0]<=d[i][1]) cnt1++;
		else cnt2++;
//		cout<<i+1<<" "<<d[i][0]<<" "<<d[i][1]<<endl;
	}
//	cout<<cnt1<<" "<<cnt2;
	if (cnt1>cnt2) cout<<"Fennec"<<endl;
	else cout<<"Snuke"<<endl;
	return 0;
}

