        a[i]--;
        b[i]--;
        G[a[i]].push_back(b[i]);
        G[b[i]].push_back(a[i]);
    }
    vector<long long> adist(N, 0);

    rec(G, 0, -1, 0, adist);

    vector<long long> Ndist(N, 0);
    rec(G, N - 2, N - 1, 0, Ndist);

    long long cnt = 0;
    REP(i, N) {
        if(adist[i] <= Ndist[i]) {
            cnt++;
        }
    }
    if(cnt > N - cnt) {
