int main() {
    int n; cin >> n;
    vector<vector<int>> bitree(n);
    for (int i = 0; i < n - 1; ++i) {
        int a, b; cin >> a >> b;
        a--; b--;
        bitree[a].push_back(b);
        bitree[b].push_back(a);
    }
    queue<vector<int>> q;
    q.push({0});
    vector<bool> reached(n);
    vector<int> vs;
    reached[0] = true;
    while (true) {
        vector<int> front = q.front();
        q.pop();
        int cur = front[(int)front.size() - 1];
        if (cur == n - 1) {
            vs = front;
            break;
        }
        for (int v : bitree[cur]) {
            if (!reached[v]) {
                vector<int> nv = front;
                nv.push_back(v);
                q.push(nv);
                reached[v] = true;
            }
        }
    }
    int bidx = ((int)vs.size() + 1) / 2;
    int c = 0;
    queue<int> que;
    reached = vector<bool>(n, 0);
    que.push(vs[bidx]);
    reached[vs[bidx]] = true;
    while (!que.empty()) {
        int front = que.front();
        que.pop();
        c++;
        for (int v : bitree[front]) {
            if (!reached[v] && v != vs[bidx - 1]) {
                que.push(v);
                reached[v] = true;
            }
        }
    }
    if (c < n / 2) {
        cout << "Fennec";
    } else {
        cout << "Snuke";
    }
    return 0;
}

