int dijkstra(int s){

    priority_queue<pii,vector<pii>,greater<pii> > que;
    fill(d,d+V,LLINF);
    d[s] = 0;
    que.push(pii(d[s],s));

    while(!que.empty()){
        pii p = que.top();
        que.pop();
        int v = p.second;
        if (d[v] < p.first)
            continue;
        for(int i = 0;i < G[v].size();i++){
            edge e = G[v][i];
            if(d[e.to] > d[v] + e.cost){
                d[e.to] = d[v] + e.cost;
                que.push(pii(d[e.to],e.to));
            }
        }
    }
}

