bool gl(ll a, ll p, ll g, const vvll &e, set<ll> &r){
    if(a == g){
        return true;
    }
    if(sz(e[a]) == 1){
        return false;
    }
    bool b = false;
    for(auto x: e[a]){
        if(x == p){
            continue;
        }
        if(gl(x, a, g, e, r)){
            r.insert(x);
            b = true;
        }
    }
    return b;
}

ll cnt2(ll a, ll p, ll g, const vvll &e){
    if(a == g){
        return 0;
