    for (it = G[node1].begin(); it != G[node1].end(); it++) {
        if (*it == node2) {
            G[node1].erase(it);
            break;
        }
    }
    for (it = G[node2].begin(); it != G[node2].end(); it++) {
        if (*it == node1) {
            G[node2].erase(it);
            break;
        }
    }

    int black_cnt = dfs_cnt(0, -1);
    int white_cnt = N - black_cnt;

    if (black_cnt > white_cnt) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }

    return 0;
}

