#include <bits/stdc++.h>
using namespace std;

typedef long long int ll;
#define INF 1<<20

struct Node {
	public:
		vector <ll> edge_to; //接続されているノードID
		vector <ll> edge_cost; //エッジのコスト
		bool done;
		ll id, cost;
};

bool operator < (const Node &a, const Node &b){
	return (a.cost < b.cost);
}
bool operator > (const Node &a, const Node &b){
	return (a.cost > b.cost);
}


vector<Node> node;
vector<ll> x_cost;
vector<ll> y_cost;
void dijkstra(ll s) {
	priority_queue<Node, vector<Node>, greater<Node> > pq;
	node[s].cost = 0;
	pq.push(node[s]);
	while(!pq.empty()){
		Node n = pq.top(); pq.pop();
		for (ll i = 0; i < n.edge_to.size(); i++) {
			if (!node[n.edge_to[i]].done) {
				if (node[n.edge_to[i]].cost > n.cost + n.edge_cost[i]) {
					node[n.edge_to[i]].cost = n.cost + n.edge_cost[i];
				}
				pq.push(node[n.edge_to[i]]);
			}
		}
		node[n.id].done = true;
	}
}

int main() {
	ll n;
	scanf("%lld",&n);
	node.resize(n);
	for (ll i = 0; i < n; i++) {
		node[i].id = i;
		node[i].done = false;
		node[i].cost = INF;
	}
	for (ll i = 0; i < n-1; i++) {
		ll a, b;
		scanf("%lld %lld",&a, &b);
		a--; b--;
		node[a].edge_to.push_back(b);
		node[a].edge_cost.push_back(1);
		node[b].edge_to.push_back(a);
		node[b].edge_cost.push_back(1);
	}

	dijkstra(0);
	x_cost.resize(n);
	y_cost.resize(n);
	for (ll i = 0; i < n; i++) {
		x_cost[i] = node[i].cost;
	}
	for (ll i = 0; i < n; i++) {
		node[i].done = false;
		node[i].cost = INF;
	}
	dijkstra(n-1);
	for (ll i = 0; i < n; i++) {
		y_cost[i] = node[i].cost;
	}

	ll x_cnt = 0;
	ll y_cnt = 0;
	for (ll i = 0; i < n; i++) {
		if (x_cost[i] <= y_cost[i]) {
			x_cnt ++;
		} else {
			y_cnt ++;
		}
	}

	if (x_cnt >= y_cnt) {
		cout << "Fennec" << endl;
		return 0;
	} else {
		cout << "Snuke" << endl;
		return 0;
	}

}

