#include <bits/stdc++.h>

using namespace std;

void dijkstra(int start, vector<int> &costs,
              unordered_map<int, vector<int>> &edges) {
  priority_queue<pair<int, int>, vector<pair<int, int>>,
                 greater<pair<int, int>>>
      q;
  costs[1] = start;
  q.push(make_pair(0, start));
  while (!q.empty()) {
    auto v = q.top();
    q.pop();
    for (const auto &e : edges[v.second]) {
      if (v.first + 1 < costs[e]) {
        costs[e] = v.first + 1;
        q.push(make_pair(costs[e], e));
      }
    }
  }
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);

  int n;
  cin >> n;
  unordered_map<int, vector<int>> e;
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;
    e[a].emplace_back(b);
    e[b].emplace_back(a);
  }
  vector<int> black(n + 1, INT_MAX), white(n + 1, INT_MAX);
  dijkstra(1, black, e);
  dijkstra(n, white, e);

  int blacks = 0;
  for (int i = 1; i < n + 1; ++i) {
    if (black[i] <= white[i]) {
      blacks++;
    }
  }
  int whites = n - blacks;
  if (whites < blacks) {
    cout << "Fennec\n";
  } else {
    cout << "Snuke\n";
  }
}

