    int a,b; cin>>a>>b; a--; b--;
    tree[a].push_back(b);
    tree[b].push_back(a);
  }

  vector<int> dist(n, n);
  queue<int> qs;
  qs.push(n-1);
  dist[n-1] = 0;
  while (not qs.empty()) {
    auto q = qs.front(); qs.pop();
    int d = dist[q];
    for (auto t:tree[q]) {
      if (dist[t] < d)
        continue;
      qs.push(t);
      dist[t] = d+1;
    }
  }
  vector<int> path;
  path.push_back(0);
  int d = dist[0];
  while (d > 0) {
    for (auto t:tree[path.back()]) {
      if (dist[t] == d-1) {
        path.push_back(t);
        break;
      }
    }
    d--;
  }
  vector<int> color(n, 0);
  color[path[(path.size()+1)/2-1]] = 1;
  color[path[(path.size()+1)/2]] = 2;

  qs = {};
  qs.push(path[(path.size()+1)/2-1]);
  int bs = 1;
  while (not qs.empty()) {
    auto q = qs.front(); qs.pop();
    for (auto t:tree[q]) {
      if (color[t] != 0) continue;
      color[t] = 1;
      bs++;
      qs.push(t);
    }
  }

  cerr<<bs<<" "<<n-bs<<endl;
  cout << (bs > n-bs ? "Fennec" : "Snuke") << endl;

  return 0;
}

