vector<int> G[100010];
bool tr[100010];

int dfs(int i, int now) {
    tr[now] = false;
    if (now == n - 1) return i;
    int mn = inf;
    if (!tr[G[now][0]]) {
        if (G[now].size() == 1) return inf;
    }
    for (int j = 0; j < G[now].size(); j++) {
        if (tr[G[now][j]]) mn = min(mn, dfs(i + 1, G[now][j]));
    }
    return mn;
}

int par[100010], rnk[100010], sze[100010];

// 初期化
void init(int n) {
    for (int i = 0; i < n; i++) {
        par[i] = i;
        rnk[i] = 0;
        sze[i] = 1;
    }
}

// 親探し
int find(int x) {
    if (par[x] == x) return x;
    else return par[x] = find(par[x]);
}

// 併合
void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rnk[x] < rnk[y]) {
        par[x] = y;
        sze[y] = sze[x] + sze[y];
    }
    else {
        par[y] = x;
        if (rnk[x] == rnk[y]) rnk[x]++;
        sze[x] = sze[x] + sze[y];
    }
}

// 同じ木にあるか
bool same(int x, int y) {
    return find(x) == find(y);
}

int main(void){
    cin >> n;
    fill(tr, tr + n, true);
    for (int i = 0; i < n - 1; i++) {
        cin >> a[i] >> b[i];
        if (a[i] > b[i]) {
            int tmp = a[i];
            a[i] = b[i];  b[i] = tmp;
        }
        a[i]--;  b[i]--;
        G[a[i]].push_back(b[i]);
        G[b[i]].push_back(a[i]);
    }

    int y = dfs(0, 0) - 1;

    int x = 0;
    for (int i = 0; i < G[0].size(); i++) {
        init(n);
        for (int j = 0; j < n - 1; j++) {
            if (a[j] == 0 && b[j] == G[0][i]) ;
            else unite(a[j], b[j]);
        }
        if (!same(G[0][i], n - 1)) x += sze[G[0][i]];
    }

    int z = n - x - y - 2;

    if (x + y % 2 > z) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

    //cout << x << " " << y << " " << z << endl;
}

