  if(root==root1){
    dep1=depth;
    flag = true;
    return;
  }
  for(auto i:root->nexts){
    if(flag==true)break;
    if(pre==i.to){
      continue;
    }
    search1(i.to,depth+i.length,root);
  }
  return;
}
