vector<int> getPath(vector<vector<int> > graph, int s, int t) {
	vector<int> parent(graph.size(), -1);
	queue<int> qu;
	qu.push(s);
	while (!qu.empty()) {
		int now = qu.front();
		qu.pop();
		for (int i = 0; i < graph[now].size(); i++) {
			int next = graph[now][i];
			if (next != s && parent[next] < 0) {
				parent[next] = now;
				qu.push(next);
			}
		}
	}
	vector<int> ans;
	int now = t;
	while (now != -1) {
		ans.push_back(now);
		now = parent[now];
	}
	reverse(ans.begin(), ans.end());
	return ans;
}

int main() {
	int n;
	cin >> n;
	vector<vector<int> > graph(n);
	for (int i = 0; i < n - 1; i++) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		graph[a].push_back(b);
		graph[b].push_back(a);
	}
	vector<int> path = getPath(graph, 0, n - 1);
	int l = path.size();
	queue<int> fqu, squ;
	vector<bool> isChecked(n, false);
	int fnum = 0;
	int snum = 0;
	for (int i = 0; i < l / 2 + (l % 2); i++) {
		fqu.push(path[i]);
		fnum++;
		isChecked[path[i]] = true;
	}
	for (int i = l / 2 + (l % 2); i < l; i++) {
		squ.push(path[i]);
		snum++;
		isChecked[path[i]] = true;
	}
	while (!fqu.empty()) {
		int now = fqu.front();
		fqu.pop();
		for (int i = 0; i < graph[now].size(); i++) {
			int next = graph[now][i];
			if (!isChecked[next]) {
				isChecked[next] = true;
				fnum++;
				fqu.push(next);
			}
		}
	}
	while (!squ.empty()) {
		int now = squ.front();
		squ.pop();
		for (int i = 0; i < graph[now].size(); i++) {
			int next = graph[now][i];
			if (!isChecked[next]) {
				isChecked[next] = true;
				snum++;
				squ.push(next);
			}
		}
	}
	if (fnum > snum)
		cout << "Fennec" << endl;
	else
		cout << "Snuke" << endl;
}

