template<typename T> class Dijkstra {
public:
  struct edge {
    int to; T cost;
  };
  int V;
  vector<vector<edge>> G;
  vector<T> dist;
  using pti = pair<T,int>;
  Dijkstra(int n) : V(n), G(V), dist(V, numeric_limits<T>::max()) {}
  void add(int u, int v, T cost) {
    G.at(u).push_back((edge) {v, cost});
    G.at(v).push_back((edge) {u, cost});
  }
  void solve(int s) {
    priority_queue<pti, vector<pti>, greater<pti>> Q;
    dist.at(s) = 0;
    Q.push(pti(0, s));
    while (!Q.empty()) {
      pti p = Q.top();
      Q.pop();
      int v = p.second;
      if (dist.at(v) < p.first) continue;
      for (auto &w : G.at(v)) {
        if (dist.at(w.to) > dist.at(v) + w.cost) {
          dist.at(w.to) = dist.at(v) + w.cost;
          Q.push(pti(dist.at(w.to), w.to));
        }
      }
    }
  }
};

int N;
vector<vector<int>> G;

void dfs(int pre, int v, vector<int> &V) {
  V.at(v) = 1;
  for (auto next : G.at(v)) {
    if (next == pre) continue;
    if (next == N - 1) continue;
    dfs(v, next, V);
  }
}

void dfs2(int pre, int v, vector<int> &V2) {
  V2.at(v) = 1;
  for (auto next : G.at(v)) {
    if (next == pre) continue;
    if (next == 0) continue;
    dfs2(v, next, V2);
  }
}

int main() {
  cin >> N;
  G.resize(N);
  Dijkstra<int> D(N);
  for (int i = 0, a, b; cin >> a >> b; i++) {
    G.at(--a).push_back(--b);
    G.at(b).push_back(a);
    D.add(a, b, 1);
  }
  D.solve(0);
  int tmp = D.dist.at(N - 1) - 1;
  vector<int> V(N);
  dfs(-1, 0, V);
  int tmp2 = accumulate(V.begin(), V.end(), 0);
  vector<int> V2(N);
  dfs2(-1, N - 1, V2);
  int tmp3 = accumulate(V2.begin(), V2.end(), 0);
  int F = tmp2 - tmp;
  int S = tmp3 - tmp;
  F += (tmp - tmp / 2);
  S += tmp / 2;
  cout << ((F > S) ? "Fennec" : "Snuke") << "\n";
}

