typedef long long int ll;
using namespace std;

struct unionfind {
    int MAX_N;
    int par[100005]; //親
    int rank[100005]; //木の深さ

    void init(int n) {
        MAX_N = n;
        for (int i = 0; i < n; i++) {
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;

        if (rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (rank[x] == rank[y])rank[x]++;
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    //属している奴の要素数を求める
    int element(int x) {
        int ret = 0;
        for (int i = 0; i < MAX_N; i++) {
            if (find(x) == find(i)) ret++;
        }
        return ret;
    }
};

int main() {
    int n;
    cin >> n;
    unionfind uni;
    uni.init(n + 1);
    bool kinjo = false;
    vector<int> next1;
    vector<int> nextn;

    for (int i = 1; i < n; i++) {
        int x, y;
        cin >> x >> y;
//        x = 1;
//        y = 9;
        if (x == 1 || x == n || y == 1 || y == n) {
            if ((x == 1 && y == n) || (x == n && y == 1)) {
                kinjo = true;
            } else {
                if (x == 1 || x == n) {
                    if (x == 1) {
                        next1.push_back(y);
                    } else {
                        nextn.push_back(y);
                    }
                } else {
                    if (y == 1) {
                        next1.push_back(x);
                    } else {
                        nextn.push_back(x);
                    }
                }
            }
        } else {
            uni.unite(x, y);
        }
    }
    int joint;
    if (kinjo) {
        joint = 0;
    } else {
        int removeNext1, removeNextN;
        for (int i = 0; i < next1.size(); i++) {
            for (int j = 0; j < nextn.size(); j++) {
                if (next1[i] == next1[j]) {
                    removeNext1 = i;
                    removeNextN = j;
//                    joint = next1[i];
                    joint = uni.element(next1[i]);
                }
            }
        }
        next1.erase(next1.begin() + removeNext1);
        nextn.erase(nextn.begin() + removeNextN);
    }

    int elements1 = 0;
    int elementsn = 0;
    for (int num: next1) {
        elements1 += uni.element(num);
    }
    for (int num: nextn) {
        elementsn += uni.element(num);
    }
    if (elements1 + joint / 2 + joint % 2 > elementsn + joint / 2) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
}

