#define MAX_V 100005

struct edge{
    int to;
    long long cost;
    edge(int i, long long j) {to = i, cost = j; };
};
typedef pair<long long, int> P; // firstは最短距離、secondは頂点の番号

int V;
vector<edge> G[MAX_V];
long long d[MAX_V];
int pv[MAX_V];

void dijkstra(int s){
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d + V, LLONG_MAX);
    fill(pv, pv + V, -1);
    d[s] = 0;
    que.push(P(0,s));

    while (!que.empty()) {
        P p = que.top(); que.pop();
        int v = p.second;
        if (d[v] < p.first ) continue;
        for (int i = 0; i < G[v].size(); i++) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost ) {
                d[e.to] = d[v] + e.cost;
                pv[e.to] = v;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

vector<int> get_path(int t){
    vector<int> path;
    for(; t != -1; t = pv[t]) path.push_back(t);
    reverse(path.begin(), path.end());
    return path;
}

int pcount(int v, int user, vi& used) {

    int res = 1;

    // cout << " -- " << v << " " << G[v].size() << endl;

    REP(i, G[v].size()) {
        if (used[G[v][i].to] > 0) continue;
        used[G[v][i].to] = user;
        res += pcount(G[v][i].to, user, used);
    }

    return res;
}

int main() {

    cin >> V;
    int a, b;

    REP(i, V-1) {
        cin >> a >> b;
        a--; b--;
        // cout << a << " " << b << endl;
        G[a].push_back(edge(b, 1));
        G[b].push_back(edge(a, 1));
    }

    dijkstra(0);

    vi path = get_path(V-1);

    vi used(V, 0);
    for (int i = 0, j = path.size()-1; i < path.size(); i++, j--) {
        // cout << path[i] << " ";
        if (used[path[i]] == 0) used[path[i]] = 1;
        if (used[path[j]] == 0) used[path[j]] = 2;
    }
    // cout << endl;

    int f = 0, s = 0;
    REP(i, path.size()) {
        if (used[path[i]] == 1) f += pcount(path[i], 1, used);
        if (used[path[i]] == 2) s += pcount(path[i], 2, used);
    }

    if (f > s) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

    return 0;
}

