// 深さ優先探索
Graph G(100005);
int Fennec[100005];
int Sunuke[100005];

void dfs(int v,int before,int step,bool f) {
		if(f) Fennec[v]=step;
		else Sunuke[v]=step;
    for(int i=0;i<G[v].size();i++)
			if(G[v][i]!=before) dfs(G[v][i],v,step+1,f);
}

int main()
{
	int a,b;
	int N;
	int ans=0;
	sd1(N);
	for(int i=0;i<N-1;i++){
		sd2(a,b);
		a--,b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	dfs(0,-1,0,true);
	dfs(N-1,-1,0,false);
	for(int i=0;i<N;i++) ans+=(Fennec[i]<=Sunuke[i])?1:-1;
	puts((ans>0)?"Fennec":"Snuke");
}

