void dfs(int x, int n, int count, bool graph[][100000], int dist[], bool visit[]){
   if(visit[x]) return;
   visit[x] = true;
   dist[x] = count;
   //printf("dist:%d\n",dist[x]);
   ++count;
   rep(i,n){
      if(graph[x][i] == false) continue;
      if(visit[i]) continue;
      dfs(i,n,count,graph,dist,visit);
   }
}

int main()
{
   int n;
   cin >> n;

   // 5-7-4-1-2 
   //       L3-6
   // 1-4-2-3

   bool graph[n][100000];
   int distA[n];
   int distB[n];
   bool visit[n];
   rep(i,n){
      distA[i] = 0;
      distB[i] = 0;
      visit[i] = false;
      rep(j,n) graph[i][j] =false;
   }

   rep(i,n-1){
      int a,b;
      cin >> a >> b;
      --a; --b;
      graph[a][b] = true;
      graph[b][a] = true;
   }

   //それぞれからの距離を求める
   //フェネックA
   dfs(0,n,0,graph, distA,visit);
   //リセット
   rep(i,n) visit[i] = false;
   //スヌケ
   dfs(n-1,n,0,graph, distB, visit);

   int A = 0;
   int B = 0;

   rep(i,n){
      if(distA[i] <= distB[i]) A++;
      else B++;
   }
   //rep(i,n) printf("A:%d B:%d\n",distA[i], distB[i]);

   if(A > B) cout << "Fennec" << endl;
   else cout << "Snuke" << endl;
   return 0;
}

