class UnionFind {
private:
  vector<int> par;
public:
  UnionFind(int N) {
    par.resize(N);
    for (int i = 0; i < N; i++) par[i] = i;
  }
  int root(int x) { return (x == par[x])? x: (par[x] = root(par[x])); }
  void unite(int x, int y) { par[root(y)] = root(x); }
  bool same(int x, int y) { return (root(x) == root(y)); }
};


int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  ll N; cin >> N;
  vector<ll> G[N];
  for (ll i = 0; i < N - 1; i++) {
    ll a, b; cin >> a >> b; a--, b--;
    G[a].emplace_back(b);
    G[b].emplace_back(a);
  }

  vector<ll> d(N, -1);
  vector<ll> prev(N, -1);
  vector<bool> used(N, 0);
  queue<ll> q;

  q.push(0);
  d[0] = 0;
  used[0] = true;
  while (!q.empty()) {
    ll c = q.front(); q.pop();
    for (auto n: G[c]) {
      if (!used[n]) {
        d[n] = d[c] + 1;
        prev[n] = c;
        used[n] = true;
        q.push(n);
      }
    }
  }

  vector<ll> path(d[N - 1] + 1, 0); // path from 1 to N
  path[d[N - 1]] = N - 1;
  for (ll i = d[N - 1] - 1; i >= 0; i--) {
    path[i] = prev[path[i + 1]];
  }
  ll m1 = path[d[N - 1] / 2], m2 = path[d[N - 1] / 2 + 1];


  UnionFind UF(N);
  for (ll i = 0; i < N; i++) {
    for (auto n: G[i]) {
      if (i == m1 && n == m2) continue;
      if (i == m2 && n == m1) continue;
      UF.unite(i, n);
    }
  }
  ll cnt1 = 0, cntN = 0;
  for (ll i = 0; i < N; i++) {
    if (UF.same(0, i)) cnt1++;
    if (UF.same(N - 1, i)) cntN++;
  }

  if (cnt1 >= cntN) {
    cout << "Fennec" << '\n';
  } else {
    cout << "Snuke" << '\n';
  }

  return 0;
}

