#define F first
#define S second

int n;
vi adj[100050];
int p[100050];
int s[100050];
bool vis[100050];

int dfs(int here) {
	vis[here] = true;
	s[here] = 1;
	for(auto there : adj[here]) {
		if(!vis[there]) {
			p[there] = here;
			s[here] += dfs(there);
		}
	}
	return s[here];
}

int main(void) {
	ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
	//freopen("in.txt", "r", stdin);
	cin >> n;
	rep(i,0,n) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		adj[a].pb(b);
		adj[b].pb(a);
	}
	memset(vis, false, sizeof(vis));
	p[0] = 0;
	dfs(0);
	vi ret;
	int here = n-1;
	while(here != 0) {
		if(here != n-1){
			ret.pb(here);
		}
		here = p[here];
	}
	here = (sz(ret) > 0 ? ret.back() : n-1);
	int a = n - s[here] - 1;
	int b = s[n-1] - 1;
	int m = sz(ret);
	per(i,0,m) {
		int j = (i == 0 ? n-1 : ret[i-1]);
		s[ret[i]] -= s[ret[j]];
	}
	rep(i,0,m/2) {
		b += s[ret[i]];
	}
	rep(i,m/2,m) {
		a += s[ret[i]];
	}
	if(a>b) {
		cout << "Fennec" << '\n';
	} else {
		cout << "Snuke" << '\n';
	}
	return 0;
}

