int lento(vector<int>& col,vector<int>& k,int l){
  int c=0;
  for(int i=0;i<l;i++){if(col[k[i]]==0) c+=1;}
  //cout << c << endl;
  return c;
}

//can change or can't
bool change_to_black(vv& v,vector<int>& col,int n,queue<int>& q1){
  int l=q1.size();//cout <<l;
  queue<int> q3;
  pair<int,int> ma(n,0);
  for(int i=0;i<l;i++){
    int x=q1.front();//cout <<x;
    if(col[x]!=0){q1.pop();continue;}
    //cout << x;
    int l_sub=v[x].size();
    int c=lento(col,v[x],l_sub);
    if(ma.second<c)ma=make_pair(x,c);
    //cout << x;
    q1.pop();
    q3.push(x);
  }
  if(ma.second==0){
    return false;
  }else{
    col[ma.first]=1;
    q1.swap(q3);
    int l_sub=v[ma.first].size();
    for(int i=0;i<l_sub;i++){
      q1.push(v[ma.first][i]);
    }
    return true;
  }
}

//can change or can't
bool change_to_white(vv& v,vector<int>& col,int n,queue<int>& q2){
  int l=q2.size();
  queue<int> q3;
  pair<int,int> ma(n,0);
  for(int i=0;i<l;i++){
    int x=q2.front();//cout << x << endl;
    if(col[x]!=0){q2.pop();continue;}
    int l_sub=v[x].size();
    int c=lento(col,v[x],l_sub);
    //cout << c << endl;
    if(ma.second<c)ma=make_pair(x,c);
    q2.pop();
    q3.push(x);
  }
  if(ma.second==0){
    return false;
  }else{
    col[ma.first]=-1;
    q2.swap(q3);
    int l_sub=v[ma.first].size();
    for(int i=0;i<l_sub;i++){
      q2.push(v[ma.first][i]);
    }
    return true;
  }
}


