#include <bits/stdc++.h>
using namespace std;
int n;
vector <vector <int> > graph;
map <int, int> p;
vector <bool> used;
void dfs(int v){
    used[v] = true;
    for (auto to: graph[v]){
        if (!used[to]){
            p[to] = v;
            dfs(to);
        }
    }
}
int dfs_count(int v){
    used[v] = true;
    int now = 1;
    for (auto x: graph[v]){
        if (!used[x]){
            now += dfs_count(x);
        }
    }
    return now;
}
int main(){
    cin >> n;
    graph.resize(n);
    used.resize(n, false);
    for (int i = 0; i < n - 1; ++i){
        int a,b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    vector <int> path;
    path.push_back(n - 1);
    dfs(0);
    while (path[path.size() - 1] != 0){
        int x = p[path[path.size() - 1]];
        path.push_back(x);
    }
    reverse(path.begin(), path.end());
    int Fennec = 0;
    int Snuke = 0;
    for (int i = 0; i < n; ++i){
        used[i] = false;
    }
    used[0] = true;
    for (auto x: graph[0]){
        if (x != path[1]){
            Fennec += dfs_count(x);
        }
    }
    used[n - 1] = true;
    for (auto x: graph[n - 1]){
        if (x != path[path.size() - 2]){
            Snuke += dfs_count(x);
        }
    }
    for (int i = 1; i < path.size() - 1; ++i){
        if (i <= (path.size() - 2) / 2 + path.size() % 2){
            Fennec++;
            used[path[i]] = true;
            for (auto x: graph[path[i]]){
                if (x != path[i + 1] && x != path[i - 1]){
                    Fennec += dfs_count(x);
                }
            }
        }
        else{
            Snuke++;
            used[path[i]] = true;
            for (auto x: graph[path[i]]){
                if (x != path[i + 1] && x != path[i - 1]){
                    Snuke += dfs_count(x);
                }
            }
        }
    }
    if (Fennec - Snuke >= 1){
        cout << "Fennec" << "\n";
    }
    else{
        cout << "Snuke" << "\n"; 
    }
    return 0;
}

