const int MOD = 1000000007;

int N;
vector<int> adj[100010];
vector<int> path;
bool visited[100010];
int color[100010];

bool find_path(int index){
    if(visited[index]) return false;
    if(index == 0) return true;
    visited[index] = true;
    bool ret = false;
    for(int next : adj[index]){
        if(find_path(next)){
            ret = true;
            if(index != N - 1) path.push_back(index);
        }
    }
    return ret;
}

signed main(){
    cin >> N;
    int a, b;
    REP(i, N - 1){
        cin >> a >> b;
        a--; b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    find_path(N - 1);
    int L = path.size();
    queue<int> fen, snu;
    REP(i, (L + 1) / 2){
        color[path[i]] = 1;
        fen.push(path[i]);
    }
    FOR(i, (L + 1) / 2 + 1, L){
        color[path[i]] = -1; 
        snu.push(path[i]);
    }
    color[0] = 1; color[N - 1] = -1;
    int i = L % 2;
    while(true){
        if(fen.empty()){
            PRINT("Snuke");
            return 0;
        }else if(snu.empty()){
            PRINT("Fennec");
            return 0;
        }
        int index;
        if(i % 2 == 0){
            index = fen.front();
            fen.pop();
            color[index] = 1;
            for(int next : adj[index]){
                if(color[next] == 0) fen.push(next);
            }
        }else{
            index = snu.front();
            snu.pop();
            color[index] = -1;
            for(int next : adj[index]){
                if(color[next] == 0) snu.push(next);
            }
        }
        i++;
    }
    return 0;
}

