int dcount = 0;
bool direct = true;

int dfs(const int &cnt, const int &par, const int &stop) {
    int ret = 0;
    for(auto t:tree[cnt]) {
        if (t == stop) {
            direct = false;
            continue;
        }
        if (t == par) continue;
        ret += dfs(t,cnt,stop);
    }
    if (direct) dcount++;
    return ret+1;
}

