void bfs(int start, vector<int>& dist, vector<vector<int>>& G) {
  queue<int> que;
  que.emplace(start);
  dist[start] = 0;
  int level = 0;
  while (!que.empty()) {
    int size = que.size();
    ++level;
    rep(i, size) {
      int v = que.front();
      que.pop();
      dist[v] = level;
      for (auto nv : G[v]) {
        if (dist[nv] != INT_MAX) continue;
        que.emplace(nv);
      }
    }
  }
}

int main(void) {
  int N;
  cin >> N;
  vector<vector<int>> G(N);
  rep(i, N - 1) {
    int a, b;
    cin >> a >> b;
    --a;
    --b;
    G[a].emplace_back(b);
    G[b].emplace_back(a);
  }

  vector<int> fv(N, INT_MAX);
  bfs(0, fv, G);
  vector<int> sv(N, INT_MAX);
  bfs(N - 1, sv, G);

  int count = 0;
  rep(i, N) {
    if (fv[i] <= sv[i]) ++count;
  }
  if (count <= (N - count))
    cout << "Snuke" << endl;
  else
    cout << "Fennec" << endl;
  return 0;
}

