int64_t dfs(const vector<vector<int64_t>>& adjs, int64_t v, int64_t p) {
    int64_t n = adjs.size();

    for (auto u : adjs[v]) {
        if (u == p) {
            continue;
        }

        if (u == n - 1) {
            return 1;
        }

        auto t = dfs(adjs, u, v);
        if (t >= 0) {
            return t + 1;
        }
    }

    return -1;
}

