struct unionfind{
    vector<int> d;
    unionfind(int n=0) : d(n, -1){}
    int find(int x) {//根を返す関数
        if(d[x]<0) return x;
        return d[x]=find(d[x]);//d[x]にfind[d[x]]の値を代入してそれを返している．これにより根に全ての子を繋げられる．
    }
    bool unite(int x, int y){
        x=find(x);y=find(y);
        if(x == y) return false;
        if(d[x]>d[y]) swap(x, y);//-なので逆にしている
        d[x]+=d[y];//連結成分サイズを保持している
        d[y]=x;//yの根をxにしている
        return true;
    }
    bool same(int x, int y){return find(x)==find(y);}//同じかどうかを判定
    int size(int x){return -d[find(x)];}//連結成分の数を返す
    int kind(){
        int tmp = 0;
        rep(i, d.size()) if(d[i]<0) tmp++;
        return tmp;
    }
};

void dist(int u, int p, int now, int goal){
    di[u] = now;
    for(int v : g[u]){
        if(v==p) continue;
        dist(v, u, now+1, goal);
    }
}

int main(void){
    cin>>n;
    unionfind uf1(n);
    unionfind uf2(n);
    rep(i, n-1){
        int a, b;
        cin>>a>>b;
        --a;--b;
        g[a].push_back(b);
        g[b].push_back(a);
        if(a!=0 && b!=0) uf1.unite(a, b);
        if(a!=n-1&&b!=n-1) uf2.unite(a, b);
    }
    di.resize(n);
    dist(0, -1, 0, n-1);
    int mb = uf1.kind();
    int mw = uf2.kind();
    if((di[n-1])/2+mb>di[n-1]-(di[n-1])/2+mw){
        cout<<"Fennec"<<endl;
    }
    else cout<<"Snuke"<<endl;
    return 0;
}

