    color[n-1]=WHITE;

    while(rest>0){
        //erabu
        rest=0;
        for(int i=0;i<n-1;i++){
            cbit[i]=0;
        }
        for(list<Road>::iterator i=g.begin();i!=g.end();){
            int l=color[i->l];
            int r=color[i->r];
            if (l==BLACK && r == NONE){
                cbit[i->r]+=BBIT;
            }
            if (l==WHITE && r == NONE){
                cbit[i->r]+=WBIT;
            }
            if (r==BLACK && l == NONE){
                cbit[i->l]+=BBIT;
            }
            if (r==WHITE && l == NONE){
                cbit[i->l]+=WBIT;
            }
            i++;
        }
        for(list<Road>::iterator i=g.begin();i!=g.end();){
            int l=color[i->l];
            int r=color[i->r];
//            cout << l << " " << r <<endl;
            if(cbit[i->r]==3){
                color[i->r]=teban;
                rest++;
                break;
            }else if(cbit[i->l]==3){
                color[i->l]=teban;
                rest++;
                break;
            }else{
                if(r==NONE&&l==teban){
                    color[i->r]=teban;
                    rest++;
                    break;
                }
                if(l==NONE&&r==teban){
