const int MAX_V = 10002;  // ツリーのサイズのありうる最大値
int dist_1 = 0, dist_n = 0;
int N;  // ツリーのサイズ
vector<int> tree[MAX_V];  // ツリーを隣接リスト形式のグラフ構造で表したもの

int sizeSubtree[MAX_V];  // sizeSubtree[v] := v を根とする部分ツリーのサイズ
vector<int> centroids;  // 重心列挙の答えがここに入る

/* ツリーDP */
void SubFindCentroids(int v, int parent_of_v = -1) {
    sizeSubtree[v] = 1;
    bool isCentroid = true;
    for (auto ch : tree[v]) {
        if (ch == parent_of_v) continue;
        SubFindCentroids(ch, v);
        if (sizeSubtree[ch] > N / 2) isCentroid = false;
        sizeSubtree[v] += sizeSubtree[ch];
    }
    if (N - sizeSubtree[v] > N / 2) isCentroid = false;
    if (isCentroid) centroids.push_back(v);
}

void FindCentroids() {
    centroids.clear();
    SubFindCentroids(0, N); // これを呼び出すと centoroids に重心を列挙したものが入る
}

int dist(int v, int c1, int c2){
    if(v == c1 || v == c2) return 0;
    queue<int> que;
    vector<int> dist(N, -1);
    que.push(v);
    dist[v] = 0;
    while(!que.empty()){
        v = que.front(); que.pop();
        for(int nv : tree[v]){
            if(dist[nv] != -1) continue;
            if(nv == c1 || nv == c2) return dist[v] + 1;
            dist[nv] = dist[v] + 1;
            que.push(nv);
        }
    }
    return -1;
}
int main(){
    cin >> N;
    rep(i,N - 1){
        int a, b; cin >> a >> b;
        --a; --b;
        tree[a].push_back(b);
        tree[b].push_back(a);
    }
    FindCentroids();
    int c1 = centroids[0], c2 = -inf;
    if(sz(centroids) == 2) c2 = centroids[1];
    dist_1 = dist(0, c1, c2);
    dist_n = dist(N - 1, c1, c2);
    if(dist_1 < dist_n){
        cout << "Fennec" << endl;
    }
    else if(dist_1 > dist_n) cout << "Snuke" << endl;
    else{
        if(sz(centroids) == 2) cout << "Snuke" << endl;
        else cout << "Fennec" << endl;
    }
}

