    a--; b--;
    t_arr[a].push_back(b);
    t_arr[b].push_back(a);
  }

  int cut_node = -1;
  dfs(t_arr, 0, -1, 0, N-1, cut_node);
  int f_size = dfs_size(t_arr, 0, -1, cut_node);

  if(f_size*2 > N) std::cout << "Fennec" << std::endl;
  else std::cout << "Snuke" << std::endl;

  return 0;
}

