void dfs(int u, int d, int p, int rival, int& dist,
         vector<vector<int>>& adj, vector<int>& visited, vector<int>& parent)
{
  if (u == rival) {
    dist = d;
    return;
  }
  visited[u] = 1;
  parent[u] = p;
  for (int v : adj[u]) {
    if (visited[v]) { continue; }
    dfs(v, d + 1, p, rival, dist, adj, visited, parent);
  }
}

