            int top=s.front();
            s.pop();
            for(int i=0;i<adj[top].size();i++)
            {
                int chi=adj[top][i];
                if(vis[chi]==0)
                {
                    vis[chi]=2;
                    s.push(chi);
                }
            }
        }
        if(s.empty()&&f.empty())break;
    }
    int cnt=0;
    for(int i=1;i<=n;i++)
    {
        if(vis[i]==1)cnt++;
    }
    if(cnt>n-cnt)ans="Fennec";
    else ans="Snuke";
    return ans;
}

