int main(void) {
    using namespace std;

    long n;
    cin >> n;

    vector<vector<long>> G(n);
    for(int i=0; i<n-1; i++) {
        long a, b;
        cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    vector<short> mark(n);

    {
        auto dfs = [&] (auto dfs, int cur, int prev, int idx) -> int {
            if(cur == n-1) return idx;

            for(auto v: G[cur]) {
                if(v == prev) continue;
                int r = dfs(dfs, v, cur, idx+1);
                if(r > 0)
                    mark[cur] = idx <= r / 2 ? 1 : 2;
            }
            return 0;
        };

        dfs(dfs, 0, -1, 0);
    }
    mark[0] = 1;
    mark[n-1] = 2;

    {
        auto dfs = [&] (auto dfs, int cur, int prev) -> int {
            if(mark[cur]) return mark[cur];

            for(auto v: G[cur]) {
                if(v == prev) continue;
                mark[cur] |= dfs(dfs, v, cur);
            }
            return 0;
        };

        for(int i=0; i<n; i++)
            mark[i] |= dfs(dfs, i, -1);
    }

    long a = 0, b = 0;
    for(int i=0; i<n; i++)
        (mark[i] == 1 ? a : b)++;

    cout << (a < b ? "Snuke" : "Fennec") << endl;
}

