    vector<vector<int>> G(N);
    int a, b;
    for (int i = 0; i < N-1; i++) {
        cin >> a >> b; a--; b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    stack<int> st;
    st.push(0);
    vector<int> par(N, -1);
    par[0] = -1;
    while(!st.empty()){
        int v = st.top(); st.pop();
        for(int w : G[v]){
            if(par[w] == -1){
                par[w] = v;
                st.push(w);
            }
        }
    }

    int d = 0;
    int now = N-1;
    while(now != 0) {
        now = par[now];
        d++;
    }
    d = (d-1) / 2;
    now = N - 1;
    while(d > 0){
        now = par[now];
        d--;
    }
    int m = par[now];

    int cnt = 0;
    vector<bool> used(N, false);
    used[m] = true;
    st.push(now);
    while(!st.empty()){
        int v = st.top(); st.pop();
        cnt++;
        used[v] = true;
        for(int w : G[v]){
            if(used[w]) continue;
            st.push(w);
        }
    }
    if(N - cnt > cnt){
        printf("Fennec\n");
    }
