    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        edges[u].emplace_back(v, 1);
        edges[v].emplace_back(u, 1);
    }
    vector<lint> distf = dijkstra(0, edges);
    vector<lint> dists = dijkstra(n - 1, edges);
    lint cnt           = 0;
    for (int i = 0; i < n; ++i) {
        if (distf[i] <= dists[i])
            cnt++;
    }
    if (cnt > n / 2)
        cout << "Fennec"
             << "\n";
    else
        cout << "Snuke"
             << "\n";
    return 0;
}

