void dfsSnuke(int node, int prev){
    if(node == 0)return;
    visited[node] = true;
    snuke ++;
    for(int i =0 ; i < graph[node].size(); i ++){
        int sosed = graph[node][i];
        if(sosed == prev)continue;
        dfsSnuke(sosed, node);
    }
}
void dfsFennec(int node, int prev){
    if(visited[node] && node != 0)return;
    fennec ++;
    for(int i =0; i < graph[node].size(); i ++){
        int sosed = graph[node][i];
        if(sosed == prev)continue;
        dfsFennec(sosed, node);
    }
}
