#include<bits/stdc++.h>
using namespace std;
vector<int> pathN(0);
int N;
bool dfs(int p, int u, vector<vector<int>> &side) {
  if(u == N - 1) {
    pathN.push_back(u);
    return true;
  }
  for(int i = 0; i < side.at(u).size(); i++) {
    int v = side.at(u).at(i);
    if(v == p) continue;
    if(dfs(u, v, side)) {
      pathN.push_back(u);
      return true;
    }
  }
  return false;
}

void paint(vector<int> &tree, vector<vector<int>> &side, int u, int color) {
  for(int i = 0; i < side.at(u).size(); i++) {
    int v = side.at(u).at(i);
    if(tree.at(v) != -1) continue;
    tree.at(v) = color;
    paint(tree, side, v, color);
  }
}

int main() {
  cin >> N;
  vector<int> tree(N, -1);
  vector<vector<int>> side(N, vector<int> (0));
  for(int i = 0; i < N - 1; i++) {
    int a, b; cin >> a >> b; a--; b--;
    side.at(a).push_back(b);
    side.at(b).push_back(a);
  }
  map<string, int> score;
  score["Fennec"] = 0; score["Snuke"] = 0;
  dfs(-1, 0, side);
  reverse(pathN.begin(), pathN.end());
  for(int i = 0; i < pathN.size(); i++) {
    if(tree.at(pathN.at(i)) == -1) tree.at(pathN.at(i)) = 1;
    else break;
    if(tree.at(pathN.at(pathN.size() - 1 - i)) == -1) tree.at(pathN.at(pathN.size() - 1 - i)) = 0;
    else break;
  }
  for(int i = 0; i < pathN.size(); i++) {
    paint(tree, side, pathN.at(i), tree.at(pathN.at(i)));
  }
  for(int i = 0; i < N; i++) {
    if(tree.at(i) == 1) score.at("Fennec")++;
    else score.at("Snuke")++;
  }
  cout << ((score.at("Fennec") > score.at("Snuke")) ? "Fennec" : "Snuke") << endl;
}

