#include <bits/stdc++.h>
using namespace std;
#define INF 1e+9
#define MAX_V 100300
using P = pair<int,int>;
struct edge{
    int to;
    int cost;
};
vector <edge> G[MAX_V]; //グラフ
vector <int> d1(MAX_V, INF);// 距離
vector <int> d2(MAX_V, INF);
void dijkstra(int s, vector <int> &d){
    priority_queue<P, vector<P>, greater<P> > que;
    d[s] = 0;
    que.push(P(0,s)); // 今までのコストと現在地

    while(!que.empty()){
        P p = que.top(); que.pop();
        int v = p.second;
        if(d[v]< p.first) continue;

        for(int i=0;i<G[v].size();i++){
            edge e = G[v][i];
            if(d[e.to] > d[v] + e.cost){
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}
int main(void){
    int n; cin>>n;
    for(int i=0;i<n-1;i++){
        int a,b; cin>>a>>b; a--; b--;
        G[a].push_back({b,1});
        G[b].push_back({a,1});
    }
    dijkstra(0, d1);
    dijkstra(n-1, d2);
    int feneko=0, snuke=0;
    for(int i=0;i<n;i++){
            if(d1[i]>d2[i]) snuke++;
            else feneko++;
    }
    if(feneko>snuke) cout<<"Fennec"<<endl;
    else cout<<"Snuke"<<endl;
}

