void Fennec(int depth, int i, vector<Node>& nodes, vector<bool>& visited) {
    if(visited[i])return;
    visited[i] = true;
    nodes[i].fennec = depth;
    for(auto edge : nodes[i].edges) {
        Fennec(depth + 1, edge, nodes, visited);
    }
}

void Snuke(int depth, int i, vector<Node>& nodes, vector<bool>& visited) {
    if(visited[i])return;
    visited[i] = true;
    nodes[i].snuke = depth;
    for(auto edge : nodes[i].edges) {
        Snuke(depth + 1, edge, nodes, visited);
    }
}

