void bfs(int sp, int cost[])
{
    queue<pair<int, int> > q;
    q.push(make_pair(sp, 0));

    while(q.empty() == false)
    {
        pair<int, int> e = q.front();
        q.pop();
        if (cost[e.first] != -1)
        {
            continue;
        }
        //cout << "cell : " << e.first << " cost : " << e.second << endl;
        cost[e.first] = e.second;
        for (int i = 0; i < tree[e.first].size();i++)
        {
            pair<int, int> t = make_pair(tree[e.first][i], e.second + 1);
            q.push(t);
            //cout << "b" << endl;
        }
    }
}

