	} 
	vis[x] = true;
	int flag = 0; 
		for (int j:v[x])
			if (!vis[j]) { 
				DFS(v, vis, j, y, stack);
				flag = 1;
			} 
	if (flag == 0) 
		stack.pop_back();
}

