        cin>>N;
        for(int i=0;i<N-1;i++){
                int aa, bb;
                cin>>aa>>bb;
                ab[aa].push_back(bb);
                ab[bb].push_back(aa);
        }
        rec(1, 1, N);
        for(int i=0;i<=N;i++){
                flag[i]=false;
        }
        rec(N, 2, 1);
        for(int i=2;i<=N-1;i++){
                //cout<<graph[i]<<" ";
                if(graph[i]==1){
                        F++;
                }
                else if(graph[i]==2){
                        S++;
                }
                else if(graph[i]==3){
                        SF++;
                }
        }
        //cout<<endl;
        //cout<<S<<":"<<F<<":"<<SF<<endl;
        bool res=false;
        for(int i=0;;i++){
                if(SF>0){
                        SF--;
                }
                else if(i%2==0){
                        if(F<=0){
                                break;
                        }
                        F--;
                }
                else if(i%2==1){
                        if(S<=0){
                                res=true;
                                break;
                        }
                        S--;
                }
        }
        if(res){
                cout<<"Fennec"<<endl;
        }
        else{
                cout<<"Snuke"<<endl;
        }
        return 0;
}

