using namespace std;
using Graph = vector<vector<int>>;

// 深さ優先探索
vector<bool> seen;
void dfs(const Graph &G,int v,int before,int step,vector<int> &Array) {
		Array[v]=step;
    for(int i=0;i<G[v].size();i++)
			if(G[v][i]!=before) dfs(G,G[v][i],v,step+1,Array);
}

int main()
{
	int a,b;
	int N;
	int ans=0;
	sd1(N);
	vector<int> Fennec(N+10);
	vector<int> Sunuke(N+10);
	Graph G(N+10);
	for(int i=0;i<N-1;i++){
		sd2(a,b);
		a--,b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	dfs(G,0,-1,0,Fennec);
	dfs(G,N-1,-1,0,Sunuke);

//	for(int i=0;i<N;i++) cout<<Fennec[i]<<" ";
//	cout<<endl;
//	for(int i=0;i<N;i++) cout<<Sunuke[i]<<" ";
	for(int i=0;i<N;i++) ans+=(Fennec[i]<=Sunuke[i])?1:-1;
	printf("%s",(ans>0)?"Fennec":"Snuke");
}

