int main(){
  int N;
  cin >> N;
  vector<int> a(N), b(N);
  rep(i, N-1) {
    cin >> a[i] >> b[i];
    a[i]--; b[i]--;
  }
  vector<vector<int>> to(N);
  rep(i, N-1) {
    to[a[i]].push_back(b[i]);
    to[b[i]].push_back(a[i]);
  }
  vector<vector<int>> node(N, vector<int>(2));
  queue<pair<int, int>> que;
  que.push({0, -1});

  auto bfs = [&](int n) {
    while(!que.empty()) {
      int now, prev;
      tie(now, prev) = que.front();
      que.pop();
      rep(i, to[now].size()) {
        if(to[now][i] == prev)
          continue;
        node[to[now][i]][n] = node[now][n]+1;
        que.push({to[now][i], now});
      }
    }
  };

  bfs(0);
  que.push({N-1, -1});
  bfs(1);
  int fennec = 0, snuke = 0;
  rep(i, N) {
    if(node[i][0] <= node[i][1])
      fennec++;
    else
      snuke++;
  }
  if(fennec > snuke)
    cout << "Fennec" << endl;
  else
    cout << "Snuke" << endl;
  return 0;
}

