bool used[100010];
int tr[100010];
vector <int> tree[100010];
int d[100010];
int n;
queue <int> q;
int cnt1=0,cnt2=0,cnt0=0;
int tmp1=0;

void dfs(int x){
	for (int i=0;i<tree[x].size();i++){
		int u=tree[x][i];
		if (!used[u]){
			tmp1++;
			used[u]=true;
			dfs(u);	
		}
	}
	return;
}

void trace(int x){
	cnt0++;
	if (x==0) return;
	used[x]=true;
	int tmp=tr[x];
	if (tmp==-1) return;
	used[tmp]=true;
	for (int i=0;i<tree[tmp].size();i++){
		int u=tree[tmp][i];
		if (cnt0>cnt2) dfs(u);
	}
	trace(tmp);
	return;
}

int main(){
	memset(used,false,sizeof(used));
	cin>>n;
	for (int i=0;i<n-1;i++){
		int x,y;
		cin>>x>>y;
		x--;y--;
		tree[x].push_back(y);
		tree[y].push_back(x);
	} 
	q.push(0);
	memset(d,-1,sizeof(d));
	d[0]=0;
	memset(tr,-1,sizeof(tr));
	while(!q.empty()){
		int p=q.front();
		q.pop();
		if (p==n-1) {
			trace(n-1);
			break;
		}
		for (int i=0;i<tree[p].size();i++){
			int tmp=tree[p][i];
			if (d[tmp]==-1||d[tmp]>d[p]+1){
				tr[tmp]=p;
				d[tmp]=d[p]+1;
				q.push(tmp);
			}
		}
	}
	int dis=d[n-1]-1;
	cnt2+=dis/2;
	cnt1+=dis-cnt2+tmp1;
	cnt2=n-cnt1;
	if (cnt1>cnt2) cout<<"Fennec";
	else cout<<"Snuke";
}

#include <iostream>
#include <algorithm>
#include <vector>
#include <queue>
#define MAXV 100007
using namespace std;

int a[MAXV], b[MAXV];
vector<int> tree[MAXV];
int n;

vector<int> bfs(int s){
    vector<int> dist(n+1, -1);
    queue<int> q;
    q.push(s);
    dist[s] = 0;

    while(!q.empty()){
       int t = q.front(); q.pop();
       for(int i: tree[t]){
           if(dist[i] == -1){
               dist[i] = dist[t]+1;
               q.push(i);
           }
       } 
    }
    return dist;
}


int main(){
    cin >> n;
    int black, white;
    for(int i=1; i<n; i++){
        cin >> black >> white;
        black--; 
        white--;
        tree[black].push_back(white);
        tree[white].push_back(black);
    }

    vector<int> d1 = bfs(1);
    vector<int> d2 = bfs(n);

    int l = 0, r = 0;
    for(int i=1; i<=n; i++){
        if(d1[i] <= d2[i]) l++;
        else r++;
    }

    if(l > r) cout << "Fennec" << endl;
    else if(r >= l) cout << "Snuke" << endl;

    return 0;
}

#include <iostream>
#include <cstdio>
#include <vector>
#include <list>
using namespace std;

typedef long long int ll;

typedef struct{
  vector<int> connect;
} Node;

int check[100010];

int main () {
  int N;
  cin >> N;
  vector<Node> nvec;
  for (int i = 0; i < N; i++) {
    Node temp;
    nvec.push_back(temp);
    check[i] = 0;
  }
  check[0] = 1;
  check[N-1] = -1;
  for (int i = 0; i < N-1; i++) {
    int a, b;
    scanf("%d %d\n", &a, &b);
    a--; b--;
    nvec.at(a).connect.push_back(b);
    nvec.at(b).connect.push_back(a);
  }
  list<int> univB, univW;
  univB.push_back(0);
  univW.push_back(N-1);
  int countB, countW;
  countB = countW = 1;
  while(1) {
    int bcB, bcW;
    bcB = countB;
    bcW = countW;
    int sizeB = univB.size();
    int sizeW = univW.size();
