typedef tuple<int, int, int> tup;

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    auto edge = initVec2<int>(n + 1, 0);
    rep(i, n - 1){
        int a, b;
        cin >> a >> b;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    vector<int> dep(n + 1, -1);
    vector<int> par(n + 1, 0);
    stack<tup> st;
    st.emplace(1, 1, 0);
    while(not st.empty()){
        int v, d, p;
        tie(v, d, p) = st.top();
        st.pop();
        if(dep[v] != -1){
            continue;
        }
        dep[v] = d;
        par[v] = p;
        for(int u : edge[v]){
            st.emplace(u, d + 1, v);
        }
    }

    int len = dep[n];
    int id = n;
    rep(i, len / 2){
        id = par[id];
    }

    vector<bool> used(n + 1, false);
    stack<int> sti;
    sti.push(n);
    while(not sti.empty()){
        int v = sti.top();
        sti.pop();

        if(used[v] || v == id){
            continue;
        }
        used[v] = true;
        for(int u : edge[v]){
            sti.push(u);
        }
    }

    int snuke = 0;
    rep(i, n + 1){
        if(used[i]){
            snuke++;
        }
    }

    int fennec = n - snuke;
    if(fennec > snuke){
        cout << "Fennec" << endl;
    }else{
        cout << "Snuke" << endl;
    }

    return 0;
}

