using namespace std;

int color[100001];
vector <int> adj[100001];
queue <int> s1, s2;

int solve(void)
{
	int a, b;
	fill(color, color + 100001, 0);
	while (1)
	{
		while (s1.size() != 0)
		{
			a = s1.front();
			if (color[a] == 0)
			{
				color[a] = 1;
				s1.pop();
				break;
			}
			s1.pop();
		}

		while (s2.size() != 0)
		{
			b = s2.front();
			if (color[b] == 0)
			{
				color[b] = 2;
				s2.pop();
				break;
			}
			s2.pop();
		}

		for (int i = 0; i < adj[a].size(); i++)
		{
			if (color[adj[a][i]] == 0)
			{
				s1.push(adj[a][i]);
			}
		}

		if (s1.size() == 0)
		{
			break;
		}

		for (int i = 0; i < adj[b].size(); i++)
		{
			if (color[adj[b][i]] == 0)
			{
				s2.push(adj[b][i]);
			}
		}

		if (s2.size() == 0)
		{
			break;
		}
	}

	if (s2.size() == 0)
	{
		return 1;
	}

	return 2;
}

