{
	int a, b, flag, n;

	cin >> n;

	for (int i = 0; i < n - 1; i++)
	{
		cin >> a >> b;
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	s1.push(1);
	s2.push(n);
	flag=solve();

	if (flag == 1)
	{
		cout << "Fennec" << endl;
	}
	else
	{
		cout << "Snuke" << endl;
	}

	return 0;
}

