template<class T>bool chmax(T &a, const T &b) { if (b > a) { a = b; return true; } return false; }
template<class T>bool chmin(T &a, const T &b) { if (b < a) { a = b; return true; } return false; }

constexpr int dx[4] = {-1, 0, 0, 1}, dy[4] = {0, -1, 1, 0};
constexpr int INF = 1e9;
constexpr long long LINF = 1e18;
#pragma endregion

vector<ll> dijkstra(const WGraph &G, const int s) {
    int n = (int)G.size();
    std::vector<long long> dis(n, LINF);
    dis.at(s) = 0;
    using P = std::pair<long long, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> que;
    que.push(std::make_pair(0, s));

    while (!que.empty()) {
        auto p = que.top();
        que.pop();
        int v = p.second;
        if (dis.at(v) < p.first) {
            continue;
        }
        for (auto e : G.at(v)) {
            if (dis.at(e.first) > dis.at(v) + e.second) {
                dis.at(e.first) = dis.at(v) + e.second;
                que.push(std::make_pair(dis.at(e.first), e.first));
            }
        }
    }
    return dis;
}

void solve(){
    int n;
    cin >> n;
    WGraph G(n);
    for (int i=0; i<n-1; i++) {
        int a, b;
        cin >> a >> b;
        G.at(a-1).push_back(make_pair(b-1, 1));
        G.at(b-1).push_back(make_pair(a-1, 1));
    }
    vector<ll> fennec = dijkstra(G, 0), snuke = dijkstra(G, n-1);
    int cnt = 0;
    for (int i=0; i<n; i++) {
        if (fennec.at(i) <= snuke.at(i)) cnt++;
        else cnt--;
    }
    if (cnt > 0) cout << "Fennec" << "\n";
    else cout << "Snuke" << "\n";
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

    return 0;
}

