const int MAXN = 100010;
int n;
vector<int> graph[MAXN];
bool visited[MAXN];
int dist1[MAXN];
int distn[MAXN];

void init() {
  for (int i=0;i<MAXN;i++) {
    visited[i] = false;
  }
}

void dfs(int x, int level, bool startFrom1) {
  visited[x] = true;
  if (startFrom1) {
    dist1[x] = level;
  } else {
    distn[x] = level;
  }
  for (int i=0;i<graph[x].size();i++) {
    int next = graph[x][i];
    if (!visited[next]) {
      dfs(next, level + 1, startFrom1);
    }
  }
}

void solve() {
  init();
  dfs(0, 0, true);
  init();
  dfs(n-1, 0, false);
  int closeTo1 = 0;
  int closeToN = 0;
  for (int i=0;i<n;i++) {
    if (dist1[i] <= distn[i]) {
      closeTo1++;
    } else {
      closeToN++;
    }
  }
  if (closeTo1 > closeToN) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }
}

