        --a; --b;
        add_edge(g, a, b);
    }

    vector<Weight> depth = dijkstra(g, 0);
    int p = n-1;
    int d = depth[p];

    while (true) {
        int np = to_root(g, depth, p);
        //dump(d); dump(p); dump(depth[p]); dump(np); dump(depth[np]); el;
        if (depth[np] == d / 2) {
            repeat(i, (int)g[np].size()) {
                if (g[np][i].dst == p) {
                    g[np].erase(g[np].begin() + i);
                }
            }
            repeat(i, (int)g[p].size()) {
                if (g[p][i].dst == np) {
                    g[p].erase(g[p].begin() + i);
                }
            }
            break;
        }
        p = np;
    }

    if (connect_numbers(g, 0) > connect_numbers(g, n-1)) {
        cout << "Fennec" << endl;
    }
    else {
        cout << "Snuke" << endl;
    }

    return 0;
}

