//si:頂点数
//root:根
//ch:子供の集合
//pa:親(根の親=-1)
//no:前提情報
void treeconstruct(ll si, ll root,vector<vector<ll>>& ch, vector<ll>& pa, vector<vector<ll>>& no) {
	ch.resize(si,vector<ll>(0));
	pa.resize(si,-2);
	queue<pll> q;
	q.push(pll(root, -1));
	while (!q.empty()) {
		ll cur = q.front().first;
		ll p = q.front().second;
		q.pop();
		pa[cur] = p;
		for (ll next : no[cur]) {
			if (next == p)continue;
			ch[cur].push_back(next);
			q.push(pll(next, cur));
		}
	}
	return;
}

ll cnum(ll n) {
	if (CNUM[n] != -1)return CNUM[n];
	ll ans = 0;
	for (ll c : childs[n])ans += cnum(c);
	CNUM[n] = ans + 1;
	return CNUM[n];
}

