		}
	}
	ll top = N - 1;
	for (ll d = 1; d <= (dist - 1) / 2; d++)top = parents[top];
	ll sn = cnum(top);
	ll fe = N - cnum(top);
	if (fe >= sn)cout << "Fennec" << endl;
	else cout << "Snuke" << endl;
	return 0;
}

