using namespace std;

int cnt(vector<int> *v,int a,int end)
{
	map<int,int>m;
	queue<int> q;
	q.push(a);
	while(!q.empty())
	{
		int y = q.front();
		q.pop();
		m[y]++;
		for(int i: v[y])
		{
			if(i==end)
				continue;
			else if(m[i]==0)
			{
				m[i]++;
				q.push(i);
			}
		}
	}
	return m.size();
}

void printPath(vector<int> &stack, vector<int> *v) 
{
	int black=0, white = 0, n = (stack.size()-1)/2;
	black = cnt(v,1,stack[n+1]);
	white = stack.back()-black;
	if(black>white)
		cout<<"Fennec"<<endl;
	else
		cout<<"Snuke"<<endl; 
} 

void DFS(vector<int> *v, bool *vis, int x, int y, vector<int> &stack) 
{ 
	stack.push_back(x); 
	if (x == y) {
		printPath(stack,v); 
		exit(0);
	} 
	vis[x] = true;
	int flag = 0; 
		for (int j:v[x])
			if (!vis[j]) { 
				DFS(v, vis, j, y, stack);
				flag = 1;
			} 
	if (flag == 0) 
		stack.pop_back();
}

