vector<vector<int>> G;
vector<int> Prev;
vector<bool> visited;

int bfs(int s, int t){
    queue<pair<int,int>> que;
    que.push({s,0});
    while(!que.empty()){
        auto now = que.front(); que.pop();
        int v = now.first;
        int d = now.second;
        if(v == t){
            return d;
        }
        for(auto e: G[v]) if(!visited[e]) {
            visited[e] = true;
            que.push({e, d + 1});
            Prev[e] = v;
        }
    }
    return -1;
}

int tbfs(int s){
    queue<int> que;
    que.push(s);
    int cnt = 0;
    while(!que.empty()){
        auto v = que.front(); que.pop();
        for(auto e: G[v]) if(!visited[e]) {
            visited[e] = true;
            que.push(e);
            cnt++;
        }
    }
    return cnt;
}

