        G[a].push_back(b);
        G[b].push_back(a);
    }
    Prev.resize(N, -1);
    visited.assign(N, 0);
    bfs(0, N - 1);
    visited.assign(N, 0);
    vector<int> path, rpath; // pathがフェネック
    for(int v = N - 1; v != 0; v = Prev[v]){
        if( v != N - 1)rpath.push_back(v);
        //cout << v << endl;
    }
    int k = rpath.size();
