    int black = k - (k / 2);
    int white = k / 2;
    //cout << black << white << endl;
    for(auto e: path){
        visited[e] = true;
    }
    for(auto e: rpath){
        visited[e] = true;
    }

    for(auto e: path){
        black += tbfs(e);
    }
    for(auto e: rpath){
        white += tbfs(e);
