		for (size_t i = 0; i < edge[pn].size(); ++i) {
			if (edge[pn][i] == N) {
				++dn;
				stpath = true;
			}
			else if (!check[edge[pn][i]]) {
				q.push(edge[pn][i]);
				d.push(dn+1);
			}
		}
	}

	int bc,wc;
	bc = wc = 0;
	queue<int> b,w;
	b.push(1);
	check = vector<bool>(N,false);
	while (!b.empty()) {
		pn = b.front();
		b.pop();
		check[pn] = true;
		for (size_t i = 0; i < edge[pn].size(); ++i) {
			if (!(edge[pn][i] == N) && !(check[edge[pn][i]])) {
				b.push(edge[pn][i]);
				++bc;
			}
		}
	}

	w.push(N);
	check = vector<bool>(N,false);
	while (!w.empty()) {
		pn = w.front();
		w.pop();
		check[pn] = true;
		for (size_t i = 0; i < edge[pn].size(); ++i) {
			if (!(edge[pn][i] == 1) && !(check[edge[pn][i]])) {
				w.push(edge[pn][i]);
				++wc;
			}
		}

	}

	bc -= dn/2;
	wc -= (dn+1)/2;

	if (bc > wc) {
		cout << "Fennec" << endl;
	}
	else {
		cout << "Snuke" << endl;
	}

	return 0;
}

