bool solve() {
  queue<int> qu, qfs[2];
  int cnt[2] = {0};
  qu.push(1);
  while(!qu.empty()) {
    int now = qu.front();
    qu.pop();
    for(int i = 0; i < edge[now].size(); ++i) {
      int nextn = edge[now][i];
      if(dis[now] + 1 < dis[nextn]) {
        qu.push(nextn);
        memo[nextn] = now;
        dis[nextn] = dis[now] + 1;
      }
    }
  }
  int halfdist = (dis[n] - 1) / 2, from = n, to = memo[n];
  for(int i = 0; i < halfdist; ++i) {
    from = to;
    to = memo[from];
  }
  if(from > to) swap(from, to);
  qfs[0].push(1);
  qfs[1].push(n);
  ch[1] = ch[n] = 1;
  for(int i = 0; i < 2; ++i) {
    while(!qfs[i].empty()) {
      int now = qfs[i].front();
      qfs[i].pop();
      for(int j = 0; j < edge[now].size(); ++j) {
        int nextn = edge[now][j];
        if(min(now, nextn) == from && max(now, nextn) == to)
          continue;
        if(!ch[nextn]) {
          ch[nextn] = 1;
          qfs[i].push(nextn);
          ++cnt[i];
        }
      }
    }
  }
  return cnt[0] > cnt[1];
}

