   // 5-7-4-1-2 
   //       L3-6
   // 1-4-2-3

   rep(i,n-1){
      int a,b;
      cin >> a >> b;
      --a; --b;
      dist[a].push_back(b);
      dist[b].push_back(a);
   }
   //一番最初と最後のますを塗る
   vector<bool> visit(n);
   visit[0] = true;
   visit[n-1] = true;

   while(1){
      //0 = 黒　n-1 = 白　フェネックは黒を、スヌケは白を塗っていく
      //フェネックの番
      int decide = -1;
      //攻める
      for(int a :dist[n-1]){
         if(visit[a]) continue;
         for(int b : dist[0]){
            if(a == b){
               decide = a;
               visit[a] = true;
               break;
            } 
         }
         if(decide != -1) break;
      }
      if(decide == -1){
         for(int b :dist[0]){
            if(!visit[b]) {
               decide = b; 
               visit[b] = true;
               break;
            }
         }
      }
      if(decide == -1)
      {
         //負け
         cout << "Snuke" <<endl;
         return 0;
      }

      //スヌケの番
      decide = -1;
      //攻める
      for(bool a :dist[0]){
