         for(int b :dist[0]){
            if(!visit[b]) {
               decide = b; 
               visit[b] = true;
               break;
            }
         }
      }
      if(decide == -1)
      {
         //負け
         cout << "Fennec" <<endl;
         return 0;
      }
   }
}

