class Tree {
    vector<vector<int>> tree;
    vector<int> befores;

    deque<int> q;


    void insertTask(int now) {
        for (int i : tree[now]) {
            if (befores[now] == i) continue;
            befores[i] = now;
            q.push_back({i});
        }
    }

    vector<int> routeFrom(int start, int end) {
        int now = end;
        vector<int> route;
        route.push_back(end);
        while (now != start) {
            now = befores[now];
            route.push_back(now);
        }
        reverse(route.begin(), route.end());
        return route;
    }

    vector<int> dfs(int start, int end) {

        q.push_back({start});

        while (!q.empty()) {
            int t = q.front();
            if (t == end) {
                return routeFrom(start, end);
            }
            q.pop_front();
            insertTask(t);
        }
        __throw_runtime_error("korenai");
    }

public:
    Tree(int n) {
        tree.resize(n);
        befores.resize(n, -1);
    }

    void connect(int a, int b) {
        tree[a].push_back(b);
        tree[b].push_back(a);
    }

    vector<int> getRoute(int start, int end) {
        return dfs(start, end);
    }


};

class UnionFind {
public:
    // 親の番号を格納する。親だった場合-size
    vector<int> parents;

    UnionFind(int n) {
        parents = vector<int>(n, -1);
    }

    // aがどのグループに属しているか
    int root(int a) {
        if (parents[a] < 0) {
            return a;
        }
        return parents[a] = root(parents[a]);
    }

    int size(int a) {
        return -parents[root(a)];
    }

    // aとbをくっつける
    bool connect(int a, int b) {
        int ra = root(a);
        int rb = root(b);
        if (ra == rb) {
            return false;
        }
        // 大きいほうにA
        if (size(ra) < size(rb)) {
            swap(ra, rb);
        }
        parents[ra] += parents[rb];
        parents[rb] = ra;
        return true;
    }

};

int main() {

