typedef long long ll;

struct tree_distance{
    int n;
    vector<vector<int>> g;
    vector<int> d;
    int s;
    tree_distance(int _n,int _s){
        n = _n;
        g.resize(n);
        d.resize(n);
        for (int i = 0; i < n; ++i)
        {
            d[i] = -1;
        }
        s = _s;
    }
    void add(int a,int b){
        g[a].push_back(b);
    }
    void init(){
        dfs(s,0);
    }
    void dfs(int x,int dis){
        d[x] = dis;
        for(int i : g[x]){
            if(d[i] < 0){
                dfs(i,dis+1);
            }
        }
    }
};

int main(int argc, char const *argv[])
{
    cin.tie(0);ios::sync_with_stdio(false);
    cout<<fixed<<setprecision(20);
    int n;cin >> n;
    tree_distance A(n,0),B(n,n-1);
    for (int i = 0; i < n-1; ++i)
    {
        int a,b;cin >> a >> b;
        a--,b--;
        A.add(a,b);A.add(b,a);
        B.add(a,b);B.add(b,a);
    }
    A.init();B.init();
    int cnt = 0;
    for (int i = 0; i < n; ++i)
    {
        if(A.d[i] <= B.d[i])cnt++;
    }

    if(cnt > n - cnt){
        cout << "Fennec" << endl;
    }else{
        cout << "Snuke" << endl;
    }
    return 0;
}

