class Solve {
public:
    Int N;
    vector<vector<Int>> treeone;
    vector<Int> bdist, wdist;

    void compute_dist(Int v, vector<Int> &dist, Int d = 0, Int p = -1) {
        dist[v] = d;
        for (auto e : treeone[v]) {
            if (e != p) {
                compute_dist(e, dist, d + 1, v);
            }
        }
    }

    void solve() {
        cin >> N;
        treeone.resize(N);
        bdist.resize(N, -1);
        wdist.resize(N, -1);
        for (int i = 1; i < N; ++i) {
            Int a, b;
            cin >> a >> b;
            a--, b--;
            treeone[a].push_back(b);
            treeone[b].push_back(a);
        }

        compute_dist(0, bdist);
        compute_dist(N - 1, wdist);

        Int B = 0, W = 0;
        for (int i = 0; i < N; ++i) {
            if (bdist[i] <= wdist[i]) {
                B++;
            } else {
                W++;
            }
        }
        if (W >= B) {
            cout << "Snuke" << endl;
        } else {
            cout << "Fennec" << endl;
        }
    }
};


