queue<int> f_bfs(queue<int> q_v) {
    queue<int> next_v;
    while (!q_v.empty()) {
        int v = q_v.front();
        q_v.pop();
        rep(i, G[v].size()) {
            if (!s_seen[G[v][i]] && !f_seen[G[v][i]]) {
                next_v.push(G[v][i]);
                f_seen[G[v][i]] = true;
            }
        }
    }
    return next_v;
}

void solve() {
    queue<int> q_f, q_s;
    q_f.push(0), q_s.push(n - 2);
    int f_num = 1, s_num = 1;
    while (true) {
        q_f = f_bfs(q_f);
        f_num += q_f.size();
        if (q_f.empty()) {
            if (f_num > s_num) {
                cout << "Fennec" << endl;
                return;
            } else {
                cout << "Snuke" << endl;
                return;
            }
        }
        q_s = s_bfs(q_s);
        s_num += q_s.size();
        if (q_s.empty()) {
            if (f_num > s_num) {
                cout << "Fennec" << endl;
                return;
            } else {
                cout << "Snuke" << endl;
                return;
            }
        }
    }
