const size_t maxN = 100005;

int N;
std::vector<int> G[maxN];
int Fa[maxN], Dep[maxN], Size[maxN];

void DFS(int i)
{
	Size[i] = 1;
	for (auto to : G[i])
		if (to != Fa[i])
		{
			Fa[to] = i;
			Dep[to] = Dep[i] + 1;
			DFS(to);
			Size[i] += Size[to];
		}
}

int main()
{
	scanf("%d", &N);
	for (int u, v, i = 1; i != N; ++i)
	{
		scanf("%d%d", &u, &v);
