	}

	Dep[1] = 1, DFS(1);

	int cnt = Dep[N] / 2;
	int o = N;
	while (--cnt)
		o = Fa[o];

	puts(N - Size[o] > Size[o] ? "Fennec" : "Snuke");

	return 0;
}

