vector<int> graph[100001];
bool is_reached[100001];

pair<int, int> bfs(int blk, int whi){
	int b_ans = 1, w_ans = 1;
	queue<pair<int, int> > que_b, que_w;
	que_b.push(make_pair(blk, 1));
	que_w.push(make_pair(whi, 1));
	is_reached[blk] = true;
	is_reached[whi] = true;
	int coun = 0;
	while(1){
		coun++;
		while(1){
			auto b = que_b.front();
			if (b.second != coun) break;
			que_b.pop();
			for (auto ne : graph[b.first]){
				if (!is_reached[ne]){
					is_reached[ne] = true;
					que_b.push(make_pair(ne, coun+1));
					b_ans++;
				}
			}
		}
		while(1){
			auto w = que_w.front();
			if (w.second != coun) break;
			que_w.pop();
			for (auto ne : graph[w.first]){
				if (!is_reached[ne]){
					is_reached[ne] = true;
					que_w.push(make_pair(ne, coun+1));
					w_ans++;
				}
			}
		}
		if (que_b.empty() && que_w.empty()) break;
	}
	return make_pair(b_ans, w_ans);
}


int main(){
	int n;
	cin >> n;
	for (int i = 1; i < n; i++){
		int a, b;
		cin >> a >> b;
		graph[a].push_back(b);
		graph[b].push_back(a);
	}
	auto ans = bfs(1, n);
	if (ans.first >= ans.second) cout << "Fennec" << endl;
	else cout << "Sunke" << endl;
	return 0;
}

