using namespace std;

map<int, set<int>> path;

void calc_dist(int start, vector<int>& dist) {
	queue<pair<int, int>> queue;
	queue.push(make_pair(start, 0));

	while (queue.size()) {
		auto f = queue.front();
		queue.pop();

		if (dist[f.first] != 0)
			continue;

		dist[f.first] = f.second;
		for (auto p : path[f.first]) {
			queue.push(make_pair(p, f.second + 1));
		}
	}
}

int main() {
	int N;
	cin >> N;

	int a, b;
	for (int i = 0; i < N - 1; i++) {
		cin >> a >> b;
		a--;
		b--;
		path[a].insert(b);
		path[b].insert(a);
	}

	vector<int> fenn(N);
	vector<int> snuke(N);

	calc_dist(0, fenn);
	calc_dist(N - 1, snuke);

	set<int> fenq;
	set<int> snukeq;

	fenq.insert(0);
	snukeq.insert(N - 1);

	while (fenq.size() && snukeq.size()) {
		// fenn first
		int fen_max = 100001;
		int fen_next = -1;

		for (auto f : fenq) {
			if (fen_max > snuke[f]) {
				fen_max = snuke[f];
				fen_next = f;
			}
		}

		if (fen_next == -1) {
			// fen failed.
			cout << "Snuke" << endl;
			return 0;
		}
		fenn[fen_next] = -1;
		snuke[fen_next] = -1;

		fenq.erase(fen_next);
		snukeq.erase(fen_next);

		for (auto f : path[fen_next]) {
			if (fenn[f] != -1 && snuke[f] != -1) {
				fenq.insert(f);
			}
		}

		// snuke
		// fenn first
		int snuke_max = 100001;
		int snuke_next = -1;

		for (auto f : snukeq) {
			if (snuke_max > fenn[f]) {
				snuke_max = fenn[f];
				snuke_next = f;
			}
		}

		if (snuke_next == -1) {
			// snuke failed.
			cout << "Fennec" << endl;
			return 0;
		}
		fenn[fen_next] = -1;
		snuke[fen_next] = -1;

		snukeq.erase(snuke_next);
		fenq.erase(snuke_next);

		for (auto f : path[snuke_next]) {
			if (fenn[f] != -1 && snuke[f] != -1) {
				snukeq.insert(f);
			}
		}
	}

	if (fenq.size() == 0) {
		cout << "Snuke" << endl;
	} else {
		cout << "Fennec" << endl;
	}

	return 0;
}

