void cnt(ll a, ll p, ll &c, const vvll &e){
    c++;
    for(auto x: e[a]){
        if(x == p){
            continue;
        }
        cnt(x, a, c, e);
    }
}

bool gl(ll a, ll p, ll g, const vvll &e){
    if(a == g){
        return true;
    }
    if(sz(e[a]) == 1){
        return false;
    }
    bool b = false;
    for(auto x: e[a]){
        if(x == p){
            continue;
        }
        if(gl(x, a, g, e)){
            b = true;
        }
    }
    return b;
}

ll cnt2(ll a, ll p, ll g, const vvll &e){
    if(a == g){
        return 0;
    }
    if(sz(e[a]) == 1&&p != INF){
        return -INF;
    }
    ll v = -INF;
    for(auto x: e[a]){
        if(x == p){
            continue;
        }
        chmax(v, cnt2(x, a, g, e));
    }
    return v+1;
}

