    }
    ll s = 0, f = 0;
    ll n1;
    for(auto x: e[0]){
        if(gl(x, 0, N-1, e)){
            n1 = x;
        }
    }
    ll n2;
    for(auto x: e[N-1]){
        if(gl(x, N-1, 0, e)){
            n2 = x;
