        //prtl(v);
        f += v;
    }
    for(auto x: e[N-1]){
        if(x == n2){
            continue;
        }
        ll w = 0;
        cnt(x, N-1, w, e);
        s += w;
    }
    ll c = cnt2(0, INF, N-1, e);
