void dfs(int u, vector<int> &d,vector<vector<int> > G, int N) {
    for (int i = 0; i < G[u].size(); i++) {
        if (d[G[u][i]] == 0) {
            d[G[u][i]] = d[u] + 1;
            dfs(G[u][i],d,G,N);
        }
    }
}


int main() {
    int N; cin >> N;
    int res = 0;
    vector<vector<int> > G(N, vector<int> {});
