    for (int i = 0; i < N-1; i++) {
        int a, b; cin >> a >> b;
        G[a-1].push_back(b-1);
        G[b-1].push_back(a-1);
    }

    d1[0] = d2[N-1] = -1;
    dfs(0,d1,G,N);
    dfs(N-1,d2,G,N);
    for (int i = 0; i < N; i++) {
