		for(int p=1;p<maxK;p++)
		{
			int x = pre[i][p-1];
			pre[i][p] = pre[x][p-1]; 
		}
	int pos = 0;
	int s = n;
	for(int i=maxK-1;i>=0;i--)
	{
		if(pre[s][i] == 0)
