int main(){
    ll n;cin>>n;
    Graph G(n);
    rep(i,n-1){
        ll a,b;cin>>a>>b;
        a--;b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    queue<ll> que,que2;
    que.push(0);
    que2.push(n-1);

    ll f_can=0,s_can=0;//fennec snuke それぞれの個数
    vector<bool> visit(n,false);
    visit[0]=true;
    visit[n-1]=true;

    while(que.size()!=0){
        ll now=-1;
        if(que.size()!=0){    
            now=que.front();
            que.pop();
        }

        if(now!=-1){    
            for(auto next:G[now]){
                if(visit[next]!=false) continue;
                visit[next]=true;

                que.push(next);
                f_can++;
            }
        }

        ll now2=-1;
        if(que2.size()!=0){    
            now2=que2.front();
            que2.pop();
        }

        if(now2!=-1){    
            for(auto next:G[now2]){
                if(visit[next]!=false) continue;
                visit[next]=true;

                que2.push(next);
                s_can++;
            }
        }
    }

    if(f_can>s_can) cout<<"Fennec"<<endl;
    else cout<<"Snuke"<<endl;

