using namespace std;

vector<int> bfs(int src, vector<vector<int>> &Tree) {
  int N = Tree.size();
  vector<int> dist(N, -1);
  dist[src] = 0;

  queue<int> que;
  que.push(src);
  while (!que.empty()) {
    int cur_v = que.front();
    que.pop();
    for (auto nxt_v : Tree[cur_v]) {
      if (dist[nxt_v] != -1) {
        continue;
      }
      dist[nxt_v] = dist[cur_v] + 1;
      que.push(nxt_v);
    }
  }
  return dist;
}

int main() {
  int N;
  cin >> N;

  vector<vector<int>> Tree(N);
  for (int i = 0; i < N - 1; i++) {
    int a, b;
    cin >> a >> b;
    a--, b--;
    Tree[a].push_back(b);
    Tree[b].push_back(a);
  }

  vector<int> dist_from_1 = bfs(0, Tree);
  vector<int> dist_from_n = bfs(N - 1, Tree);

  int alice = 0;
  int bob = 0;

  for (int i = 0; i < N; i++) {
    if (dist_from_1[i] <= dist_from_n[i]) {
      alice++;
    } else {
      bob++;
    }
  }
  cout << (alice >= bob ? "Fennec" : "Snuke") << endl;

  return 0;
}

