using namespace std;
int n;
vector<int> tree[100005];
int succ[100005]={};
int depth;
bool haveN[100005];

int dfs(int v,int p,int d){
	if(v==n) depth=d;
	if(tree[v].size()==1 && tree[v][0]==p) return succ[v]=1;
	for(int i=0;i<tree[v].size();i++){
		if(tree[v][i]==p) continue;
		succ[v]+=dfs(tree[v][i],v,d+1);
		if(haveN[tree[v][i]]) haveN[v]=true;
	}
	return ++succ[v];
}
int dfs2(int v,int p,int d){
	if(d==depth/2+1) {
		return succ[v];
	}
	for(int i=0;i<tree[v].size();i++){
		if(tree[v][i]==p) continue;
		if(haveN[tree[v][i]]) return dfs2(tree[v][i],v,d+1);
	}
}

int main(){
	cin >> n;
	for(int i=0;i<n-1;i++){
		int a,b;
		cin >> a >> b;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}
	haveN[n]=true;
	succ[1]=dfs(1,-1,0);		
	bool ans = n-dfs2(1,-1,0)>n/2?true:false;
	if(ans) cout << "Fennec" << endl;
	else cout << "Snuke" << endl;
}

