struct edge {
	int to;
	int cost;
	//edge e ={to, cost}
};

// <最短距離, 頂点の番号>
using P = pair<int, int>;

int V;// 頂点の数
vector<edge> G[MAX_V];
int d[MAX_V];



void dijkstra(int s) {
	//sからiへの最短距離をd[i]に保存 i=e.to
	priority_queue<P, vector<P>, greater<P> > que;
	fill(d, d + V, INF);
	d[s] = 0;//初期位置へのコストは0

	que.push(P(0, s));
	//queはmake_pair(cost,to)?

	while (!que.empty()) {
		P p = que.top();
		que.pop();
		int v = p.second;//v=e.to	from s to v
		//すでにこの経路よりいい経路が見つかっているなら無視
		if (d[v] < p.first) continue;


		for (int i = 0; i < G[v].size(); ++i) {
			edge e = G[v][i];
			// i 番目の v と v'を結ぶ辺　G=<e.to, e.cost>
			//e.to=v'
	                //e.cost means v to v' costs e.cost
			if (d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				//from s to v'> from s to v + from v to v'
				//vを経由したほうがコストが低いなら経由する
				que.push(P(d[e.to], e.to));
			}
		}
	}
}
int main() {
	cin >> V;
	int E=V-1;//辺の数
	for (int i = 0; i < E; ++i) {
		int a, b, c=1;
		cin >> a >> b ;
		a--; b--;
		//the route a to b costs c
		edge e = { b, c };
		G[a].push_back(e);
        edge e2={a,c};
        G[b].push_back(e2);
		//有効グラフの場合であり、無向グラフなら e{a,c}も必要
	}
	dijkstra(0);
    vector<int>d1(V),d2(V);
	//dijkstra(int s); nからの最短距離を計算
	//d[i]はsからiまでの最短距離が保存される the path from s to i costs d[i]
    rep(i,V){
        d1[i]=d[i];
    }
    dijkstra(V-1);
    rep(i,V){
        d2[i]=d[i];
    }
    vector<bool>isSnuke(V,true);

    rep(i,V){
        if(d1[i]<=d2[i]){
            isSnuke[i]=false;
        }
    }

    int snuke=0,fennec=0;
    rep(i,V){
        if(isSnuke[i]){
            snuke++;
        }else{
            fennec++;
        }
    }
    if(snuke>=fennec){
        cout<<"Snuke"<<endl;
    }else{
        cout<<"Fennec"<<endl;
    }
}

