int dfs1(int p, int v, int dist){
  // 今見ている頂点がvで0からの距離がdist
  // p から来た
  // N-1までの距離が返されるので適切に処理

  if (v == N-1) return dist;

  bool leaf = true;
  int res = 0;
  for (auto nv : G[v]){
    if (nv == p) continue;
    leaf = false;
    int tmp = dfs1(v, nv, dist+1);
    chmax(res, tmp);
  }
  // N-1に到達するパスでなければ適当に0を返す
  if (res == 0) return 0;
  // N-1に到達するパスならN-1と0の距離を返す
  // そして自分がFennec側ならcolorに1を、Snuke側ならcolorに-1を入れる
  // (Fennec) 0, 1, ..., dist-1, dist (Snuke)
  // 距離が偶数：0, 1, 2 | 3, 4
  // 距離が奇数：0, 1, 2 | 3, 4, 5
  color[v] = dist <= res/2 ? 1 : -1;
  return res;
}

void dfs(int p, int v){
  // 今見ている頂点がvで pから来た
  for (auto nv : G[v]){
    if (nv == p) continue;
    if (color[nv] != 0) continue; // 既に色が塗られている
    color[nv] = color[v];
    dfs(v, nv);
  }
}

