vector<int> roadToN;

bool istoN(int now, int p)
{
	if (now == n - 1)return toN[n - 1];
	for (int next : v[now])
	{
		if (next == p)continue;
		toN[now] = (toN[now] || istoN(next, now));
	}
	if (toN[now])roadToN.push_back(now);
	return toN[now];
}

