const int BLACK = 1;
const int WHITE = -1;
const int NONE = 0;

bool dfs(const vector<vector<int>>& g, int s, int t, vector<bool>& visited,
         vector<int>& route) {
    if (s == t) {
        route.push_back(s);
        return true;
    }

    visited[s] = true;
    for (int u : g[s]) {
        if (visited[u]) {
            continue;
        }
        if (dfs(g, u, t, visited, route)) {
            route.push_back(s);
            return true;
        }
    }
    visited[s] = false;

    return false;
}

void bfs(int n, const vector<vector<int>>& g, vector<int>& mark, int color) {
    queue<int> q;
    for (int i = 0; i < n; i++) {
        if (mark[i] == color) {
            q.push(i);
            mark[i] = NONE;
        }
    }
    while (!q.empty()) {
        const int v = q.front();
        q.pop();

        if (mark[v] != NONE) {
            continue;
        }
        mark[v] = color;

        for (int u : g[v]) {
            if (mark[u] != NONE) {
                continue;
            }
            q.push(u);
        }
    }
}

