#define MAX_N 100000

vector<vector<int> > graph;
int dist[MAX_N];

int dfs(int s, int step) {
    dist[s] = step;

    int nodes = 0;
    for (const auto dst: graph.at(s)) {
        if (dist[dst] == -1) {
            nodes += dfs(dst, step + 1);
        }
    }
    return nodes + 1;
}

bool visited[MAX_N];
bool find_route(int now, int g, vector<int>& route) {
    visited[now] = true;
    if (now == g) {
        route.push_back(g);        
        return true;
    }
    for (const auto dst: graph.at(now)) {
        if (!visited[dst] && find_route(dst, g, route)) {
            route.push_back(now);
            return true;
        }
    }
    return false;
}

int main() {
    int N;
