        graph.at(a-1).push_back(b-1);
        graph.at(b-1).push_back(a-1);
    }

    vector<int> route;
    find_route(0, N-1, route);
    reverse(route.begin(), route.end());
    dfs(0, 0);

    int d = dist[N-1] / 2;

    int u = route.at(d);
    int v = route.at(d+1);
    graph.at(v).erase(remove(graph.at(v).begin(), graph.at(v).end(), u), graph.at(v).end());
    graph.at(u).erase(remove(graph.at(u).begin(), graph.at(u).end(), v), graph.at(u).end());

    // init
    memset(dist, -1, sizeof(dist));
    int fn = dfs(0,0);

