void bfs(int s, vector<vector<int>> graph, vector<int> &dis){
    queue<int> que;
    vector<bool> closed(graph.size(), false);
    closed[s] = true;
    for(auto x : graph[s]){
        que.push(x);
        closed[x] = true;
    }
    int num = 1;
    while(!que.empty()){
        int z = que.size();
        REP(i, z){
            int x = que.front();
            que.pop();
            for(auto y : graph[x]){
                if(!closed[y]){
                    que.push(y);
                    closed[y] = true;
                }
            }

            dis[x] = num;
        }
        num++;
    }
}

