int N;
std::vector< std::vector<int> > to;
std::vector< int > distance[2];

void calc(int player, int start){
    std::deque< std::pair<int,int> > deq;

    deq.push_back(std::make_pair(start, 0));
    while(!deq.empty()){
        auto point = deq.front();
        deq.pop_front();

        distance[player][point.first] = point.second;

        for( int t : to[point.first] ){
            if( distance[player][t] == -1 ){
                deq.push_back(std::make_pair(t, point.second + 1));
            }
        }
    }
}

