        to[a].push_back(b);
        to[b].push_back(a);
    }

    distance[0].resize(N);
    distance[1].resize(N);

    for(int i=0; i<N; ++i){
        distance[0][i] = distance[1][i] = -1;
    }

    calc(0, 0);
    calc(1, N-1);

    int fennec = 0, sunuke = 0;
