			wq.emplace(e);
			check[e] *= 2;
			++wcount;

		}
	}


	decltype(wcount) bcount{};
	decltype(wq) bq;
	bq.emplace(0);
	check[0] *= 3;

	while (!bq.empty()) {

		auto vtx = bq.front(); bq.pop();
		for (auto e : tab[vtx]) {

			if (check[e] % 3 == 0 || e == n - 1)
				continue;

			bq.emplace(e);
			check[e] *= 3;
			++bcount;
		}
	}

	std::cout << (wcount < bcount ? "Fennec" : "Snuke") << "\n";

	return 0;
}

