    vector<pair<ll, ll>> v{};
    for (int i=0; i < N; ++i) {
        ll x;
        ll y;
        cin >> x >> y;
        v.emplace_back(make_pair(x,y));
    }
    C c{move(v)};
    cout << (c.resolve() ? "Fennec" : "Snuke") << endl;
    return 0;
}

