class UnionFind{
public:
    V par,rank;// parent,rank
    UnionFind(int n);
    int Find(int x);
    void Unite(int x,int y);
    bool Same(int x,int y);
};
UnionFind::UnionFind(int n){
    par.resize(n);rank.resize(n);
    REP(i,n){par[i]=i;rank[i]=0;}
}
int UnionFind::Find(int x){

    return (par[x]==x?x:Find(par[x]));
}
void UnionFind::Unite(int x,int y){
    x=Find(x);y=Find(y);//parent

    if(x==y)return;//end
    if(rank[x]<rank[y])par[x]=y;
    else{
        par[y]=x;
        if(rank[x]==rank[y])rank[x]++;
    }
}
bool UnionFind::Same(int x,int y){
    return (Find(x)==Find(y));
}

class Dijkstra{
public:
    Dijkstra(vector<M> ed,int firs,int pnum);
    void Solve();
    V range;// range[a]=b;
    vector<M> edges;// [a][b]=c;
    priority_queue<P,vector<P>,greater<P>> que;// queue=(range,point);
    V keiro;
    V CalcRoute(int startp,int endp,V vec);
};

Dijkstra::Dijkstra(vector<M> ed,int firs,int pnum){
    edges=ed;
    V ttt(pnum,INF);
    range=ttt;
    range[firs]=0;
    que.push(mp(0,firs));
    keiro=V(pnum);
    REP(i,pnum)keiro[i]=i;
}

void Dijkstra::Solve(){
    while(!que.empty()){
        P top_=que.top();
        que.pop();
        FOREACH(x,edges[top_.second]){
            if(range[x.first] > range[top_.second] + x.second){
                range[x.first] = range[top_.second] + x.second;
                que.push(mp(range[x.first],x.first));
                keiro[x.first] = top_.second;
            }
        }
    }
}

V Dijkstra::CalcRoute(int startp,int endp,V vec){
  vec.pb(endp);
  if(keiro[endp] == startp){
    vec.pb(startp);
    return vec;
  }else{
    return CalcRoute(startp,keiro[endp],vec);
  }
}


