{
  ll N;
	cin >> N;
	WeightedGraph<ll> G(N);
	REP(i, N-1) {
		ll a, b;
		cin >> a >> b;
		a--; b--;
		G[a].emplace_back(b,1);
		G[b].emplace_back(a,1);
	}
	vector<ll> dist, prev, num;
	dijkstra(G, dist, prev, num, 0);
	vector<ll> path = get_path(prev, N-1);
	vector<bool> vi(N);
	vector<bool> color(N);
	REP(i, path.size()) {
		if (i % 2 == 0) {
			vi[path[i/2]] = true;
			color[path[i/2]] = true;
		} else {
			vi[path[path.size()-1 - i/2]] = true;
		}
	}

	vector<bool> visited = vi;
	REP(i, N) {
		if (visited[i]) {
			stack<ll> sta;
			sta.push(i);
			while(!sta.empty()) {
				ll t = sta.top();
				sta.pop();
				REP(j, G[t].size()) {
					if (!vi[G[t][j]]) {
						sta.push(G[t][j]);
						vi[G[t][j]] = true;
						color[G[t][j]] = color[i];
					}
				}
			}
		}
	}
	ll cnt = 0;
	REP(i, N) {
		cnt += color[i];
	}
	if (cnt > N-cnt) PRINT("Fennec");
	else PRINT("Sunuke");
	return 0;
}

