    path.push_back(n-1);
    while(!q.empty()) q.pop();
    q.push(n-1);

    //経路復元
    while(1){
        int current_place = q.front();
        if(current_place == 0) break;
        q.pop();
        for(int x : v[current_place]){
            if(d[x] == d[current_place] - 1){
                q.push(x);
                path.push_back(x);
                break;
            }
        }
    }
    reverse(all(path));

    for(size_t i = 0; i <= (path.size() + 1)/2; i++){
        color[path[i]] = 0;
    }
    for(size_t i = (path.size() + 3)/2; i < path.size(); i++){
        color[path[i]] = 1;
    }

    //着色
    int cnt_b = (int(path.size()) + 1)/2;
    int cnt_w = (int(path.size()))/2;
    while(!q.empty()) q.pop();
    q.push(0);
    while(!q.empty()){
        int current_place = q.front();
        q.pop();
        for(int x : v[current_place]){
            if(color[x] >= 0) continue;
            cnt_b++;
            color[x] = 0;
            q.push(x);
        }
    }
    cnt_w = n - cnt_b;
    if(cnt_w >= cnt_b) cout << "Sunuke" << endl;
    else cout << "Fennec" << endl;;
}

