bool flag=false;
void dfs(int be,int en)
{
	vis[be]=true;
	if(be==en)
	{
		flag=true;
		return;
	}
	int len=node[be].to.size();
	for(int i=0;i<len;i++)
	{
		if(!vis[node[be].to[i]])
		{
			dfs(node[be].to[i],en);
			if(!flag)vis[node[be].to[i]]=false;
		}
	}
}
int temp=0;
void go(int be)
{
	vis[be]=true;
	int len=node[be].to.size();
	for(int i=0;i<len;i++)
	{
		if(!vis[node[be].to[i]])
		{
			temp++;
			go(node[be].to[i]);
		}
	}
}
