		node[a].to.push_back(b);
		node[b].to.push_back(a);
	}
	dfs(1,n);
	int l=0;
	for(int i=1;i<=n;i++)
	{
		if(vis[i])
		{
			tree[l++]=i;
		}
	}
	int ansa=0;
	int ansb=0;
	for(int i=0;i<l/2;i++)
	{
		temp=0;
		go(tree[i]);
		ansa+=temp+1;
		temp=0;
		go(tree[l-1-i]);
		ansb+=temp+1;	
	}
	if(l%2)
	{
		temp=0;
		go(tree[l/2]);
		ansa+=temp+1;
	}
	//cout<<ansa<<endl<<ansb<<endl;
	if(ansa>ansb)printf("Fennec\n");
	else printf("Snuke\n");

}

