using namespace std;
using namespace boost;
using uint = unsigned int;
using ll = long long int;
using ull = unsigned long long int;

int main() {
    ll N;
    cin >> N;
    vector<vector<ll>> nodes(N, vector<ll>{});
    for (auto &&i: boost::irange(0LL, N - 1)) {
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        nodes.at(a).emplace_back(b);
        swap(a, b);
        nodes.at(a).emplace_back(b);
    }
    vector<ll> distance_from_0(N, numeric_limits<ll>::max());
    deque<ll> q{};
    q.emplace_back(0LL);
    distance_from_0.at(0) = 0;
    while (!q.empty()) {
        ll now = q.front();
        q.pop_front();
        for (auto &&next: nodes.at(now)) {
            if (distance_from_0.at(next) == numeric_limits<ll>::max()) {
                distance_from_0.at(next) = distance_from_0.at(now) + 1;
                q.emplace_back(next);
            }
        }
    }
    vector<ll> distance_from_last(N, numeric_limits<ll>::max());
    q.emplace_back(N - 1);
    distance_from_last.back() = 0;
    while (!q.empty()) {
        ll now = q.front();
        q.pop_front();
        for (auto &&next: nodes.at(now)) {
            if (distance_from_last.at(next) == numeric_limits<ll>::max()) {
                distance_from_last.at(next) = distance_from_last.at(now) + 1;
                q.emplace_back(next);
            }
        }
    }
    ll count_f{0};
    ll count_s{0};
//    for (auto &&i: boost::irange(0LL, N)){
//        cout << i << " " << distance_from_0.at(i) << " " << distance_from_last.at(i) << endl;
//    }
    for (auto &&i: boost::irange(0LL, N)) {
        if (distance_from_0.at(i) <= distance_from_last.at(i)) {
            count_f++;
        } else {
            count_s++;
        }
    }
    if (count_f > count_s) {
        cout << "Fennec";
    } else {
        cout << "Snuke";
    }
    return 0;
}

