    while(PQ.size()) {
        P f=PQ.top(); PQ.pop();
        u=f.second;

        color[u]=BLACK;
        if(d[u]<f.first*(-1)) continue;

        for(i=0; i<G[u].size(); i++) {
            Edge &e=G[u][i];
            if(color[e.t]!=BLACK && d[e.t]>d[u]+e.w) {
                d[e.t]=d[u]+e.w;
                PQ.push(P(-d[e.t], e.t));
            }

        }

    }

}


