    vll par(n,0);
    par[0]=-1;
    vll dep(n,INF);
    dep[0]=0;
    stack<ll> st;
    st.push(0);
    while(!st.empty()){
        ll now = st.top();
        st.pop();
        for(ll i : nei[now]){
            if(i!=par[now]){
                dep[i]=dep[now]+1;
                par[i]=now;
                st.push(i);
            }
        }
    }
    ll ca,cb;
    ll x = n-1;
    while(true){
        ll now = par[x];
        if(dep[now]==(dep[n-1]/2)){
            ca = x;
            cb = now;
            break;
        }
        x = now;
    }
    UnionFind uf(n);
    REP(i,n-1){
        if((p[i].fi==ca&&p[i].se==cb)||(p[i].fi==cb&&p[i].se==ca)){
            continue;
        }
        uf.unite(p[i].fi,p[i].se);
    }
    int bl = (int)uf.groups[uf.id[0]].size();
    int wh = (int)uf.groups[uf.id[n-1]].size();
