using Graph = vector<vector<int>>;

int main() {
    // 頂点数と辺数
    int n;
    cin >> n;

    // グラフ入力受取 (ここでは無向グラフを想定)
    Graph G(n);
    rep(i,n-1) {
        int a,b;
        cin >> a >> b;
        G[a-1].pb(b-1);
        G[b-1].pb(a-1);
    }

    // BFS のためのデータ構造
    vector<int> dist(n, -1); // 全頂点を「未訪問」に初期化
    deque<int> que;

    // 初期条件 (頂点 0 を初期ノードとする)
    dist[0] = 0;
    que.pb(0); // 0 を橙色頂点にする

    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        int v = que.front(); // キューから先頭頂点を取り出す
        que.pop_front();

        // v から辿れる頂点をすべて調べる
        for (int nv : G[v]) {
            if (dist[nv] != -1) continue; // すでに発見済みの頂点は探索しない

            // 新たな白色頂点 nv について距離情報を更新してキューに追加する
            dist[nv] = dist[v] + 1;
            que.pb(nv);
        }
    }

    vector<int> dist2(n, -1); // 全頂点を「未訪問」に初期化

    // 初期条件 (頂点 0 を初期ノードとする)
    dist2[n-1] = 0;
    que.pb(n-1); // 0 を橙色頂点にする

    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        int v = que.front(); // キューから先頭頂点を取り出す
        que.pop_front();

        // v から辿れる頂点をすべて調べる
        for (int nv : G[v]) {
            if (dist2[nv] != -1) continue; // すでに発見済みの頂点は探索しない

            // 新たな白色頂点 nv について距離情報を更新してキューに追加する
            dist2[nv] = dist2[v] + 1;
            que.pb(nv);
        }
    }   

  int fe=0;
  rep(i,n) {
    if(dist[i]<=dist2[i]) fe++;
  }

  cout << (fe>n-fe?"Fennec":"Snuke") << endl;

}

