		a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	int nl, nr;// 塗った点の数(点0からと点n-1から)
	nl = nr = 1;
	vector<bool>splat(n, false);// 色塗り済みかどうかを格納
	splat[0] = splat[n - 1] = true;

	// 点0と点n-1の2点から交互にBFSを進めて、
	// 両方の探索が続けられなくなったら、
	// 塗れた点の数を数えて勝敗を出力する
	queue<int>sl, sr;
	sl.push(0);
	sr.push(n - 1);
	while (!sl.empty() || !sr.empty()) {
		int sizel = sl.size();
		rep(i, sizel) {//点0からの距離が同じ点集合を全部popする
			if (!sl.empty()) {
				int l = sl.front();
				sl.pop();
				for (auto v : g[l]) {
					if (splat[v] == false) {
						splat[v] = true;
						sl.push(v);
						nl++;
					}
				}
			}
		}
		int sizer = sr.size();
		rep(i,sizer){
			int r = sr.front();
			sr.pop();
			for (auto v : g[r]) {
				if (splat[v] == false) {
					splat[v] = true;
					sr.push(v);
					nr++;
				}
			}
		}
	}


	if (nl > nr) cout << "Fennec" << endl;
	else cout << "Snuke" << endl;


	return 0;
}

