#define rep(i, n) for(ll i=0;i<(ll)(n);i++)
#define rep1(i, n) for(ll i=1;i<=(ll)(n);i++)
#define rep2(i, m, n) for(ll i=m;i<(ll)(n);i++)
#define rrep(i, n, m) for(ll i=n;i>=(ll)(m);i--)
#define ALL(obj) (obj).begin(), (obj).end()
#define MOD 1000000007
#define INF 1000000000

#define MAX_V 100001
struct edge {
	int to;
	int cost;
};
vector<edge> G[MAX_V];
int d[MAX_V];

void dijkstra(int s) {
	priority_queue<P, vector<P>, greater<P> > que;
	fill(d, d + MAX_V, INF);
	d[s] = 0;
	que.push(P(0, s));

	while (!que.empty()) {
		P p = que.top();
		que.pop();
		int v = p.second;
		if (d[v] < p.first) continue;

		for (int i = 0; i < G[v].size(); ++i) {
			edge e = G[v][i];
			if (d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				que.push(P(d[e.to], e.to));
			}
		}
	}
}

void solve_abc_d() {
	ll n;

	cin >> n;

	ll a, b;
	edge e;
	rep(i, n - 1) {
		cin >> a >> b;
		e.to = a;
		e.cost = 1;
		G[b].push_back(e);
		e.to = b;
		e.cost = 1;
		G[a].push_back(e);
	}

	int d1[MAX_V], dn[MAX_V];
	dijkstra(1);
	rep1(i, n) {
		d1[i] = d[i];
	}
	dijkstra(n);
	rep1(i, n) {
		dn[i] = d[i];
	}

	ll f = 0;
	ll s = 0;
	rep1(i, n) {
		if (d1[i] <= dn[i]) {
			f++;
		}
		else {
			s++;
		}
	}

	if (f > s) {
		cout << "Fennec\n";
	}
	else {
		cout << "Snuke\n";
	}
}

