vector<int> dis(100005, INF);
vector<int> check(100005);
vector<int> color(100005);
int N;
int m;

void discalc(int a, int d){
    dis[a] = d;
    for(int p : to[a]){
        if(dis[p] != INF)continue;
        discalc(p, d+1);
    }
    return;
}

int road(int a){
    if(a == N-1){
        return check[a] = 1;
    }
    if(a != 0 && to[a].size() == 1){
        return check[a] = 2;
    }
    for(int p : to[a]){
        if(dis[p] < dis[a])continue;
        if(check[p] == 2)continue;
        if(check[p] == 1)return check[a] = 1;

        int x = road(p);
        if(x == 2)continue;
        if(x == 1)return check[a] = 1;
    }
    return check[a] = 2;
}

void coloring(int a, int d){
    color[a] = 1;
    if(d == m)return;
    for(int p : to[a]){
        if(dis[p] > dis[a])continue;
        if(check[p] == 1)coloring(p, d+1);
    }
    return;
}

void coloring2(int a){
    color[a] = 1;
    for(int p : to[a]){
        if(color[p] != 0)continue;
        coloring2(p);
    }
    return;
}

int main() {
    cin >> N;
    rep(i, N-1){
        int a, b; cin >> a >> b;
        a--; b--;
        to[a].push_back(b);
        to[b].push_back(a);
    }

    discalc(0, 0);
    road(0);

    m = (dis[N-1]-2) / 2;
    coloring(N-1, 0);
    rep(i, N){
        if(check[i] == 1 && color[i] == 0){
            color[i] = 2;
        }
    }
    rep(i, N){
        if(color[i] != 2){
            color[i] = 0;
        }
    }
    coloring2(N-1);

    int cnt = 0;
    rep(i, N){
        if(color[i] == 1){
            cnt++;
        }
    }

    int need = (N+1)/2;
    if(cnt >= need){
        cout << "Snuke" << endl;
    } else {
        cout << "Fennec" << endl;
    }

    return 0;
}

