void dfs(int s,int p,int d,vector<int> &dist,vector<int> &parent,vector<vector<int> > &G){
    parent[s]=p;
    dist[s]=d;
    for(auto v:G[s]){
        if(v!=p) dfs(v,s,d+1,dist,parent,G);
    }
}

int rec(int s,vector<int> &num,vector<int> &parent,vector<vector<int>> &G){
    if(num[s]!=-1)return num[s];
    else {
        int tmp=1;
        for(auto v:G[s]){
            if(v!=parent[s])tmp+=rec(v,num,parent,G);
        }
        num[s]=tmp;return num[s];
    }
}

int main(){
    int N;cin>>N;
    vector<vector<int> > G(N);
    int a,b;
    REP(i,N-1){
        cin>>a>>b;a--;b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    vector<int> parent(N);
    vector<int> dist(N),num(N,-1);    
    dfs(0,-1,0,dist,parent,G);
    int u=N-1;
    REP(i,(dist[N-1]+1)/2-1)u=parent[u];
    cout<<(rec(u,num,parent,G)>=(N%2==0?N/2:N/2+1)?"Snuke":"Fennec")<<endl;
    return 0;
}

