const int INF = 1000000000;
const int maxN = 100010;
const int maxK = 19;
int a[maxN];
int b[maxN];
int deep[maxN];
int pre[maxN][maxK];
int flag;
vector<int> v[maxN];
void dfs(int x,int p)
{
	a[x] = flag++;
	for(int i=0;i<v[x].size();i++)
	{
		int y = v[x][i];
		if(y==p)
			continue;
		else
		{
			pre[y][0] = x;
			deep[y] = deep[x] + 1;
			dfs(y,x); 
		}
	}
	b[x] = flag;
}
int main()
{
	int n;
	scanf("%d",&n);
	for(int i=1;i<n;i++)
	{
		int x,y;
		scanf("%d%d",&x,&y);
		v[x].push_back(y);
		v[y].push_back(x);
	}
	deep[1] = 1;
	flag = 1;
	pre[1][0] = 0;
	dfs(1,0);
	for(int i=1;i<=n;i++) 
		for(int p=1;p<maxK;p++)
		{
			int x = pre[i][p-1];
			pre[i][p] = pre[x][p-1]; 
		}
	int pos = 0;
	int s = n;
	for(int i=maxK-1;i>=0;i--)
	{
		if(pre[s][i] == 0)
			continue;
		else
		{
			s = pre[s][i];
			pos += 1<<i;
			if(pre[n][i] == 1)
				break;
		}
	}
	pos = (pos-1)/2;
	int tmp = 0;
	s = n;
	for(int i=maxK-1;i>=0;i--)
	{
		if(pos == 0)
			break;
		if(pre[s][i] == 0)
			continue;
		else
		{
			s = pre[s][i];
			tmp += 1<<i;
			if(tmp == pos)
				break;
		}
	}
	int fen,snu;
	snu = b[s] - a[s];
	fen = n - snu;
	if(fen >= snu )
		printf("Fennec\n");
	else
		printf("Snuke\n");
	return 0;
}

