int main() {
    cin >> n;
    VVi adj(n);
    REP(i, n-1) {
        int a, b; cin >> a >> b;
        a--; b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    Vi parent(n, -1);
    queue<int> q;
    q.push(0);
    parent[0] = 0;
    while (!q.empty()) {
        int node = q.front();
        q.pop();
        for (auto x: adj[node]) {
            if (parent[x] != -1) continue;
            parent[x] = node;
            q.push(x);
        }
        if (parent[n-1] != -1) break;
    }

    Vi path = {n-1};
    while (path.back() != 0) {
        path.push_back(parent[path.back()]);
    }
    int confnode = path[path.size()/2-1];

    UFTree t = UFTree(n);
    q = queue<int>();
    q.push(0);
    while (!q.empty()) {
        int node = q.front();
        q.pop();
        for (auto x: adj[node]) {
            if (t.same(0, x) || x == confnode) continue;
            t.unite(0, x);
            q.push(x);
        }
    }

    int s = t.size(0);
    if (s > n-s) {
        cout << "Fennec" << '\n';
    } else {
        cout << "Snuke" << '\n';
    }

    return 0;
}

