std::vector<int> calcDistance(int nodeNum, std::vector<std::pair<int, int>> edge, int startIndex){
    std::vector<int> ret;
    ret.resize(nodeNum, -1);
    ret[startIndex] = 0;

    std::queue<int> queue;
    queue.push(startIndex);

    std::vector<std::pair<int, int>> tempedge = edge;

    while(!queue.empty()){
        int node = queue.front();
        queue.pop();
        for(int i=tempedge.size()-1;i>=0;i--){
            int a = tempedge[i].first;
            int b = tempedge[i].second;
            if(a == node && ret[b] == -1 && b != startIndex){
                ret[b] = ret[a] + 1;
                queue.push(b);
                tempedge.erase(tempedge.begin() + i);
            }
            if(b == node && ret[a] == -1 && a != startIndex){
                ret[a] = ret[b] + 1;
                queue.push(a);
                tempedge.erase(tempedge.begin() + i);
            }
        }
    }

    return ret;
}

