    while(q1.size() > 0){
        int num = q1.front();
        q1.pop();
        rep(j, G[num].size()){
            int idx = G[num][j];
            if (dis1[idx] != -1) continue;
            dis1[idx] = dis1[num] + 1;
            q1.push(idx);
        }
    }
    while(q2.size() > 0){
        int num = q2.front();
        q2.pop();
        rep(j, G[num].size()){
