struct SS
{
	vector<int> link;
	int score;
};
SS S[100001];

void find_score(int i)
{
	for (int j : S[i].link) {
		if (S[j].score == -1) {
			S[j].score = S[i].score + 1;
			find_score(j);
		}
	}
}

int64_t find_links(int i, int parent)
{
	int64_t sum = 1;
	for (int j : S[i].link) {
		if (j != parent) {
			sum += find_links(j, i);
		}
	}
	return sum;
}
int main(int argc, char* argv[])
{
	if (argc >= 2) {
		FILE* fp = freopen(argv[1], "r", stdin);
	}

	int N;
	cin >> N;
	for (int i = 1; i <= N; i++) {
		S[i].score = -1;
	}
	for (int i = 0; i < N - 1; i++) {
		int a, b;
		cin >> a >> b;
		S[a].link.push_back(b);
		S[b].link.push_back(a);
	}
	S[1].score = 0;
	find_score(1);
	vector<int> root;
	root.push_back(N);
	for (int i = N; i != 1;) {
		for (int j : S[i].link) {
			if (S[j].score == S[i].score - 1) {
				root.push_back(j);
				i = j;
				break;
			}
		}
	}
	int64_t f = 0, s = 0;
	int i = 0;
	for (i; i < root.size() / 2; i++) {
		int j = root[i];
		s++;
		for (int k : S[j].link) {
			if (i != 0 && k == root[i - 1]) continue;
			if (i != root.size() - 1 && k == root[i + 1]) continue;
			s += find_links(k, j);
		}
	}
	for (; i < root.size(); i++) {
		int j = root[i];
		f++;
		for (int k : S[j].link) {
			if (i != 0 && k == root[i - 1]) continue;
			if (i != root.size() - 1 && k == root[i + 1]) continue;
			f += find_links(k, j);
		}
	}
	if (f > s) {
		cout << "Fennec";
	} else {
		cout << "Snuke";
	}

	return 0;
}

