        load[a].push_back(b);
        load[b].push_back(a);
    }
    SearchResult r = calcStepsToN(-1, 1, 0);
    int count = countCitys(-1, 1, r.centerCityIdx);
    if (count > N / 2) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
    return 0;
}

