// Dijkstra
struct Dijkstra {
  struct Edge {
    int to;
    long long cost;
  };

  vector<vector<Edge>> G;
  int num_v;

 public:
  Dijkstra(int num_v) : G(num_v), num_v(num_v) {
  }

  void add_edge(int from, int to, long long cost) {
    G[from].push_back((Edge){to, cost});
  }

  // start: Start point
  // result: result
  void solve(int start, vector<long long>& result) {
    vector<int> tmp;
    solve(start, result, tmp);
  }

  void solve(int start, vector<long long>& result, vector<int>& prev) {
    result.resize(num_v, INF);
    prev.resize(num_v, -1);

    // get<0>(T): cost
    // get<1>(T): index
    // get<2>(T): ... ( for extent)
    using T = tuple<long long, int>;
    priority_queue<T, vector<T>, greater<T>> que;

    que.emplace(0, start);

    while (!que.empty()) {
      T p = que.top();
      que.pop();

      long long t = get<0>(p);
      int v = get<1>(p);

      // 対象以下のコストの経路が既に見つかっている場合
      if (result[v] <= t) {
        continue;
      }

      result[v] = t;

      // vの各辺に対しよりコストの低い経路があるかを確認
      for (auto& e : G[v]) {
        // pathを確認しないならこのifはなくても良い
        if (result[e.to] > result[v] + e.cost) {
          prev[e.to] = v;
          que.emplace(result[v] + e.cost, e.to);
        }
      }
    }
  }

  // t: 目的地
  vector<int> get_path(const vector<int>& prev, int t) {
    vector<int> path;

    for (int v = t; v != -1; v = prev[v]) {
      path.push_back(v);
    }

    reverse(path.begin(), path.end());
    return path;
  }
};

Dijkstra d(1);

int dfs(int idx, int from, int prohibited) {
  int ans = 1;
  FORm(it, d.G[idx]) {
    if (it->to != from && it->to != prohibited) {
      ans += dfs(it->to, idx, prohibited);
    }
  }
  return ans;
}

signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(20);

  ll n;
  cin >> n;

  d = Dijkstra(n + 1);

  rep(i, n - 1) {
    ll a, b;
    cin >> a >> b;
    d.add_edge(a, b, 1);
    d.add_edge(b, a, 1);
  }

  vll dist;
  vi pre;
  d.solve(1, dist, pre);
  vi path = d.get_path(pre, n);
  int si = (path.size() + 1) / 2;
  int fi = si - 1;

  // 1-nの最短経路でそれぞれがどこまで取れたか
  int f = path[fi];
  int s = path[si];

  int nf = dfs(1, -1, s);
  int sf = n - nf;

  if (nf > sf) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }

  return 0;
}

