	t = 2;
	while (t < n) {
		k = fe.size();
		for (int i = 0; i < k; i++) {
			u = fe.front();
			fe.pop();
			for (int j = 0; j < g[u].size(); j++) {
				if (d[g[u][j]] == 0) {
					d[g[u][j]] = d[u] + 1;
					fe.push(g[u][j]);

					x++;
				}
			}
		}
		k = sn.size();
		for (int i = 0; i < k; i++) {
			u = sn.front();
			sn.pop();
			for (int j = 0; j < g[u].size(); j++) {
				if (d[g[u][j]] == 0) {
					d[g[u][j]] = d[u] - 1;
					sn.push(g[u][j]);
					y++;
				}
			}
		}
	}
