        ll from; // 移動前のノード
        ll to; // 移動先のノード
        ll cost; // 辺のコスト
        ll hoge; // 任意変更 いらないかも

        Edge() = default;
        Edge(ll _to) : from(-1), to(_to), cost(1), hoge(-1) {};
        Edge(ll _to, ll _cost) : from(-1), to(_to), cost(_cost), hoge(-1) {};
        Edge(ll _from, ll _to, ll _cost) : from(_from), to(_to), cost(_cost), hoge(-1) {};
        Edge(ll _from, ll _to, ll _cost, ll _hoge) : from(_from), to(_to), cost(_cost), hoge(_hoge) {};
        bool operator< (const Edge& rhs) const {
            return cost < rhs.cost;
        }
        bool operator> (const Edge& rhs) const {
            return cost > rhs.cost;
        }
    };

    using Graph = vector<vector<Edge>>;

    // ダイクストラ法 O(ElogV)
    vector<ll> dijkstra(ll start, const Graph& G) {
        vector<ll> dist(G.size(), infll);
        // 辺のコストが小さい順に取り出す　場合に応じて変更
        priority_queue<Edge, vector<Edge>, greater<Edge>> que;

        dist[start] = 0; // dist[i] := start->iまでの最短距離
        que.push(Edge(start, 0));

        while (!que.empty()) {
            ll cost, u; // 今までにかかった時間　現在の頂点
            cost = que.top().cost, u = que.top().to;
            que.pop();
            if (dist[u] < cost) continue;
            for (auto& e : G[u]) {
                ll v = e.to;
                ll new_cost = cost + e.cost;

                if (dist[v] <= new_cost) continue;

                dist[v] = new_cost;
                que.push(Edge(v, new_cost));
            }
        }
        return dist;
    }


    struct UnionFind {
    private:
        const int n;
        int __size;
        vector<int> uf;
    public:
        // 初期化 UnionFind uni(n) のように宣言すれば良い
        UnionFind(int _n) : n(_n), __size(_n), uf(_n, -1) {}
        // find (木の根を求める)
        int find(int x) { return (uf[x] < 0) ? x : uf[x] = find(uf[x]); }
        // x と y が同じ集合に属するかどうか
        bool same(int x, int y) { return find(x) == find(y); }
        // x が属する集合の要素数
        int size(int x) { return -uf[find(x)]; }
        // 集合はいくつあるか
        int size() { return __size; }
        // x と y の属する集合を併合
        bool unite(int x, int y) {
            x = find(x); y = find(y);
            if (x == y) return false;
            __size--;
            if (uf[y] < uf[x]) swap(x, y);
            uf[x] += uf[y]; uf[y] = x;
            return true;
        }
    };
}

int main() {

    int n = inp1;
    Graph G(n);
    vector<int> a(n - 1), b(n - 1);
    rep(i, n - 1) {
        cin >> a[i] >> b[i];
        --a[i], --b[i];
        G[a[i]].emplace_back(Edge(b[i]));
        G[b[i]].emplace_back(Edge(a[i]));
    }

    // 陣取りゲーム

    // お互いが近づこうとする
    auto dist_0 = dijkstra(0, G);
    auto dist_n = dijkstra(n - 1, G);

    int dist = dist_0[n - 1];
    vector<int> path(dist + 1);
    path[0] = 0;
    rep(i, dist) {
        int u = path[i];
        for (auto e : G[u]) {
            if (dist_n[e.to] == dist - i - 1) {
                path[i + 1] = e.to;
                break;
            }
        }
    }

    // エッジを切る
    pair<int, int> p = { path[dist / 2], path[dist / 2 + 1] };
    UnionFind uni(n);
    rep(i, n - 1) {
        if (p.first == a[i] && p.second == b[i] || p.second == a[i] && p.first == b[i]) continue;

        uni.unite(a[i], b[i]);
    }

    int ans = uni.size(0) - uni.size(n - 1);

    if (ans <= 0) Cout("Snuke");
    else Cout("Fennec");

    // データ構造の乱用

    return 0;
}

