int dfs(vvi &root, int pos, int color, pii dis, vi &checked){
  int ans = 1;
  for(int a : root[pos]){
    if(!checked[a]){
      if(color && dis.second == a) continue;
      if(!color && dis.first == a) continue;
      checked[a] = 1;
      ans += dfs(root, a, color, dis, checked);
    }
  }
  return ans;
}
