using namespace std;
typedef long long ll;
typedef pair<int,int> P;
int INF=1<<29;

vector<P> table[100000]; //隣接リスト to,cost
int d[100000]; //S→Gのcost
int preva[100000];
bool used[100000];
priority_queue<P> que;
int path;
bool use[100000];

void dijkstra(int s){
	fill(d,d+100000,INF);
	fill(used,used+100000,false);
	d[s]=0;
	que.push(P(s,0));

	while(!que.empty()){

		int Rto=que.top().first, Rcost=que.top().second; //中継点(Relay),S→Rのcost
		que.pop();
		if(used[Rto]) continue;
		if(Rcost > d[Rto]) continue;
		used[Rto]=true;

		for(int i=0;i<table[Rto].size();i++){
			int to=table[Rto][i].first, cost=table[Rto][i].second; //目的地(G),R→Gのcost
			if(d[to] > cost + Rcost){
				d[to] = cost + Rcost;
				que.push( P(to,d[to]) );
				preva[to]=Rto;
			}
		}

	}
}

int dfs(int s){
	int res=0;
	for(int i=0;i<table[s].size();i++){
		if(use[table[s][i].first]) continue;
		use[table[s][i].first]=true;
		res++;
		res+=dfs(table[s][i].first);
	}
	return res;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	int N;
	cin>>N;
	for(int i=0;i<N-1;i++){
		int a,b;
		cin>>a>>b;
		a--; b--;
		table[a].push_back(make_pair(b,1));
		table[b].push_back(make_pair(a,1));
	}
	for(int i=0;i<1000;i++) preva[i]=-1;
	dijkstra(0);

	vector<int> path;
	for(int t=N-1;t!=-1;t=preva[t]) path.push_back(t);
	reverse(path.begin(),path.end());
	int fennec;
	fennec=path[(path.size()+1)/2-1];

	for(int i=0;i<N;i++) use[i]=false;
	use[fennec]=true;
	use[fennec+1]=true;
	int ans=dfs(fennec)+1;
	if(ans>N-ans) cout<<"Fennec"<<endl;
	else cout<<"Snuke"<<endl;
	return 0;
}

