using namespace std;

struct PathData
{
    long long pos;
    long long dist;
    unordered_set<long long> set;
};

int main()
{
    unordered_map<long long, vector<long long>> checkMap;
    unordered_map<long long, long long> fennecMap;
    unordered_map<long long, long long> sunukeMap;

    long long N;
    cin >> N;

    long a, b;
    for (long long i = 0; i < N; i++)
    {
        cin >> a >> b;
        a--;
        b--;
        checkMap[a].push_back(b);
        checkMap[b].push_back(a);
    }

    queue<PathData> PQueue;
    for (long long i = 0; i < checkMap[0].size(); i++)
    {
        if (checkMap[0][i] != N - 1)
        {

            PathData pd;
            pd.pos = checkMap[0][i];
            pd.dist = 1;
            pd.set.emplace(0);
            PQueue.push(pd);
        }
    }
    fennecMap[0] = 0;

    while (!PQueue.empty())
    {
        PathData pd = PQueue.front();
        PQueue.pop();

        fennecMap[pd.pos] = pd.dist;

        for (long long i = 0; i < checkMap[pd.pos].size(); i++)
        {
            if (checkMap[pd.pos][i] != N - 1 && pd.set.find(checkMap[pd.pos][i]) == pd.set.end())
            {
                PathData pd_new;
                pd_new.pos = checkMap[pd.pos][i];
                pd_new.dist = pd.dist + 1;
                pd_new.set.emplace(pd.pos);
                PQueue.push(pd_new);
            }
        }
    }

    while (!PQueue.empty())
    {
        PQueue.pop();
    }

    for (long long i = 0; i < checkMap[N - 1].size(); i++)
    {
        if (checkMap[N - 1][i] != 0)
        {

            PathData pd;
            pd.pos = checkMap[N - 1][i];
            pd.dist = 1;
            pd.set.emplace(N - 1);
            PQueue.push(pd);
        }
    }
    sunukeMap[N - 1] = 0;

    long long fennec = 0;
    while (!PQueue.empty())
    {
        PathData pd = PQueue.front();
        PQueue.pop();

        sunukeMap[pd.pos] = pd.dist;
        if (pd.dist >= fennecMap[pd.pos])
        {
            fennec++;
        }

        for (long long i = 0; i < checkMap[pd.pos].size(); i++)
        {
            if (checkMap[pd.pos][i] != 0 && pd.set.find(checkMap[pd.pos][i]) == pd.set.end())
            {
                PathData pd_new;
                pd_new.pos = checkMap[pd.pos][i];
                pd_new.dist = pd.dist + 1;
                pd_new.set.emplace(pd.pos);
                PQueue.push(pd_new);
            }
        }
    }

    if (N - fennec > 0)
    {
        cout << "Fennec" << endl;
    }
    else
    {
        cout << "Snuke" << endl;
    }

    return 0;
}

