const long long MAX_V = 200000;
const long long INF = 1LL << 60;
typedef long long ll;

struct edge
{
    long long to, cost;
};
typedef pair<long long, long long> P;

long long d[MAX_V];
long long prevnode[MAX_V];
bool visited[MAX_V];
long long n, m, t;

vector<edge> G[MAX_V];

void dijkstra(long long s, vector<edge> G[])
{
    priority_queue<P, vector<P>, greater<P>> que;
    fill(d, d + MAX_V, INF);
    fill(prevnode, prevnode + MAX_V, -1);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty())
    {
        P p = que.top();
        que.pop();
        long long v = p.second;
        if (d[v] < p.first)
            continue;
        for (long long i = 0; i < G[v].size(); i++)
        {
            edge e = G[v][i];
            if (not(visited[e.to]) and d[e.to] > d[v] + e.cost)
            {
                d[e.to] = d[v] + e.cost;
                prevnode[e.to] = v;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

vector<long long> get_path(ll t)
{
    vector<ll> path;
    for (; t != -1; t = prevnode[t])
        path.push_back(t);
    reverse(path.begin(), path.end());
    return path;
}

