		int x, y, z;
		scanf("%d%d", &x, &y);
		if((x == 1 || x == n) && (y == 1 || y == n))  z = 1;
		else if(x == 1 || x == n)
			Build(x, y, 1);
		else if(y == 1 || y == n)
			Build(y, x, 1);
		else {
			Build(x, y, 1);
			Build(y, x, 1);
		}
	}
	dfs1(1, 0);
	dfs2(n, n + 1);
	int c = a + b;
	int d = c - (n - 2);
	int e = d / 2;
	b += e;
	a += (d - e);
	if(a > b) flag = 1;
	if(flag == 1) printf("Fennec\n");
	else printf("Snuke\n");
	return 0;
}

