void dfs(int v, int p, int d, VVI& G, VI& dist) {
	dist[v] = d;
	FOR(i, 0, SZ(G[v])) {
		int nx = G[v][i];
		if (nx != p) {
			dfs(nx, v, d + 1, G, dist);
		}
	}
}
int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> N;
	VVI G(N);
	FOR(i, 0, N - 1) {
		int a, b;
		cin >> a >> b;
		G[a - 1].push_back(b - 1);
		G[b - 1].push_back(a - 1);
	}
	VI distF(N, -1);
	VI distS(N, -1);
	dfs(0, -1, 0, G, distF);
	dfs(N-1, -1, 0, G, distS);
	int Fcnt = 0;
	FOR(i, 0, N) {
		if (distF[i] <= distS[i])Fcnt++;
	}

	if (Fcnt > N - Fcnt) {
		cout << "Fennec" << endl;
	}
	else cout << "Snuke" << endl;

	return 0;
}

