        }
      }
    }

    while(!Qw.empty() && Qw.front().second == cost) {
      int x = Qw.front().first;
      Qw.pop();

      if (color[x] == 1) continue;

      color[x] = -1;
      for (auto node: T[x]) {
        if (color[node] == 0) {
          Qw.push({node, cost + 1});
          color[node] = -1;
          white++;
        }
      }
    }
    cost++;
  }

