VI depth1(100000, LINF);
VI depth2(100000, LINF);

void bfs(int N,int start){

	VI &depth = ((start == 0)?depth1:depth2);
	VB visit(N,true);
	queue<int> q;
	q.push(start);
	depth[start] = 0;
	visit[0] = false;
	visit[N - 1] = false;

	while(!q.empty()){
		int from = q.front();
		q.pop();
		REP(i, edge[from].size()) {
			int to = edge[from][i];
			if(visit[to]){
				visit[to] = false;
				depth[to] = depth[from] + 1;
				q.push(to);
			}
		}	
	}
	return;
}

