ll dist[100001];

void Dijkstra(int s) {
	priority_queue<P, vector<P>, greater<P> > que;
	fill(dist, dist + N, LLONG_MAX / 3);
	dist[0] = 0;
	que.push(P(0, s));

	while(!que.empty()) {
		P p = que.top(); que.pop();
		int v = p.second;
		if(dist[v] < p.first) continue;
		for(int i = 0; i < G[v].size(); ++i) {
			edge e = G[v][i];
			if(dist[e.to] > dist[v] + e.cost) {
				dist[e.to] = dist[v] + e.cost;
				que.push(P(dist[e.to], e.to));
			}
		}
	}
}

int solve() {
	int res = 0;
	FOR(i, 1, N) {
		if(dist[i] < 100000) ++res;
	}
	return res;
}

