void Calc() {
  int n = in;
  vector<vector<int>> edge(n);
  rep(i, n - 1) {
    int a = in;
    int b = in;
    a--, b--;
    edge[a].push_back(b);
    edge[b].push_back(a);
  }

  vector<int> path;
  auto dfs = [&](auto &dfs, int i, int pre) {
    path.push_back(i);
    if (n - 1 == i) return true;
    for (auto& j : edge[i]) {
      if (j == pre) continue;
      if (dfs(dfs, j, i)) return true;
    }
    path.pop_back();
    return false;
  };

  dfs(dfs, 0, -1);
  err(path);
  int k = path.size() / 2;
  int a = k + path.size() % 2;
  int b = k;
  vector<int> check(n);
  auto dfs2 = [&](auto& dfs, int i, int pre) ->int {
    int ans = 1;
    for (auto& j : edge[i]) {
      if (j == pre) continue;
      if (check[j]) continue;
      ans += dfs(dfs, j, i);
    }
    return ans;
  };
  rep(i, a, path.size()) check[path[i]] = 1;
  err(check);
  int suma = dfs2(dfs2, 0, -1);
  check.resize(n);
  rep(i, 0, a) check[path[i]] = 1;
  err(check);
  int sumb = dfs2(dfs2, n - 1, -1);
  err(a, b, suma, sumb);
  if (suma < sumb) {
    cout << ("Snuke") << endl;
  }
  else {
    cout << ("Fennec") << endl;
  }


}

