set<int> shortest_path(auto G, auto s, auto g) {
  vector<int> p(G.size(), -1);
  function<void(int)> dfs = [&](int v) {
    for(auto nex: G[v]) if(p[nex]==-1) {
      p[nex] = v;
      dfs(nex);
    }
  };

  p[0] = 0;
  dfs(0);

  set<int> V;
  V.emplace(0);
  for(auto v = g; v != 0; v = p[v]) V.emplace(v);
  return V;
}

bool check() {
  int N;
  cin >> N;

  vector<vector<int>> G(N);
  for(auto i = 1; i < N; ++i) {
    int a, b;
    cin >> a >> b;
    --a; --b;
    G[a].emplace_back(b);
    G[b].emplace_back(a);
  }

  auto path = shortest_path(G, 0, N-1);
  vector<int> color(N, -1);
  vector<deque<int>> q(2);
  q[0].emplace_front(0);
  q[1].emplace_front(N-1);
  for(auto turn = 0; !q[0].empty() || !q[1].empty(); turn ^= 1) {
    if(q[turn].empty()) continue;
    auto v = q[turn].front();
    q[turn].pop_front();
    if(color[v] != -1) {turn ^= 1; continue;}
    color[v] = turn;
    for(auto nex: G[v]) if(color[nex] == -1) {
      if(path.count(nex)) q[turn].emplace_front(nex);
      else                q[turn].emplace_back(nex);
    }
  }

  vector<int> n(2);
  for(auto i: color) ++n[i];
  return n[0] > n[1];
}

int main() {
  cout << (check() ? "Fennec" : "Snuke") << endl;
}

