void solve() {
  int n; cin >> n;
  vector<vi32> edges(n);
  rep(i, n - 1) {
    int a, b; cin >> a >> b;
    a--, b--;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }

  vector<bool> seen(n);

  vi32 cnt(2, -1);
  queue<int> q[2];
  q[0].push(0), q[1].push(n - 1);

  auto bfs = [&](queue<int> &q, int t) {
    if (q.size() == 0) return;

    int v = q.front(); q.pop();
    if (seen[v]) return;
    seen[v] = true;
    cnt[t]++;

    each(u, edges[v]) {
      if (seen[u]) continue;
      q.push(u);
    }
  };

  while (!q[0].empty() || !q[1].empty()) {
    bfs(q[0], 0), bfs(q[1], 1);
  }
  if (cnt[0] <= cnt[1]) no(); yes();
}

