  int a, b;
  for(int i = 0; i < N-1; i++){
    cin >> a >> b;
    a--;
    b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  vector<int> dist_f(N);
  queue<int> q;
  for(int i = 0; i < N; i++){
    dist_f[i] = -1;
  }
  dist_f[0] = 0;
  q.push(0);

  while(!q.empty()){
    int v = q.front();
    q.pop();

    for(auto nv : G[v]){
      if(dist_f[nv] >= 0) continue;

      dist_f[nv] = dist_f[v] + 1;
      q.push(nv);
    }
  }

  vector<int> dist_s(N);
  for(int i = 0; i < N; i++){
    dist_s[i] = -1;
  }
  dist_s[N-1] = 0;
  q.push(N-1);

  while(!q.empty()){
    int v = q.front();
    q.pop();

    for(auto nv : G[v]){
      if(dist_s[nv] >= 0) continue;

      dist_s[nv] = dist_s[v] + 1;
      q.push(nv);
    }
  }

  int dist_f_s = dist_f[N-1];
  int check = -1;
  for(int i = 0; i < N; i++){
    if(dist_f[i] == dist_f_s/2 + 1 && dist_s[i] == (dist_f_s - dist_f_s/2 - 1)){
      check = i;
    }
  }

  vector<int> dist_ans(N);
  for(int i = 0; i < N; i++){
    dist_ans[i] = -1;
  }

  dist_ans[check] = 0;

  dist_ans[0] = 0;
  q.push(0);

  while(!q.empty()){
    int v = q.front();
    q.pop();

    for(auto nv : G[v]){

      if(dist_ans[nv] >= 0) continue;

      dist_ans[nv] = dist_ans[v] + 1;
      q.push(nv);
    }
  }

  int ans = 0;
  for(int i = 0; i < N; i++){
    if(dist_ans[i] >= 0){
      ans++;
    }
  }

  ans--;


  if(ans * 2 <= N){
    cout << "Snuke" << endl;
  }else{
    cout << "Fennec" << endl;
  }

  return 0;
}

