bool find_path(int index){
    if(visited[index]) return false;
    if(index == 0){
        path.push_back(0);
        return true;
    }
    visited[index] = true;
    bool ret = false;
    for(int next : adj[index]){
        if(find_path(next)){
            ret = true;
            path.push_back(index);
        }
    }
    return ret;
}

