void calc_parent(ll v, vector<ll>& parent, const vector<vector<Edge>>& graph) {
	for (Edge e : graph[v]) {
		if (parent[e.to] == -1) {
			parent[e.to] = v;
			calc_parent(e.to, parent, graph);
		}
	}
}

void visit(ll v, const vector<vector<Edge>>& graph, vector<bool>& visited) {
	visited[v] = true;
	for (Edge e : graph[v]) {
		if (!visited[e.to]) {
			visit(e.to, graph, visited);
		}
	}
}

int main() {
	ll N;
	cin >> N;
	vector<vector<Edge>> graph(N);
	rep(i,0,N-1) {
		ll A, B;
		cin >> A >> B;
		A--;
		B--;
		graph[A].push_back({A, B});
		graph[B].push_back({B, A});
	}
	vector<ll> parent(N, -1);
	calc_parent(0, parent, graph);
	vector<ll> path;
	ll v = N-1;
	while (v != 0) {
		path.push_back(v);
		v = parent[v];
	}
	path.push_back(0);
	reverse(path.begin(), path.end());
	ll f_root = path[path.size()/2+path.size()%2-1];
	ll s_root = path[path.size()/2+path.size()%2];
	// cout << f_root << endl;
	// cout << s_root << endl;
	for (auto it = graph[f_root].begin(); it != graph[f_root].end(); ++it) {
		if (it->to == s_root) {
			graph[f_root].erase(it);
			break;
		}
	}
	for (auto it = graph[s_root].begin(); it != graph[s_root].end(); ++it) {
		if (it->to == f_root) {
			graph[s_root].erase(it);
			break;
		}
	}
	vector<bool> visited(N);
	visit(s_root, graph, visited);
	ll s_cnt = 0;
	rep(i,0,N) {
		if (visited[i]) {
			s_cnt++;
		}
	}
	ll f_cnt = N - s_cnt;
	if (f_cnt > s_cnt) {
		cout << "Fennec" << endl;
	} else {
		cout << "Snuke" << endl;
	}
}

