	for(int i=0;i<N;i++){
		string s = color[i];
		if(s=="")continue;
		Q.push(i);
		while(Q.size()!=0){
			int from = Q.front();
			Q.pop();
			for(int j=0;j<E[from].size();j++){
				int to = E[from][j];
				if(color[to]!="")continue;
				color[to]=s;
				Q.push(to);
			}
		}
	}

	int b=0,w=0;

	for(int i=0;i<N;i++){
		assert(color[i]!="");
