typedef long long ll;


vector<ll> d(ll n,ll from,  vector<vector<ll> > tree){
  vector<ll> res(n);
  queue<ll> que;
  que.push(from);
  ll dist = 0;
  while(!que.empty()){
    ll top = que.front();
    que.pop();
    dist++;
    // cout << top << endl;
    for(ll i = 0;i < tree[top].size(); i++){
      if(res[tree[top][i]] == 0){
        res[tree[top][i]] = res[top] + 1;
        que.push(tree[top][i]);
      }
    }
  }
  return res;
}

int solve() {
  ll n;
  cin >> n;
  vector<vector<ll> > tree(n);
  vector<ll> a(n - 1);
  vector<ll> b(n - 1);
  for(ll i = 0; i < n - 1; i++){
    ll a,b;
    cin >> a >> b;
    a--;
    b--;
    tree[a].push_back(b);
    tree[b].push_back(a);
  }
  vector<ll> f(n),s(n);
  f = d(n, 0, tree);
  s = d(n, n - 1, tree);
  f[0] = 0;
  s[n - 1] = 0;
  ll sum = 0;
  for(ll i = 0;i < n; i++){
    if(f[i] > s[i]){
      sum++;
    }else{
      sum--;
    }
  }
  if(sum < 0){
    cout << "Fennec" << endl;
  }else{
    cout << "Snuke" << endl;
  }
  return 0;
}


int main(void){
  solve();
  return 0;
}

