int bfs(int start, int goal) {
  vector<bool> visited = vector<bool>(n + 1, false);
  queue<int> q;
  visited[start] = true;
  q.push(start);
  int cnt = 0;
  while (!q.empty()) {
    int u = q.front();
    q.pop();
    for (auto v: edge[u]) {
      if (visited[v]) {
        continue;
      }
      if (v == goal) {
        continue;
      }
      visited[v] = true;
      cnt++;
      q.push(v);
    }
  }
  return cnt;
}

