    for(auto iter:ab){
        if(iter.first == index[index.size()-1] && std::find(index.begin(), index.end(), iter.second) == index.end()){
            distMap[iter.second] = distMap[iter.first]+1;
            auto tmp = index;
            tmp.push_back(iter.second);
            distMap = check(tmp, distMap);
        }
        if(iter.second == index[index.size()-1] && std::find(index.begin(), index.end(), iter.first) == index.end()){
            distMap[iter.first] = distMap[iter.second]+1;
            auto tmp = index;
            tmp.push_back(iter.first);
            distMap = check(tmp, distMap);
        }
    }
    return distMap;
}

