	tree* RIGHT=NULL;	
}tree;

void add_node(tree a[],int node1,int node2)
{
        if(a[node1].UP==NULL)        {a[node1].UP=&a[node2];a[node2].DOWN=&a[node1];}
	else if(a[node1].DOWN==NULL) {a[node1].DOWN=&a[node2];a[node2].UP=&a[node1];}
	else if(a[node1].LEFT==NULL) {a[node1].LEFT=&a[node2];a[node2].RIGHT=&a[node1];}
	else if(a[node1].RIGHT==NULL){a[node1].RIGHT=&a[node2];a[node2].LEFT=&a[node1];}
	else cout<<"木が足りません！"<<endl;
}
ll num;
void dfs(tree a,ll terget)
{
	static ll distance;
	if(a.color==terget){num=distance;distance=0;return ;}
	distance++;
	if(a.UP!=NULL&&a.UP->visit==false){/*cout<<"U"<<endl;*/a.UP->visit=true;dfs(*a.UP,terget);}
	if(a.LEFT!=NULL&&a.LEFT->visit==false){/*cout<<"L"<<endl;*/a.LEFT->visit=true;dfs(*a.LEFT,terget);}
	if(a.RIGHT!=NULL&&a.RIGHT->visit==false){/*cout<<"R"<<endl;*/a.RIGHT->visit=true;dfs(*a.RIGHT,terget);}
	if(a.DOWN!=NULL&&a.DOWN->visit==false){/*cout<<"D"<<endl;*/a.DOWN->visit=true;dfs(*a.DOWN,terget);}
	return ;
}
