        int a, b; cin >> a >> b; a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }  

    //bfs＆経路復元
    queue<int> que; que.push(0);
    vector<int> d(n, INF); d[0] = 0;
    vector<int> prev(n); prev[0] = -1;
    while(!que.empty()){
        int v = que.front(); que.pop();
        for(int e: G[v]){
