            for(int e: G[v]){
                if(color[e] != 0) continue;
                color[e] = color[i];
                color[i] == 1 ? black++ : white++ ;
                que.push(e);
            }
        }
    }
    //cout<< "black:" << black << " white:" << white << ln;
    cout << (black >= white ? "Fennec" : "Snuke") << ln;
}

