  function<void(int, int)> func = [&](int uu, int before){
    if(uu == N-1) fs.at(uu) = true;

    for(int i = 0; i < G.at(uu).size(); i++){
      int next = G.at(uu).at(i);
      if(next == before) continue;
      func(next, uu);
      if(fs.at(next)) fs.at(uu) = true;
    }
  };

  func(0, 0);

  queue<int> fque1, fque2, sque1, sque2;
  fque1.push(0); sque1.push(N-1);

  while(true){
