      if(color.at(v) != -1) continue;
      color.at(v) = 0;
      for(int i = 0; i < G.at(v).size(); i++){
        int next = G.at(v).at(i);
        if(color.at(next) != -1) continue;
        if(fs.at(next)) fque1.push(next);
        else fque2.push(next);
      }
      fng = false;
      break;
    }
    while(fng && !fque2.empty()){
      int v = fque2.front(); fque2.pop();
      if(color.at(v) != -1) continue;
      color.at(v) = 1;
      for(int i = 0; i < G.at(v).size(); i++){
        int next = G.at(v).at(i);
        if(color.at(next) != -1) continue;
        if(fs.at(next)) fque1.push(next);
        else fque2.push(next);
      }
      fng = false;
      break;
    }
    if(fng){
      cout << "Snuke" << endl;
      return 0;
    }

    bool sng = true;
    while(!sque1.empty()){
      int v = sque1.front(); sque1.pop();
      if(color.at(v) != -1) continue;
      color.at(v) = 0;
      for(int i = 0; i < G.at(v).size(); i++){
        int next = G.at(v).at(i);
        if(color.at(next) != -1) continue;
        if(fs.at(next)) sque1.push(next);
        else sque2.push(next);
      }
      sng = false;
      break;
    }
    while(sng && !sque2.empty()){
      int v = sque2.front(); sque2.pop();
      if(color.at(v) != -1) continue;
      color.at(v) = 0;
      for(int i = 0; i < G.at(v).size(); i++){
