int main(){
	int n;
	std::vector<int> aList;
	std::vector<int> bList;
	std::vector<int> dist;
	std::vector<bool> isReached;
	std::vector<std::vector<int>> graph;
	std::vector<std::vector<int>> graph2;	
	std::vector<int> connect;
	std::queue<int> q;
	std::stack<int> s;

	std::cin>>n;
	aList.resize(n-1);
	bList.resize(n-1);
	isReached.resize(n, false);
	dist.resize(n,0);
	graph.resize(n);
	graph2.resize(n);
	connect.resize(n, 1);


	for(int i=0; i<n-1; i++)
		std::cin>>aList[i]>>bList[i];

	for(int i=0; i<n-1; i++){
		graph[aList[i]-1].push_back(bList[i]-1);
		graph[bList[i]-1].push_back(aList[i]-1);
	}

	isReached[0]=true;
	q.push(0);
	while(!q.empty()){
		int cur= q.front();
		q.pop();

		for(int i=0; i<graph[cur].size(); i++){
			if(isReached[graph[cur][i]])
				continue;

			dist[graph[cur][i]]= dist[cur]+1;
			isReached[graph[cur][i]]= true;
			q.push(graph[cur][i]);
		}

	}

	for(int i=0; i<n; i++)
		isReached[i]= false;

	isReached[n-1]=true;
	s.push(n-1);

	while(!s.empty()){
		int cur= s.top();

		if(cur==0)
			break;

		bool isFound=false;

		for(int i=0; i< graph[cur].size(); i++){
			if(isReached[graph[cur][i]])
				continue;

			isFound= true;
			isReached[graph[cur][i]]= true;
			s.push(graph[cur][i]);
			break;
		}

		if(!isFound)
			s.pop();
	}

	int front;
	int back;
	for(int i=0; i<s.size(); i++){
		front= s.top();
		s.pop();
	}
	back= s.top();

	if(front> back){
		int tmp= front;
		front= back;
		back= tmp;
	}


	for(int i=0; i<n; i++)
		for(int j=0; j<graph[i].size(); j++)
			if(i<graph[i][j] && !(i==front && graph[i][j]==back))
				graph2[i].push_back(graph[i][j]);


	q.push(0);
	connect[0]= 0;
	while(!q.empty()){
		int cur= q.front();
		q.pop();

		for(int i=0; i<graph2[cur].size(); i++){
			if(connect[graph2[cur][i]]== 0)
				continue;

			connect[graph2[cur][i]]= 0;
			q.push(graph2[cur][i]);
		}

	}

	int fen=0; 
	int sun=0;

	for(int i=0; i<n; i++){
		if(connect[i]==0)
			fen++;
		else
			sun++;
	}

	if(fen>sun)
		std::cout<<"Fennec"<<std::endl;
	else
		std::cout<<"Snuke"<<std::endl;


	return 0;


}

