bool dfs_path(int u, int p) {
        if (u == N) {
                path.push_back(N);
                return true;
        }

        for (auto v : T[u]) {
                if (v == p) continue;
                if (dfs_path(v,u)) {
                        path.push_back(u);
                        return true;
                }
        }

        return false;
}

int dfs_sz(int u, int p) {
        sz[u] = 1;
        for (auto v : T[u]) {
                if (v == p) continue;
                sz[u] += dfs_sz(v,u);
        }
        return sz[u];
}

