#include<bits/stdc++.h>

int distance(int start, int destination, std::vector<std::vector<int>> &v){
  int n = v.size();
  std::vector<int> d(n);
  int node = start;
  std::vector<bool> finished(n, false);
  std::vector<bool> candidate(n, false);
  std::stack<int> s;
  s.push(node);
  candidate[node] = true;
  d[node] = 0;

  while(!s.empty()){
    node = s.top();
    s.pop();
    finished[node] = true;
    candidate[node] = false;

    if(node == destination){
      break;
    }

    int num_of_children = v[node].size();
    for(int child = 0; child < num_of_children; child++){
      if(finished[v[node][child]]){
        continue;
      }
      if(candidate[v[node][child]]){
        continue;
      }
      s.push(v[node][child]);
      candidate[v[node][child]] = true;
      d[v[node][child]] = d[node] + 1;
    }
  }

  return d[destination];
}

std::vector<int> sphere(int start, int depth, std::vector<std::vector<int>> &v){
  int n = v.size();
  std::vector<int> d(n);
  std::vector<int> sphr;
  int node = start;
  std::vector<bool> finished(n, false);
  std::vector<bool> candidate(n, false);
  std::stack<int> s;
  s.push(node);
  candidate[node] = true;
  d[node] = 0;

  while(!s.empty()){
    node = s.top();
    s.pop();
    finished[node] = true;
    candidate[node] = false;

    if(d[node] == depth){
      sphr.push_back(node);
      continue;
    }

    int num_of_children = v[node].size();
    for(int child = 0; child < num_of_children; child++){
      if(finished[v[node][child]]){
        continue;
      }
      if(candidate[v[node][child]]){
        continue;
      }
      s.push(v[node][child]);
      candidate[v[node][child]] = true;
      d[v[node][child]] = d[node] + 1;
    }
  }

  return sphr;
}

int count(int start, std::vector<int> &gap, std::vector<std::vector<int>> &v){
  int n = v.size();
  int node = start;
  std::vector<bool> finished(n, false);
  for(int i : gap){
    finished[i] = true;
  }
  std::vector<bool> candidate(n, false);
  std::stack<int> s;
  s.push(node);
  candidate[node] = true;

  while(!s.empty()){
    node = s.top();
    s.pop();
    finished[node] = true;
    candidate[node] = false;


    int num_of_children = v[node].size();    
    for(int child = 0; child < num_of_children; child++){
      if(finished[v[node][child]]){
        continue;
      }
      if(candidate[v[node][child]]){
        continue;
      }
      s.push(v[node][child]);
      candidate[v[node][child]] = true;
    }
  }

  int count = 0;
  for(int i = 0; i < n; i++){
    if(finished[i]) count++;
  }
  count -= gap.size();

  return count;
}

int main(){
  int n;
  std::cin >> n;
  std::vector<std::vector<int>> v(n);
  int a, b;
  for(int i = 0; i < n - 1; i++){
    std::cin >> a >> b;
    v[a - 1].push_back(b - 1);
    v[b - 1].push_back(a - 1);
  }

  int d = distance(0, n - 1, v);
  std::vector<int> gap = sphere(0, d / 2, v);
  int white = count(n - 1, gap, v);
  if(white >= n - white){
    std::cout << "Snuke" << '\n';
  }else{
    std::cout << "Fennec" << '\n';
  }

  return 0;
}

