        g[b].push_back(a);
    }

    vector<int> v;
    function<int(int, int, int)> dfs = [&](int t, int p, int d) {
        for (int c : g[t]) {
            if (c == p) continue;
            if (c == n - 1) {
                v.push_back(c);
                return d;
            }
            int r = dfs(c, t, d + 1);
            if (r > 0) {
                v.push_back(c);
                return r;
            }
        }
        return -1;
    };

