int main() {        
    int n;
    cin >> n;
    unordered_map<int, vector<int>> um;
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        um[a].push_back(b);
        um[b].push_back(a);
    }
    vector<int> last(n + 1, -1);
    vector<int> v(1, 1);
    last[1] = 1;
    while (v.size() > 0) {
        int index = v.back();
        v.pop_back();
        if (index == n) break;
        for (auto next : um[index]) {
            if (last[next] == -1 ) {
                last[next] = index;
                v.push_back(next);
            }
        }
    }
    vector<int> colored(1, n);
    int node = n;
    while (node != 1) {
        node = last[node];
        colored.push_back(node);
    }
    int s = colored.size();
    vector<int> res(n + 1, 0);
    v.clear();
    for (int i = 0; i < s / 2; i++) {
        res[colored[i]] = -1;
    }
    for (int i = s / 2; i < s; i++) {
        res[colored[i]] = 1;
        v.push_back(colored[i]);
    }
    while (v.size() > 0) {
        int index = v.back();
        v.pop_back();
        for (auto next : um[index]) {
            if (res[next] == 0) {
                res[next] = 1;
                v.push_back(next);
            }
        }
    }
    int c = 0;
    for (int i = 1; i <= n; i++) {
        if (res[i] == 1) c++;
    }
    if (c * 2 > n) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
}

