vi dijkstra(int start)
{
  vi ret(n, inf);
  ret[start] = 0;
  pqg<pii> que;
  que.em(0, start);

  while (!que.empty()) {
    pii p = que.top(); que.pop();

    int d = p.fi, v = p.se;
    if (ret[v] < d) continue;

    for (auto to : edge[v]) {
      if (ret[to] > d + 1) {
        ret[to] = d + 1;
        que.em(d + 1, to);
      }
    }
  }

  return ret;
}

