    ed[cnt].to = v;
    ed[cnt].next = head[u];
    head[u] = cnt++;
}

int sz[MAXN], fa[MAXN], dep[MAXN];
void dfs(int u, int pre) {
    sz[u] = 1;
    dep[u] = dep[pre] + 1;
    fa[u] = pre;
    for ( int i = head[u]; i != -1; i = ed[i].next ) {
        int v = ed[i].to;
        if ( v != pre ) {
            dfs(v, u);
            sz[u] += sz[v];
        }
    }
}

