struct Node {
  // std::set<int> out;
  // std::set<int> in;
  std::vector<int> neighbor;
};

using Tree = std::vector<Node>;

std::vector<int> bfs(Tree& tree, int from, int dst, std::vector<bool>& visited) {
  std::queue<std::vector<int>> q;
  q.push({from});
  while (q.size() > 0) {
    std::vector<int>& route = q.front();
    for (auto n : tree[route.back()].neighbor) {
      if (visited[n])
        continue;
      std::vector<int> next = route;
      next.push_back(n);
      if (n == dst)
        return next;
      q.emplace(std::move(next));
    }
    q.pop();
  }
  return {};
}

int counts(Tree& tree, int v, std::vector<bool>& visited) {
  int sum = 1;
  for (int a : tree[v].neighbor) {
    if (visited[a])
      continue;
    visited[a] = true;
    sum += counts(tree, a, visited);
  }
  return sum;
}

void erase(std::vector<int>& v, int num) {
  for (auto it = v.begin(); it < v.end(); it++) {
    if (*it == num) {
      v.erase(it);
      return;
    }
  }
}

