        a--;b--;
        E[a].pb(b);
        E[b].pb(a);
    }
    vector<pii> C(N, {-1,-1});
    queue<int> q1, q2;
    q1.push(0);
    while(!q1.empty()){
        auto f = q1.front(); q1.pop();
        REPA(c, E[f]){
            if(C[c].fi==-1){
                C[c].fi = C[f].fi + 1;
                q1.push(c);
            }
        }
    }
    q2.push(N-1);
    while(!q2.empty()){
        auto f = q2.front(); q2.pop();
        REPA(c, E[f]){
            if(C[c].se==-1){
                C[c].se = C[f].se + 1;
                q2.push(c);
            }
        }
    }

    int f = 0, s = 0;
    REPA(ci,C){
        if(ci.fi==ci.se) continue;
        else if(ci.fi < ci.se) f++;
        else s++;
    }
    if(f>=s) pr("Fennec");
    else pr("Snuke");
}

