        int v = Q.front().first;
        vector<int> Pa = Q.front().second; Q.pop();
        //cout << v << endl;
        for(auto u : V[v]){
            //cout << " " << u << endl;
            if(!grid[u]){
                grid[u] = true;
                if(u == N-1){
                    path = Pa;
                    continue;
                }
                vector<int> temp = Pa; temp.push_back(u);
                Q.push(make_pair(u, temp));
                count++;
            }
        }
    }
    memset(grid, false, sizeof(grid));
    for(auto p : path) grid[p] = true;
    grid[0] = grid[N-1] = true;
    vector<ll> Pnum(path.size());

    if(path.size() > 0){
        for(int i = 0; i < path.size(); i++){
            int p = path[i];
            queue<int> q; q.push(p);
            while(!q.empty()){
                int v = q.front(); q.pop();Pnum[i]++;
                for(auto u : V[v]){
                    if(!grid[u]){q.push(u);grid[u] = true;}
                }
            }
        }
    }




    ll b = count;
    for(int i = 0; i < path.size()/2; i++) b -= Pnum[path.size()-1-i];

    ll w = N - b;
