  for(int i=0; i<N; i++){
    if(d1[i] <= dN[i])
      Fennec++;
    else
      Snuke++;
  }
  if(Fennec > Snuke)
    cout << "Fennec" << endl;
  else
    cout << "Snuke" << endl;
  return 0;
}

