class Tree{
private:
    int N;
    vector<vector<int>> depth;
    map<int,vector<int>> mp;
    pair<int,int> counter;

public:
    Tree(int n) : N(n), depth(2, vector<int>(n,0)), counter({0,0}){}

    void setlist(int a, int b){
        mp[a].push_back(b);
    }

    void dfs(int var, int par, int cost, int pl){
        depth[pl][var] = cost;
        for(auto i : mp[var]){
            if(i == par){
                continue;
            }
            dfs(i, var, cost + 1, pl);
        }
    }

    string result(){
        for(int i=0; i<N; i++){
            if(depth[0][i] <= depth[1][i]){
                counter.first++;
            }else{
                counter.second++;
            }
        }
        if(counter.first > counter.second){
            return "Fennec";
        }else{
            return "Snuke";
        }
    }

};

