struct C {
    ll N_{};
    vector<pair<ll, ll>> v_{};
    vector<vector<ll>> map_{};
    vector<vector<ll>> t_{};
    vector<ll> num_children_{};
    vector<ll> path_to_N_{};
    bool path_creation_finished_ = false;

    // visit cur from previous prev, count returns # of nodes including cur
    ll dfs(ll prev, ll cur) {
        ll count = 0;
        t_[prev].emplace_back(cur);
        if (!path_creation_finished_) {
            path_to_N_.emplace_back(cur);
            if (cur == N_) {
                path_creation_finished_ = true;
            }
        }
        ll childs{};
        for(ll next : map_[cur]) {
           if (next != prev) {
               count += dfs(cur, next);
           }
        }
        num_children_[cur] = count;
        count++;
        if (!path_creation_finished_) {
            path_to_N_.pop_back();
        }
        return count;
    }
    explicit C(vector<pair<ll, ll>> v) : v_(move(v)){
        N_ = v_.size()+1; // number of nodes
        map_.resize(N_+1); // node number is 1-origin
        t_.resize(N_+1);
        num_children_.resize(N_+1);
        for(auto p : v_) {
            map_[p.first].emplace_back(p.second);
            map_[p.second].emplace_back(p.first);
        }
        dfs(0, 1);
    }
    // true if Feneck wins
    bool resolve() {
        ll L = path_to_N_.size();
        ll sunuke_last_position = path_to_N_[(L+1)/2];
        ll sunukes = 1+num_children_[sunuke_last_position];
        ll fenecks = N_ - sunukes;
        return fenecks > sunukes;
    }
};

