class Node {
public:
  std::vector<int> neighbor;
};

int action(std::vector<int>* coloring, int man, int now,
            std::vector<Node>& graph) {
  int max = 0;
  int maxidx = -1;
  for (int node : graph[now].neighbor) {
    if ((*coloring)[node] != 0)
      continue;
    if ((int)graph[node].neighbor.size() > max) {
      max = (int)graph[node].neighbor.size();
      maxidx = node;
    }
  }
  if (maxidx < 0)
    return -1;
  (*coloring)[maxidx] = man;
  return maxidx;
}

bool check(std::vector<Node>& graph, const int& n) {
  int f_now = 1;
  int s_now = n;
  std::vector<int> coloring(n + 1, 0);
  coloring[1] = -1;
  coloring[n] = 1;
  while(1) {
    f_now = action(&coloring, -1, f_now, graph);
    if (f_now < 0) 
      return false;
    s_now = action(&coloring, 1, s_now, graph);
    if (s_now < 0)
      return true;
  }
}

