    odfs(-1,0,0);
    ndfs(-1,N-1,0);
    int ans=0;
    REP(i,N){
        if(oned[i]<=nd[i])ans++;
        else ans--;
    }
    cout<<(ans>0?"Fennec":"Snuke")<<endl;
}

