void dijkstra(int start, vector<int> &costs,
              unordered_map<int, vector<int>> &edges) {
  priority_queue<pair<int, int>, vector<pair<int, int>>,
                 greater<pair<int, int>>>
      q;
  costs[start] = 0;
  q.push(make_pair(0, start));
  while (!q.empty()) {
    auto v = q.top();
    q.pop();
    for (const auto &e : edges[v.second]) {
      if (v.first + 1 < costs[e]) {
        costs[e] = v.first + 1;
        q.push(make_pair(costs[e], e));
      }
    }
  }
}

