    for (int i = 1; i < n; i++){
        cin >> a >> b;
        a--; b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    dfs(0);
    int g = (ranks[n - 1] + 2) / 2;
    int s = n - 1;
    while (ranks[s] > g) s = parent[s];
    if (num[s] * 2 >= n) cout << "Snuke" << endl;
    else cout << "Fennec" << endl;
}

