using namespace std;
int par[100010];
int urank[100010];

void init(int n){
   for(int i=0;i<n;i++){
      par[i]=i;
      urank[i]=0;
   }
}
int find(int x){
   if(par[x]==x)return x;
   else return par[x]=find(par[x]);
}
void unite(int x,int y){
   x=find(x);
   y=find(y);
   if(x==y)return ;
   if(urank[x]<urank[y])par[x]=y;
   else {
      par[y]=x;
      if(urank[x]==urank[y])urank[x]++;
   }
}
bool same(int x,int y){
   return find(x)==find(y);
}

int main(){
    int n;
    cin>>n;
    init(n);

    vector<int> a(n-1),b(n-1);
    for(int i=0;i<n-1;i++){
        cin>>a[i]>>b[i];
        a[i]--;b[i]--;
        if(a[i]!=n-1 && b[i]!=n-1)unite(a[i],b[i]);
    }
    int cnt=0;
    for(int i=0;i<n;i++){
        if(same(0,i))cnt++;
    }
    if(cnt>=(n+1)/2)cout<<"Fennec"<<endl;
    else cout<<"Snuke"<<endl;
}

