int dfs(vvi &root, int pos, int color, pii dis, vi &checked){
  if(color && dis.first == pos) return 1;
  if(!color && dis.second == pos) return 1;
  int ans = 1;
  for(int a : root[pos]){
    if(!checked[a]){
      checked[a] = 1;
      ans += dfs(root, a, color, dis, checked);
      checked[a] = 0;
    }
  }
  return ans;
}
