void dfs(const graph &g,vector<int> &v, int s,int parent,vector<int> &P,vector<int> &d){
  for(auto nx:g[s]){
    if(nx==parent)continue;
    P[nx]=s;
    d[nx]=d[s]+1;
    dfs(g,v,nx,s,P,d);
    v[s]+=v[nx];
  }
  v[s]++;
}

