void dfs(int c,int depth,vector<vector<int> >& tree, vector<int>& memo){
	if(memo[c] != -1) return;
	memo[c] = depth;

	for(int i=0;i<tree[c].size();++i){
		int next = tree[c][i];
		dfs(next,depth+1,tree,memo);
	}
}


