void dfs(int x,vector<vector<ll>> &graph, vector<ll> &vec, int count = 0){
    vec[x] = count;
    for(auto next : graph[x]){
        if(vec[next] == INT_MAX) dfs(next, graph, vec, count+1);
    }
}

