int N;

struct Node{
    ll cost;
    int parent;  // index of parent node
    int index;   // index in node list
    vector< ll > connect;
};

int reach[100001];
ll cnt = 0;    

void dfs(vector<Node> &node, int index, vector<int> &route){

    cnt ++;
    reach[index] = 1;
    route.push_back(index);

    if(index == N - 1){
        return ;
    }

    for(int i = 0; i < node[index].connect.size(); i++){
        int next_index = node[index].connect[i];
        if(reach[next_index] == 0){
            dfs(node, next_index, route);
        }
    }

    route.pop_back();
}


int main(){

    cin >> N;

    vector<Node> node(N);
    for(int i = 0; i < N; i++){
        node[i].cost = 0;
        node[i].parent = -1;
        node[i].index = i;
    }
    for(int i = 0; i < N-1; i++){
        ll a, b;
        cin >> a >> b ;
        a --;
        b --;
        node[a].connect.push_back(b);
        node[b].connect.push_back(a);
    }

    vector<int> route;
    dfs(node, 0, route);

    // reset
    cnt = 0;
    for(int i = 0; i < N; i++){
        reach[i] = 0;
    }

    int id = (route.size() + 1) / 2;
    reach[ route[id] ] = 1;
    dfs(node, 0, route);

    if(cnt > N - cnt){
        cout << "Fennec" << endl;
    }
    else{
        cout << "Snuke" << endl;
    }

}

