bool path(int i, int d) {
  color[i] = 1;
  if(i == d) {
    p.push_back(d);
    return true;
  }
  bool found = false;
  for(int n: al[i]) {
    if(color[n] != -1) continue;
    if(path(n, d)) {
      found = true;
      p.push_back(i);
    }
  }
  return found;
}

int s(int i) {
  color[i] = 1;
  int res = 1;
  for(int n: al[i]) {
    if(color[n] != -1) continue;
    res += s(n);
  }
  return res;
}

int main () {
  int n;
  cin >> n;

  al = vector<vector<int>>(n, vector<int>(0));
  rep(i,n-1) {
    int s,t;
    scanf("%d %d", &s, &t);
    al[s-1].push_back(t-1);
    al[t-1].push_back(s-1);
  }

  color = vector<int>(n, -1);
  path(0, n-1);


  fill(color.begin(), color.end(), -1);
  for(int i : p) color[i] = 1;
  int l = p.size();
  vector<int> score(l, 0);
  rep(i,l) score[i] = s(p[i]);

  int fs = 0, ss = 0;
  rep(i,(l+1)/2) {
    ss += score[i];
  }
  for(int i = l-1; i >= l / 2; i--) {
    fs += score[i];
  }

  if(fs > ss) {
    printf("Fennec\n");
  } else {
    printf("Snuke\n");
  }

  return 0;
}

