using namespace std;
const int maxn=200010;
int head[maxn],tot;
struct edge
{
	int to,next;	
}e[2*maxn];
void init()
{
	memset(head,-1,sizeof(head));
	tot=0;
}
void addedge(int u,int v)
{
	e[tot].to=v;
	e[tot].next=head[u];
	head[u]=tot++;
} 
int n,ans1,ans2;
int c[maxn];
int dfs(int u,int fa)
{
	if(u==n)	return 0;
	for(int i=head[u];i!=-1;i=e[i].next)
	{
		if(e[i].to==fa)	continue;
		int ret=dfs(e[i].to,u);
		if(ret>=0)
		{
			c[u]=true;
			return ret+1;
		}
	}
	return -1;
}
void dfs1(int u,int fa,int cnt)
{
	if(u==n||cnt==0)	return ;
	for(int i=head[u];i!=-1;i=e[i].next)
	{
		if(e[i].to==fa)	continue;
		if(c[e[i].to]==1)
		{
			c[e[i].to]=1;
			dfs1(e[i].to,u,cnt-1)	;	
		}
	}
}
void dfs2(int u,int fa,int cnt)
{
	if(u==1||cnt==0)	return ;
	for(int i=head[u];i!=-1;i=e[i].next)
	{
		if(e[i].to==fa)	continue;
		if(c[e[i].to]==1)
		{
			c[e[i].to]=0;
			dfs2(e[i].to,u,cnt-1);		
		}
	}
}
void dfs3(int u,int fa)
{
	ans1++;
	for(int i=head[u];i!=-1;i=e[i].next)
	{
		int v=e[i].to;
	//	cout<<v<<endl;
		if(v==fa)	continue ;
		if(c[v]!=0)
			dfs3(v,u);
	}
}
void dfs4(int u,int fa)
{
	ans2++;
	for(int i=head[u];i!=-1;i=e[i].next)
	{
		int v=e[i].to;
		if(v==fa)	continue ;
		if(c[v]!=1)
			dfs4(v,u);
	}
}
int main()
{
	while(scanf("%d",&n)!=EOF)
	{
		init();
		ans1=0;
		ans2=0;
		memset(c,-1,sizeof(c));
		for(int i=1;i<n;i++)
		{
			int u,v;
			scanf("%d%d",&u,&v);
			addedge(u,v);
			addedge(v,u);
		}
		int ans = dfs(1,-1)-1;
		int a=ans/2,b=ans/2;
		if(ans%2==1)
		{
			a+=1;
		}
		c[1]=1;
		c[n]=0;
		dfs1(1,-1,a);
		dfs2(n,-1,b);
		dfs3(1,-1);
		dfs4(n,-1);
		if(ans1>ans2)
		printf("Fennec\n");
		else 
		printf("Snuke\n");
	}	
	return 0;
}

