using namespace std;
using ll = long long;

int main() {
  ll N, a, b;
  cin >> N;
  vector<vector<ll>> edge(N, vector<ll>());
  for (ll i = 0; i < N - 1; ++i) {
    cin >> a >> b;
    --a, --b;
    edge[a].push_back(b);
    edge[b].push_back(a);
  }

  vector<int> reached(N, 0);
  ll dist = 0;
  queue<tuple<ll, ll>> q;
  q.push(make_tuple(0, 0));
  while (!q.empty()) {
    auto cur = q.front();
    if (get<0>(cur) == N - 1) {
      dist = get<1>(cur);
      break;
    }
    q.pop();
    for (auto &&e : edge[get<0>(cur)]) {
      if (reached[e] == 0) {
        q.push(make_tuple(e, get<1>(cur) + 1));
        reached[e] = 1;
      }
    }
  }

  if (dist % 2 == 0) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }
}

