int n;
const int NMAX = 100010;
VVL tree(NMAX);
VL depth_s(NMAX), depth_g(NMAX);

void dfs(LL v, LL p, LL d,bool s){
    if (s) {
        depth_s[v] = d;
    }
    else {
        depth_g[v] = d;
    }

    for (auto&& var : tree[v]) {
        if (var == p) {
            continue;
        }
        dfs(var,v,d+1,s);
    }
}

