    dfs(n,-1,0,false);
    LL w = 0,b = 0;
    for (int i = 1; i < n+1; i++) {
        if (depth_s[i] > depth_g[i]) {
            w++;
        }
        else {
            b++;
        }
    }

    if (w > b) {
        cout << "Snuke" << endl;
    }
    else {
        cout << "Fennec" << endl;
    }
    return 0;
}

