#include <bits/stdc++.h>
using namespace std;

int main() {
	ios_base::sync_with_stdio(false);

	int n;
	cin >> n;

	vector<vector<int> > graph(n, vector<int>(0));

	for (int i = 1; i < n; i++) {
		int a, b;
		cin >> a >> b;
		a = a - 1;
		b = b - 1;
		graph.at(a).push_back(b);
		graph.at(b).push_back(a);
	}

	int last[n];
	for (int i = 0; i < n; i++) last[i] = -1;
	last[0] = 0;

	queue<int> q;
	q.push(0);


	while (!q.empty() && last[n-1] == -1) {
		int cur = q.front();
		q.pop();
		for (auto &i : graph.at(cur)) {
			if (last[i] == -1) {
				last[i] = cur;
				q.push(i);

			}
		}
	}





	int dist = 1;
	int cur = n-1;
	while (cur != 0) {
		cur = last[cur];
		dist++;
	}


	dist = dist / 2;
	int breakpoint = n-1;
	for (int i = 1; i < dist; i++) {
		breakpoint = last[breakpoint];
	}

	int start = last[breakpoint];

	queue<int> qu;
	qu.push(start);
	int found[n];
	for (int i = 0; i < n; i++) {
		found[i] = 0;
	}
	found[start] = 1;



	while (!qu.empty()) {
		int curr = qu.front();
		qu.pop();
		for (auto &i : graph.at(curr)) {
			if (found[i] == 0 && i != breakpoint) {
				found[i] = 1;
				qu.push(i);
			}
		}

	}

	int count = 0;
	for (int i = 0; i < n; i++) if (found[i] == 1) count++;

	if (count > n / 2) {
		cout << "Fennec" << endl;
	} else {
		cout << "Snuke" << endl;
	}



	return 0;

}

