        bq=bn;

        while(!wq.empty()){
            int t=wq.front();
            wq.pop();

            for(int x:map[t]){
                if(col[x]==0){
                    wn.push(x);
                    col[x]=W;
                    white++;
                }
            }
        }
        wq=wn;
    } 

    if(black>white) cout << "Fennec" << endl;
