        li a, b;
        cin >> a >> b;
        a--;
        b--;
        edges[a].pb(b);
        edges[b].pb(a);
    }
    rin{
        state[i] = -1;
    }
    queue<PI> q;
    q.push({0, 0});
    q.push({n - 1, 1});
    while (!q.empty()) {
        li now = q.front().first;
        li side = q.front().second;
        q.pop();

        if (state[now] >= 0)continue;
        state[now] = side;
