int main() {
    int N;
    cin>>N;
    for(int i=0;i<N;++i){
        DP[i] = -1;
    }
    vector<vector<int> > edge(N);
    int a, b;
    for(int i=0;i<N-1;++i){
        cin>>a>>b;
        a--;
        b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    queue<int> que;
    queue<int> numque;
    que.push(0);
    numque.push(0);
    DP[0] = 0;
    int state, num;
    while(!que.empty()){
        state = que.front();que.pop();
        num = numque.front();numque.pop();
        if(state==N-1){
            break;
        }
        for(int i=0;i<edge[state].size();++i){
            if(DP[edge[state][i]]>-1) continue;
            DP[edge[state][i]] = state;
            que.push(edge[state][i]);
            numque.push(num+1);
        }
    }
    while(!que.empty()) que.pop();
    state = N-1;
    num = 0;
    while(DP[state]!=state){
        DP1[state] = 1;
        que.push(state);
        state = DP[state];
        num++;
    }
    DP1[0] = 1;
    que.push(0);
    num++;
    for(int i=0;i<num/2;++i){
        que.pop();
    }
    int ans = 0;
    while(!que.empty()){
        state = que.front();que.pop();
        ans++;
        for(int i=0;i<edge[state].size();++i){
            if(DP1[edge[state][i]]>0) continue;
            DP1[edge[state][i]] = 1;
            que.push(edge[state][i]);
        }
    }
    if(ans>N/2) cout<<"Fennec"<<endl;
    else cout<<"Snuke"<<endl;
}

