bool dfs1(int p,int d){
    used[p] = true;
    bool ret = 0;
    if(p == n-1){
        flag[p] = true;
        return 1;
    }
    for(auto i:v[p]){
        if(!used[i]){
            ret = dfs1(i,d+1);
        }
    }
    if(ret == 1){
        dist = max(dist,d);
        flag[p] = true;
    }
    return ret;
}

bool gone[111111];
int tr;
int dfs2(int p,int d){
    gone[p]=true;
    if(flag[p] == true && d>tr){
        return 0;
    }
    int ret = 1;
    for(auto i:v[p]){
        if(!gone[i]){
            ret += dfs2(i,d+1);
        }
    }
    return ret;
}

