using namespace std;

const int SIZE = 100000+10;
vector<int> vec[SIZE];
int step[SIZE];
queue<int> que;
int N;
int size_1 = 0;
bool vis[SIZE];
int sz[SIZE];

void BFS()
{

	while( que.size() ){
		int now = que.front();que.pop();
		for(int i:vec[now]){
			if( step[i] == -1 && i!=N ){
				//printf("* %d\n",i);
				step[i] = step[now]+1;
				que.push(i);
				size_1++ ;
			}
		}
	}
}


int DFS(int now)
{
	int size = 0;
	vis[now] = true;

	for( int i:vec[now] ){
		if( !vis[i] ){
			size += DFS(i);
		}
	}
	return sz[now] = size+1;
}

int count(int fix)
{
	int now = N;
	for(int i=step[N];i>fix;i--){
		for(int next:vec[now]){
			if( step[next] == i-1 ){
				now = next;
				break;
			}
		}
	}
	return sz[now];
}

inline void init()
{
	for(int i=0;i<SIZE;i++)
		step[i] = -1,vis[i] = false;
}
int main (void)
{
	init();

	scanf("%d",&N);
	for(int i=1;i<N;i++){
		int a,b;
		scanf("%d %d",&a,&b);
		vec[a].pb(b);
		vec[b].pb(a);		
	}
	que.push(1);
	step[1] = 0;
	BFS();

	int cnt = (step[N]+1)/2;
	DFS(1);

	size_1 = sz[1] - count( cnt );

	//printf("%d\n",size_1);

	size_1 >= N/2? puts("Fennec") : puts("Snuke");

	return 0;
}





