int n;
vector<vector<int> > tree;
vector<int> color;

int main(){
    cin >> n;
    tree = vector<vector<int> >(n);
    color = vector<int>(n, 0);
    vector<int> d(n, 1e9);
    color[0] = 1;
    color[n-1] = -1;
    REP(i, 0, n-1){
        int a, b; cin >> a >> b;
        a--; b--;
        tree[a].pb(b);
        tree[b].pb(a);
    }
    queue<int> q, rq;
    q.push(0);
    d[0] = 0;
    while(!q.empty()){
        int now = q.front();
        q.pop();
        REP(i, 0, tree[now].size()){
            int next = tree[now][i];
            if(d[next] != 1e9){continue;}
            d[next] = d[now] + 1;
            q.push(next);
        }
    }
    int count = 0;
    rq.push(n-1);
    while(1){
        int now = rq.front();
        rq.pop();
        int f = 0;
        REP(i, 0, tree[now].size()){
            int next = tree[now][i];
            if(d[next] == d[now]-1){
                if(next == 0){f = 1;break;}
                rq.push(next);
                color[next] = -2;
                count++;
                break;
            }else{
                continue;
            }
        }
        if(f == 1){break;}
    }
    stack<int> s1, s2, ss1, ss2;
    int fc = 0, sc = 0;
    ss1.push(0);
    REP(i, 0, 1+(count+1)/2){
        int now = ss1.top();
        ss1.pop();
        fc++;
        color[now] = 1;
        s1.push(now);
        REP(i, 0, tree[now].size()){
            int next = tree[now][i];
            if(color[next] == -2){
                ss1.push(now);
            }
        }
    }
    ss2.push(n-1);
    count /= 2;
    REP(i, 0, 1+count){
        int now = ss2.top();
        ss2.pop();
        sc++;
        color[now] = -1;
        s2.push(now);
        REP(i, 0, tree[now].size()){
            int next = tree[now][i];
            if(color[next] == -2){
                ss2.push(now);
            }
        }
    }
    while(!s1.empty()){
        int now = s1.top();
        s1.pop();
        REP(i, 0, tree[now].size()){
            int next = tree[now][i];
            if(color[next] == 0){
                color[next] = 1;
                s1.push(next);
                fc++;
            }else{
                continue;
            }
        }
    }
    while(!s2.empty()){
        int now = s2.top();
        s2.pop();
        REP(i, 0, tree[now].size()){
            int next = tree[now][i];
            if(color[next] == 0){
                color[next] = -1;
                s2.push(next);
                sc++;
            }else{
                continue;
            }
        }
    }
    cout << fc << sc << endl;
    if(sc < fc){
        cout << "Fennec" << endl;
    }else{
        cout << "Snuke" << endl;
    }
}

#include<bits/stdc++.h>
using namespace std;
int main(){
  int N; cin >> N;
  vector<vector<int>> to(N);
  for(int i = 0; i < N-1; i++){
    int a,b; cin >> a >> b; a--; b--;
    to[a].push_back(b); to[b].push_back(a);}
  // フェネックが0,すぬけがN-1番ノードから出発する
  // 回路は木だから、フェネック←→すぬけの間の経路は一通りしかない
  //最適戦略は、上の経路上を両者とも塗り続けること
  vector<int> visited1(N,-1);
  vector<int> visited2(N,-1);

  queue<int> Q; Q.push(0); visited1[0] = 0;
  while(!Q.empty()){
    int p = Q.front(); Q.pop();
    for(int i = 0; i < to[p].size(); i++){
      int q = to[p][i];
      if( visited1[q] == -1){ continue;}
      visited1[q] = visited1[p] + 1; Q.push(q);
    }}

  Q.push(N-1); visited2[N-1] = 0;
  while(!Q.empty()){
    int p = Q.front(); Q.pop();
    for(int i = 0; i < to[p].size(); i++){
      int q = to[p][i];
      if(visited2[q] == -1){ continue;}
      visited2[q] = visited2[p]+1; Q.push(q);
    }}
   int fennec = 0; int snuke = 0;
  for(int i = 0; i < N; i++){
    if( visited1[i] < visited2[i]){ fennec++;}
    if( visited1[i] > visited2[i]){ snuke++;}
    if( visited1[i] == visited2[i]){ fennec++;}
  }
  if( fennec > snuke){ cout << "Fennec" << endl;}
  if( snuke > fennec){ cout << "Snuke" << endl;}
  if( snuke == fennec){ cout << "Snuke" << endl;}
  return 0;}

