// bfs
template<typename T>
vector<T> bfs(vvi &g, int start = 0){ 
  int N = (int)g.size();
  T INF = numeric_limits<T>::max() / 2;
  vector<T> d(N , INF);
  d[start] = 0;
  queue<int> Q;
  Q.push(start);
  while(!Q.empty()){
    int cur = Q.front(); Q.pop();
    for(auto dst : g[cur]){
      if(d[dst] != INF) continue;
      d[dst] = d[cur] + 1;
      Q.push(dst);
    }
  }
  return d;
}

void solve(){
  ini(N);
  auto g = graph(N);

  auto df = bfs<int>(g , 0);
  auto ds = bfs<int>(g , N - 1);
  trc(df);
  trc(ds);
  ll cf = 0 , cs = 0;
  rep(i , N){
    if(df[i] <= ds[i]) cf++;
    else cs++;
  }
  out(cf > cs ? "Fennec" : "Snuke");


}

