using namespace std;

vector<int> graph[100000];
enum color_e{
  NONE,
  BLACK,
  WHITE
};

color_e C[100000];

int main(){
  int N;
  cin >> N;
  for(int i=0;i<N-1;++i){
    int a,b;
    cin >> a >> b;
    graph[a-1].push_back(b-1);
    graph[b-1].push_back(a-1);
  }
  C[0] = BLACK;
  C[N-1] = WHITE;

  queue<int> qb,qw;
  qb.push(0);
  qw.push(N-1);

  while((!qb.empty())||(!qw.empty())){
    if(!qb.empty()){
      auto ub = qb.front();qb.pop();

      for(auto vb:graph[ub]){
        if(C[vb]==NONE){
          qb.push(vb);
          C[vb] = BLACK;
        }
      }
    }

    if(!qw.empty()){
      auto uw = qw.front();qw.pop();

      for(auto vw:graph[uw]){
        if(C[vw]==NONE){
          qw.push(vw);
          C[vw] = WHITE;
        }
      }
    }
  }

  int black_num = 0;
  int white_num = 0;
  for(int i=0;i<N;++i){
    if(C[i] == BLACK) black_num++;
    else if(C[i] == WHITE) white_num++;
  }

  // cout << black_num << " " << white_num << endl;
  if(black_num>white_num){
    cout << "Fennec" << endl;
  }else{
    cout << "Snuke" << endl;
  }
  return 0;
}

