int n;
vector<vector<int>> map;
vector<int> db, dw;
int main()
{
	int a, b;
	scanf("%d", &n);
	map.resize(n + 1);	db.resize(n + 1); dw.resize(n + 1);
	for (int i = 1; i < n; i++)
	{
		scanf("%d%d", &a, &b);
		map[a].push_back(b);
		map[b].push_back(a);
	}
	queue<int> goblack,gowhite;
	goblack.push(1); gowhite.push(n);
	db[1] = 1;	dw[n] = 1;
	while (!goblack.empty())
	{
		int t=goblack.front();
		goblack.pop();
		for (auto& k : map[t])
		{
			if (!db[k])
			{
				goblack.push(k);
				db[k] = db[t] + 1;
			}
		}
	}
	while (!gowhite.empty())
	{
		int t = gowhite.front();
		gowhite.pop();
		for (auto& k : map[t])
		{
			if (!dw[k])
			{
				gowhite.push(k);
				dw[k] = dw[t] + 1;
			}
		}
	}

	a = 0, b = 0;
	for (int i = 1; i <= n; i++)
	{
		if (db[i] <= dw[i]) a++;
		else b++;
	}
	printf("%s\n", a > b ? "Fennec" : "Snuke");
}

