template <typename T>
ostream &operator<<(ostream &out, const vector<T> &v)
{
    size_t last = v.size() - 1;
    for (size_t i = 0; i < v.size(); ++i)
    {
        out << v[i];
        if (i != last)
            out << " ";
    }
    return out;
}

void f(const vector<vector<int>> &edges, vector<int> &costs, int c)
{
    for (auto u : edges[c])
    {
        // int u = edges[c][i];
        if (costs[u] >= 0)
            continue;
        costs[u] = costs[c] + 1;
        f(edges, costs, u);
    }
}

