vector<int> dis(int origin) {
	vector<int> d(n,n);
	d[origin] = 0;
	priority_queue<pii, vector<pii>, greater<pii>>pq;
	vector<bool> isChecked(n);
	pq.push(make_pair(0,origin));
	while (!pq.empty()) {
		int v = pq.top().second;
		pq.pop();
		if (!isChecked[v]) {
			for (auto it = tree[v].begin(); it != tree[v].end();it++) {
				if (d[*it] > d[v] + 1) {
					d[*it] = d[v] + 1;
					pq.push(make_pair(d[*it], *it));
				}
			}

			isChecked[v] = true;
		}
	}
	return d;
}

