#define rep(i,n) for(int i=0;i<(n);i++)
using namespace std;
int n;
vector<int> t[100000]; //木
bool u[100000]; //訪れたかどうか
int p[100000]; //親ノード
int d[100000]; //深さ
int c[100000]; //塗れるマス数
int dfs(int i,int cd){ //現在地,深さ
  u[i]=true; //到達済み
  d[i]=cd; //深さ
  c[i]=1; //１マスカウント
  for(int v:t[i]){ //いけるマスでループ
    if(!u[v]){ //まだ訪れていない場合
      p[v]=i; //親を代入
      c[i]+=dfs(v,cd+1); //塗れるマス数を累積
    }
  }
  return c[i];
}
int main(){
  cin>>n;
  rep(i,n-1){
    int a,b;
    cin>>a>>b;
    t[a-1].push_back(b-1);
    t[b-1].push_back(a-1);
  }
  p[0]=-1;
  dfs(0,0);
  int k=(d[n-1]-1)/2; //snukeが接近できる回数
  int q=n-1; //snukeの現在地
  rep(i,k){ //snukeの最終到達点まで行く
    q=p[q];
  }
  int a=n-c[q]; //fennecが塗れるマス数
  int b=c[q]; //snukeが塗れるマス数
  if(a>b){ //同数ならsnukeの勝ち
    cout<<"Fennec"<<endl;
  }else{
    cout<<"Snuke"<<endl;
  }
}

