bool path(int u, int from) {
    if (u == n - 1) {
        p.insert(u);
        pa.pb(u);
        return true;
    }
    bool on = false;
    rep(i, v[u].to.size()) {
        if (v[u].to[i] == from) continue;
        on |= path(v[u].to[i], u);
    }
    if (on) p.insert(u), pa.pb(u);
    return on;
}

