    vector<ll> dist0(n, -1LL), distN(n, -1LL);
    queue<ll> Q0, QN;

    dist0[0] = 0;
    Q0.push(root0);
    while(!Q0.empty()) {

        ll v = Q0.front();
        Q0.pop();

        rep(i, to[v].size()) {

            ll u = to[v][i];

            if(dist0[u] != -1) {
                continue;
            }

            dist0[u] = dist0[v] + cost[v][i];
            Q0.push(u);
        }
    }

    distN[n-1] = 0;
    QN.push(rootN);
    while(!QN.empty()) {

        ll v = QN.front();
        QN.pop();

        rep(i, to[v].size()) {

            ll u = to[v][i];

            if(distN[u] != -1) {
                continue;
            }

            distN[u] = distN[v] + cost[v][i];
            QN.push(u);
        }
    }

    int cnt0 = 0, cntN = 0;
    rep(i, n) { 
        if(dist0[i] <= distN[i]) {
            cnt0++;
        }
        else {
            cntN++;
        }
    }

    if(cnt0 > cntN) {
        cout << "Fennec";
    }
    else {
        cout << "Snuke";
    }

    cout << endl;
    return 0;
}

