int Dist[int(1e5+5)];

int Calc_Dist(){
  fill(Dist, Dist + N + 1, -1);
  Dist[1] = 0;
  queue <int> que; que.push(1);
  while (!que.empty()){
    int Q = que.front(); que.pop();
    for (int v:Graph[Q]){
      if (Dist[v] != -1) continue;
      Dist[v] = Dist[Q] + 1;
      que.push(v);
    }
  }
  return 0;
}

bool visited[int(1e5+5)], color[int(1e5+5)];
int Solve(){
  vector <int> route;
  queue <int> que; que.push(N);
  while (!que.empty()){
    int Q = que.front(); que.pop();
    route.push_back(Q);
    for (int v:Graph[Q]){
      if (Dist[v] < Dist[Q]) que.push(v);
    }
  }

  for (int v:route){
    visited[v] = true;
    que.push(v);
    if (Dist[v] <= Dist[N] - Dist[v]) color[v] = true;
    else color[v] = false;
  }

  while (!que.empty()){
    int Q = que.front(); que.pop();
    for (int v:Graph[Q]){
      if (visited[v]) continue;
      que.push(v);
      visited[v] = true;
      color[v] = color[Q];
    }
  }

  return 0;
}


