std::map<int, int> check(int index, map<int, int> distMap, int startIndex, vector<pair<int,int>> ab){
    map<int, int> temp = distMap;
    for(int i=ab.size()-1;i>=0;i--){
        bool b = false;
        if(ab[i].first == index && temp[ab[i].second] == 0 && ab[i].second != startIndex){
            temp[ab[i].second] = temp[ab[i].first]+1;
            temp = check(ab[i].second, temp, startIndex, ab);
            b = true;
        }
        if(ab[i].second == index && temp[ab[i].first] == 0 && ab[i].first != startIndex){
            temp[ab[i].first] = temp[ab[i].second]+1;
            temp = check(ab[i].first, temp, startIndex, ab);
            b = true;
        }
        if(b)ab.erase(ab.begin()+i);
    }
    return temp;
}

