vector<pair<long long, long long> > prime_factorize(long long N) {
    vector<pair<long long, long long> > res;
    for (long long a = 2; a * a <= N; ++a) {
        if (N % a != 0) continue;
        long long ex = 0; // 指数

        // 割れる限り割り続ける
        while (N % a == 0) {
            ++ex;
            N /= a;

        }

        // その結果を push
        res.push_back({ a, ex });
    }

    // 最後に残った数について
    if (N != 1) res.push_back({ N, 1 });
    return res;
}

map<long long, set<long long>> cache;
set<long long> enum_divisors(long long N) {
    set<long long> res;
    for (long long i = 1; i * i <= N; ++i) {
        if (N % i == 0) {
            res.insert(i);

            if (cache.count(N / i) > 0) {
                auto copy = cache[N / i];
                auto copy2 = cache[N / i];
                for (auto v : res) {
                    if (v != 1) {
                        //cout << "v*" << v << endl;
                        for (auto itr = copy2.begin(); itr != copy2.end(); itr++) {
                            copy.insert(*itr * v);
                        }
                        break;
                    }
                }
                cache[N] = copy;
                return copy;
            }

            // 重複しないならば i の相方である N/i も push
            if (N / i != i) res.insert(N / i);


        }
    }

    cache[N] = res;
    return res;
}

long long euclid(long long a, long long b) {
    if (a > b) {
        long long temp = b;
        b = a;
        a = temp;
    }
    if (b % a == 0) {
        return a;
    }
    else {
        return euclid(a, b - a);
    }
}

long long gcd(long long a, long long b) {
    if (b > a) {
        long long temp = b;
        b = a;
        a = temp;
    }
    //cout << "a:" << a << "b:" << b << endl;
    long long c = a % b;
    if (c == 0) {
        return b;
    }
    else {
        return gcd(b, c);
    }
}


int N;
vector<vector<int>> graph;
void Find1toN(stack<int>& v, int pre, int from) {

    int size = graph[pre].size();
    for (int i = 0; i < size; i++) {
        if (graph[pre][i] != from) {
            v.push(graph[pre][i]);
            if (graph[pre][i] == N) {
                return;
            }

            Find1toN(v, graph[pre][i], pre);
            if (v.top() != N) {
                v.pop();
            }
            else {
                return;
            }
        }
    }
}

int GetChildrenCount(int node, int preNode, int count, int except) {
    int currentCount = count + 1;
    int size = graph[node].size();
    for (int i = 0; i < size; i++) {
        if (graph[node][i] != preNode && graph[node][i] != except) {
            currentCount = GetChildrenCount(graph[node][i], node, currentCount, -1);
        }
    }

    return currentCount;
}

int main() {
    cin >> N;

    for (int i = 0; i <= N; i++) {
        graph.push_back(vector<int>());
    }
    for (int i = 1; i <= N-1; i++) {
        int a, b;
        cin >> a >> b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    stack<int> temp;
    temp.push(1);

    Find1toN(temp, 1, -1);

    vector<int> route1toN(temp.size());
    for (int i = temp.size() - 1; i >= 0; i--) {
        route1toN[i] = temp.top();
        temp.pop();
    }

    int wIndex = route1toN.size(), bIndex = -1;
    int wCount = 0, bCount = 0;
    while (wIndex > bIndex) {

        bIndex++;
        if (wIndex > bIndex) {
            if (bCount > 0) {
                bCount += GetChildrenCount(route1toN[bIndex], route1toN[bIndex - 1], 0, route1toN[bIndex + 1]);
            }
            else {
                bCount += GetChildrenCount(route1toN[bIndex], -1, 0, route1toN[bIndex + 1]);
            }
        }


        wIndex--;
        if (wIndex > bIndex) {
            if (wIndex < route1toN.size() - 1) {
                wCount += GetChildrenCount(route1toN[wIndex], route1toN[wIndex + 1], 0, route1toN[wIndex - 1]);
            }
            else {
                wCount += GetChildrenCount(route1toN[wIndex], -1, 0, route1toN[wIndex - 1]);
            }
        }
    }


    if (wCount >= bCount) {
        cout << "Snuke" << endl;
    }
    else {
        cout << "Fennec" << endl;
    }
    return 0;
}

