bool isFirst(int n, const vector<vector<int>> &v) {

    vector<int> visited{n, 0};
    visited[0] = 1;
    visited[n - 1] = -1;

    vector<int> f1{0};
    vector<int> fN{n - 1};

    vector<int> newF1;
    vector<int> newFN;

    while (!(f1.empty() && fN.empty())) {

        newF1.clear();

        for (auto t : f1) {

            for (auto u : v[t]) {

                if (visited[u] != 0) { continue; }

                visited[u] = 1;
                newF1.push_back(u);

            }

        }

        newFN.clear();

        for (auto t: fN) {

            for (auto u : v[t]) {

                if (visited[u] != 0) { continue; }

                visited[u] = -1;
                newFN.push_back(u);

            }

        }

        swap(f1, newF1);
        swap(fN, newFN);

    }

    return accumulate(visited.begin(), visited.end(), 0) > 0;

}

