using VI = vector<long>;

VI adj[101010];
int color[101010];
int color2[101010];

void depth(int i, int d) {
    if (color[i] != -1) return;
    color[i] = d;
    for (int a: adj[i]) {
        depth(a, d + 1);
    }
}

void depth2(int i, int d) {
    if (color2[i] != -1) return;
    color2[i] = d;
    for (int a: adj[i]) {
        depth(a, d + 1);
    }
}


int initb, initw;

void c(int i, int v) {
    if (((i == 0 && v != initb) || (i == 1 && v != initw)) && color[v] != -1) return;
    color[v] = i;
    for (int a: adj[v]) {
        if (color[a] == -1) {
            c(i, a);
        }
    }
}

int main() {
    int n;
    cin >> n;

    REP(i,101010) color[i] = -1;
    REP(i,101010) color2[i] = -1;
    REP(i,n-1) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    depth(0,0);
    depth2(n-1,0);
    int d = color[n-1];
    REP(i,101010) {
        if (color[i] == d / 2 && color2[i] == d - d / 2) initb = i;
        if (color[i] == d / 2 + 1 && color2[i] == d - (d / 2 + 1)) initw = i;
    }

    REP(i,101010) color[i] = -1;
    color[initb] = 0;
    color[initw] = 1;
    c(0, initb);
    c(1, initw);

    int cntb = 0, cntw = 0;
    REP(i,101010) {
        if (color[i] == 0) cntb++;
        else if (color[i] == 1) cntw++;
    }

    if (cntb > cntw) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
}

