void dfs(int x,int all)
{
    if(flag)return;
    s1[all]=x;
    if(x==n)
    {
        tempall=all;
        flag=1;
        return;
    }
    for(int a=0; a<vec[x].size(); a++)
    {
        if(judge[vec[x][a]]&&flag==0)
        {
            judge[vec[x][a]]=false;
            dfs(vec[x][a],all+1);
            if(!flag)
            judge[vec[x][a]]=true;
        }
    }
    return ;
}
int ddfs(int x)
{
    int sum=0;
    for(int a=0;a<vec[x].size();a++)
    {
        if(judge[vec[x][a]])
        {
            sum++;
            judge[vec[x][a]]=false;
            sum+=ddfs(vec[x][a]);
        }
    }
    return sum;
}
