        {
            int tempnum=s1[a];
            for(int b=0; b<vec[tempnum].size(); b++)
            {
                if(tempall%2==0)
                if(vec[tempnum][b]!=s1[tempall/2+1])
                    continue;
                if(judge[vec[tempnum][b]])
                {
                    judge[vec[tempnum][b]]=false;
                    sum++;
                    sum+=ddfs(vec[tempnum][b]);
                }
            }
        }
        if(tempall%2)
        {
            sum++;
            int tempnum=s1[tempall/2+1];
            for(int b=0; b<vec[tempnum].size(); b++)
            {
                if(vec[tempnum][b]!=s1[tempall/2+2])
                    continue;
                if(judge[vec[tempnum][b]])
                {
                    judge[vec[tempnum][b]]=false;
                    sum++;
                    sum+=ddfs(vec[tempnum][b]);
                }
            }
        }

        if(sum>n-sum)cout<<"Fennec"<<endl;
        else cout<<"Snuke"<<endl;
    }
    return 0;
}

