    vector<int> d(N, inf);
    d[0] = 0;

    queue<int> q;
    q.push(0);

    vector<int> p(N);
    while (q.size()) {
        int from = q.front();
        q.pop();

        for (int to : g[from]) {
            if (d[to] != inf) continue;
            q.push(to);
            p[to] = from;
            d[to] = min(d[to], d[from] + 1);
        }
    }
    //for (int x : d) cerr << x << " "; cerr << endl;

    vector<int> t;
    for (int node = N - 1; ; node = p[node]) {
        t.push_back(node);
        if (!node) break;
    }
    //for (int x : t) cerr << x << " " ; cerr << endl;

    vector<int> ans(N); // 1:Fennec, 2:Snuke
    reverse(t.begin(), t.end());
    for (int i = 0; i < t.size(); i++) {
        ans[t[i]] = (i < (t.size() + 1) / 2 ? 1 : 2);
    }
    //for (int x : t) cerr << x << " " ; cerr << endl;
    //for (int x : t) cerr << ans[x] << " " ; cerr << endl;

    dfs(0, ans, g);
    dfs(N - 1, ans, g);
    //for (int x : ans) cerr << x << " " ; cerr << endl;

    int fennec = count(ans.begin(), ans.end(), 1);
    //cerr << fennec << endl;
    cout << (fennec > N - fennec ? "Fennec" : "Snuke") << endl;

    return 0;
}

