struct edge{ll to,cost;};
vector<edge> G[MAX_V];
typedef pair<ll,ll> P;
bool used[MAX_V]={};
vector<ll> prever(MAX_V,-1);
void dij(ll s){
  priority_queue<P,vector<P>,greater<P>> que;
  fill(d,d+MAX_V,INF);
  d[s]=0;
  que.push(make_pair(0,s));
  while(!que.empty()){
    P p=que.top();
    que.pop();
    ll v=p.second;
    if(d[v]<p.first) continue;
    for(ll i=0;i<G[v].size();i++){
      edge e=G[v][i];
      if(d[e.to]>d[v]+e.cost){
        d[e.to]=d[v]+e.cost;  
        prever[e.to]=v;
        que.push(make_pair(d[e.to],e.to));
      }
    }
  }
}
ll fill_f(ll v){
  if(used[v])return 0;
  if(b_draw[v]==2) return 0;
  b_draw[v]=1;
  ll time = 1;
  used[v]=true;
  for(int i=0;i<G[v].size();i++){
    time += fill_f(G[v][i].to);
  }
  return time;
}
vector<ll> getpath(ll t){
  vector<ll> path;
  for(;t!=-1;t=prever[t]){
    path.push_back(t);
  }
  reverse(path.begin(),path.end());
  return path;
}
