VI G[114514];
int n;

void bfs(int s, int d[]){
    queue<P> que;
    fill(d,d+n,INF);
    d[s] = 0;
    que.push(P(0,s));

    while(!que.empty()){
        P p=que.front(); que.pop();
        int v = p.second;
        if(d[v]<p.first) continue;
        for(int i=0;i<G[v].size();i++){
            int e = G[v][i];
            if(d[e]>d[v]+1){
                d[e] = d[v] + 1;
                que.push(P(d[e],e));
            }
        }
    }
}

