void dfs(ll now){
  visited[now] = 1;
  for(int i = 0; i < edge[now].size(); i++){
    ll next = edge[now][i];
    if(visited[next] == 1) continue;
    t[next] = t[now] + 1;
    dfs(next);
  }
}

void nul(ll now){
  paste[now] = 1;
  for(int i = 0; i < edge[now].size(); i++){
    ll next = edge[now][i];
    if(paste[next] == 1) continue;
    if(color[next] != 0) continue;
    color[next] = color[now];
    nul(next);
  }
}

