  t[0] = 0;
  dfs(0);
  vector<ll> path;
  ll k = t[N-1];
  ll now = N-1;
  while(k > 0){
    path.push_back(now);
    rep(i, edge[now].size()){
      if(t[edge[now][i]] == k-1){
        now = edge[now][i];
        k--;
        break;
      }
    }
  }
  path.push_back(0);
  reverse(path.begin(), path.end());
  int s = 0, t = path.size() - 1;
  while(true){
    if(s > t) break;
    if(color[path[s]] != 0) break;
    color[path[s]] = 1;
    s++;
    if(color[path[t]] != 0) break;
    color[path[t]] = -1;
    t--;
  }
  for(ll x : path){
      if(paste[x] != 0) continue;
