vector<bool> done(100001);

bool get_pass(int from, int to, vector<int> &pass) {
    if (done.at(from)) return false;

    if (from == to) {    
        pass.push_back(from);
        return true;
    }

    done.at(from) = true;

    for (int i = 0; i < (int)G[from].size(); i++) {
        if (get_pass(G[from].at(i), to, pass)) {
            pass.push_back(from);
            return true;
        }
    }

    return false;
}

vector<bool> used(100001);
void dfs(int p, int &cnt) {
    if (used.at(p)) return;

    used.at(p) = true;
    cnt++;

    for (int i = 0; i < (int)G[p].size(); i++) {
        dfs(G[p].at(i), cnt);
    }

    return;
}

