std::vector<int> route(Tree& tree, int from, int dst, std::vector<bool>& visited) {
  if (from == dst)
    return {dst};
  for (int v : tree[from].neighbor) {
    if (visited[v])
      continue;
    visited[v] = true;
    std::vector<int> r = route(tree, v, dst, visited);
    if (!r.empty()) {
      r.push_back(from);
      return r;
    }
  }
  return {};
}

std::vector<int> route(Tree& tree, int from, int dst) {
  std::vector<bool> visited(tree.size(), false);
  visited[from] = true;
  return route(tree, from, dst, visited);
}

int counts(Tree& tree, int v, std::vector<bool>& visited) {
  int sum = 1;
  for (int a : tree[v].neighbor) {
    if (visited[a])
      continue;
    visited[a] = true;
    sum += counts(tree, a, visited);
  }
  return sum;
}

int counts(Tree& tree, int v) {
  std::vector<bool> visited(tree.size(), false);
  return counts(tree, v, visited);
}

void erase(std::vector<int>& v, int num) {
  for (auto it = v.begin(); it < v.end(); it++) {
    if (*it == num) {
      v.erase(it);
      return;
    }
  }
}

