    tree[in - 1].neighbor.push_back(out - 1);
    tree[out - 1].neighbor.push_back(in - 1);
  }

  int black = 0;
  int white = n - 1;
  std::vector<int> r = route(tree, black, white);
  int half = r.size() / 2;
  int white_side_id = r[half];
  int black_side_id = r[half + 1];

  Node& black_side = tree[black_side_id];
  Node& white_side = tree[white_side_id];
  erase(black_side.neighbor, white_side_id);
  erase(white_side.neighbor, black_side_id);

  int black_num = counts(tree, black_side_id);
  int white_num = counts(tree, white_side_id);

  std::cout << (black_num > white_num ? "Fennec" : "Snuke") << std::endl;
  return 0;
}

