    {
        int u=nxt(),v=nxt();
        g[u].push_back(v);
        g[v].push_back(u);
    }

    visited.resize(n+1,0);

    dfs(1,0);
    int f=size[1]-1-size[n];
    int s=size[n]-1;
    if((depth[n]-1)%2)
        f++;
    int x=min(f,s);
    f-=x;
    s-=x;
    if(f==0)
        cout<<"Snuke\n";
    else
        cout<<"Fennec\n";


    return 0;   
