int dfs(int s,int depth2)
{
    visited[s]=1;
    depth[s]=depth2;
    size[s]=1;
    for(auto i:g[s])
    {
        if(!visited[i])
        {
            size[s]+=dfs(i,depth2+1);
        }
    }

    return size[s];

}

