int dfs(int x){
  used[x] = true;
  chi[x] = 1;
  for(int c: edge[x]){
    if(used[c])continue;
    par[c] = x;
    int tmp = dfs(c);
    chi[x] += tmp;
  }
  return chi[x];
}

