int main() {
	int n;
	std::cin >> n;

	std::vector<std::vector<int>> tab(n);

	for (int i{}; i < n - 1; ++i) {
		int a, b;
		std::cin >> a >> b;
		--a; --b;
		tab[a].emplace_back(b);
		tab[b].emplace_back(a);
	}

	/*
	for (auto e : tab){
		for (auto ee : e) {
			std::cout << " " << ee+1;
		}std::cout << "\n";
	}*/

	std::vector<int> check(n, 1);

	std::queue<int> wq;
	wq.emplace(n-1);
	check[n-1] *= 2;

	auto wcount = 0;
	while (!wq.empty()) {

		auto vtx = wq.front(); wq.pop();
//		std::cout << vtx << "\n";
		for (auto e : tab[vtx]) {
//			std::cout << e+1 << " e\n";
			if (check[e] % 2 == 0 || e == 0)
				continue;

			wq.emplace(e);
			check[e] *= 2;
			++wcount;

		}
	}

	decltype(wq) bq;
	bq.emplace(0);
	check[0] *= 3;

	decltype(wcount) bcount{};

	while (!bq.empty()) {
		auto vtx = bq.front(); bq.pop();

		for (auto e : tab[vtx]) {
			if (check[e] % 3 == 0 || e == n - 1)
				break;
			bq.emplace(e);
			check[e] *= 3;

			++bcount;
		}
	}


//	decltype(bcount) dist{};
	decltype(check)dist_(n,std::numeric_limits<decltype(check)::value_type>::max());
	decltype(bq) dq;
	dq.emplace(0);
	dist_[0] = 0;
	while (!dq.empty()) {
		auto vtx = dq.front(); dq.pop();
		if (vtx == n - 1)
			break;

		for (auto e : tab[vtx]) {
			if (dist_[e] <= dist_[vtx] + 1)
				break;

			dist_[e] = dist_[vtx] + 1;
			dq.emplace(e);
		}
	}

	auto com = dist_[n - 1] - 1;
	auto wuni = wcount - com;
	auto buni = bcount - com;

	if (wuni == buni)
		std::cout << (com % 2 == 1 ? "Fennec" : "Snuke") << "\n";
	else
		std::cout <<( wuni < buni ?"Fennec":"Snuke")<< "\n";

	return 0;
}

