		int a,b;
		SCD2(a,b);

		adj[a].push_back(b);
		adj[b].push_back(a);

	}

	bool visited[N+2];
	REP(i,N+2){visited[i] = false;}

	queue<int>Q;
	Q.push(1);

	visited[1] = true;
	visited[N] = true;
	int F = 0;

	while(!Q.empty()){
		int nowv = Q.front(); Q.pop();
		visited[nowv] = true;
		REP(i,adj[nowv].size()){
			int next = adj[nowv][i];
			if (visited[next]) { continue; }
			F++;
			Q.push(next);
		}

	}

	REP(i,N+2){visited[i] = false;}
	Q.push(N);
	visited[1] = true;
	visited[N] = true;

	int S = 0;
		while(!Q.empty()){
		int nowv = Q.front(); Q.pop();
		visited[nowv] = true;
		REP(i,adj[nowv].size()){
			int next = adj[nowv][i];
			if (visited[next]) { continue; }
			S++;
			Q.push(next);
		}

	}

	//F cup S = T
	int T = S+T-N;

	bool win;

	if (T%2 == 0) {
		if (F>S) win=true;
		else win=false;
	}else{
		if (F>=S) win = true;
		else win = false;
	}

	if(win) printf("Fennec");
	else printf("Snuke");

	return 0;
}

