vector<ll> bfs(vector<ll> path, ll v, vector<ll> visited) {
	queue<ll> q = queue<ll>();
	path.push_back(v);
	visited[v] = 0;
 	for (auto& nv : edge[v]) {
		if (nv == edge.size() - 1) {
			path.push_back(nv);
			return path;
		}
		if (visited[nv] == -1) {
			q.push(nv);
		}
	}
	while (q.size() > 0) {
		ll nv = q.front();
		visited[nv] = 0;
		vector<ll> p = bfs(path, nv,visited);
		if (p[0] != -1) return p;
		visited[nv] = -1;
		q.pop();

	}
	return vector<ll>(1, -1);

}

int main(void) {
	ll n;
	cin >> n;
    edge = vector<vector<ll>>(n);
	rep(i, 0, n-1) {
		ll a, b;
		cin >> a >> b;
		edge[a - 1].push_back(b - 1);
		edge[b - 1].push_back(a - 1);
	}
	vector<ll> path = bfs(vector<ll>(), 0, vector<ll>(n,-1));
	vector<ll> vOwner = vector<ll>(n,-1);
	ll length = path.size();
	ll fCount = 0;
	ll sCount = 0;
	rep(i, 0, length - length / 2) {
		vOwner[path[i]] = 0;
		fCount++;
	}
	rep(i, 0, length / 2) {
		vOwner[path[length - 1 - i]] = 1;
		sCount++;
	}
	queue<ll> q = queue<ll>();
	for (auto& v : edge[0]) {
		q.push(v);
	}

	while (q.size() > 0) {
		ll v = q.front();
		q.pop();
		if (vOwner[v] != 1) {
			if (vOwner[v] == -1) {
				fCount++;
				for (auto& nv : edge[v]) {
					q.push(nv);
				}
			}			
			vOwner[v] = 0;

		}
	}


	if (fCount * 2 > n) cout << "Fennec" << endl;
	else cout << "Snuke" << endl;
}

