const int V_MAX = 1e5+10;
int V;
vector<int> G[V_MAX];
bool ischecked[V_MAX];

int size(int p, int x){
  int s = 1;
  for(int &e : G[x]){
    if(e==p)continue;
    s += size(x,e);
  }
  return s;
}

int dfs(int x, int p, int y, vector<int> &v){
  if(x == y){
    v.push_back(x);
    return 1;
  }
  for(int &e:G[x]){
    if( e == p ) continue;
    int num = dfs(e,x,y,v);
    if(num!=0){
      v.push_back(x);
      return num+1;
    }
  }
  return 0;
}

int main(void){
  SPEEDUP
  cout << setprecision(15);
  cin >> V;
  rep(i,V-1){
    int x,y;cin >> x >> y;
    --x;--y;
    G[x].push_back(y);
    G[y].push_back(x);
  }
  vector<int> route;
  int num = dfs(0,-1,V-1,route);
  reverse(all(route));
  int count[2];
  int now[2];
  count[0] = count[1] = 0;
  now[0] = 0, now[1] = route.size()-1;
  int turn = 0;
  while(true){
    int cur = route[now[turn]];
    if(ischecked[cur]) break;
    ischecked[cur] = true;
    for(auto &e : G[cur]){
      if(now[turn] != route.size()-1 && e == route[now[turn]+1]) continue;
      if(now[turn] != 0 && e == route[now[turn]-1])continue;
      count[turn] += size(cur,e);
    }
    if(turn) --now[turn];
    else ++now[turn];
    turn^=1;
  }
  out(count[0] > count[1]);
  return 0;
}

