// 0 : white, 1 : black, -1 : uncoloured

int dfs(int here)
{
	visited[here] = true;

	int ret = 0;
	for(auto there : adj[here])
		if(!visited[there]) {
			ret += 1 + dfs(there);
		}
	return ret;
}

const int INF = (int)1e9;
void bfs(int start, VI& parent, VI& dist)
{
	parent = VI(n, -1);
	dist = VI(n, INF);
	queue<int> q;

	dist[start] = 0;
	parent[start] = start;
	q.push(start);

	while(q.empty() == false)
	{
		int here = q.front();
		q.pop();

		for(int there : adj[here])
		{
			if(parent[there] == -1)
			{
				parent[there] = here;
				dist[there] = dist[here] + 1;
				q.push(there);
			}
		}
	}
}

bool FennecWins()
{
	VI parent, dist;
	bfs(0, parent, dist);

	visited.assign(n, false);	
	int dest = n - 1;  visited[0] = true;
	while(parent[dest] != dest)
	{
		visited[dest] = true;
		dest = parent[dest];
	} 

	int fennec, snuke;
	if(dist[n - 1] % 2 == 0) {
		fennec = dist[n - 1] / 2 + 1;
		snuke = dist[n - 1] / 2;
	}
	else {
		fennec = snuke = (dist[n - 1] + 1) / 2;
	}

	fennec += dfs(0); snuke += dfs(n - 1);
	return snuke <= fennec;
}

