int dfs(vector<vector<int>> &g, int n, int par, int v, int depth) {
  ll ans0 = 1;

	if (v == n-1) {
		return ans0 - ((depth+1)/2);
	}

	for (int w : g[v]) {
	  if (w != par) ans0 += dfs(g, n, v, w, depth + 1);
	}

	return ans0;
}

