const double EPS=1e-8;

const int MAX_V=1e5;

struct edge{
    int to;
    int cost;
};

int V;
vector<edge>G[MAX_V];
int d[MAX_V];

void dijkstra(int s){
    priority_queue<pint,vector<pint>,greater<pint> > que;
    fill(d,d+V,INF);
    d[s]=0;

    que.push(pint(0,s));

    while(!que.empty()){
        pint p=que.top();que.pop();
        int v=p.second;
        if(d[v]<p.first) continue;
        for(int i=0;i<G[v].size();i++){
            edge e=G[v][i];
            if(d[e.to]>d[v]+e.cost){
                d[e.to]=d[v]+e.cost;
                que.push(pint(d[e.to],e.to));
            }
        }
    }
}

