        G[a].pb(e);
        e.to=a;
        G[b].pb(e);
    }

    dijkstra(0);
    int dist=d[V-1]/2;
    int res=0;
    rep(i,V){
        if(d[i]<=dist) res++;
    }

    out(res>=V/2?"Fennec":"Snuke");

    return 0;
}

