{
	if(u==n)	return 0;
	for(int i=head[u];i!=-1;i=e[i].next)
	{
		if(e[i].to==fa)	continue;
		int ret=dfs(e[i].to,u);
		if(ret>=0)
		{
			c[u]=true;
			return ret+1;
		}
	}
	return -1;
}
