void solve() {
    int n;
    cin >> n;

    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;

        g[a].push_back(b);
        g[b].push_back(a);
    }
    dfs(1);
    int b = 0, w = 0;

    vector<int> path;
    int cur = n;
    while (cur != -1) {
        path.push_back(cur);
        cur = p[cur];
    }
    reverse(path.begin(), path.end());
    for (int i = 0, j = (int)path.size() - 1; i <= j;) {
        c[path[i]] = 1;
        i++;
        c[path[j]] = 2;
        j--;
        if (i == j) {
            c[path[i]] = 1;
            break;
        }
    }
    for (auto x: p) {
        if (!visited[x])dfs2(x);
    }
    for (int i = 1; i <= n; i++)
        b += (c[i] == 1), w += (c[i] == 2);
    if (b > w)cout << "Fennec" << endl;
    else cout << "Snuke" << endl;
}

