#include <bits/stdc++.h>

using namespace std;

const int INF = 7777777;

vector< vector<int> > G;
vector<int> b_size, b_dist, w_size, w_dist;
int n;


void Dfs(int v, int p, int depth = 0) {
  if(v == p) {
    return;
  }
  else {
    if(v == n) {
      depth = INF;
    }
    b_dist[v] = depth;
    b_size[v] = 1;
    for(int i = 0; i < G[v].size(); ++i) {
      if(G[v][i] != p) {
        Dfs(G[v][i], v, depth + 1);
        b_size[v] += b_size[ G[v][i] ];
      } 
    }
  }
}


void Dfs1(int v, int p, int depth = 0) {
  if(v == p) {
    return;
  }
  else {
    if(v == 1) {
      depth = INF;
    }
    w_dist[v] = depth;
    w_size[v] = 1;
    for(int i = 0; i < G[v].size(); ++i) {
      if(G[v][i] != p) {
        Dfs1(G[v][i], v, depth + 1);
        w_size[v] += w_size[ G[v][i] ];
      }
    }
  }
}

int main() {
  #ifdef _OFFLINE_
  freopen("input.txt", "r", stdin);
  freopen("output.txt", "w", stdout);
  #endif

  cin >> n;
  G.resize(n+1);
  for(int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  b_dist.resize(n + 1);
  w_dist.resize(n + 1);
  b_size.resize(n + 1);
  w_size.resize(n + 1);

  fill(b_dist.begin(), b_dist.end(), 10 * n);
  fill(w_dist.begin(), w_dist.end(), 10 * n);

  Dfs(1, -1);
  Dfs1(n, -1);

  int not_cnt = 0;
  for(int i = 2; i <= n - 1; ++i) {
    if(b_dist[i] < INF && w_dist[i] < INF &&
        b_dist[i] <= w_dist[i] && n - w_size[i] < w_size[i]) {
      cout << "Fennec";
      return 0;
    }
    if(b_dist[i] >= INF || w_dist[i] >= INF) {
      ++not_cnt;
    }
  }

  if(not_cnt == n - 2) {
    int a = 0, b = 0;
    for(int i = 1; i <= n; ++i) {
      if(b_dist[i] < INF) {
        ++a;
      }
      else {
        ++b;
      }
    }
    if(a > b) {
      cout << "Fennec";
    }
    else {
      cout << "Snuke";
    }
    return 0;
  }

  cout << "Snuke";
}

