static const ll MAX = 100001;
vector <ll> G[MAX];
int NIL = -1;

struct prob{
    ll num, diss = NIL, disf = NIL;
};

prob lis[MAX];

void bfsf(ll u){
    queue <ll> Q;
    Q.push(u);
    lis[u].disf = 0;
    while(!Q.empty()){
        ll v = Q.front();
        Q.pop();
        for (ll i = 0;i<G[v].size();i++){
            if(lis[G[v][i]].disf == NIL){
                lis[G[v][i]].disf = lis[v].disf + 1;
                Q.push(G[v][i]);
            }
        }
    }
}

void bfss(ll u){
    queue <ll> Q;
    Q.push(u);
    lis[u].diss = 0;
    while(!Q.empty()){
        ll v = Q.front();
        Q.pop();
        for (ll i = 0;i<G[v].size();i++){
            if(lis[G[v][i]].diss == NIL){
                lis[G[v][i]].diss = lis[v].diss + 1;
                Q.push(G[v][i]);
            }
        }
    }
}

