    for (ll i = 1;i<n;i++){
        ll a,b;
        cin >> a >> b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    for (ll i=1;i<=n;i++){
        prob p;
        p.num = i;
        lis[i] = p;
    }
    bfsf(1);
    bfss(n);
    ll numf = 0;
    ll nums = 0;
    for (ll i=1;i<=n;i++){
        if(lis[i].disf <= lis[i].diss){
            numf += 1;
        }else{
            nums += 1;
        }
    }
    if(numf > nums){
        cout << "Fennec" << endl;
    }else{
        cout << "Snuke" << endl;
    }

}

