	p1count = 0;
	p2count = 0;

	std::queue<int> que;
	que.emplace(0);
	std::vector<int> went1(n,0);
	while(!que.empty()) {
		int i = que.front();que.pop();
		went1[i] = 1;
		p1count++;
		for(int j:from[i]) {
			if(went1[j]==0&&j!=cut2)que.emplace(j);
		}
	}
	que.emplace(n-1);
	std::vector<int> went2(n,0);
	while(!que.empty()) {
		int i = que.front();que.pop();
		went2[i] = 1;
		p2count++;
		for(int j:from[i]) {
			if(went2[j]==0&&j!=cut1)que.emplace(j);
		}
	}

	if(p1count>p2count) {
		print("Fennec");
		return 0;
	}
	if(p1count<=p2count) {
		print("Snuke");
		return 0;
	}
	return 0;
}

