  if(u == N - 1) {
    pathN.push_back(u);
    return true;
  }
  for(int i = 0; i < side.at(u).size(); i++) {
    int v = side.at(u).at(i);
    if(v == p) continue;
    if(dfs(u, v, side)) {
      pathN.push_back(u);
