    cin >> a[i] >> b[i];
    a[i]--,b[i]--;
    g.add_edge(a[i],b[i],1);
    g.add_edge(b[i],a[i],1);
    f.add_edge(a[i],b[i],1);
    f.add_edge(b[i],a[i],1);
  }
  f.dijkstra(n-1);
  g.dijkstra(0);
  ll gg,ff;
  gg = 0;
  ff = 0;
  rep(i,n){
    if(g.d[i] <= f.d[i]){
       gg = max(gg,g.d[i]);
    }else{
      ff = max(ff,f.d[i]);
    }
  }
  // cout << gg << " " << ff << endl;
  if(ff <= gg){
    cout << "Fennec" << "\n";
  }else{
    cout << "Sunuke" << endl;
  }
  return 0;
}

