int fanc(vector<bool> &c, vector<vector<int>> &v, int n){
	int ans = -1;
	queue<int> q;
	q.push(n-1);
	while(!q.empty()){
		int qi = q.front(); q.pop();
		ans++;
		rep(i, n){
			if(v.at(qi).at(i) == 1 && c.at(i) == false){
				q.push(i);
				c.at(i) = true;
			}
		}
	}
	return ans;
}

