int main() {
    // source
    int n;
    cin >> n;
    vector<vector<int>> graph(n);

    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
        graph[a - 1].push_back(b - 1);
        graph[b - 1].push_back(a - 1);
    }

    int dist0[n], dist1[n];
    rep(i, n) {
        dist0[i] = mod;
        dist1[i] = mod;
    }
    dist0[0] = 0;
    dist1[n - 1] = 0;

    queue<int> q0;
    q0.push(0);
    while (!q0.empty()) {
        int point = q0.front();
        q0.pop();
        rep(i, graph[point].size()) {
            int next = graph[point][i];
            if (dist0[next] != mod) {
                continue;
            }
            q0.push(next);
            dist0[next] = dist0[point] + 1;
        }
    }

    queue<int> q1;
    q1.push(n - 1);
    while (!q1.empty()) {
        int point = q1.front();
        q1.pop();
        rep(i, graph[point].size()) {
            int next = graph[point][i];
            if (dist1[next] != mod) {
                continue;
            }
            q1.push(next);
            dist1[next] = dist1[point] + 1;
        }
    }

    int num0 = 0, num1 = 0;

    rep(i, n) {
        if (dist0[i] <= dist1[i]) {
            num0++;
        } else {
            num1++;
        }
    }

    if (num0 >= num1) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }

    return 0;
}

Bint comb(Bint a, Bint b) {
    Bint ans = 1;

    if (a < b) {
        return 0;
    }

    rep(i, b) {
        ans *= a - i;
        ans /= i + 1;
    }

    return ans;
}

template <typename T> void output(T a, int precision) {
    if (precision > 0) {
        cout << setprecision(precision) << a << "\n";
    } else {
        cout << a << "\n";
    }
}

template <typename T> T min(T a, T b) {

    if (a < b) {
        return a;
    } else {
        return b;
    }
}

ll gcd(ll a, ll b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

ll lcm(ll a, ll b) { return a * b / gcd(a, b); }

void prime_map(map<ll, ll> &m, ll num) {
    ll cache = num;
    repd(i, 2, sqrt(num) + 2) {
        if (num % i == 0) {
            if (m[i] == 0) {
                m[i] = 1;
            } else {
                m[i]++;
            }

            num /= i;
            break;
        }
    }

    if (cache == num) {
        if (m[num] == 0) {
            m[num] = 1;
        } else {
            m[num]++;
        }
        return;
    } else {
        prime_map(m, num);
    }
}

