#include <bits/stdc++.h>

using namespace std;

#define FOR(v, b, e)   for (int v = (b); v < (e); ++v)
#define REP(v, n)      FOR(v, 0, n)

#define ALL(c)         (c).begin(), (c).end()


void painting (int i, vector<int>& r, vector<vector<int>>& g) {
	if (r[i] != 0) return;
	r[i] = 1;
	for (auto v : g[i]) painting(v, r, g);
}

int main () {
	ios::sync_with_stdio(false);
	cin.tie(0);

	int N;
	cin >> N;

	vector<vector<int>> g(N, vector<int>());
	int a, b;
	REP(i, N - 1) {
		cin >> a >> b;
		g[a - 1].push_back(b - 1);
		g[b - 1].push_back(a - 1);
	}

	vector<int> black(N);
	black[N - 1] = -1;
	painting(0, black, g);

	vector<int> white(N);
	white[0] = -1;
	painting(N - 1, white, g);

	int bc = 0;
	int wc = 0;
	int zc = 0;
	REP(i, N) {
		int r = black[i] - white[i];
		if (r > 0) {
			++bc;
		} else if (r < 0) {
			++wc;
		} else {
			++zc;
		}
	}

	if ((zc % 2) != 0) {
		if (((bc + wc) % 2) == 0) {
			++bc;
		} else {
			++wc;
		}
	}

	if (bc > wc) {
		cout << "Fennec" << endl;
	} else {
		cout << "Snuke" << endl;
	}
}

