void dij(int s){
  d[s] = 0;
  priority_queue<P,vector<P>,greater<P>> que;
  que.push(P(0,s));
  while(!que.empty()){
    P tmp = que.top();
    que.pop();
    ll v=tmp.second,dis = tmp.first;
    if(d[v] < dis){
      continue;
    }
    for(auto nv:G[v]){
      if(d[nv] > d[v]+1){
        d[nv] = d[v]+1;
        pr[nv] = v;
        que.push(P(d[nv],nv));
      }
    }
  }
}
vector<ll> g_path(int t){
  vector<ll> path;
  for(; t!=-1;t=pr[t]){
    path.push_back(t);
  }
  reverse(path.begin(),path.end());
  return path;
}
