using namespace std;
const int INF = 1e9;

vector<int> univ (const vector<vector<int>> &G, int s) {
    vector<int> koike(G.size(), INF); koike[s] = 0;
    vector<bool> LOVE(G.size(), false);
    queue<int> que; que.emplace(s);
    while (!que.empty()) {
        int yuriko = que.front(); que.pop();
        LOVE[yuriko] = true;
        for (auto abe : G[yuriko]) {
            if (LOVE[abe] == true) continue;
            koike[abe] = koike[yuriko] + 1;
            que.emplace(abe);
        }
    }
    return koike;
}

int main(){
    int N;
    cin >> N;
    vector<vector<int>> G(N);
    for (int i = 1; i < N; i++) {
        int abe, koike; cin >> abe >> koike; abe--; koike--;
        G[abe].emplace_back(koike);
        G[koike].emplace_back(abe);
    }

    vector<int> fen = univ(G, 0);
    vector<int> snuke = univ(G, N-1);

    int ok = 0, ng = 0;
    for (int i = 0; i < N; i++) {
        if (fen[i] <= snuke[i]) ok++;
        else ng++;
    }

    cout << ((ng < ok) ? "Fennec" : "Snuke") << endl;
    return 0;
}

