#include <bits/stdc++.h>
using namespace std;
#define maxn 100010
struct Edge {
	int to, nxt;
} edge[2 * maxn];
int tot, head[maxn], n, color[maxn];
void init() {
	tot = 0;
	memset(head, -1, sizeof head);
}
void add(int u, int v) {
	edge[tot].to = v;
	edge[tot].nxt = head[u];
	head[u] = tot++;
}
int ppp;
bool dfs(int x, int y, int z) {
	if (y == n) {
		ppp = z - 1;
		return 1;
	}
	for (int i = head[y]; i != -1; i = edge[i].nxt) {
		if (edge[i].to != x) {
			if (dfs(y, edge[i].to, z + 1)) {
				if (y != 1)
				if (z <= (ppp + 1) / 2) {
					color[y] = 0;
				} else {
					color[y] = 1;
				}
				return 1;
			}
		}
	}
	return 0;
} 
void work(int x) {
	for (int i = head[x]; i != -1; i = edge[i].nxt) {
		int y = edge[i].to;
		if (color[y] == -1) {
			color[y] = color[x];
			work(y);
		}
	}
}
int main()
{
	int x, y;

	scanf("%d", &n);
	init();
	memset(color, -1, sizeof color);
	color[1] = 0, color[n] = 1;
	for (int i = 1; i < n; i++) {
		scanf("%d%d", &x, &y);
		add(x, y);
		add(y, x);
	}
	dfs(1, 1, 0);
	int ans = 0;
	for (int i = 1; i <= n; i++) {
		if (color[i] != -1) {
			work(i);
		}
	}
	for (int i = 1; i <= n; i++) {
		ans += color[i];
		//printf("%d ", color[i]);
	}
	puts(n > 2 * ans ? "Fennec" : "Snuke");
}

