const ll LINF=1LL<<60;
const int MAX_N=100005;

int dist[MAX_N];
vector<int> graph[MAX_N];
bool used[MAX_N];

int search(int me,int enemy){
  //自分の領地と相手との領域を探索する
  fill(used,used+MAX_N,false);
  stack<P> st;
  st.push(P(me,0));
  int cnt=0;
  while(!st.empty()){
    P p = st.top();
    int x=p.first;
    st.pop();
    if(used[x]||x==enemy||dist[x]<=p.second) continue;
    used[x]=true;
    dist[x]=p.second;
    cnt++;
    for(auto y:graph[x]) st.push(P(y,p.second+1));
  }
  return cnt;
}

int main(){
  int N;
  cin >> N ;
  fill(dist,dist+MAX_N,INF);
  rep(i,N-1){
    int a,b;
    scanf("%d%d",&a,&b);
    a--; b--;
    graph[a].pb(b);
    graph[b].pb(a);
  }
  int b,w;
  search(0,N-1);
  w=search(N-1,0); //白の領地
  b=N-w;
  cout << b << "," << w << endl;
  if(b>w) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;
  return 0;
}

