struct edge {ll to, cost;};
const ll mx = 1e5 + 100;
vector<edge> ed[mx];
ll N;

vl dijkstra(ll st){
    vl dist(N, LINF); dist[st] = 0;
    priority_queue<PL,vector<PL>, greater<PL>> q;
    q.push({0,st});
    while (!q.empty()) {
        auto tmp = q.top(); q.pop();
        ll now = tmp.ss, dis = tmp.ff;
        if(dist[now] < dis) continue;
        for(auto& e : ed[now]){
            if(dist[e.to] > dis + e.cost){
                dist[e.to] = dis + e.cost;
                q.emplace(dist[e.to], e.to);
            }
        }
    }
    return dist;
}

