const int N = 100010;
const int INF = 1e9;
int distB[N], distW[N];

vector<vector<int>> G;

void bfs(int s, int flag){ // 1:Black 0:White
    queue<int> que;
    que.push(s);
    if(flag == 1) distB[s] = 0;
    if(flag == 0) distW[s] = 0;

    while(!que.empty()){
        int from = que.front();
        que.pop();

        for(auto to : G[from]){
            if(flag == 1){
                if(distB[to] == INF){
                    distB[to] = distB[from] + 1;
                    que.push(to);
                }
            }
            if(flag == 0){
                if(distW[to] == INF){
                    distW[to] = distW[from] + 1;
                    que.push(to);
                }
            }
        }
    }
}

int main() {
    int n;
    cin >> n;

    G.resize(n);
    fill(distB, distB + N, INF);
    fill(distW, distW + N, INF);

    for (int i = 0; i < n - 1; i++) {
        int a,b;
        cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    bfs(0,1);
    bfs(n-1, 0);

    int B = 0, W = 0;
    for(int i = 0; i < n; i++){
        if(distB[i] <= distW[i]) B++;
        else if(distB[i] > distW[i]) W++;
    }

    if(B > W) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

}

