using namespace std;

int N;
vector<vector <int> > wo(100001, vector<int>());
vector<int> sl;

bool oneton(int now, int pre){
  if(now == N) {
    sl.push_back(N);
    return true;
  }
  if(wo[now].size() == 1) return false;

  for(auto e: wo[now]){
    if(e != pre){
      if(oneton(e, now)) sl.push_back(now);
    }
  }
}

int dfs(int now, int pre){
  if(wo[now].size() == 1) return 1;

  int dist = 0;
  for(auto e: wo[now]){
    if(e != pre){
      dist += dfs(e, now);
    }
  }
  return dist + 1;
}

int main(){
  cin >> N;

  for(int i = 0; i < N - 1; i++){
    int a, b; cin >> a >> b;
    wo[a].push_back(b);
    wo[b].push_back(a);
  }

  oneton(1, -1);
  sl.push_back(1);

  int ssl = sl.size();
  int fnk = dfs(sl[ssl/2], sl[ssl/2-1]);
  int snk = dfs(sl[ssl/2-1], sl[ssl/2]);

  if(ssl % 2){
    if(fnk > snk) cout << "Fennec";
    else cout << "Snuke";
  }else{
    if(fnk >= snk) cout << "Fennec";
    else cout << "Snuke";
  }
}

