        queue<int> q;
        q.push(0);
        int cnt = 0;
        fennec[0] = 0;
        fennec[n-1] = -99;
        while(!q.empty()){
            int u = q.front(); q.pop();
            for(auto const& e : g[u]){
                if(fennec[e] != 1e6) continue;
                fennec[e] = ++cnt;
                q.push(e);
