    dfs(g,0,-1);
    vl v=vec;
    rev(all(v));
    ll sz=v.size();
    ll a,b;
    if(sz%2==0){
        a=v[sz/2-1],b=v[sz/2];
    }
    else{
        a=v[sz/2],b=v[sz/2+1];
