const int MAX_V = 100100;

int V, E;
vector<int> G[MAX_V];

int cnt[2], mark[MAX_V];
bool f[2][MAX_V];

void dfs(int s, int n) {

	for (int i = 0; i < G[s].size(); i++) {
		int u = G[s][i];
		if(f[n][u]) continue;
		f[n][u] = true;
		cnt[n]++;
		mark[u]++;
		dfs(u, n);
	}
}

