        g[a].push_back(b);
        g[b].push_back(a);
    }

    vector<int> v;
    function<int(int, int, int)> dfs = [&](int t, int p, int d) {
        for (int c : g[t]) {
            if (c == p) continue;
            if (c == n - 1) {
                v.push_back(c);
                return d;
            }
            int r = dfs(c, t, d + 1);
            if (r > 0) {
                v.push_back(c);
                return r;
            }
        }
        return -1;
    };

    int depth = dfs(0, -1, 0);
    int s = depth > 0 ? v[depth / 2] : n - 1;
    int sp = depth > 0 ? v[depth / 2 + 1] : 0;

    function<int(int, int)> dfs2 = [&](int t, int p) {
        if (g[t].size() == 1) return 1;
        int total = 1;
        for (int c : g[t]) {
            if (c == p) continue;
            total += dfs2(c, t);
        }
        return total;
    };
    int white = dfs2(s, sp);
    if (white >= (n + 1) / 2) {
        cout << "Snuke" << endl;
    } else {
        cout << "Fennec" << endl;
    }
}

