const ll V = 100000;
const ll INF = 1LL << 60;
using P = pair<ll, ll>;
vector<P> G[V];	//pair<辺の距離, 行き先の頂点>
vector<ll> dist(V); //dist[i]はsから頂点iへの最短距離が入る
vector<bool> used(V);
void dijkstra(ll s) {	//s : 始点
	//初期化
	fill(dist.begin(), dist.end(), INF);
	fill(used.begin(), used.end(), false);

	priority_queue<P, vector<P>, greater<P>> q;
	q.push(P(0, s));
	while (!q.empty()) {
		ll d;	//d : sからの距離
		ll t;	//t ; 行き先
		tie(d, t) = q.top();
		q.pop();
		if (used[t]) {	//もう探索済みか
			continue;
		}
		used[t] = true;
		dist[t] = d;
		for (P e : G[t]) {
			if (dist[e.second] <= d + e.first) {	//枝刈り
				continue;
			}
			q.push(P(d + e.first, e.second));
		}
	}
}

int main() {
	ll n;
	vector<ll> dist1(V);
	vector<ll> distn(V);

	cin >> n;

	REP(i, n - 1) {
		ll a, b;
		cin >> a >> b;
		G[a - 1].push_back(make_pair(1, b - 1));
		G[b - 1].push_back(make_pair(1, a - 1));
	}

	dijkstra(0);

	REP(i, n) {
		dist1[i] = dist[i];
	}

	dijkstra(n - 1);

	REP(i, n) {
		distn[i] = dist[i];
	}

	ll black = 0;
	ll white = 0;

	REP(i, n) {
		if (dist1[i] <= distn[i]) {
			black++;
		}
		else {
			white++;
		}
	}

	if (black > white) {
		cout << "Fennec" << endl;
	}
	else {
		cout << "Snuke" << endl;
	}
}

