const ll MAX_N = 100005;
bool okay = false;
ll answer = 0;
ll n, a, b;
gr tree[MAX_N];
bool visited[MAX_N];
ll nto1;
ll ds[2][MAX_N];

class LCA{
public:
    ll N, logN;
    vl depth, len;
    vector<vl> parents;

    LCA(ll n){
        N = n;
        logN = 0;
        while (N > (1LL << logN)) logN++;
        depth = vl(N); len = vl(N);
        parents = vector<vl>(logN, vl(N));
        init(0, -1, 0, 0);
        build();
    }

    void init(ll v, ll parent, ll d, ll l){
        depth[v] = d;
        parents[0][v] = parent;
        len[v] = l;
        rep(i, tree[v].size()){
            ll w = tree[v][i].to;
            ll lc = tree[v][i].cost;
            if (w == parent) continue;
            init(w, v, d + l, lc + l);
        }
    }

    void build(){
        rep(k, logN - 1) rep(n, N){
            if (parents[k][n] < 0) parents[k + 1][n] = -1;
            else parents[k + 1][n] = parents[k][parents[k][n]];
        }
    }

    ll query(ll u, ll v){
        if (depth[u] > depth[v]) swap(u, v);
        rep(k, k < logN) if ((depth[v] - depth[u]) >> k & 1) v = parents[k][v];
        if (u == v) return u;

        revrep(k, logN){
            if (parents[k][u] != parents[k][v]){
                u = parents[k][u]; v = parents[k][v];
            }
        }
        return parents[0][u];
    }

    ll distance(ll u, ll v){
        ll w = query(u, v);
        return len[u] + len[v] - 2 * len[w];
    }

};

pl dfs(char player, ll source){
    if (visited[source]) return mp(0, 0);
    visited[source] = true;

    ll val_white, val_black; pl vals;
    if (player == 'w') {val_white = 1; val_black = 0;}
    else if (player == 'b') {val_white = 0; val_black = 1;}

    rep(i, tree[source].size()){
        ll target = tree[source][i].to;
        if (ds[0][target] <= ds[1][target]) vals = dfs('b', target);
        else vals = dfs('w', target);
        val_black += vals.e1; val_white += vals.e2;
    }
    return mp(val_black, val_white);
}

void solve(){
    rep(i, n - 1){
        in2(a, b); a--; b--;
        tree[a].pb({b, 1});
        tree[b].pb({a, 1});
    }

    // path(0, 0, -1, 0);
    // path(1, n - 1, -1, 0);

    LCA lca(n);
    rep(i, n){
        ds[0][i] = lca.distance(0, i);
        ds[1][i] = lca.distance(n - 1, i);
    }
    pl v;
    v = dfs('b', 0);
    ll b = v.e1;
    ll w = v.e2;
    if (b > w) prl("Fennec");
    else prl("Snuke");
}

