int road(int a){
    if(a == N-1){
        return check[a] = 1;
    }
    if(a != 0 && to[a].size() == 1){
        return check[a] = 2;
    }
    for(int p : to[a]){
        if(dis[p] < dis[a])continue;
        if(check[p] == 2)continue;
        if(check[p] == 1)return check[a] = 1;

        int x = road(p);
        if(x == 2)continue;
        if(x == 1)return check[a] = 1;
    }
    return 2;
}

void coloring(int a, int d){
    color[a] = 1;
    if(d == m)return;
    for(int p : to[a]){
        if(check[p] == 1)coloring(p, d+1);
    }
    return;
}

void coloring2(int a){
    color[a] = 1;
    for(int p : to[a]){
        if(color[p] != 0)continue;
        coloring2(p);
