int first(int u, int dist) {
    seen[u] = true;
    if (u == n - 1) {
        if (dist <= 2) f1 = u;
        return dist;
    }
    for (int v : adj[u]) {
        if (seen[v]) continue;
        int d = first(v, dist + 1);
        if (d > 0) {
            if (dist == d / 2 + 1) f1 = u;
            else if (dist == d - (d + 1) / 2) f2 = u;
            return d;
        }
    }
    return -1;
}

