        path[a].push_back(b);
        path[b].push_back(a);
    }
    queue<int> q;
    int banpei = INT_MIN;

    int used[n+1];
    rep(i,n+1){used[i]=0;}
    used[1] = 1;
    q.push(1);
    q.push(banpei);
    bool flag = true;
    map<int,int> parent;
    while(flag){

        while(q.front()!=banpei){

            auto pos = q.front();
            q.pop();

            if(pos == n){flag = false; break;}

            for(auto targ:path[pos]){
                if(used[targ]==1)continue;
                used[targ] = 1;
                q.push(targ);
                parent[targ] = pos;
            }
        }
        q.pop();
        q.push(banpei);
    }
    vector<int> shortest;
    int cur = n;
    shortest.push_back(cur);
    while(cur!=1){
        cur = parent[cur];
        shortest.push_back(cur);
    }

    int curp = 0;
    int curn = (int)shortest.size()-1;
    reverse(all(shortest));
    color.resize(n+1,'.');

    while(1){
        if(curp>curn)break;
        color[shortest[curp]] = 'B';
        curp++;
        if(curp>curn)break;
        color[shortest[curn]] = 'W';
        curn--;
    }

    if (dfs(1,'B',0) <= dfs(n,'W',0)) cout<<"Snuke"<<endl;
    else cout<<"Fennec"<<endl;

    return 0;
}

