    {
        from = que.front();
        que.pop();

        for(int i = 0; i < G[from].size(); ++i)
        {
            to = G[from][i];
            if(d[from] + 1 < d[to])
            {
                d[to] = d[from] + 1;
                prev[to] = from;
                que.push(to);
            }
        }
    }

    //snukeは Nから1に向かって、(d[N-1] - 1) / 2回移動できる
