    {
        from = que.front();
        que.pop();

        for(int i = 0; i < G[from].size(); ++i)
        {
            to = G[from][i];
            if(guard[to] == 1)continue;
            guard[to] = 1;
            ++fen;
            que.push(to);
        }
    }

    string res;
    //奇数個の場合
    if( fen > (N - 2 + 1) / 2)
    {   
        res = "Fennec";
    }
    else
    {
        res = "Snuke";
    }

    cout << res << endl;
    return 0;
}

