    color[i] = d;
    for (int a: adj[i]) {
        depth(a, d + 1);
    }
}

void depth2(int i, int d) {
    if (color2[i] != -1) return;
    color2[i] = d;
    for (int a: adj[i]) {
        depth2(a, d + 1);
    }
}


int initb, initw;

void c(int i, int v) {
    if (((i == 0 && v != initb) || (i == 1 && v != initw)) && color[v] != -1) return;
    color[v] = i;
    for (int a: adj[v]) {
        if (color[a] == -1) {
            c(i, a);
        }
    }
}

