const LL mod = 1000000007ll;
const int mod_int = 1000000007;

LL N;
vector<vector<int>> adj;

string ans = "Fennec";

void solve(){
    queue<int> q;
    q.push(1);
    vector<int> used(N+1,-1);
    used[1] = 0;
    while(!q.empty()){
        int now = q.front();q.pop();
        for(int next : adj[now]){
            if(used[next]==-1){
                used[next] = now;//どこからやってきたのかを格納
                q.push(next);
            }
        }
    }

    //フェネックとすぬけくんの初期位置の距離を求める
    //きた道を逆にたどって距離を求める
    int dist_1_to_N = 0;
    int now = N;
    while(now!=1){
        now = used[now];
        dist_1_to_N++;
    }

    queue<int> p;

    vector<int> color(N+1,-1);//0なら黒、1なら白とする
    color[1] = 0;color[N] = 1;
    //フェネックとすぬけくんの間に色を塗る
    int vertex = N;
    int numof_white = (dist_1_to_N-1)/2;
    while(vertex!=1){
        vertex = used[vertex];
        color[vertex] = (numof_white>=1);
        if(numof_white>=1) p.push(vertex);
        numof_white--;
    }

    p.push(N);
    while(!p.empty()){
        int now = p.front();p.pop();
        for(int next : adj[now]){
            if(color[next]==-1){
                color[next] = 1;
                p.push(next);
            }
        }
    }

    int white_counter = 0;
    for(int i=1;i<=N;i++) white_counter += (color[i]==1);
    if(white_counter>=N-white_counter) ans = "Snuke";
}

int main(){
    cin >> N;
    adj = vector<vector<int>>(N+1);
    for(int i=0;i<=N-2;i++){
        int a,b;cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    solve();

    cout << ans << endl;
    return 0;
}

