    int p = parent[n];
    while(p != 1)
    {
        if(debugFlag)
        {
            cout << "parent : " << p << endl;

        }
        pathNum += 1;
        p = parent[p];
    }
    if(pathNum%2 != 0)
    {
        pathNum /= 2;
        ++pathNum;
    }
    else
    {
        pathNum /= 2;
    }

    return pathNum;
}

int ScoreDec(int n)
{
    if(debugFlag)
    {
        cout << "ScoreDec" << endl;
    }
    int result = 0;
    int pathNum = calcPathNum(n);
    int p = n;

    for(int i = 0; i < pathNum; ++i)
    {
        result += score[p];
        p = parent[p];
    }
    if(debugFlag)
    {
        cout << "2p scr : "<< result << endl;
    }
    return result;
}

