/* ------------- Functions -------------- */

void paint(int c) {

    queue<int> bfsq;

    if (c == 0) {
        dis[c][1] = 0;
        bfsq.push(1);
    } else {
        dis[c][N] = 0;
        bfsq.push(N);
    }

    while (!bfsq.empty()) {
        int v = bfsq.front();
        for (int vs : path[v]) {
            if (dis[c][vs] < 0) {
                dis[c][vs] = dis[c][v] + 1;
                bfsq.push(vs);
            }
        }
        bfsq.pop();
    }
    return;
}

/* ----------- Main Function ------------ */

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N;
    REP(i, N - 1) {
        int a, b;
        cin >> a >> b;
        path[a].pb(b);
        path[b].pb(a);
    }

    REP(c, 2) {
        paint(c);
    }

    int score = 0;
    // フェネックとすぬけの塗れるマスの差
    // 正ならフェネック、非正ならすぬけの勝ち
    NREP(i, N) {
        if (dis[0][i] <= dis[1][i]) {
            score++;
        } else {
            score--;
        }
    }

    if (score > 0) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
    return 0;
}

