      univB.pop_front();
    }

    for (auto x: univW) {
      for (auto y: nvec.at(x).connect) {
	if (check[y] == 0) {
	  univW.push_back(y);
	  check[y] = -1;
	  countW++;
	}
      }
    }
    for (int i = 0; i < countW-bcW; i++) {
      univW.pop_front();
    }

    if(bcB == countB && bcW == countW) break;
  }
  if (countB < countW) {
    cout << "Snuke" << endl;
  } else {
    cout << "Fennec" << endl;
  }
  return 0;
}

