        G[b-1].push_back(a-1);
    }
    cc.assign(N, 0);
    P.assign(N, -1);
    dfs(0);
    ll n = N-1;
    ll level = 0;
    while(n > 0) {
        n = P[n];
        level++;
    }
    n = N-1;
    ll cnt = cc[n]+1;
    REP(i, (level-1)/2) {
        n = P[n];
        cnt = cc[n]+1;
    }
    if (cnt < N-cnt) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke"  << endl;
    }
}


