    Graph[a].push_back(edge{b, 1});
    Graph[b].push_back(edge{a, 1});
  }

  dijkstra(1);
  repe(i, 1, N) { dist1[i] = dist[i]; }

  dijkstra(N);
  repe(i, 1, N) { distN[i] = dist[i]; }

  ll fenec = 0;
  repe(i, 1, N) {
    if (dist1[i] <= distN[i]) {
      ++fenec;
    }
  }

  ll snuke = N - fenec;

  if (fenec > snuke) {
    cout << "Fennec";
  } else {
    cout << "Snuke";
  }
}

