void Bfs(int s)
{
	int head = 1, tail = 1, now, ed, dr;
	seq[head] = s;
	for(int i = 1; i <= n; i++){
		if(i == s) dis[i] = 0;
		else dis[i] = 1 << 30;
	}
	vis[s] = 1;
	while(head <= tail)
	{
		now = seq[head];
		ed = last[now];
		while(ed != -1)
		{
			dr = other[ed];
			if(!vis[dr]){
				vis[dr] = 1;
				seq[++tail] = dr;
				dis[dr] = dis[now] + 1;
			}
			ed = pre[ed];
		}
		head++;
	}
}

void Dfs(int x, int y)
{
	int ed, dr;
	size[x] = 1;
	ed = last[x];
	while(ed != -1)
	{
		dr = other[ed];
		if(dr != y)
		{
			Dfs(dr, x);
			size[x] += size[dr];
		}
		ed = pre[ed];
	}
}


