ll N;
static const ll MAX = 100001;
static const ll INFTY = (ll)1 << 55;
static const int WHITE = 1;
static const int GRAY = 2;
static const int BLACK = 3;
vector<pair<ll, ll>>adj[MAX];
ll d[MAX];
ll pre[MAX];

priority_queue<pair<ll, ll>>PQ;
ll color[MAX];
ll n;
void dijkstra(ll x) {
	repe(i, 1, n) {
		d[i] = INFTY;
		color[i] = WHITE;
		pre[i] = -1;
	}

	d[x] = 0;
	PQ.push(make_pair(x, x));
	color[x] = GRAY;
	while (!PQ.empty()) {
		pair<ll, ll> f = PQ.top(); PQ.pop();
		ll u = f.second;
		color[u] = BLACK;

		if (d[u] < f.first * (-1))continue;

		rep(j, 0, adj[u].size()) {
			ll v = adj[u][j].first;
			if (color[v] == BLACK)continue;
			if (d[v] > d[u] + adj[u][j].second) {
				d[v] = d[u] + adj[u][j].second;
				pre[v] = u;
				PQ.push(make_pair(d[v] * (-1), v));

				color[v] = GRAY;
			}
		}
	}
}
vector<ll> get_path(ll t) {
	vector<ll> path;
	for (; t != -1; t = pre[t])path.push_back(t);
	reverse(path.begin(), path.end());
	return path;
}
ll F_P;
ll S_P;
bool vis[100001] = {};
void dfs(ll k, bool isF) {
	if (isF && k == n)return;
	if (!isF && k == 1)return;
	if (isF && k == F_P) {
		return;
	}
	if (!isF && k == S_P) {
		return;
	}

	if (vis[k])return;

	vis[k] = true;

	for (vector<pair<ll, ll>>::iterator it = adj[k].begin(); it != adj[k].end(); it++) {
		dfs(it->first, isF);
	}
}

int main() {
	cin >> n;
	rep(i, 0, n - 1) {
		ll a, b; cin >> a >> b;
		adj[a].push_back(make_pair(b, 1));
		adj[b].push_back(make_pair(a, 1));
	}

	dijkstra(1);
	ll dis = d[n];
	vector<ll> t = get_path(n);
	F_P = t[dis / 2 + 1];
	S_P = t[dis / 2];

	repe(i, 1, n)vis[i] = false;
	dfs(1, true);
	ll fenec = 0;
	repe(i, 1, n) {
		if (vis[i]) fenec++;
	}

	repe(i, 1, n)vis[i] = false;
	dfs(n, false);
	ll sunuke = 0;
	repe(i, 1, n) {
		if (vis[i]) sunuke++;
	}
	//sunuke--;

	cout << ((fenec >= sunuke) ? "Fennec" : "Snuke") << endl;;

	return 0;
}

#include <iostream>
#include <vector>
using namespace std;
struct NODE{
	int id;
	vector<NODE*> lnkNodes;
	int color;
	NODE(){
		lnkNodes.clear();
		id=-1;
		color=0;
	}
	void AddLnkNode(NODE &node){
		lnkNodes.push_back(&node);
	}
	void SetColor(int _color){
		color=_color;
	}
};
bool Find(vector<NODE> &Nodes,int color)
{
	int i;
	for (i=0;i<Nodes.size();i++){
		if (Nodes[i].color==color){
			for (int j=0;j<Nodes[i].lnkNodes.size();j++){
				if (Nodes[i].lnkNodes[j]->color==0){
					Nodes[i].lnkNodes[j]->color=color;
					Nodes[i].lnkNodes.erase(Nodes[i].lnkNodes.begin()+j);
					return true;
				}
			}
		}
	}
	return false;
}
int main(int argc, char* argv[])
{
	int N;
	cin>>N;
	vector<NODE> Nodes(N);
	Nodes[0].color=1;
	Nodes[N-1].color=2;
	int i;
	int node1,node2;
	for (i=0;i<N-1;i++){
		cin>>node1>>node2;
		node1--;
		node2--;
		Nodes[node1].id=node1;
		Nodes[node2].id=node2;
		Nodes[node1].AddLnkNode(Nodes[node2]);
		Nodes[node2].AddLnkNode(Nodes[node1]);
	}
	int color=1;
	while (true){
		if (!Find(Nodes,color)){
			switch(color){
			case 1:
				cout<<"Snuke"<<endl;
				return 0;
			case 2:
				cout<<"Fennec"<<endl;
				return 0;
			}
		}
		color++;
		if (color==3){
			color=1;
		}
	}
	return 0;
}

