int dfs(int u, int step){
    vis[u]=1;
    if(u==n){
        int mid=step/2+1+step%2;
        if(step==mid)p=u;
        return mid;
    }
    for(int i=0;i<E[u].size();i++){
        int v=E[u][i];
        if(!vis[v]){
            int mid=dfs(v, step+1);
            if(mid&&step==mid&&!p)p=u;
        }
    }
    return 0;
}

int dfs2(int u){
    vis[u]=1;
    if(u==p)return 0;
    int add=0;
    for(int i=0;i<E[u].size();i++){
        int v=E[u][i];
        if(!vis[v]){
            add+=dfs2(v);
        }
    }
    return add+1;
}

