int main()
{
	int N;
	cin >> N;

	vector<vector<int>> tree(N);

	for (int i = 0; i < N - 1; ++i)
	{
		int a, b; cin >> a >> b;

		tree[a - 1].emplace_back(b - 1);
		tree[b - 1].emplace_back(a - 1);
	}

	int sunuke = 1;
	vector<bool> used(N, false);

	stack<int> S;

	S.push(N - 1);
	used[N - 1] = true;

	while(!S.empty())
	{
		int v = S.top();
		S.pop();

		for (int u : tree[v])
		{
			if (!used[u] && u != 0)
			{
				S.push(u);
				used[u] = true;
				sunuke += 1;
			}
		}
	}

	if (N % 2 == 0) {
		if (sunuke >= N / 2) {
