    q.push(0);
    pf[0] = P(0,0);
    while (!q.empty()) {
        int now = q.front();
        q.pop();
        REP(i,p[now].size()){
            if(pf[p[now][i]].first==-1){
                pf[p[now][i]] = P(pf[now].first+1,now);
                q.push(p[now][i]);
            }
        }
    }
    //queue<int> q;
    vector<P> pb(n,P(-1,-1));
    q.push(n-1);
    while (!q.empty()) {
        int now = q.front();
