                pb[p[now][i]] = P(pb[now].first+1,now);
                q.push(p[now][i]);
            }
        }
    }
    //int mid = -1;
    if(pf[n-1].first%2==0){
        int d = (pf[n-1].first-1)/2;
        int v = n-1;
        REP(i,d){
            v = pf[v].second;
        }
        int cnt = -1;
