        while(!q.empty()){
            int now = q.front();
            q.pop();
            visited[now] = true;
            if(now!=v){
                cnt++;
                REP(i,p[now].size()){
                    if(!visited[p[now][i]]){
                        q.push(p[now][i]);
                    }
                }
            }
        }
        int pcnt = n-2-cnt;
        if(cnt>pcnt){
            put("Fennec");
        }else{
            put("Snuke");
        }
        return 0;
    }else{
        int d = (pf[n-1].first-1)/2;
        int v = n-1;
        REP(i,d){
            v = pf[v].second;
        }
        int cnt = -1;
