    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    std::cin >> N;

    CommonGraph g(N,
                  CommonGraph::Type::Normal,
                  CommonGraph::Edge::Type::Undirected);
    REP(i, N - 1) {
        int a, b;
