        g.addEdge(a - 1, b - 1, 1);
    }

    vector<int> b_table(N, -1), w_table(N, -1);
    b_table[0] = 0;
    g.dfs(b_table, 0);

    w_table[N - 1] = 0;
    g.dfs(w_table, N - 1);

    int b_draw_num = 0;
    REP(i, N) {
        if(b_table[i] <= w_table[i]) {
            b_draw_num++;
        }
    }

    std::cout << ((N / 2 < b_draw_num) ? "Fennec" : "Snuke") << std::endl;

    return 0;
}

