template<typename T>
class Queue {
    T *que;
    T *head, *tail;
    int capacity;
public:
    Queue() {}
    Queue(int capacity):capacity(capacity) {
        que=new T[capacity];
        head=tail=que;
    }
    ~Queue() { delete[] que; }
    void push(T x) { *tail++=x; }
    T front() { return *head; }
    void pop() { head++; }
    size_t size() const { return tail-head; }
    bool empty() const { return head==tail; }
    void clear() { head=tail=que; }
};

