using namespace std;
typedef int64_t ll;
typedef vector<pair<ll,ll>> vpll;
struct UnionFind {
    static const int MAX_N = 100005;
    int par[MAX_N]; // 親
    int rank[MAX_N]; // 木の深さ
    UnionFind() {
    }
    // n要素で初期化
    void init(int n) {
        for (int i = 0; i < n; i++) {
            par[i] = i;
            rank[i] = 0;
        }
    }
    // 木の根を求める
    int find(int x) {
        if (par[x] == x) {
            return x;
        }
        else {
            return par[x] = find(par[x]);
        }
    }
    // xとyの属する集合を併合
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) {
            return;
        }
        if (rank[x] < rank[y]) {
            par[x] = y;
        }
        else {
            par[y] = x;
            if (rank[x] == rank[y]) {
                rank[x]++;
            }
        }
    }
    // xとyが同じ集合に属するか否か
    bool same(int x, int y) {
        return find(x) == find(y);
    }
};
UnionFind uf;
struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll N;
        in >> N;
        vpll f(N), s(N);
        uf.init(N + 1);
        rep(i, N) {
            ll a, b;
            in >> a >> b;
            f[i].first = min(a, b);
            f[i].second = max(a, b);
            f[i].second *= -1;
            s[i].first = max(a, b);
            s[i].second = min(a, b);
            s[i].second *= -1;
        }
        sort(f.begin(), f.end());
        sort(s.begin(), s.end());
        reverse(s.begin(), s.end());
        rep(i, 2 * N - 1) {
            ll a, b;
            if (i % 2 == 0) {
                a = f[i / 2].first;
                b = -f[i / 2].second;
            }
            else {
                a = s[i / 2].first;
                b = -s[i / 2].second;
            }
            if (a != 1 && b != N && a != N && b != 1) {
                uf.unite(a, b);
            }
            else if (a == 1 || b == 1) {
                if (!uf.same(N, a) && !uf.same(N, b)) {
                    uf.unite(a, b);
                }
            }
            else if (a == N || b == N) {
                if (!uf.same(1, a) && !uf.same(1, b)) {
                    uf.unite(a, b);
                }
            }
        }
        ll fe = 0, su = 0;
        rer(i, 1, N) {
            fe += uf.same(1, i);
            su += uf.same(N, i);
        }
        out << (fe >= su ? "Fennec" : "Snuke") << endl;
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
