class Node {
public:
  std::vector<int> neighbor;
};

std::vector<int> bfs(std::vector<Node>& graph, const int& n, int s) {
  std::vector<int> dist(n+1, -1);
  dist[s] = 0;
  std::queue<int> visit;
  visit.push(s);
  while (!visit.empty()) {
    int u = visit.front(); visit.pop();
    for (int node : graph[u].neighbor) {
      if (dist[node] == -1) {
        dist[node] = dist[u] + 1;
        visit.push(node);
      }
    }
  }
  return dist;
}

int main() {
  int n;
  std::cin >> n;
  std::vector<Node> graph(n + 1);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    std::cin >> a >> b;
    graph[a].neighbor.push_back(b);
    graph[b].neighbor.push_back(a);
  }
  std::vector<int> d_f = bfs(graph, n, 1);
  std::vector<int> d_s = bfs(graph, n, n);
  int f = 0, s = 0;
  for (int i = 1; i <= n; ++i) {
    if (d_f[i] <= d_s[i])
      f++;
    else
      s++;
  }
  if (f > s)
    printf("Fennec\n");
  else if (s >= 1)
    printf("Snuke\n");
}

