//配列管理がウザったいので番号は全て-1しよう

vector <int>recursion(vector <vector <int>>neighbor, vector <int> path,int N, int current,int before_node){
	int before_size;

	//再帰深さ優先
	for(int i=0 ; i<neighbor[current].size() ; i++){
		//呼び出し元除外
		if(neighbor[current][i]==before_node)continue;
		//パスを追加
		path.push_back(neighbor[current][i]);
		//目的地N-1を見つけたら探索をやめてパスを返す
		if(neighbor[current][i]==N-1){
			if(path.size()==1)path.pop_back();
			return path;
		}
		path=recursion(neighbor,path,N,neighbor[current][i],current);
		//探索終了判定
		if(before_size<path.size())break;
	}
	path.pop_back();
	return path;
}

int search_counter(vector <vector <int>>neighbor, int current,int offset,int point,int before_node){
	point+=1;
	for(int i=0 ; i<neighbor[current].size() ; i++){
		//呼び出し元除外
		if(neighbor[current][i]==before_node)continue;
		if(neighbor[current][i]==offset)continue;
		point=search_counter(neighbor,neighbor[current][i],offset,point,current);
	}
	return point;
}

int main(){
	int N;
