    vector <int>a(N-1);
	vector <int>b(N-1);
    for(int i=0 ; i<N-1 ; i++){
        cin>>a[i];
    	cin>>b[i];
    	a[i]-=1;
    	b[i]-=1;
    }
	vector <vector <int>> neighbor(N);
	vector <int>path;
	int white=0,black=0,b_offset,w_offset,address;

	//隣接関係を作る
	for(int i=0 ; i<N-1 ; i++){
		neighbor[a[i]].push_back(b[i]);
		neighbor[b[i]].push_back(a[i]);
	}

	//0番からN-1番までのパスを受け取る
	path=recursion(neighbor,path,N,0,0);
	address=(int)(path.size()/2);
	if(path.size()==0){
		b_offset=N-1;
		w_offset=0;
	}
	else if(path.size()%2==0){
		b_offset=path[address];
		w_offset=path[address-1];
	}
	else if(path.size()%2==1){
		b_offset=path[address+1];
		w_offset=path[address];
	}

	black=search_counter(neighbor,0,b_offset,black,0);
	white=search_counter(neighbor,N-1,w_offset,white,0);

	if(white>=black)cout<<"Snuke\n";
	else cout<<"Fennec\n";
	return 0;
}

