    {
        if (checkMap[0][i] != N - 1)
        {

            PathData pd;
            pd.pos = checkMap[0][i];
            pd.dist = 1;
            pd.set.emplace(0);
            PQueue.push(pd);
        }
    }
    fennecMap[0] = 0;

