int dfs(int i, int now) {
    tr[now] = false;
    if (now == n - 1) return i;
    int mn = inf;
    if (!tr[G[now][0]]) {
        if (G[now].size() == 1) return inf;
    }
    for (int j = 0; j < G[now].size(); j++) {
        if (G[now][j]) mn = min(mn, dfs(i + 1, G[now][j]));
    }
