int par[100010], rnk[100010], sze[100010];

// 初期化
void init(int n) {
    for (int i = 0; i < n; i++) {
        par[i] = i;
        rnk[i] = 0;
        sze[i] = 1;
    }
}

// 親探し
int find(int x) {
    if (par[x] == x) return x;
    else return par[x] = find(par[x]);
}

// 併合
void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rnk[x] < rnk[y]) {
        par[x] = y;
        sze[y] = sze[x] + sze[y];
    }
    else {
        par[y] = x;
        if (rnk[x] == rnk[y]) rnk[x]++;
        sze[x] = sze[x] + sze[y];
    }
}

// 同じ木にあるか
bool same(int x, int y) {
    return find(x) == find(y);
}

