            int tmp = a[i];
            a[i] = b[i];  b[i] = tmp;
        }
        a[i]--;  b[i]--;
        G[a[i]].push_back(b[i]);
        G[b[i]].push_back(a[i]);
    }

    int y = dfs(0, 0) - 1;

    fill(tr, tr + n, true);
    int x = 0;
    for (int i = 0; i < G[0].size(); i++) {
        init(n);
        for (int j = 0; j < n - 1; j++) {
            if (a[j] == 0 && b[j] == G[0][i]) ;
            else unite(a[j], b[j]);
        }
        if (!same(G[0][i], n - 1)) x += sze[G[0][i]];
    }

    int z = n - x - y - 2;

    if (x + y % 2 > z) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

    //cout << x << " " << y << " " << z << endl;
}

