vll bfs(ll n, vector<vll> &next, ll start, ll goal) {
  queue<ll> task;
  task.push(start);
  queue<ll> task2;
  task2.push(goal);

  vll seen(n, 0);
  seen[start] = 1;
  vll seen2(n, 0);
  seen2[goal] = 1;

  while (1) {
    for (ll j = 0; j < next[task.front()].size(); j++) {
      if (seen[next[task.front()][j]] == 0 && seen2[next[task.front()][j]] == 0) {
        task.push(next[task.front()][j]);
        seen[next[task.front()][j]] = 1;
      }
      else if (seen[next[task.front()][j]] == 0) {
        return {task.front(), next[task.front()][j]};
      }
    }
    task.pop();

    for (ll j = 0; j < next[task2.front()].size(); j++) {
      if (seen[next[task2.front()][j]] == 0 && seen2[next[task2.front()][j]] == 0) {
        task2.push(next[task2.front()][j]);
        seen2[next[task2.front()][j]] = 1;
      }
      else if (seen2[next[task2.front()][j]] == 0) {
        return {next[task2.front()][j], task2.front()};
      }
    }
    task2.pop();
  }
}

ll bfs2(ll n, vector<vll> &next, ll start, ll goal) {
  queue<ll> task;
  task.push(start);

  vll seen(n, 0);
  seen[start] = 1;
  seen[goal] = 1;

  ll cnt = 0;
  while (task.size() > 0) {
    for (ll j = 0; j < next[task.front()].size(); j++) {
      if (seen[next[task.front()][j]] == 0) {
        cnt++;
        task.push(next[task.front()][j]);
        seen[next[task.front()][j]] = 1;
      }
    }
    task.pop();
  }
  return cnt;
}

