const int INF = 20000000;

void dfs(int v, int p, vector<int> &dist, vector<int> G[]) {
  if (dist[v] != INF) return;
  if (p != -1) dist[v] = dist[p] + 1;
  else dist[v] = 0;
  for (auto&u: G[v]) {
    if (dist[u] != INF) continue;
    dfs(u, v, dist, G);
  }
}


void bfs(int start, vector<int> &dist, vector<int> G[]) {
  queue<int> Q;
  Q.push(start);
  dist[start] = 0;
  while (Q.size()) {
    int v = Q.front(); Q.pop();
    for (auto &&u: G[v]) {
      if (dist[u] != INF) continue;
      dist[u] = dist[v] + 1;
      Q.push(u);
    }
  }
}

/*
 両者、とれるコマの中で最も相手に近いものから取るのが最善.
 それを実際にシミュレートする.
 優先度付きキューを用いて相手までの距離が短い方から埋めていく.
 先におけるコマが無くなったほうが負け.
*/
void solve(int n, int s, int t, vector<int> &fromS, vector<int> fromT, vector<int> G[]) {
  vector<bool> done(n, false);
  priority_queue<pair<int, int> > Qs, Qt;
  Qs.push({ fromT[s], s });
  Qt.push({ fromS[t], t });
  while (Qs.size() and Qt.size()) {
    auto qs = Qs.top(); Qs.pop();
    while (done[qs.second] and Qs.size()) {
      qs = Qs.top(); Qs.pop();
    }
    if (done[qs.second]) {
      print("Snuke");
      return;
    }
    done[qs.second] = true;

    auto qt = Qt.top(); Qt.pop();
    while (done[qt.second] and Qt.size()) {
      qt = Qt.top(); Qt.pop();
    }
    if (done[qt.second]) {
      print("Fennec");
      return;
    }
    done[qt.second] = true;

    // print("Fennec", " ");
    // print(qs.second+1);
    // print("Snuke", " ");
    // print(qt.second+1);
    {
      for (auto &&u: G[qs.second]) {
        if (done[u]) continue;
        Qs.push({ -fromT[u], u }); // Tに近い方から取る.
      }
    }
    {
      for (auto &&u: G[qt.second]) {
        if (done[u]) continue;
        Qt.push({ -fromS[u], u }); // Sに近い方から取る.
      }
    }
  }

  if (Qs.size()) print("Fennec");
  else print("Snuke");
}


/*
 Fennec、Snukeそれぞれにより近い点を数える.
 Fennecの方が真に大きければFennecの勝ち.
 等しい場合は、Fennec->Snukeという順番だとFennecが先に塗れなくなるのでSnukeの勝ち.
*/
void solve2(int n, int s, int t, vector<int> &fromS, vector<int> &fromT, vector<int> G[]) {
  int fennec = 0;
  loop(i,0,n) {
    // TよりもSに近いところはFennecが取れる.
    fennec += fromS[i] <= fromT[i];
  }
  int snuke = n-fennec;
  if (fennec > snuke) print("Fennec");
  else print("Snuke");
}

int main() {
  int n;in(n);
  vector<int> G[n];
  loop(i,0,n-1) {
    int a, b; in(a),in(b);
    a--;b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  int s = 0, t = n-1;
  vector<int> fromS(n, INF), fromT(n, INF);
  // dfs(s, -1, fromS, G);
  // dfs(t, -1, fromT, G);
  bfs(s, fromS, G);
  bfs(t, fromT, G);

  solve2(n, s, t, fromS, fromT, G);
  return 0;
}

