class Edge {
public:
    ll t, w;
    Edge (ll t, ll w): t(t), w(w) {}
};

ll N;
vector<Edge> G[MAX_V];
ll d[MAX_V], color[MAX_V];
ll dis_Fen[MAX_V], dis_Sun[MAX_V];

void dijkstra(ll s) {
    ll i, u;
    for(i=0; i<N; i++) {
        d[i]=INF;
        color[i]=WHITE;
    }
    priority_queue<P> PQ;
    PQ.push(P(0, s));
    d[s]=0;

    while(PQ.size()) {
        P f=PQ.top(); PQ.pop();
        u=f.second;

        color[u]=BLACK;
        if(d[u]<f.first*(-1)) continue;

        for(i=0; i<G[u].size(); i++) {
            Edge &e=G[u][i];
            if(color[e.t]!=BLACK && d[e.t]>d[u]+e.w) {
                d[e.t]=d[u]+e.w;
                PQ.push(P(-d[e.t], e.t));
            }

        }

    }

}


void add_edge(ll s, ll t, ll w) {
    G[s].push_back(Edge(t, w));
    G[t].push_back(Edge(s, w));
}

