const int MAX_N = 100000;
int N;
set<int> adj[MAX_N + 1];
bool colored[MAX_N + 1];
set<int> can_fill_black, can_fill_white;

void move_to_adj(set<int>& my_next_candidates, set<int>& your_next_candidates) {
    // fill black
    int next_best = -1;
    int max_profit = -1;
    for (auto b : my_next_candidates) {
        if (your_next_candidates.find(b) != your_next_candidates.end()) {
            next_best = b;
            break;
        }

        int profit = 0;
        for (auto ab : adj[b]) {
            if (colored[ab]) continue;
            profit++;
        }

        if (max_profit < profit) {
            max_profit = profit;
            next_best = b;
        }
    }

//    cout << "select: " << next_best << endl;
    // move to best
    colored[next_best] = true;
    my_next_candidates.erase(next_best);
    for (auto ab : adj[next_best]) {
        if (colored[ab]) continue;
        my_next_candidates.insert(ab);
    }

    if (your_next_candidates.find(next_best) != your_next_candidates.end()) your_next_candidates.erase(next_best);
}

void solve() {
    colored[1] = colored[N] = true;
    for (auto b : adj[1]) {
        if (!colored[b]) can_fill_black.insert(b);
    }
    for (auto w : adj[N]) {
        if (!colored[w]) can_fill_white.insert(w);
    }

//    cout << can_fill_black.size() << " " << can_fill_white.size() << endl;
    while (true) {
//        cout << "move black" << endl;
        // fill black
        if (can_fill_black.size() == 0) {
            cout << "Snuke" << endl;
            break;
        }
        move_to_adj(can_fill_black, can_fill_white);
//        cout << can_fill_black.size() << " " << can_fill_white.size() << endl;

//        cout << "move white" << endl;
        if (can_fill_white.size() == 0) {
            cout << "Fennec" << endl;
            break;
        }
        move_to_adj(can_fill_white, can_fill_black);
//        cout << can_fill_black.size() << " " << can_fill_white.size() << endl;
    }
}

