int bfs(int x , int y)
{
    queue<pii> q;
    q.push(pii(x , 0));
    vis[x] =1;

    while(!q.empty()){
        pii p = q.front();
        int u = p.first;
        vis[u] = 1;

        q.pop();
        for(int i = 0 ; i < G[u].size() ; i++){
            int v= G[u][i];
            if(v == y){
                cnt2 = p.second;
            }
            else if(vis[v] == 0){
              q.push(pii(v , p.second+1));
              //cnt++;
              cnt++;
            }
        }
    }
    return cnt - cnt2;
}

