        if(x != -1) c = x;
    }
    return col[v] = c;
}

void solve() {
	cin >> n;
    g.assign(n, vector<int>());
    rep(i, n - 1) {
        int a, b; cin >> a >> b;
        -- a, -- b;
        g[a].pb(b);
        g[b].pb(a);
    }
    col.assign(n, -1);
    vector<int> d(n, -1);
    dfs(0, -1, 0, d);
    int di = d[n - 1];
    rep(i, n) {
        if(d[i] <= di / 2) {
            col[i] = 0;
        }
    }
    vector<int> e(n, -1);
    dfs(n - 1, -1, 0, e);
    rep(i, n) {
        if(e[i] <= (di - 1) / 2) {
            col[i] = 1;
        }
    }
    rep(i, n) {
        if(col[i] == -1) {
            ddfs(i, -1);
        }
    }
    int cnt0 = 0;
    rep(i, n) {
        if(col[i] == 0) ++ cnt0;
    }
    if((n + 1) / 2 <= cnt0) {
        cout << "Fennec" << endl;
    } else {
        cout << "Snuke" << endl;
    }
}

