int v,o;
int bfs(int t) {
	v=t;
	if(t==0)
		return o;
	int f=1;
	for(int i=0; i<n; i++) {
		if(absd[i][t]==1&&!b[i])f=0,at[v]=++o;
	}
	if(f) {
		b[t]=1;
		v=2,o=0;
		return bfs(1);
	}
}
int check(int y) {
	int ans=0;
	if(at[y]==0) {
		for(int i=0; i<n; i++) {
			if(absd[i][y]==0&&at[i]==0)ans++,y=i;
		}
	}
	return ans;
}
int main() {
	at[1]=1;
	int n;
	for(int i=0; i<n; i++) {
		int a,b;
		cin>>a>>b;
		if(a>b)
			absd[b][a]=true;
		else
			absd[a][b]=true;
	}
	ab[0]=2;
	ab[1]=3;
	int ast=bfs(2);
	int d1=0,d2=1;
	int q=2,i=0;
	int h=1;
	while(true) {
		if(!i) {
			for(int j=0; j<n; j++) {
				if(absd[j][d1]&&!at[j]&&check(j)>ast-q) {
					cout<<"Fennec";
					return 0;
				}
			}
			for(int j=0; j<n; j++) {
				if(at[j]==q-2&&ab[j]==3&&!check(j)) {
					cout<<"Snuke";
					return 0;
				} else if(at[j]==q-2&&ab[j]!=2&&ab[j]!=3)ab[j]=2,i++,q++;
			}
		} else {
			for(int j=0; j<n; j++) {
				if(absd[j][d1]&&!at[j]&&check(j)>ast-q) {
					cout<<"Snuke";
					return 0;
				}
			}
			for(int j=0; j<n; j++) {
				if(at[j]==q-2&&ab[j]==3&&!check(j)) {
					cout<<"Fennec";
					return 0;
				} else if(at[j]==q-2&&ab[j]!=2&&ab[j]!=3)ab[j]=3,i--,q++;
			}
		}
		if(ast-q==0) {
			h=0;
			break;
		}
	}
	if(h==0)
		cout<<"Snuke";
	return 0;
}

