vector<vector<long>> tree(1e5+1);
void f(long k,vector<long>& d){
    queue<long> q;
    q.push(k);
    while(!q.empty()){
        long t=q.front(); q.pop();
        for(auto x:tree[t]){
            if(x!=k&&d[x]==0){
                d[x]=d[t]+1;
                q.push(x);
            }
        }
    }
}
int main(){
    long n; cin>>n;
    for(int i=0;i<n-1;i++){
        long a,b; cin>>a>>b;
        tree[a].push_back(b);
        tree[b].push_back(a);
    }
    vector<long> df(n+1,0),ds(n+1,0);
    f(1,df);
    f(n,ds);
    long sum=0;
    for(int i=1;i<=n;i++)
        sum+=df[i]<=ds[i]?1:-1;
