const int SIZE = 100000+10;
vector<int> vec[SIZE];
int step[SIZE];
queue<int> que;
int N;
int size_1 = 0;

void BFS()
{

	while( que.size() ){
		int now = que.front();que.pop();
		for(int i:vec[now]){
			if( step[i] == -1 && i!=N ){
				//printf("* %d\n",i);
				step[i] = step[now]+1;
				que.push(i);
				size_1++ ;
			}
		}
	}
}


inline void init()
{
	for(int i=0;i<SIZE;i++)
		step[i] = -1;
}
int main (void)
{
	init();

	scanf("%d",&N);
	for(int i=1;i<N;i++){
		int a,b;
		scanf("%d %d",&a,&b);
		vec[a].pb(b);
		vec[b].pb(a);		
	}
	que.push(1);
	step[1] = 0;
	BFS();

	int fix = step[N];
	fix--;
	size_1 -= (fix+1)/2;


	//printf("%d\n",size_1);

	size_1 >= N/2? puts("Fennec") : puts("Snuke");

	return 0;
}





