#include <bits/stdc++.h>
#define ll long long
#define all(x) x.begin(), x.end()
#define rep(i, from, to) for(int i=from; i<(int)to; ++i)
#define REP(i, from, to) for(int i=from; i<=(int)to; ++i)
using namespace std;
static const int INF = INT_MAX;
static const int MAX_N = 100010;
vector<vector<int>> g; //隣接リストによるグラフ表現
vector<int> dist_1, dist_N; //dist_1[i]: 頂点1から頂点iへの距離
bool vis[MAX_N]; //vis[i]: 頂点iは訪問済(1)か否(0)か
int n;
void bfs(int start, vector<int>& dist) {
	fill(all(dist), INF);
	fill(vis, vis + MAX_N, false);
	dist[start] = 0;
	queue<int> que;
	que.push(start);
	while (!que.empty()) {
		int now = que.front();
		que.pop();
		vis[now] = true;
		rep(i,0,g[now].size())
		{
			int next = g[now][i];
			if (!vis[next]) {
				dist[next] = dist[now] + 1;
				que.push(next);
			}
		}
	}

}
void solve() {
	cin >> n;
	g = vector<vector<int> >(n + 1, vector<int>());
	dist_1 = vector<int>(n + 1);
	dist_N = vector<int>(n + 1);
	rep(i,0,n-1)
	{
		int a, b;
		cin >> a >> b;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	bfs(1, dist_1);
	bfs(n, dist_N);
	int fennec = 0, sunuke = 0;
	REP(i,1,n)
	{
		if (dist_1[i] <= dist_N[i]) {
			fennec++;
		} else {
			sunuke++;
		}
	}
	cout << (fennec > sunuke ? "Fennec" : "Snuke'") << endl;
}
int main() {
	solve();
}

