int main(){
  int N;
  cin >> N;
  vector<vector<int>> G(N);
  for(int i=0; i<N-1; i++){
    int a,b;
    cin >> a >> b;
    a--;
    b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  vector<int> dist(N, -1);
  queue<int> que_b;
  queue<int> que_w;
  dist[0] = 0;
  dist[N-1] = 0;
  que_b.push(0);
  que_w.push(N-1);
  int count_b=1;
  int count_w=1;
  int i=1,j=1;
  while(1){
    while(!que_b.empty()){
      int v = que_b.front();
      if(dist[v] > i){
        i++;
        break;
      }
      que_b.pop();
      for(int nv: G[v]){
        if(dist[nv] != -1){
          continue;
        }
        count_b++;
        dist[nv] = dist[v] + 1;
        que_b.push(nv);
      }
    }
    while(!que_w.empty()){
      int v = que_w.front();
      if(dist[v] > j){
        j++;
        break;
      }
      que_w.pop();
      for(int nv: G[v]){
        if(dist[nv] != -1){
          continue;
        }
        count_w++;
        dist[nv] = dist[v] + 1;
        que_w.push(nv);
      }
    }
    if(que_b.empty() && que_w.empty()){
      break;
    }
  }
  if(count_b <= count_w){
    cout << "Snuke" << endl;
  }else{
    cout << "Fennec" << endl;
  }
  return 0;
}

