int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout<<std::setprecision(10);

    ll n;
    cin>>n;
    VV g(n);
    Vec dist(n,INF);
    rep(i,n-1){
        ll a,b;
        cin>>a>>b;
        a--;b--;
        g[a].pb(b);
        g[b].pb(a);
    }

    queue<ll> q;
    q.push(0);

    dist[0] = 0;
    Vec pre(n,-1);
    Vec col(n,-1);

    while(!q.empty()){
        ll now = q.front();
        q.pop();
        Each(nxt,g[now]){
            if(dist[nxt]==INF){
                dist[nxt] = dist[now]+1;
                pre[nxt] = now;
                q.push(nxt);
            }
        }
    }

    //木の最短経路
    Vec way;
    way.pb(n-1);
    q.push(n-1);
    while (!q.empty()){
        ll now = q.front();
        q.pop();
        if(pre[now]!=-1){
            way.pb(pre[now]);
            q.push(pre[now]);
        }
    }
    reverse(ALL(way));

    //色を塗る
    per(c,way.size()-1){
        q.push(way[c]);
        col[way[c]] = c;
        while(!q.empty()){
            ll now = q.front();
            q.pop();
            Each(nxt,g[now]){
                if(pre[now]!=nxt && col[nxt]==-1){
                    col[nxt] = c;
                    q.push(nxt);
                }
            }
        }
    }

    ll bl = 0;
    ll wh = 0;
    rep(i,n){
        if(col[i]<=(way.size()-1)/2){
            bl++;
        }else{
            wh++;
        }
    }

    if(bl>wh){
