vector<int> bfs(int s, Graph &G) {
    int N = G.size();
    vector<int> dist(N, INT_MAX);
    queue<int> que;
    dist[s] = 0;
    que.push(s);
    while (!que.empty()) {
        int v = que.front();
        que.pop();
        for (auto nv : G[v]) {
            if (dist[nv] < INT_MAX)
                continue;
            dist[nv] = dist[v] + 1;
            que.push(nv);
        }
    }
    return dist;
