        while(!q.empty()){
                int qq=q.front();
                flag[qq]=true;
                q.pop();
                for(int i=0;i<(int)ab[qq].size();i++){
                        if(!flag[ab[qq][i]]){
                                Fgraph[ab[qq][i]]=Fgraph[qq]+1;
                                if(ab[qq][i]!=N)
                                        q.push(ab[qq][i]);
                        }
                }
        }

        for(int i=0;i<=N;i++){
                flag[i]=false;
        }

        //Snuke
        Sgraph[N]=0;
        q.push(N);
        while(!q.empty()){
                int qq=q.front();
                flag[qq]=true;
                q.pop();
                for(int i=0;i<(int)ab[qq].size();i++){
