void dijkstra(int s, vi &d) {
	d[s] = 0;
	while (true) {
		int v = -1;
		for (int u = 0; u < N; u++) {
			if (!used[u] && (v == -1 || d[u] < d[v])) v = u;
		}
		if (v == -1) break;
		used[v] = true;
		for (int u = 0; u < N; u++) {
			d[u] = min(d[u], d[v] + G[v][u]);
		}
	}
}

int main(void) {
