		G[a - 1][b - 1] = 1;
		G[b - 1][a - 1] = 1;
	}

	d1.resize(N, INF);
	used.resize(N, false);
	dijkstra(0, d1);

	d2.resize(N, INF);
	used.clear();
	used.resize(N, false);
	dijkstra(N - 1, d2);

	int black = 0;
	for (int i = 1; i < N - 1; ++i) {
		if (d1[i] <= d2[i])
			++black;
	}
	int white = N - 2 - black;

	if (black > white)
		cout << "Fennec\n";
	else
		cout << "Snuke\n";
	return 0;
}

