vector<int> bfs(int src, vector<vector<int>> &Tree) {
  int N = Tree.size();
  vector<int> dist(N, -1);
  dist[src] = 0;

  queue<int> que;
  que.push(src);
  while (!que.empty()) {
    int cur_v = que.front();
    que.pop();
    for (auto nxt_v : Tree[cur_v]) {
      if (dist[nxt_v] != -1) {
        continue;
      }
      dist[nxt_v] = dist[cur_v] + 1;
      que.push(nxt_v);
    }
  }
  return dist;
}

