  vector<int> dist_from_n = bfs(N - 1, Tree);

  int alice = 0;
  int bob = 0;

  for (int i = 0; i < N; i++) {
    if (dist_from_1[i] <= dist_from_n[i]) {
      alice++;
    } else {
      bob++;
    }
  }
  cout << (alice > bob ? "Fennec" : "Snuke") << endl;

