class Graph {
    struct edge {
        int from, to, cost;
        edge(int from, int to, int cost) : from(from), to(to), cost(cost) {}
    };

public:
    int verN;
    int edgeN = 0;
    vector<edge> edge_set;
    vector<vector<pair<int, int>>> adj_list;
    Graph(int verN) : verN(verN), adj_list(verN) {}

    void add_directed_edge(int from, int to, int cost = 1) {
        edge_set.push_back(edge(from, to, cost));
        adj_list[from].push_back(make_pair(to, cost));
        edgeN++;
    }

    void add_undirected_edge(int from, int to, int cost = 1) {
        edge_set.push_back(edge(from, to, cost));
        edge_set.push_back(edge(to, from, cost));
        adj_list[from].push_back(make_pair(to, cost));
        adj_list[to].push_back(make_pair(from, cost));
        edgeN += 2;
    }

    bool _cycleDetection(int now, int prev, vector<int> &seen, vector<int> &used, vector<int> &cycle) {
        if (used[now]) {
            return false;
        }
        if (seen[now]) {
            cycle.push_back(now);
            return true;
        }

        seen[now] = true;

        for (auto adj_pair : adj_list[now]) {
            int adj = adj_pair.first;
            if (prev == adj)
                continue;
            bool hasDetected = _cycleDetection(adj, now, seen, used, cycle);
            if (hasDetected) {
                cycle.push_back(now);
                return true;
            }
        }
        used[now] = true;

        seen[now] = false;

        return false;
    }

    bool cycleDetection(vector<int> &cycle) {
        cycle.reserve(N);
        vector<int> seen(N);
        vector<int> used(N);
        for (int start = 0; start < N; start++) {
            bool hasDetected = _cycleDetection(start, -1, seen, used, cycle);
            if (hasDetected) {
                for (int i = 1; i < (int)cycle.size(); i++) {
                    if (cycle[i] == cycle[0]) {
                        cycle.erase(cycle.begin() + i + 1, cycle.end());
                    }
                }
                reverse(cycle.begin(), cycle.end());
                //cycle.pop_back();
                return 1;
            }
        }
        return 0;
    }

    bool bellmanford(int start, vector<int> &d) {
        d.assign(verN, INF);
        for (int i = 0; i < verN; i++) {
            d[i] = INF;
        }
        d[start] = 0;
        for (int i = 0; i < verN; i++) {
            for (int j = 0; j < edgeN; j++) {
                edge e = edge_set[j];
                if (d[e.from] != INF && d[e.to] > d[e.from] + e.cost) {
                    d[e.to] = d[e.from] + e.cost;
                    if (i == verN - 1) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    vector<int> dijkstra(int start) {
        vector<int> d(verN, INF);
        d[start] = 0;
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        vector<int> used(verN, 0);
        pq.push(make_pair(0, start));
        while (!pq.empty()) {
            int now = pq.top().second;
            pq.pop();
            used[now] = 1;
            for (auto adj_pair : adj_list[now]) {
                int adj = adj_pair.first;
                int dist = adj_pair.second;
                if (used[adj])
                    continue;
                if (d[adj] > d[now] + dist) {
                    d[adj] = d[now] + dist;
                    pq.push(make_pair(d[adj], adj));
                }
            }
        }
        return d;
    }

    vector<vector<int>> warshallfloyd() {
        vector<vector<int>> d(verN, vector<int>(verN, INF));
        for (int i = 0; i < verN; i++) {
            for (auto adj_pair : adj_list[i]) {
                int adj = adj_pair.first;
                int dist = adj_pair.second;
                d[i][adj] = dist;
            }
        }
        for (int i = 0; i < verN; i++) {
            d[i][i] = 0;
        }
        for (int k = 0; k < verN; k++) {         // 経由する頂点
            for (int i = 0; i < verN; i++) {     // 始点
                for (int j = 0; j < verN; j++) { // 終点
                    if (d[i][k] != INF && d[k][j] != INF)
                        d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
                }
            }
        }
        return d;
    }
};

vector<int> Centroid(const vector<vector<pair<int, int>>> &g) {
    int n = g.size();
    vector<int> centroid;
    vector<int> sz(n);
    function<void(int, int)> dfs = [&](int u, int prev) {
        sz[u] = 1;
        bool is_centroid = true;
        for (auto adj : g[u]) {
            int v = adj.first;
            if (v != prev) {
                dfs(v, u);
                sz[u] += sz[v];
                if (sz[v] > n / 2)
                    is_centroid = false;
            }
        }
        if (n - sz[u] > n / 2)
            is_centroid = false;
        if (is_centroid)
            centroid.push_back(u);
    };
    dfs(0, -1);
    return centroid;
}

signed main() {
    cin >> N;
    Graph g(N);
    REP(i, N - 1) {
        cin >> A >> B;
        A--, B--;
        g.add_undirected_edge(A, B);
    }
    auto c = Centroid(g.adj_list);
    auto d0 = g.dijkstra(0);
    auto d1 = g.dijkstra(N - 1);
    int f = INF;
    REP(i, c.size()) {
        f = min(f, d0[c[i]]);
    }
    int s = INF;
    REP(i, c.size()) {
        s = min(s, d1[c[i]]);
    }
    if (f <= s)
        cout << "Fennec" << endl;
    else
        cout << "Snuke" << endl;
}

