  queue<Pl> q;
  q.push(Pl(0, 0));
  q.push(Pl(n-1, 1));

  vector<ll> area(n, -1);
  area[0] = 0;
  area[n-1] = 1;

  vector<ll> cntwho(2, 0);

  while(!q.empty()) {
    ll pos = q.front().first;
    ll who = q.front().second;
    q.pop();

    rep(i, ll(G[pos].size())) {
      ll to =G[pos][i];
      if (area[to] != -1) continue;
      q.push(Pl(to, who));
      area[to] = who;
      cntwho[who]++;
    }
  }

  if (cntwho[0] > cntwho[1]) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;

  return 0;
}

