int bfs(int s,int goal){
    memset(used,false,sizeof(used));
    queue<int> que;
    que.push(s);
    used[s]=true;
    int cnt=0;
    while(!que.empty()){
        int u=que.front(); que.pop();
        if(u==goal) continue;
