		add_edge(g, a, b, 1, true, 1);
	}

	queue<pair<ll,ll>> que;
	Array con(2, 0);
	Array used(n, false);

	que.push(make_pair(0, 0));
	que.push(make_pair(n-1, 1));
	while (que.size() > 0) {
		ll v=que.front().first;
		ll co = que.front().second;
		con[co]++;
		que.pop();
		for (auto e : g[v]) {
			if (!used[e.to]) {
				que.push(make_pair(e.to, co));
				used[e.to] = true;
			}
		}
	}

	if (con[0] > con[1]) {
		cout << "Fennec" << endl;
	}
	else {
		cout << "Snuke" << endl;
	}


	return 0;
}

