				color[v] = (dist[n-1]/2 < dist[v]) ? 0 : 1;
				now = v;
				if(now == 0) {
					finish = true;
				}
				break;
			}
		}
		if(finish) break;
	}
	{
		// 黒を塗ります。
		int start = 0;
		vector<int> dist(n, -1);	//startからの距離を格納。未訪問は-1
		queue<int> que;
