			int v = que.front();
			que.pop();
			for(int nv: g[v]) {
				if(dist[nv] != -1) continue;
				if(color[nv] == 1) continue;
				dist[nv] = dist[v] + 1;
				color[nv] = 0;
				que.push(nv);
			}
		}
	}
	{
		// 白を塗ります。
		int start = n-1;
		vector<int> dist(n, -1);	//startからの距離を格納。未訪問は-1
		queue<int> que;
		dist[start] = 0;
		que.push(start);
		while(!que.empty()) {
			int v = que.front();
			que.pop();
			for(int nv: g[v]) {
				if(dist[nv] != -1) continue;
				if(color[nv] == 0) continue;
				dist[nv] = dist[v] + 1;
				color[nv] = 1;
				que.push(nv);
			}
		}
	}
	int cnt = 0;
	rep(i, n) if(color[i] == 0) cnt++;
