int N;
int m;

void discalc(int a, int d){
    dis[a] = d;
    for(int p : to[a]){
        if(dis[p] != INF)continue;
        discalc(p, d+1);
    }
    return;
}

bool road(int a){
    if(a == N-1){
        return check[a] = true;
    }
    if(a != 0 && to[a].size() == 1){
        return false;
    }
    for(int p : to[a]){
        if(dis[p] < dis[a])continue;
        if(road(p))return check[a] = true;
    }
    return false;
}

void coloring(int a, int d){
    color[a] = 1;
    if(d == m)return;
    for(int p : to[a]){
        if(check[p])coloring(p, d+1);
    }
    return;
}

void coloring2(int a){
    color[a] = 1;
    for(int p : to[a]){
        if(color[p] != 0)continue;
        coloring2(p);
    }
    return;
}

int main() {
    cin >> N;
    rep(i, N-1){
        int a, b; cin >> a >> b;
        a--; b--;
        to[a].push_back(b);
        to[b].push_back(a);
    }

    discalc(0, 0);
    road(0);

    m = (dis[N-1]-2) / 2;
    coloring(N-1, 0);
    rep(i, N){
        if(check[i] && color[i] == 0){
            color[i] = 2;
        }
    }
    rep(i, N){
        if(color[i] != 2){
            color[i] = 0;
        }
    }
    coloring2(N-1);

    int cnt = 0;
    rep(i, N){
        if(color[i] == 1){
            cnt++;
        }
    }

    int need = (N+1)/2;
    if(cnt >= need){
        cout << "Snuke" << endl;
    } else {
        cout << "Fennec" << endl;
    }

    return 0;
}

