    }
    tree.run();
    int ans = 0;
    rep(i, n)
    {
        if (tree.cost1[i + 1] <= tree.cost2[i + 1])
            ans += 1;
        else
            ans -= 1;
    }
    if (ans <= 0)
    {
        print("Snuke");
    }
    else
    {
        print("Fennec")
    };

    return 0;
}

