using namespace std;

typedef pair<int, int> P;

vector<int> graph[100005];
bool used[100005];
int cnt = 0;

// s-t間s-leafnode間にある頂点数を数える(sとtを除く)
// 実行前に、cnt=0,used=false(但し、used[s]=true)と初期化
void dfs(int s, int t){
    if(s == t){
        --cnt;
        return;
    }

    // leafnodeまで辿り着くと、この走査はすべてcontinueされる
    for(int i = 0; i < graph[s].size(); ++i){
        int v = graph[s][i];
        if(used[v])     continue;

        used[v] = true;
        // 子ノードに対して再帰するたびにcntをインクリメント
        dfs(v, t);
        ++cnt;
    }

    return;
}

// s-t間にある頂点数を数える
// 実行前に、cnt=0,used=false(但し、used[s]=true)と初期化
int bfs(int s, int t){
    queue<P> que;
    que.push(P(s, 0));

    while(!que.empty()){
        P p = que.front();
        que.pop();
        int v = p.first;
        int d = p.second;

        // これが求めたい数
        if(v == t)      return d;

        for(int i = 0; i < graph[v].size(); ++i){
            int v1 = graph[v][i];

            if(used[v1])    continue;

            used[v1] = true;
            que.push(P(v1, d + 1));
        }
    }

    return -1;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    // 0-indexed
    for(int i = 0; i < n-1; ++i){
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    // 0からみた頂点数
    fill(used, used + n, false);
    used[0] = true;
    cnt = 0;
    dfs(0, n-1);
    int cnt1 = cnt;

    // n-1からみた頂点数
    fill(used, used + n, false);
    used[n-1] = true;
    cnt = 0;
    dfs(n-1, 0);
    int cnt2 = cnt;

    // 0-n-1間の頂点数
    fill(used, used + n, false);
    used[0] = true;
    cnt = 0;
    bfs(0, n-1);
    int cnt3 = cnt;

    if(cnt3 % 2 == 0){
        cnt1 -= cnt3;
        cnt2 -= cnt3;
        if(cnt1 > cnt2){
            cout << "Fennec\n";
        }
        else{
            cout << "Snuke\n";
        }
    }
    else{
        cnt1 -= cnt3;
        cnt2 -= cnt3;
        if(cnt1 < cnt2){
            cout << "Snuke\n";
        }
        else{
            cout << "Fennec\n";
        }
    }
}

