            if (trace_fwd[graph[q][i]] < 0) {
                trace_fwd[graph[q][i]] = q;
                que.push(graph[q][i]);
            }
        }
    }

    vector<int> trace(0);
    for (int i = 0; i != n - 1; i = trace_fwd[i]) {
        trace.push_back(i);
    }
