    int f_rem = 0, s_rem = 0;
    for (int fi = 1, si = trace.size() - 2; fi <= si; fi++, si--) {
        f_rem += graph[trace[fi]].size() - 2;
        if (fi < si) {
            s_rem += graph[trace[si]].size() - 2;
        }
    }

