  cin >> N;
  vector<Node> nvec;
  for (int i = 0; i < N; i++) {
    Node temp;
    nvec.push_back(temp);
    check[i] = 0;
  }
  check[0] = 1;
  check[N-1] = -1;
  for (int i = 0; i < N-1; i++) {
    int a, b;
    scanf("%d %d\n", &a, &b);
    a--; b--;
    nvec.at(a).connect.push_back(b);
    nvec.at(b).connect.push_back(a);
  }
  list<int> univB, univW;
  univB.push_back(0);
  univW.push_back(N-1);
  int countB, countW;
  countB = countW = 1;
  while(1) {
    int bcB, bcW;
    bcB = countB;
    bcW = countW;
    int sizeB = univB.size();
    int sizeW = univW.size();
    for (auto x: univB) {
      for (auto y: nvec.at(x).connect) {
	if (check[y] == 0) {
	  univB.push_back(y);
	  check[y] = 1;
	  countB++;
	}
      }
    }
    for (int i = 0; i < sizeB; i++) {
      univB.pop_front();
    }

    for (auto x: univW) {
      for (auto y: nvec.at(x).connect) {
	if (check[y] == 0) {
	  univW.push_back(y);
	  check[y] = -1;
	  countW++;
	}
      }
    }
    for (int i = 0; i < sizeW; i++) {
      univW.pop_front();
    }

    if(bcB == countB && bcW == countW) break;
  }
  if (countB < countW) {
    cout << "Snuke" << endl;
  } else {
    cout << "Fennec" << endl;
  }
  return 0;
}

