vi bfs(vv &e,ll s)
{
    ll n=sz(e);
    queue <ll> q;
    vi dis(n,-1);

    q.push(s);
    dis[s]=0;
    while(!q.empty())
    {
        ll u=q.front();
        q.pop();
        for(ll v:e[u])
        {
            if(dis[v]==-1)
            {
                dis[v]=dis[u]+1;
                q.push(v);
            }
        }
    }
    return dis;
}
