vector<int> divisor(int n){
  vector<int> ret;
  for(int i = 1;i*i <= n;i++){
    if(n%i == 0){
      ret.push_back(i);
      if(i*i != n)ret.push_back(n/i);
    }
  }
  sort(ret.begin(), ret.end());
  return ret;
}

int n;vector<int> v[110000];
int d1[110000], dn[110000];

void dfs1(int depth, int node, int pre, bool vn){
  d1[node] = depth;
  if(vn){
    d1[node] = -(depth-d1[n]);
  }
  vn = vn || (node == n);
  rep(i,v[node].size()){
    if(v[node][i] == pre)continue;
    dfs1(depth+1, v[node][i], node, vn);
  }
}

void dfsn(int depth, int node, int pre, bool vn){
  dn[node] = depth;
  if(vn){
    dn[node] = -(depth-dn[1]);
  }
  vn = vn || node == 1;
  rep(i,v[node].size()){
    if(v[node][i] == pre)continue;
    dfsn(depth+1, v[node][i], node, vn);
  }
}

