    p[0] = -1;
    queue<int> que;
    que.push(0);
    while(!que.empty()){
        int v = que.front();
        que.pop();
        for(int t : to[v]){
            if(p[t] != -2)continue;
            p[t] = v;
            que.push(t);
        }
