using namespace std;
typedef long long LL;
const LL mod = 1e9+7;

vector<int> mp[N];
typedef pair<int, int> P;

void bfs(int n)
{
    queue<int> q;
    int vis[N];
    memset(vis, 0, sizeof(vis));
    vis[1] = 1;
    int a = 0, b = 0;
    q.push(1);
    while(!q.empty())
    {
        int u = q.front(); q.pop();
        for(int j = 0; j < mp[u].size(); j++)
        {
            int v = mp[u][j];
            if(!vis[v]&&v != n)
            {
                a++, q.push(v);
                vis[v] = 1;
            }
        }
    }
    memset(vis, 0, sizeof(vis));
    vis[n] = 1;
    while(!q.empty()) q.pop();
    q.push(n);
    while(!q.empty())
    {
        int u = q.front(); q.pop();
        for(int j = 0; j < mp[u].size(); j++)
        {
            int v = mp[u][j];
            if(!vis[v]&&v != 1)
            {
                b++, q.push(v);
                vis[v] = 1;
            }
        }
    }
    if(a > b) puts("Fennec");
    else puts("Snuke");
}

