int F=0, S=0, SF=0;
int graph[100100]={0};

void rec(int n, int m, int gl){
        if(gl==n){
                return;
        }
        flag[n]=true;
        graph[n]+=m;
        for(int i=0;i<N;i++){
                if(!flag[ab[i].second]&&ab[i].first==n){
                        rec(ab[i].second, m, gl);
                }
                else if(!flag[ab[i].first]&&ab[i].second==n){
                        rec(ab[i].first, m, gl);
                }
        }
}

