                if(aa<bb){
                        ab.push_back(make_pair(aa, bb));
                }
                else{
                        ab.push_back(make_pair(bb, aa));
                }
        }
        rec(1, 1, N);
        for(int i=0;i<=N;i++){
                flag[i]=false;
