	}

	vector<int> path;
	x = n;
	do {
		path.push_back(x);
		x = parent[x];
	} while (x > 0);

	m = path.size();
	if (m % 2 == 0) x = path[(m - 1) / 2];
	else x = path[m / 2 - 1];

	b = s[x];
	a = n - b;

	if (a > b) cout << "Fennec\n";
	else cout << "Snuke\n";

