}

void addedge(int from, int to) {
    eg[tot] = {to, head[from]};
    head[from] = tot++;
}

void dfs(int u, int pa, int* d) {
    if(pa != -1) d[u] = d[pa] + 1;
    else d[u] = 0;
    for(int i = head[u]; i != -1; i = eg[i].next) {
        int to = eg[i].to;
        if(to != pa) {
            dfs(to, u, d);
        }
    }
}

