#define P(r) do{cout<<#r": ";for(const auto &i:r){cout<<i<<" ";}cout<<endl;}while(0)
int main()
{
    int N; cin >> N;
    vector<vector<int>> node(N);
    REP(i, N-1) {
        int a, b; cin >> a >> b;
        a--, b--;
        node[a].push_back(b);
        node[b].push_back(a);
    }
    // find path from 0 to N-1
    vector<int> path;
    function<bool(int, int)> dfs;
    dfs = [&](int x, int prev) -> bool {
        if (x == N - 1) {
            path.push_back(x);
            return true;
        }
        for (auto child : node[x]) {
            if (child != prev && dfs(child, x)) {
                path.push_back(x);
                return true;
            }
        }
        return false;
    };
    dfs(0, -1);
    reverse(path.begin(), path.end());
    // count nodes
    function<int(int, int)> count;
    count = [&](int x, int prev) -> int {
        int res = 1;
        for (auto child : node[x]) {
            if (child != prev) {
                res += count(child, x);
            }
        }
        return res;
    };
    int fenec = 0;
    REP(i, (path.size() + 1) / 2) {
        fenec++;
        for (auto child : node[path[i]]) {
            if (child == path[i+1]) continue;
            fenec += count(child, path[i]);
        }
    }
    cout << ((fenec > (N - fenec)) ? "Fennec" : "Snuke") << endl;
    return 0;
}

