int dfs(int from, int p = -1){
    int res = 1;
    for(int to : graph[from]){
        if(to == p || to == white)  continue;
        res += dfs(to, from);
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    graph.resize(n);
    for(int i = 0; i < n - 1; ++i){
        int a, b;
        cin >> a >> b;
        --a, --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    LCA<G> lca(graph);
    lca.build();
    int diameter = lca.length(0, n - 1);
    int dist = diameter / 2;
    if(diameter % 2 == 0){
        int x = dist;
        black = n - 1;
        for(int i = lca.ub_log - 1; i >= 0; --i){
            if((x >> i) & 1)    black = lca.table[i][black];
        }
        x = dist - 1;
        white = n - 1;
        for(int i = lca.ub_log - 1; i >= 0; --i){
            if((x >> i) & 1)    white = lca.table[i][white];
        }
    }
    else{
        int x = dist;
        white = n - 1;
        for(int i = lca.ub_log - 1; i >= 0; --i){
            if((x >> i) & 1)    white = lca.table[i][white];
        }
        x = dist + 1;
        black = n - 1;
        for(int i = lca.ub_log - 1; i >= 0; --i){
            if((x >> i) & 1)    black = lca.table[i][black];
        }
    }
    int cnt = dfs(black);
    bool win = (cnt > n - cnt) ? true : false;
    if(win) cout << "Fennec\n";
    else    cout << "Snuke\n";
}

