#include "bits/stdc++.h"
using namespace std;

const ll MAX_V = 100100;

ll V, E;
vector<ll> G[MAX_V];

ll cnt[2], mark[MAX_V];
bool f[2][MAX_V];

void dfs(ll s, ll n) {

	for (ll i = 0; i < G[s].size(); i++) {
		ll u = G[s][i];
		if(f[n][u]) continue;
		f[n][u] = true;
		cnt[n]++;
		mark[u]++;
		dfs(u, n);
	}
}

int main() {
	cin >> V;
	for (ll i = 0; i < V-1; i++) {
		ll a, b; cin >> a >> b;
		a--; b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}

	f[0][0] = f[0][V-1] = true;
	f[1][0] = f[1][V-1] = true;

	dfs(0, 0);
	dfs(V-1, 1);

	ll bw=0;
	for (ll i = 0; i < V; i++) {
		if(mark[i]==2) bw++;
	}
	cnt[0] -= bw/2;
	cnt[1] -= (bw/2)+(bw%2);

	//cout << cnt[0] <<" "<< cnt[1] << endl;

	if(cnt[0] > cnt[1]) cout << "Fennec" << endl;
	else cout << "Snuke" << endl;
}

