int n;
int cnt1=0,cnt2=0;
queue<int> q;
vector<int> v[100010];

vector<int> bfs(int x){
	vector <int> d(n,100010);
	d[x]=0;
	q.push(x);
	while(!q.empty()){
		int u=q.front();
		q.pop();
		for (int i=0;i<v[u].size();i++){
			int tmp=v[u][i];
			if (d[tmp]>d[u]+1){
				d[tmp]=d[u]+1;
				q.push(tmp);
			}
		}
	}
	return d;
}

int main(){
	cin>>n;
	for (int i=1;i<n;i++){
		int x,y;
		cin>>x>>y;
		x--;y--;
		v[x].push_back(y);
		v[y].push_back(x);
	}
	vector<int> d1=bfs(0);
	vector<int> d2=bfs(n-1);
	for (int i=0;i<n;i++){
		if (d1[i]<=d2[i]) cnt1++;
		else cnt2++;
//		cout<<i+1<<" "<<d[i][0]<<" "<<d[i][1]<<endl;
	}
//	cout<<cnt1<<" "<<cnt2;
	if (cnt1>cnt2) cout<<"Fennec"<<endl;
	else cout<<"Snuke"<<endl;
	return 0;
}

