#define mod 1000000007
using namespace std;
const int N=123456;

vector<int>adj[N];
int color[N];


int find(int u,int par,int n,vi&path)
{

    for(auto v:adj[u])
    {
        if(v==par)continue;
        if(v==n)return 1;

        if(find(v,u,n,path))
            {path.pb(v);
             return 1;
            }
    }
    return 0;
}

void dfs(int u,int par,int n)
{
    for(int v : adj[u])
    {
       if(v==par)continue;

       if( color[v]==0 && color[u]==1)
            color[v]=1;
       else if( color[v]==0 )
        color[v]=2;

        dfs(v,u,n);
    }

}


