int dfs(int x,int p,int lev)
{
    if(x==n)
        dist=lev;

    int tmp=1;
    for(auto c:v[x])
    {
        if(c==p)
            continue;

        tmp+=dfs(c,x,lev+1);
    }

    if(x==n)
        sub=tmp;

    return tmp;
}

void solve()
{
    cin>>n;

    int a,b;
    for(int i=1;i<n;++i)
