    int chance=(dist-1)%2;

    a=n-1-sub-(dist-1),b=sub-1;

    //cout<<chance<<" "<<a<<" "<<b<<"\n";

    if(chance==1)
    {
        if(a>=b)
            cout<<"Fennec";
        else
            cout<<"Snuke";
    }
    else
    {
        if(a>b)
            cout<<"Fennec";
        else
            cout<<"Snuke";
    }
}

