#include <queue>
#define INF LONG_MAX
typedef long long ll;
struct edge{ll to, cost;};
typedef pair<ll,ll> P;

struct graph{
  ll V;
  vector<vector<edge> > G;
  vector<ll> d;

  graph(ll n){
    init(n);
  }

  void init(ll n){
    V = n;
    G.resize(V);
    d.resize(V);
    for(int i = 0; i < V; i++){
      d[i] = INF;
    }
  }

  void add_edge(ll s, ll t, ll cost){
    edge e;
    e.to = t, e.cost = cost;
    G[s].push_back(e);
  }

  void dijkstra(ll s){
    for(int i = 0; i < V; i++){
      d[i] = INF;
    }
    d[s] = 0;
    priority_queue<P,vector<P>, greater<P> > que;
    que.push(P(0,s));
    while(!que.empty()){
      P p = que.top(); que.pop();
      ll v = p.second;
      if(d[v]<p.first) continue;
      for(auto e : G[v]){
        if(d[e.to]>d[v]+e.cost){
          d[e.to] = d[v]+e.cost;
          que.push(P(d[e.to],e.to));
        }
      }
    }
  }
};

/*
graph g(n);

と書けばn頂点のグラフが作成され、

  g.add_edge(a,b,cost);

とすれば頂点aから頂点bへのコストcostの辺が張られます。そして

  g.dijkstra(s);

とすれば頂点sから各頂点への最短経路をダイクストラ法で探索できます。探索結果は

  int dist = g.d[i]:

と呼び出して使うことができます。
*/

int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin >> n;
  VI a(n-1), b(n-1);
  graph g(n);
  graph f(n);
  rep(i,n-1){
    cin >> a[i] >> b[i];
    a[i]--,b[i]--;
    g.add_edge(a[i],b[i],1);
    g.add_edge(b[i],a[i],1);
    f.add_edge(a[i],b[i],1);
    f.add_edge(b[i],a[i],1);
  }
  f.dijkstra(n-1);
  g.dijkstra(0);
  ll gg,ff;
  gg = -1;
  ff = -1;
  rep(i,n){
    if(g.d[i] <= f.d[i]){
      gg = max(gg,g.d[i]);
    }else{
      ff = max(ff,f.d[i]);
    }
  }


  // cout << gg << " " << ff << endl;
  if(ff <= gg){
    cout << "Fennec" << "\n";
  }else{
    cout << "Snuke" << endl;
  }
  return 0;
}

