int count_node(int player, int parent, int node) {
  int ans = 1;
  iter(it, edge[node]) {
    int to = *it;
    if (to == parent)
      continue;
    if (to == start[1 - player])
      return INF;
    int res = count_node(player, node, to);
    if (res == INF)
      return INF;
    ans += res;
  }
  return ans;
}
int main() {
