  int nodes[2] = {0, 0};
  rep(player, 2) {
    iter(it, edge[start[player]]) {
      int to = *it;
      if (to == start[1 - player])
        continue;
      int res = count_node(player, start[player], to);
      if (res != INF)
        nodes[player] += res;
    }
  }
  int common = N - 2 - (nodes[0] + nodes[1]);
  if (common % 2 == 0 && nodes[0] > nodes[1] || common % 2 == 1 && nodes[0] >= nodes[1])
    out("Fennec");
