#include<iostream>
#include<queue>
#include<vector>
#define WHITE 0
#define GRAY 1
#define BLACK 2
#define INF (1 << 30)
using namespace std;

int both_color[100005];
int fennec_color[100005];
int dist[100005];
int parent[100005];
vector<pair<int, int> > adj[100005];
int N;
int adj_count = 0, fennec_count = 0;

void dijkstra() {
    priority_queue<pair<int, int> > PQ;
    for(int i = 0; i < N; i++) {
        dist[i] = INF;
        both_color[i] = WHITE;
        parent[i] = i;
    }
    pair<int, int> u = make_pair(0, 0);
    dist[0] = 0;
    both_color[u.second] = GRAY;
    PQ.push(u);
    while (!PQ.empty()) {
        pair<int, int> v = PQ.top();
        PQ.pop();
        both_color[v.second] = BLACK;
        if (dist[v.second] < v.first * (-1)) continue;
        for (int i = 0; i < adj[v.second].size(); i++) {
            int adj_u = adj[v.second][i].second;
            if (both_color[adj_u] == BLACK) continue;
            if (dist[adj_u] > dist[v.second] + adj[v.second][adj_u].first) {
                dist[adj_u] = dist[v.second] + adj[v.second][adj_u].first;
                PQ.push(make_pair(dist[adj_u] * (-1), adj_u));
                both_color[adj_u] = GRAY;
                parent[adj_u] = v.second;
            }
        }
    }
    return;
}


void dfs(int u) {
    for (int i = 0; i < adj[u].size(); i++) {
        if (adj[u][i].second == N - 1) continue;
        if (fennec_color[adj[u][i].second] == WHITE) {
            fennec_color[adj[u][i].second] = BLACK;
            dfs(adj[u][i].second);
        }
    }
    return;
}

int main() {
    int a, b;
    cin >> N;
    for (int i = 0; i < N - 1; i++) {
        cin >> a >> b;
        a--; b--;
        adj[a].push_back(make_pair(-1, b));
        adj[b].push_back(make_pair(-1, a));
    }
    dijkstra();
    for (int i = 0; i < N; i++) fennec_color[i] = WHITE;
    int p = parent[N - 1];
    while (p != 0) {
        fennec_color[p] = GRAY;
        adj_count++;
        p = parent[p];
    }
    dfs(0);
    for (int i = 0; i < N; i++) {
        if (fennec_color[i] == BLACK) fennec_count++;
    }
    if (fennec_count + adj_count % 2 >= N - (fennec_count + adj_count)) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

    return 0;
}

