const int INF = 10e9;
vector<int> tree[100050];
int n;
bool used[100050];
vector<int> shortRoot;
ll count(int f,int v) {

	bool next = false;
	ll sum = 1;
	for (size_t i = 0; i < tree[v].size(); i++)
	{
		int nex = tree[v][i];
		if (nex == f) continue;
		sum += count(v,nex);
	}
	return sum;
}
void recur(int v, int c,vector<int> root) {

	used[v] = true;
	if (v == n) {
		shortRoot = root;
	}
	else {
		bool next = false;
		for (size_t i = 0; i < tree[v].size(); i++)
		{
			if (!used[tree[v][i]]) {

				root.push_back(tree[v][i]);
				recur(tree[v][i], c + 1, root);
				root.erase(root.end() - 1);
				next = true;
			}
		}
	}
}
void FennecVSSnuke(){

	cin >> n;
	for (size_t i = 1; i < n; i++)
	{
		int a, b;
		cin >> a >> b;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}

	recur(1, 0, {1});
	int start = 0;
	int goal = shortRoot.size() - 1;
	bool even = shortRoot.size() % 2;
	int turn = 0;
	ll fv = 0;
	ll sv = 0;
	ll judge;
	while (start != (goal + !even))
	{
		if (turn % 2 == 0) {
			int from = shortRoot[start];
			int next = shortRoot[start + 1];

			for (size_t i = 0; i < tree[from].size(); i++)
			{
				if (tree[from][i] == next) continue;
				if (start > 0 && shortRoot[start - 1] == tree[from][i]) continue;
				fv += count(from,tree[from][i]);
			}
			if (start + 1 == goal) {
				judge = 1;
			}
			start++;
		}
		else {
			int from = shortRoot[goal];
			int next = shortRoot[goal - 1];

			for (size_t i = 0; i < tree[from].size(); i++)
			{
				if (tree[from][i] == next) continue;
				if (goal < shortRoot.size() - 1 && shortRoot[goal + 1] == tree[from][i]) continue;
				sv += count(from,tree[from][i]);
			}
			if (start == goal - 1) {
				judge = 0;
			}
			goal--;
		}
		turn++;
	}
	if (judge == 1) {
		if (fv >= sv) {
			cout << "Fennec" << endl;
		}
		else {
			cout << "Snuke" << endl;
		}
	}
	else {
		if (fv <=  sv) {
			cout << "Snuke" << endl;
		}
		else {
			cout << "Fennec" << endl;
		}
	}

}

int main() {
	FennecVSSnuke();
	return 0;
}

