class union_find{
private:
  int p[200000];
  int r[200000];


public:
  union_find(int n){
    for(int i=0;i < n;i++){
      p[i] = i;
      r[i] = 0;
    }
  }
  int find(int x){
    if(p[x] == x){
      return x;
    }else{
      return p[x] = find(p[x]);
    }
  }
  void unite(int x, int y){
    x = find(x);
    y = find(y);
    if(x == y) return;

    if(r[x] < r[y]){
      p[x] = y;
    }else{
      p[y] = x;
      if(r[x] == r[y]) r[x]++;
    }
  }
  bool same(int x, int y){
    return find(x) == find(y);
  }
};

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
  int n;
  cin >> n;
  union_find node(n);
  union_find pre(n);
  int fen = 0, snu = 0, mid = 0;

  rep(i, n-1){
    int a, b;
    cin >> a >> b;
    node.unite(--a, --b);
    if(node.same(0, n-1)){
      if(a == 0 || b == 0) snu--;
      else if (a == n-1 || b == n-1) fen--;
      node = pre;
    }
    pre = node;
  }
  for(int i = 1; i < n-1; i++){
    if(node.same(0, i)) fen++;
    else if(node.same(n-1, i)) snu++;
    else mid++;
  }
  if(mid%2 != 0) fen++;
  cout << (fen > snu ? "Fennec" : "Snuke") << endl;

	return 0;
}

