ll gcd(ll a, ll b){return b!=0 ? gcd(b, a%b) : a;}
ll lcm(ll a, ll b){return a / gcd(a, b) * b;}

void bfs(vector<int>& dist, const int start, const int goal, const vector<vector<int>>& g){
	dist[start] = 0;
	queue<int> q;
	q.push(start);

	while(!q.empty()){
		int now = q.front();
		q.pop();
		for(auto itr : g[now]){
			if(dist[itr] != INF) continue;
			if(itr == goal) continue;
			dist[itr] = dist[now] + 1;
			q.push(itr);
		}
	}
}

