		g[a].push_back(b);
		g[b].push_back(a);
	}

	vector<int> dist_f(n, INF);
	bfs(dist_f, 0, n - 1, g);

	vector<int> dist_s(n, INF);
	bfs(dist_s, n - 1, 0, g);

	int f_only = 0, s_only = 0, _union = 0;
	for(int i = 0; i < n; ++i){
		if(i != n-1 && dist_f[i] == INF) s_only++;
