	queue<pair<ll,ll>>que;
	ll dis;
	que.push(make_pair(0,0));
	while(!que.empty()){
		ll u=que.front().first;
		ll depth=que.front().second;
		que.pop();
		for(int i=0;i<G[u].size();i++){
			ll next=G[u][i];
			if(exWhite[next])continue;
			if(next==N-1){
				dis=depth;
				continue;
			}
			exWhite[next]=true;
			que.push(make_pair(next,depth+1));
		}
	}

	ll numWhite=-1;
	for(int i=0;i<N;i++){
		if(exWhite[i])numWhite++;
	}
	//cout<<numWhite<<endl;

	vector<bool>exBlack(N,false);
	exBlack[N-1]=true;
	queue<ll>que2;
	que2.push(N-1);
	while(!que2.empty()){
		ll u=que2.front();
		que2.pop();
		for(int i=0;i<G[u].size();i++){
			ll next=G[u][i];
			if(exBlack[next])continue;
			if(next==0)continue;
			exBlack[next]=true;
			que2.push(next);
		}
	}

	ll numBlack=-1;
	for(int i=0;i<N;i++){
		if(exBlack[i])numBlack++;
	}
	ll num=dis/2;
	numWhite-=num;
	numBlack-=(dis-num);
	if(numWhite>numBlack){
		cout<<"Fennec"<<endl;
	}else cout<<"Snuke"<<endl;
	//cout<<numWhite<<endl;
	//cout<<numBlack<<endl;
}

