//前向星+SPFA
/*
edeg[]: 邻接表
dis[]: 最短路数组
vis[]: 出入队标记数组
cnt[]: 入队次数统计
head[u]:表示起点为u的最后一条边的标号，如果是-1表示没有以u为起点的边
init::初始化边
add::(u起点, v终点, w权值)
spfa::(s起点，n点数)[-1存在负环，反之为到点n最短路权值]

*/
#include<iostream>
#include<queue>
#include<algorithm>
#include<string.h>
#define N 100005
#define INF 0x3f3f3f3f
using namespace std;
struct Edge
{
	int to;
	int next;//表示和该边有共同起点的上一条边的标号
	int val;
}edge[500000];
int tot;
int head[N];
int dis1[N];
int dis2[N];
int vis[N];
int cnt[N];
void init()
{
	tot=0;
	for(int i=0;i<N;i++)
	head[i]=-1;
	memset(vis,0,sizeof(vis));
	memset(cnt,0,sizeof(cnt));

}
void add(int u,int v,int w)
{
	edge[tot].to=v;
	edge[tot].val=w;
	edge[tot].next=head[u];
	head[u]=tot++;
}
int spfa1(int s,int n)
{
	queue<int> q;
	for(int i=1;i<=n;i++)
	{
		vis[i]=0;
		cnt[i]=0;
		dis1[i]=INF;
	}
	cnt[s]=1;
	vis[s]=1;
	dis1[s]=0;
	q.push(s);
	while(!q.empty())
	{
		int u=q.front();
		q.pop();
		vis[u]=0;
		for(int i=head[u];i!=-1;i=edge[i].next)
		{
			int v=edge[i].to;
			int w=edge[i].val;
			if(dis1[u]+w<dis1[v])
			{
				dis1[v]=dis1[u]+w;
				if(!vis[v])
				{
					vis[v]=1;
					if(++cnt[v]>n) return -1;
					q.push(v);
				}
			}
		}
	}
	return dis1[n];//默认返回最后一个点最短距离，可更改
}
int spfa2(int s,int n)
{
	queue<int> q;
	for(int i=1;i<=n;i++)
	{
		vis[i]=0;
		cnt[i]=0;
		dis2[i]=INF;
	}
	cnt[s]=1;
	vis[s]=1;
	dis2[s]=0;
	q.push(s);
	while(!q.empty())
	{
		int u=q.front();
		q.pop();
		vis[u]=0;
		for(int i=head[u];i!=-1;i=edge[i].next)
		{
			int v=edge[i].to;
			int w=edge[i].val;
			if(dis2[u]+w<dis2[v])
			{
				dis2[v]=dis2[u]+w;
				if(!vis[v])
				{
					vis[v]=1;
					if(++cnt[v]>n) return -1;
					q.push(v);
				}
			}
		}
	}
	return dis2[n];//默认返回最后一个点最短距离，可更改
}
int n;
int main()
{
	init();
	cin>>n;
	for(int i=1;i<n;i++)
	{
		int a,b;
		cin>>a>>b;
		add(a,b,1);
		add(b,a,1);
	}

	spfa1(1,n);
	spfa2(n,n);
	int s=0;
	for(int i=1;i<=n;i++)
	if(dis1[i]<=dis2[i])
	s++;
/*
	for(int i=1;i<=n;i++)
	cout<<"dis1: "<<dis1[i]<<" dis2: "<<dis2[i]<<endl;*/
	if((s-1)>(n-s))
	cout<<"Fennec"<<endl;
	else
	cout<<"Snuke"<<endl;
	return 0;

}

