using namespace std;

bool first_win(int N, const vector<vector<int>> &Es) {
    vector<int> visited(N, 0);
    visited[0] = 1;
    visited[N - 1] = -1;
    vector<int> f1{0};
    vector<int> fN{N - 1};
    vector<int> new_f1;
    vector<int> new_fN;
    while (not (f1.empty() and fN.empty())){
        new_f1.clear();
        for (auto v : f1){
            for (u : Es[v]){
                if (visited[u] != 0) continue;
                visited[u] = 1;
                new_f1.push_back(u);
            }
        }
        new_fN.clear();
        for (auto v : fN){
            for (u : Es[v]){
                if (visited[u] != 0) continue;
                visited[u] = -1;
                new_fN.push_back(u);
            }
        }
        swap(f1, new_f1);
        swap(fN, new_fN);
    }
    return accumulate(visited.begin(), visited.end(), 0) > 0;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vector<vector<int>> Es(N, vector<int>());
    for (int i = 0; i < N - 1; ++i){
        int a, b;
        cin >> a >> b;
        Es[a - 1].push_back(b - 1);
        Es[b - 1].push_back(a - 1);
    }
    if (first_win(N, Es)){
        cout << "Fennec" << endl;
    }else{
        cout << "Snuke" << endl;
    }
    return 0;
}

