    queue<int> que;

    cin>>n;
    vector<vector<int>> G(n);

    for(int i=0; i<n-1; i++){
        int a,b; 
        cin>>a>>b;
        a--; b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    vector<int> d1(n,-1),d2(n,-1);

    int fenec=0,snuke=0;

    que.push(0);    

    while(!que.empty()){
        int v = que.front();
        que.pop();

        for(auto a : G[v]){
            if(d1[a] != -1) continue;

            d1[a] = d1[v]+1;
            que.push(a);
        }
    }

    que.push(n-1);

    while(!que.empty()){
        int v = que.front();
        que.pop();

        for(auto a : G[v]){
            if(d2[a] != -1) continue;

            d2[a] = d2[v]+1;
            que.push(a);
        }
    }

    for(int i=0; i<n-1; i++){
        if(d1[i] > d2[i]){
            snuke++;
        }
        else if(d1[i] <= d2[i]){
            fenec++;
        }

        cout<<d1[i]<<" "<<d2[i]<<endl;
    }

    if(snuke >= fenec) cout<<"Snuke"<<endl;

    else cout<<"Fennec"<<endl;

    return 0;
}

