void vprn(vector<int> &v){ for(int i=0;i<v.size();i++) cout<<v[i]<<(i<v.size()-1?",\t":"\n"); }
void vvprn(vector<vector<int>> &vv){
	rp(i,1,vv.size()){
		cout<<i<<") ";
		vprn(vv[i]);
	}
}

int distance(int p1, int p2, vvi &tree, vi &visited){
	if(p1 == p2) return 0;
	if(visited[p1]) return 0;
	// printf("p1 %d p2 %d\n",p1,p2);//
	visited[p1] = true;
	int d = 0;
	for(auto c: tree[p1]){
		if(c == p2){
			d = 1;
			break;
		}
		else{
			int ret = distance(c, p2, tree, visited);
			if(ret>0){
				d = ret + 1;
				break;
			}
		}
	}
	visited[p1] = false;
	// printf("p1 %d p2 %d d %d\n",p1,p2,d);//
	return d;
}

string solve(int N, vi &A, vi &B){
	vvi tree(N+1, vi());
	rp(i, 0, N-1){
		tree[A[i]].push_back(B[i]);
		tree[B[i]].push_back(A[i]);
	}
	// vvprn(tree);//
	vi visited(N);
	int c = 0;
	rp(i, 2, N){
		int a = distance(1,i,tree,visited);
		int b = distance(N,i,tree,visited);
		c += a==b? 0: a<b? 1: -1;
		// printf("a %d b %d c %d\n",a,b,c);//
	}
	return c>0? "Fennec": "Snuke";
}

int main(){
	int N; cin>>N;
	vi A(N-1), B(N-1);
	rp(i, 0, N-1) cin>>A[i]>>B[i];
	cout<< solve(N, A, B) <<endl;
}

