	cin >> N;
	REP(i, N) {
		cin >> a >> b;
		v[a - 1].push_back(b - 1);
		v[b - 1].push_back(a - 1);
	}

	int parent[100000];
	REP(i, N) {
		parent[i] = -1;
	}
	stack<int> s;
	s.push(0);
	parent[0] = -2;
	while (s.size() != 0) {
		int k = s.top();
		s.pop();
		REP(i, v[k].size()) {
			if (parent[v[k][i]] == -1) {
				parent[v[k][i]] = k;
				s.push(v[k][i]);
			}
		}
	}

	int key = N - 1;
	vector<int> path;
	while (key != -2) {
		path.push_back(key);
		key = parent[key];
	}
	//cout << parent[3] << endl;
	int left = path[(path.size() - 1) / 2];
	int right = path[path.size() / 2];
	int size = v[left].size();
	REP(i, size) {
		int k = v[left][0];
		v[left].erase(v[left].begin());
		if (k != right) {
			v[left].push_back(k);
		}
	}
	size = v[right].size();
	REP(i, size) {
		int k = v[right][0];
		v[right].erase(v[right].begin());
		if (k != left) {
			v[right].push_back(k);
		}
	}

	REP(i, N) {
