				parent[v[k][i]] = k;
				t.push(v[k][i]);
			}
		}
	}
	int cnt = 0;
	REP(i, N) {
		if (parent[i] != -1) {
			cnt++;
		}
	}

	//cout << right << " " << left << endl;
