const int maxn = 100000;
queue< int > q, sf;
vector< vector< int > > vr(maxn);
bool used[maxn];
int n;
int pre[maxn];

void road(int s = 0) {
  fill(used, used + n, false);
  used[0] = true;
  pre[0] = -1;
  q.push(s);
  bool key = false;
  //点を詰めて、そこからのばす
  while(!key) { //点n-1を含むまで続ける
    int v = q.front();
    q.pop();
    for(int i = 0; i < vr[v].size(); i++) {
      if(!used[vr[v][i]]) { //行先の頂点は未使用
        used[vr[v][i]] = true;
        q.push(vr[v][i]);       //点vからのびる点を詰める
        pre[vr[v][i]] = v;      //詰められた点は点vから伸びている
        if(vr[v][i] == n - 1) { //のびた点がn-1の時に終わり
          key = true;
          break;
        }
      }
    }
  }

  return;
}

int main() {
  cin >> n;

  rep(i, n - 1) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    vr[a].push_back(b); //頂点aは頂点bへの道をもつ、その逆も
    vr[b].push_back(a);
  }

  //頂点0から頂点n-1への頂点の個数を数える(頂点0,n-1も含める)
  // 0からn-1への道順
  road();
  // 0からn-1にc個の点があるかを調べる
  int c = 0, s = n - 1;
  while(pre[s] != -1) {
    c++;
    s = pre[s];
  }
  c++;

  // Snukeは0からn-1のうち最後からc(下で更新)個の点を塗る

  if(c % 2 == 0) {
    c = c / 2;
  } else {
    c = (c - 1) / 2;
  }

  //後ろからc個をsfにつめる
  s = n - 1;
  int att;
  fill(used, used + n, false);
  for(int i = 0; i < c; i++) {
    sf.push(s);
    used[s] = true; // NOTE : ここでおらないと
    s = pre[s];
    if(i == c - 1) att = s;
  }
  //後ろから詰めた点から派生する点はSnukeが塗る 得点sp
  //点attはフェネックが塗るから含んではいけない
  used[att] = true;
  int sp = 0;
  while(sf.size()) {
    int v = sf.front();
    sf.pop();
    sp++; // NOTE : 同じ点がここで二回数えられるかもしれない
    for(int i = 0; i < vr[v].size(); i++) {
      if(!used[vr[v][i]]) {
        used[vr[v][i]] = true;
        sf.push(vr[v][i]);
      }
    }
  }

  if(sp < n - sp) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }

  return 0;
}

