vector<map<int,int>> mp(100010);

int main() {
  int n;
  cin >> n;
  for (int i = 1; i < n; i++) {
    int a, b;
    cin >> a >> b;
    mp[a][b] = 1;
    mp[b][a] = 1;
  }
  int tree[n + 1] = {};
  tree[1] = 1;
  queue<int> que;
  que.push(1);
  while (!que.empty()) {
    int top = que.front();
    que.pop();
    for (auto p: mp[top]) {
      if (tree[p.first] == 0) {
        tree[p.first] = top;
        que.push(p.first);
      }
    }
  }
  int pos = n;
  int dist = 0;
  while (1) {
    if (tree[pos] != 1) {
      dist++;
      pos = tree[pos];
    } else {
      break;
    }
  }
  dist /= 2;
  for (int i = 0; i < dist; i++) {
    n = tree[n];
  }
  int cnt = 0;
  que.push(n);
  while (!que.empty()) {
    int top = que.front();
    que.pop();
    cnt++;
    for (auto p: mp[top]) {
      if (tree[p.first] != top) {
        que.push(p.first);
      }
    }
  }
  if (n - cnt > cnt) {
    puts("Fennec");
  } else {
    puts("Snuke");
  }
  return 0;
}

