#define WHITE 0
#define BLACK 1
using namespace std;

vector<int> adj[100005];
int parent[100005];
int color[100005];
int N;

void assign_color(int u, int cl, int goal) {
    color[u] = cl;
    for (int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if (v == goal) {
            continue;
        }
        if (color[v] != cl) {
            color[v] = cl;
            assign_color(v, cl, goal);
        }
    }
    return;
}

void path_dfs(int u) {
    color[u] = BLACK;
    for (int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if (v == N - 1) {
            parent[v] = u;
            return;
        }
        if (color[v] != BLACK) {
            parent[v] = u;
            color[v] = BLACK;
            path_dfs(v);
        }
    }
    return;
}

int main() {
    int a, b, p, s2g = 0, fennec_count = 0;
    cin >> N;
    for (int i = 0; i < N - 1; i++) {
        cin >> a >> b;
        a--; b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    for (int i = 0; i < N; i++) {
        color[i] = WHITE;
        parent[i] = i;
    }
    path_dfs(0);
    p = parent[N - 1];
    while (p != 0 || parent[p] != p) {
        s2g++;
        p = parent[p];
    }
    p = N - 1;
    for (int i = 0; i < s2g / 2; i++) {
        p = parent[p];
    }
    for (int i = 0; i < N; i++) color[i] = WHITE;
    assign_color(0, BLACK, p);
    for (int i = 0; i < N; i++) {
        if (color[i] == BLACK) fennec_count++;
    }
    if (fennec_count > N - fennec_count) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;

    return 0;

}

