class UnionFind {
public:
	vector <ll> par; // 各元の親を表す配列
	vector <ll> siz; // 素集合のサイズを表す配列(1 で初期化)

	// Constructor
	UnionFind(ll sz_) : par(sz_), siz(sz_, 1LL) {
		for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
	}
	void init(ll sz_) {
		par.resize(sz_);
		siz.assign(sz_, 1LL);  // resize だとなぜか初期化されなかった
		for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
	}

	// Member Function
	// Find
	ll root(ll x) { // 根の検索
		while (par[x] != x) {
			x = par[x] = par[par[x]]; // x の親の親を x の親とする
		}
		return x;
	}

	// Union(Unite, Merge)
	bool merge(ll x, ll y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		// merge technique（データ構造をマージするテク．小を大にくっつける）
		if (siz[x] < siz[y]) swap(x, y);
		siz[x] += siz[y];
		par[y] = x;
		return true;
	}

	bool issame(ll x, ll y) { // 連結判定
		return root(x) == root(y);
	}

	ll size(ll x) { // 素集合のサイズ
		return siz[root(x)];
	}
};

vector<Pa> edges;
set<Pa> st;
int main() {
	cin >> N;
	rep(i, N - 1) {
		cin >> A >> B; A--; B--;
		to[A].push_back(B);
		to[B].push_back(A);
		edges.push_back(Pa(A, B));
	}

	route.push_back(0);
	dfs(0, -1);

	rep(i, route.size() - 1) {
		st.insert(Pa(route[i], route[i + 1]));
		st.insert(Pa(route[i + 1], route[i]));
	}
	UnionFind tree(N + 1);
	rep(i, edges.size()) {
		if (st.count(edges[i]) == 0) {
			tree.merge(edges[i].first, edges[i].second);
		}
	}

	int fennec_score = tree.size(0);
	int snukekun_score = tree.size(N-1);
	rep(i, route.size() - 2) {
		if (i % 2 == 0) {
			fennec_score += tree.size(route[i / 2 + 1]);
		}
		else {
			snukekun_score += tree.size(route[N - 2 - i / 2]);
		}
	}
	if (fennec_score > snukekun_score) {
		cout << "Fennec";
	}
	else {
		cout << "Snuke";
	}
}

