using namespace std;

bool f = 0;
int N;
vector<int> ways,v(100001);
vector<vector<int>> to(100001);

void dfs(int now,vector<int> &t){
	if(f)return;
	if(now == N-1){
		ways = t;
		f = 1;
		return;
	}
	for(auto next:to[now]){
		if(v[next]==0){
			v[next] = 1;
			t.push_back(next);
			dfs(next,t);
			t.pop_back();
			v[next] = 0;
		}
	}
}

int main(void){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> N;
	rep(i,N-1){
		int x,y;
		cin >> x >> y;
		x--;y--;
		to[x].push_back(y);
		to[y].push_back(x);
	}
	vector<int> t(1,0);
	v[0] = 1;
	dfs(0,t);
	v[0] = 0;
	// waysには0からN-1までの最短経路が入っている
	queue<int> a,b;
	for(int i=0;i<ways.size();i++){
		if(i < (ways.size()+1)/2){
			a.push(ways[i]);
		}
		else {
			b.push(ways[i]);
		}
		v[ways[i]]=1;
	}
	bool astart = 0,bstart = 0;
	if(ways.size()%2==0)astart = 1;
	else bstart = 1;
	while(1){
		//aのターン 0になったら塗れたことにする
		bool aturn = 1,bturn = 1;
		//現時点から行ける場所にとりあえず行く
		if(astart){
			while(aturn && !a.empty()){
				int now = a.front();
				for(auto next:to[now]){
					if(v[next]==0){
						v[next]=1;
						a.push(next);
						aturn = 0;
						break;
					}
				}
				if(aturn)a.pop();
			}
			if(aturn){
				cout << "Snuke" << endl;
				return 0;
			}
			bstart = 1;
		}else {
			astart = 1;
			bstart = 1;
		}
		//bのターン
		//現時点から行ける場所にとりあえず行く
		if(bstart){
			while(bturn && !b.empty()){
				int now = b.front();
				for(auto next:to[now]){
					if(v[next]==0){
						v[next]=2;
						b.push(next);
						bturn = 0;
						break;
					}
				}
				if(bturn)b.pop();
			}
			if(bturn){
				cout << "Fennec" << endl;
				return 0;
			}
			astart = 1;
		}else{
			bstart = 1;
		}
	}
}

