int main()
{
    ll i,j;
    ll n;
    cin >> n;
    vector<vector<ll>> graph(n);
    for(i = 0;i < n-1;++i){
        ll a,b;
        cin >> a >> b;
        --a;    --b;
        graph.at(a).push_back(b);
        graph.at(b).push_back(a);
    }
    vector<ll> f(n,-1);
    vector<ll> snu(n,-1);
    queue<ll> que;
    f.at(0) = 0;
    que.emplace(0);
    while(!que.empty()){
        ll now = que.front();
        ll dist = f.at(now);
        que.pop();
        for(i = 0;i < graph.at(now).size();++i){
            ll next = graph.at(now).at(i);
            if(f.at(next) == -1){
                f.at(next) = dist+1;
                que.emplace(next);
            }
        }
    }
    snu.at(n-1) = 0;
    que.emplace(n-1);
    while(!que.empty()){
        ll now = que.front();
        ll dist = snu.at(now);
        que.pop();
        for(i = 0;i < graph.at(now).size();++i){
            ll next = graph.at(now).at(i);
            if(snu.at(next) == -1){
                snu.at(next) = dist+1;
                que.emplace(next);
            }
        }
    }
    ll fval = 0;
    ll snuval = 0;
    for(i = 0;i < n;++i){
       if(f.at(i) <= snu.at(i)) ++fval;
       else ++snuval;
    }
    if(fval > snuval) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;
    return 0;
}

