pair<ll,int> dfs(vector<vector<int>> &g, int n, int par, int v, int d) {
  ll ans0 = 1;

	if (v == n-1) {
		return {1, d};
	}

	int nLength = -1;
	for (int w : g[v]) {
	  if (w != par){
			int verN = dfs(g, n, v, w, d + 1).first;
			int length = dfs(g, n, v, w, d + 1).second;

			chmax(nLength, length);
		  if (length == -1 || d+1 <= length / 2) { 
		    ans0 += verN;
			}
		}
	}

	return {ans0, nLength};
}

