class UnionFind {
public:
    vector <ll> par;
    vector <ll> siz;

    UnionFind(ll sz_): par(sz_), siz(sz_, 1LL) {
        for (ll i = 0; i < sz_; ++i) par[i] = i;
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);
        for (ll i = 0; i < sz_; ++i) par[i] = i;
    }

    ll find(ll x) {
        while (par[x] != x) {
            x = par[x] = par[par[x]];
        }
        return x;
    }

    bool merge(ll x, ll y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool issame(ll x, ll y) {
        return find(x) == find(y);
    }

    ll size(ll x) {
        return siz[find(x)];
    }
};


void dfs(vector<ll> &p, ll node, ll par = -1){
    p.push_back(node);
    if (node == N - 1){
        path = p;
        return;
    }
    eachdo(g[node], e){
        if (e == par) continue;
        dfs(p, e, node);
    }
    p.pop_back();
}

int main(){
    cin >> N;
    g.resize(N);
    rep(i, N - 1){
        ll a, b; cin >> a >> b;
        g[--a].push_back(--b);
        g[b].push_back(a);
    }
    vector<ll> t;
    dfs(t, 0);
    ll cut_u = path[(path.size() + 1) / 2 - 1];
    ll cut_v = path[(path.size() + 1) / 2];
    UnionFind uf(N);
    rep(i, N){
        eachdo(g[i], e){
            if (i <= e) continue;
            if ((i == cut_u && e == cut_v) || (e == cut_u && i == cut_v)) continue;
            uf.merge(i, e);
        }
    }
    pt(uf.size(0) >= uf.size(N - 1) ? "Fennec" : "Snuke");
    // pt(uf.size(0), uf.size(N - 1));
}

