using namespace std;

vector<int> fennec_to_snuke, snuke_to_fennec;
vector<vector <int>> v;


void search_path(int node, int snuke_s, vector<int> path, unordered_set<int> v_set)
{
    if(node == snuke_s){
        fennec_to_snuke = path;
        reverse(path.begin(), path.end());
        snuke_to_fennec = path;
        return;
    }
    else {
        int m;
        m = v[node].size();
        for(int i=0; i<m; ++i){
            if(v_set.find(v[node][i]) == v_set.end()){
                vector<int> new_path(path);
                unordered_set<int> new_v_set(v_set);
                new_path.push_back(v[node][i]);
                new_v_set.insert(v[node][i]);
                search_path(v[node][i], snuke_s, new_path, new_v_set);
            }
        }
    }
    return;
}

string fennec_vs_snuke(int sn){
    unordered_set<int> fennec_v, fennec_next_v, snuke_v, snuke_next_v;
    bool fennec_flag, snuke_flag;
    fennec_flag = true;
    snuke_flag = true;
    fennec_v.insert(1);
    for (int i=0; i<(int)v[1].size(); ++i){
        fennec_next_v.insert(v[1][i]);
    }

    snuke_v.insert(sn);
    for (int i=0; i<(int)v[sn].size(); ++i){
        snuke_next_v.insert(v[sn][i]);
    }

    auto fennec_itr = ++fennec_to_snuke.begin();
    auto snuke_itr = ++snuke_to_fennec.begin();

    while(true){
        // fennec's turn
        if(fennec_itr != fennec_to_snuke.end() && fennec_flag){
            if(snuke_v.find(*fennec_itr) == snuke_v.end()){
                // paint node
                // cout << "Fennec get: " << *fennec_itr << endl;
                fennec_v.insert(*fennec_itr);
                snuke_next_v.erase(*fennec_itr);
                fennec_next_v.erase(*fennec_itr);

                // add paintable node
                for (int i=0; i<(int)v[*fennec_itr].size(); ++i){
                    if(snuke_v.find(v[*fennec_itr][i]) == snuke_v.end() && fennec_v.find(v[*fennec_itr][i]) == fennec_v.end()){
                        // cout << "Fennec add: " << v[*fennec_itr][i] << endl;
                        fennec_next_v.insert(v[*fennec_itr][i]);
                    }
                }
                fennec_itr++;
            }
            else {
                fennec_flag = false;
            }
        }
        if(!fennec_flag){
            if(fennec_next_v.size() > snuke_next_v.size()){
                return "Fennec";
            }
            else {
                return "Snuke";
            }
        }

        // snuke's turn
        if(snuke_itr != snuke_to_fennec.end() && snuke_flag){
            if(fennec_v.find(*snuke_itr) == fennec_v.end()){
                // cout << "Snuke get: " << *snuke_itr << endl;
                snuke_v.insert(*snuke_itr);
                fennec_next_v.erase(*snuke_itr);
                snuke_next_v.erase(*snuke_itr);
                for (int i=0; i<(int)v[*snuke_itr].size(); ++i){
                    if(fennec_v.find(v[*snuke_itr][i]) == fennec_v.end() && snuke_v.find(v[*snuke_itr][i]) == snuke_v.end()){
                        // cout << "Snuke add: " << v[*snuke_itr][i] << endl;
                        snuke_next_v.insert(v[*snuke_itr][i]);
                    }
                }
                snuke_itr++;
            }
            else {
                snuke_flag = false;
            }
        }
        if(!snuke_flag){
            if(snuke_next_v.size() > fennec_next_v.size()){
                return "Snuke";
            }
            else {
                return "Fennec";
            }
        }
    }

}

