#include <bits/stdc++.h>
using namespace std;

static const int MAX = 1e5;
static const int INF = 1e9;

// 隣接リストを用いた幅優先探索 O(|V|+|E|)
int n;
vector<int> G[MAX], d(MAX, INF), d2(MAX, INF); // 始点sから頂点iまでの最短距離をd[i]に記録
// main関数からこれらを削除すること

void bfs(int s, vector<int> &x) {
  queue<int> q;
  q.push(s);
  x[s] = 0;
  while(!q.empty()){
    int u = q.front();
    q.pop();
    for(int v = 0; v < G[u].size(); v++){
    if(x[G[u][v]] == INF){
        x[G[u][v]] = x[u] + 1;
        q.push(G[u][v]);
      }
    }
  }
}

int main() {
// 無向(有向)グラフの隣接リスト
  int u, v;
  cin >> n;

  for(int i = 0; i < n - 1; i++){
    cin >> u >> v;
    u--;
    v--;
    G[u].push_back(v);
    G[v].push_back(u); // 有向グラフではこの行をコメントアウト
  }

  bfs(0, d);
  bfs(n - 1, d2);

  int f = 0, sn = 0;
  for(int i = 0; i < n; i++){
    if(d[i] > d2[i]) sn++;
    else f++;
  }

  if(f > sn) cout << "Fennec" << endl;
  else cout << "Snuke" << endl;
}

