using Graph = vector<vector<int>>;
Graph G;

int f[100005];
int s[100005];

void dfs(int v, int p, string name){
    for(auto e: G[v]){
        if(e == p) continue;
        if(name == "Snuke") s[e] = s[v] + 1;
        else f[e] = f[v] + 1;
        dfs(e, v, name);
    }
    return;
}

int main(){
    int n;
    cin >> n;
    G.assign(n, vector<int>());
    rep(i, n-1){
        int a, b;
        cin >> a >> b;
        a--; b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    dfs(n-1, -1, "Fennec");
    dfs(0, -1, "Snuke");

    int S = 0;
    int F = 0;
    rep(i, n){
        if(f[i] < s[i]) S++;
        if(s[i] < f[i]) F++;
        if(s[i] == f[i]) F++;
    }

    if(S <= F) cout << "Fennec" << endl;
    else cout << "Snuke" << endl;
}

