        if (seen2[next_v]) {
        	continue;
        } // next_v が探索済だったらスルー
        if (next_v == 0){
        	return make_pair(count, 1);
        }
        return dfs2(G, next_v, count); // 再帰的に探索
    }
    return make_pair(count, 0);
