using namespace std;

typedef vector<vector<int>> Graph;

stack<int> dfs(Graph &g, int s, int t)
{ 
  vector<bool> flag(g.size(), false);
  stack<int> st;
  flag[s] = true;
  st.push(s);
  while(!st.empty())
  {
    int current = st.top();
    if(current == t)
    {
      return st;
    }else{
      bool nv = false;
      for(int i = 0; i < g[current].size(); i++)
      {
        int next = g[current][i];
        if(!flag[next])
        {
          nv = true;
          flag[next] = true;
          st.push(next);
          break;
        }
      }
      if(!nv)
      {
        st.pop();
      }
    }
  }
  return st;
}

int count_non_path(Graph &g, vector<int> mem, int s)
{
  int count = 0;
  vector<bool> flag(g.size(), false);
  queue<int> q;
  flag[s] = true;
  q.push(s);
  while(!q.empty())
  {
    int current = q.front();
    q.pop();
    for(int i = 0; i < g[current].size(); i++)
    {
      int next = g[current][i];
      if(mem[next] != 0) continue;
      if(flag[next]) continue;
      flag[next] = true;
      q.push(next);
      count++;
    }
  }
  return count;
}

int main()
{
  int n;
  cin >> n;
  Graph tree(n);
  for(int i = 0; i < n - 1; i++)
  {
    int a, b;
    cin >> a >> b;
    tree[a - 1].push_back(b - 1);
    tree[b - 1].push_back(a - 1);
  }
  stack<int> result = dfs(tree, 0, n - 1);
  //パス内の点を登録
  int count = 0;
  vector<int> in_path(n, 0);
  while(!result.empty())
  {
    int temp = result.top();
    result.pop();
    in_path[temp] = 1;
    count++;
  }
  //パス外の点をカウント
  int non_path_b = count_non_path(tree, in_path, 0);
  int non_path_w = count_non_path(tree, in_path, n - 1);
  //判定
  if(count % 2 == 0)
  {
    //パスではwの勝ち
    if(non_path_b > non_path_w)
    {
      cout << "Fennec" << endl;
    }else{
      cout << "Snuke" << endl;
    }
  }else{
    //パスではbの勝ち
    if(non_path_b < non_path_w)
    {
      cout << "Snuke" << endl;
    }else{
     cout << "Fennec" << endl;
    }
  }
	return 0;
}

