  g.exec(0);
  ll dist = g.dist(n - 1);
  // cout << dist << endl;
  ll v = n - 1;
  vl color(n, -1);
  vl path;
  path.emplace_back(n - 1);
  while (v > 0) {
    v = g.prev(v);
    path.emplace_back(v);
  }
  reverse(ALL(path));
  rep(i, path.size()) {
    if (i < path.size() / 2)
      color[path[i]] = 0;
    else
      color[path[i]] = 1;
  }
  // rep(i, n) { cout << color[i] << endl; }
  queue<ll> que;
  rep(i, n) {
    if (color[i] == 0) {
      que.push(i);
    }
  }
  // cout << que.size() << endl;
  while (!que.empty()) {
    ll v = que.front();
    que.pop();
    for (auto& e : g.G_[v]) {
      ll to = e.to;
      if (color[to] == -1) {
        // cout << to << endl;
        color[to] = 0;
        que.push(to);
      }
    }
  }
  ll cnt0 = 0;
  rep(i, n) {
    if (color[i] == 0) {
      cnt0++;
    }
  }
  // cout << cnt0 << endl;
  if (cnt0 > (n - cnt0)) {
    cout << "Fennec" << endl;
  } else {
    cout << "Snuke" << endl;
  }
  return 0;
}

