using namespace std;
const int MAXN=100000;
int n;
vector<int> G[MAXN+10];
int col[MAXN+10];
int dep[MAXN+10],sz[MAXN+10];
void dfs(const int x,const int fa)
{
	sz[x]=1;dep[x]=dep[fa]+1;
	for(unsigned int i=0;i!=G[x].size();++i)
	{
		if(G[x][i]==fa)continue;
		dfs(G[x][i],x);
		sz[x]+=sz[G[x][i]];
	}
}
int main()
{
	memset(col,-1,sizeof col);
	scanf("%d",&n);
	int u,v;
	for(int i=1;i<n;++i)
	{
		scanf("%d%d",&u,&v);
		G[u].push_back(v);
		G[v].push_back(u);
	}
	dep[0]=-1;
	dfs(1,0);
	int cnt=((dep[n]-1)>>1)+sz[n]-1;
	if(cnt>=n-2-cnt)puts("Snuke");
	else puts("Fennec");
	return 0;
}

