using namespace std;
#define N (1000000000+7)
#define INF 1e16
typedef pair<int,int> P;
typedef long long ll;

struct edge{
    int to;
};
int dist[100010];
int area[100010];
vector<edge>graph[100010];
vector<int>prever;
int n;

vector<int> get(int g){
    vector<int>path;
    for(;g!=-1;g=prever[g])path.push_back(g);
    return path;
}

void dfs(int s,int r){
    for(int i=0;i<(int)graph[s].size();i++){
        int next=graph[s][i].to;
        if(r==next)continue;
        if(area[next]==1) continue;
        if(area[next]==-1){
            area[next]=0;
            dfs(next,s);
        }
        if(area[next]==0){
            dfs(next,s);
        }
    }
    return;
}

void solve(int s,int g){
    int mi=0;
    dist[0]=0;
    vector<int>ans;
    queue<int>que;
    que.push(s);
    while(!que.empty()){
        bool flag=false;
        int now=que.front();
        que.pop();
        for(int i=0;i<(int)graph[now].size();i++){
            int next=graph[now][i].to;
            if(dist[next]>dist[now]+1){
                dist[next]=dist[now]+1;
                prever[next]=now;
                if(next==g){
                    mi=dist[next];
                    flag=true;
                    break;
                }
                else{
                    que.push(next);
                }
            }
        }
        if(flag)break;
    }
    ans=get(g);
    reverse(ans.begin(),ans.end());
    for(int i=0;i<(int)ans.size();i++){
        //cout<<ans[i]<<endl;
        if(((int)ans.size()%2==0)){
            if(i<((int)ans.size()/2))area[ans[i]]=0;
            else area[ans[i]]=1;
        }
        else{
            if(i<=((int)ans.size()/2))area[ans[i]]=0;
            else area[ans[i]]=1;
        }
    }
    dfs(0,0);
    int value=0;
    for(int i=0;i<n;i++){
        if(area[i]==0)value++;
    }
    if(value==n-value){
        cout<<"Snuke"<<endl;
    }
    else{
        if(value>n-value)cout<<"Fennec"<<endl;
        else cout<<"Snuke"<<endl;
    }
    return;
}

int main(void){
    int a,b;
    cin>>n;
    for(int i=0;i<n-1;i++){
        cin>>a>>b;
        a--;
        b--;
        graph[a].push_back({b});
        graph[b].push_back({a});
    }
    prever=vector<int>(n,-1);
    for(int i=0;i<n;i++){
        dist[i]=1000000;
        area[i]=-1;
    }
    solve(0,n-1);
    return 0;
}

#include <iostream>
