const int MAX=1e5+1;

vector<vector<int>> g(100005);

int df[MAX];
int dl[MAX];

bool bfs(int f,int l){
    memset(df,0,sizeof(df));
    memset(dl,0,sizeof(dl));
    queue<int> quef;
    queue<int> quel;
    quef.push(f);
    quel.push(l);
    while(!quef.empty()){
        int u=quef.front(); quef.pop();
        for(auto it=g[u].begin();it!=g[u].end();it++){
            int next=*it;
            if(!df[next]){
                df[next]=df[u]+1;
                quef.push(next);
            }
        }
    }
    while(!quel.empty()){
        int u=quel.front(); quel.pop();
        for(auto it=g[u].begin();it!=g[u].end();it++){
            int next=*it;
            if(!dl[next]){
                dl[next]=dl[u]+1;
                quel.push(next);
            }
        }
    }
}

int main(){
