    cin >> N;
    for(int i=0;i<N-1;i++){
        int a,b;
        cin >> a >> b;
        a--;b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    bfs(0,N-1);
    int a=0;
    int b=0;
    for(int i=1;i<N-1;i++){
        if(df[i]<=dl[i]){
            a++;
        }else{
            b++;
        }
    }
    if(a>b){
        cout << "Fennec" << endl;
    }else{
        cout << "Snuke" << endl;
    }
}

