main :: IO ()
main = do
    n <- readLn @Int
    es <- U.unfoldrN (n - 1) (runParser $ (,) <$> int1 <*> int1) <$> C.getContents
    putStrLn . bool "Snuke" "Fennec" $ solve n es

solve :: Int -> U.Vector (Int, Int) -> Bool
solve n es = runST $ do
    size <- UM.replicate n 1
    depth <- UM.replicate n (0 :: Int)
    parent <- UM.replicate n (-1)
    UM.write depth fennec 1
    fix (\dfs d pv v -> do
        U.forM_ (U.filter (/=pv) $ adj gr v) $ \nv -> do
            UM.write depth nv (d + 1)
            UM.write parent nv v
            dfs (d + 1) v nv
            c <- UM.read size nv
            UM.modify size (+c) v
        ) 1 (-1) fennec
    h <- UM.read depth snuke
    s <- fix (\dfs v -> do
        dv <- UM.read depth v
        if dv == div h 2 + 1
        then UM.read size v
        else UM.read parent v >>= dfs
        ) snuke
    return $! n - s > s
  where
    fennec = 0
    snuke = n - 1
    !gr = buildUndirectedGraph n es
