int main(void){
    int n,count;
    scanf("%d",&n);
    int a[n],b[n];
    bool visited[n];
    for (int i=0; i<n-1; i++){
        scanf("%d%d",&a[i],&b[i]);
        a[i]--;
        b[i]--;
    }


    int next,q[n],costf[n],costs[n];

    count=1;
    next=0;
    costf[0]=0;
    for (int i=0; i<n; i++){
        visited[i]=false;
    }
    for (int i=0; i<count; i++){
        visited[next]=true;
        for (int j=0; j<n-1; j++){
            if (a[j]==next && visited[b[j]]==false){
                q[count]=b[j];
                costf[b[j]]=costf[next]+1;
                count++;
            } else if (b[j]==next && visited[a[j]]==false){
                q[count]=a[j];
                costf[a[j]]=costf[next]+1;
                count++;
            }
        }
        next=q[i+1];
    }

    count=1;
    next=n-1;
    costs[n-1]=0;
    for (int i=0; i<n; i++){
        visited[i]=false;
    }
    for (int i=0; i<count; i++){
        visited[next]=true;
        for (int j=0; j<n-1; j++){
            if (a[j]==next && visited[b[j]]==false){
                q[count]=b[j];
                costs[b[j]]=costs[next]+1;
                count++;
            } else if (b[j]==next && visited[a[j]]==false){
                q[count]=a[j];
                costs[a[j]]=costs[next]+1;
                count++;
            }
        }
        next=q[i+1];
    }

    int f=0,s=0;
    for (int i=0; i<n; i++){
        if(costf[i]<=costs[i]){
            f++;
        } else {
            s++;
        }
    }

    if (f>s){
        printf("Fennec\n");
    } else {
        printf("Snuke\n");
    }

	return 0 ;
}

