int par[100000];

void turn(int x){
    if (par[par[x]]!=par[x]){
        turn(par[x]);
    }
    par[par[x]]=x;
    par[x]=x;
}

void unite(int x,int y){
    if (par[x]==x && par[y]==y){
        if (x>y){
            par[x]=y;
        } else {
            par[y]=x;
        }
    } else if (par[x]==x){
        par[x]=y;
    } else if (par[y]==y){
        par[y]=x;
    } else {
        if (x>y){
            turn(x);
            par[x]=y;
        } else {
            turn(y);
            par[y]=x;
        }
    }
}

void unite2(int x,int y){
    if (par[x]==x && par[y]==y){
        if (x<y){
            par[x]=y;
        } else {
            par[y]=x;
        }
    } else if (par[x]==x){
        par[x]=y;
    } else if (par[y]==y){
        par[y]=x;
    } else {
        if (x<y){
            turn(x);
            par[x]=y;
        } else {
            turn(y);
            par[y]=x;
        }
    }
}

int count(int x){
    if (par[x]==x){
        return 0;
    } else {
        return count(par[x])+1;
    }
}


