int
main(int argc, const char *argv[])
{
  vector<int> g[100010];
  int n;
  scanf("%d", &n);
  int a, b;
  for (int i = 0; i < n - 1; i++) {
    scanf("%d %d", &a, &b);
    a--; b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  queue<int> p, q;

  p.push(0); p.push(-1);
  q.push(n); q.push(-1);
  int color[100010] = {}, x, y;
  color[0] = 1; color[n - 1] = 2;
  while (!p.empty() && !q.empty()) {
    if (!p.empty()) {
      while (1) {
	x = p.front(); p.pop();
	if (x == -1) break;
	for (int i = 0; i < g[x].size(); i++) {
	  if (color[g[x][i]] == 0) {
	      color[g[x][i]] = 1;
	      p.push(g[x][i]);
	  }
	}
      }
      if (!p.empty()) p.push(-1);
    }
    if (!q.empty()) {
      while (1) {
	y = q.front(); q.pop();
	if (y == -1) break;
	for (int i = 0; i < g[y].size(); i++) {
	  if (color[g[y][i]] == 0) {
	    color[g[y][i]] = 1;
	    q.push(g[y][i]);
	  }
	}
      }
      if (!q.empty()) q.push(-1);
    }
  }

  int f = 0, s = 0;
  for (int i = 0; i < n; i++) {
    if (color[i] == 1) f++;
    else s++;
  }

  if (f <= s) printf("Snuke\n");
  else printf("Fennec\n");

  return 0;
}

