int main(void){
    int n,count=1;
    scanf("%d",&n);
    int a[n],b[n];
    bool visited[n];
    for (int i=0; i<n; i++){
        scanf("%d%d",&a[i],&b[i]);
        a[i]--;
        b[i]--;
        visited[i]=false;
    }

    int next=0,q[n],cost[n];
    cost[0]=0;
    for (int i=0; i<count; i++){
        visited[next]=true;
        if (next!=n-1){
            for (int j=0; j<n; j++){
                if (a[j]==next && visited[b[j]]==false){
                    q[count]=b[j];
                    cost[b[j]]=cost[next]+1;
                    count++;
                } else if (b[j]==next && visited[a[j]]==false){
                    q[count]=a[j];
                    cost[a[j]]=cost[next]+1;
                    count++;
                }
            }
        }
        next=q[i+1];
    }
    int f=count-(cost[n-1]+1)/2-1;
    if (f>(n-2)/2){
        printf("Fennec\n");
    } else {
        printf("Snuke\n");
    }

	return 0 ;
}

