long *tree[100001];

int main(void) {

  long n;
  scanf("%ld\n", &n);
  long tree_s[n+1];
  for (long i = 0; i <= n; i++) {
    tree_s[i] = 0;
  }
  long a,b;
  for (long i = 0; i < n-1; i++) {
    scanf("%ld %ld", &a, &b);
    tree[a] = realloc(tree[a], sizeof(long)*(tree_s[a]+1));
    tree[a][tree_s[a]] = b;
    tree_s[a]++;
    tree[b] = realloc(tree[b], sizeof(long)*(tree_s[b]+1));
    tree[b][tree_s[b]] = a;
    tree_s[b]++;
  }
  long parent[n+1],depth[n+1],color[n+1];
  for (long i = 0; i <= n; i++) {
    parent[i] = -1;
    depth[i] = -1;
    color[i] = -1;
  }
  parent[1] = 0;
  depth[1] = 0;
  color[1] = 1;
  color[n] = 0;
  long queue[n];
  queue[0] = 1;
  long start = 0, end = 0, tail = 0;
  long cur,next;
  while (tail < n-1) {
    for (long i = start; i <= end; i++) {
      cur = queue[i];
      for (long j = 0; j < tree_s[cur]; j++) {
        next = tree[cur][j];
        if (next == parent[cur]) {
          continue;
        }
        parent[next] = cur;
        depth[next] = depth[cur]+1;
        tail++;
        queue[tail] = next;
      }
    }
    start = end+1;
    end = tail;
  }
  cur = n;
  for (long i = depth[n]-1; i > depth[n]/2; i--) {
    cur = parent[cur];
    color[cur] = 0;
  }
  for (long i = depth[n]/2; i > 0; i--) {
    cur = parent[cur];
    color[cur] = 1;
  }
  for (long i = 1; i < n; i++) {
    cur = queue[i];
    if (color[cur] == -1) {
      color[cur] = color[parent[cur]];
    }
  }
  long black = 0, white = 0;
  for (long i = 2; i < n; i++) {
    if (color[i] == 1) {
      black++;
    } else {
      white++;
    }
  }
  printf("%ld %ld\n", black, white);
  if (black > white) {
    printf("Fennec\n");
  } else {
    printf("Snuke\n");
  }

  return 0;
}

