}node;
void initNodeArray(node* p, int n){
    for(int i=0; i<n; i++){
        (p+i)->value = 0;
        (p+i)->fst = NULL;
        (p+i)->lst = NULL;
    }
}
void addEdge(node* p, node* target){
    if(p->fst == NULL){
        p->fst = (edge*)malloc(sizeof(edge));
        p->lst = p->fst;
    }else{
        p->lst->next = (edge*)malloc(sizeof(edge));
        p->lst = p->lst->next;
    }
    p->lst->target = target;
    p->lst->next = NULL;
}

int fennec = 0;

void func(node* p, int len, node* pre, node* snuke){
    if(p == snuke){
        fennec -= (len-1)/2;
        return;
    }
    fennec++;
    edge* e = p->fst;
    while(e != NULL){
        if(e->target != pre){
            func(e->target, len+1, p, snuke);
        }
        e = e->next;
    }
    return;
}

