    int a[n],b[n];
    bool visited[n];
    for (int i=0; i<n; i++){
        scanf("%d%d",&a[i],&b[i]);
        a[i]--;
        b[i]--;
        visited[i]=false;
    }

    int next=0,q[n],cost[n];
    cost[0]=0;
    for (int i=0; i<count; i++){
        visited[next]=true;
        for (int j=0; j<n; j++){
            if (a[j]==next && visited[b[j]]==false){
                q[count]=b[j];
                cost[b[j]]=cost[next]+1;
                count++;
            } else if (b[j]==next && visited[a[j]]==false){
                q[count]=a[j];
                cost[a[j]]=cost[next]+1;
                count++;
            }
        }
        next=q[i+1];
    }
    if ((cost[n-1]-1)%2==0){
        Fennec+=(cost[n-1]-1)/2;
        Snuke+=(cost[n-1]-1)/2;
    } else {
        Fennec+=(cost[n-1]-1)/2+1;
        Snuke+=(cost[n-1]-1)/2;
    }

    for (int i=0; i<n; i++){
        visited[i]=false;
    }
    next=0;
    visited[n-1]=true;
    count=1;
    for (int i=0; i<count; i++){
        visited[next]=true;
        for (int j=0; j<n; j++){
            if (a[j]==next && visited[b[j]]==false){
                q[count]=b[j];
                count++;
            } else if (b[j]==next &&visited[a[j]]==false){
                q[count]=a[j];
                count++;
            }
        }
        next=q[i+1];
    }
    Fennec+=count-cost[n-1];

    for (int i=0; i<n; i++){
        visited[i]=false;
    }
    next=n-1;
    visited[0]=true;
    count=1;
    for (int i=0; i<count; i++){
        visited[next]=true;
        for (int j=0; j<n; j++){
            if (a[j]==next && visited[b[j]]==false){
                q[count]=b[j];
                count++;
            } else if (b[j]==next && visited[a[j]]==false){
                q[count]=a[j];
                count++;
            }
        }
        next=q[i+1];
    }
    Snuke+=count-cost[n-1];

    if (Fennec>Snuke){
        printf("Fennec\n");
    } else {
        printf("Snuke\n");
    }

	return 0 ;
}

