    //各ノードの色を格納する配列を用意
    int* color;
    NEW(color,N);
    for(int i=0;i<N;i++) color[i]=GRAY;
    color[0]=BLACK;
    color[N-1]=WHITE;

    //グラフのslist→nodeを更新
    slobj p=G->E[0]->head;
    while(p!=NULL){
        G->E[p->v]->node--;
        p=p->next;
    }
    p=G->E[N-1]->head;
    while(p!=NULL){
        G->E[p->v]->node--;
        p=p->next;
    }

    //1ならフェネック、-1ならすぬけ
    int person=1;    
    while(1){
        //これから塗ろうとするノード番号
        int c_node=-1;
        int tmp=0;
        //自分の色が塗ってあるノードを探索→一番隣接グレーが多いのはどれか探す
        for(int i=0;i<N;i++){
            if(color[i]==person){
                p=G->E[i]->head;
                while(p!=NULL){
                    if(G->E[p->v]->node>tmp){
                        tmp=G->E[p->v]->node;
                        c_node=i;
                    }
                    p=p->next;
                }
            }
        }

        //c_nodeが見つからない→負け
        if(c_node==-1){
            if(person==1) printf("Snuke\n");
            else printf("Fennec\n");
            break;
        }

        //c_nodeが見つかる→更新作業
        color[c_node]=person;
        p=G->E[c_node]->head;
        while(p!=NULL){
            G->E[p->v]->node--;
            p=p->next;
        }

        //人の切り替え
        if(person==1) person=-1;
        else person=1;
    }

    return 0;
}

