int *e[100000];
int el[100000];

int p[100000];

int f(int now, int from, int k){
	if(now==n-1) return 1;
	if(el[now]==1 && e[now][0]==from) return 0;
	for(int i=0; i<el[now]; i++){
		int to=e[now][i];
		if(to!=from){
			int v=f(to, now, k+1);
			if(v>0){
				if(v>k){
					p[now]=1;
				}else{
					p[now]=2;
				}
				return v+1;
			}
		}
	}
	return 0;
}

void g(int now, int from, int x){
	if(el[now]==1 && e[now][0]==from) return;
	for(int i=0; i<el[now]; i++){
		int to=e[now][i];
		if(to!=from){
			if(p[to]==0){
				p[to]=x;
				g(to, now, x);
			}else{
				g(to, now, p[to]);
			}
		}
	}
}

