#include <stdio.h>

#define MAXN    100001

struct
{
    int id;
    int next;
}node[MAXN<<2];
int nnodes;
int front[MAXN];
void add_edge(int u, int v)
{
    int newnode = ++nnodes;
    node[newnode].id = v;
    node[newnode].next = front[u];
    front[u] = newnode;
}

int N;
int vis[MAXN];
int par[MAXN];
int nxt[MAXN];
int chd[MAXN];
int nb, nw;

int dfs2N(int u)
{
    int v = front[u];
    vis[u] = 1;
    if(u == N) return 1;
    while(v)
    {
        int w = node[v].id;
        if(!vis[w])
        {
            if(dfs2N(w))
            {
                u[nxt] = w;
                w[par] = u;
                return 1;
            }
        }
        v = node[v].next;
    }
    return 0;
}

void find_path(void)
{
    int i = 0;
    dfs2N(1);
    for(i = 1;i <= N;++i)
        vis[i] = 0;
    for(i = nxt[1];i != N;i = nxt[i])
        vis[i] = 1;
    vis[1] = vis[N] = 1;
}

int countchd(int u)
{
    int  v = front[u];
    int cnt = 1;
    vis[u] = 1;
    while(v)
    {
        int w = node[v].id;
        if(!vis[w]) cnt += countchd(w);
        v = node[v].next;
    }
    return cnt;
}

void travel_path(void)
{
    int i = 0;
    int u = 1[nxt], v = N[par];
    nb = countchd(1); nw = countchd(N);
    while(u != v && u != v[nxt])
    {
        nb += countchd(u);
        nw += countchd(v);
        u = u[nxt]; v = v[par];
    }
    if(u == v) nb += countchd(u);
}

int main(void)
{
    int i = 0;
    int ai = 0, bi = 0;

    scanf("%d", &N);
    for(i = 1;i < N;++i)
    {
        scanf("%d%d", &ai, &bi);
        add_edge(ai, bi);
        add_edge(bi, ai);
    }
    find_path();
    travel_path();
    printf("%s\n", (nb>nw)?"Fennec":"Snuke");
    return 0;
}

