#define limit 100001

int N;
int cnt[limit];
int visited[limit];
int dist[limit];
int graph[limit][100];

void init(int N){
  for(int i = 0;i < N;i++) visited[i] = 0;
}

void dfs(int v,int depth){
  int fennec = 0,snuke = 0;
  visited[v] = 1;
  dist[v] = depth;
  for(int v2 = 0;v2 < cnt[v];v2++){
    if(visited[graph[v][v2]] == 1) continue;
    dfs(graph[v][v2],depth+1);
  }
}

int main(void){
  int fennec,snuke;
  int a,b;
  scanf("%d",&N);

  for(int i = 0;i < N;i++){
    cnt[i] = 0;
    for(int j = 0;j < 100;j++){
      graph[i][j] = 0;
    }
  }
  for(int i = 0;i < N-1;i++){
    scanf("%d%d",&a,&b);
    graph[a][cnt[a]++] = b;
    graph[b][cnt[b]++] = a;
  }

  init(N);
  dfs(1,0);
  int dist1[N+1];
  for(int i = 1;i <= N;i++) dist1[i] = dist[i];
  init(N);
  dfs(N,0);

  for(int i = 1;i <= N;i++){
    if(dist1[i] > dist[i]) snuke++;
    else fennec++;
  }
  if(fennec >= snuke) printf("Fennec\n");
  else printf("Snuke\n");


  return 0;
}

