void initNodeArray(node* p, int n){
    for(int i=0; i<n; i++){
        (p+i)->col = 0;
        (p+i)->len = 100002;
        (p+i)->fst = NULL;
        (p+i)->lst = NULL;
    }
}
void addEdge(node* p, node* target){
    if(p->fst == NULL){
        p->fst = (edge*)malloc(sizeof(edge));
        p->lst = p->fst;
    }else{
        p->lst->next = (edge*)malloc(sizeof(edge));
        p->lst = p->lst->next;
    }
    p->lst->target = target;
    p->lst->next = NULL;
}

void func(node* p, int len, node* pre, int col){
    p->col = col;
    p->len = len;
    edge* e = p->fst;
    while (e != NULL){
        if(len + 1 < e->target->len){
            func(e->target, len+1, p, col);
        }
        e = e->next;
    }
}

int main(){
    int n;
    scanf("%d", &n);
    node a[n+1];
    initNodeArray(a, n+1);
    rep(i, 1, n){
        int x, y;
        scanf("%d %d", &x, &y);
        addEdge(&a[x], &a[y]);
        addEdge(&a[y], &a[x]);
    }
    a[1].col = 1;
    a[n].col = 2;
    a[1].len = 0;
    a[n].len = 0;
    func(&a[1], 0, &a[1], 1);
    func(&a[n], 0, &a[n], 2);
    int f = 0, s = 0;
    rep(i, 1, n+1){
        if(a[i].col == 1){
            f++;
        }else{
            s++;
        }
    }
    printf(f > s ? "Fennec" : "Snuke");

    return 0;
}

