    static int aout[VERTEX_MAX];
    static int bout[VERTEX_MAX];
    get_dist(graph, 0, -1, aout);
    get_dist(graph, num-1, -1, bout);

    int blacks = 0;
    int whites = 0;
    for(i = 0; i < num; i++) {
        if(aout[i] <= bout[i]) {
            blacks++;
        } else {
            whites++;
        }
    }
#ifdef DEBUG
    printf("%d vs %d\n", blacks, whites);
#endif
    printf("%s\n", blacks > whites ? "Fennec" : "Snuke");
    return 0;
}

