// ソート関数 - 隣接マス - マス(元)昇順
int
fSortFnc(
	const void *pzpVal1			// <I> 値１
	, const void *pzpVal2		// <I> 値２
)
{
	NNo *lzpVal1 = (NNo *)pzpVal1;
	NNo *lzpVal2 = (NNo *)pzpVal2;

	// マス(元)昇順
	if (lzpVal1->miFNo > lzpVal2->miFNo) {
		return(1);
	}
	else if (lzpVal1->miFNo < lzpVal2->miFNo) {
		return(-1);
	}

	return 0;
}

// 指定色からの距離 - セット
int
fSetLen(
	int piCNo					// <I> 色 0～
	, int piMNo					// <I> マス 1～
	, int piLen					// <I> 距離
)
{
	int i;

	// 対象データ
	Mass *lzpMass = &sz1Mass[piMNo];

	// セット済チェック
	if (lzpMass->mi1Len[piCNo] > 0) {
		return 0;
	}

	// セット
	lzpMass->mi1Len[piCNo] = piLen;

	// 隣接マス有無
	if (lzpMass->miNSNo < 1) {
		return 0;
	}

	// 隣接マスへ
	for (i = lzpMass->miNSNo; i <= lzpMass->miNENo; i++) {
		fSetLen(piCNo, sz1NNo[i - 1].miTNo, piLen + 1);
	}

	return 0;
}

