int main(void){
    int n;
    scanf("%d",&n);
    int m=0,head[n*2],next[n*2],to[n*2],a,b,post[n],count;
    bool visited[n];

    for (int i=0; i<n; i++){
        head[i]=-1;
    }
    for (int i=0; i<n-1; i++){
        scanf("%d%d",&a,&b);
        a--;
        b--;
        next[m]=head[a];
        head[a]=m;
        to[m]=b;
        m++;
        next[m]=head[b];
        head[b]=m;
        to[m]=a;
        m++;
    }

    for (int i=0; i<n; i++){
        visited[i]=false;
    }
    int costf[n];
    costf[0]=0;
    visited[0]=true;
    count=0;
    post[0]=0;
    for (int i=0; i<count+1; i++){
        for (int e=head[post[i]]; e!=-1; e=next[e]){
            if (visited[to[e]]==false){
                visited[to[e]]=true;
                costf[to[e]]=costf[post[i]]+1;
                count++;
                post[count]=to[e];
            }
        }
    }

    for (int i=0; i<n; i++){
        visited[i]=false;
    }
    int costs[n];
    costs[n-1]=0;
    visited[n-1]=true;
    count=0;
    post[0]=n-1;
    for (int i=i=0; i<count+1; i++){
        for (int e=head[post[i]]; e!=-1; e=next[e]){
            if (visited[to[e]]==false){
                visited[to[e]]=true;
                costs[to[e]]=costs[post[i]]+1;
                count++;
                post[count]=to[e];                
            }
        }
    }

    int Fennec=0,Snuke=0;
    for (int i=0; i<n; i++){
        if (costf[i]<=costs[i]){
            Fennec++;
        } else {
            Snuke++;
        }
    }

    if (Fennec>Snuke){
        printf("Fennec\n");
    } else {
        printf("Snuke\n");
    }


	return 0 ;
}

