fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val m = n - 1
    val adj = Array(n) { mutableSetOf<Int>() }
    for (i in 0 until m) {
        val u = sc.nextInt() - 1
        val v = sc.nextInt() - 1
        adj[u].add(v)
        adj[v].add(u)
    }
    val dist_black = Array(n) { Int.MAX_VALUE }
    val dist_white = Array(n) { Int.MAX_VALUE }
    val que: Queue<Pair<Int, Int>> = ArrayDeque()
    var visited = BitSet(n)
    visited[0] = true
    que.add(0 to 0)
    while (que.count() > 0) {
        val (v, d) = que.poll()
        dist_black[v] = d
        for (w in adj[v]) {
            if (!visited[w] && w != n - 1) {
                que.add(w to d + 1)
                visited[w] = true
            }
        }
    }
    visited = BitSet(n)
    visited[n - 1] = true
    que.add(n - 1 to 0)
    while (que.count() > 0) {
        val (v, d) = que.poll()
        dist_white[v] = d
        for (w in adj[v]) {
            if (!visited[w] && w != 0) {
                que.add(w to d + 1)
                visited[w] = true
            }
        }
    }
    var b = 0
    var w = 0
    for (i in 0 until n) {
        if (dist_black[i] <= dist_white[i]) {
            b++
        } else {
            w++
        }
    }
    println(if (b > w) "Fennec" else "Snuke")
}

fun compress(a: Array<Int>): Array<Int> {
    val n = a.count()
    val b = a.sorted().distinct().toTypedArray()
    val c = Array(n) { 0 }
    for (i in 0 until n) {
        c[i] = Arrays.binarySearch(b, a[i])
    }
    return c
}

