fun main(arg: Array<String>) {
    val N = nextInt()
    val G = Array<MutableList<Int>>(N) { mutableListOf<Int>() }
    repeat(N - 1) {
        val (a, b) = listOfInt(-1)
        G[a].add(b); G[b].add(a)
    }
    //フェネック  先手  黒  1
    //すぬけくん  後手  白 -1
    val RB = IntArray(N)
    val RW = IntArray(N)
    fun dfs(R: IntArray, v: Int, p: Int = -1) {
        for (u in G[v]) {
            if (u == p) continue
            R[u] += R[v] + 1
            dfs(R, u, v)
        }
    }
    dfs(RB, 0)
    dfs(RW, N - 1)
    val M = IntArray(N)
    for (n in 0 until N) {
        M[n] = if (RB[n] <= RW[n]) 1 else -1
    }
    val Fennec = M.count { it == 1 }
    val Snuke = M.count { it == -1 }
    println(if (Fennec > Snuke) "Fennec" else "Snuke")
//System.err.println(RB.joinToString(" "))
//System.err.println(RW.joinToString(" "))
//System.err.println(M.joinToString(" "))
}

