fun solve() {
    val n = nextLong()
    val nodes: Array<Node> = Array(n.toInt()) { Node(it.toLong()) }
    for (i in 0 until n - 1) {
        val a = nextLong() - 1
        val b = nextLong() - 1
        nodes[a].edges.add(Edge(a, b, 1))
        nodes[b].edges.add(Edge(b, a, 1))
    }

    val adist = bfs(nodes, 0)
    val bdist = bfs(nodes, n - 1)
    var a = 0L
    var b = 0L
    for (i in 0 until n) {
        if(adist[i] <= bdist[i]) a++
        else b++
    }

    println(if(a >= b) "Fennec" else "Snuke")


}




