fun solve(N: Int, a: IntArray, b: IntArray){
    val tree = AdjacentListGraph<Int, Int>(MutableList(N){ Vertex<Int, Int>() })
    for(i in 0 until N - 1){
        tree.addEdge(a[i] - 1, b[i] - 1, 1)
        tree.addEdge(b[i] - 1, a[i] - 1, 1)
    }
    val distances1 = tree.getDistances(0)
    val distances2 = tree.getDistances(N - 1)
    val fennec = (0 until N).count{ distances1[it] <= distances2[it] }
    if(fennec > N - fennec){ println("Fennec") }
    else println("Snuke")
    return
}

fun AdjacentListGraph<Int, Int>.getDistances(from: Int): IntArray{
    // Bread First Search
    val distances = IntArray(vertices.size){ -1 }
    distances[from] = 0
    val queue = ArrayDeque<Int>()
    queue.add(from)
    while(queue.size > 0){
        val node = queue.removeFirst()
        val curDist = distances[node]
        vertices[node].edges.filter{ distances[it.to] == -1 }.forEach{
            val delta = it.weight?: 1
            distances[it.to] = curDist + delta
            queue.add(it.to)
        }
    }
    return distances
}
data class Vertex<T : Comparable<T>, E : Comparable<E>>(val data: T? = null) {
    data class Edge<T : Comparable<T>>(val to: Int, val weight: T? = null)

    val edges = mutableListOf<Edge<E>>()

    fun addEdge(to: Int, weight: E?) = when (edges.find { it.to == to }) {
        null -> {
            edges.add(Edge(to, weight))
            true
        }
        else -> false
    }

    fun removeEdge(to: Int) = edges.removeIf { it.to == to }
}

class AdjacentListGraph<T : Comparable<T>, E : Comparable<E>>(
    val vertices: MutableList<Vertex<T, E>>
) {
    // T = data of Vertex, E = weight of Edge
    fun getWeight(from: Int, to: Int): E? = vertices[from].edges.find { it.to == to }?.weight
    fun addEdge(from: Int, to: Int, weight: E? = null) = vertices[from].addEdge(to, weight)
    fun removeEdge(from: Int, to: Int) = vertices[from].removeEdge(to)
    fun isAdjacent(from: Int, to: Int) = vertices[from].edges.find { it.to == to } != null
}


class Tree<T>(private val nodes: List<T>){
    val edges = mutableMapOf<Int, MutableList<Int>>()
    fun addEdge(from: Int, to: Int) =
        edges[from]?.run{ add(to) }?: { edges[from] = mutableListOf(to) }()

    fun getDistances(from: Int): IntArray{
        // Bread First Search
        val distances = IntArray(nodes.size){ -1 }
        distances[from] = 0
        val queue = ArrayDeque<Int>(from)
        while(queue.size > 0){
            val node = queue.removeFirst()
            val curDist = distances[node]
            edges[node]?.filter{ distances[it] != -1 }?.forEach{
                distances[it] = curDist + 1
                queue.add(it)
            }
        }
        return distances
    }

    fun getShortestPath(from: Int, to: Int): List<Int>?{
        val isVisited = BooleanArray(nodes.size){ false }
        val queue = ArrayDeque<Int>()
        edges[from]?.forEach{ queue.add(it) }
        val path = mutableListOf(from)
        val beforeNodes = IntArray(nodes.size){ -1 }
        while(queue.size > 0){
            val node = queue.removeFirst()
            edges[node]?.filter{ !isVisited[it] }?.forEach{
                beforeNodes[it] = node
                queue.add(it)
            }
            isVisited[node] = true
            if(node == to){
                val path = mutableListOf(to)
                var bef = beforeNodes[to]
                while(bef != -1){
                    path.add(bef)
                    bef = beforeNodes[bef]
                }
                path.add(from)
                return path.reversed()
            }
        }
        return null
    }
}

