/** edge info */
data class Edge(val from: Int, val to: Int, val cost: Long)

fun solve(out: PrintWriter) {
    val n = readInteger()

    /** graph[fromNodeIndex]: edges to other node */
    val graph = Array(n) { mutableListOf<Edge>() }
    repeat(n - 1) {
        val (a, b) = readIntegerList().map { it - 1 }
        graph[a].add(Edge(a, b, 1))
        graph[b].add(Edge(b, a, 1))
    }

    // 1からnへの最短経路を求める
    val costArray = IntArray(graph.size)
    val nearestFrom = IntArray(graph.size)
    val isUnchecked = BooleanArray(graph.size) { true }
    val nodeQueue = ArrayDeque<Int>()
    nodeQueue.addLast(0)
    isUnchecked[0] = false
    while (nodeQueue.isNotEmpty()) {
        val node = nodeQueue.removeFirst()
        for (edge in graph[node]) {
            if (isUnchecked[edge.to]) {
                costArray[edge.to] = costArray[node] + 1
                nearestFrom[edge.to] = node
                isUnchecked[edge.to] = false
                nodeQueue.addLast(edge.to)
            }
        }
    }

    // 1からnへの最短経路の中央でグラフを切る
    val blackLast = costArray[n - 1] / 2
    val whiteMoveCount = costArray[n - 1] - blackLast - 1
    var cutFrom = 0
    var cutTo = 0
    var last = n - 1
    repeat(whiteMoveCount) {
        last = nearestFrom[last]
    }
    cutFrom = nearestFrom[last]
    cutTo = last

    //Unionfindで数えて比較
    val uf = UnionFind(n)
    for (eList in graph) {
        for (e in eList) {
            if (e.from == cutFrom && e.to == cutTo) {
                continue
            }

            if (e.from == cutTo && e.to == cutFrom) {
                continue
            }
            uf.unite(e.from, e.to)
        }
    }

    val ans = if (uf.getSize(0) > uf.getSize(n - 1)) "Fennec" else "Snuke"
    println(ans)
}

/**　Union find 0 ~ (n - 1)　*/
class UnionFind(n: Int) {
    val parent = IntArray(n) { it }
    val rank = IntArray(n)
    val size = IntArray(n) { 1 }

    /** O(α(n)) */
    fun findRoot(x: Int): Int {
        if (parent[x] == x) return x

        parent[x] = findRoot(parent[x])
        return parent[x]
    }

    /** O(α(n)) */
    fun sameRoot(x: Int, y: Int) = findRoot(x) == findRoot(y)

    /** O(α(n)) */
    fun unite(x: Int, y: Int) {
        val x = findRoot(x)
        val y = findRoot(y)
        if (x == y) return

        if (rank[x] < rank[y]) {
            parent[x] = y
            size[y] += size[x]
        } else {
            parent[y] = x
            if (rank[x] == rank[y]) rank[x]++

            size[x] += size[y]
        }
    }

    /** O(α(n)) */
    fun getSize(x: Int) = size[findRoot(x)]
}



