fun main(args: Array<String>) {
    val N = readLine()!!.toInt()

    val graph = Array(N, { mutableListOf<Int>()})
    (1..N-1).forEach {
        val (a, b) = readLine()!!.split(" ").map { it.toInt() }
        graph[a-1].add(b-1)
        graph[b-1].add(a-1)
    }

    fun dFrom(source: Int) : IntArray {
        val default = Int.MAX_VALUE
        val d = IntArray(N, { default })
        val queue : Queue<Int> = ArrayDeque()
        queue.add(source)
        d[source] = 0
        while (!queue.isEmpty()) {
            val current = queue.poll()
            graph[current].forEach {
                if (d[it] == default) {
                    d[it] = d[current] + 1
                    queue.add(it)
                }
            }
        }
        return d
    }
    val dFromS = dFrom(0)
    val dFromT = dFrom(N -1)
    var position = 0
    for (i in 0 until N) {
        if (dFromT[i] - dFromS[i] <= 1) {
            position = i
            break
        }
    }
    val uf = UnionFind(N)
    for (i in 0 until N) {
        if (i != position) {
            graph[i].forEach {
                if (it != position) {
                    uf.merge(i, it)
                }
            }
        }
    }
    uf.merge(position, 0)

    var fennec = uf.size(0)
    var snuke = uf.size(N - 1)
    if (fennec > snuke) {
        println("Fennec")
    } else {
        println("Snuke")
    }
}
internal class UnionFind(size: Int) {
    var parent: IntArray
    var height: IntArray
    var size: IntArray

    init {
        this.parent = IntArray(size)
        this.height = IntArray(size)
        this.size = IntArray(size)

        for (i in 0 until size) {
            makeSet(i)
        }
    }

    fun merge(x: Int, y: Int) {
        val rootX = root(x)
        val rootY = root(y)

        if (rootX == rootY) {
            return
        }

        if (height[rootX] > height[rootY]) {
            parent[rootY] = rootX
            size[rootX] += size[rootY]

        } else if (height[rootX] < height[rootY]) {
            parent[rootX] = rootY
            size[rootY] += size[rootX]

        } else {
            parent[rootY] = rootX
            size[rootX] += size[rootY]
            height[rootX]++
        }
    }

    fun isSame(x: Int, y: Int) : Boolean {
        return root(x) == root(y)
    }

    fun size(x: Int): Int {
        val rootX = root(x)
        return size[rootX]
    }

    private fun root(x: Int): Int {
        if (!isRoot(x)) {
            parent[x] = root(parent[x])
        }
        return parent[x]
    }
    fun isRoot(x: Int): Boolean {
        return x == parent[x]
    }


    private fun makeSet(i: Int) {
        parent[i] = i
        height[i] = 0
        size[i] = 1
    }
}

fun main(args: Array<String>) {
    val N = readInputLine().toInt()
    val next = Array(N) { mutableListOf<Int>() }

    for (i in 0 until N - 1) {
        val (a, b) = readInputLine().split(" ").map { it.toInt() - 1 }
        next[a].add(b)
        next[b].add(a)
    }

    // 0: 未着色 1:Fennec 2:Snuke
    val color = IntArray(N)
    color[0] = 1
    color[N - 1] = 2

    var nextFennec = mutableListOf(0)
    var nextSnuke = mutableListOf(N - 1)

    var usedCnt = 2

    while (usedCnt != N) {
        val nf = mutableListOf<Int>()

        for (n in nextFennec) {
            for (nn in next[n]) {
                if (color[nn] == 0) {
                    color[nn] = 1
                    nf.add(nn)
                    usedCnt++
                }
            }
        }

        nextFennec = nf

        val ns = mutableListOf<Int>()

        for (n in nextSnuke) {
            for (nn in next[n]) {
                if (color[nn] == 0) {
                    color[nn] = 2
                    ns.add(nn)
                    usedCnt++
                }
            }
        }

        nextSnuke = ns
    }

    val fennecCnt = color.count { it == 1 }
    val snukeCnt = N - fennecCnt

    if (fennecCnt > snukeCnt) {
        println("Fennec")
    } else {
        println("Snuke")
    }
}

