data class Position(val cur: Int, val turn: Int)
class Dfs(val n: Int, val edges: Array<MutableList<Int>>) {
	fun dfs(start: Int): Array<Int> {
		val turns = Array(n) { n + 1000 }.apply {
			this[start] = 0
		}
		val st = Stack<Position>()
		st.push(Position(start, 0))
		while(!st.isEmpty()) {
			val pos = st.pop()	
			val nexts = edges[pos.cur]
			nexts.forEach { next ->
				if(turns[next] > pos.turn + 1) {
					st.push(Position(next, pos.turn + 1))	
					turns[next] = pos.turn + 1
				}
			}
		}
		return turns
	}
}

