class Dfs(val n: Int, val edges: Array<MutableList<Int>>) {
	fun dfs(start: Int, goal: Int): Int {
		val visited = Array(n) { false }.apply {
			this[start] = true
		}
		val st = Stack<Int>()
		st.push(start)
		while(!st.isEmpty()) {
			val cur = st.pop()	
			if(cur == goal) continue
			val nexts = edges[cur]
			nexts.forEach { n ->
				if(!visited[n]) {
					st.push(n)	
					visited[n] = true
				}
			}
		}
		var cnt = 0
		for(i in 0 until n) {
			if(i != start && i != goal && visited[i]) {
				cnt++
			}
		}
		return cnt
	}
}

