fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val m = n - 1
    val adj = Array(n) { mutableSetOf<Int>() }
    for (i in 0 until m) {
        val u = sc.nextInt() - 1
        val v = sc.nextInt() - 1
        adj[u].add(v)
        adj[v].add(u)
    }
    val black = BitSet(n)
    val white = BitSet(n)
    val stack = Stack<Int>()
    stack.add(0)
    var visited = BitSet(n)
    visited[0] = true
    while (stack.count() > 0) {
        val v = stack.pop()
        black[v] = true
        for (w in adj[v]) {
            if (!visited[w] && w != n - 1) {
                stack.add(w)
                visited[w] = true
            }
        }
    }
    visited = BitSet(n)
    visited[n - 1] = true
    stack.add(n - 1)
    while (stack.count() > 0) {
        val v = stack.pop()
        white[v] = true
        for (w in adj[v]) {
            if (!visited[w] && w != 0) {
                stack.add(w)
                visited[w] = true
            }
        }
    }
    var only_b = 0
    var only_w = 0
    var bandw = 0
    for (i in 0 until n) {
        if (black[i] && white[i]) bandw++
        else if (black[i]) only_b++
        else only_w++
    }
    val b = only_b + (bandw + 1) / 2
    val w = only_w + bandw / 2
    println(if (b > w) "Fennec" else "Snuke")
}

fun compress(a: Array<Int>): Array<Int> {
    val n = a.count()
    val b = a.sorted().distinct().toTypedArray()
    val c = Array(n) { 0 }
    for (i in 0 until n) {
        c[i] = Arrays.binarySearch(b, a[i])
    }
    return c
}

