import java.util.ArrayList;
import java.util.Arrays;
import java.util.Queue;

public class Main {
	static int n;

	public static void main(String args[]) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		n = Integer.parseInt(br.readLine());

		ArrayList<ArrayList<Integer>> edge = new ArrayList<>();

		for (int i = 0; i < n; i++) {
			edge.add(new ArrayList<>());
		}

		for (int i = 0; i < n - 1; i++) {
			String str[] = br.readLine().split(" ");

			int a = Integer.parseInt(str[0]) - 1;
			int b = Integer.parseInt(str[1]) - 1;
			edge.get(a).add(b);
			edge.get(b).add(a);
		}

		int fennec = 0;
		int snuke = 0;

		int distF[] = bfs(edge, 0);
		int distS[] = bfs(edge, n - 1);

		for (int i = 0; i < n; i++) {
			if (distF[i] < distS[i]) {
				fennec++;
			} else if (distF[i] == distS[i]) {
				fennec++;
			} else {
				snuke++;
			}
			//System.out.println(i + " " + distF[i] + " " + distS[i]);
		}
		if (fennec > snuke) {
			System.out.println("Fennec");
		} else {
			System.out.println("Snuke");
		}
	}

	static int[] bfs(ArrayList<ArrayList<Integer>> edge, int s) {
		boolean used[] = new boolean[n];
		int[] dist = new int[n];
		Queue<Integer> queue = new ArrayDeque<>();

		Arrays.fill(dist, Integer.MAX_VALUE);
		dist[s] = 0;
		used[s] = true;
		queue.add(s);

		while (!queue.isEmpty()) {
			int now = queue.poll();
			for (int i = 0; i < edge.get(now).size(); i++) {
				int next = edge.get(now).get(i);
				if (!used[next]) {
					used[next] = true;
					dist[next] = dist[now] + 1;
					queue.add(next);
				}
			}
		}
		return dist;
	}
}

import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;

public class Main {
	static class Node{
		List<Node>nextList;
		boolean visited;

		int type;

		public Node(){
			nextList = new LinkedList<>();
			visited = false;
			this.type = 0;
		}

		public void addNext(Node next){
			nextList.add(next);
		}

		public int count(int c,int type){
			if(visited){
				return c;
			}
			if(this.type > 0 && this.type != type){
				return c;
			}
			c += 1;
			visited = true;
			for(Node n : nextList){
				c += n.count(c,this.type);
			}
			return c;
		}

		public void setVisited(boolean flag){
			visited = flag;
		}

		public void setType(int type){
			this.type = type;
		}
	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		Node[] nodes = new Node[N];
		for(int i = 0; i < N;i++){
			nodes[i] = new Node();
		}
		nodes[0].type = 1;
		nodes[N - 1].type = 2;

		for(int i = 0;i < N - 1;i++){
			int a = sc.nextInt() - 1;
			int b = sc.nextInt() - 1;
			nodes[a].addNext(nodes[b]);
			nodes[b].addNext(nodes[a]);
		}

		int black = nodes[0].count(0,nodes[0].type);
		for(int i = 0;i < N;i++){
			nodes[i].setVisited(false);
		}
		int white = nodes[N - 1].count(0,nodes[N - 1].type);

		if(white < black){
			System.out.println("Fennec");
		}else{
			System.out.println("Snuke");
		}
	}
}

