    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int N = scan.nextInt();
        Map<Integer, Set<Integer>> tree = new HashMap<>();
        for (int i : IntStream.range(0, N - 1).toArray()) {
            int a = Integer.parseInt(scan.next());
            int b = Integer.parseInt(scan.next());
            Set<Integer> map = tree.getOrDefault(a, new HashSet<>());
            map.add(b);
            tree.put(a, map);
            map = tree.getOrDefault(b, new HashSet<>());
            map.add(a);
            tree.put(b, map);
        }

        int blackCount = bfs(tree, N);
        if (blackCount > 0) {
            System.out.println("Fennec");
        } else {
            System.out.println("Snuke");
        }

    }

    static int bfs(Map<Integer, Set<Integer>> tree, int N) {
        int[] nodes = new int[N+1];
        nodes[1] = 1;
        nodes[N] = -1;
        LinkedList<List<Integer>> deque = new LinkedList<>();
        deque.addFirst(Arrays.asList(1, 1));
        deque.addFirst(Arrays.asList(N, -1));
        while (!deque.isEmpty()) {
            List<Integer> node = deque.removeLast();
            for (int next : tree.get(node.get(0))) {
                if(nodes[next] != 0) {
                    continue;
                }
                nodes[next] = node.get(1);
                deque.addFirst(Arrays.asList(next, node.get(1)));
            }
        }
        return Arrays.stream(nodes).sum();
    }

}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

public class Main {
	static int n;
	static int[][] m = new int[2000][2000];
	static int max = Integer.MAX_VALUE;

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		n = scan.nextInt();

		// ノード同士の関係を記録
		for (int i = 0; i < n - 1; i++) {
			int a = scan.nextInt() - 1;
			int b = scan.nextInt() - 1;
			m[a][b] = 1;
			m[b][a] = 1;

		}
		int[] f = bfs(0);
		int[] s = bfs(n - 1);
		int ansF = 0;
		int ansS = 0;
		int flag = 1;
		for (int i = 0; i < n; i++) {
			if (f[i] <= s[i]) {
				ansF++;

			} else {
				ansS++;

			}
		}

		if (ansF > ansS) {
			System.out.println("Fennec");
		} else {
			System.out.println("Snuke");
		}

	}

	public static int[] bfs(int u) {
		int[] ans = new int[2000];
		Deque<Integer> q = new ArrayDeque<Integer>();
		q.offer(u);
		Arrays.fill(ans, max);
		ans[u] = 0;

		while (!q.isEmpty()) {
			// 調べるノードを取り出す
			int v = q.poll();
			for (int i = 0; i < n; i++) {
				if (m[v][i] == 0) {
					continue;
				}
				if (ans[i] != max) {
					continue;
				}
				ans[i] = ans[v] + 1;
				q.offer(i);
			}
		}
		return ans;

	}

}

