import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    private static Scanner scan = new Scanner(System.in);

    public static void main(String[] args) {
	int N = Integer.parseInt(scan.next());
	UnionFind u = new UnionFind(N);
	List<Integer> bNeighbor = new ArrayList<Integer>();
	List<Integer> wNeighbor = new ArrayList<Integer>();
	for (int i = 0; i < N-1; i++) {
	    int a = Integer.parseInt(scan.next()) - 1;
	    int b = Integer.parseInt(scan.next()) - 1;
	    if(a > b) {
		int tmp = a;
		a = b;
		b = tmp;
	    }
	    if(a == 0 && b != N-1) {
		bNeighbor.add(b);
	    } else if(b == N-1 && a != 0) {
		wNeighbor.add(a);
	    } else if(a != 0 && b != N-1) {
		u.connect(a, b);
	    }
	}

	List<Integer> black = new ArrayList<Integer>();
	List<Integer> white = new ArrayList<Integer>();
	List<Integer> both = new ArrayList<Integer>();
	for(int node: bNeighbor) black.add(u.root(node));
	for(int node: wNeighbor) {
	    int g = u.root(node);
	    if(black.contains(Integer.valueOf(g))) {
		black.remove(Integer.valueOf(g));
		both.add(g);
	    } else {
		white.add(g);
	    }
	}

	int blackCount = 0;
	for(int g: black) blackCount += u.size(g);
	int whiteCount = 0;
	for(int g: white) whiteCount += u.size(g);
	int bothCount = 0;
	for(int g: both) bothCount += u.size(g);

	if(bothCount % 2 != 0) blackCount++;

	System.out.println(blackCount > whiteCount ? "Fennec" : "Snuke");
	scan.close();
    }

    private static class UnionFind {
	private int[] u;

	public UnionFind(int n) {
	    u = new int[n];
	    for (int i = 0; i < n; i++) {
		u[i] = -1;
	    }
	}

	public int size(int a) {
	    return -u[root(a)];
	}

	public int root(int a) {
	    if(u[a] < 0) return a;
	    return u[a] = root(u[a]);
	}

	public boolean connect(int a, int b) {
	    a = root(a);
	    b = root(b);
	    if(a == b) return false;
	    if(u[a] > u[b]) {
		int tmp = a;
		a = b;
		b = tmp;
	    }
	    u[a] += u[b];
	    u[b] = a;
	    return true;
	}
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main
{
    private static boolean solve(boolean player, Boolean[] vertices, Map<Integer, List<Integer>> nodes)
    {
        boolean put = false;
        for (int i = 0; i < vertices.length; i++) {
            Boolean v = vertices[i];
            if (v == null) {
                continue;
            }

            if ((player && v) || (!player && !v)) {
                List<Integer> dstList = nodes.get(i);
                if (dstList == null) {
                    continue;
                }
                for (int dst : dstList) {
                    if (vertices[dst] == null) {
                        Boolean[] newVertices = Arrays.copyOf(vertices, vertices.length);
                        newVertices[dst] = player;
                        if (!solve(!player, newVertices, nodes)) {
                            put = true;
                        }
                    }
                }
            }
        }
        return put;
    }

    private static ArrayList<Integer> shortestRoute(int cur, int goal, ArrayList<Integer> route, Map<Integer, List<Integer>> nodes)
    {
        if (cur == goal) {
            return route;
        }

        for (int next : nodes.get(cur)) {
            if (!route.contains(next)) {
                ArrayList<Integer> newRoute = new ArrayList<>(route);
                newRoute.add(next);
                ArrayList<Integer> result = shortestRoute(next, goal, newRoute, nodes);
                if (result != null) {
                    return result;
                }
            }
        }

        return null;
    }

    private static void prevail(boolean[] vertices, int cur, List<Integer> shortestRoute, Map<Integer, List<Integer>> nodes) {
        vertices[cur] = true;
        for (int next : nodes.get(cur)) {
            if (!vertices[next] && !shortestRoute.contains(next)) {
                prevail(vertices, next, shortestRoute, nodes);
            }
        }
    }

    public static void main(String[] args)
    {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        Map<Integer, List<Integer>> nodes = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();

            nodes.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
            nodes.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
        }

        ArrayList<Integer> shortestRoute;
        {
            ArrayList<Integer> list = new ArrayList<>();
            list.add(1);
            shortestRoute = shortestRoute(1, n, list, nodes);
        }

        boolean[] vertices = new boolean[n + 1];
        for (int i = 0; i < Math.ceil(shortestRoute.size() / 2.0); i++) {
            prevail(vertices, shortestRoute.get(0), shortestRoute, nodes);
        }

        int fennecCells = 0;
        for (boolean b : vertices) {
            if (b) {
                fennecCells++;
            }
        }

        if (fennecCells > (n - fennecCells)) {
            System.out.println("Fennec");
        }
        else {
            System.out.println("Snuke");
        }
    }
}

import java.util.*;

class Main{
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        HashSet<Integer>[] map = new HashSet[N+1];
        for(int i=0;i<=N;i++) map[i]=new HashSet<>();
        for(int i=1;i<=N-1;i++){
            int a = sc.nextInt();
            int b = sc.nextInt();
            map[a].add(b);
            map[b].add(a);
        }
        int[] color = new int[N+1];
        color[1]=1; // black is 1
        color[N]=-1; // white is -1;
        boolean isBlack = true;
        LinkedList<Integer> bCur = new LinkedList<>();
        LinkedList<Integer> bNext = new LinkedList<>();
        LinkedList<Integer> wCur = new LinkedList<>();
        LinkedList<Integer> wNext = new LinkedList<>();
        bCur.add(1);
        wCur.add(N);
        while(bCur.size()>0||wCur.size()>0){
            if(isBlack&&bCur.size()==0){
                isBlack = false;
                continue;
            }
            if((!isBlack)&&wCur.size()==0){
                isBlack=true;
                continue;
            }
            if(isBlack){
                int cur = bCur.poll();
                for(Integer w:map[cur]){
                    if(color[w]==0){
                        color[w]=1;
                        bNext.add(w);
                    }
                }
                if(bCur.size()==0){
                    bCur = bNext;
                    bNext = new LinkedList<>();
                    isBlack = !isBlack;
                }
            } else{
                int cur = wCur.poll();
                for(Integer w:map[cur]){
                    if(color[w]==0){
                        color[w]=-1;
                        wNext.add(w);
                    }
                }
                if(wCur.size()==0){
                    wCur = wNext;
                    wNext = new LinkedList<>();
                    isBlack = !isBlack;
                }
            }
        }
        int bCnt = 0;
        for(int i=1;i<=N;i++){
            if(color[i]==1) bCnt++;
        }
        String ans = "Snuke";
        if(bCnt>N-bCnt) ans = "Fennec";
        System.out.println(ans);
    }
}

