import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		Map<Integer,List<Integer>> tree = new HashMap<>();
		for(int i=0;i<n-1;i++) {
			int a = in.nextInt();
			int b = in.nextInt();
			if(tree.containsKey(a)) tree.get(a).add(b);
			else {
				List<Integer> list = new ArrayList<>();
				list.add(b);
				tree.put(a, list);
			}
			if(tree.containsKey(b)) tree.get(b).add(a);
			else {
				List<Integer> list = new ArrayList<>();
				list.add(a);
				tree.put(b, list);
			}
		}
		in.close();
		int[] board = new int[n+1];
		board[1] = 1;
		board[n] = -1;
		Queue<Integer> que = new ArrayDeque<>();
		que.add(1);
		que.add(n);
		while(!que.isEmpty()) {
			int now = que.poll();
			for(int next:tree.get(now)) {
				if(board[next]==0) {
					board[next] = board[now];
					que.add(next);
				}
			}
		}
		int sum = 0;
		for(int i=1;i<=n;i++) {
			sum += board[i];
		}
		System.out.println(sum>0?"Fennec":"Snuke");
	}

}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

public class Main {
	static int n;
	static int[][] m = new int[100000][100000];

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		for (int i = 0; i < n; i++) {
			m[scan.nextInt() - 1][scan.nextInt() - 1] = 1;
		}
		int[] ansF = bfs(0);
		int[] ansS = bfs(n - 1);
		int f = 0;
		int s = 0;
		int flag = 1;
		for (int i = 0; i < n; i++) {
			if (ansF[i] < ansS[i]) {
				f++;
			} else if (ansF[i] > ansS[i]) {
				s++;
			} else {
				if (flag % 2 == 1) {
					f++;
				} else {
					s++;
				}
			}
		}
		if (f > s) {
			System.out.println("Fennec");
		} else {
			System.out.println("Snuke");
		}

	}

	public static int[] bfs(int a) {
		int[] ans = new int[100001];
		Deque<Integer> q = new ArrayDeque<>();
		q.offer(a);
		Arrays.fill(ans, -1);
		ans[a] = 0;
		while (!q.isEmpty()) {
			int b = q.poll();
			for (int i = 0; i < n; i++) {
				if (m[b][i] == 0) {
					continue;
				}
				if (ans[i] != -1) {
					continue;
				}
				ans[i] = ans[b] + 1;
				q.offer(i);
			}
		}
		return ans;
	}
}

import java.util.*;
import java.io.*;

class Main{
    static int[] num=new int[2];
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int n=fsc.nextInt();
        ArrayList<Integer>[] nodes=new ArrayList[n];
        for(int i=0;i<n;i++) nodes[i]=new ArrayList<>();
        for(int i=0;i<n-1;i++){
            int a=fsc.nextInt()-1, b=fsc.nextInt()-1;
            nodes[a].add(b);
            nodes[b].add(a);
        }
        fsc.close();
        int[] path=bfs(nodes);
        int len=path.length;
        int[] color=new int[n];
        for(int i=0;i<n;i++) color[i]=-1;
        for(int i=0;i<len;i++){
            color[path[i]]=i<len/2?0:1;
        }
        for(int i=0;i<len;i++){
            coloring(nodes, color, path[i], i<len/2?0:1);
        }
        if(num[0]>num[1]) System.out.println("Fennec");
        else System.out.println("Snuke");
    }
    static void coloring(ArrayList<Integer>[] nodes, int[] color, int st, int c){
        ArrayDeque<Integer> q=new ArrayDeque<>();
        q.add(st);
        while(q.size()!=0){
            int u=q.removeFirst();
            for(int v:nodes[u]){
                if(color[v]<0){
                    q.addLast(v);
                    color[v]=c;
                    num[c]++;
                }
            }
        }
    }

    static int[] bfs(ArrayList<Integer>[] nodes){
        ArrayDeque<Integer> q=new ArrayDeque<>();
        q.add(0);
        int n=nodes.length;
        int[] d=new int[n];
        int[] prev=new int[n];
        for(int i=0;i<n;i++) d[i]=-1;
        d[0]=0;
        while(q.size()!=0){
            int u=q.removeFirst();
            for(int v:nodes[u]){
                if(d[v]<0){
                    q.addLast(v);
                    d[v]=d[u]+1;
                    prev[v]=u;
                }
            }
        }
        int[] path=new int[d[n-1]+1];
        int now=n-1;
        for(int i=0;i<d[n-1]+1;i++){
            path[d[n-1]-i]=now;
            now=prev[now];
        }
        return path;
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

import java.util.*;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int N = scan.nextInt();
        List<List<Integer>> tree = new ArrayList<>();
        for (int i :IntStream.range(0, N-1).toArray()){
            tree.add(Arrays.asList(scan.nextInt(), scan.nextInt()));
        }

        List<Integer> path = dijkstra(tree, N);
        path.forEach(System.out::println);
        List<Integer> black = new ArrayList<>();
        int blackNum = path.size() / 2 + path.size() % 2;
        int forbidden = path.get(blackNum);
        int blackCount = count(tree,black,forbidden,N);
        if(path.size() % 2 == 0) {
            if(N < blackCount * 2) {
                System.out.println("Fennec");
            }
            else{
                System.out.println("Snuke");
            }
        }
        else {
            if(N < blackCount * 2 + 1) {
                System.out.println("Fennec");
            }
            else{
                System.out.println("Snuke");
            }
        }
    }

    static List<Integer> dijkstra(List<List<Integer>> tree, int N) {
        LinkedList<List<Integer>> stack = new LinkedList<>();
        stack.add(Collections.singletonList(1));
        List<List<Integer>> ret = new ArrayList<>();
        for (int i :IntStream.range(0, N).toArray()){
            List<Integer> current = stack.removeFirst();
            int node = current.get(current.size()-1);
            tree.stream().filter(x -> x.contains(node)).forEach(path ->{
                int next = path.get(0) != node ? path.get(0) : path.get(1);
                if(next == N) {
                    List<Integer> tmp = new ArrayList<>(current);
                    tmp.add(next);
                    ret.add(tmp);
                }
                if(!current.contains(next)) {
                    List<Integer> tmp = new ArrayList<>(current);
                    tmp.add(next);
                    stack.add(tmp);
                }
            });
            if(!ret.isEmpty()) {
                return ret.get(0);
            }
        }
        return null;
    }

    static int count(List<List<Integer>> tree, List<Integer> black, int forbidden, int N) {
        List<Integer> tmp = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            int firstSize = tree.size();
            for(int j = 0; j < tree.size();){
                int a = tree.get(j).get(0);
                int b = tree.get(j).get(1);
                if(a == forbidden || b == forbidden) {
                    tree.remove(j);
                    continue;
                }
                for (int data : black) {
                    if(data == a && !black.contains(b)) {
                        tree.remove(j);
                        tmp.add(b);
                        break;
                    }
                    else if(data == b && !black.contains(a)) {
                        tree.remove(j);
                        tmp.add(a);
                        break;
                    }
                }
                if(tmp.isEmpty()) {
                    j++;
                }
                else {
                    black.addAll(tmp);
                    tmp.clear();
                }
            }
            if(firstSize == tree.size()) {
                return black.size();
            }
        }
        return black.size();
    }
}

