@SuppressWarnings("unused")
public class Main {

	//final boolean isDebug = true;
	final boolean isDebug = false;
	String fileName = "input.txt";
	FastScanner sc;
	PrintWriter out;
	final int MOD = (int)1e9+7;
	final int INF = Integer.MAX_VALUE / 2;

	void solve() throws Exception{
		int N = sc.nextInt();
		ArrayList<ArrayList<Integer>> G = new ArrayList<>();
		for(int i = 0; i < N; i++) G.add(new ArrayList<>());
		for(int i = 0; i < N-1; i++){
			int s = sc.nextInt()-1;
			int t = sc.nextInt()-1;
			G.get(s).add(t);
			G.get(t).add(s);
		}

		int[] num = new int[N];
		Arrays.fill(num, Integer.MAX_VALUE / 2);
		int[] from = new int[N];
		Arrays.fill(from, -1);
		Queue<Integer> queue = new ArrayDeque<Integer>();
		queue.add(0);
		num[0] = 0;

		while(queue.size() != 0){
			int v = queue.poll();
			if(v == N-1) break;
			for(int next : G.get(v)){
				if(num[next] > num[v] + 1){
					num[next] = num[v] + 1;
					from[next] = v;
					queue.add(next);
				}
			}
		}

		boolean[] visited = new boolean[N];
		int now = N-1;
		for(int i = 0; now != -1; i++){
			//System.out.println(now);
			if(i <= (num[N-1] - 1) / 2) visited[now] = true;
			now = from[now];
		}
		//System.out.println(num[N-1]);

		int numF = 1;
		Queue<Integer> queueAns = new ArrayDeque<>();
		queueAns.add(0);

		while(queueAns.size() != 0){
			int v = queueAns.poll();
			for(int next : G.get(v)){
				if(!visited[next]){
					visited[next] = true;
					numF++;
					queueAns.add(next);
				}
			}
		}

		System.out.println((numF > N - numF) ? "Fennec" : "Snuke");
	}

	/* end solve */

	/* main */
	public static void main(String[] args) throws Exception {
		new Main().m();
	}

	void m() throws Exception {
		long S = System.currentTimeMillis();
		sc = (isDebug) ? new FastScanner(new FileInputStream(fileName)) : new FastScanner(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
		long G = System.currentTimeMillis();
		if(isDebug){
			System.out.println("---Debug---");
			System.out.printf("%8d ms\n", (G-S));
		}
	}
	/* end main */
}
