class FastScanner {
    private InputStream in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    public FastScanner(InputStream in) {
		this.in = in;
	}
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() {
    	if (hasNextByte()) return buffer[ptr++];
    	else return -1;
    }
    private static boolean isPrintableChar(int c){
    	return 33 <= c && c <= 126;
    }
    public boolean hasNext() {
    	while(hasNextByte() && !isPrintableChar(buffer[ptr]))
    		ptr++; return hasNextByte();
    }
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public String nextLine() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(b != 10) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() {
    	return Double.parseDouble(next());
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Scanner;
import java.util.Stack;

class Main {

    public static void main(String[] args) {
        new Main().compute();
    }

    void compute() {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        List<Integer>[] adjacents = new List[N];
        for (int i = 0; i < N; i++) {
            adjacents[i] = new ArrayList<>();
        }
        for (int i = 0; i < N - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            adjacents[a].add(b);
            adjacents[b].add(a);
        }
        int[] fromFennec = new int[N];
        Arrays.fill(fromFennec, N);
        Stack<Integer> stk = new Stack<>();
        fromFennec[0] = 0;
        stk.push(0);
        while (!stk.empty()) {
            int start = stk.pop();
            int dist = fromFennec[start] + 1;
            for (int i : adjacents[start]) {
                if (fromFennec[i] == N) {
                    fromFennec[i] = dist;
                    stk.push(i);
                }
            }
        }
        int[] fromSnuke = new int[N];
        Arrays.fill(fromSnuke, N);
        fromSnuke[N - 1] = 0;
        stk.push(N - 1);
        while (!stk.empty()) {
            int start = stk.pop();
            int dist = fromSnuke[start] + 1;
            for (int i : adjacents[start]) {
                if (fromSnuke[i] == N) {
                    fromSnuke[i] = dist;
                    stk.push(i);
                }
            }
        }
        int sum = 0;
        for (int i = 0; i < N; i++) {
            if (fromFennec[i] > fromSnuke[i]) {
                sum++;
            }
        }
        if (sum >= N - sum) {
            System.out.println("Snuke");
        } else {
            System.out.println("Fennec");
        }
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	class Masu {
		int masuNumber;
		ArrayList<Integer> closeMasuNumber;

		Masu(int i) {
			masuNumber = i;
			closeMasuNumber = new ArrayList<Integer>();
		}
	}

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);

		// マスの数を取得
		int masuNum = scan.nextInt();

		ArrayList<Masu> masuList = new ArrayList<Masu>();
		Main main = new Main();
		for(int i = 0; i < masuNum; i++) {
			masuList.add(main.new Masu(i));
		}

		for(int i = 0; i < masuNum - 1; i++) {
			main.inputMasu(scan.nextInt(), scan.nextInt(), masuList);
		}

		int[] fennecList = new int[masuNum];
		fennecList[0] = -1;
		int[] snukeList = new int[masuNum];
		snukeList[masuNum - 1] = -1;

		// 何手で相手のマスに行き着くか計算する
		// fennecの探査
		main.tansa(masuList,fennecList,0,0);
		// snukeの探査
		main.tansa(masuList,snukeList,masuNum - 1,0);

		int fennecWinMasu = 0;
		int snukeWinMasu = 0;

		for(int i = 0; i < masuNum; i++) {
			if(fennecList[i] <= snukeList[i]) {
				fennecWinMasu++;
			} else {
				snukeWinMasu++;
			}
		}

		if(fennecWinMasu > snukeWinMasu) {
			System.out.println("Fennec");
		} else {
			System.out.println("Snuke");
		}
	}

	private void inputMasu(int i, int j, ArrayList<Masu> masuList) {
		masuList.get(i - 1).closeMasuNumber.add(j - 1);
		masuList.get(j - 1).closeMasuNumber.add(i - 1);
	}

	private void tansa(ArrayList<Masu> masuList, int[] tansaList, int masu, int depth) {
		ArrayList<Integer> closeMasuList = masuList.get(masu).closeMasuNumber;

		for(Integer i:closeMasuList) {
			if(tansaList[i] == 0) {
				tansaList[i] = depth + 1;
				tansa(masuList, tansaList, i , depth + 1);
			}
		}
	}
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		new Main().solve();
	}

	int N;
	int[]a;
	int[]b;

	void solve(){
		Scanner sc=new Scanner(System.in);
		N=sc.nextInt();
		a=new int[N-1];
		b=new int[N-1];
		ArrayList<Integer>[] path=new ArrayList[N];
		int []dist_1=new int[N];
		int []dist_N=new int[N];
		boolean[] visited=new boolean[N];
		dist_1[0]=0;
		dist_N[N-1]=0;
		for(int i=0;i<N;i++){
			path[i]=new ArrayList<Integer>();
		}
		for(int i=0;i<N-1;i++){
			a[i]=sc.nextInt()-1;
			b[i]=sc.nextInt()-1;
			path[a[i]].add(b[i]);
			path[b[i]].add(b[i]);
		}

		Queue<Integer> nowq=new LinkedList<Integer>();
		Queue<Integer> nextq=new LinkedList<Integer>();

		nowq.add(0);
		int count=0;
		while(!nowq.isEmpty()){
			int now=nowq.poll();
			visited[now]=true;
			dist_1[now]=count;

			for(int i=0;i<path[now].size();i++){
				if(!visited[path[now].get(i)]) nextq.add(path[now].get(i));
			}
			nowq=nextq;
			count++;
		}

		nowq.add(N-1);
		count=0;
		Arrays.fill(visited, false);
		while(!nowq.isEmpty()){
			int now=nowq.poll();
			visited[now]=true;
			dist_N[now]=count;

			for(int i=0;i<path[now].size();i++){
				if(!visited[path[now].get(i)]) nextq.add(path[now].get(i));
			}
			nowq=nextq;
			count++;
		}

		int snukeCount=0;
		int fennecCount=0;
		for(int i=0;i<N;i++){
			if(dist_1[i]<=dist_N[i])fennecCount++;
			else snukeCount++;
		}

		if(fennecCount>snukeCount)System.out.println("Fennec");
		else System.out.println("Snuke");

	}
}

import java.io.BufferedReader;
