/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Hamza Hasbi
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        D_Fennec_VS_Snuke solver = new D_Fennec_VS_Snuke();
        solver.solve(1, in, out);
        out.close();
    }

    static class D_Fennec_VS_Snuke {
        private static final int inf = Integer.MAX_VALUE;
        private static int n;
        private static int ans = 0;
        private static HashMap<Integer, ArrayList<Integer>> graph = new HashMap<>();
        private static int[] vis = new int[100005];
        private static int[] parent = new int[100005];
        private static int[] color = new int[100005];

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            graph.clear();

            for (int i = 0; i < n - 1; i++) {
                int a = in.nextInt();
                int b = in.nextInt();
                if (!graph.containsKey(a)) {
                    graph.put(a, new ArrayList<Integer>());
                }
                if (!graph.containsKey(b)) {
                    graph.put(b, new ArrayList<Integer>());
                }
                graph.get(a).add(b);
                graph.get(b).add(a);
            }
            color[1] = 1;
            color[n] = 2;
            bfs(1);
            int max_dis = vis[n];
            int first = (int) Math.ceil(max_dis / 2.0);
            int second = (int) Math.floor(max_dis / 2.0);
            int des = n;
            Arrays.fill(vis, 0);
            //out.printLine(first+" "+second);
            vis[1] = 1;
            vis[n] = 1;
            while (des > 0) {
                if (parent[des] == -1) break;
                vis[parent[des]] = 1;
                des = parent[des];
            }
            first += dfs(1);
            ans = 0;
            second += dfs(n);
            //out.printLine(first+" "+second);
            out.printLine(first > second ? "Fennec" : "Snuke");

        }

        public static int dfs(int node) {
            vis[node] = 1;
            ans++;
            for (int vertex : graph.get(node)) {
                if (vis[vertex] == 0) {
                    //System.out.println(node+"->"+vertex);
                    dfs(vertex);
                }
            }
            return ans;
        }

        public static void bfs(int node) {
            Arrays.fill(vis, inf);
            Arrays.fill(parent, -1);
            vis[node] = 1;
            ArrayDeque<Integer> q = new ArrayDeque<>();
            q.push(node);
            parent[node] = -1;
            while (!q.isEmpty()) {
                int vertex = q.poll();

                for (int v : graph.get(vertex)) {
                    if (vis[v] == inf) {
                        parent[v] = vertex;
                        vis[v] = vis[vertex] + 1;
                        q.push(v);
                    }
                }

            }
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void printLine(String s) {
            writer.println(s);
        }

        public void close() {
            writer.close();
        }

    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer st;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            st = null;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (Exception e) {
                    throw new RuntimeException();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;
import java.io.*;


public class Main {

    public static Node[] nodes;
    public static PriorityQueue<Node> fennecCanColor, snukeCanColor;
    public static boolean[] colored;

    public static void main(String[] args) throws Exception{

        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        int n = Integer.parseInt(in.readLine());

        nodes = new Node[n+1];
        colored = new boolean[n+1];
        fennecCanColor = new PriorityQueue<Node>();
        snukeCanColor = new PriorityQueue<Node>();

        for(int i = 1; i <= n; i++){
            nodes[i] = new Node();
            nodes[i].num = i;
        }

        colored[1] = true;
        colored[n] = true;

        for(int i = 1; i < n; i++){
            String[] input = in.readLine().split("\\s+");
            int a = Integer.parseInt(input[0]);
            int b = Integer.parseInt(input[1]);

            nodes[a].adjList.add(nodes[b]);
            nodes[b].adjList.add(nodes[a]);

            nodes[a].canColorSize++;
            nodes[b].canColorSize++;

            if(a == 1 || a == n){
                nodes[b].canColorSize--;
            }

            if(b == 1 || b == n){
                nodes[a].canColorSize--;
            }

            if(a == 1 && b != n){
                fennecCanColor.add(nodes[b]);
                nodes[b].added++;
            }
            else if(a == n && b != 1){
                snukeCanColor.add(nodes[b]);
                nodes[b].added++;
            }

            if(b == 1 && a != n){
                fennecCanColor.add(nodes[a]);
                nodes[a].added++;
            }
            else if(b == n && a != 1){
                snukeCanColor.add(nodes[a]);
                nodes[a].added++;
            }
        }

        boolean fennec = true;;

        while(play(fennec)){
            fennec = !fennec;
        }

        if(fennec){
            out.println("Snuke");
        }
        else{
            out.println("Fennec");
        }

        in.close();
        out.close();
    }

    public static boolean play(boolean fennec){
        if(fennec){
            return playFennec();
        }
        return playSnuke();
    }

    public static boolean playFennec(){

        int size = fennecCanColor.size();

        if(size == 0){
            return false;
        }

        Node tmpNode = fennecCanColor.poll();
        //System.out.println("Fennec colors: " + tmpNode.num);
        colored[tmpNode.num] = true;
        addAdjList(tmpNode.num, true);
        if(tmpNode.added > 1){
            snukeCanColor.remove(tmpNode);
        }

        return true;

    }

    public static boolean playSnuke(){

        int size = snukeCanColor.size();

        if(size == 0){
            return false;
        }

        Node tmpNode = snukeCanColor.poll();
        //System.out.println("Snuke colors: " + tmpNode.num);
        colored[tmpNode.num] = true;
        addAdjList(tmpNode.num, false);
        if(tmpNode.added > 1){
            fennecCanColor.remove(tmpNode);
        }

        return true;

    }

    public static void addAdjList(int num, boolean fennec){
        if(fennec){
            for(Node node : nodes[num].adjList){
                node.canColorSize--;
                if(snukeCanColor.remove(node)){
                    snukeCanColor.add(node);
                }
                if(!colored[node.num]){
                    //System.out.println("\tFennec adds: " + node.num);
                    node.added++;
                    fennecCanColor.remove(node);
                    fennecCanColor.add(node);
                }
            }
        }
        else{
            for(Node node : nodes[num].adjList){
                node.canColorSize--;
                if(fennecCanColor.remove(node)){
                    fennecCanColor.add(node);
                }
                if(!colored[node.num]){
                    //System.out.println("\tSnuke adds: " + node.num);
                    node.added++;
                    snukeCanColor.remove(node);
                    snukeCanColor.add(node);
                }
            }
        }
    }
}

class Node implements Comparable<Node> {

    public int num;
    public int added;
    public int canColorSize;
    public ArrayList<Node> adjList;

    public Node(){
        adjList = new ArrayList<Node>();
        canColorSize = 0;
        added = 0;
    }

    @Override
    public int compareTo(Node n){
        if(this.added > n.added)
            return -1;
        if(n.added > this.added)
            return 1;
        return -1 * Integer.compare(this.canColorSize, n.canColorSize);
    }

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Queue;
import java.util.StringJoiner;

class Main {

    static PrintWriter out;
    static InputReader sc;

    static final int MOD = (int) 1e9 + 7;

    static List<List<Integer>> graph;
    static int[] memo;

    public static void main(String[] args) {
        sc = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    static void solve() {
        int N = sc.nextInt();
        graph = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            graph.add(new ArrayList<Integer>());
        }
        for (int i = 0; i < N - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            graph.get(a).add(b);
            graph.get(b).add(a);
        }
        memo = new int[N];
        Arrays.fill(memo, -1);
        size(0, -1);
        int s = memo[N - 1];
        Arrays.fill(memo, -1);
        size(N - 1, -1);
        int f = memo[0];
        Arrays.fill(memo, -1);
        Queue<Integer> que = new ArrayDeque<>();
        memo[0] = 0;
        que.add(0);
        while (!que.isEmpty()) {
            int v = que.poll();
            for (int u : graph.get(v)) {
                if (memo[u] == -1) {
                    memo[u] = memo[v] + 1;
                    que.add(u);
                }
            }
        }
        int p = memo[N - 1] - 1;
        f += (p + 1) / 2;
        s += p / 2;
        out.println(f > s ? "Fennec" : "Snuke");
    }

    static int size(int s, int p) {
        int res = 1;
        for (int v : graph.get(s)) {
            if (v != p) {
                res += size(v, s);
            }
        }
        return memo[s] = res;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            Class<?> type = arg.getClass();
            if (type.getComponentType().isArray()) {
                for (Object o : (Object[]) arg) {
                    debug(o);
                }
            } else if (arg instanceof int[]) {
                j.add(Arrays.toString((int[]) arg));
            } else if (arg instanceof long[]) {
                j.add(Arrays.toString((long[]) arg));
            } else if (arg instanceof double[]) {
                j.add(Arrays.toString((double[]) arg));
            } else if (arg instanceof char[]) {
                j.add(Arrays.toString((char[]) arg));
            } else if (arg instanceof boolean[]) {
                j.add(Arrays.toString((boolean[]) arg));
            } else if (arg instanceof Object[]) {
                j.add(Arrays.toString((Object[]) arg));
            } else {
                j.add(arg.toString());
            }
        }
        System.err.println(j.toString());
    }

    static class InputReader {

        private InputStream in;
        private byte[] buffer = new byte[1024];
        private int curbuf;
        private int lenbuf;

        public InputReader(InputStream in) {
            this.in = in;
            this.curbuf = this.lenbuf = 0;
        }

        public boolean hasNextByte() {
            if (this.curbuf >= this.lenbuf) {
                this.curbuf = 0;
                try {
                    this.lenbuf = this.in.read(this.buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (this.lenbuf <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (this.hasNextByte()) {
                return this.buffer[this.curbuf++];
            } else {
                return -1;
            }
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private void skip() {
            while (this.hasNextByte() && this.isSpaceChar(this.buffer[this.curbuf])) {
                this.curbuf++;
            }
        }

        public boolean hasNext() {
            this.skip();
            return this.hasNextByte();
        }

        public String next() {
            if (!this.hasNext()) {
                throw new NoSuchElementException();
            }
            StringBuilder sb = new StringBuilder();
            int b = this.readByte();
            while (!this.isSpaceChar(b)) {
                sb.appendCodePoint(b);
                b = this.readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            if (!this.hasNext()) {
                throw new NoSuchElementException();
            }
            int c = this.readByte();
            while (this.isSpaceChar(c)) {
                c = this.readByte();
            }
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = this.readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = res * 10 + c - '0';
                c = this.readByte();
            } while (!this.isSpaceChar(c));
            return minus ? -res : res;
        }

        public long nextLong() {
            if (!this.hasNext()) {
                throw new NoSuchElementException();
            }
            int c = this.readByte();
            while (this.isSpaceChar(c)) {
                c = this.readByte();
            }
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = this.readByte();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = res * 10 + c - '0';
                c = this.readByte();
            } while (!this.isSpaceChar(c));
            return minus ? -res : res;
        }

        public double nextDouble() {
            return Double.parseDouble(this.next());
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = this.nextInt();
            }
            return a;
        }

        public long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) {
                a[i] = this.nextLong();
            }
            return a;
        }

        public char[][] nextCharMap(int n, int m) {
            char[][] map = new char[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = this.next().toCharArray();
            }
            return map;
        }
    }
}

import java.util.*;

import static java.lang.System.*;

// https://atcoder.jp/contests/abc067/tasks/arc078_b
// 1<->N番目の間を通るマスを埋めたあとに、それ以外のところを埋めるのが最適な戦略
// グラフ木なので、閉路は持たない。最小の通り方は1つだけ
// O(N)
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[][] edges = new int[N][N];

        for (int i = 0; i < N - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            edges[a][b] = 1;
            edges[b][a] = 1;
        }

        solver(N, edges);
    }

    public static void solver(int N, int[][] edges) {
        // 0->N-1番目の最短経路を埋める
        List<Integer> shortestPath = dijkstra(N, edges, 0, N-1);

        int length = shortestPath.size();
        //out.println(Arrays.toString(shortestPath.toArray()));
        int splitNode1 = shortestPath.get((int)Math.floor(length/2) - 1);      //white
        int splitNode2 = shortestPath.get((int)Math.floor(length/2));          //black

        //out.println(splitNode1+","+splitNode2);

        // 通せなくする
        edges[splitNode1][splitNode2] = 0;
        edges[splitNode2][splitNode1] = 0;

        int blackCount = 0; //countNodes(N, edges, 0);
        int whiteCount = 1; //countNodes(N, edges, N-1);

        if(blackCount > whiteCount){
            out.println("Fennec");
        } else {
            out.println("Snuke");
        }

        //out.println(blackCount+","+whiteCount);

    }

    // start地点から行けるところを全て行ったときのノードの数
    public static int countNodes(int N, int[][] graph, int start){
        PriorityQueue<Integer> queue = new PriorityQueue<Integer>();
        queue.add(start);

        boolean[] passed = new boolean[N];
        passed[start] = true;

        int count = 1;

        while(!queue.isEmpty()){
            int pos = queue.poll();
            for(int n = 0; n < N; n++){
                if(graph[pos][n] > 0 && passed[n] == false){
                    queue.add(n);
                    passed[n] = true;
                    count++;
                }
            }
        }

        return count;
    }

    public static List<Integer> dijkstra(int n, int[][] graph, int start, int end){
        final int INF = Integer.MAX_VALUE;

        int[] distance = new int[n];  //最小距離を管理
        int[] prev = new int[n];      //最小距離となるときの直前ノード

        // 初期化
        Arrays.fill(distance, INF);
        Arrays.fill(prev, INF);
        distance[start] = 0;
        prev[start] = start;
        Queue<Integer> nodesQueue = new PriorityQueue<Integer>();
        nodesQueue.add(start);

        // 計算
        while(!nodesQueue.isEmpty()){
            int node = nodesQueue.poll();

            for(int i = 0; i < n; i++){
                int moveCost = graph[node][i];
                if (moveCost > 0 && distance[i] > distance[node] + moveCost) {
                    distance[i] = distance[node] + moveCost;
                    prev[i] = node;
                    if(i != end){ nodesQueue.add(i);}
                }
            }
            //System.out.println(node+","+Arrays.toString(prev)+","+Arrays.toString(distance));
        }

        List<Integer> route = new ArrayList<Integer>();

        int pos = end;
        route.add(pos);
        while(pos != start){
            pos = prev[pos];
            route.add(pos);
        }

        return route;
    }
}

import java.lang.reflect.Array;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main
{
    private static boolean solve(boolean player, Boolean[] vertices, Map<Integer, List<Integer>> nodes)
    {
        boolean put = false;
        for (int i = 0; i < vertices.length; i++) {
            Boolean v = vertices[i];
            if (v == null) {
                continue;
            }

            if ((player && v) || (!player && !v)) {
                List<Integer> dstList = nodes.get(i);
                if (dstList == null) {
                    continue;
                }
                for (int dst : dstList) {
                    if (vertices[dst] == null) {
                        Boolean[] newVertices = Arrays.copyOf(vertices, vertices.length);
                        newVertices[dst] = player;
                        if (!solve(!player, newVertices, nodes)) {
                            put = true;
                        }
                    }
                }
            }
        }
        return put;
    }

    public static void main(String[] args)
    {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        Map<Integer, List<Integer>> nodes = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();

            nodes.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
            nodes.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
        }
        Boolean[] vertices = new Boolean[n + 1];
        vertices[1] = true;
        vertices[n] = false;
        if (solve(true, vertices, nodes)) {
            System.out.println("Fennec");
        }
        else {
            System.out.println("Snuke");
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    int n;
    ArrayList<ArrayList<Edge>> es;
    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    void read() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        es = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            es.add(new ArrayList<>());
        }
        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            es.get(a).add(new Edge(a, b));
            es.get(b).add(new Edge(b, a));
        }
    }

    void solve() {
        int sScore = 0, fScore = 0;
        int[] fScores = getDists(0);
        int[] sScores = getDists(n-1);

        for (int i = 0; i < n; i++) {
            if (fScores[i] >= sScores[i])
                fScore++;
            else
                sScore++;
        }

        if (fScore > sScore)
            System.out.println("Fennec");
        else
            System.out.println("Snuke");
    }

    ArrayList<Integer> getPath() {
        int[] log = new int[n];
        int[] prev = new int[n];
        Arrays.fill(log, Integer.MAX_VALUE);
        PriorityQueue<Node> queue =
                new PriorityQueue<>((n1, n2) -> Integer.compare(n2.rank, n1.rank));
        log[0] = 0;
        Arrays.fill(prev, -1);
        prev[0] = 0;
        for (Edge e: es.get(0)) {
            queue.add(new Node(e.to, 1));
            prev[e.to] = 0;
        }
        while (!queue.isEmpty()) {
            Node n = queue.poll();
            if (n.rank > log[n.id])
                continue;
            log[n.id] = n.rank;
            for (Edge e: es.get(n.id)) {
                if (log[e.to] > log[n.id] + 1) {
                    prev[e.to] = n.id;
                    queue.add(new Node(e.to, log[n.id] + 1));
                }
            }
        }
        ArrayList<Integer> path = new ArrayList<>(n-1);
        int current = n - 1;
        while (current != 0) {
            path.add(0, current);
            current = prev[current];
        }
        path.add(0, 0);
        return path;
    }

    int[] getDists(int start) {
        int[] log = new int[n];
        Arrays.fill(log, Integer.MAX_VALUE);
        PriorityQueue<Node> queue =
                new PriorityQueue<>((n1, n2) -> Integer.compare(n2.rank, n1.rank));
        log[start] = 0;
        for (Edge e: es.get(start)) {
            queue.add(new Node(e.to, 1));
        }
        while (!queue.isEmpty()) {
            Node n = queue.poll();
            if (n.rank > log[n.id])
                continue;
            log[n.id] = n.rank;
            for (Edge e: es.get(n.id)) {
                if (log[e.to] > log[n.id] + 1) {
                    queue.add(new Node(e.to, log[n.id] + 1));
                }
            }
        }
        return log;
    }

    private class Edge {
        int from, to;
        Edge(int f, int t) {
            from = f;
            to = t;
        }
    }

    private class Node {
        int id;
        int rank;
        Node(int id, int rank) {
            this.id = id;
            this.rank = rank;
        }
    }

    private class UnionFind {
        int[] parent;
        UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int getRoot(int x) {
            if (x == parent[x])
                return x;
            return parent[x] = getRoot(parent[x]);
        }

        boolean hasSamePar(int x, int y) {
            return getRoot(x) == getRoot(y);
        }

        void unite(int x, int y) {
            int px = getRoot(x);
            int py = getRoot(y);
            if (px == py)
                return;
            parent[py] = px;
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.List;

public class Main {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        new Main().calc();    
    }

    List<List<Integer>> treeList;
    boolean[] done;
    int[] distN, dist1;


    public void calc() {
        int N = in.nextInt();
        int[] a = new int[N-1], b = new int[N-1];

        for (int i = 0; i < N-1; i++) {
            a[i] = in.nextInt() - 1;
            b[i] = in.nextInt() - 1;
        }

        treeList = new ArrayList<List<Integer>>();
        for (int i = 0; i < N; i++) {
            treeList.add(new ArrayList<Integer>());
        }

        for (int i = 0; i < N-1; i++) {
            treeList.get(a[i]).add(b[i]);
            treeList.get(b[i]).add(a[i]);
        }


        done = new boolean[N];
        dist1 = new int[N];
        distN = new int[N];

        dfs(0, 0, dist1);
        Arrays.fill(done, false);
        dfs(N-1, 0, distN);

        int fennec = 0, snuke = 0;;

        for(int i = 0; i < N; i++) {
            if (dist1[i] <= distN[i]) {
                fennec++;
            }
            else {
                snuke++;
            }
        }

        String ans = "Fennec";

        if (snuke >= fennec) {
            ans = "Snuke";
        }


        out.println(ans);
        out.close();
    }

    void dfs(int to, int len, int[] dist) {
        if (done[to]) {
            return;
        }
        done[to] = true;
        dist[to] += len;
        treeList.get(to).forEach(next -> dfs(next, len+1, dist));             
    }

    class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++)
                array[i] = nextInt();

            return array;
        }

        int[][] nextIntMap(int n, int m) {
            int[][] map = new int[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextIntArray(m);
            }
            return map;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int n) {
            long[] array = new long[n];
            for (int i = 0; i < n; i++)
                array[i] = nextLong();

            return array;
        }

        long[][] nextLongMap(int n, int m) {
            long[][] map = new long[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextLongArray(m);
            }
            return map;
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        double[] nextDoubleArray(int n) {
            double[] array = new double[n];
            for (int i = 0; i < n; i++)
                array[i] = nextDouble();

            return array;
        }

        double[][] nextDoubleMap(int n, int m) {
            double[][] map = new double[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextDoubleArray(m);
            }
            return map;
        }

        String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        String[] nextStringArray(int n) {
            String[] array = new String[n];
            for (int i = 0; i < n; i++)
                array[i] = next();

            return array;
        }

        String nextLine() {
            int c = read();
            while (isEndline(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private void solve(Scanner sc) {
        int N = sc.nextInt();

        List<List<Path>> list = new ArrayList<>();
        for (int i = 0; i < N; ++i) {
            list.add(new ArrayList<>());
        }

        for (int i = 1; i <= N - 1; ++i) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            list.get(a).add(new Path(a, b, 1));
            list.get(b).add(new Path(b, a, 1));
        }

        long[] dist = dist(N, list);
        long ct1 = 0;
        long ct2 = 0;
        for (int i = 1; i < N - 1; ++i) {
            if (dist[i] < dist[N - 1]) {
                ++ct1;
            }
            if (dist[i] > dist[N - 1]) {
                ++ct2;
            }
        }
//_err.println(Arrays.toString(dist));
//_err.println(ct1 + " / " + ct2);

        if (ct1 >= ct2) {
            _out.println("Fennec");
        } else {
            _out.println("Snuke");
        }
    }
    private long[] dist(int N, List<List<Path>> edges) {
        long[] dist = new long[N];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[0] = 0;
        Queue<Path> q = new PriorityQueue<>();
        for (int i = 0; i < edges.size(); ++i) {
            for (Path edge : edges.get(i)) {
                q.offer(edge);
            }
        }

        while (!q.isEmpty()) {
            Path edge = q.poll();
            int u = edge.to;
            for (Path p : edges.get(u)) {
                long tmp = dist[u] + p.cost;
                if (dist[p.to] > tmp) {
                    dist[p.to] = tmp;
                    Path newPath = new Path(0, p.to, tmp);
                    q.offer(newPath);
                }
            }
        }

        return dist;
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    private static class Path implements Comparable<Path> {
        int from;
        int to;
        long cost;
        public Path(int from, int to, long cost) {
            this.from = from;
            this.to = to;
            this.cost = cost;
        }
        @Override
        public int compareTo(Path that) {
            if (that.cost > this.cost) {
                return -1;
            } else if (that.cost < this.cost) {
                return 1;
            }
            if (that.from != this.from) {
                return this.from - that.from;
            }
            if (that.to != this.to) {
                return this.to - that.to;
            }
            return 0;
        }
        @Override
        public String toString() {
            return "[" + from + ", " + to + ", " + cost + "]";
        }
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
