/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author silviase
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DFennecVSSnuke solver = new DFennecVSSnuke();
        solver.solve(1, in, out);
        out.close();
    }

    static class DFennecVSSnuke {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            Graph g = new Graph(n);
            for (int i = 0; i < n - 1; i++) {
                g.addUnDirectedEdge(in.nextInt() - 1, in.nextInt() - 1, 1);
            }
            long[] d1 = g.dijkstra(0);
            long[] dn = g.dijkstra(n - 1);
            int cntF = 0;
            int cntS = 0;

            for (int i = 0; i < n; i++) {
                if (d1[i] <= dn[i]) {
                    cntF++;
                } else {
                    cntS++;
                }
            }
            if (cntS >= cntF) {
                out.println("Snuke");
            } else {
                out.println("Fennec");
            }
        }

    }

    static class Edge {
        public int from;
        public int to;
        public long cost;

        public Edge(int to) {
            this.to = to;
        }

        public Edge(int to, long cost) {
            this.to = to;
            this.cost = cost;
        }

        public Edge(int from, int to, long cost) {
            this.from = from;
            this.to = to;
            this.cost = cost;
        }

        public String toString() {
            return "Edge{" +
                    "from=" + from +
                    ", to=" + to +
                    ", cost=" + cost +
                    '}';
        }

    }

    static class Graph {
        public int size;
        public ArrayList<Edge>[] adj;
        public int[] inDeg;
        public int[] vertexCost;

        public Graph(int size) {
            this.size = size;
            adj = new ArrayList[size];
            inDeg = new int[size];
            vertexCost = new int[size];
            for (int i = 0; i < size; i++) {
                adj[i] = new ArrayList<>();
            }
        }

        public void addEdge(int from, int to, long cost) {
            addEdge(new Edge(from, to, cost));
        }

        public void addUnDirectedEdge(int from, int to, long cost) {
            addEdge(from, to, cost);
            addEdge(to, from, cost);
        }

        public void addEdge(Edge e) {
            adj[e.from].add(e);
            inDeg[e.to]++;
        }

        public long[] dijkstra(int from) {
            long[] d = new long[size];
            PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.comparing(e -> d[e]));
            for (int i = 0; i < size; i++) {
                d[i] = (i == from) ? 0 : (long) 1e18;
                pq.add(i);
            }
            // System.out.println(Arrays.toString(pq.toArray()));
            while (!pq.isEmpty()) {
                int search = pq.poll();
                // System.out.println("now: " + search);
                ArrayList<Edge> edges = adj[search];
                for (Edge e : edges) {
                    // System.out.println(e.toString());
                    long cmp = d[search] + e.cost;
                    if (d[e.to] > d[search] + e.cost) {
                        // 更新が入る
                        // 処理を入れたい場合はここに入れる
                        d[e.to] = d[search] + e.cost;
                        pq.add(e.to);
                    }
                }
                //  System.out.println(Arrays.toString(pq.toArray()));
            }
            return d;
        }

    }
}

import java.util.*;
public class Main {
    private static int n;
    private static int mid;
    private static Map<Integer, List<Integer>> graph = new HashMap<>();
    private static Map<Integer, Integer> sz = new HashMap<>();
    private static List<Integer> path = new ArrayList<>();

    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            graph = new HashMap<>();
            sz = new HashMap<>();
            path = new ArrayList<>();

            n = sc.nextInt();
            for (int i=1; i<n; i++) {
                int u = sc.nextInt();
                int v = sc.nextInt();

                graph.computeIfAbsent(u, ArrayList::new).add(v);
                graph.computeIfAbsent(v, ArrayList::new).add(u);
            }

            dfs(1, -1);

            int sum1 = n - sz.get(mid);
            if (sum1 > sz.get(mid)) {
                System.out.println("Fennec");
            } else {
                System.out.println("Snuke");
            }
        }
    }

    private static void dfs(int x, int parent) {
        path.add(x);
        sz.put(x, 1);

        for(int e: graph.computeIfAbsent(x, ArrayList::new)) {
            if (e == parent) {
                continue;
            }
            dfs(e, x);
            sz.put(x, sz.get(x) + sz.get(e));
        }

        if (x == n) {
            mid = path.get((path.size() + 1) / 2);
        }

        path.remove(path.size()-1);
    }
}

import java.util.*;

public class Main {

	public static void main (String[] args)  {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		ArrayList<Path>[] graph = new ArrayList[n + 1];
		for (int i = 1; i <= n; i++) {
			graph[i] = new ArrayList<Path>();
		}
		for (int i = 0; i < n - 1; i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			graph[a].add(new Path(a, b));
			graph[b].add(new Path(b, a));
		}
		int[] arr = new int[n + 1];
		ArrayDeque<Path> deq = new ArrayDeque<>();
		deq.add(new Path(0, 1));
		while (deq.size() > 0) {
			Path p = deq.poll();
			if (arr[p.to] != 0) {
				continue;
			}
			arr[p.to] = arr[p.from] + 1;
			deq.addAll(graph[p.to]);
		}
		int min = (arr[n] + 1) / 2 + 1;
		deq.add(new Path(n, n));
		int count = 0;
		while (deq.size() > 0) {
			Path p = deq.poll();
			if (arr[p.to] < min) {
				continue;
			}
			arr[p.to] = 0;
			count++;
			deq.addAll(graph[p.to]);
		}
		if (count > n / 2) {
			System.out.println("Snuke");
		} else {
			System.out.println("Fennec");
		}
	}

	static class Path {
		int from;
		int to;
		public Path(int from, int to) {
			this.from = from;
			this.to = to;
		}
	}
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

public class Main {
	static int n;
	static int[][] m = new int[10000][10000];
	static int max = Integer.MAX_VALUE;

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		n = scan.nextInt();

		// ノード同士の関係を記録
		for (int i = 0; i < n - 1; i++) {
			int a = scan.nextInt() - 1;
			int b = scan.nextInt() - 1;
			m[a][b] = 1;
			m[b][a] = 1;

		}
		int[] f = bfs(0);
		int[] s = bfs(n - 1);
		int ansF = 0;
		int ansS = 0;
		int flag = 1;
		for (int i = 0; i < n; i++) {
			if (f[i] < s[i]) {
				ansF++;

			} else if (f[i] > s[i]) {
				ansS++;

			} else {
				if (flag % 2 == 1) {
					ansF++;
					flag++;
				} else {
					ansS++;
					flag++;
				}
			}
		}
		if (ansF > ansS) {
			System.out.println("Fennec");
		} else {
			System.out.println("Snuke");
		}

	}

	public static int[] bfs(int u) {
		int[] ans = new int[10000];
		Deque<Integer> q = new ArrayDeque<Integer>();
		q.offer(u);
		Arrays.fill(ans, max);
		ans[u] = 0;

		while (!q.isEmpty()) {
			// 調べるノードを取り出す
			int v = q.poll();
			for (int i = 0; i < n; i++) {
				if (m[v][i] == 0) {
					continue;
				}
				if (ans[i] != max) {
					continue;
				}
				ans[i] = ans[v] + 1;
				q.offer(i);
			}
		}
		return ans;

	}

}

