        // -----------------------------------------

        // Integer のキーに対して、カウントを管理する（カウントを足したり、引いたりする）
        static class MapCounter {
        	private Map<Integer, Integer> map = new HashMap<Integer, Integer>();
        	public MapCounter() {}
        	// キーのカウントに値を足す
        	public void add(int key) {
