import java.util.*;

public class Main {
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		ArrayList<ArrayList<Integer>> graph = new ArrayList<>();
		for (int i = 0; i < n; i++) {
		    graph.add(new ArrayList<>());
		}
		for (int i = 0; i < n - 1; i++) {
		    int a = sc.nextInt() - 1;
		    int b = sc.nextInt() - 1;
		    graph.get(a).add(b);
		    graph.get(b).add(a);
		}
		PriorityQueue<Path> queue = new PriorityQueue<>();
		int[] costs = new int[n];
		Arrays.fill(costs, Integer.MAX_VALUE);
		queue.add(new Path(0, 0));
		while (queue.size() > 0) {
		    Path p = queue.poll();
		    if (costs[p.idx] <= p.value) {
		        continue;
		    }
		    costs[p.idx] = p.value;
		    for (int x : graph.get(p.idx)) {
		        if (costs[x] == Integer.MAX_VALUE) {
		            queue.add(new Path(x, p.value + 1));
		        }
		    }
		}
		int[] routes = new int[n];
		int idx = n - 1;
		int value = costs[n - 1];
		while (value >= 0) {
		    routes[idx] = value + 1;
		    for (int x : graph.get(idx)) {
		        if (costs[x] == value - 1) {
		            idx = x;
		            break;
		        }
		    }
		    value--;
		}
		int max = (routes[n - 1] + 1) / 2;
		value = 0;
		ArrayDeque<Path> deq = new ArrayDeque<>();
		deq.add(new Path(0, Integer.MIN_VALUE));
		while (deq.size() > 0) {
		    Path p = deq.poll();
		    if (routes[p.idx] <= n && routes[p.idx] > value) {
		        value = routes[p.idx];
		    } else if (routes[p.idx] != 0) {
		        continue;
		    } else {
		        routes[p.idx] = p.value;
		    }
		    int next;
		    if (routes[p.idx] <= max) {
		        next = Integer.MIN_VALUE;
		    } else {
		        next = Integer.MAX_VALUE;
		    }
		    for (int x : graph.get(p.idx)) {
		        deq.add(new Path(x, next));
		    }
		}
		int fCount = 0;
		int sCount = 0;
		for (int x : routes) {
		    if (x <= max) {
		        fCount++;
		    } else {
		        sCount++;
		    }
		}
		if (fCount > sCount) {
		    System.out.println("Fennec");
		} else {
		    System.out.println("Snuke");
		}
   }

   static class Path implements Comparable<Path> {
       int idx;
       int value;

       public Path(int idx, int value) {
           this.idx = idx;
           this.value = value;
       }

       public int compareTo(Path another) {
           return value - another.value;
       }
   }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

    private static FastReader in = new FastReader(System.in);
    private static PrintWriter out = new PrintWriter(System.out);

    private static final long MOD = (long) 1e9 + 7;

    public static void main(String[] args) {
        solve();
        out.flush();
    }

    private static class Node {
        private List<Integer> children;
        private int parent;

        private Node() {
            this.parent = -1;
            this.children = new ArrayList<>();
        }

        private void addChild(int child) {
            this.children.add(child);
        }
    }

    private static void solve() {
        int n = in.nextInt();
        Node[] nodes = new Node[n];
        for (int i = 0; i < n; i++) {
            nodes[i] = new Node();
        }

        for (int i = 0; i < n - 1; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            nodes[a].addChild(b);
            nodes[b].addChild(a);
        }

        // construct tree with node 0 as the root (fill "parent" field)
        treeDfs(nodes, -1, 0);

        // snuke's depth
        int depth = findDepth(nodes, n - 1);
        int raceCounts = depth - 1;
        int snukeRoot = findNDepthIndex(nodes, n - 1, raceCounts / 2);

        int snukeCount = count(nodes, snukeRoot);

        out.println((n - snukeCount) > snukeCount ? "Fennec" : "Snuke");
    }

    // Tree dfs, expected no loop in the graph
    // First call: treeDfs(nodes, -1, root); (root is the root index)
    private static void treeDfs(Node[] nodes, int parent, int current) {
        for (int child : nodes[current].children) {
            if (child != parent) {
                nodes[child].parent = current;
                treeDfs(nodes, current, child);
            }
        }
    }

    private static int findDepth(Node[] nodes, int index) {
        if (nodes[index].parent == -1) {
            return 0;
        }

        return findDepth(nodes, nodes[index].parent) + 1;
    }

    // go up the tree n-times
    private static int findNDepthIndex(Node[] nodes, int index, int n) {
        if (n == 0) {
            return index;
        }

        return findNDepthIndex(nodes, nodes[index].parent, n - 1);
    }

    // finds number of nodes below this index (including the index)
    private static int count(Node[] nodes, int index) {
        int count = 1;
        for (int child : nodes[index].children) {
            if (child == nodes[index].parent) {
                continue;
            }
            count += count(nodes, child);
        }
        return count;
    }

    // https://www.geeksforgeeks.org/fast-io-in-java-in-competitive-programming/
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader(InputStream inputStream) {
            br = new BufferedReader(new
                    InputStreamReader(inputStream));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException  e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
