	}

	public void dfs(int parent, long dist, long d[]) {
		used[parent]=true;
		d[parent]=dist;
		for(int i=0; i<g.get(parent).size(); i++) {
			int t = g.get(parent).get(i);
			if(used[t]) continue;
			dfs(t, dist+1, d);
		}
	}

