public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        DFennecVSSnuke solver = new DFennecVSSnuke();
        solver.solve(1, in, out);
        out.close();
    }

    static class DFennecVSSnuke {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int n = in.ints();
            DFennecVSSnuke.Node[] nodes = new DFennecVSSnuke.Node[n];
            for (int i = 0; i < n; i++) nodes[i] = new DFennecVSSnuke.Node();
            for (int i = 1; i < n; i++) {
                int x = in.ints() - 1, y = in.ints() - 1;
                nodes[x].adj.add(nodes[y]);
                nodes[y].adj.add(nodes[x]);
            }
            nodes[0].dfs(null);
            DFennecVSSnuke.Node now = nodes[n - 1];
            while (now.parent != null && now.parent.depth > nodes[n - 1].depth / 2) {
                now = now.parent;
            }
            out.ans(n >= now.size * 2 ? "Fennec" : "Snuke").ln();
        }

        private static class Node {
            List<DFennecVSSnuke.Node> adj = new ArrayList<>();
            int depth;
            int size = 1;
            DFennecVSSnuke.Node parent;

            void dfs(DFennecVSSnuke.Node from) {
                if (from != null) {
                    depth = from.depth + 1;
                    parent = from;
                }
                for (DFennecVSSnuke.Node child : adj) {
                    if (from == child) continue;
                    child.dfs(this);
                    size += child.size;
                }
            }

        }

    }

