	public static int dfs(int node) {
		int numC = 1;
		for (int child: tree[node]) {
			if (depth[child] == -1) {
				depth[child] = depth[node]+1;
				parent[child] = node;
				numC += dfs(child);
			}
		}
		children[node] = numC;
		return numC;
	}


