        nodes = new Node[n];
        for (int i = 0; i < n; i++) {
            nodes[i] = new Node(i);
        }
    }

    // 双方向pathの追加
    public void addPath(int v, int u) {
        this.nodes[u].addPath(nodes[v]);
        this.nodes[v].addPath(nodes[u]);
    }

    // pathの削除
    public void removePath(int u, int v) {
        this.nodes[u].removePath(nodes[v]);
        this.nodes[v].removePath(nodes[u]);
    }

    /**
     * @param v : node
     * @return count of this group7s node
     */
    public int countGroup(int v) {
        int cnt = 0;
        boolean[] visited = new boolean[n];
        ArrayDeque<Integer> stack = new ArrayDeque<Integer>();
        stack.push(v);
        cnt++;
        visited[v] = true;
        while (!stack.isEmpty()) {
            int pos = stack.poll();
            for (Node node : nodes[pos].edges) {
                if (!visited[node.id]) {
                    visited[node.id] = true;
                    cnt++;
                    stack.push(node.id);
                }
            }
        }
        return cnt;
    }

    public ArrayList<Integer> serchPath(int from, int to) {
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        boolean[] visited = new boolean[n];
        stack.push(from);
        visited[from] = true;
        S: while (!stack.isEmpty()) {
            int currentPosition = stack.peekFirst();
            if (currentPosition == to) {
                break S;
            }
            for (Node n : nodes[currentPosition].edges) {
                if (!visited[n.id]) {
                    stack.push(n.id);
                    visited[n.id] = true;
                    continue S;
                }
            }
            stack.pollFirst();
        }
        ArrayList<Integer> path = new ArrayList<>(stack);
        Collections.reverse(path);
        return path;
    }

    class Node {
        int id;

        ArrayList<Node> edges;

        Node(int id) {
            this.id = id;
            this.edges = new ArrayList<>();
        }

        void addPath(Node next) {
            this.edges.add(next);
        }

        void removePath(Node other) {
            this.edges.remove(other);
        }
    }
}

import java.util.*;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<Integer, Set<Integer>> graph = new HashMap<>(n);
        for (int i = 1; i <= n; i++) {
            graph.put(i, new HashSet<>());
        }

        for (int r = 0; r < n - 1; r++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            graph.get(a).add(b);
            graph.get(b).add(a);
        }

        boolean[] claimedCache = new boolean[n + 1];
        Deque<List<Integer>> queue = new Deque<>();
        queue.addLast(Arrays.asList(1, 1));
        claimedCache[1] = true;
        queue.addLast(Arrays.asList(n, -1));
        claimedCache[n] = true;
        int fennecCount = 1;
        int snukeCount = 1;

        while (!queue.isEmpty()) {
            List<Integer> data = queue.removeFirst();
            int nodeId = data.get(0);
            int colorId = data.get(1);
            for (Integer neighbor : graph.get(nodeId)) {
                if (!claimedCache[neighbor]) {
                    claimedCache[neighbor] = true;
                    if (colorId == 1) {
                        fennecCount++;
                    }
                    else {
                        snukeCount++;
                    }
                    queue.addLast(Arrays.asList(neighbor, colorId));
                }
            }
        }

        System.out.println((fennecCount > snukeCount) ? "Fennec" : "Snuke");
    }
}

