public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private static class Node {
        int no;
        int color;
        public Node(int no) {
            this.no = no;
        }
        public String toString() {
            return "(" + no + ":" + color + ")";
        }
    }
    private void solve(Scanner sc) {
        int N = sc.nextInt();

        Map<Integer, Node> nodes = new HashMap<>();
        List<List<Node>> list = new ArrayList<>();
        for (int i = 0; i < N; ++i) {
            list.add(new ArrayList<>());

            nodes.put(i, new Node(i));
        }
        nodes.get(0).color = -1;
        nodes.get(N - 1).color = 1;

        for (int i = 1; i <= N - 1; ++i) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            list.get(a).add(nodes.get(b));
            list.get(b).add(nodes.get(a));
        }
        Deque<Node> q = new ArrayDeque<>();
        q.offer(nodes.get(0));
        q.offer(nodes.get(N - 1));
        int black = 0;
        int white = 0;
        Set<Integer> visited = new HashSet<>();
        while (!q.isEmpty()) {
            Node node = q.poll();
            if (visited.contains(node.no)) {
                continue;
            }
            visited.add(node.no);
            List<Node> l = list.get(node.no);
            for (Node n : l) {
                if (n.color == 0) {
                    n.color = node.color;
                    q.offer(n);
                }
            }
        }

        int color = 0;
        for (Node node : nodes.values()) {
            color += node.color;
        }

        if (color <= 0) {
            _out.println("Fennec");
        } else {
            _out.println("Snuke");
        }
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.StringTokenizer;
import java.util.TreeSet;

public class Main {

	public static void main(String args[]) {
		ConsoleScanner cin = new ConsoleScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	private static void solve(ConsoleScanner cin, PrintWriter cout) {

		// timeout?
		// int[][] arr = new int[100000 - 1][2];
		// for (int i = 0; i < arr.length; i++) {
		// arr[i][0] = i + 1;
		// arr[i][1] = i + 2;
		// }
		// System.out.println(solve(100000, arr));

		int n = cin.nextInt();
		int[][] abs = new int[n - 1][];
		for (int i = 0; i < abs.length; i++)
			abs[i] = new int[] { cin.nextInt(), cin.nextInt() };

		String ans = solve(n, abs);
		cout.println(ans);
	}

	private static String solve(int n, int[][] abs) {
		TreeSet<int[]> tmap = new TreeSet<>(Comparator.comparingLong((ab) -> (long) ab[0] * Integer.MAX_VALUE + ab[1]));
		for (int[] ab : abs) {
			tmap.add(ab);
			tmap.add(new int[] { ab[1], ab[0] });
		}

		// 1 to n, shortest path
		// ダイクストラ法
		int sp = -1;
		PriorityQueue<int[]> q = new PriorityQueue<>(Comparator.comparingInt((dhp) -> dhp[0]));
		Integer[] preced = new Integer[n + 1];
		q.add(new int[] { 0, 1, -1 });
		while (!q.isEmpty()) {
			int[] arr = q.poll();
			int dist = arr[0];
			int here = arr[1];
			int pre = arr[2];
			if (preced[here] != null)
				continue;
			preced[here] = pre;
			if (here == n) {
				sp = dist;
				break;
			}
			for (int[] edge : tmap.subSet(new int[] { here, 0 }, new int[] { here + 1, 0 })) {
				int to = edge[1];
				if (preced[to] != null)
					continue;
				q.add(new int[] { dist + 1, to, here });
			}
		}
		q.clear();

		ArrayDeque<int[]> stk = new ArrayDeque<>();
		Integer[] paint = new Integer[n + 1];
		final int FENNEC = 1;
		final int SNUKE = 0;
		for (int i = 1, p = preced[n]; i < sp; i++) {
			if (i < sp / 2)
				paint[p] = SNUKE;
			else
				paint[p] = FENNEC;
			stk.add(new int[] { p, paint[p] });
			p = preced[p];
		}
		paint[1] = FENNEC;
		paint[n] = SNUKE;
		stk.add(new int[] { 1, paint[1] });
		stk.add(new int[] { n, paint[n] });

		while (!stk.isEmpty()) {
			int[] arr = stk.pollFirst();
			int here = arr[0];
			int color = arr[1];
			for (int[] edge : tmap.subSet(new int[] { here, 0 }, new int[] { here + 1, 0 })) {
				int to = edge[1];
				if (paint[to] != null)
					continue;
				paint[to] = color;
				stk.add(new int[] { to, color });
			}
		}

		long fennec = Arrays.stream(paint).filter(p -> p != null && p == FENNEC).count();
		long sunuke = Arrays.stream(paint).filter(p -> p != null && p == SNUKE).count();
		if (fennec > sunuke)
			return "Fennec";
		return "Snuke";
	}

	static class ConsoleScanner {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer("");

		String next() {
			try {
				while (!st.hasMoreElements())
					st = new StringTokenizer(br.readLine());
				return st.nextToken();
			} catch (IOException e) {
				throw new AssertionError(e);
			}
		}

		int nextInt() {
			return Integer.parseInt(next());
		}
	}

}

