import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    private static int N;
    private static int[] A;
    private static int[] B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        N = sc.nextInt();
        A = new int[N];
        B = new int[N];
        for (int i = 0; i < N-1; i++) {
            A[i] = sc.nextInt();
            B[i] = sc.nextInt();
        }
        System.out.println(solve());
    }

    private static String solve() {
        Rin r = mkRin();
        Path path = findPath(r);

        List<Integer> nodes = path.nodes;

        boolean fene = true;
        while(nodes.size() > 2) {
            if( fene ) {
                nodes.remove(0);
                fene = false;
            } else {
                nodes.remove(nodes.size() - 1);
                fene = true;
            }
        }

        int cut1 = nodes.get(0);
        int cut2 = nodes.get(1);

        UnionFind uf = new UnionFind(N);
        for (int i = 0; i < N-1; i++) {
            int a = A[i];
            int b = B[i];

            if( cut1 == a && cut2 == b || cut1 == b && cut2 == a ) {
                continue;
            }

            uf.unite(a-1, b-1);
        }

        int fRoot = uf.root(0);
        int f = 0;
        for (int i = 0; i < N; i++) {
            if( uf.root(i) == fRoot ) {
                f++;
            }
        }

        int s = N - f;

        if( f > s ) {
            return "Fennec";
        } else {
            return "Snuke";
        }
    }

    private static Path findPath(Rin r) {
        boolean[] used = new boolean[N];
        List<Path> current = Collections.singletonList(Path.single(1));
        while(true) {
            List<Path> next = new ArrayList<>();
            for (Path path : current) {
                for (Integer n : r.get(path.last())) {
                    if( n == N ) {
                        return path.add(n);
                    } else if( !used[n] ){
                        next.add(path.add(n));
                        used[n] = true;
                    }
                }
            }
            current = next;
        }
    }

    private static Rin mkRin() {
        Rin r = new Rin(N);
        for (int i = 0; i < N-1; i++) {
            r.set(A[i], B[i]);
        }
        return r;
    }

    // 隣接リスト
    private static class Rin {

        private final List[] array;

        public Rin(int n) {
            array = new List[n];
        }

        public void set(int a, int b) {
            get(a).add(b);
            get(b).add(a);
        }

        public List<Integer> get(int n) {
            if( array[n - 1] == null ) {
                array[n - 1] = new ArrayList();
            }
            //noinspection unchecked
            return (List<Integer>)array[n - 1];
        }
    }

    public static class Path {

        public static Path single(int n) {
            return new Path(Collections.singletonList(n));
        }

        private final List<Integer> nodes;

        public Path(List<Integer> nodes) {
            this.nodes = nodes;
        }

        public Path add(int n) {
            List<Integer> list = new ArrayList<>(nodes.size() + 1);
            list.addAll(nodes);
            list.add(n);
            return new Path(list);
        }

        public int last() {
            return nodes.get(nodes.size() - 1);
        }
    }

    static class UnionFind {

        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int root(int n) {
            if( parent[n] == n ) {
                return n;
            } else {
                parent[n] = root(parent[n]);
                return parent[n];
            }
        }

        void unite(int x, int y) {
            x = root(x);
            y = root(y);
            if( x == y ) return;

            if( rank[x] < rank[y] ) {
                parent[x] = y;
            } else {
                parent[y] = x;
                if( rank[x] == rank[y]) rank[x]++;
            }
        }
    }

    static class FastScanner {

        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        public String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

public class Main {
	static ArrayList<Integer>[] lists;
	static int n;
	static int[] colors;
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		lists = new ArrayList[n + 1];
		for (int i = 1; i <= n; i++) {
			lists[i] = new ArrayList<Integer>();
		}
		for (int i = 0; i < n - 1; i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			lists[a].add(b);
			lists[b].add(a);
		}
		// 最短経路の探索
		ArrayList<Integer> route = new ArrayList<>();
		search(route, 1);

		int x = route.size() / 2 + (route.size() % 2);
		colors = new int[n + 1];
		for (int i = 0; i < route.size(); i++) {
			if (i < x) {
				colors[route.get(i)] = 1;
			} else {
				colors[route.get(i)] = 2;
			}
		}

		// 色塗り
		for (int c : route) {
			paint(c, colors[c]);
		}

		int Fennec = 0;
		int Snuke = 0;
		for (int i = 1; i <= n; i++) {
			if (colors[i] == 1) {
				Fennec++;
			} else {
				Snuke++;
			}
		}

		if (Fennec > Snuke) {
			System.out.println("Fennec");
		} else {
			System.out.println("Snuke");
		}
	}

	static void paint(int idx, int color) {
		for (int x : lists[idx]) {
			if (colors[x] == 0) {
				colors[x] = color;
				paint(x, color);
			}
		}
	}

	static boolean search(ArrayList<Integer> list, int a) {
		list.add(a);
		if (a == n) {
			return true;
		}
		for (Integer x : lists[a]) {
			if (list.contains(x)) {
				return false;
			}
			boolean ret = search(list, x);
			if (ret) {
				return true;
			} else {
				list.remove(x);
			}
		}
		return false;
	}
}

import java.io.*;
import java.util.*;

class Solver {
  private static final int FENNEC = 1;
  private static final int SNUKE = 2;

  final int n;
  final int[] as, bs;
  List<List<Integer>> graph;
  int[] colors;
  boolean[] visited;

  Solver(int n, int[] as, int[] bs) {
    this.n = n;
    this.as = as;
    this.bs = bs;
  }

  private int dfs(int prev, int index, int length) {
    if (index == n) {
      return length;
    }

    for (int next : graph.get(index)) {
      if (next == prev) {
        continue;
      }
      int goalLength = dfs(index, next, length + 1);
      if (goalLength > 0) {
        if (length <= (goalLength + 1) / 2) {
          colors[index] = FENNEC;
        } else {
          colors[index] = SNUKE;
        }
        return goalLength;
      }
    }
    return 0;
  }

  private int visit(int index, int color) {
    if (colors[index] != color && colors[index] != 0) {
      return 0;
    }
    if (visited[index]) {
      return 0;
    }
    visited[index] = true;

    int sum = 1;
    for (int next : graph.get(index)) {
      sum += visit(next, color);
    }
    return sum;
  }

  public String solve() {
    graph = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }

    for (int i = 0; i < n-1; i++) {
      graph.get(as[i]).add(bs[i]);
      graph.get(bs[i]).add(as[i]);
    }

    colors = new int[n + 1];
    colors[1] = FENNEC;
    colors[n] = SNUKE;

    dfs(-1, 1, 1);

    visited = new boolean[n + 1];
    int count1 = visit(1, FENNEC);
    int count2 = visit(n, SNUKE);
//    System.err.printf("%d %d\n", count1, count2);
    if (count1 > count2) {
      return "Fennec";
    } else {
      return "Snuke";
    }
  }
}

