import java.util.HashMap;
import java.util.InputMismatchException;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Main {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        new Main().calc();    
    }

    public void calc() {
        int N = in.nextInt();
        int[] a = new int[N-1], b = new int[N-1];

        for (int i = 0; i < N-1; i++) {
            a[i] = in.nextInt() - 1;
            b[i] = in.nextInt() - 1;
        }

        int[][] dist = new int[N][N];

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                dist[i][j] = 99999999;
            }
            dist[i][i] = 0;  
        }        
        for (int i = 0; i < N-1; i++) {
            // 道のある町間での距離を入れる
            // 町と町の間に複数の道がある場合があるため，一番短い距離の道のみ考慮する
            dist[a[i]][b[i]] = 1;
            dist[b[i]][a[i]] = 1;
        }              
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }

        int fennec = 0, snuke = 0;;

        for(int i = 0; i < N; i++) {
            if (dist[0][i] <= dist[N-1][i]) {
                fennec++;
            }
            else {
                snuke++;
            }
        }

        String ans = "Fennec";

        if (snuke >= fennec) {
            ans = "Snuke";
        }


        out.println(ans);
        out.close();
    }

    class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++)
                array[i] = nextInt();

            return array;
        }

        int[][] nextIntMap(int n, int m) {
            int[][] map = new int[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextIntArray(m);
            }
            return map;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int n) {
            long[] array = new long[n];
            for (int i = 0; i < n; i++)
                array[i] = nextLong();

            return array;
        }

        long[][] nextLongMap(int n, int m) {
            long[][] map = new long[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextLongArray(m);
            }
            return map;
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        double[] nextDoubleArray(int n) {
            double[] array = new double[n];
            for (int i = 0; i < n; i++)
                array[i] = nextDouble();

            return array;
        }

        double[][] nextDoubleMap(int n, int m) {
            double[][] map = new double[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextDoubleArray(m);
            }
            return map;
        }

        String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        String[] nextStringArray(int n) {
            String[] array = new String[n];
            for (int i = 0; i < n; i++)
                array[i] = next();

            return array;
        }

        String nextLine() {
            int c = read();
            while (isEndline(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Set;

public class Main {
	public static void main(String args[]) {
		FastScanner scanner = new FastScanner();
		int n=scanner.nextInt();
		int[] a=new int[n-1];
		int[] b=new int[n-1];
		Map<Integer,Set<Integer>>map=new HashMap<>();
		for(int i=0;i<n-1;i++){
			a[i]=scanner.nextInt()-1;
			b[i]=scanner.nextInt()-1;
			if (map.containsKey(a[i])) {
				Set<Integer>set=new HashSet<>(map.get(a[i]));
				set.add(b[i]);
				map.put(a[i], set);
			} else {
				Set<Integer>set=new HashSet<>();
				set.add(b[i]);
				map.put(a[i], set);
			}
			if (map.containsKey(b[i])) {
				Set<Integer>set=new HashSet<>(map.get(b[i]));
				set.add(a[i]);
				map.put(b[i], set);
			} else {
				Set<Integer>set=new HashSet<>();
				set.add(a[i]);
				map.put(b[i], set);
			}
		}
		Deque<Integer>que=new ArrayDeque<>();
		que.add(0);
		Set<Integer>checked=new HashSet<>();
		int[] memo=new int[n];
		while(!que.isEmpty()){
			int tar=que.poll();
			checked.add(tar);
			for(int i:map.get(tar)){
				if(!checked.contains(i)){
					que.add(i);
					memo[i]=tar;
				}
			}
		}
		List<Integer>center=new ArrayList<>();
		int pre=memo[n-1];
		center.add(n-1);
		while(true){
			center.add(pre);
			if(pre==0){
				break;
			}
			pre=memo[pre];
		}
		Deque<Integer>queS=new ArrayDeque<>();
		for(int i=0;i<Math.ceil(center.size()/2.0);i++){
			queS.add(center.get(i));
		}
		int cntS=0;
		checked=new HashSet<>();
		while(!queS.isEmpty()){
			int tar=queS.poll();
			checked.add(tar);
			for(int i:map.get(tar)){
				if(!center.contains(i)&&!checked.contains(i)){
					queS.add(i);
				}
			}
			cntS++;
		}
		int cntF=n-cntS;
		System.out.println(cntS<cntF?"Fennec":"Snuke");
	}
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main
{
    private static boolean solve(boolean player, Boolean[] vertices, Map<Integer, List<Integer>> nodes)
    {
        boolean put = false;
        for (int i = 0; i < vertices.length; i++) {
            Boolean v = vertices[i];
            if (v == null) {
                continue;
            }

            if ((player && v) || (!player && !v)) {
                List<Integer> dstList = nodes.get(i);
                if (dstList == null) {
                    continue;
                }
                for (int dst : dstList) {
                    if (vertices[dst] == null) {
                        Boolean[] newVertices = Arrays.copyOf(vertices, vertices.length);
                        newVertices[dst] = player;
                        if (!solve(!player, newVertices, nodes)) {
                            put = true;
                        }
                    }
                }
            }
        }
        return put;
    }

    private static ArrayList<Integer> shortestRoute(int cur, int goal, ArrayList<Integer> route, Map<Integer, List<Integer>> nodes)
    {
        if (cur == goal) {
            return route;
        }

        for (int next : nodes.get(cur)) {
            if (!route.contains(next)) {
                ArrayList<Integer> newRoute = new ArrayList<>(route);
                newRoute.add(next);
                ArrayList<Integer> result = shortestRoute(next, goal, newRoute, nodes);
                if (result != null) {
                    return result;
                }
            }
        }

        return null;
    }

    private static void prevail(boolean[] vertices, int cur, List<Integer> shortestRoute, Map<Integer, List<Integer>> nodes) {
        vertices[cur] = true;
        for (int next : nodes.get(cur)) {
            if (!vertices[next] && !shortestRoute.contains(next)) {
                prevail(vertices, next, shortestRoute, nodes);
            }
        }
    }

    private static int dfs(boolean[] vertices, int cur, Map<Integer, List<Integer>> nodes, int[] cut)
    {
        int moves = 0;
        for (int next : nodes.get(cur)) {
            if (cur == cut[0] && next == cut[1]
            || cur == cut[1] && next == cut[0]) {
                continue;
            }
            if (!vertices[next]) {
                vertices[next] = true;
                moves++;
                moves += dfs(vertices, next, nodes, cut);
            }
        }
        return moves;
    }

    public static void main(String[] args)
    {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        Map<Integer, List<Integer>> nodes = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();

            nodes.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
            nodes.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
        }

        ArrayList<Integer> shortestRoute;
        {
            ArrayList<Integer> list = new ArrayList<>();
            list.add(1);
            shortestRoute = shortestRoute(1, n, list, nodes);
        }

        int conflictPos = (int) Math.ceil(shortestRoute.size() / 2.0);
        int[] cut = new int[] { shortestRoute.get(conflictPos - 1), shortestRoute.get(conflictPos)};

        boolean[] vertices = new boolean[n + 1];
        /*
        for (int i = 0; i < Math.ceil(shortestRoute.size() / 2.0); i++) {
            prevail(vertices, shortestRoute.get(0), shortestRoute, nodes);
        }

        int fennecCells = 0;
        for (boolean b : vertices) {
            if (b) {
                fennecCells++;
            }
        }
         */

        int fennecCells = dfs(vertices, 1, nodes, cut);

        if (fennecCells > (n - fennecCells)) {
            System.out.println("Fennec");
        }
        else {
            System.out.println("Snuke");
        }
    }
}

