    static int[] bfs(ArrayList<Integer>[] nodes){
        ArrayDeque<Integer> q=new ArrayDeque<>();
        q.add(0);
        int n=nodes.length;
        int[] d=new int[n];
        int[] prev=new int[n];
        for(int i=0;i<n;i++) d[i]=-1;
        d[0]=0;
        while(q.size()!=0){
            int u=q.removeFirst();
            for(int v:nodes[u]){
