/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author David Wu
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        private HashMap<Integer, Vertex> tree = new HashMap<>();
        private int n;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.readInt();
            for (int i = 1; i <= n; i++) {
                tree.put(i, new Vertex(i));
            }
            for (int i = 0; i < n - 1; i++) {
                int a = in.readInt(), b = in.readInt();
                if (tree.containsKey(a) && tree.containsKey(b)) {
                    tree.get(a).addNeighbour(b);
                    tree.get(b).addNeighbour(a);
                }
            }
            tree.get(1).color = 'B';
            tree.get(n).color = 'W';
            while (true) {
                if (player1() == -1) {
                    out.printLine("Snuke");
                    return;
                }
                if (player2() == -1) {
                    out.printLine("Fennec");
                    return;
                }
            }

        }

        int player1() {
            int maxFreeNeighboursID = Integer.MIN_VALUE;
            int maxFreeNeighbours = 0;
            int t = 0;
            int p = 0;
            for (int i = 1; i <= n; i++) {
                int temp = 0;
                if (tree.get(i).color == 'B') {
                    for (int k : tree.get(i).getNeighbours()) {
                        if (tree.get(k).color == ' ') {
                            t = k;
                            p++;
                            for (int j : tree.get(k).getNeighbours()) {
                                if (tree.get(j).color == ' ') {
                                    temp++;
                                }
                            }
                            if (temp > maxFreeNeighbours) {
                                maxFreeNeighbours = temp;
                                maxFreeNeighboursID = k;
                            }
                        }
                    }
                }
            }
            if (maxFreeNeighbours == 0) {
                if (p == 0) {
                    return -1;
                } else {
                    tree.get(t).color = 'B';
                }
            } else {
                tree.get(maxFreeNeighboursID).color = 'B';
            }
            return 0;
        }

        int player2() {
            int maxFreeNeighboursID = Integer.MIN_VALUE;
            int maxFreeNeighbours = 0;
            int t = 0;
            int p = 0;
            for (int i = 1; i <= n; i++) {
                int temp = 0;
                if (tree.get(i).color == 'W') {
                    for (int k : tree.get(i).getNeighbours()) {
                        if (tree.get(k).color == ' ') {
                            t = k;
                            p++;
                            for (int j : tree.get(k).getNeighbours()) {
                                if (tree.get(j).color == ' ') {
                                    temp++;
                                }
                            }
                            if (temp > maxFreeNeighbours) {
                                maxFreeNeighbours = temp;
                                maxFreeNeighboursID = k;
                            }
                        }
                    }
                }
            }
            if (maxFreeNeighbours == 0) {
                if (p == 0) {
                    return -1;
                } else {
                    tree.get(t).color = 'W';
                }
            } else {
                tree.get(maxFreeNeighboursID).color = 'W';
            }
            return 0;
        }

        class Vertex {
            int id;
            char color = ' ';
            public ArrayList<Integer> Neighbours = new ArrayList<>();

            public Vertex(int id) {
                this.id = id;
            }

            public void addNeighbour(Integer id) {
                Neighbours.add(id);
            }

            public ArrayList<Integer> getNeighbours() {
                return Neighbours;
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }
}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private void solve(Scanner sc) {
        int N = sc.nextInt();

        List<List<Path>> list = new ArrayList<>();
        for (int i = 0; i < N; ++i) {
            list.add(new ArrayList<>());
        }

        for (int i = 1; i <= N - 1; ++i) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            list.get(a).add(new Path(a, b, 1));
            list.get(b).add(new Path(b, a, 1));
        }

        long[] dist = dist(N, list);

        if (dist[N - 1] % 2 == 0) {
            _out.println("Fennec");
        } else {
            _out.println("Snuke");
        }
    }
    private long[] dist(int N, List<List<Path>> edges) {
        long[] dist = new long[N];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[0] = 0;
        Queue<Path> q = new PriorityQueue<>();
        for (int i = 0; i < edges.size(); ++i) {
            for (Path edge : edges.get(i)) {
                q.offer(edge);
            }
        }

        while (!q.isEmpty()) {
            Path edge = q.poll();
            int u = edge.to;
            for (Path p : edges.get(u)) {
                long tmp = dist[u] + p.cost;
                if (dist[p.to] > tmp) {
                    dist[p.to] = tmp;
                    Path newPath = new Path(0, p.to, tmp);
                    q.offer(newPath);
                }
            }
        }

        return dist;
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    private static class Path implements Comparable<Path> {
        int from;
        int to;
        long cost;
        public Path(int from, int to, long cost) {
            this.from = from;
            this.to = to;
            this.cost = cost;
        }
        @Override
        public int compareTo(Path that) {
            if (that.cost > this.cost) {
                return -1;
            } else if (that.cost < this.cost) {
                return 1;
            }
            if (that.from != this.from) {
                return this.from - that.from;
            }
            if (that.to != this.to) {
                return this.to - that.to;
            }
            return 0;
        }
        @Override
        public String toString() {
            return "[" + from + ", " + to + ", " + cost + "]";
        }
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
