		for(int i=0;i<=n;i++){
			way.add(new LinkedList<Integer>());
		}
		for(int i=1;i<n;i++){
			in.nextToken();
			int a=(int)in.nval;
			in.nextToken();
			int b=(int)in.nval;
			way.get(a).add(b);
			way.get(b).add(a);
