					if(point[edge]==0){
						point[edge]=-1;
						q2.add(edge);
						temp22++;
						ans2++;
					}
				}
			}
			temp2=temp22;
		}
		if(ans1>ans2)out.println("Fennec");
		else out.println("Snuke");
		out.flush();
	}
}

