class Graph {
	int n;
	boolean directed;
	ArrayList<Edge>[] adjList;
	int m;
	long[] dist;
	long[][] distWF;
	int start;
	int[] prev;
	ArrayList<Integer> path;
	long INF = 1001001001001001001L;

	public Graph (int n, boolean directed) {
		this.n = n;
		this.m = 0;
		this.directed = directed;
		this.adjList = new ArrayList[n];
		for(int i = 0; i < n; i++){
			adjList[i] = new ArrayList<Edge>();
		}
	}

	public void add(int from, int to) {
		add(from, to, 1);
	}
	public void add(int from, int to, int w) {
		adjList[from].add(new Edge(from, to, w));
		this.m++;
		if(!directed){
			adjList[to].add(new Edge(to, from, w));
			this.m++;
		}
	}

	public long[] bfs(int start) { // O(M)
		this.start = start;
		this.prev = new int[n];
		Arrays.fill(prev, -1);
		prev[start] = start;
		this.dist = new long[n];
		Arrays.fill(dist, INF);
		dist[start] = 0;
		ArrayDeque<Integer> q = new ArrayDeque<Integer>();
		q.add(start);
		while(!q.isEmpty()){
			int now = q.poll();
			if(now == n-1) continue;
			for(Edge e : adjList[now]){
				if(dist[e.to] != INF) continue;
				dist[e.to] = dist[now] + e.w;
				prev[e.to] = now;
				q.add(e.to);
			}
		}
		return dist;
	}

	public long[] dijkstra(int start) { // O(MlogM)
		this.start = start;
		this.prev = new int[n];
		Arrays.fill(prev, -1);
		prev[start] = start;
		this.dist = new long[n];
		Arrays.fill(dist, INF);
		dist[start] = 0;
		PriorityQueue<Vertex> q = new PriorityQueue<Vertex>((x, y) -> Long.compare(x.distance, y.distance));
		q.add(new Vertex(start, 0));
		while(!q.isEmpty()){
			Vertex now = q.poll();
			if(now.distance > dist[now.id]) continue; 
			for(Edge e : adjList[now.id]){
				long newDist = now.distance + e.w;
				if(dist[e.to] <= newDist) continue;
				dist[e.to] = newDist;
				prev[e.to] = now.id;
				q.add(new Vertex(e.to, newDist));
			}
		}
		return dist;
	}

	public long[][] wf() { // O(N^3)
		this.distWF = new long[n][n];
		for(int i = 0; i < n; i++){
			Arrays.fill(distWF[i], INF);
			distWF[i][i] = 0;
		}
		for(ArrayList<Edge> list : adjList){
			for(Edge e : list){
				distWF[e.from][e.to] = e.w;
			}
		}
		for(int k = 0; k < n; k++){
			for(int i = 0; i < n; i++){
				for(int j = 0; j < n; j++){
					distWF[i][j] = min(distWF[i][j], distWF[i][k] + distWF[k][j]);
				}
			}
		}
		return distWF;
	}

	public boolean bf(int start) { // O(NM)
		this.start = start;
		this.prev = new int[n];
		Arrays.fill(prev, -1);
		prev[start] = start;
		this.dist = new long[n];
		Arrays.fill(dist, INF);
		dist[start] = 0;
		boolean hasNegativeLoop = false;
		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				for(Edge e : adjList[j]){
					if(dist[e.to] <= dist[e.from] + e.w) continue;
					dist[e.to] = dist[e.from] + e.w;
					prev[e.to] = e.from;
					if(i == n-1) hasNegativeLoop = true;
				}
			}
		}
		return hasNegativeLoop;
	}

	public ArrayList<Integer> pathTo(int to){
		this.path = new ArrayList<Integer>();
		return pathToRec(to);
	}

	private ArrayList<Integer> pathToRec(int to){
		if(to != start) pathToRec(prev[to]);
		path.add(to);
		return path;
	}

	public String toString(){
		StringBuilder sb = new StringBuilder();
		for(ArrayList<Edge> list : adjList){
			for(Edge e : list){
				sb.append(e.toString());
				sb.append("\n");
			}
		}
		return sb.toString();
	}

	public String distToString(){
		if(dist != null) return Arrays.toString(dist);
		StringBuilder sb = new StringBuilder();
		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				if(distWF[i][j] == INF){
					sb.append("from:" + i + " to:" + j + " dist:INF" + "\n");
				}else{
					sb.append("from:" + i + " to:" + j + " dist:" + distWF[i][j] + "\n");
				}
			}
		}
		return sb.toString();
	}

	class Edge {
		int from;
		int to;
		int w;

		Edge(int from, int to, int w){
			this.from = from;
			this.to = to;
			this.w = w;
		}

		public String toString(){
			return "from:" + from + " to:" + to + " w:" + w;
		}
	}

	class Vertex {
		int id;
		long distance;

		Vertex(int id, long distance){
			this.id = id;
			this.distance = distance;
		}

		public String toString(){
			return "id:" + id + " distance:" + distance;
		}
	}
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		new Main().solve();
	}

	int N;
	int[]a;
	int[]b;

	void solve(){
		Scanner sc=new Scanner(System.in);
		N=sc.nextInt();
		a=new int[N-1];
		b=new int[N-1];
		ArrayList<Integer>[] path=new ArrayList[N];
		int []dist_1=new int[N];
		int []dist_N=new int[N];
		boolean[] visited=new boolean[N];
		dist_1[0]=0;
		dist_N[N-1]=0;
		for(int i=0;i<N;i++){
			path[i]=new ArrayList<Integer>();
		}
		for(int i=0;i<N-1;i++){
			a[i]=sc.nextInt()-1;
			b[i]=sc.nextInt()-1;
			path[a[i]].add(b[i]);
			path[b[i]].add(a[i]);
		}

		Queue<Integer> nowq=new LinkedList<Integer>();

		nowq.add(0);
		int count=0;
		boolean flag=true;

		while(flag){
			flag=false;
			Queue<Integer> nextq=new LinkedList<Integer>();
			while(!nowq.isEmpty()){
				int now=nowq.poll();
				visited[now]=true;
				dist_1[now]=count;

				for(int i=0;i<path[now].size();i++){
					int to=path[now].get(i);
					if(!visited[to]){
						nextq.add(to);
						flag=true;
					}
				}
			}

			nowq=nextq;
			count++;
		}

		nowq.add(N-1);
		count=0;
		flag=true;
		Arrays.fill(visited, false);
		while(flag){
			flag=false;
			Queue<Integer> nextq=new LinkedList<Integer>();
			while(!nowq.isEmpty()){
				int now=nowq.poll();
				visited[now]=true;
				dist_N[now]=count;

				for(int i=0;i<path[now].size();i++){
					int to=path[now].get(i);
					if(!visited[to]){
						nextq.add(to);
						flag=true;
					}
				}
			}

			nowq=nextq;
			count++;
		}

		int snukeCount=0;
		int fennecCount=0;
		for(int i=0;i<N;i++){
			if(dist_1[i]<=dist_N[i])fennecCount++;
			else snukeCount++;
		}

		if(fennecCount>snukeCount)System.out.println("Fennec");
		else System.out.println("Snuke");

	}
}

