/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author anand.oza
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DFennecVSSnuke solver = new DFennecVSSnuke();
        solver.solve(1, in, out);
        out.close();
    }

    static class DFennecVSSnuke {
        int n;
        List<Integer>[] adj;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            final int fennec = 0;
            final int snuke = n - 1;

            adj = new List[n];
            for (int i = 0; i < n; i++) {
                adj[i] = new ArrayList<>();
            }

            for (int i = 0; i < n - 1; i++) {
                int a = in.nextInt() - 1, b = in.nextInt() - 1;
                adj[a].add(b);
                adj[b].add(a);
            }

            int[] distanceFromFennec = distance(fennec);
            int[] distanceFromSnuke = distance(snuke);

            int claimedByFennec = 0;
            int claimedBySnuke = 0;

            for (int i = 0; i < n; i++) {
                if (distanceFromFennec[i] <= distanceFromSnuke[i]) {
                    claimedByFennec++;
                } else {
                    claimedBySnuke++;
                }
            }

            if (claimedByFennec <= claimedBySnuke) {
                out.println("Snuke");
            } else {
                out.println("Fennec");
            }
        }

        private int[] distance(int start) {
            int[] distance = new int[n];
            Arrays.fill(distance, -1);

            distance[start] = 0;
            Queue<Integer> q = new ArrayDeque<>();
            q.add(start);
            while (!q.isEmpty()) {
                int cur = q.poll();
                for (int next : adj[cur]) {
                    if (distance[next] >= 0) {
                        continue;
                    }
                    distance[next] = distance[cur] + 1;
                    q.add(next);
                }
            }

            return distance;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

