class Main {

    static PrintWriter out;
    static InputReader sc;

    static final int MOD = (int) 1e9 + 7;

    static List<List<Integer>> graph;
    static int[] memo;

    public static void main(String[] args) {
        sc = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    static void solve() {
        int N = sc.nextInt();
        graph = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            graph.add(new ArrayList<Integer>());
        }
        for (int i = 0; i < N - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            graph.get(a).add(b);
            graph.get(b).add(a);
        }
        memo = new int[N];
        Arrays.fill(memo, -1);
        size(0, -1);
        int s = memo[N - 1];
        Arrays.fill(memo, -1);
        size(N - 1, -1);
        int f = memo[0];
        int p = N - s - f;
        f += (p + 1) / 2;
        s += p / 2;
        out.println(f >= s ? "Fennec" : "Snuke");
    }

    static int size(int s, int p) {
        int res = 1;
        for (int v : graph.get(s)) {
            if (v != p) {
                res += size(v, s);
            }
        }
        return memo[s] = res;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
