public class Main {

	public static void main(String[] args) {
		new Main().solve();
	}

	int N;
	int[]a;
	int[]b;

	void solve(){
		Scanner sc=new Scanner(System.in);
		N=sc.nextInt();
		a=new int[N-1];
		b=new int[N-1];
		ArrayList<Integer>[] path=new ArrayList[N];
		int []dist_1=new int[N];
		int []dist_N=new int[N];
		boolean[] visited=new boolean[N];
		dist_1[0]=0;
		dist_N[N-1]=0;
		for(int i=0;i<N;i++){
			path[i]=new ArrayList<Integer>();
		}
		for(int i=0;i<N-1;i++){
			a[i]=sc.nextInt()-1;
			b[i]=sc.nextInt()-1;
			path[a[i]].add(b[i]);
			path[b[i]].add(b[i]);
		}

		Queue<Integer> nowq=new LinkedList<Integer>();
		Queue<Integer> nextq=new LinkedList<Integer>();

		nowq.add(0);
		int count=0;

		while(count==0 || !nextq.isEmpty()){
			while(!nowq.isEmpty()){
				int now=nowq.poll();
				visited[now]=true;
				dist_1[now]=count;

				for(int i=0;i<path[now].size();i++){
					if(!visited[path[now].get(i)]) nextq.add(path[now].get(i));
				}
			}
			nowq=nextq;
			nextq=nowq;
			count++;
		}

		nowq.add(N-1);
		count=0;
		Arrays.fill(visited, false);
		while(count==0 || !nextq.isEmpty()){
			while(!nowq.isEmpty()){
				int now=nowq.poll();
				visited[now]=true;
				dist_N[now]=count;

				for(int i=0;i<path[now].size();i++){
					if(!visited[path[now].get(i)]) nextq.add(path[now].get(i));
				}
			}
			nowq=nextq;
			nextq=nowq;
			count++;
		}

		int snukeCount=0;
		int fennecCount=0;
		for(int i=0;i<N;i++){
			if(dist_1[i]<=dist_N[i])fennecCount++;
			else snukeCount++;
		}

		if(fennecCount>snukeCount)System.out.println("Fennec");
		else System.out.println("Snuke");

	}
}

import java.util.*;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int N = scan.nextInt();
        Map<Integer, Set<Integer>> tree = new HashMap<>();
        for (int i : IntStream.range(0, N - 1).toArray()) {
            int a = scan.nextInt();
            int b = scan.nextInt();
            Set<Integer> map = tree.getOrDefault(a, new HashSet<>());
            map.add(b);
            tree.put(a, map);
            map = tree.getOrDefault(b, new HashSet<>());
            map.add(a);
            tree.put(b, map);
        }

        List<Integer> path = dijkstra(tree, N);
        List<Integer> black = new ArrayList<>();
        int blackNum = path.size() / 2 + path.size() % 2;
        for (int i = 0; i < blackNum; i++) {
            black.add(path.get(i));
        }
        int forbidden = path.get(blackNum);
        int blackCount = count(tree, forbidden);
        if (path.size() % 2 == 0) {
            if (N < blackCount * 2) {
                System.out.println("Fennec");
            } else {
                System.out.println("Snuke");
            }
        } else {
            if (N < blackCount * 2 + 1) {
                System.out.println("Fennec");
            } else {
                System.out.println("Snuke");
            }
        }
    }

    static List<Integer> dijkstra(Map<Integer, Set<Integer>> tree, int N) {
        LinkedList<List<Integer>> stack = new LinkedList<>();
        stack.add(Collections.singletonList(1));
        List<List<Integer>> ret = new ArrayList<>();
        for (int i : IntStream.range(0, N).toArray()) {
            List<Integer> current = stack.removeFirst();
            int node = current.get(current.size() - 1);
            int previous = current.size() >= 2 ? current.get(current.size() - 2) : -1;
            for (int next : tree.get(node)) {
                if (next == previous) {
                    continue;
                }
                if (next == N) {
                    List<Integer> tmp = new ArrayList<>(current);
                    tmp.add(next);
                    ret.add(tmp);
                }
                List<Integer> tmp = new ArrayList<>(current);
                tmp.add(next);
                stack.add(tmp);
            }
            if (!ret.isEmpty()) {
                return ret.get(0);
            }
        }
        return null;
    }

    static int count(Map<Integer, Set<Integer>> tree, int forbidden) {
        Set<Integer> ret = new HashSet<>();
        LinkedList<Integer> stack = new LinkedList<>();
        stack.add(1);
        while (!stack.isEmpty()) {
            int next = stack.removeFirst();
            ret.add(next);
            for (Integer tmp : tree.get(next)) {
                if (tmp == forbidden) {
                    continue;
                }
                if(ret.contains(tmp)) {
                    continue;
                }
                stack.add(tmp);
            }
        }
        return ret.size();
    }
}

import java.util.*;
import java.util.stream.Collectors;
import java.io.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;

public class Main {

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		Main ins = new Main(in);
		ins.calc();
		ins.showResult();
	}

	static class Node {
		int id;
		Set<Integer> conns;

		Node(int id) {
			this.id = id;
			this.conns = new HashSet<>();
		}
	}

	int N;
	Node[] nodes;

	Main(BufferedReader in) throws IOException {
		N = Integer.parseInt(in.readLine());
		nodes = new Node[N];
		for (int i = 0; i < N; ++i) {
			nodes[i] = new Node(i);
		}
		for (int i = 0; i < N - 1; ++i) {
			String[] tokens = in.readLine().split(" ");
			int a = Integer.parseInt(tokens[0]) - 1;
			int b = Integer.parseInt(tokens[1]) - 1;
			nodes[a].conns.add(b);
			nodes[b].conns.add(a);
		}
	}

	List<Integer> getPath(int current, int parent) {
		if (current == N - 1) {
			List<Integer> path = new ArrayList<>();
			path.add(current);
			return path;
		} else {
			List<Integer> remain = null;
			for (Integer i : nodes[current].conns) {
				if (i != parent) {
					List<Integer> l = getPath(i, current);
					if (l != null) {
						remain = l;
						break;
					}
				}
			}
			if (remain != null) {
				remain.add(current);
			}
			return remain;
		}
	}

	int count(int current, int parent) {
		int c = 1;
		for (Integer i : nodes[current].conns) {
			if (i != parent) {
				c += count(i, current);
			}
		}
		return c;
	}

	void calc() {
		// まずpathを求める
		List<Integer> path = getPath(0, -1);
		Collections.reverse(path);
		int middle = (path.size() - 1) / 2;
		// 分割する
		int blackEdge = path.get(middle);
		int whiteEdge = path.get(middle + 1);
		nodes[blackEdge].conns.remove(whiteEdge);
		nodes[whiteEdge].conns.remove(blackEdge);

		int blackNum = count(0, -1);
		int whiteNum = count(N - 1, -1);
		if (blackNum <= whiteNum) {
			System.out.println("Snuke");
		} else {
			System.out.println("Fennec");
		}
	}

