import java.util.*;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int N = scan.nextInt();
        Map<Integer, Set<Integer>> tree = new HashMap<>();
        for (int i : IntStream.range(0, N - 1).toArray()) {
            int a = Integer.parseInt(scan.next());
            int b = Integer.parseInt(scan.next());
            Set<Integer> map = tree.getOrDefault(a, new HashSet<>());
            map.add(b);
            tree.put(a, map);
            map = tree.getOrDefault(b, new HashSet<>());
            map.add(a);
            tree.put(b, map);
        }

        List<Integer> path = dijkstra(tree, N);
        List<Integer> black = new ArrayList<>();
        int blackNum = path.size() / 2 + path.size() % 2;
        for (int i = 0; i < blackNum; i++) {
            black.add(path.get(i));
        }
        int forbidden = path.get(blackNum);
        int blackCount = count(tree, forbidden, N);
        if (path.size() % 2 == 0) {
            if (N < blackCount * 2) {
                System.out.println("Fennec");
            } else {
                System.out.println("Snuke");
            }
        } else {
            if (N < blackCount * 2 + 1) {
                System.out.println("Fennec");
            } else {
                System.out.println("Snuke");
            }
        }
    }

    static List<Integer> dijkstra(Map<Integer, Set<Integer>> tree, int N) {
        LinkedList<List<Integer>> stack = new LinkedList<>();
        stack.add(Collections.singletonList(1));
        List<List<Integer>> ret = new ArrayList<>();
        for (int i : IntStream.range(0, N).toArray()) {
            List<Integer> current = stack.removeFirst();
            int node = current.get(current.size() - 1);
            int previous = current.size() >= 2 ? current.get(current.size() - 2) : -1;
            for (int next : tree.get(node)) {
                if (next == previous) {
                    continue;
                }
                if (next == N) {
                    List<Integer> tmp = new ArrayList<>(current);
                    tmp.add(next);
                    ret.add(tmp);
                }
                List<Integer> tmp = new ArrayList<>(current);
                tmp.add(next);
                stack.add(tmp);
            }
            if (!ret.isEmpty()) {
                return ret.get(0);
            }
        }
        return null;
    }

    static int count(Map<Integer, Set<Integer>> tree, int forbidden, int N) {
        N = N / 2 + 1;
        Set<Integer> ret = new HashSet<>(N);
        ArrayDeque<Integer> deque = new ArrayDeque<>();
        deque.add(1);
        while (!deque.isEmpty()) {
            int next = deque.removeFirst();
            ret.add(next);
            for (Integer tmp : tree.get(next)) {
                if (tmp == forbidden) {
                    continue;
                }
                if(ret.contains(tmp)) {
                    continue;
                }
                deque.add(tmp);
            }
            if(ret.size() > N) {
                return ret.size();
            }
        }
        return ret.size();
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    int n;
    ArrayList<ArrayList<Edge>> es;
    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    void read() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        es = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            es.add(new ArrayList<>());
        }
        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            es.get(a).add(new Edge(a, b));
            es.get(b).add(new Edge(b, a));
        }
    }

    void solve() {
        UnionFind uf = new UnionFind(n);
        int sScore = 0, fScore = 0;
        ArrayList<Integer> path = getPath();
        int mid = (path.size() - 1) / 2;
        int midFrom = path.get(mid);
        int midTo = path.get(mid+1);
        for (int i = 0; i < n; i++) {
            ArrayList<Edge> ess = es.get(i);
            for (int j = 0; j < ess.size(); j++) {
                if ((i == midFrom && ess.get(j).to == midTo) ||
                        (i == midTo && ess.get(j).to == midFrom))
                    continue;
                uf.unite(i, ess.get(j).to);
            }
        }
        for (int i = 0; i < n; i++) {
            if (uf.hasSamePar(0, i))
                fScore++;
            else
                sScore++;
        }
        if (fScore > sScore)
            System.out.println("Fennec");
        else
            System.out.println("Snuke");
    }

    ArrayList<Integer> getPath() {
        int[] log = new int[n];
        int[] prev = new int[n];
        Arrays.fill(log, Integer.MAX_VALUE);
        PriorityQueue<Node> queue =
                new PriorityQueue<>((n1, n2) -> Integer.compare(n2.rank, n1.rank));
        log[0] = 0;
        Arrays.fill(prev, -1);
        prev[0] = 0;
        for (Edge e: es.get(0)) {
            queue.add(new Node(e.to, 1));
            prev[e.to] = 0;
        }
        while (!queue.isEmpty()) {
            Node n = queue.poll();
            if (n.rank > log[n.id])
                continue;
            log[n.id] = n.rank;
            for (Edge e: es.get(n.id)) {
                if (log[e.to] > log[n.id] + 1) {
                    prev[e.to] = n.id;
                    queue.add(new Node(e.to, log[n.id] + 1));
                }
            }
        }
        ArrayList<Integer> path = new ArrayList<>(n-1);
        int current = n - 1;
        while (current != 0) {
            path.add(0, current);
            current = prev[current];
        }
        path.add(0, 0);
        return path;
    }

    private class Edge {
        int from, to;
        Edge(int f, int t) {
            from = f;
            to = t;
        }
    }

    private class Node {
        int id;
        int rank;
        Node(int id, int rank) {
            this.id = id;
            this.rank = rank;
        }
    }

    private class UnionFind {
        int[] parent;
        UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int getRoot(int x) {
            if (x == parent[x])
                return x;
            return parent[x] = getRoot(parent[x]);
        }

        boolean hasSamePar(int x, int y) {
            return getRoot(x) == getRoot(y);
        }

        void unite(int x, int y) {
            int px = getRoot(x);
            int py = getRoot(y);
            if (px == py)
                return;
            parent[x] = py;
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Scanner;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Graph g = new Graph(n);
        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            g.addPath(a, b);
        }
        ArrayList<Integer> ar = g.serchPath(0, n - 1);
        int len = ar.size();
        int Snuke = ar.get((len - 1) / 2);
        int Fennec = ar.get((len - 1) / 2 + 1);
        g.removePath(Snuke, Fennec);
        Snuke = g.countGroup(Snuke);
        Fennec = g.countGroup(Fennec);
        // len % 2 == 0 => Fenecスタート
        // len % 2 == 1 => Sunekeスタート
        if (len % 2 == 1) {
            Fennec++;
        }
