import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.List;

public class Main {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        new Main().calc();    
    }

    List<List<Integer>> treeList;
    boolean[] done;
    int[] distN, dist1;


    public void calc() {
        int N = in.nextInt();
        int[] a = new int[N-1], b = new int[N-1];

        treeList = new ArrayList<List<Integer>>();
        for (int i = 0; i < N; i++) {
            treeList.add(new ArrayList<Integer>());
        }

        for (int i = 0; i < N-1; i++) {
            a[i] = in.nextInt() - 1;
            b[i] = in.nextInt() - 1;
            treeList.get(a[i]).add(b[i]);
            treeList.get(b[i]).add(a[i]);
        }

        done = new boolean[N];
        dist1 = new int[N];
        distN = new int[N];

        dfs(0, 0, dist1);
        Arrays.fill(done, false);
        dfs(N-1, 0, distN);

        int fennec = 0, snuke = 0;;

        for(int i = 0; i < N; i++) {
            if (dist1[i] <= distN[i]) {
                fennec++;
            }
            else {
                snuke++;
            }
        }

        String ans = "Fennec";

        if (snuke >= fennec) {
            ans = "Snuke";
        }


        out.println(ans);
        out.close();
    }

    void dfs(int to, int len, int[] dist) {
        if (done[to]) {
            return;
        }
        done[to] = true;
        dist[to] += len;
        treeList.get(to).forEach(next -> dfs(next, len+1, dist));             
    }

    class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++)
                array[i] = nextInt();

            return array;
        }

        int[][] nextIntMap(int n, int m) {
            int[][] map = new int[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextIntArray(m);
            }
            return map;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int n) {
            long[] array = new long[n];
            for (int i = 0; i < n; i++)
                array[i] = nextLong();

            return array;
        }

        long[][] nextLongMap(int n, int m) {
            long[][] map = new long[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextLongArray(m);
            }
            return map;
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        double[] nextDoubleArray(int n) {
            double[] array = new double[n];
            for (int i = 0; i < n; i++)
                array[i] = nextDouble();

            return array;
        }

        double[][] nextDoubleMap(int n, int m) {
            double[][] map = new double[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextDoubleArray(m);
            }
            return map;
        }

        String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        String[] nextStringArray(int n) {
            String[] array = new String[n];
            for (int i = 0; i < n; i++)
                array[i] = next();

            return array;
        }

        String nextLine() {
            int c = read();
            while (isEndline(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.util.ArrayList;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    int n;
    ArrayList<ArrayList<Edge>> es;
    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    void read() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        es = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            es.add(new ArrayList<>());
        }
        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            es.get(a).add(new Edge(a, b));
            es.get(b).add(new Edge(b, a));
        }
    }

    void solve() {
        int player = 1;
        int[] used = new int[n];
        Node[] graph = new Node[n];
        PriorityQueue<Node> queueF =
                new PriorityQueue<>((n1, n2) -> Integer.compare(n2.rank, n1.rank));
        PriorityQueue<Node> queueS =
                new PriorityQueue<>((n1, n2) -> Integer.compare(n2.rank, n1.rank));
        for (int i = 0; i < n; i++) {
            graph[i] = new Node(i, es.get(i).size());
        }
        for (Edge e: es.get(0)) {
            graph[e.to].rank--;
            queueF.add(graph[e.to]);
        }
        for (Edge e: es.get(n-1)) {
            graph[e.to].rank--;
            queueS.add(graph[e.to]);
        }
        used[0] = 1;
        used[n-1] = -1;

        while (true) {
            Node next = null;
            if (player == 1) {
                if (!queueF.isEmpty()) {
                    next = queueF.poll();
                    if (next == null)
                        break;
                    if (used[next.id] != 0)
                        continue;
                }
                else {
                    break;
                }
            } else {
                if (!queueS.isEmpty()) {
                    next = queueF.poll();
                    if (next == null)
                        break;
                    if (used[next.id] != 0)
                        continue;
                }
                else{
                    break;
                }
            }
            used[next.id] = player;
            for (Edge e: es.get(next.id))
                graph[e.to].rank--;
            player *= -1;
        }

        if (player == -1)
            System.out.println("Fennec");
        else
            System.out.println("Snuke");
    }

    private class Edge {
        int from, to;
        Edge(int f, int t) {
            from = f;
            to = t;
        }
    }

    private class Node {
        int id;
        int rank;
        Node(int id, int rank) {
            this.id = id;
            this.rank = rank;
        }
    }
}

import java.util.*;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] g = buildGraph(sc, n, n-1);
        boolean[] used = new boolean[n];
        ArrayDeque<Integer> fq = new ArrayDeque<>();
        ArrayDeque<Integer> sq = new ArrayDeque<>();
        fq.add(0); sq.add(n-1);
        int fsum = 0; int ssum = 0;
        for (int i = 0; i < n; i++) {
            ArrayDeque<Integer> tq = new ArrayDeque<>();
            while(!fq.isEmpty()){
                int nex = fq.poll();
                if(!used[nex]){
                    fsum++; used[nex] = true;
                    for(int a : g[nex]){
                        tq.add(a);
                    }
                }
            }
            fq.addAll(tq);
            tq.clear();
            while(!sq.isEmpty()){
                int nex = sq.poll();
                if(!used[nex]){
                    ssum++; used[nex] = true;
                    for(int a : g[nex]){
                        tq.add(a);
                    }
                }
            }
            sq.addAll(tq);
        }
        System.out.println(fsum < ssum ? "Snuke" : "Fennec");
        sc.close();

    }

    public static int[][] buildGraph(Scanner sc, int n, int m) {
        int[][] graph = new int[n][];
        int[][] edges = new int[m][2];
        int[] deg = new int[n];
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            edges[i][0] = a;
            edges[i][1] = b;
            deg[a]++;
            deg[b]++;
        }
        for (int i = 0; i < n; i++) {
            graph[i] = new int[deg[i]];
        }
        for (int i = 0; i < m; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            graph[a][--deg[a]] = b;
            graph[b][--deg[b]] = a;
        }

        return graph;
    }

}

