	static class Edge implements Comparable<Edge>{
		int to;
		long v;
		public Edge(int to,long v) {
			this.to=to;
			this.v=v;
		}
		@Override
    	public boolean equals(Object obj) {
    		if(obj instanceof Edge) {
    			Edge other = (Edge) obj;
    			return other.to==this.to && other.v==this.v;
    		}
    		return false;
    	}//同値の定義
    	@Override
    	public int hashCode() {
    		return Objects.hash(this.to,this.v);
    	}
    	@Override
		  public int compareTo( Edge p2 ){
			 if (this.v>p2.v) {
				return 1;
			}
			 else if (this.v<p2.v) {
				return -1;
			}
			 else {
				return 0;
			}
		  }
	} 
	static class graph{
		ArrayList<Edge>[] list;
		int size;
		long INF=Long.MAX_VALUE/2;
		int[] color;
		@SuppressWarnings("unchecked")
		public graph(int n) {
			size = n;
			list = new ArrayList[n];
			color =new int[n];
			for(int i=0;i<n;i++){
				list[i] = new ArrayList<Edge>();
			}
		}
		void addEdge(int from,int to,long w) {
			list[from].add(new Edge(to,w));
		}
		long[] bfs(int s) {
			long[] l=new long[size];
			for (int i = 0; i < l.length; i++) {
				l[i]=-1;
			}
			l[s]=0;
			ArrayDeque<Integer> qArrayDeque=new ArrayDeque<Integer>();
			qArrayDeque.add(s);
			while (!qArrayDeque.isEmpty()) {
				int v=qArrayDeque.poll();
				for (Edge nv: list[v]) {
					if (l[nv.to]==-1) {
						l[nv.to]=l[v]+nv.v;
						qArrayDeque.add(nv.to);
					}
				}
			}
			return l;
		}
	}
		static class InputReader { 
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;
		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}
}

import java.util.*;
import java.io.*;


public class Main{

    public static Node[] nodes;
    public static ArrayList<Node> fennecCanColor, snukeCanColor;
    public static boolean[] colored;

    public static void main(String[] args) throws Exception{

        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        int n = Integer.parseInt(in.readLine());

        nodes = new Node[n+1];
        colored = new boolean[n+1];
        fennecCanColor = new ArrayList<Node>();
        snukeCanColor = new ArrayList<Node>();

        for(int i = 1; i <= n; i++){
            nodes[i] = new Node();
            nodes[i].num = i;
        }

        colored[1] = true;
        colored[n] = true;

        for(int i = 1; i < n; i++){
            String[] input = in.readLine().split("\\s+");
            int a = Integer.parseInt(input[0]);
            int b = Integer.parseInt(input[1]);

            nodes[a].adjList.add(nodes[b]);
            nodes[b].adjList.add(nodes[a]);

            nodes[a].canColorSize++;
            nodes[b].canColorSize++;

            if(a == 1 || a == n){
                nodes[b].canColorSize--;
            }

            if(b == 1 || b == n){
                nodes[a].canColorSize--;
            }

            if(a == 1 && b != n){
                fennecCanColor.add(nodes[b]);
            }
            else if(a == n && b != 1){
                snukeCanColor.add(nodes[b]);
            }

            if(b == 1 && a != n){
                fennecCanColor.add(nodes[a]);
            }
            else if(b == n && a != 1){
                snukeCanColor.add(nodes[a]);
            }
        }

        Collections.sort(fennecCanColor);
        Collections.sort(snukeCanColor);

        boolean fennec = true;;

        while(play(fennec)){
            fennec = !fennec;
        }

        if(fennec){
            out.println("Snuke");
        }
        else{
            out.println("Fennec");
        }

        in.close();
        out.close();
    }

    public static boolean play(boolean fennec){
        if(fennec){
            return playFennec();
        }
        return playSnuke();
    }

    public static boolean playFennec(){

        int size = fennecCanColor.size();

        if(size == 0){
            return false;
        }

        boolean canColor = false;

        for(int i = 0; i < size; i++){
            Node tmpNode = fennecCanColor.get(i);
            if(snukeCanColor.contains(tmpNode)){
                //System.out.println("Fennec colors: " + tmpNode.num);
                colored[tmpNode.num] = true;
                fennecCanColor.remove(i);
                snukeCanColor.remove(tmpNode);
                canColor = true;
                addAdjList(tmpNode.num, true);
                break;
            }
        }

        if(!canColor){
            Node tmpNode = fennecCanColor.get(0);
            //System.out.println("Fennec colors: " + fennecCanColor.get(0).num);
            colored[tmpNode.num] = true;
            canColor = true;
            addAdjList(fennecCanColor.get(0).num, true);
            fennecCanColor.remove(0);
        }

        return canColor;
    }

    public static boolean playSnuke(){

        int size = snukeCanColor.size();

        if(size == 0){
            return false;
        }

        boolean canColor = false;

        for(int i = 0; i < size; i++){
            Node tmpNode = snukeCanColor.get(i);
            if(fennecCanColor.contains(tmpNode)){
                //System.out.println("Snuke colors: " + tmpNode.num);
                colored[tmpNode.num] = true;
                snukeCanColor.remove(i);
                fennecCanColor.remove(tmpNode);
                canColor = true;
                addAdjList(tmpNode.num, false);
                break;
            }
        }

        if(!canColor){
            Node tmpNode = snukeCanColor.get(0);
            //System.out.println("Snuke colors: " + snukeCanColor.get(0).num);
            colored[tmpNode.num] = true;
            canColor = true;
            addAdjList(snukeCanColor.get(0).num, false);
            snukeCanColor.remove(0);
        }

        return canColor;
    }

    public static void addAdjList(int num, boolean fennec){
        if(fennec){
            for(Node node : nodes[num].adjList){
                node.canColorSize--;
                if(!colored[node.num]){
                    //System.out.println("\tFennec adds: " + node.num);
                    fennecCanColor.add(node);
                }
            }
        }
        else{
            for(Node node : nodes[num].adjList){
                if(!colored[node.num]){
                    //System.out.println("\tSnuke adds: " + node.num);
                    snukeCanColor.add(node);
                }
            }
        }

        Collections.sort(fennecCanColor);
        Collections.sort(snukeCanColor);
    }
}

