import java.util.*;

public class Main {

    private static int N;
    private static int[] A;
    private static int[] B;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        N = sc.nextInt();
        A = new int[N];
        B = new int[N];
        for (int i = 0; i < N-1; i++) {
            A[i] = sc.nextInt();
            B[i] = sc.nextInt();
        }
        System.out.println(solve());
    }

    private static String solve() {
        Rin r = mkRin();
        Path path = findPath(r);

        List<Integer> nodes = path.nodes;

        boolean fene = true;
        while(nodes.size() > 2) {
            if( fene ) {
                nodes.remove(0);
                fene = false;
            } else {
                nodes.remove(nodes.size() - 1);
                fene = true;
            }
        }

        int cut1 = nodes.get(0);
        int cut2 = nodes.get(1);

        UnionFind uf = new UnionFind(N);
        for (int i = 0; i < N-1; i++) {
            int a = A[i];
            int b = B[i];

            if( cut1 == a && cut2 == b || cut1 == b && cut2 == a ) {
                continue;
            }

            uf.unite(a-1, b-1);
        }

        int fRoot = uf.root(0);
        int f = 0;
        for (int i = 0; i < N; i++) {
            if( uf.root(i) == fRoot ) {
                f++;
            }
        }

        int s = N - f;

        if( f > s ) {
            return "Fennec";
        } else {
            return "Sunuke";
        }
    }

    private static Path findPath(Rin r) {
        List<Path> current = Collections.singletonList(Path.single(1));
        while(true) {
            List<Path> next = new ArrayList<>();
            for (Path path : current) {
                for (Integer n : r.get(path.last())) {
                    if( n == N ) {
                        return path.add(n);
                    } else if( !path.contains(n) ){
                        next.add(path.add(n));
                    }
                }
            }
            current = next;
        }
    }

    private static Rin mkRin() {
        Rin r = new Rin(N);
        for (int i = 0; i < N-1; i++) {
            r.set(A[i], B[i]);
        }
        return r;
    }

    // 隣接リスト
    private static class Rin {

        private final List[] array;

        public Rin(int n) {
            array = new List[n];
        }

        public void set(int a, int b) {
            get(a).add(b);
            get(b).add(a);
        }

        public List<Integer> get(int n) {
            if( array[n - 1] == null ) {
                array[n - 1] = new ArrayList();
            }
            //noinspection unchecked
            return (List<Integer>)array[n - 1];
        }
    }

    public static class Path {

        public static Path single(int n) {
            return new Path(Collections.singletonList(n));
        }

        private List<Integer> nodes;

        public Path(List<Integer> nodes) {
            this.nodes = nodes;
        }

        public boolean contains(int n) {
            return nodes.contains(n);
        }

        public Path add(int n) {
            List<Integer> list = new ArrayList<>(nodes.size() + 1);
            list.addAll(nodes);
            list.add(n);
            return new Path(list);
        }

        public int last() {
            return nodes.get(nodes.size() - 1);
        }
    }

    static class UnionFind {

        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int root(int n) {
            if( parent[n] == n ) {
                return n;
            } else {
                parent[n] = root(parent[n]);
                return parent[n];
            }
        }

        void unite(int x, int y) {
            x = root(x);
            y = root(y);
            if( x == y ) return;

            if( rank[x] < rank[y] ) {
                parent[x] = y;
            } else {
                parent[y] = x;
                if( rank[x] == rank[y]) rank[x]++;
            }
        }
    }
}

import java.awt.Point;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Scanner;

public class Main {
	static int n;
	static ArrayList<ArrayList<Integer>> arr;
	static int[] FDiff;
	static int[] SDiff;
	static boolean[] visited;

	public static void main(String[] args) {
		final Scanner sc = new Scanner(System.in);

		n = sc.nextInt();
		arr = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			arr.add(new ArrayList<Integer>());
		}

		for (int i = 0; i < n - 1; i++) {
			int from = sc.nextInt() - 1;
			int to = sc.nextInt() - 1;
			arr.get(from).add(to);
			arr.get(to).add(from);
		}

		visited = new boolean[n];
		FDiff = new int[n];
		SDiff = new int[n];
		ArrayDeque<Point> deq = new ArrayDeque<>();

		deq.add(new Point(0, 0));

		while (!deq.isEmpty()) {
			Point p = deq.poll();
			if (visited[p.x])
				continue;
			FDiff[p.x] = p.y;
			visited[p.x] = true;
			ArrayList<Integer> Edges = arr.get(p.x);
			for (int i = 0; i < Edges.size(); i++) {
				int to = Edges.get(i);
				if (!visited[to]) {
					deq.add(new Point(to, p.y + 1));
				}
			}
		}

		deq.clear();
		visited = new boolean[n];
		deq.add(new Point(n - 1, 0));
		while (!deq.isEmpty()) {
			Point p = deq.poll();
			if (visited[p.x]) {
				continue;
			}
			SDiff[p.x] = p.y;
			visited[p.x] = true;
			ArrayList<Integer> Edges = arr.get(p.x);
			for (int i = 0; i < Edges.size(); i++) {
				int to = Edges.get(i);
				if (!visited[to]) {
					deq.add(new Point(to, p.y + 1));
				}
			}
		}
		int fp = 0, sp = 0;
		for(int i = 0; i < n; i++) {
			if(FDiff[i] < SDiff[i]) {
				fp++;
			} else {
				sp++;
			}
		}
		System.out.println(fp > sp ? "Fennec" : "Snuke");
//		System.out.println(Arrays.toString(FDiff));
//		System.out.println(Arrays.toString(SDiff));
	}
}

