import java.util.ArrayList;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    int n;
    ArrayList<ArrayList<Edge>> es;
    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    void read() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        es = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            es.add(new ArrayList<>());
        }
        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            es.get(a).add(new Edge(a, b));
            es.get(b).add(new Edge(b, a));
        }
    }

    void solve() {
        int player = 1;
        int[] used = new int[n];
        Node[] graph = new Node[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new Node(i, es.get(i).size());
        }
        for (Edge e: es.get(0)) {
            graph[e.to].rank--;
        }
        for (Edge e: es.get(n-1)) {
            graph[e.to].rank--;
        }
        used[0] = 1;
        used[n-1] = -1;
        while (true) {
            int next = -1;
            int maxRank = -1;
            for (int i = 0; i < n; i++) {
                if (used[i] == player) {
                    for (Edge e: es.get(i)) {
                        if (used[e.to] == 0 && graph[e.to].rank > maxRank) {
                            next = e.to;
                            maxRank = graph[e.to].rank;
                        }
                    }
                }
            }
            if (next == -1)
                break;
            used[next] = player;
            for (Edge e: es.get(next))
                graph[e.to].rank--;
            player *= -1;
        }

        if (player == -1)
            System.out.println("Fennec");
        else
            System.out.println("Snuke");
    }

    private class Edge {
        int from, to;
        Edge(int f, int t) {
            from = f;
            to = t;
        }
    }

    private class Node {
        int id;
        int rank;
        Node(int id, int rank) {
            this.id = id;
            this.rank = rank;
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		Map<Integer,List<Integer>> tree = new HashMap<>();
		for(int i=0;i<n-1;i++) {
			int a = in.nextInt();
			int b = in.nextInt();
			if(tree.containsKey(a)) tree.get(a).add(b);
			else {
				List<Integer> list = new ArrayList<>();
				list.add(b);
				tree.put(a, list);
			}
			if(tree.containsKey(b)) tree.get(b).add(a);
			else {
				List<Integer> list = new ArrayList<>();
				list.add(a);
				tree.put(b, list);
			}
		}
		in.close();
		int[] board = new int[n+1];
		board[1] = 1;
		board[n] = -1;
		Queue<Integer> que = new ArrayDeque<>();
		que.add(1);
		que.add(n);
		while(!que.isEmpty()) {
			int now = que.poll();
			for(int next:tree.get(now)) {
				if(board[next]==0) {
					board[next] = board[now];
					que.add(next);
				}
			}
		}
		int sum = 0;
		for(int i=1;i<n;i++) {
			sum += board[i];
		}
		System.out.println(sum>0?"Fennec":"Snuke");
	}

}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    private static Scanner scan = new Scanner(System.in);

    public static void main(String[] args) {
	int N = Integer.parseInt(scan.next());
	UnionFind u = new UnionFind(N);
	List<Integer> bNeighbor = new ArrayList<Integer>();
	List<Integer> wNeighbor = new ArrayList<Integer>();
	for (int i = 0; i < N-1; i++) {
	    int a = Integer.parseInt(scan.next()) - 1;
	    int b = Integer.parseInt(scan.next()) - 1;
	    if(a > b) {
		int tmp = a;
		a = b;
		b = tmp;
	    }
	    if(a == 0 && b != N-1) {
		bNeighbor.add(b);
	    } else if(b == N-1 && a != 0) {
		wNeighbor.add(a);
	    } else if(a != 0 && b != N-1) {
		u.connect(a, b);
	    }
	}

	List<Integer> black = new ArrayList<Integer>();
	List<Integer> white = new ArrayList<Integer>();
	List<Integer> both = new ArrayList<Integer>();
	for(int node: bNeighbor) black.add(u.root(node));
	for(int node: wNeighbor) {
	    int g = u.root(node);
	    if(black.contains(g)) {
		black.remove(Integer.valueOf(g));
		both.add(g);
	    } else {
		white.add(g);
	    }
	}

	int blackCount = 0;
	for(int g: black) blackCount += u.size(g);
	int whiteCount = 0;
	for(int g: white) whiteCount += u.size(g);
	int bothCount = 0;
	for(int g: both) bothCount += u.size(g);

	if(bothCount % 2 != 0) blackCount++;

	System.out.println(blackCount > whiteCount ? "Fennec" : "Snuke");
	scan.close();
    }

    private static class UnionFind {
	private int[] u;

	public UnionFind(int n) {
	    u = new int[n];
	    for (int i = 0; i < n; i++) {
		u[i] = -1;
	    }
	}

	public int size(int a) {
	    return -u[root(a)];
	}

	public int root(int a) {
	    if(u[a] < 0) return a;
	    return u[a] = root(u[a]);
	}

	public boolean connect(int a, int b) {
	    if(root(a) == root(b)) return false;

	    a = root(a);
	    b = root(b);
	    if(u[a] > u[b]) {
		int tmp = a;
		a = b;
		b = tmp;
	    }
	    u[a] += u[b];
	    u[b] = a;
	    return true;
	}
    }
}

