// https://atcoder.jp/contests/abc067/tasks/arc078_b
// 1<->N番目の間を通るマスを埋めたあとに、それ以外のところを埋めるのが最適な戦略
// グラフ木なので、閉路は持たない。最小の通り方は1つだけ.O(N)
// ノード数は10^5なので、int[N][N]の配列を作るとMLEで落とされる
//  ArrayList<Integer>を各ノードごとに持つことでつながるノードだけ管理できる
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();

        Map<Integer, List<Integer>> tree = new HashMap<Integer, List<Integer>>();

        for (int i = 0; i < N - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;

            if(tree.containsKey(a)){
                tree.get(a).add(b);
            } else {
                List<Integer> list = new ArrayList<Integer>();
                list.add(b);
                tree.put(a, list);
            }

            if(tree.containsKey(b)){
                tree.get(b).add(a);
            } else {
                List<Integer> list = new ArrayList<Integer>();
                list.add(a);
                tree.put(b, list);
            }
        }

        out.println("Fennec");
        //solver(N, edges);
    }

    public static void solver(int N, int[][] edges) {
        // 0->N-1番目の最短経路を埋める
        List<Integer> shortestPath = dijkstra(N, edges, 0, N-1);

        int length = shortestPath.size();
        //out.println(Arrays.toString(shortestPath.toArray()));
        int splitNode1 = shortestPath.get((int)Math.floor(length/2) - 1);      //white
        int splitNode2 = shortestPath.get((int)Math.floor(length/2));          //black

        //out.println(splitNode1+","+splitNode2);

        // 通せなくする
        edges[splitNode1][splitNode2] = 0;
        edges[splitNode2][splitNode1] = 0;

        int blackCount = countNodes(N, edges, 0);
        int whiteCount = countNodes(N, edges, N-1);

        if(blackCount > whiteCount){
            out.println("Fennec");
        } else {
            out.println("Snuke");
        }

        //out.println(blackCount+","+whiteCount);

    }

    // start地点から行けるところを全て行ったときのノードの数
    public static int countNodes(int N, int[][] graph, int start){
        PriorityQueue<Integer> queue = new PriorityQueue<Integer>();
        queue.add(start);

        boolean[] passed = new boolean[N];
        passed[start] = true;

        int count = 1;

        while(!queue.isEmpty()){
            int pos = queue.poll();
            for(int n = 0; n < N; n++){
                if(graph[pos][n] > 0 && passed[n] == false){
                    queue.add(n);
                    passed[n] = true;
                    count++;
                }
            }
        }

        return count;
    }

    // MLEで落ちている
    public static List<Integer> dijkstra(int n, int[][] graph, int start, int end){
        final int INF = Integer.MAX_VALUE;

        int[] distance = new int[n];  //最小距離を管理
        int[] prev = new int[n];      //最小距離となるときの直前ノード

        // 初期化
        Arrays.fill(distance, INF);
        Arrays.fill(prev, INF);
        distance[start] = 0;
        prev[start] = start;
        Queue<Integer> nodesQueue = new PriorityQueue<Integer>();
        nodesQueue.add(start);

        // 計算
        while(!nodesQueue.isEmpty()){
            int node = nodesQueue.poll();

            for(int i = 0; i < n; i++){
                int moveCost = graph[node][i];
                if (moveCost > 0 && distance[i] > distance[node] + moveCost) {
                    distance[i] = distance[node] + moveCost;
                    prev[i] = node;
                    if(i != end){ nodesQueue.add(i);}
                }
            }
            //System.out.println(node+","+Arrays.toString(prev)+","+Arrays.toString(distance));
        }

        List<Integer> route = new ArrayList<Integer>();

        int pos = end;
        route.add(pos);
        while(pos != start){
            pos = prev[pos];
            route.add(pos);
        }

        return route;
    }
}

import java.util.*;

public class Main {

    private static int N;
    private static int[] A;
    private static int[] B;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        N = sc.nextInt();
        A = new int[N];
        B = new int[N];
        for (int i = 0; i < N-1; i++) {
            A[i] = sc.nextInt();
            B[i] = sc.nextInt();
        }
        System.out.println(solve());
    }

    private static String solve() {
        Rin r = mkRin();
        Path path = findPath(r);

        List<Integer> nodes = path.nodes;

        boolean fene = true;
        while(nodes.size() > 2) {
            if( fene ) {
                nodes.remove(0);
                fene = false;
            } else {
                nodes.remove(nodes.size() - 1);
                fene = true;
            }
        }

        int cut1 = nodes.get(0);
        int cut2 = nodes.get(1);

        UnionFind uf = new UnionFind(N);
        for (int i = 0; i < N-1; i++) {
            int a = A[i];
            int b = B[i];

            if( cut1 == a && cut2 == b || cut1 == b && cut2 == a ) {
                continue;
            }

            uf.unite(a-1, b-1);
        }

        int fRoot = uf.root(0);
        int f = 0;
        for (int i = 0; i < N; i++) {
            if( uf.root(i) == fRoot ) {
                f++;
            }
        }

        int s = N - f;

        if( f > s ) {
            return "Fennec";
        } else {
            return "Snuke";
        }
    }

    private static Path findPath(Rin r) {
        boolean[] used = new boolean[N];
        List<Path> current = Collections.singletonList(Path.single(1));
        while(true) {
            List<Path> next = new ArrayList<>();
            for (Path path : current) {
                for (Integer n : r.get(path.last())) {
                    if( n == N ) {
                        return path.add(n);
                    } else if( !used[n] ){
                        next.add(path.add(n));
                        used[n] = true;
                    }
                }
            }
            current = next;
        }
    }

    private static Rin mkRin() {
        Rin r = new Rin(N);
        for (int i = 0; i < N-1; i++) {
            r.set(A[i], B[i]);
        }
        return r;
    }

    // 隣接リスト
    private static class Rin {

        private final List[] array;

        public Rin(int n) {
            array = new List[n];
        }

        public void set(int a, int b) {
            get(a).add(b);
            get(b).add(a);
        }

        public List<Integer> get(int n) {
            if( array[n - 1] == null ) {
                array[n - 1] = new ArrayList();
            }
            //noinspection unchecked
            return (List<Integer>)array[n - 1];
        }
    }

    public static class Path {

        public static Path single(int n) {
            return new Path(Collections.singletonList(n));
        }

        private final List<Integer> nodes;

        public Path(List<Integer> nodes) {
            this.nodes = nodes;
        }

        public Path add(int n) {
            List<Integer> list = new ArrayList<>(nodes.size() + 1);
            list.addAll(nodes);
            list.add(n);
            return new Path(list);
        }

        public int last() {
            return nodes.get(nodes.size() - 1);
        }
    }

    static class UnionFind {

        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int root(int n) {
            if( parent[n] == n ) {
                return n;
            } else {
                parent[n] = root(parent[n]);
                return parent[n];
            }
        }

        void unite(int x, int y) {
            x = root(x);
            y = root(y);
            if( x == y ) return;

            if( rank[x] < rank[y] ) {
                parent[x] = y;
            } else {
                parent[y] = x;
                if( rank[x] == rank[y]) rank[x]++;
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;
public class Main {
	public static final int N = 100005;
	public static int n;
	public static int[] g = new int[N];

	public static int[] bfa(int s){
		int[] dist = new int[n+1];
		Arrays.fill(dist, -1);
		Queue<Integer> q = new ArrayDeque<Integer>();
		q.add(s);
		dist[s] = 0;

		while(!q.isEmpty()){
			int u = q.poll();
			for(int v :g){
				if(dist [v] == -1){
					dist[v] = dist[u] + 1;
					q.add(v);
				}
			}
		}
		return dist;
	}

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		n = scan.nextInt();
		for(int i = 1;i < n;i++){
			int a = scan.nextInt();
			int b = scan.nextInt();
			g[a] = b;
			g[b] = a;
		}

		int[] d1 = bfa(1);
		int[] d2 = bfa(n);
		int l = 0;
		int r = 0;
		for (int i = 1;i <= n;i++){
			if(d1[i] <= d2[i]){
				l++;
			}else{
				r++;
			}
		}
		if(l>r){
			System.out.println("Fennec");
		}else{
			System.out.println("Snuke");
		}
	}

}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Scanner;
import java.util.TreeSet;

public class Main {
	static HashMap<Integer, TreeSet<Integer>> dp = new HashMap<Integer, TreeSet<Integer>>();
	static int n;
	static int max = Integer.MAX_VALUE;

	public static void main(String[] args) {

		Scanner scan = new Scanner(System.in);
		n = scan.nextInt();
		for (int i = 0; i < n - 1; i++) {
			int a = scan.nextInt();
			int b = scan.nextInt();

			if (!dp.containsKey(a)) {
				TreeSet<Integer> list = new TreeSet<>();
				list.add(b);
				dp.put(a, list);
			} else {
				dp.get(a).add(b);
			}

			if (!dp.containsKey(b)) {
				TreeSet<Integer> list = new TreeSet<>();
				list.add(a);
				dp.put(b, list);
			} else {
				dp.get(b).add(a);
			}

		}
		int[] f = bfs(1);
		int[] s = bfs(n);

		int ansF = 0;
		int ansS = 0;
		for (int i = 1; i <= n; i++) {
			if (f[i] <= s[i]) {
				ansF++;

			} else {
				ansS++;

			}
		}

		if (ansF > ansS) {
			System.out.println("Fennec");
		} else {
			System.out.println("Snuke");
		}

	}

	public static int[] bfs(int u) {
		int[] ans = new int[n + 1];
		Deque<Integer> q = new ArrayDeque<Integer>();
		q.offer(u);
		Arrays.fill(ans, max);
		ans[u] = 0;
		Iterator<Integer> it = null;

		while (!q.isEmpty()) {
			// 調べるノードを取り出す
			int v = q.poll();
			it = dp.get(v).iterator();
			while (it.hasNext()) {
				int temp = it.next();
				if (ans[temp] == max) {
					ans[temp] = ans[v] + 1;
					q.offer(temp);
				}
			}
		}
		return ans;

	}

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.NoSuchElementException;
import java.util.Queue;
public class Main {
    private static final PrintStream ps     = System.out;
    private static final InputStream IS     = System.in;
    private static final byte[]      BUFFER = new byte[1024];
    private static int               ptr    = 0;
    private static int               buflen = 0;

    public static void main(String[] args) {
        int n = ni();
        boolean[] v = new boolean[n+1];
        int[] dFrom1 = new int[n+1];
        ArrayList<Integer>[] g = new ArrayList[n+1];
        for (int i = 0; i < n+1; i++) {
            g[i] = new ArrayList<Integer>();
        }

        for (int i = 0; i < n-1; i++) {
            int a = ni();
            int b = ni();
            g[a].add(b);
            g[b].add(a);
        }

        Queue<Integer> q = new LinkedList<Integer>();
        q.add(1);
        v[1] = true;

        int fenec = 0;
        int snuke = 0;
        while (!q.isEmpty()) {
            int head = q.poll();
            for (int next: g[head]) {
                if (!v[next]) {
                    dFrom1[next] = dFrom1[head] + 1;
                    v[next] = true;

                    if (next != n) {
                        fenec++;
                        q.add(next);
                    }
                }
            }
        }
        int mid = dFrom1[n] - 1;
        int midFenec = (mid + 1) / 2;
        fenec -= (mid - midFenec);
        snuke = n - (fenec + 1) - 1;

        ps.println(fenec > snuke ? "Fennec" : "Snuke");
    }

    private static boolean hasNextByte() {
        if (ptr < buflen)
            return true;
        else {
            ptr = 0;
            try {
                buflen = IS.read(BUFFER);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0)
                return false;
        }
        return true;
    }

    private static int readByte() {
        if (hasNextByte())
            return BUFFER[ptr++];
        else
            return -1;
    }

    private static boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public static boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(BUFFER[ptr]))
            ptr++;
        return hasNextByte();
    }

    public static String n() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public static long nl() {
        if (!hasNext())
            throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b)
            throw new NumberFormatException();
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b))
                return minus ? -n : n;
            else
                throw new NumberFormatException();
            b = readByte();
        }
    }

    public static int ni() {
        long nl = nl();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
            throw new NumberFormatException();
        return (int) nl;
    }

    public static double nextDouble() {
        return Double.parseDouble(n());
    }

    private static int[] nia(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = ni();
        return a;
    }
}

import java.util.*;
import java.io.*;


public class Main{

    public static Node[] nodes;
    public static ArrayList<Node> fennecCanColor, snukeCanColor;
    public static boolean[] colored;

    public static void main(String[] args) throws Exception{

        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        int n = Integer.parseInt(in.readLine());

        nodes = new Node[n+1];
        colored = new boolean[n+1];
        fennecCanColor = new ArrayList<Node>();
        snukeCanColor = new ArrayList<Node>();

        for(int i = 1; i <= n; i++){
            nodes[i] = new Node();
            nodes[i].num = i;
        }

        colored[1] = true;
        colored[n] = true;

        for(int i = 1; i < n; i++){
            String[] input = in.readLine().split("\\s+");
            int a = Integer.parseInt(input[0]);
            int b = Integer.parseInt(input[1]);

            nodes[a].adjList.add(nodes[b]);
            nodes[b].adjList.add(nodes[a]);

            nodes[a].canColorSize++;
            nodes[b].canColorSize++;

            if(a == 1 || a == n){
                nodes[b].canColorSize--;
            }

            if(b == 1 || b == n){
                nodes[a].canColorSize--;
            }

            if(a == 1 && b != n){
                fennecCanColor.add(nodes[b]);
            }
            else if(a == n && b != 1){
                snukeCanColor.add(nodes[b]);
            }

            if(b == 1 && a != n){
                fennecCanColor.add(nodes[a]);
            }
            else if(b == n && a != 1){
                snukeCanColor.add(nodes[a]);
            }
        }

        Collections.sort(fennecCanColor);
        Collections.sort(snukeCanColor);

        boolean fennec = true;;

        while(play(fennec)){
            fennec = !fennec;
        }

        if(fennec){
            out.println("Snuke");
        }
        else{
            out.println("Fennec");
        }

        in.close();
        out.close();
    }

    public static boolean play(boolean fennec){
        if(fennec){
            return playFennec();
        }
        return playSnuke();
    }

    public static boolean playFennec(){

        int size = fennecCanColor.size();

        if(size == 0){
            return false;
        }

        boolean canColor = false;

        for(int i = 0; i < size; i++){
            Node tmpNode = fennecCanColor.get(i);
            if(snukeCanColor.contains(tmpNode)){
                //System.out.println("Fennec colors: " + tmpNode.num);
                colored[tmpNode.num] = true;
                fennecCanColor.remove(i);
                snukeCanColor.remove(tmpNode);
                canColor = true;
                addAdjList(tmpNode.num, true);
                break;
            }
        }

        if(!canColor){
            Node tmpNode = fennecCanColor.get(0);
            //System.out.println("Fennec colors: " + fennecCanColor.get(0).num);
            colored[tmpNode.num] = true;
            canColor = true;
            addAdjList(fennecCanColor.get(0).num, true);
            fennecCanColor.remove(0);
        }

        return canColor;
    }

    public static boolean playSnuke(){

        int size = snukeCanColor.size();

        if(size == 0){
            return false;
        }

        boolean canColor = false;

        for(int i = 0; i < size; i++){
            Node tmpNode = snukeCanColor.get(i);
            if(fennecCanColor.contains(tmpNode)){
                //System.out.println("Snuke colors: " + tmpNode.num);
                colored[tmpNode.num] = true;
                snukeCanColor.remove(i);
                fennecCanColor.remove(tmpNode);
                canColor = true;
                addAdjList(tmpNode.num, true);
                break;
            }
        }

        if(!canColor){
            Node tmpNode = snukeCanColor.get(0);
            //System.out.println("Snuke colors: " + snukeCanColor.get(0).num);
            colored[tmpNode.num] = true;
            canColor = true;
            addAdjList(snukeCanColor.get(0).num, true);
            snukeCanColor.remove(0);
        }

        return canColor;
    }

    public static void addAdjList(int num, boolean fennec){
        if(fennec){
            for(Node node : nodes[num].adjList){
                node.canColorSize--;
                if(!colored[node.num]){
                    //System.out.println("\tFennec adds: " + node.num);
                    fennecCanColor.add(node);
                }
            }
        }
        else{
            for(Node node : nodes[num].adjList){
                if(!colored[node.num]){
                    //System.out.println("\tSnuke adds: " + node.num);
                    snukeCanColor.add(node);
                }
            }
        }

        Collections.sort(fennecCanColor);
        Collections.sort(snukeCanColor);
    }
}

class Node implements Comparable<Node> {

    public int num;
    public int canColorSize;
    public ArrayList<Node> adjList;

    public Node(){
        adjList = new ArrayList<Node>();
        canColorSize = 0;
    }

    @Override
    public int compareTo(Node n){
        return -1 * Integer.compare(this.canColorSize, n.canColorSize);
    }

}

import java.util.*;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int N = scan.nextInt();
        List<List<Integer>> tree = new ArrayList<>();
        for (int i :IntStream.range(0, N-1).toArray()){
            tree.add(Arrays.asList(scan.nextInt(), scan.nextInt()));
        }

        List<Integer> path = dijkstra(tree, N);
        List<Integer> black = new ArrayList<>();
        int blackNum = path.size() / 2 + path.size() % 2;
        for(int i = 0; i < blackNum; i++) {
            black.add(path.get(i));
        }
        int forbidden = path.get(blackNum);
        int blackCount = count(tree,black,forbidden,N);
        if(path.size() % 2 == 0) {
            if(N < blackCount * 2) {
                System.out.println("Fennec");
            }
            else{
                System.out.println("Snuke");
            }
        }
        else {
            if(N < blackCount * 2 + 1) {
                System.out.println("Fennec");
            }
            else{
                System.out.println("Snuke");
            }
        }
    }

    static List<Integer> dijkstra(List<List<Integer>> tree, int N) {
        LinkedList<List<Integer>> stack = new LinkedList<>();
        stack.add(Collections.singletonList(1));
        List<List<Integer>> ret = new ArrayList<>();
        for (int i :IntStream.range(0, N).toArray()){
            List<Integer> current = stack.removeFirst();
            int node = current.get(current.size()-1);
            tree.stream().filter(x -> x.contains(node)).forEach(path ->{
                int next = path.get(0) != node ? path.get(0) : path.get(1);
                if(next == N) {
                    List<Integer> tmp = new ArrayList<>(current);
                    tmp.add(next);
                    ret.add(tmp);
                }
                if(!current.contains(next)) {
                    List<Integer> tmp = new ArrayList<>(current);
                    tmp.add(next);
                    stack.add(tmp);
                }
            });
            if(!ret.isEmpty()) {
                return ret.get(0);
            }
        }
        return null;
    }

    static int count(List<List<Integer>> tree, List<Integer> black, int forbidden, int N) {
        List<Set<Integer>> ret = new ArrayList<>();
        Set<Integer> ans = new HashSet<>();
        ans.addAll(black);
        ret.add(new HashSet<>());
        for (List<Integer> edge : tree) {
            int a = edge.get(0);
            int b = edge.get(1);
            if(a ==forbidden || b == forbidden) {
                break;
            }
            if(ans.contains(a) || ans.contains(b)) {
                ans.add(a);
                ans.add(b);
                for(int i = 0; i < ret.size(); i++) {
                    Set<Integer> tmp = ret.get(i);
                    if(tmp.contains(a) || tmp.contains(b)) {
                        ans.addAll(tmp);
                        ret.remove(i);
                        break;
                    }
                }

            }
            else {
                boolean flag= false;
                for (Set<Integer> tmp : ret) {
                    if (tmp.contains(a) || tmp.contains(b)) {
                        tmp.add(a);
                        tmp.add(b);
                        flag = true;
                        break;
                    }
                }
                if(!flag) {
                    Set<Integer> tmp = new HashSet<>();
                    tmp.add(a);
                    tmp.add(b);
                    ret.add(tmp);
                }
            }
        }
        return ans.size();
    }
}

