        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(from);
        dist[from] = 0;

        while(!q.isEmpty()) {
            int n = q.pop();
            List<Integer> nexts = r.get(n);
            for (int next : nexts) {
                if( dist[next] > dist[n] + 1 ) {
                    dist[next] = dist[n] + 1;
                    q.add(next);
                }
            }
        }
        return dist;
    }

    private static String solve() {
        Rin r = mkRin();
        int[] from_1 = distance(1, r);
        int[] from_n = distance(N, r);

        int f = 0;
        for (int i = 1; i <= N; i++) {
            if( from_1[i] <= from_n[i] ) {
                f++;
            }
        }
        int s = N - f;

        if( f > s ) {
            return "Fennec";
        } else {
            return "Snuke";
        }
    }

    private static Rin mkRin() {
        Rin r = new Rin(N);
        for (int i = 0; i < N-1; i++) {
            r.set(A[i], B[i]);
        }
        return r;
    }

    // 隣接リスト
    private static class Rin {

        private final List[] array;

        public Rin(int n) {
            array = new List[n];
            for (int i = 0; i < n; i++) {
                array[i] = new ArrayList<>();
            }
        }

        public void set(int a, int b) {
            get(a).add(b);
            get(b).add(a);
        }

        public List<Integer> get(int n) {
            //noinspection unchecked
            return (List<Integer>)array[n - 1];
        }
    }

    static class FastScanner {

        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        public String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

}

import java.awt.Point;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    static int n;
    static ArrayList<ArrayList<Integer>> arr;
    static int[] FDiff;
    static int[] SDiff;
    static boolean[] visited;

    public static void main(String[] args) {
        final Scanner sc = new Scanner(System.in);

        n = sc.nextInt();
        arr = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            arr.add(new ArrayList<Integer>());
        }

        for (int i = 0; i < n - 1; i++) {
            int from = sc.nextInt() - 1;
            int to = sc.nextInt() - 1;
            arr.get(from).add(to);
            arr.get(to).add(from);
        }

        visited = new boolean[n];
        FDiff = new int[n];
        SDiff = new int[n];
        ArrayDeque<Point> deq = new ArrayDeque<>();

        deq.add(new Point(0, 0));

        while (!deq.isEmpty()) {
            Point p = deq.poll();
            if (visited[p.x]) {
                continue;
            }
            FDiff[p.x] = p.y;
            visited[p.x] = true;
            ArrayList<Integer> Edges = arr.get(p.x);
            for (int i = 0; i < Edges.size(); i++) {
                int to = Edges.get(i);
                if (!visited[to]) {
                    deq.add(new Point(to, p.y + 1));
                }
            }
        }

        deq.clear();
        visited = new boolean[n];
        deq.add(new Point(n - 1, 0));
        while (!deq.isEmpty()) {
            Point p = deq.poll();
            if (visited[p.x]) {
                continue;
            }
            SDiff[p.x] = p.y;
            visited[p.x] = true;
            ArrayList<Integer> Edges = arr.get(p.x);
            for (int i = 0; i < Edges.size(); i++) {
                int to = Edges.get(i);
                if (!visited[to]) {
                    deq.add(new Point(to, p.y + 1));
                }
            }
        }
        int fp = 0, sp = 0;
        for(int i = 0; i < n; i++) {
            if(FDiff[i] <= SDiff[i]) {
                fp++;
            } else {
                sp++;
            }
        }
        System.out.println(fp > sp ? "Fennec" : "Snuke");
//		System.out.println(Arrays.toString(FDiff));
//		System.out.println(Arrays.toString(SDiff));
//		System.out.println(fp+" "+sp);
    }
}

import java.util.*;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] g = buildGraph(sc, n, n-1);
        boolean[] used = new boolean[n];
        ArrayDeque<Integer> fq = new ArrayDeque<>();
        ArrayDeque<Integer> sq = new ArrayDeque<>();
        fq.add(0); sq.add(n-1);
        int fsum = 0; int ssum = 0;
        for (int i = 0; i < n; i++) {
            ArrayDeque<Integer> tq = new ArrayDeque<>();
            while(!fq.isEmpty()){
                int nex = fq.poll();
                if(!used[nex]){
                    fsum++; used[nex] = true;
                    for(int a : g[nex]){
                        tq.add(a);
                    }
                }
            }
            fq.addAll(tq);
            tq.clear();
            while(!sq.isEmpty()){
                int nex = sq.poll();
                if(!used[nex]){
                    ssum++; used[nex] = true;
                    for(int a : g[nex]){
                        tq.add(a);
                    }
                }
            }
            sq.addAll(tq);
        }
        System.out.println(fsum <= ssum ? "Snuke" : "Fennec");
        sc.close();

    }

    public static int[][] buildGraph(Scanner sc, int n, int m) {
        int[][] graph = new int[n][];
        int[][] edges = new int[m][2];
        int[] deg = new int[n];
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            edges[i][0] = a;
            edges[i][1] = b;
            deg[a]++;
            deg[b]++;
        }
        for (int i = 0; i < n; i++) {
            graph[i] = new int[deg[i]];
        }
        for (int i = 0; i < m; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            graph[a][--deg[a]] = b;
            graph[b][--deg[b]] = a;
        }

        return graph;
    }

}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main
{
    private static class Step {
        final Step prev;
        final int pos;

        Step(Step prev, int pos)
        {
            this.prev = prev;
            this.pos = pos;
        }
    }

    private static List<Integer> shortestRoute(int goal, Map<Integer, List<Integer>> nodes)
    {
        LinkedList<Step> queue = new LinkedList<>();
        queue.add(new Step(null, 0));

        while (true) {
            Step step = queue.pop();

            if (step.pos == goal) {
                LinkedList<Integer> route = new LinkedList<>();
                Step cur = step;
                while (true) {
                    route.addFirst(cur.pos);
                    if (cur.prev == null) {
                        return route;
                    }
                    cur = cur.prev;
                }
            }

            for (int next : nodes.get(step.pos)) {
                if (step.prev != null && next == step.prev.pos) {
                    continue;
                }
                queue.add(new Step(step, next));
            }
        }
    }

    private static void dfs(Boolean[] vertices, Map<Integer, List<Integer>> nodes, int[] cut)
    {
        LinkedList<Integer> stack = new LinkedList<>();
        stack.add(0);

        while (true) {
            if (stack.isEmpty()) {
                return;
            }

            Integer pos = stack.removeLast();

            for (int next : nodes.get(pos)) {
                if (vertices[next] != null) {
                    continue;
                }
                if (cut[0] == pos && cut[1] == next
                        || cut[1] == pos && cut[0] == next) {
                    continue;
                }
                vertices[next] = true;
                stack.addLast(next);
            }
        }
    }

    public static void main(String[] args)
    {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        Map<Integer, List<Integer>> nodes = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            int a = scanner.nextInt() - 1;
            int b = scanner.nextInt() - 1;

            nodes.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
            nodes.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
        }

        List<Integer> shortestRoute = shortestRoute(n - 1, nodes);

        int conflictPos = (int) Math.ceil(shortestRoute.size() / 2.0);
        int[] cut = new int[] { shortestRoute.get(conflictPos - 1), shortestRoute.get(conflictPos)};

        Boolean[] vertices = new Boolean[n];
        vertices[0] = true;
        vertices[n - 1] = false;
        dfs(vertices, nodes, cut);

        int fennecCells = 0;
        for (Boolean b : vertices) {
            if (b != null && b) {
                fennecCells++;
            }
        }

        if (fennecCells > (n - fennecCells)) {
            System.out.println("Fennec");
        }
        else {
            System.out.println("Snuke");
        }
    }
}

import java.util.*;
class Main {
  static int N;
  static boolean[][] neighbors;

  static int saiki(int turn, int[] locations, int color, int[] masu) {
    int[] loc = (int[])locations.clone();
    int here = locations[color];
    int maxturn = turn;
    turn++;
    for (int i = 0; i < N; i++) {
      if (neighbors[here][i] && masu[i] == -1) {
        loc[color] = i;
        int[] cur = (int[])masu.clone();
        cur[i] = color;
        maxturn = Math.max(maxturn, saiki(turn, loc, 1-color, cur));
      }
    }
    return maxturn;
  }

  public static void main(String args[]) {
    Scanner sc = new Scanner(System.in);
    N = sc.nextInt();
    neighbors = new boolean[N][N];
    for (int i = 0; i < N-1; i++) {
      int a = sc.nextInt() - 1;
      int b = sc.nextInt() - 1;
      neighbors[a][b] = true;
      neighbors[b][a] = true;
    }

    int[] masu = new int[N];
    Arrays.fill(masu, -1);
    masu[0]   = 0;
    masu[N-1] = 1;

    if (saiki(0, new int[]{0,N-1}, 0, masu) % 2 == 0)
      System.out.println("Snuke");
    else
      System.out.println("Fennec");
  }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説どおりに作成したソースコード
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			@SuppressWarnings("unchecked")
			List<Path>[] pathLists = new List[n];
			IntStream.range(0, n).forEach(i -> pathLists[i] = new ArrayList<>());
			IntStream.range(0, n - 1).forEach(i -> {
				int from = scanner.nextInt() - 1;
				int to = scanner.nextInt() - 1;
				pathLists[from].add(new Path(from, to, 1));
				pathLists[to].add(new Path(to, from, 1));
			});
			// ノード1からの距離の配列
			int[] distances1 = dijkstra(pathLists, 0, n);
			// ノードnからの距離の配列
			int[] distancesn = dijkstra(pathLists, n - 1, n);
			// 黒と白に塗られたマスの数
			int black = 0, white = 0;
			for (int i = 0; i < n; i++) {
				if (distances1[i] <= distancesn[i]) {
					black++;
				} else {
					white++;
				}
			}
			System.out.println((black >= white) ? "Fennec" : "Snuke");
		}
	}

	/**
	 * @param pathLists ノード間の連結パス一覧の配列
	 * @param src       開始ノード
	 * @param n         ノードの数
	 * @return 開始ノードからの距離の配列
	 */
	private static int[] dijkstra(List<Path>[] pathLists, int src, int n) {
		int[] distances = new int[n];
		Arrays.fill(distances, Integer.MAX_VALUE);
		// 最短距離が確定したかどうか
		boolean[] fixed = new boolean[n];
		Arrays.fill(fixed, false);
		// 出発地点までの距離を0とする
		distances[src] = 0;
		Queue<Path> queue = new PriorityQueue<>();
		queue.add(new Path(src, src, 0));
		while (!queue.isEmpty()) {
			int now = queue.poll().to;
			if (!fixed[now]) {
				fixed[now] = true;
				for (Path path : pathLists[now]) {
					if (!fixed[path.to] && distances[path.to] > distances[now] + path.cost) {
						distances[path.to] = distances[now] + path.cost;
						queue.add(new Path(path.to, path.to, distances[path.to]));
					}
				}
			}
		}
		return distances;
	}

	/**
	 * ノード間の一つのパスを表すクラス
	 */
	private static class Path implements Comparable<Path> {
		/** 開始ノード */
		@SuppressWarnings("unused")
		int from;
		/** 終了ノード */
		int to;
		/** 移動コスト */
		int cost;

		Path(int from, int to, int cost) {
			super();
			this.from = from;
			this.to = to;
			this.cost = cost;
		}

		@Override
		public int compareTo(Path path) {
			return this.cost - path.cost;
		}
	}
}

