class Solver {
  private static final int FENNEC = 1;
  private static final int SNUKE = 2;

  final int n;
  final int[] as, bs;
  List<List<Integer>> graph;
  int[] colors;
  boolean[] visited;

  Solver(int n, int[] as, int[] bs) {
    this.n = n;
    this.as = as;
    this.bs = bs;
  }

  private int dfs(int prev, int index, int length) {
    if (index == n) {
      return length;
    }

    for (int next : graph.get(index)) {
      if (next == prev) {
        continue;
      }
      int goalLength = dfs(index, next, length + 1);
      if (goalLength > 0) {
        if (length <= goalLength / 2) {
          colors[index] = FENNEC;
        } else {
          colors[index] = SNUKE;
        }
        return goalLength;
      }
    }
    return 0;
  }

  private int visit(int index, int color) {
    if (colors[index] != color && colors[index] != 0) {
      return 0;
    }
    if (visited[index]) {
      return 0;
    }
    visited[index] = true;

    int sum = 1;
    for (int next : graph.get(index)) {
      sum += visit(next, color);
    }
    return sum;
  }

  public String solve() {
    graph = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }

    for (int i = 0; i < n-1; i++) {
      graph.get(as[i]).add(bs[i]);
      graph.get(bs[i]).add(as[i]);
    }

    colors = new int[n + 1];
    colors[1] = FENNEC;
    colors[n] = SNUKE;

    dfs(-1, 1, 1);

    visited = new boolean[n + 1];
    int count1 = visit(1, FENNEC);
    int count2 = visit(n, SNUKE);
//    System.err.printf("%d %d\n", count1, count2);
    if (count1 > count2) {
      return "Fennec";
    } else {
      return "Snuke";
    }
  }
}

