class ModCalculator {
  private final long mod;

  ModCalculator(long mod) {
    this.mod = mod;
  }

  public long add(long a, long b) {
    return (a + b) % mod;
  }

  public long sub(long a, long b) {
    return (a - b + mod) % mod;
  }

  public long mul(long a, long b) {
    return (a * b) % mod;
  }

  public long pow(long a, long b) {
    if (b == 0) {
      return 1;
    }
    long v = pow(mul(a, a), b / 2);
    if (b % 2 == 1) {
      return mul(v, a);
    } else {
      return v;
    }
  }

  public long inverse(long a) {
    return pow(a, mod - 2);
  }

  public long div(long a, long b) {
    return mul(a, inverse(b));
  }
}

class ModCombinationCache {
  private final ModCalculator modCalculator;
  private final List<Long> factorialCache;
  private final List<Long> factorialInverseCache;

  public ModCombinationCache(ModCalculator modCalculator) {
    this.modCalculator = modCalculator;
    factorialCache = new ArrayList<>();
    factorialCache.add(1L);
    factorialInverseCache = new ArrayList<>();
    factorialInverseCache.add(1L);
  }

  private void resize(int n) {
    for (int i = factorialCache.size() - 1; i < n; i++) {
      long v = modCalculator.mul(factorialCache.get(i), i + 1);
      factorialCache.add(v);
      factorialInverseCache.add(modCalculator.inverse(v));
    }
  }

  public long getP(int n) {
    resize(n);
    return factorialCache.get(n);
  }

  public long getC(int n, int k) {
    resize(n);
    return modCalculator.mul(factorialCache.get(n), modCalculator.mul(factorialInverseCache.get(k), factorialInverseCache.get(n-k)));
  }
}

class Algorithm {
  private static void swap(Object[] list, int a, int b) {
    Object tmp = list[a];
    list[a] = list[b];
    list[b] = tmp;
  }

  public static <T extends Comparable<? super T>> boolean nextPermutation(T[] ts) {
    int rightMostAscendingOrderIndex = ts.length - 2;
    while (rightMostAscendingOrderIndex >= 0 &&
        ts[rightMostAscendingOrderIndex].compareTo(ts[rightMostAscendingOrderIndex + 1]) >= 0) {
      rightMostAscendingOrderIndex--;
    }
    if (rightMostAscendingOrderIndex < 0) {
      return false;
    }

    int rightMostGreatorIndex = ts.length - 1;
    while (ts[rightMostAscendingOrderIndex].compareTo(ts[rightMostGreatorIndex]) >= 0) {
      rightMostGreatorIndex--;
    }

    swap(ts, rightMostAscendingOrderIndex, rightMostGreatorIndex);
    for (int i = 0; i < (ts.length - rightMostAscendingOrderIndex - 1) / 2; i++) {
      swap(ts, rightMostAscendingOrderIndex + 1 + i, ts.length - 1 - i);
    }
    return true;
  }

  public static void shuffle(int[] array) {
    Random random = new Random();
    int n = array.length;
    for (int i = 0; i < n; i++) {
      int randomIndex = i + random.nextInt(n - i);

      int temp = array[i];
      array[i] = array[randomIndex];
      array[randomIndex] = temp;
    }
  }

  public static void shuffle(long[] array) {
    Random random = new Random();
    int n = array.length;
    for (int i = 0; i < n; i++) {
      int randomIndex = i + random.nextInt(n - i);

      long temp = array[i];
      array[i] = array[randomIndex];
      array[randomIndex] = temp;
    }
  }

  public static void sort(int[] array) {
    shuffle(array);
    Arrays.sort(array);
  }

  public static void sort(long[] array) {
    shuffle(array);
    Arrays.sort(array);
  }
}

class UnionFind {
  int[] parents;
  int[] ranks;

  UnionFind(int n) {
    parents = new int[n];
    ranks = new int[n];

    for (int i = 0; i < n; i++) {
      parents[i] = i;
    }
  }

  public int getRoot(int index) {
    if (parents[index] == index) {
      return index;
    } else {
      parents[index] = getRoot(parents[index]);
      return parents[index];
    }
  }

  public boolean sameGroup(int a, int b) {
    return getRoot(a) == getRoot(b);
  }

  public void merge(int a, int b) {
    int rootA = getRoot(a);
    int rootB = getRoot(b);
    if (rootA == rootB) {
      return;
    }
    if (ranks[rootA] < ranks[rootB]) {
      parents[rootA] = rootB;
    } else if (ranks[rootB] < ranks[rootA]) {
      parents[rootB] = rootA;
    } else {
      parents[rootA] = rootB;
      ranks[rootB]++;
    }
  }
}

import java.util.*;

public class Main {
	static ArrayList<Integer>[] lists;
	static int n;
	static int[] colors;
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		lists = new ArrayList[n + 1];
		for (int i = 1; i <= n; i++) {
			lists[i] = new ArrayList<Integer>();
		}
		for (int i = 0; i < n - 1; i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			lists[a].add(b);
			lists[b].add(a);
		}
		// 最短経路の探索
		ArrayList<Integer> route = new ArrayList<>();
		search(route, 1);

		int x = route.size() / 2 + (route.size() % 2);
		colors = new int[n + 1];
		for (int i = 0; i < route.size(); i++) {
			if (i < x) {
				colors[route.get(i)] = 1;
			} else {
				colors[route.get(i)] = 2;
			}
		}

		// 色塗り
		for (int c : route) {
			paint(c, colors[c]);
		}

		int Fennec = 0;
		int Snuke = 0;
		for (int i = 1; i <= n; i++) {
			if (colors[i] == 1) {
				Fennec++;
			} else {
				Snuke++;
			}
		}

		if (Fennec > Snuke) {
			System.out.println("Fennec");
		} else {
			System.out.println("Snuke");
		}
	}

	static void paint(int idx, int color) {
		for (int x : lists[idx]) {
			if (colors[x] == 0) {
				colors[x] = color;
				paint(x, color);
			}
		}
	}

	static boolean search(ArrayList<Integer> list, int a) {
		list.add(a);
		if (a == n) {
			return true;
		}
		for (Integer x : lists[a]) {
			if (list.contains(x)) {
				continue;
			}
			boolean ret = search(list, x);
			if (ret) {
				return true;
			} else {
				list.remove(x);
			}
		}
		return false;
	}
}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private void solve(Scanner sc) {
        int N = sc.nextInt();

        List<List<Path>> list = new ArrayList<>();
        for (int i = 0; i < N; ++i) {
            list.add(new ArrayList<>());
        }

        for (int i = 1; i <= N - 1; ++i) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            list.get(a).add(new Path(a, b, 1));
            list.get(b).add(new Path(b, a, 1));
        }

        long[] dist = dist(N, list);
        long ct1 = 0;
        long ct2 = 0;
        for (int i = 1; i < N - 1; ++i) {
            if (dist[i] < dist[N - 1]) {
                ++ct1;
            }
            if (dist[i] > dist[N - 1]) {
                ++ct2;
            }
        }
//_err.println(Arrays.toString(dist));
//_err.println(ct1 + " / " + ct2);

        if (dist[N - 1] % 2 == 0 && ct1 >= ct2) {
            _out.println("Fennec");
        } else {
            _out.println("Snuke");
        }
    }
    private long[] dist(int N, List<List<Path>> edges) {
        long[] dist = new long[N];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[0] = 0;
        Queue<Path> q = new PriorityQueue<>();
        for (int i = 0; i < edges.size(); ++i) {
            for (Path edge : edges.get(i)) {
                q.offer(edge);
            }
        }

        while (!q.isEmpty()) {
            Path edge = q.poll();
            int u = edge.to;
            for (Path p : edges.get(u)) {
                long tmp = dist[u] + p.cost;
                if (dist[p.to] > tmp) {
                    dist[p.to] = tmp;
                    Path newPath = new Path(0, p.to, tmp);
                    q.offer(newPath);
                }
            }
        }

        return dist;
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    private static class Path implements Comparable<Path> {
        int from;
        int to;
        long cost;
        public Path(int from, int to, long cost) {
            this.from = from;
            this.to = to;
            this.cost = cost;
        }
        @Override
        public int compareTo(Path that) {
            if (that.cost > this.cost) {
                return -1;
            } else if (that.cost < this.cost) {
                return 1;
            }
            if (that.from != this.from) {
                return this.from - that.from;
            }
            if (that.to != this.to) {
                return this.to - that.to;
            }
            return 0;
        }
        @Override
        public String toString() {
            return "[" + from + ", " + to + ", " + cost + "]";
        }
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
}

import java.io.BufferedReader;
