    static class Dijkstra
    {
        long initValue = LINF;
        Node[] nodes;
        int s, n;
        long[] d;
        int prev[]; //最短経路の直前の頂点 -1ならnull

        Dijkstra(int s, int n)
        {
            this.s = s;
            this.n = n;
            nodes = new Node[n];
            for (int i = 0; i < n; i++)
                nodes[i] = new Node(i);
            d = new long[n];
            //todo 現状最短経路が複数ある場合に対応できていない
            //todo prev = List<LinkedList>();として複数の直前最短頂点を持とう
            prev = new int[n];
            Arrays.fill(d, initValue);
            Arrays.fill(prev, -1);
            d[s] = 0;
        }

        Dijkstra(int s, int n, int edge, boolean isDirectedGraph)
        {
            this.s = s;
            this.n = n;

            nodes = new Node[n];
            for (int i = 0; i < n; i++)
                nodes[i] = new Node(i);

            d = new long[n];
            prev = new int[n];
            Arrays.fill(d, initValue);
            Arrays.fill(prev, -1);
            d[s] = 0;

            if (isDirectedGraph)
            {
                for (int ei = 0; ei < edge; ei++)
                {
                    int f = sc.nextInt() - 1;
                    int t = sc.nextInt() - 1;
                    long c = 1;
                    addEdge(f, t, c);
                }
            }
            else
            {
                for (int ei = 0; ei < edge; ei++)
                {
                    int f = sc.nextInt() - 1;
                    int t = sc.nextInt() - 1;
                    long c = 1;
                    addEdge(f, t, c);
                    addEdge(t, f, c);
                }
            }
        }

        void addEdge(int f, int t, long c)
        {
            nodes[f].edges.add(new Edge(t, c));
        }

        long[] solve()
        {
            //頂点とそこへの最短距離を持つ
            PriorityQueue<Dis> q = new PriorityQueue<>();
            q.add(new Dis(s, 0));
            while (!q.isEmpty())
            {
                Dis now = q.poll();
                int nowId = now.p;
                long nowC = now.cos;
                for (Edge edge : nodes[nowId].edges)
                {
                    int to = edge.toId;
                    long needsCost = edge.toCost + nowC;
                    if (d[to] == initValue || needsCost < d[to])
                    {
                        d[to] = needsCost;
                        prev[to] = nowId;
                        q.add(new Dis(to, needsCost));
                    }
                }
            }
            return d;
        }

        //O( E ^ 2) 辺が密の時用
        long[] solve2()
        {
            boolean[] used = new boolean[n];
            long[][] cost = new long[n][n];
            Main.fill(cost, initValue);

            for (Node node : nodes)
            {
                for (Edge edge : node.edges)
                {
                    int fromId = node.id;
                    int toId = edge.toId;
                    long toCost = edge.toCost;
                    cost[fromId][toId] = toCost;
                }
            }
            while (true)
            {
                int v = -1;
                //まだ使われていない頂点のうち、距離が最小のものを探す。
                for (int u = 0; u < n; u++)
                    if (!used[u] && (v == -1 || d[u] < d[v])) v = u;
                if (v == -1) break;
                used[v] = true;
                for (int u = 0; u < n; u++)
                {
                    if (d[u] > d[v] + cost[v][u])
                    {
                        d[u] = d[v] + cost[v][u];
                        prev[u] = v;
                    }
                }
            }
            return d;
        }

        List<Integer> getShotestPath(int to)
        {
            List<Integer> path = new LinkedList<>();
            int now = to;
            while (true)
            {
                path.add(now);
                now = prev[now];
                if (now == -1) break;
            }
            Collections.reverse(path);
            return path;
        }

        static class Dis implements Comparable<Dis>
        {
            //現在地点 最短距離
            int p;
            long cos;

            Dis(int p, long cost)
            {
                this.p = p;
                cos = cost;
            }

            public int compareTo(Dis d)
            {
                if (cos != d.cos)
                {
                    if (cos > d.cos) return 1;
                    else if (cos == d.cos) return 0;
                    else return -1;
                }
                else
                {
                    return p - d.p;
                }
            }
        }

