            Node(int id)
            {
                edges = new ArrayList<>();
                this.id = id;
            }
        }

        static class Edge
        {
            int toId;
            long toCost;

            Edge(int id, long cost)
            {
                toId = id;
                toCost = cost;
            }

        }
    }


