import java.util.*;
import java.io.*;


public class Main{

    public static Node[] nodes;
    public static ArrayList<Node> fennecCanColor, snukeCanColor;
    public static boolean[] colored;

    public static void main(String[] args) throws Exception{

        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        int n = Integer.parseInt(in.readLine());

        nodes = new Node[n+1];
        colored = new boolean[n+1];
        fennecCanColor = new ArrayList<Node>();
        snukeCanColor = new ArrayList<Node>();

        for(int i = 1; i <= n; i++){
            nodes[i] = new Node();
            nodes[i].num = i;
        }

        colored[1] = true;
        colored[n] = true;

        for(int i = 1; i < n; i++){
            String[] input = in.readLine().split("\\s+");
            int a = Integer.parseInt(input[0]);
            int b = Integer.parseInt(input[1]);

            nodes[a].adjList.add(nodes[b]);
            nodes[b].adjList.add(nodes[a]);

            nodes[a].canColorSize++;
            nodes[b].canColorSize++;

            if(a == 1 || a == n){
                nodes[b].canColorSize--;
            }

            if(b == 1 || b == n){
                nodes[a].canColorSize--;
            }

            if(a == 1 && b != n){
                fennecCanColor.add(nodes[b]);
            }
            else if(a == n && b != 1){
                snukeCanColor.add(nodes[b]);
            }

            if(b == 1 && a != n){
                fennecCanColor.add(nodes[a]);
            }
            else if(b == n && a != 1){
                snukeCanColor.add(nodes[a]);
            }
        }

        Collections.sort(fennecCanColor);
        Collections.sort(snukeCanColor);

        boolean fennec = true;;

        while(play(fennec)){
            fennec = !fennec;
        }

        if(fennec){
            out.println("Snuke");
        }
        else{
            out.println("Fennec");
        }

        in.close();
        out.close();
    }

    public static boolean play(boolean fennec){
        if(fennec){
            return playFennec();
        }
        return playSnuke();
    }

    public static boolean playFennec(){

        int size = fennecCanColor.size();

        if(size == 0){
            return false;
        }

        boolean canColor = false;

        for(int i = 0; i < size; i++){
            Node tmpNode = fennecCanColor.get(i);
            if(snukeCanColor.contains(tmpNode)){
                //System.out.println("Fennec colors: " + tmpNode.num);
                colored[tmpNode.num] = true;
                fennecCanColor.remove(i);
                snukeCanColor.remove(tmpNode);
                canColor = true;
                addAdjList(tmpNode.num, true);
                break;
            }
        }

        if(!canColor){
            Node tmpNode = fennecCanColor.get(0);
            //System.out.println("Fennec colors: " + fennecCanColor.get(0).num);
            colored[tmpNode.num] = true;
            canColor = true;
            addAdjList(tmpNode.num, true);
            fennecCanColor.remove(0);
        }

        return canColor;
    }

    public static boolean playSnuke(){

        int size = snukeCanColor.size();

        if(size == 0){
            return false;
        }

        boolean canColor = false;

        for(int i = 0; i < size; i++){
            Node tmpNode = snukeCanColor.get(i);
            if(fennecCanColor.contains(tmpNode)){
                //System.out.println("Snuke colors: " + tmpNode.num);
                colored[tmpNode.num] = true;
                snukeCanColor.remove(i);
                fennecCanColor.remove(tmpNode);
                canColor = true;
                addAdjList(tmpNode.num, false);
                break;
            }
        }

        if(!canColor){
            Node tmpNode = snukeCanColor.get(0);
            //System.out.println("Snuke colors: " + snukeCanColor.get(0).num);
            colored[tmpNode.num] = true;
            canColor = true;
            addAdjList(tmpNode.num, false);
            snukeCanColor.remove(0);
        }

        return canColor;
    }

    public static void addAdjList(int num, boolean fennec){
        if(fennec){
            for(Node node : nodes[num].adjList){
                node.canColorSize--;
                if(!colored[node.num]){
                    //System.out.println("\tFennec adds: " + node.num);
                    fennecCanColor.add(node);
                }
            }
        }
        else{
            for(Node node : nodes[num].adjList){
                node.canColorSize--;
                if(!colored[node.num]){
                    //System.out.println("\tSnuke adds: " + node.num);
                    snukeCanColor.add(node);
                }
            }
        }

        Collections.sort(fennecCanColor);
        Collections.sort(snukeCanColor);
    }
}

class Node implements Comparable<Node> {

    public int num;
    public int canColorSize;
    public ArrayList<Node> adjList;

    public Node(){
        adjList = new ArrayList<Node>();
        canColorSize = 0;
    }

    @Override
    public int compareTo(Node n){
        return -1 * Integer.compare(this.canColorSize, n.canColorSize);
    }

}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    Node[] nodes = new Node[N];
    for (int i = 0; i < N; i++) nodes[i] = new Node(i);
    for (int i = 0; i < N - 1; i++) {
      int a = scanner.nextInt() - 1;
      int b = scanner.nextInt() - 1;
      nodes[a].edges.add(nodes[b]);
      nodes[b].edges.add(nodes[a]);
    }

    List<Node> path = findPath(null, nodes[0], nodes[N - 1]);
    Collections.reverse(path);
    Node endBlack = path.get((path.size() - 1) / 2);
    Node endWhite = path.get((path.size() - 1) / 2 + 1);

    int countBlack = count(null, nodes[0], endWhite);
    int countWhite = count(null, nodes[N - 1], endBlack);

    if (countBlack > countWhite) {
      System.out.println("Fennec");
    } else {
      System.out.println("Snuke");
    }
  }

  private static List<Node> findPath(Node from, Node node, Node goal) {
    if (node == goal) {
      List<Node> path = new ArrayList<>();
      path.add(node);
      return path;
    }
    for (Node e : node.edges) {
      if (e != from) {
        List<Node> found = findPath(node, e, goal);
        if (found != null) {
          found.add(node);
          return found;
        }
      }
    }
    return null;
  }

  private static int count(Node from, Node node, Node end) {
    int count = 1;
    for (Node e : node.edges) if (e != from && e != end) count += count(node, e, end);
    return count;
  }

  static class Node {
    final int id;
    List<Node> edges = new ArrayList<>();

    Node(int id) {
      this.id = id;
    }
  }
}

import java.util.*;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int N = scan.nextInt();
        Map<Integer, Set<Integer>> tree = new HashMap<>();
        for (int i : IntStream.range(0, N - 1).toArray()) {
            int a = Integer.parseInt(scan.next());
            int b = Integer.parseInt(scan.next());
            Set<Integer> map = tree.getOrDefault(a, new HashSet<>());
            map.add(b);
            tree.put(a, map);
            map = tree.getOrDefault(b, new HashSet<>());
            map.add(a);
            tree.put(b, map);
        }

        List<Integer> path = dijkstra(tree, N);
        List<Integer> black = new ArrayList<>();
        int blackNum = path.size() / 2 + path.size() % 2;
        for (int i = 0; i < blackNum; i++) {
            black.add(path.get(i));
        }
        int forbidden = path.get(blackNum);
        int blackCount = count(tree, forbidden, N);
        if (path.size() % 2 == 0) {
            if (N < blackCount * 2) {
                System.out.println("Fennec");
            } else {
                System.out.println("Snuke");
            }
        } else {
            if (N < blackCount * 2 + 1) {
                System.out.println("Fennec");
            } else {
                System.out.println("Snuke");
            }
        }
    }

    static List<Integer> dijkstra(Map<Integer, Set<Integer>> tree, int N) {
        LinkedList<List<Integer>> stack = new LinkedList<>();
        stack.add(Collections.singletonList(1));
        List<List<Integer>> ret = new ArrayList<>();
        for (int i : IntStream.range(0, N).toArray()) {
            List<Integer> current = stack.removeFirst();
            int node = current.get(current.size() - 1);
            int previous = current.size() >= 2 ? current.get(current.size() - 2) : -1;
            for (int next : tree.get(node)) {
                if (next == previous) {
                    continue;
                }
                if (next == N) {
                    List<Integer> tmp = new ArrayList<>(current);
                    tmp.add(next);
                    ret.add(tmp);
                }
                List<Integer> tmp = new ArrayList<>(current);
                tmp.add(next);
                stack.add(tmp);
            }
            if (!ret.isEmpty()) {
                return ret.get(0);
            }
        }
        return null;
    }

    static int count(Map<Integer, Set<Integer>> tree, int forbidden, int N) {
        N = N / 2 + 1;
        Set<Integer> ret = new HashSet<>(N);
        ArrayDeque<Integer> deque = new ArrayDeque<>();
        deque.add(1);
        ret.add(1);
        while (!deque.isEmpty()) {
            int next = deque.removeFirst();
            for (Integer tmp : tree.get(next)) {
                if (tmp == forbidden) {
                    continue;
                }
                if(ret.contains(tmp)) {
                    continue;
                }
                ret.add(tmp);
                deque.add(tmp);
            }
            if(ret.size() > N) {
                return ret.size();
            }
        }
        return ret.size();
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
