import java.util.Set;

public class Main {
	public static void main(String args[]) {
		FastScanner scanner = new FastScanner();
		int n=scanner.nextInt();
		int[] a=new int[n-1];
		int[] b=new int[n-1];
		Map<Integer,List<Integer>>map=new HashMap<>();
		for(int i=0;i<n-1;i++){
			a[i]=scanner.nextInt()-1;
			b[i]=scanner.nextInt()-1;
			if (map.containsKey(a[i])) {
				List<Integer>list=new ArrayList<>(map.get(a[i]));
				list.add(b[i]);
				map.put(a[i], list);
			} else {
				List<Integer>list=new ArrayList<>();
				list.add(b[i]);
				map.put(a[i], list);
			}
			if (map.containsKey(b[i])) {
				List<Integer>list=new ArrayList<>(map.get(b[i]));
				list.add(a[i]);
				map.put(b[i], list);
			} else {
				List<Integer>list=new ArrayList<>();
				list.add(a[i]);
				map.put(b[i], list);
			}
		}
		Deque<Integer>que=new ArrayDeque<>();
		que.add(0);
		Set<Integer>checked=new HashSet<>();
		int[] memo=new int[n];
		while(!que.isEmpty()){
			int tar=que.poll();
			checked.add(tar);
			for(int i=0;i<n;i++){
				if(map.get(tar).contains(i)&&!checked.contains(i)){
					que.add(i);
					memo[i]=tar;
				}
			}
		}
		List<Integer>center=new ArrayList<>();
		int pre=memo[n-1];
		center.add(n-1);
		while(true){
			center.add(pre);
			if(pre==0){
				break;
			}
			pre=memo[pre];
		}
		Collections.reverse(center);
		Deque<Integer>queF=new ArrayDeque<>();
		for(int i=0;i<Math.ceil(center.size()/2.0);i++){
			queF.add(center.get(i));
		}

		int cntF=0;
		checked=new HashSet<>();
		while(!queF.isEmpty()){
			int tar=queF.poll();
			checked.add(tar);
			for(int i=0;i<n;i++){
				if(map.get(tar).contains(i)&&!center.contains(i)&&!checked.contains(i)){
					queF.add(i);
				}
			}
			cntF++;
		}
		int cntS=n-cntF;
		System.out.println(cntF>cntS?"Fennec":"Snuke");
	}
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

import java.io.FileNotFoundException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main
{
    private static class Step {
        final Step prev;
        final int pos;

        Step(Step prev, int pos)
        {
            this.prev = prev;
            this.pos = pos;
        }
    }

    private static List<Integer> shortestRoute(int goal, Map<Integer, List<Integer>> nodes)
    {
        LinkedList<Step> queue = new LinkedList<>();
        queue.add(new Step(null, 1));

        while (true) {
            Step step = queue.pop();

            if (step.pos == goal) {
                LinkedList<Integer> route = new LinkedList<>();
                Step cur = step;
                while (true) {
                    route.addFirst(cur.pos);
                    if (cur.prev == null) {
                        return route;
                    }
                    cur = cur.prev;
                }
            }

            for (int next : nodes.get(step.pos)) {
                if (step.prev != null && next == step.prev.pos) {
                    continue;
                }
                queue.add(new Step(step, next));
            }
        }
    }

    private static void dfs(boolean[] vertices, Map<Integer, List<Integer>> nodes, int[] cut)
    {
        LinkedList<Integer> stack = new LinkedList<>();
        stack.add(1);

        while (true) {
            if (stack.isEmpty()) {
                return;
            }

            Integer pos = stack.removeLast();

            for (int next : nodes.get(pos)) {
                if (vertices[next]) {
                    continue;
                }
                if (cut[0] == pos && cut[1] == next
                        || cut[1] == pos && cut[0] == next) {
                    continue;
                }
                vertices[next] = true;
                stack.addLast(next);
            }
        }
    }

    public static void main(String[] args)
    {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        Map<Integer, List<Integer>> nodes = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();

            nodes.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
            nodes.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
        }

        List<Integer> shortestRoute = shortestRoute(n, nodes);

        int conflictPos = (int) Math.ceil(shortestRoute.size() / 2.0);
        int[] cut = new int[] { shortestRoute.get(conflictPos - 1), shortestRoute.get(conflictPos)};

        boolean[] vertices = new boolean[n + 1];
        dfs(vertices, nodes, cut);

        int fennecCells = 0;
        for (boolean b : vertices) {
            if (b) {
                fennecCells++;
            }
        }

        if (fennecCells >= (n - fennecCells)) {
            System.out.println("Fennec");
        }
        else {
            System.out.println("Snuke");
        }
    }
}

