public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<Integer, List<Integer>> graph = new HashMap<>(n);
        for (int i = 1; i <= n; i++) {
            graph.put(i, new ArrayList<>());
        }

        for (int r = 0; r < n - 1; r++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            graph.get(a).add(b);
            graph.get(b).add(a);
        }

        boolean[] claimedCache = new boolean[n + 1];
        Queue<Integer> fennecFringe = new LinkedList<>();
        fennecFringe.add(1);
        int fennecCount = 1;
        Queue<Integer> snukeFringe = new LinkedList<>();
        snukeFringe.add(n);
        int snukeCount = 1;

        while (!fennecFringe.isEmpty() && !snukeFringe.isEmpty()) {
            // Fennec goes first
            Queue<Integer> fennecNextFringe = new LinkedList<>();
            for (Integer f : fennecFringe) {
                if (!claimedCache[f]) {
                    fennecCount++;
                    claimedCache[f] = true;
                    for (Integer neighbor : graph.get(f)) {
                        if (!claimedCache[neighbor]) {
                            fennecNextFringe.add(neighbor);
                        }
                    }
                }
            }
            fennecFringe = fennecNextFringe;

            Queue<Integer> snukeNextFringe = new LinkedList<>();
            for (Integer f : snukeFringe) {
                if (!claimedCache[f]) {
                    snukeCount++;
                    claimedCache[f] = true;
                    for (Integer neighbor : graph.get(f)) {
                        if (!claimedCache[neighbor]) {
                            snukeNextFringe.add(neighbor);
                        }
                    }
                }
            }
            snukeFringe = snukeNextFringe;
        }

        System.out.println(fennecCount > snukeCount ? "Fennec" : "Snuke");
    }
}

import java.util.HashSet;
import java.util.LinkedList;
import java.util.Scanner;

public class Main 
{
	static class Node
	{
		HashSet<Node> e = new HashSet<>();
		int i;
		int dis1 = -1;
		int dis2 = -1;
		boolean census = false;
		int blacksize = 1;

		public Node(int id)
		{
			i=id;
		}
	}

	static int cen(Node n)
	{
//		System.out.println("census " + n.i);
		n.census = true;
		int score = 1;
		for(Node e : n.e)
		{
			if(!e.census)
			{
				e.census = true;
				score += cen(e);
			}
		}
		return score;
	}

	public static void main(String[] args) 
	{
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();

		Node[] nd = new Node[n];

		for(int i = 0; i < n; i++)
		{
			nd[i] = new Node(i);
		}

		for(int i = 0; i < n-1; i++)
		{
			int a = sc.nextInt()-1;
			int b = sc.nextInt()-1;
			nd[a].e.add(nd[b]);
			nd[b].e.add(nd[a]);
		}

		Node s1 = nd[0];
		Node s2 = nd[n-1];
		LinkedList<Node> q = new LinkedList<Node>();
		q.add(s1);
		s1.dis1 = 0;
		while(!q.isEmpty())
		{
			Node pos = q.pollFirst();
			for(Node e : pos.e)
			{
				if(e.dis1 == -1)
				{
					e.dis1 = pos.dis1+1;
					q.add(e);
				}
			}
		}

		q = new LinkedList<Node>();
		q.add(s2);
		s2.dis2 = 0;
		while(!q.isEmpty())
		{
			Node pos = q.pollFirst();
			for(Node e : pos.e)
			{
				if(e.dis2 == -1)
				{
					e.dis2 = pos.dis2+1;
					q.add(e);
				}
			}
		}

		int path = nd[0].dis2;
		Node fb = null;
		for(int i = 0; i < n; i++)
		{ //find frontline black
			Node x = nd[i];
			if(x.dis1 + x.dis2 == path && x.dis1 == path/2)
			{
				fb = x;
				break;
			}
		}

		int blackscore = 1;
		fb.census = true;
//		System.out.println("frontline " + fb.i + ", dis " + fb.dis1 + " " + fb.dis2);
		for(Node e : fb.e)
		{
//			System.out.println(fb.i + " " + e.i);
			if(!(e.dis1 + e.dis2 == path && e.dis2 < fb.dis2))
			{
//				System.out.println("Open census " + e.i + ", dis " + e.dis1 + " " + e.dis2);
				blackscore += cen(e);
			}
		}

		int whitescore = n-blackscore;
//		System.out.println(blackscore + " " + whitescore);
		if(blackscore>whitescore)
			System.out.println("Fennec");
		else System.out.println("Snuke");
	}

}

import java.util.*;
import java.io.*;


public class Main {

    public static Node[] nodes;
    public static ArrayList<Node> fennecCanColor, snukeCanColor;
    public static boolean[] colored;

    public static void main(String[] args) throws Exception{

        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        int n = Integer.parseInt(in.readLine());

        nodes = new Node[n+1];
        colored = new boolean[n+1];
        fennecCanColor = new ArrayList<Node>();
        snukeCanColor = new ArrayList<Node>();

        for(int i = 1; i <= n; i++){
            nodes[i] = new Node();
            nodes[i].num = i;
        }

        for(int i = 1; i < n; i++){
            String[] input = in.readLine().split("\\s+");
            int a = Integer.parseInt(input[0]);
            int b = Integer.parseInt(input[1]);

            nodes[a].adjList.add(nodes[b]);
            nodes[b].adjList.add(nodes[a]);

            nodes[a].canColorSize++;
            nodes[b].canColorSize++;

            if(a == 1 || a == n){
                nodes[b].canColorSize--;
            }

            if(b == 1 || b == n){
                nodes[a].canColorSize--;
            }

            if(a == 1 && b != n){
                fennecCanColor.add(nodes[b]);
            }
            else if(a == n && b != 1){
                snukeCanColor.add(nodes[b]);
            }

            if(b == 1 && a != n){
                fennecCanColor.add(nodes[a]);
            }
            else if(b == n && a != 1){
                snukeCanColor.add(nodes[a]);
            }
        }

        Collections.sort(fennecCanColor);
        Collections.sort(snukeCanColor);

        boolean fennec = true;;

        while(play(fennec)){
            fennec = !fennec;
        }

        if(fennec){
            out.println("Snuke");
        }
        else{
            out.println("Fennec");
        }

        in.close();
        out.close();
    }

    public static boolean play(boolean fennec){
        if(fennec){
            return playFennec();
        }
        return playSnuke();
    }

    public static boolean playFennec(){

        int size = fennecCanColor.size();

        if(size == 0){
            return false;
        }

        boolean canColor = false;

        for(int i = 0; i < size; i++){
            Node tmpNode = fennecCanColor.get(i);
            if(snukeCanColor.contains(tmpNode)){
                //System.out.println("\tFennec colors: " + tmpNode.num);
                fennecCanColor.remove(i);
                snukeCanColor.remove(tmpNode);
                canColor = true;
                addAdjList(tmpNode.num, true);
                break;
            }
        }

        if(!canColor){
            //System.out.println("\tFennec colors: " + fennecCanColor.get(0).num);
            canColor = true;
            addAdjList(fennecCanColor.get(0).num, true);
            fennecCanColor.remove(0);
        }

        return canColor;
    }

    public static boolean playSnuke(){

        int size = snukeCanColor.size();

        if(size == 0){
            return false;
        }

        boolean canColor = false;

        for(int i = 0; i < size; i++){
            Node tmpNode = snukeCanColor.get(i);
            if(fennecCanColor.contains(tmpNode)){
                //System.out.println("\tSnuke colors: " + tmpNode.num);
                snukeCanColor.remove(i);
                fennecCanColor.remove(tmpNode);
                canColor = true;
                addAdjList(tmpNode.num, true);
                break;
            }
        }

        if(!canColor){
            //System.out.println("\tSnuke colors: " + snukeCanColor.get(0).num);
            canColor = true;
            addAdjList(snukeCanColor.get(0).num, true);
            snukeCanColor.remove(0);
        }

        return canColor;
    }

    public static void addAdjList(int num, boolean fennec){
        if(fennec){
            for(Node node : nodes[num].adjList){
                node.canColorSize--;
                if(!colored[node.num]){
                    fennecCanColor.add(node);
                }
            }
        }
        else{
            for(Node node : nodes[num].adjList){
                if(!colored[node.num]){
                    snukeCanColor.add(node);
                }
            }
        }

        Collections.sort(fennecCanColor);
        Collections.sort(snukeCanColor);
    }
}

class Node implements Comparable<Node> {

    public int num;
    public int canColorSize;
    public ArrayList<Node> adjList;

    public Node(){
        adjList = new ArrayList<Node>();
        canColorSize = 0;
    }

    @Override
    public int compareTo(Node n){
        return -1 * Integer.compare(this.canColorSize, n.canColorSize);
    }

}

