class Main{
	public static void main(String[] args) {
		int INF=1000000007;
		Scanner sc=new Scanner(System.in);
		int V=sc.nextInt();
		Vec[] v=new Vec[V+1];
		for(int i=0; i<=V; i++) {
			v[i]=new Vec();
		}
		for(int i=0; i<V-1; i++) {
			int a=sc.nextInt();
			int b=sc.nextInt();
			v[a].add(b);
			v[b].add(a);
		}
		int[] Fe=new int[V+1];
		int[] Su=new int[V+1];
		boolean[] Fe_V=new boolean[V+1];
		boolean[] Su_V=new boolean[V+1];
		Arrays.fill(Fe, INF);
		Arrays.fill(Su, INF);
		Fe[1]=0;
		Su[V]=0;
		Stack<Integer> Q=new Stack<Integer>();
		Q.add(1);
		while(!Q.isEmpty()) {
			int tmp=Q.pop();
			for(int i=0; i<v[tmp].size(); i++) {
				if(!Fe_V[v[tmp].get(i)] && Fe[tmp]+1<Fe[v[tmp].get(i)]) {
					Fe_V[v[tmp].get(i)]=true;
					Fe[v[tmp].get(i)]=Fe[tmp]+1;
					Q.push(v[tmp].get(i));
				}
			}
		}

		Q.add(V);
		while(!Q.isEmpty()) {
			int tmp=Q.pop();
			for(int i=0; i<v[tmp].size(); i++) {
				if(!Su_V[v[tmp].get(i)] && Su[tmp]+1<Su[v[tmp].get(i)]) {
					Su_V[v[tmp].get(i)]=true;
					Su[v[tmp].get(i)]=Su[tmp]+1;
					Q.push(v[tmp].get(i));
				}
			}
		}
		int Su_w=0;
		int Fe_w=0;
		for(int i=1; i<=V; i++) {
			if(Fe[i]<=Su[i]) {
				Fe_w++;
			}
			else {
				Su_w++;
			}
		}
		if(Su_w>=Fe_w) {
			System.out.println("Snuke");
			System.out.flush();
		}
		else {
			System.out.println("Fennec");
			System.out.flush();
		}
	}
	public static class Vec{
		ArrayList <Integer> rinsetu=new ArrayList<Integer>();
		public void add(int V) {
			rinsetu.add(V);
		}
		public void show() {
			for(int i=0; i<rinsetu.size(); i++) {
				System.out.println(rinsetu.get(i));
			}
		}
		public int get(int i) {
			return rinsetu.get(i);
		}
		public int size() {
			return rinsetu.size();
		}
		public int lowerBound(final int value) {
			int low = 0;
			int high = rinsetu.size();
			int mid;
			while (low < high) {
				mid = ((high - low) >>> 1) + low;
				if (rinsetu.get(mid) < value) {
					low = mid + 1;
				} else {
					high = mid;
				}
			}
			if(low<rinsetu.size()) {
				return low;
			}
			else {
				return -1;
			}
		}
	}
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();

        final Map<Integer, List<Integer>> tree = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            final int a = scanner.nextInt();
            final int b = scanner.nextInt();

            tree.computeIfAbsent(a, v -> new ArrayList<>()).add(b);
            tree.computeIfAbsent(b, v -> new ArrayList<>()).add(a);
        }

        final boolean[] isVisited = new boolean[n + 1];
        isVisited[1] = true;
        final Deque<Integer> route = search(tree, isVisited, 1, n);
        route.addFirst(1);

        final Deque<Integer> fennecRoute = new ArrayDeque<>();
        final Deque<Integer> snukeRoute = new ArrayDeque<>();
        while (true) {
            fennecRoute.add(route.pollFirst());
            if (route.isEmpty()) break;
            snukeRoute.add(route.pollLast());
            if (route.isEmpty()) break;
        }

        final boolean[] isAdded = new boolean[n + 1];
        for (final int toVisit : fennecRoute) {
            isAdded[toVisit] = true;
        }
        for (final int toVisit : snukeRoute) {
            isAdded[toVisit] = true;
        }

        while (true) {
            if (fennecRoute.isEmpty()) {
                System.out.println("Snuke");
                return;
            }
            final int fennecCurrent = fennecRoute.pollFirst();
            for (final int fennecNext : tree.get(fennecCurrent)) {
                if (!isAdded[fennecNext]) {
                    fennecRoute.add(fennecNext);
                }
            }

            if (snukeRoute.isEmpty()) {
                System.out.println("Fennec");
                return;
            }
            final int snukeCurrent = snukeRoute.pollFirst();
            for (final int snukeNext : tree.get(snukeCurrent)) {
                if (!isAdded[snukeNext]) {
                    snukeRoute.add(snukeNext);
                }
            }
        }
    }

    private static Deque<Integer> search(final Map<Integer, List<Integer>> tree, final boolean[] isVisited, final int current, final int dest) {
        if (current == dest) {
            final Deque<Integer> route = new ArrayDeque<>();
            route.add(dest);
            return route;
        }

        for (final int next : tree.get(current)) {
            if (!isVisited[next]) {
                isVisited[next] = true;
                final Deque<Integer> route = search(tree, isVisited, next, dest);
                if (!route.isEmpty()) {
                    return route;
                }
            }
        }

        return new ArrayDeque<>();
    }
}

import java.util.*;
public class Main {
    private static int n;
    private static int mid;
    private static Map<Integer, List<Integer>> graph = new HashMap<>();
    private static Map<Integer, Integer> sz = new HashMap<>();
    private static List<Integer> path = new ArrayList<>();

    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            graph.clear();
            sz.clear();
            path.clear();

            n = sc.nextInt();
            for (int i=1; i<n; i++) {
                int u = sc.nextInt();
                int v = sc.nextInt();

                graph.computeIfAbsent(u, ArrayList::new).add(v);
                graph.computeIfAbsent(v, ArrayList::new).add(u);
            }

            dfs(1, -1);

            int sum1 = n - sz.get(mid);
            if (sum1 > sz.get(mid)) {
                System.out.println("Fennec");
            } else {
                System.out.println("Snuke");
            }
        }
    }

    private static void dfs(int x, int parent) {
        path.add(x);
        sz.put(x, 1);

        for(int e: graph.computeIfAbsent(x, ArrayList::new)) {
            if (e == parent) {
                continue;
            }
            dfs(e, x);

            sz.put(x, sz.get(x) + sz.get(e));
        }

        if (x == n) {
            mid = path.get((path.size() + 1) / 2);
        }

        path.remove(path.size()-1);
    }
}

import java.util.*;
import java.io.*;

class Main{
    static int[] num=new int[2];
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int n=fsc.nextInt();
        ArrayList<Integer>[] nodes=new ArrayList[n];
        for(int i=0;i<n;i++) nodes[i]=new ArrayList<>();
        for(int i=0;i<n-1;i++){
            int a=fsc.nextInt()-1, b=fsc.nextInt()-1;
            nodes[a].add(b);
            nodes[b].add(a);
        }
        fsc.close();
        int[] path=bfs(nodes);
        int len=path.length;
        int[] color=new int[n];
        for(int i=0;i<n;i++) color[i]=-1;
        num[0]=0;
        num[1]=0;
        for(int i=0;i<len;i++){
            int c=i<len-len/2?0:1;
            color[path[i]]=c;
            num[c]++;
        }
        for(int i=0;i<len;i++){
            coloring(nodes, color, path[i]);
        }
        if(num[0]>num[1]) System.out.println("Fennec");
        else System.out.println("Snuke");
    }
    static void coloring(ArrayList<Integer>[] nodes, int[] color, int st){
        int c=color[st];
        ArrayDeque<Integer> q=new ArrayDeque<>();
        q.add(st);
        while(q.size()!=0){
            int u=q.removeFirst();
            for(int v:nodes[u]){
                if(color[v]<0){
                    q.addLast(v);
                    color[v]=c;
                    num[c]++;
                }
            }
        }
    }

    static int[] bfs(ArrayList<Integer>[] nodes){
        ArrayDeque<Integer> q=new ArrayDeque<>();
        q.add(0);
        int n=nodes.length;
        int[] d=new int[n];
        int[] prev=new int[n];
        for(int i=0;i<n;i++) d[i]=-1;
        d[0]=0;
        while(q.size()!=0){
            int u=q.removeFirst();
            for(int v:nodes[u]){
                if(d[v]<0){
                    q.addLast(v);
                    d[v]=d[u]+1;
                    prev[v]=u;
                }
            }
        }
        int[] path=new int[d[n-1]+1];
        int now=n-1;
        for(int i=0;i<d[n-1]+1;i++){
            path[d[n-1]-i]=now;
            now=prev[now];
        }
        return path;
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

