		wNeighbor.add(a);
	    } else {
		u.connect(a, b);
	    }
	}

	List<Integer> black = new ArrayList<Integer>();
	List<Integer> white = new ArrayList<Integer>();
	List<Integer> both = new ArrayList<Integer>();
	for(int node: bNeighbor) black.add(u.root(node));
	for(int node: wNeighbor) {
	    int g = u.root(node);
	    if(black.contains(g)) {
		black.remove(Integer.valueOf(g));
		both.add(g);
	    } else {
		white.add(g);
	    }
	}

	int blackCount = 0;
	for(int g: black) blackCount += u.size(g);
	int whiteCount = 0;
	for(int g: white) whiteCount += u.size(g);
	int bothCount = 0;
	for(int g: both) bothCount += u.size(g);

	if(bothCount % 2 != 0) blackCount++;

	System.out.println(blackCount > whiteCount ? "Fennec" : "Snuke");
	scan.close();
    }

    private static class UnionFind {
	private int[] u;

	public UnionFind(int n) {
	    u = new int[n];
	    for (int i = 0; i < n; i++) {
		u[i] = -1;
	    }
	}

	public int size(int a) {
	    return -u[root(a)];
	}

	public int root(int a) {
	    if(u[a] < 0) return a;
	    return u[a] = root(u[a]);
	}

	public boolean connect(int a, int b) {
	    if(root(a) == root(b)) return false;

	    a = root(a);
	    b = root(b);
	    if(u[a] > u[b]) {
		int tmp = a;
		a = b;
		b = tmp;
	    }
	    u[a] += u[b];
	    u[b] = a;
	    return true;
	}
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.solve();
    }
    public void solve() {
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int N = scan.nextInt();
        List<Integer>[] edge = new List[N];
        for (int i = 0; i < N; i++) {
            edge[i] = new ArrayList<>();
        }
        for (int i = 0; i < N-1; i++) {
            int a = scan.nextInt()-1;
            int b = scan.nextInt()-1;
            edge[a].add(b);
            edge[b].add(a);
        }
        int[] black = this.bfs(edge, 0);
        int[] white = this.bfs(edge, N-1);
        HashSet<Integer> used = new HashSet<>();
        PriorityQueue<Pair> blacks = new PriorityQueue<>(new PairComparator());
        blacks.add(new Pair(0, Integer.MAX_VALUE));
        PriorityQueue<Pair> whites = new PriorityQueue<>(new PairComparator());
        whites.add(new Pair(N-1, Integer.MAX_VALUE));
        for (int i = 0; i < N; i++) {
            PriorityQueue<Pair> queue = blacks;
            int[] point = white;
            String winner = "Snuke";
            if (i % 2 != 0) {
                queue = whites;
                point = black;
                winner = "Fennec";
            }
            boolean done = false;
            while(!queue.isEmpty()) {
                Pair p = queue.poll();
                if (used.contains(p.index)) {
                    continue;
                }
                used.add(p.index);
                done = true;
                for (int next : edge[p.index]) {
                    if (used.contains(next)) {
                        continue;
                    }
                    queue.add(new Pair(next, point[next]));
                }
                break;
            }
            if (!done) {
                System.out.println(winner);
                return;
            }
        }
    }
    private int[] bfs(List<Integer>[] edge, int start) {
        Queue<Integer> queue = new LinkedList<>();
        queue.add(start);
        int[] distance = new int[edge.length];
        Arrays.fill(distance, Integer.MAX_VALUE);
        distance[start] = 0;
        while(!queue.isEmpty()) {
            int current = queue.poll();
            for (int next : edge[current]) {
                if (distance[current] + 1 < distance[next]) {
                    distance[next] = distance[current] + 1;
                    queue.add(next);
                }
            }
        }
        return distance;
    }
    class Pair {
        int index;
        int value;
        Pair(int index, int value) {
            this.index = index;
            this.value = value;
        }
    }
    class PairComparator implements Comparator<Pair> {
        @Override
        public int compare(Pair o1, Pair o2) {
            if (o1.value != o2.value) {
                return Integer.compare(o1.value, o2.value);
            }
            return Integer.compare(o1.index, o2.index);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Set;

public class Main {
	public static void main(String args[]) {
		FastScanner scanner = new FastScanner();
		int n=scanner.nextInt();
		Map<Integer,Set<Integer>>map=new HashMap<>();
		for(int i=0;i<n-1;i++){
			int a=scanner.nextInt()-1;
			int b=scanner.nextInt()-1;
			if (map.containsKey(a)) {
				map.get(a).add(b);
			} else {
				Set<Integer>set=new HashSet<>();
				set.add(b);
				map.put(a, set);
			}
			if (map.containsKey(b)) {
				map.get(b).add(a);
			} else {
				Set<Integer>set=new HashSet<>();
				set.add(a);
				map.put(b, set);
			}
		}
		Deque<Integer>que=new ArrayDeque<>();
		que.add(0);
		Set<Integer>checked=new HashSet<>();
		int[] memo=new int[n];
		while(!que.isEmpty()){
			int tar=que.poll();
			checked.add(tar);
			for(int i:map.get(tar)){
				if(!checked.contains(i)){
					que.add(i);
					memo[i]=tar;
				}
			}
		}
		List<Integer>center=new ArrayList<>();
		int pre=memo[n-1];
		center.add(n-1);
		while(true){
			center.add(pre);
			if(pre==0){
				break;
			}
			pre=memo[pre];
		}
		Deque<Integer>queS=new ArrayDeque<>();
		for(int i=0;i<center.size()/2;i++){
			queS.add(center.get(i));
		}
		int cntS=0;
		checked=new HashSet<>(center);
		while(!queS.isEmpty()){
			int tar=queS.poll();
			checked.add(tar);
			for(int i:map.get(tar)){
				if(!checked.contains(i)){
					queS.add(i);
				}
			}
			cntS++;
		}
		int cntF=n-cntS;
		System.out.println(cntS<cntF?"Fennec":"Snuke");
	}
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

