import java.io.*;
import java.util.*;

public class Main {

  static FastScanner sc = new FastScanner();
  static Output out = new Output(System.out);

  static final int[] dx = {0, 1, 0, -1};
  static final int[] dy = {-1, 0, 1, 0};

  static final long MOD = (long) (1e9 + 7);
  static final long INF = Long.MAX_VALUE / 2;

  static final int e5 = (int) 1e5;

  public static class Solver {
    public Solver() {

      int N = sc.nextInt();

      Tree tree = new Tree();
      tree.read(N, false, 0, 0);

      int count = tree.dfs(tree.nodes[N-1].par((tree.nodes[N-1].rank-1) / 2));

      out.println(count >= N-count ? "Snuke" : "Fennec");
    }

    public class Tree {

      Node[] nodes;
      long initCost;
      int root;
      int V;

      /*
       * N: 頂点の数
       * M: 辺の数
       * hasCost: 辺にコストがあるか
       * initCost: 頂点の初期コスト
       * root: 根の番号
       */
      public void read(int N, boolean hasCost, long initCost, int root) {
        this.initCost = initCost;
        this.root = root;
        V = N;

        nodes = new Node[N];
        for (int i=0; i<N; i++) {
          nodes[i] = new Node(i, initCost);
        }

        for (int i=0; i<V-1; i++) {
          int from = sc.nextInt()-1;
          int to = sc.nextInt()-1;
          long cost = (hasCost ? sc.nextLong() : 1);
          Edge e = new Edge(from, to, cost);
          nodes[from].edges.add(e);
          e = new Edge(to, from, cost);
          nodes[to].edges.add(e);
        }

        setParent(root, root);

      }

      private void setParent(int i, int par) {
        nodes[i].par = par;
        Iterator<Edge> itr = nodes[i].edges.iterator();
        while (itr.hasNext()) {
          Edge e = itr.next();
          if (e.to == par) {
            itr.remove();
          }
          else {
            e.to().rank = nodes[i].rank+1;
            setParent(e.to, i);
          }
        }
      }

      public int[][] tour() {
        int[] tour = new int[2*V-1];
        tour(tour, 0, root);

        int[] start = new int[V];
        int[] end = new int[V];
        Arrays.fill(start, -1);
        for (int i=0; i<2*V-1; i++) {
          if (start[tour[i]] == -1) start[tour[i]] = i;
          end[tour[i]] = i;
        }

        return new int[][] {tour, start, end};
      }

      private int tour(int[] tour, int p, int s) {

        tour[p++] = s;

        for (Edge e: nodes[s].edges) {
          p = tour(tour, p, e.to);
          tour[p++] = s;
        }

        return p;

      }

      public int dfs(Node from) {

        int res = 1;

        for (Edge e: from.edges) {

          res += dfs(e.to());

        }

        return res;
      }

      public class Node {
        int id;
        int par;
        long cost;
        LinkedList<Edge> edges;
        boolean done;
        int rank;

        public Node(int id, long cost) {
          this.id = id;
          this.cost = cost;
          par= -1;
          edges = new LinkedList<Edge>();
          rank = 0;
          done = false;
        }

        public boolean isRoot() {
          return par == id;
        }

        public boolean isLeaf() {
          return edges.size() == 0;
        }

        public Node par() {
          return nodes[par];
        }

        public Node par(int k) {
          if (k == 0) return this;
          else return par().par(k-1);
        }

      }

      public class Edge {
        int from, to;
        long cost;
        public Edge(int from, int to, long cost) {
          this.from = from;
          this.to = to;
          this.cost = cost;
        }
        public Node from() {
          return nodes[from];
        }
        public Node to() {
          return nodes[to];
        }
      }

    }

  }

  public static void main(String[] args) {
    new Solver();
    out.flush();
  }

