class Main {

    static PrintWriter out;
    static InputReader sc;

    static final int MOD = (int) 1e9 + 7;

    static int N;
    static List<List<Integer>> graph;

    public static void main(String[] args) {
        sc = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    static void solve() {
        N = sc.nextInt();
        graph = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            graph.add(new ArrayList<Integer>());
        }
        for (int i = 0; i < N - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            graph.get(a).add(b);
            graph.get(b).add(a);
        }
        int[] arrf = bfs(0);
        int[] arrs = bfs(N - 1);
        int cntf = 0;
        int cnts = 0;
        for (int i = 0; i < N; i++) {
            if (arrf[i] <= arrs[i]) {
                cntf++;
            } else {
                cnts++;
            }
        }
        out.println(cntf > cnts ? "Fennec" : "Sunuke");
    }

    static int[] bfs(int s) {
        int[] d = new int[N];
        Arrays.fill(d, -1);
        Queue<Integer> que = new ArrayDeque<>();
        d[s] = 0;
        que.add(s);
        while (!que.isEmpty()) {
            int v = que.poll();
            for (int u : graph.get(v)) {
                if (d[u] == -1) {
                    d[u] = d[v] + 1;
                    que.add(u);
                }
            }
        }
        return d;
    }

