		while(queue.size() != 0){
			int v = queue.poll();
			if(v == N-1) break;
			for(int next : G.get(v)){
				if(num[next] > num[v] + 1){
					num[next] = num[v] + 1;
					from[next] = v;
					queue.add(next);
				}
			}
		}

		boolean[] visited = new boolean[N];
		int now = N-1;
		for(int i = 0; now != -1; i++){
