class FastScanner {
    private InputStream in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    public FastScanner(InputStream in) {
		this.in = in;
	}
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() {
    	if (hasNextByte()) return buffer[ptr++];
    	else return -1;
    }
    private static boolean isPrintableChar(int c){
    	return 33 <= c && c <= 126;
    }
    public boolean hasNext() {
    	while(hasNextByte() && !isPrintableChar(buffer[ptr]))
    		ptr++; return hasNextByte();
    }
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public String nextLine() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(b != 10) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() {
    	return Double.parseDouble(next());
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    int n;
    ArrayList<ArrayList<Edge>> es;
    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    void read() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        es = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            es.add(new ArrayList<>());
        }
        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            es.get(a).add(new Edge(a, b));
            es.get(b).add(new Edge(b, a));
        }
    }

    void solve() {
        UnionFind uf = new UnionFind(n);
        int sScore = 0, fScore = 0;
        ArrayList<Integer> path = getPath();
        int mid = (path.size() - 1) / 2;
        int midFrom = path.get(mid);
        int midTo = path.get(mid+1);
        for (int i = 0; i < n; i++) {
            ArrayList<Edge> ess = es.get(i);
            for (int j = 0; j < ess.size(); j++) {
                int next = ess.get(j).to;
                if ((i == midFrom && next == midTo) ||
                        (i == midTo && next == midFrom))
                    continue;
                uf.unite(i, next);
            }
        }
        for (int i = 0; i < n; i++) {
            if (uf.hasSamePar(0, i))
                fScore++;
            else
                sScore++;
        }
        if (fScore > sScore)
            System.out.println("Fennec");
        else
            System.out.println("Snuke");
    }

    ArrayList<Integer> getPath() {
        int[] log = new int[n];
        int[] prev = new int[n];
        Arrays.fill(log, Integer.MAX_VALUE);
        PriorityQueue<Node> queue =
                new PriorityQueue<>((n1, n2) -> Integer.compare(n2.rank, n1.rank));
        log[0] = 0;
        Arrays.fill(prev, -1);
        prev[0] = 0;
        for (Edge e: es.get(0)) {
            queue.add(new Node(e.to, 1));
            prev[e.to] = 0;
        }
        while (!queue.isEmpty()) {
            Node n = queue.poll();
            if (n.rank > log[n.id])
                continue;
            log[n.id] = n.rank;
            for (Edge e: es.get(n.id)) {
                if (log[e.to] > log[n.id] + 1) {
                    prev[e.to] = n.id;
                    queue.add(new Node(e.to, log[n.id] + 1));
                }
            }
        }
        ArrayList<Integer> path = new ArrayList<>(n-1);
        int current = n - 1;
        while (current != 0) {
            path.add(0, current);
            current = prev[current];
        }
        path.add(0, 0);
        return path;
    }

    private class Edge {
        int from, to;
        Edge(int f, int t) {
            from = f;
            to = t;
        }
    }

    private class Node {
        int id;
        int rank;
        Node(int id, int rank) {
            this.id = id;
            this.rank = rank;
        }
    }

    private class UnionFind {
        int[] parent;
        UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int getRoot(int x) {
            if (x == parent[x])
                return x;
            return parent[x] = getRoot(parent[x]);
        }

        boolean hasSamePar(int x, int y) {
            return getRoot(x) == getRoot(y);
        }

        void unite(int x, int y) {
            int px = getRoot(x);
            int py = getRoot(y);
            if (px == py)
                return;
            parent[py] = px;
        }
    }
}

