	void solve() throws Exception{
		int N = sc.nextInt();
		ArrayList<ArrayList<Integer>> G = new ArrayList<>();
		for(int i = 0; i < N; i++) G.add(new ArrayList<>());
		for(int i = 0; i < N-1; i++){
			int s = sc.nextInt()-1;
			int t = sc.nextInt()-1;
			G.get(s).add(t);
			G.get(t).add(s);
		}

		int[] num = new int[N];
		Arrays.fill(num, Integer.MAX_VALUE / 2);
		int[] from = new int[N];
		Arrays.fill(from, -1);
		Queue<Integer> queue = new ArrayDeque<Integer>();
		queue.add(0);
		num[0] = 0;

		while(queue.size() != 0){
			int v = queue.poll();
			if(v == N-1) break;
			for(int next : G.get(v)){
				if(num[next] > num[v] + 1){
					num[next] = num[v] + 1;
					from[next] = v;
					queue.add(next);
				}
			}
		}

		boolean[] visited = new boolean[N];
		int now = N-1;
		while(now != -1){
			visited[now] = true;
			now = from[now];
		}

		int[] numFS = new int[2];
		if(num[N-1] % 2 == 0) numFS[0]++;
		Queue<List<Integer>> queueAns = new ArrayDeque<>();
		queueAns.add(Arrays.asList(0, 0));
		queueAns.add(Arrays.asList(1, N-1));

