			for(int next : G.get(v)){
				if(!visited[next]){
					visited[next] = true;
					numFS[isFennec]++;
					queueAns.add(Arrays.asList(isFennec, next));
				}
			}
		}

		System.out.println((numFS[0] > numFS[1]) ? "Fennec" : "Snuke");
	}

