using System;

class D
{
    static int N;
    static List<int>[] e;
    static void Main()
    {
        N = int.Parse(Console.ReadLine());
        e = new List<int>[N];

        for (int i = 0; i < N; i++) e[i] = new List<int>();
        for (long i = 0; i < N - 1; i++)
        {
            var XY = Console.ReadLine().Split(' ').Select(x => int.Parse(x) - 1);
            e[XY.ElementAt(0)].Add(XY.ElementAt(1));
            e[XY.ElementAt(1)].Add(XY.ElementAt(0));
        }

        var Black = DFS(0);
        var White = DFS(N - 1);

        var b = 0;
        for (int i = 0; i < N; i++)
        {
            if (Black[i] <= White[i]) b++;
        }

        Console.WriteLine(b > N - b ? "Fennec" : "Snuke");
    }

    static int[] DFS(int root)
    {
        var s = new Stack<int>();
        var v = new bool[N];
        var d = new int[N];
        s.Push(root);
        v[root] = true;
        while (s.Count > 0)
        {
            var current = s.Pop();
            foreach (var next in e[current])
            {
                if (!v[next])
                {
                    s.Push(next);
                    v[next] = true;
                    d[next] = d[current] + 1;
                }
            }
        }
        return d;
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
