namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			Scanner cin = new Scanner();
			int n = cin.Int();
			List<int>[] to = new List<int>[n];
			for (int i = 0; i < n; i++) {
				to[i] = new List<int>();
			}

			for (int i = 0; i < n - 1; i++) {
				int a = cin.Int() - 1;
				int b = cin.Int() - 1;
				to[a].Add(b);
				to[b].Add(a);
			}

			var bq = new Queue<int>();
			bq.Enqueue(0);
			var wq = new Queue<int>();
			wq.Enqueue(n - 1);

			var colors = new int[n];
			colors[0] = -1;
			colors[n - 1] = 1;
			while (bq.Count() > 0 || wq.Count() > 0) {
				var bb = bq.ToArray();
				bq.Clear();
				foreach (int b in bb) {
					foreach (int nextB in to[b]) {
						if (colors[nextB] == 0) {
							colors[nextB] = -1;
							bq.Enqueue(nextB);
						}
					}
				}

				var ww = wq.ToArray();
				wq.Clear();
				foreach (int w in ww) {
					foreach (int nextW in to[w]) {
						if (colors[nextW] == 0) {
							colors[nextW] = 1;
							wq.Enqueue(nextW);
						}
					}
				}
			}

			int wc = 0;
			int bc = 0;
			for (int i = 0; i < n; i++) {
				if (colors[i] == 1) {
					++wc;
				} else {
					++bc;
				}
			}

			if (bc > wc) {
				Console.WriteLine("Fennec");
			} else {
				Console.WriteLine("Snuke");
			}
		}
	}

	public class Scanner
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private string[] buf_;
		private int index_;

		public Scanner()
		{
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = Console.ReadLine();
			while (st == "") {
				st = Console.ReadLine();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}
	}
