    struct VertexAndStep
    {
        public readonly int vertex;
        public readonly int step;

        public VertexAndStep(int v, int s)
        {
            this.vertex = v;
            this.step = s;
        }
    }

    /// <summary>
    /// 無方向グラフを隣接リストで扱う
    /// </summary>
    class AdjacencyListUndirectedGraph
    {
        class Node
        {
            public int V { get; }
            private HashSet<int> nexts = new HashSet<int>();

            public Node(int v)
            {
                this.V = v;
            }

            public bool HasNext(int v)
            {
                return this.nexts.Contains(v);
            }
            public bool AddNext(int v)
            {
                if (v == this.V) throw new ArgumentException();
                return this.nexts.Add(v);
            }
            public IReadOnlyCollection<int> AllNexts()
            {
                return this.nexts;
            }
            public bool RemoveNext(int v)
            {
                return this.nexts.Remove(v);
            }
        }

        private readonly IReadOnlyDictionary<int, Node> nodeDic;

        public int VertexCount { get; }

        public AdjacencyListUndirectedGraph(int vertexCount, IEnumerable<Tuple<int, int>> edges)
        {
            if (vertexCount < 0) throw new ArgumentOutOfRangeException(nameof(vertexCount));
            this.VertexCount = vertexCount;

            this.nodeDic = Enumerable.Range(1, vertexCount).ToDictionary(v => v, v => new Node(v));

            foreach (var edge in edges)
            {
                this.AddEdge(edge.Item1, edge.Item2);
            }
        }
        public AdjacencyListUndirectedGraph(int vertexCount, IEnumerable<int[]> edges)
        {
            if (vertexCount < 0) throw new ArgumentOutOfRangeException(nameof(vertexCount));
            this.VertexCount = vertexCount;

            this.nodeDic = Enumerable.Range(1, vertexCount).ToDictionary(v => v, v => new Node(v));

            foreach (var edge in edges)
            {
                if (edge.Length != 2) throw new ArgumentException("invalid edge length " + edge.Length);
                this.AddEdge(edge[0], edge[1]);
            }
        }

        public bool AddEdge(int v1, int v2)
        {
            if (!this.nodeDic[v1].AddNext(v2)) return false;
            if (!this.nodeDic[v2].AddNext(v1))
            {
                throw new InvalidProgramException("invalid state " + v1 + "," + v2);
            }
            return true;
        }
        /// <summary>
        /// すべての点をとおるパスを深さ優先で列挙する
        /// </summary>
        /// <param name="start"></param>
        /// <returns></returns>
        public IEnumerable<int[]> EnumeratePathesDFS(int start)
        {
            return enumeratePathes(start, new int[] { });
        }
        private IEnumerable<int[]> enumeratePathes(int v, int[] accessed)
        {
            accessed = accessed.Concat(new[] { v }).ToArray();
            if (accessed.Length == this.VertexCount)
            {
                yield return accessed;
                yield break;
            }

            var nexts = this.nodeDic[v].AllNexts();

            foreach (var node in nexts)
            {
                if (accessed.Contains(node)) continue;

                foreach (var path in enumeratePathes(node, accessed))
                {
                    yield return path;
                }
            }
        }

        /// <summary>
        /// 指定した始点からの到達点を幅優先で列挙する
        /// </summary>
        /// <param name="start"></param>
        /// <returns></returns>
        public IEnumerable<VertexAndStep> EnumerateVertexesBFS(int start)
        {
            var queue = new Queue<VertexAndStep>();
            queue.Enqueue(new VertexAndStep(start, 0));

            var accessed = new HashSet<int>();

            while(queue.Any())
            {
                var item = queue.Dequeue();
                accessed.Add(item.vertex);
                yield return item;

                var node = this.nodeDic[item.vertex];

                foreach (var next in node.AllNexts())
                {
                    if (accessed.Contains(next)) continue;
                    //if (queue.Any(q => q.vertex == next)) continue;

                    queue.Enqueue(new VertexAndStep(next, item.step + 1));
                }
            }

        }

        public bool HasEdge(int v1, int v2)
        {
            return this.nodeDic[v1].HasNext(v2);
        }


        /// <summary>
        /// グラフが連結かどうかを深さ優先で調べる
        /// </summary>
        /// <returns></returns>
        public bool IsConnectedDFS()
        {
            return isConnectedDfs(1, new HashSet<int>());
        }

        private bool isConnectedDfs(int v, HashSet<int> accessed)
        {
            accessed.Add(v);
            if (accessed.Count == this.VertexCount) return true;

            foreach (var node in this.nodeDic[v].AllNexts())
            {
                if (accessed.Contains(node)) continue;

                if (isConnectedDfs(node, accessed)) return true;
            }
            return false;
        }

        public bool RemoveEdge(int v1, int v2)
        {
            if (this.nodeDic[v1].RemoveNext(v2))
            {
                if (!this.nodeDic[v2].RemoveNext(v1))
                {
                    throw new InvalidProgramException("invalid state " + v1 + "," + v2);
                }
                return true;
            }
            return false;
        }
    }

