    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var status = new Status[N];
            var graph = new GraphBuilder(N, consoleReader.Repeat(N - 1).Select(cr => cr.Split.Int0)).ToArray();
            var nextF = new List<int> { 0 };
            var nextS = new List<int> { N - 1 };
            while (nextF.Count > 0 || nextS.Count > 0)
            {
                var tmp = new List<int>();
                foreach (var current in nextF)
                {
                    if (status[current] != Status.None) continue;
                    status[current] = Status.Fennec;
                    foreach (var to in graph[current])
                        tmp.Add(to);
                }
                nextF = tmp;

                tmp = new List<int>();
                foreach (var current in nextS)
                {
                    if (status[current] != Status.None) continue;
                    status[current] = Status.Snuke;
                    foreach (var to in graph[current])
                        tmp.Add(to);
                }
                nextS = tmp;
            }
            var grouped = status.GroupCount();
            if (grouped[Status.Fennec] < grouped[Status.Snuke])
                return "Snuke";
            return "Fennec";
        }
        enum Status
        {
            None,
            Fennec,
            Snuke
        }
        class GraphBuilder
        {
            public List<int>[] lists;
            public GraphBuilder(int count)
            {
                this.lists = new List<int>[count];
                for (int i = 0; i < count; i++)
                    this.lists[i] = new List<int>();
            }
            public GraphBuilder(int count, IEnumerable<int[]> arrays) : this(count)
            {
                foreach (var item in arrays)
                    this.Add(item[0], item[1]);
            }
            public void Add(int from, int to)
            {
                this.lists[from].Add(to);
                this.lists[to].Add(from); // 有向の場合は消す
            }
            public int[][] ToArray()
            {
                var N = this.lists.Length;
                var res = new int[N][];
                for (int i = 0; i < N; i++)
                    res[i] = this.lists[i].ToArray();
                return res;
            }
        }


