				var すぬけくんの進める箇所 = new List<int>();

				var フェネックの今回の選択 = new List<int>();
				var すぬけくんの今回の選択 = new List<int>();

				フェネックとすぬけくんが隣接した = false;

				for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
				{
					マスの色の情報[マスの番号] = マスの色.透明;
				}
				マスの色の情報[フェネックの最初のマス] = マスの色.黒;
				マスの色の情報[すぬけくんの最初のマス] = マスの色.白;

				進めるマスを更新する(フェネックの進める箇所, フェネックの最初のマス, マスの色.黒);
				進めるマスを更新する(すぬけくんの進める箇所, すぬけくんの最初のマス, マスの色.白);

				for (var ターン = 0; ターン < 最大ターン数; ターン++)
				{
					// 先行はフェネック
					bool フェネックが移動していない = true;

					if (フェネックの進める箇所.Count > 1)
					{
						var 次の移動候補で一番優先したいところ = ターン < フェネックの定跡本.Count ? フェネックの定跡本[ターン] : 乱数.Next(0, フェネックの進める箇所.Count);
						var 保存領域 = フェネックの進める箇所[0];
						フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番優先したいところ];
						フェネックの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
					}
					for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
					{
						var 移動候補 = フェネックの進める箇所[移動候補の番号];
						if (マスの色の情報[移動候補] == マスの色.透明)
						{
							フェネックの今回の選択.Add(移動候補の番号);
							マスの色の情報[移動候補] = マスの色.黒;
							進めるマスを更新する(フェネックの進める箇所, 移動候補, マスの色.黒);
							フェネックが移動していない = false;
							break;
						}
						フェネックの進める箇所.RemoveAt(移動候補の番号);
						移動候補の番号--;
					}

					if (フェネックが移動していない)
					{
						if (生き延びた最大ターン < ターン)
						{
							只今の勝者 = プレイヤー.すぬけくん;
							生き延びた最大ターン = ターン;
						}
						if (すぬけくんの生き延びた最大ターン < ターン)
						{
							すぬけくんの生き延びた最大ターン = ターン;
							フェネックの定跡本.Clear();
							すぬけくんの定跡本 = すぬけくんの今回の選択;
						}
						break;
					}

					bool すぬけくんが移動していない = true;
					if (すぬけくんの進める箇所.Count > 1)
					{
						var 次の移動候補で一番優先したいところ = ターン < すぬけくんの定跡本.Count ? すぬけくんの定跡本[ターン] : 乱数.Next(0, すぬけくんの進める箇所.Count);
						var 保存領域 = すぬけくんの進める箇所[0];
						すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番優先したいところ];
						すぬけくんの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
					}
					for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
					{
						var 移動候補 = すぬけくんの進める箇所[移動候補の番号];
						if (マスの色の情報[移動候補] == マスの色.透明)
						{
							すぬけくんの今回の選択.Add(移動候補の番号);
							マスの色の情報[移動候補] = マスの色.白;
							進めるマスを更新する(すぬけくんの進める箇所, 移動候補, マスの色.白);
							すぬけくんが移動していない = false;
							break;
						}
						すぬけくんの進める箇所.RemoveAt(移動候補の番号);
						移動候補の番号--;
					}

					if (すぬけくんが移動していない)
					{
						if (生き延びた最大ターン < ターン)
						{
							只今の勝者 = プレイヤー.フェネック;
							生き延びた最大ターン = ターン;
						}
						if (フェネックの生き延びた最大ターン < ターン)
						{
							フェネックの生き延びた最大ターン = ターン;
							フェネックの定跡本 = フェネックの今回の選択;
							すぬけくんの定跡本.Clear();
						}
						break;
					}

					// 進める箇所がいっぱいあったらコールド勝ち
					// 隣接してたら最後まで続ける
					if (コールド勝ちのルールが有る && コールド勝ちに必要なターン < ターン && !フェネックとすぬけくんが隣接した)
					{
						if (フェネックの進める箇所.Count > すぬけくんの進める箇所.Count)
						{
							if (フェネックの進める箇所.Count > コールド勝ちに必要なマスの数)
							{
								只今の勝者 = プレイヤー.フェネック;
								break;
							}
						}
						else
						{
							if (すぬけくんの進める箇所.Count > コールド勝ちに必要なマスの数)
							{
								只今の勝者 = プレイヤー.すぬけくん;
								break;
							}
						}
					}
				}
			};

			for (var 世代 = 0; 世代 < 繰り返す数; 世代++)
			{
				シミュレート();
			}

			Console.WriteLine(只今の勝者 == プレイヤー.フェネック ? フェネックの名前 : すぬけくんの名前);
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

public static partial class Program
{
    public static void Main()
    {
        var n = CRL().ToInt();
        var graph = new bool[n, n];
        for (int i = 0; i < n - 1; i++)
        {
            var p = CRL().ArrayInts();
            graph[p[0] - 1, p[1] - 1] = true;
            graph[p[1] - 1, p[0] - 1] = true;
        }

        var snuke = new int[n][];
        var fennec = new int[n][];
        for (int i = 0; i < n; i++)
        {
            snuke[i] = new int[n];
            fennec[i] = new int[n];
            for (int j = 0; j < n; j++)
            {
                snuke[i][j] = int.MaxValue;
                fennec[i][j] = int.MaxValue;
            }
        }

        var queue = new Queue<int>();

        //snuke
        snuke[0][0] = 0;
        var vSnu = new bool[n];
        vSnu[0] = true;
        for (int i = 0; i < n; i++)
        {
            if (graph[0, i])
            {
                vSnu[i] = true;
                snuke[0][i] = 1;
                queue.Enqueue(i);
            }
        }

        var nsunuke = 1;
        while (queue.Count != 0)
        {
            var q = queue.Dequeue();
            for (int i = 0; i < n; i++)
            {
                if (graph[q, i] && vSnu[i] == false)
                {
                    vSnu[i] = true;
                    snuke[q][i] = Math.Min(snuke[q][i], nsunuke);
                    queue.Enqueue(i);
                }
            }

            nsunuke++;
        }

        //fennec
        fennec[n - 1][n - 1] = 0;
        var vFen = new bool[n];
        vFen[n - 1] = true;
        for (int i = 0; i < n; i++)
        {
            if (graph[n - 1, i])
            {
                vSnu[i] = true;
                snuke[n - 1][i] = 1;
                queue.Enqueue(i);
            }
        }

        var nfennec = 1;
        while (queue.Count != 0)
        {
            var q = queue.Dequeue();
            for (int i = 0; i < n; i++)
            {
                if (graph[q, i] && vFen[i] == false)
                {
                    vFen[i] = true;
                    fennec[q][i] = Math.Min(fennec[q][i], nfennec);
                    queue.Enqueue(i);
                }
            }

            nfennec++;
        }

        var cnt = 0;
        for (int i = 0; i < n; i++)
        {
            if (snuke[i].Min() <= fennec[i].Min())
            {
                cnt++;
            }
            else
            {
                cnt--;
            }
        }

        if (cnt > 0)
        {
            CWL("Fennec");
        }
        else
        {
            CWL("Snuke");
        }
    }
}

