using System;
using System.Collections.Generic;
using System.Linq;

namespace ProgramingStudying2
{
    class Program
    {
        static int n;
        static List<List<int>> G;

        static void Main(string[] args)
        {
            n = int.Parse(Console.ReadLine());

            G = new List<List<int>>();

            for (int i = 0; i < n; i++) 
            {
                G.Add(new List<int>());
            }

            for(int i = 0; i < n - 1; i++)
            {
                var ab = Console.ReadLine().Split().Select(int.Parse).ToArray();
                var a = ab[0] - 1;
                var b = ab[1] - 1;

                G[a].Add(b);
                G[b].Add(a);
            }

            //各ノードの色
            var colors = Enumerable.Repeat(-1, n).ToArray();
            colors[0] = 0;
            colors[1] = 1;

            //BFS回すためのキュー
            var que = new Queue<(int, int)>();
            que.Enqueue((0, 1));
            que.Enqueue((n - 1, 0));

            //BFS
            while (que.Any())
            {
                var (x, color) = que.Dequeue();
                foreach(var nx in G[x])
                {
                    if(colors[nx] == -1)
                    {
                        colors[nx] = color;
                        que.Enqueue((nx, color));
                    }
                }
            }

            //黒白マスの個数をカウント
            var black = colors.Sum();
            var white = n - black;

            /*
            Console.WriteLine(black);
            Console.WriteLine(white);
            */

            Console.WriteLine(black >= white ? "Fennec" : "Snuke");
        }
    }
}

