    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Fennec" : "Snuke"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var gb = new GraphBuilder(N, cr, N - 1, false);
        var tr1 = gb.ToTree(N - 1);
        var fennec = 0;
        for (int i = 0; i < tr1[0].depth / 2; i++)
            fennec = tr1[fennec].root;
        var snuke = tr1[fennec].root;
        tree = gb.ToTree(fennec);

        var sSize = Size(snuke);
        var fSize = N - sSize;
        return fSize > sSize;
    }
    int Size(int v)
