public class MainApp
{
    static public string route_from_Fenec = "";

    static public void Main(string[] args)
    {
        int n = int.Parse(Console.ReadLine());
        string[] route = new string[n + 1];

        for (int i = 0; i < n - 1; i++)
        {
            string x = Console.ReadLine();
            string[] split = x.Split(' ');
            int from = int.Parse(split[0]);
            int to = int.Parse(split[1]);
            if (route[from] == null)
            {
                route[from] = to.ToString();
            }
            else
            {
                route[from] += "," + to; 
            }
            if (route[to] == null)
            {
                route[to] = from.ToString();
            }
            else
                route[to] += "," + from;

        }

        int[] fennec_ashiato = new int[n + 1];
        int[] check = new int[n+1];
        check[1] = 1;
        tansaku first = new tansaku();
        first.road = "1";
        first.check = check;
        first.route = route;
        first.ima = 1;
        first.goal = n;
        stacking_tansaku.Add(first);
        aitemadebridge();
        while (stacking_tansaku.Count != 0)
        {
            int[] temp = stacking_tansaku[0].road.Split(' ').Select(int.Parse).ToArray();
            if (incheck(temp, n) == 1)
            {
                fennec_ashiato[stacking_tansaku[0].ima]=1;
            }
            aitemadebridge();


        }
        ;
        int dochiranomonodemonai = route_from_Fenec.Split(' ').Length - 2;
        int fennek_temochi = -1;
        for (int i = 0; i < fennec_ashiato.Length; i++)
        {
            fennek_temochi += fennec_ashiato[i];

        }
        int sunuke = n - fennek_temochi - dochiranomonodemonai-2;
        if (sunuke >= fennek_temochi) Console.WriteLine("Fennec");
        else Console.WriteLine("Snuke");

    }

    public static List<tansaku> stacking_tansaku = new List<tansaku>();

    public static void aitemadebridge()
    {

        tansaku looking = stacking_tansaku[0];
        stacking_tansaku.RemoveAt(0);
        if (looking.ima == looking.goal)
        {
            route_from_Fenec = looking.road;

        }
        int[] nextbanchi = looking.route[looking.ima].Split(',').Select(int.Parse).ToArray();
        for (int i = 0; i < nextbanchi.Length; i++)
        {
            if (looking.check[nextbanchi[i]] == 0)
            {
                tansaku nexttansaku = new tansaku();
                nexttansaku.ima = nextbanchi[i];
                looking.check[nextbanchi[i]] = 1;
                nexttansaku.check = looking.check;
                nexttansaku.road = looking.road + " " + nextbanchi[i];
                nexttansaku.route = looking.route;
                nexttansaku.goal = looking.goal;
                stacking_tansaku.Add(nexttansaku);

            }
        }

    }

    public static int[] ashiato(int[] a, int[] b)
    {
        int[] output = new int[a.Length];
        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] + b[i] >= 1) output[i] = 1;
            else output[i] = 0;
        }
        return output;
    }



    public struct tansaku
    {
        public string road;
        public int[] check;//n+1までいる
        public string[] route;
        public int ima;
        public int goal;
    }

    public static int[] ikerumichi(string route)
    {
        int[] output;
        string[] split = route.Split(',');
        output=split.Select(int.Parse).ToArray();
        return output;
    }

    public static int incheck(int[] check, int m)//mがcheckの中にあるかどうかの関数　あるなら１
    {
        for (int i = 0; i < check.Length; i++)
        {
            if (check[i] == m) return 1;

        }
        return 0;
    }


}

using System.Collections.Generic;
using System.Linq;
using System;

class D
{
    static int N;
    static List<int>[] e;
    static void Main()
    {
        N = int.Parse(Console.ReadLine());
        e = new List<int>[N];

        for (int i = 0; i < N; i++) e[i] = new List<int>();
        for (long i = 0; i < N - 1; i++)
        {
            var XY = Console.ReadLine().Split(' ').Select(x => int.Parse(x) - 1);
            e[XY.ElementAt(0)].Add(XY.ElementAt(1));
            e[XY.ElementAt(1)].Add(XY.ElementAt(0));
        }

        var Black = DFS(0, N - 1).Count(x => x);
        var White = DFS(N - 1, 0).Count(x => x);
        var c = Black + White - N;

        if (Black > White)
        {
            Console.WriteLine("Fennec");
        }
        else if (Black < White)
        {
            Console.WriteLine("Snuke");
        }
        else
        {
            if (c == 0)
            {
                Console.WriteLine("Snuke");
            }
            else if ((c & 1) == 1)
            {
                Console.WriteLine("Fennec");
            }
            else
            {
                Console.WriteLine("Snuke");
            }
        }
    }

    static bool[] DFS(int root, int goal)
    {
        var s = new Stack<int>();
        var v = new bool[N];
        s.Push(root);
        v[root] = true;
        while (s.Count > 0)
        {
            var current = s.Pop();
            foreach (var next in e[current])
            {
                if (!v[next] && next != goal)
                {
                    s.Push(next);
                    v[next] = true;
                }
            }
        }
        return v;
    }
}

