			var now = Q.Dequeue();
			foreach(var nxt in E[now]){
				if(nxt == parent[now]) continue;
				parent[nxt] = now;
				depth[nxt] = depth[now] + 1;
				E[nxt].Remove(now);
				Q.Enqueue(nxt);
			}
		}

		int len = depth[N-1];
