        q.Enqueue(N - 1);
        color[N - 1] = 1;

        while(q.Count != 0)
        {
            int now = q.Dequeue();
            foreach (var next in es[now])
            {
                if (color[next] != -1) continue;
                color[next] = color[now];
                q.Enqueue(next);
            }
        }

        int A = 0;
        for (int i = 0; i < N; i++)
        {
            if (color[i] == 0) A++;
        }
        int B = N - A;

        if (A > B) Console.WriteLine("Fennec");
        else Console.WriteLine("Snuke");

    }
}



class Scanner
