            //WriteLine("--------- line 2 -----------");
            //root.ForEach(x => WriteLine(x));
            root.ForEach(x => queOfSnuke.Enqueue(x));

            var isRooted = new int[N+1];
            var countOfFennec = 0;
            var countOfSnuke = 0;
            //WriteLine("--------------------");
            while (true) 
            {
                while(true)
                {
                    if (queOfFennec.Count == 0) break;
                    var f = queOfFennec.Dequeue();
                    //WriteLine("f {0} {1}", f, countOfFennec);
                    if (isRooted[f] == 1) continue;
                    foreach (var p in points[f])
                    {
                        if (isRooted[p] == 0) queOfFennec.Enqueue(p);
                    }
                    isRooted[f] = 1;
                    countOfFennec++;
                    break;
                }

                while (true)
                {
                    if (queOfSnuke.Count == 0) break;
                    var s = queOfSnuke.Dequeue();
                    //WriteLine("s {0} {1}", s, countOfSnuke);
                    if (isRooted[s] == 1) continue;
                    foreach (var p in points[s])
                    {
                        if(isRooted[p] == 0) queOfSnuke.Enqueue(p);
                    }
                    isRooted[s] = 1;
                    countOfSnuke++;
                    break;
                }
                if (countOfSnuke != countOfFennec) break;
            }

            WriteLine(countOfFennec > countOfSnuke ? "Fennec" : "Snuke");
        }

        private BigInteger Lcm(BigInteger a, BigInteger b)
        {
            return (a * b) / Gcd(a, b);
        }

        /// <summary>
        /// 最大公約数計算
        /// </summary>
        /// <param name="a"></param>
        /// <param name="b"></param>
        /// <returns></returns>
        private BigInteger Gcd(BigInteger a, BigInteger b)
        {
            if (a < b) return Gcd(b, a);

            while (b != 0)
            {
                var mod = a % b;
                a = b;
                b = mod;
            }
            return a;
        }
    }

    public class ConsoleInput
    {
        private readonly System.IO.TextReader _stream;
        private char _separator = ' ';
        private Queue<string> inputStream;
        public ConsoleInput(System.IO.TextReader stream, char separator = ' ')
        {
            this._separator = separator;
            this._stream = stream;
            inputStream = new Queue<string>();
        }

        public string Read
        {
            get
            {
                if (inputStream.Count != 0) return inputStream.Dequeue();
                string[] tmp = _stream.ReadLine().Split(_separator);
                for (int i = 0; i < tmp.Length; i++)
                    inputStream.Enqueue(tmp[i]);
                return inputStream.Dequeue();
            }
        }

        public string ReadLine { get { return _stream.ReadLine(); } }
        public int ReadInt { get { return int.Parse(Read); } }
        public long ReadLong { get { return long.Parse(Read); } }
        public double ReadDouble { get { return double.Parse(Read); } }
