namespace CS_AtCoder {
	class Program {
		static void Main(string[] args) {
			new Calc().Solve();
		}
	}
	public class Calc {
		Scan cin = new Scan();
		List<List<int>> graph = new List<List<int>>();
		List<bool> visited;
		int N;

		public void Solve() {
			N = cin.ReadInt();
			for (int i = 0; i < N; i++) { graph.Add(new List<int>()); }
			for (int i = 0; i < N - 1; i++) {
				var ab = cin.ReadInt(' ').Select(x => x - 1).ToArray();
				int a = ab[0], b = ab[1];
				graph[a].Add(b);
				graph[b].Add(a);
			}
			visited = Enumerable.Repeat(false, N).ToList();
			toSnuke(0, 0, 0);
			visited = visited.Select(x => { return false; }).ToList();
			CountIgnore(N-1);
			SnukeLengthTo--;
			int F_Node = N - SnukeLengthTo - SnukeNodes;
			if (F_Node == SnukeNodes) {
				(SnukeLengthTo % 2 == 1 ? "Fennec" : "Snuke").WL();
			} else {
				(F_Node > SnukeNodes ? "Fennec" : "Snuke").WL();
			}
			return;
		}
		private int SnukeLengthTo = 0;
		private int NextSnukeNode = 0;
		void toSnuke(int sum,int from,int current) {
			if (current == N - 1) { NextSnukeNode = from; SnukeLengthTo = sum; return; }
			if (visited[current]) return;
			visited[current] = true;
			for (int i = 0; i < graph[current].Count; i++) {
				toSnuke(sum+1,current,graph[current][i]);
			}
		}
		int SnukeNodes = 0;
		void CountIgnore(int current) {
			if (current == NextSnukeNode) return;
			if (visited[current]) return;
			visited[current] = true;
			SnukeNodes++;
			for (int i = 0; i < graph[current].Count; i++) {
				CountIgnore(graph[current][i]);
			}
		}

	}

