    class DFS
    {
        int[] dis;
        List<int>[] edge;

        public DFS(int n, List<int>[] edge)
        {
            dis = Enumerable.Repeat(int.MaxValue, n + 1).ToArray();
            this.edge = edge;
        }

        public void Seach(int a, int d)
        {
            dis[a] = d++;
            for (int i = 0; i < edge[a].Count; i++)
            {
                if (dis[edge[a][i]] == int.MaxValue)
                {
                    Seach(edge[a][i], d);
                }
            }
        }

        public int Dis(int a)
        {
            return dis[a];
        }
    }
