namespace ABC067D
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = RInt;

            List<int>[] edges = new List<int>[N].Select(x => new List<int>()).ToArray();
            for (int i = 0; i < N - 1; i++)
            {
                var a = RInt - 1;
                var b = RInt - 1;
                edges[a].Add(b);
                edges[b].Add(a);
            }

            int[] col = new int[N].Select(x => -1).ToArray();
            Queue<int> f = new Queue<int>();
            Queue<int> s = new Queue<int>();
            col[0] = 0;
            col[N - 1] = 1;
            f.Enqueue(0);
            s.Enqueue(N - 1);

            while (f.Count > 0 || s.Count > 0)
            {
                if (f.Count > 0)
                {
                    var now = f.Dequeue();
                    foreach (var t in edges[now])
                    {
                        if (col[t] == -1)
                        {
                            col[t] = col[now];
                            f.Enqueue(t);
                        }
                    }
                }
                if (s.Count > 0)
                {
                    var now = s.Dequeue();
                    foreach (var t in edges[now])
                    {
                        if (col[t] == -1)
                        {
                            col[t] = col[now];
                            s.Enqueue(t);
                        }
                    }
                }
            }

            int fCount = col.Count(x => x == 0);
            int sCount = col.Count(x => x == 1);

            if (fCount >= sCount) Console.WriteLine("Fennec");
            else Console.WriteLine("Snuke");
        }


    }


