namespace CS_AtCoder {
	class Program {
		static void Main(string[] args) {
			new Calc().Solve();
		}
	}
	public class Calc {
		Scan cin = new Scan();
		List<List<int>> graph = new List<List<int>>();
		List<bool> visited;
		int N;

		public void Solve() {
			N = cin.ReadInt();
			for (int i = 0; i < N; i++) { graph.Add(new List<int>()); }
			for (int i = 0; i < N - 1; i++) {
				var ab = cin.ReadInt(' ').Select(x => x - 1).ToArray();
				int a = ab[0], b = ab[1];
				graph[a].Add(b);
				graph[b].Add(a);
			}
			visited = Enumerable.Repeat(false, N).ToList();
			toSnuke(0, 0, 0);
			visited = visited.Select(x => { return false; }).ToList();
			CountIgnore(N-1);
			SnukeLengthTo--;
			int F_Node = N - SnukeLengthTo - SnukeNodes;
			SnukeLengthTo -= F_Node + SnukeNodes;
			if (SnukeLengthTo % 2 == 0) {
				"Snuke".WL();
			} else {
				"Fennec".WL();
			}

			return;
		}
		private int SnukeLengthTo = 0;
		private int NextSnukeNode = 0;
		void toSnuke(int sum,int from,int current) {
			if (current == N - 1) { NextSnukeNode = from; SnukeLengthTo = sum; return; }
			if (visited[current]) return;
			visited[current] = true;
			for (int i = 0; i < graph[current].Count; i++) {
				toSnuke(sum+1,current,graph[current][i]);
			}
		}
		int SnukeNodes = 0;
		void CountIgnore(int current) {
			if (current == NextSnukeNode) return;
			if (visited[current]) return;
			visited[current] = true;
			SnukeNodes++;
			for (int i = 0; i < graph[current].Count; i++) {
				CountIgnore(graph[current][i]);
			}
		}

	}

	public class Scan {
		public Scan() { }
		public int ReadInt() => int.Parse(Console.ReadLine());
		public int[] ReadInt(char separator) => Console.ReadLine().Split(separator).Select(int.Parse).ToArray();
		public double ReadDouble() => double.Parse(Console.ReadLine());
		public double[] ReadDouble(char separator) => Console.ReadLine().Split(separator).Select(double.Parse).ToArray();
		public long ReadLong() => long.Parse(Console.ReadLine());
		public long[] ReadLong(char separator) => Console.ReadLine().Split(separator).Select(long.Parse).ToArray();
		public string ReadLine() => Console.ReadLine();
		public string[] ReadLine(char separator) => Console.ReadLine().Split(separator).ToArray();
	}
	public static class Utils {
		public static string Docking<T>(this IEnumerable<T> collection,Func<T,string> filter = null) {
			StringBuilder sb = new StringBuilder();
			long Length = collection.Count();
			foreach (var item in collection.Select((v, i) => new { V = v, I = i })) {
				sb.Append(filter != null ? filter(item.V) : item.V.ToString());
			}
			return sb.ToString();
		}
		public static void WL(this object obj) => Console.WriteLine(obj);
		public static int IntParse(this string s) => int.Parse(s);
		public static int IntParse(this char c) => c - '0';
		public static List<int> SieveOfEratosthenes(int max) {
			int prime;
			double sqMax = Math.Sqrt(max);
			var prList = new List<int>();
			var srList = new List<int>();
			for (int i = 2; i < max+1; i++) {
				srList.Add(i);
			}
			do {
				prime = srList[0];
				prList.Add(prime);
				srList.RemoveAll(x => x % prime == 0);
			} while (prime<sqMax);
			prList.AddRange(srList);
			return prList;
		}
		public static long NCR(int n,int r) {
			long p = 1;
			for (int i = 1; i <=r; i++) {
				p = p * (n - i + 1) / i;
			}
			return p;
		}
	}
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
	public class Program
	{
		// TLEがないやつ
		// http://abc067.contest.atcoder.jp/submissions/1431424
		// クラスにしたやつ
		// http://abc067.contest.atcoder.jp/submissions/1431941

		static string フェネックの名前 = "Fennec";
		static string すぬけくんの名前 = "Snuke";

		enum マスの色
		{
			透明 = 0,
			黒,
			白,
		};

		enum プレイヤー
		{
			謎の第三者 = マスの色.透明,
			フェネック = マスの色.黒,
			すぬけくん = マスの色.白,
		};

		public static void Main(string[] args)
		{
			var str = Console.ReadLine().Split(' ');
			var マスの数 = int.Parse(str[0]); // 2 ~ 10^5
			var 道の数 = マスの数 - 1;
			var マスの情報 = new List<int>[マスの数 + 1];

			for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
			{
				マスの情報[マスの番号] = new List<int>();
			}

			for (var 道の番号 = 0; 道の番号 < 道の数; 道の番号++)
			{
				var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
				マスの情報[一つの道の情報[0]].Add(一つの道の情報[1]);
				マスの情報[一つの道の情報[1]].Add(一つの道の情報[0]);
			}

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var 合計シミュレート回数 = Math.Min(1000, Math.Max(1, 2000000000 / (マスの数 * マスの数) ));
			int 一回のシミュレート回数 = 5;
			int 繰り返す数 = 20;
			var マスの色の情報 = new マスの色[マスの数 + 1];
			var フェネックの最初のマス = 1;
			var すぬけくんの最初のマス = マスの数;
			var 乱数 = new System.Random();
			var フェネックの定跡本 = new List<int>();
			var すぬけくんの定跡本 = new List<int>();

			var 生き延びた最大ターン = -1;
			var フェネックの生き延びた最大ターン = -1;
			var すぬけくんの生き延びた最大ターン = -1;
			var 只今の勝者 = プレイヤー.謎の第三者;

			Func<int, List<int>, List<int>, プレイヤー> シミュレート = (シミュレート回数, フェネックの定跡, すぬけくんの定跡) =>
			{
				var 新しいフェネックの定跡 = new List<int>();
				var 新しいすぬけくんの定跡 = new List<int>();

				for (var 回数 = 0; 回数 < シミュレート回数; 回数++)
				{
					var フェネックの進める箇所 = new List<int>();
					var すぬけくんの進める箇所 = new List<int>();

					var フェネックの今回の選択 = new List<int>();
					var すぬけくんの今回の選択 = new List<int>();

					for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
					{
						マスの色の情報[マスの番号] = マスの色.透明;
					}
					マスの色の情報[フェネックの最初のマス] = マスの色.黒;
					マスの色の情報[すぬけくんの最初のマス] = マスの色.白;

					フェネックの進める箇所.AddRange(マスの情報[フェネックの最初のマス]);
					すぬけくんの進める箇所.AddRange(マスの情報[すぬけくんの最初のマス]);

					var 最大ターン数 = 1 + マスの数 / 2;
					for (var ターン = 0; ターン < 最大ターン数; ターン++)
					{
						// 先行はフェネック
						bool フェネックが移動していない = true;
						if (フェネックの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < フェネックの定跡.Count ? フェネックの定跡[ターン] : 乱数.Next(0, フェネックの進める箇所.Count);
							var 保存領域 = フェネックの進める箇所[0];
							フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番優先したいところ];
							フェネックの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = フェネックの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								フェネックの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.黒;
								フェネックの進める箇所.AddRange(マスの情報[移動候補]);
								フェネックが移動していない = false;
								break;
							}
							フェネックの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (フェネックが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.すぬけくん;
								生き延びた最大ターン = ターン;
							}
							if (すぬけくんの生き延びた最大ターン < ターン)
							{
								すぬけくんの生き延びた最大ターン = ターン;
								新しいすぬけくんの定跡 = すぬけくんの今回の選択;
							}
							break;
						}

						bool すぬけくんが移動していない = true;
						if (すぬけくんの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < すぬけくんの定跡.Count ? すぬけくんの定跡[ターン] : 乱数.Next(0, すぬけくんの進める箇所.Count);
							var 保存領域 = すぬけくんの進める箇所[0];
							すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番優先したいところ];
							すぬけくんの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = すぬけくんの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								すぬけくんの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.白;
								すぬけくんの進める箇所.AddRange(マスの情報[移動候補]);
								すぬけくんが移動していない = false;
								break;
							}
							すぬけくんの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (すぬけくんが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.フェネック;
								生き延びた最大ターン = ターン;
							}
							if (フェネックの生き延びた最大ターン < ターン)
							{
								フェネックの生き延びた最大ターン = ターン;
								新しいフェネックの定跡 = フェネックの今回の選択;
							}
							break;
						}
					}
				}

				switch (只今の勝者)
				{
					case プレイヤー.フェネック:
						フェネックの定跡 = 新しいフェネックの定跡.Take(新しいフェネックの定跡.Count / 2).ToList();
						break;
					case プレイヤー.すぬけくん:
						すぬけくんの定跡 = 新しいすぬけくんの定跡.Take(新しいすぬけくんの定跡.Count / 2).ToList();
						break;
				}

				return 只今の勝者;
			};

			for (var 世代 = 0; 世代 < 繰り返す数; 世代++)
			{
				シミュレート(一回のシミュレート回数, フェネックの定跡本, すぬけくんの定跡本);
			}

			Console.WriteLine(只今の勝者 == プレイヤー.フェネック ? フェネックの名前 : すぬけくんの名前);
		}
	}
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
	public class Program
	{
		static string フェネックの名前 = "Fennec";
		static string すぬけくんの名前 = "Snuke";

		public enum マスの色
		{
			透明 = 0,
			黒,
			白,
		};

		public class マス
		{
			public List<int> 隣接情報 = new List<int>();
			マスの色 _色;
			public マスの色 色
			{
				get { return _色; }
				set
				{
					_色 = value;
					移動可能 = _色 == マスの色.透明;
				}
			}

			public bool 移動可能 { get; private set;}
		}

		public class ボード
		{
			public int マスの数 { get; private set; }
			public マス[] マスの情報;

			public int デュエリスト黒のスタート地点 { get; private set; }
			public int デュエリスト白のスタート地点 { get; private set; }

			public void データを標準入力から読み込む()
			{
				var str = Console.ReadLine().Split(' ');
				マスの数 = int.Parse(str[0]); // 2 ~ 10^5
				var 道の数 = マスの数 - 1;

				マスの情報 = new マス[マスの数 + 1]; // マスは1スタートなので1個増やす

				for (var マスの番号 = 0; マスの番号 < マスの情報.Length; マスの番号++)
				{
					マスの情報[マスの番号] = new マス();
				}

				for (var 道の番号 = 0; 道の番号 < 道の数; 道の番号++)
				{
					var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
					マスの情報[一つの道の情報[0]].隣接情報.Add(一つの道の情報[1]);
					マスの情報[一つの道の情報[1]].隣接情報.Add(一つの道の情報[0]);
				}

				デュエリスト黒のスタート地点 = 1;
				デュエリスト白のスタート地点 = マスの数;
			}

			public void 新しいゲームを始める()
			{
				for (var マスの番号 = 0; マスの番号 < マスの情報.Length; マスの番号++)
				{
					マスの情報[マスの番号].色 = マスの色.透明;
				}

				マスの情報[デュエリスト黒のスタート地点].色 = マスの色.黒;
				マスの情報[デュエリスト白のスタート地点].色 = マスの色.白;
			}
		}

		public class デュエリスト
		{
			public string 真名 { get; private set; }

			int 最初のマス;
			マスの色 色;
			ボード ボード;

			ゲーム ゲーム;

			List<int> 定跡本 = new List<int>();
			int 今までで一番生きたときのターン数 = -1;

			List<int> 新しい定跡 = new List<int>();
			List<int> 進める箇所 = new List<int>();
			List<int> 今回の選択 = new List<int>();

			Random 乱数 = new Random();

			public デュエリスト(string 真名)
			{
				this.真名 = 真名;
			}

			public void ゲームの情報を取得する(int 最初のマス, マスの色 色, ボード ボード)
			{
				this.最初のマス = 最初のマス;
				this.色 = 色;
				this.ボード = ボード;
			}

			public void ゲームを開始する(ゲーム ゲーム)
			{
				this.ゲーム = ゲーム;
				新しい定跡 = new List<int>();
				進める箇所 = new List<int>();
				今回の選択 = new List<int>();

				移動する(最初のマス);
			}

			public bool 移動先を考えて移動する()
			{
				if (進める箇所.Count > 1)
				{
					var 第一移動候補 = ゲーム.ターン < 定跡本.Count ? 定跡本[ゲーム.ターン] : 乱数.Next(0, 進める箇所.Count);
					var 保存領域 = 進める箇所[0];
					進める箇所[0] = 進める箇所[第一移動候補];
					進める箇所[第一移動候補] = 保存領域;
				}

				for (var 移動候補の番号 = 0; 移動候補の番号 < 進める箇所.Count; 移動候補の番号++)
				{
					var 移動候補 = 進める箇所[移動候補の番号];
					var 移動候補のマスの情報 = ボード.マスの情報[移動候補];

					if (移動候補のマスの情報.移動可能)
					{
						今回の選択.Add(移動候補の番号);
						移動候補のマスの情報.色 = マスの色.黒;
						移動する(移動候補);
						return true;
					}
				}

				負けたので反省する();
				return false;
			}

			void 移動する(int 移動するマス)
			{
				for (var i = 0; i < 進める箇所.Count; i++)
				{
					if (ボード.マスの情報[進める箇所[i]].色 != マスの色.透明)
					{
						進める箇所.RemoveAt(i);
						i--;
					}
				}
				var 進んだ先のマスの情報 = ボード.マスの情報[移動するマス].隣接情報;
				for (var i = 0; i < 進んだ先のマスの情報.Count; i++)
				{
					if (ボード.マスの情報[進んだ先のマスの情報[i]].色 == マスの色.透明)
					{
						進める箇所.Add(進んだ先のマスの情報[i]);
					}
				}
			}

			public void 負けたので反省する()
			{
				新しい定跡.Clear();
			}

			public void 勝利したので次に向けて準備する()
			{
				ゲーム.ランキングに登録する(this);

				if (今までで一番生きたときのターン数 < ゲーム.ターン)
				{
					今までで一番生きたときのターン数 = ゲーム.ターン;
					新しい定跡 = 今回の選択.Take(ゲーム.ターン/2).ToList();
				}
			}

			public void 定跡を更新する()
			{
				定跡本 = 新しい定跡;
			}
		}

		public class ゲーム
		{
			public int ターン { get; private set; }
			public int 最大ターン { get; private set; }

			public int 今までで一番長く続いたターン { get; private set; }

			public デュエリスト 只今の勝者 { get; private set; }

			public void データを初期化する()
			{
				今までで一番長く続いたターン = -1;
			}

			public void 始める(ボード ボード, デュエリスト 黒, デュエリスト 白)
			{
				ボード.新しいゲームを始める();
				黒.ゲームを開始する(this);
				白.ゲームを開始する(this);

				ターン = 0;
				最大ターン = 1 + ボード.マスの数 / 2;

				for (ターン = 0; ターン < 最大ターン; ターン++)
				{
					var 黒が移動できない = !黒.移動先を考えて移動する();
					if (黒が移動できない)
					{
						白.勝利したので次に向けて準備する();
						break;
					}
					var 白が移動できない = !白.移動先を考えて移動する();
					if (白が移動できない)
					{
						黒.勝利したので次に向けて準備する();
						break;
					}
				}
			}

			public void ランキングに登録する(デュエリスト デュエリスト)
			{
				if (今までで一番長く続いたターン >= ターン) return;

				今までで一番長く続いたターン = ターン;
				只今の勝者 = デュエリスト;
			}
		}

		public static void Main(string[] args)
		{
			var ゲーム = new ゲーム();
			ゲーム.データを初期化する();
			var ボード = new ボード();
			ボード.データを標準入力から読み込む();

			var フェネック = new デュエリスト(フェネックの名前);
			フェネック.ゲームの情報を取得する(ボード.デュエリスト黒のスタート地点, マスの色.黒, ボード);
			var すぬけくん = new デュエリスト(すぬけくんの名前);
			すぬけくん.ゲームの情報を取得する(ボード.デュエリスト白のスタート地点, マスの色.白, ボード);

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var 合計シミュレート回数 = Math.Max(1, 30000 / ボード.マスの数);
			var シミュレート回数 = Math.Max(1, Math.Sqrt(合計シミュレート回数) / 2 );
			var 世代数 = Math.Max(1, 合計シミュレート回数 / シミュレート回数);
			for (var 世代 = 0; 世代 < 世代数; 世代++)
			{
				for (var 回数 = 0; 回数 < シミュレート回数; 回数++)
				{
					ゲーム.始める(ボード, フェネック, すぬけくん);
				}
				フェネック.定跡を更新する();
				すぬけくん.定跡を更新する();
			}

			Console.WriteLine(ゲーム.只今の勝者.真名);
		}
	}
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
	public class Program
	{
		// TLEがないやつ
		// http://abc067.contest.atcoder.jp/submissions/1431424
		// クラスにしたやつ
		// http://abc067.contest.atcoder.jp/submissions/1431941

		static string フェネックの名前 = "Fennec";
		static string すぬけくんの名前 = "Snuke";

		enum マスの色
		{
			透明 = 0,
			黒,
			白,
		};

		enum プレイヤー
		{
			謎の第三者 = マスの色.透明,
			フェネック = マスの色.黒,
			すぬけくん = マスの色.白,
		};

		public static void Main(string[] args)
		{
			var str = Console.ReadLine().Split(' ');
			var マスの数 = int.Parse(str[0]); // 2 ~ 10^5
			var 道の数 = マスの数 - 1;
			var マスの情報 = new List<int>[マスの数 + 1];

			for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
			{
				マスの情報[マスの番号] = new List<int>();
			}

			for (var 道の番号 = 0; 道の番号 < 道の数; 道の番号++)
			{
				var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
				マスの情報[一つの道の情報[0]].Add(一つの道の情報[1]);
				マスの情報[一つの道の情報[1]].Add(一つの道の情報[0]);
			}

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var 合計シミュレート回数 = Math.Min(1000, Math.Max(1, 2000000000 / (マスの数 * マスの数) ));
			int 一回のシミュレート回数 = 5;
			int 繰り返す数 = 10;
			var マスの色の情報 = new マスの色[マスの数 + 1];
			var フェネックの最初のマス = 1;
			var すぬけくんの最初のマス = マスの数;
			var 乱数 = new System.Random();
			var フェネックの定跡本 = new List<int>();
			var すぬけくんの定跡本 = new List<int>();

			var 生き延びた最大ターン = -1;
			var フェネックの生き延びた最大ターン = -1;
			var すぬけくんの生き延びた最大ターン = -1;
			var 只今の勝者 = プレイヤー.謎の第三者;

			Func<int, List<int>, List<int>, プレイヤー> シミュレート = (シミュレート回数, フェネックの定跡, すぬけくんの定跡) =>
			{
				var 新しいフェネックの定跡 = new List<int>();
				var 新しいすぬけくんの定跡 = new List<int>();

				for (var 回数 = 0; 回数 < シミュレート回数; 回数++)
				{
					var フェネックの進める箇所 = new List<int>();
					var すぬけくんの進める箇所 = new List<int>();

					var フェネックの今回の選択 = new List<int>();
					var すぬけくんの今回の選択 = new List<int>();

					for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
					{
						マスの色の情報[マスの番号] = マスの色.透明;
					}
					マスの色の情報[フェネックの最初のマス] = マスの色.黒;
					マスの色の情報[すぬけくんの最初のマス] = マスの色.白;

					フェネックの進める箇所.AddRange(マスの情報[フェネックの最初のマス]);
					すぬけくんの進める箇所.AddRange(マスの情報[すぬけくんの最初のマス]);

					var 最大ターン数 = 1 + マスの数 / 2;
					for (var ターン = 0; ターン < 最大ターン数; ターン++)
					{
						// 先行はフェネック
						bool フェネックが移動していない = true;
						if (フェネックの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < フェネックの定跡.Count ? フェネックの定跡[ターン] : 乱数.Next(0, フェネックの進める箇所.Count);
							var 保存領域 = フェネックの進める箇所[0];
							フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番優先したいところ];
							フェネックの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = フェネックの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								フェネックの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.黒;
								フェネックの進める箇所.AddRange(マスの情報[移動候補]);
								フェネックが移動していない = false;
								break;
							}
							フェネックの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (フェネックが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.すぬけくん;
								生き延びた最大ターン = ターン;
							}
							if (すぬけくんの生き延びた最大ターン < ターン)
							{
								すぬけくんの生き延びた最大ターン = ターン;
								新しいすぬけくんの定跡 = すぬけくんの今回の選択;
							}
							break;
						}

						bool すぬけくんが移動していない = true;
						if (すぬけくんの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < すぬけくんの定跡.Count ? すぬけくんの定跡[ターン] : 乱数.Next(0, すぬけくんの進める箇所.Count);
							var 保存領域 = すぬけくんの進める箇所[0];
							すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番優先したいところ];
							すぬけくんの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = すぬけくんの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								すぬけくんの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.白;
								すぬけくんの進める箇所.AddRange(マスの情報[移動候補]);
								すぬけくんが移動していない = false;
								break;
							}
							すぬけくんの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (すぬけくんが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.フェネック;
								生き延びた最大ターン = ターン;
							}
							if (フェネックの生き延びた最大ターン < ターン)
							{
								フェネックの生き延びた最大ターン = ターン;
								新しいフェネックの定跡 = フェネックの今回の選択;
							}
							break;
						}
					}
				}

				switch (只今の勝者)
				{
					case プレイヤー.フェネック:
						フェネックの定跡 = 新しいフェネックの定跡.Take(新しいフェネックの定跡.Count / 2).ToList();
						break;
					case プレイヤー.すぬけくん:
						すぬけくんの定跡 = 新しいすぬけくんの定跡.Take(新しいすぬけくんの定跡.Count / 2).ToList();
						break;
				}

				return 只今の勝者;
			};

			for (var 世代 = 0; 世代 < 繰り返す数; 世代++)
			{
				シミュレート(一回のシミュレート回数, フェネックの定跡本, すぬけくんの定跡本);
			}

			Console.WriteLine(只今の勝者 == プレイヤー.フェネック ? フェネックの名前 : すぬけくんの名前);
		}
	}
}

using System;
