		public class デュエリスト
		{
			public string 真名 { get; private set; }

			int 最初のマス;
			マスの色 色;
			ボード ボード;

			ゲーム ゲーム;

			List<int> 定跡本 = new List<int>();
			int 今までで一番生きたときのターン数 = -1;

			List<int> 新しい定跡 = new List<int>();
			List<int> 進める箇所 = new List<int>();
			List<int> 今回の選択 = new List<int>();

			bool 敵と接触済み;

			Random 乱数 = new Random();

			public デュエリスト(string 真名)
			{
				this.真名 = 真名;
			}

			public void ゲームの情報を取得する(int 最初のマス, マスの色 色, ボード ボード)
			{
				this.最初のマス = 最初のマス;
				this.色 = 色;
				this.ボード = ボード;
			}

			public void ゲームを開始する(ゲーム ゲーム)
			{
				this.ゲーム = ゲーム;
				新しい定跡 = new List<int>();
				進める箇所 = new List<int>();
				今回の選択 = new List<int>();
				敵と接触済み = false;

				移動する(最初のマス);
			}

			int 敵の方向を探す(int 深さ, int 前の移動候補の番号, List<int> 移動先候補)
			{
				深さ--;
				for (var 移動候補の番号 = 0; 移動候補の番号 < 移動先候補.Count; 移動候補の番号++)
				{
					var 移動候補 = 移動先候補[移動候補の番号];
					var 移動候補のマスの情報 = ボード.マスの情報[移動候補];
					if (!移動候補のマスの情報.移動可能)
					{
						if (移動候補のマスの情報.敵がいる(色))
						{
							敵と接触済み = true;
							return 前の移動候補の番号;
						}
						continue;
					}

					if (深さ > 0)
					{
						return 敵の方向を探す(深さ, 移動候補の番号, 移動候補のマスの情報.隣接情報);
					}
				}
				return 0;
			}

			void 移動先を考える()
			{
				if (敵と接触済み) return;

				// 数が多い時は慎重に行動する
				if (進める箇所.Count > 10)
				{
					var 第一移動候補 = 敵の方向を探す(2, 0, 進める箇所);
					var 保存領域 = 進める箇所[0];
					進める箇所[0] = 進める箇所[第一移動候補];
					進める箇所[第一移動候補] = 保存領域;
				}
				else if (進める箇所.Count > 1)
				{
					var 第一移動候補 = ゲーム.ターン < 定跡本.Count ? 定跡本[ゲーム.ターン] : 乱数.Next(0, 進める箇所.Count);
					var 保存領域 = 進める箇所[0];
					進める箇所[0] = 進める箇所[第一移動候補];
					進める箇所[第一移動候補] = 保存領域;
				}
			}

			public bool 移動先を考えて移動する()
			{
				移動先を考える();

				for (var 移動候補の番号 = 0; 移動候補の番号 < 進める箇所.Count; 移動候補の番号++)
				{
					var 移動候補 = 進める箇所[移動候補の番号];
					var 移動候補のマスの情報 = ボード.マスの情報[移動候補];

					if (移動候補のマスの情報.移動可能)
					{
						if (!敵と接触済み)
						{
							今回の選択.Add(移動候補の番号);
						}
						移動候補のマスの情報.色 = マスの色.黒;
						移動する(移動候補);
						return true;
					}
				}

				負けたので反省する();
				return false;
			}

			void 移動する(int 移動するマス)
			{
				for (var i = 0; i < 進める箇所.Count; i++)
				{
					if (!ボード.マスの情報[進める箇所[i]].移動可能)
					{
						if (ボード.マスの情報[進める箇所[i]].敵がいる(色))
						{
							敵と接触済み = true;
						}
						進める箇所.RemoveAt(i);
						i--;
					}
				}
				var 進んだ先のマスの情報 = ボード.マスの情報[移動するマス].隣接情報;
				for (var i = 0; i < 進んだ先のマスの情報.Count; i++)
				{
					if (ボード.マスの情報[進んだ先のマスの情報[i]].移動可能)
					{
						進める箇所.Add(進んだ先のマスの情報[i]);
					}
					// 敵と接触
					else if (ボード.マスの情報[進んだ先のマスの情報[i]].敵がいる(色))
					{
						敵と接触済み = true;
					}
				}
			}

			public void 負けたので反省する()
			{
				新しい定跡.Clear();
			}

			public void 勝利したので次に向けて準備する()
			{
				ゲーム.ランキングに登録する(this);

				if (今までで一番生きたときのターン数 < ゲーム.ターン)
				{
					今までで一番生きたときのターン数 = ゲーム.ターン;
					新しい定跡 = 今回の選択.Take(ゲーム.ターン/2).ToList();
				}
			}

			public void 定跡を更新する()
			{
				定跡本 = 新しい定跡;
			}
		}

		public class ゲーム
		{
			public int ターン { get; private set; }
			public int 最大ターン { get; private set; }

			public int 今までで一番長く続いたターン { get; private set; }

			public デュエリスト 只今の勝者 { get; private set; }

			public void データを初期化する()
			{
				今までで一番長く続いたターン = -1;
			}

			public void 始める(ボード ボード, デュエリスト 黒, デュエリスト 白)
			{
				ボード.新しいゲームを始める();
				黒.ゲームを開始する(this);
				白.ゲームを開始する(this);

				ターン = 0;
				最大ターン = 1 + ボード.マスの数 / 2;

				for (ターン = 0; ターン < 最大ターン; ターン++)
				{
					var 黒が移動できない = !黒.移動先を考えて移動する();
					if (黒が移動できない)
					{
						白.勝利したので次に向けて準備する();
						break;
					}
					var 白が移動できない = !白.移動先を考えて移動する();
					if (白が移動できない)
					{
						黒.勝利したので次に向けて準備する();
						break;
					}
				}
			}

			public void ランキングに登録する(デュエリスト デュエリスト)
			{
				if (今までで一番長く続いたターン >= ターン) return;

				今までで一番長く続いたターン = ターン;
				只今の勝者 = デュエリスト;
			}
		}

		public static void Main(string[] args)
		{
			var ゲーム = new ゲーム();
			ゲーム.データを初期化する();
			var ボード = new ボード();
			ボード.データを標準入力から読み込む();

			var フェネック = new デュエリスト(フェネックの名前);
			フェネック.ゲームの情報を取得する(ボード.デュエリスト黒のスタート地点, マスの色.黒, ボード);
			var すぬけくん = new デュエリスト(すぬけくんの名前);
			すぬけくん.ゲームの情報を取得する(ボード.デュエリスト白のスタート地点, マスの色.白, ボード);

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var 合計シミュレート回数 = Math.Max(1, 30000 / ボード.マスの数);
			var シミュレート回数 = 1;
			var 世代数 = 60;
			for (var 世代 = 0; 世代 < 世代数; 世代++)
			{
				for (var 回数 = 0; 回数 < シミュレート回数; 回数++)
				{
					ゲーム.始める(ボード, フェネック, すぬけくん);
				}
				フェネック.定跡を更新する();
				すぬけくん.定跡を更新する();
			}

			Console.WriteLine(ゲーム.只今の勝者.真名);
		}
	}
}

using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
using System.Text;

namespace AtCoder {
    public class Program {
        static int[] getKeys() {
            var Keys = Console.ReadLine().Split(' ');
            int N = Keys.Length;
            int[] Ns = new int[N];
            for (int i = 0; i < N; i++) {
                Ns[i] = int.Parse(Keys[i]);
            }
            return Ns;
        }
        static int[] getKeys(char delimiter) {
            var Keys = Console.ReadLine().Split(delimiter);
            int N = Keys.Length;
            int[] Ns = new int[N];
            for (int i = 0; i < N; i++) {
                Ns[i] = int.Parse(Keys[i]);
            }
            return Ns;
        }
        static long[] getKeys_L(char delimiter = ' ') {
            var Keys = Console.ReadLine().Split(delimiter);
            int N = Keys.Length;
            long[] Ns = new long[N];
            for (int i = 0; i < N; i++) {
                Ns[i] = long.Parse(Keys[i]);
            }
            return Ns;
        }

        public static void Show<T>(T[,] map) {
            int H = map.GetLength(0);
            int W = map.GetLength(1);
            Console.WriteLine("-------------------------");
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    Console.Write(map[i, j] + " ");
                }
                Console.WriteLine();
            }
            Console.WriteLine("-------------------------");
        }
        public static void Show<T>(T[,] map, string delimiter) {
            int H = map.GetLength(0);
            int W = map.GetLength(1);
            Console.WriteLine("-------------------------");
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    Console.Write(map[i, j] + delimiter);
                }
                Console.WriteLine();
            }
            Console.WriteLine("-------------------------");
        }
        public static void Show<T>(IEnumerable<T> ts) {
            foreach (var item in ts) {
                Console.Write(item + " ");
            }
            Console.WriteLine();
        }
        public static void Show<T>(IEnumerable<T> ts, string delimiter) {
            foreach (var item in ts) {
                Console.Write(item + delimiter);
            }
            Console.WriteLine();
        }
        public static void ShowDictionary<T1, T2>(Dictionary<T1, T2> dictionary) {
            foreach (var item in dictionary) {
                Console.WriteLine(item);
            }
        }
        static T[] getUniform<T>(int length, T value) {
            T[] Ts = new T[length];
            for (int i = 0; i < length; i++) {
                Ts[i] = value;
            }
            return Ts;
        }
        static void setUniform<T>(T[] ts, T value) {
            int length = ts.Length;
            for (int i = 0; i < length; i++) {
                ts[i] = value;
            }
        }
        static T[,] getUniform<T>(int row, int col, T value) {
            T[,] Ts = new T[row, col];
            for (int i = 0; i < row; i++) {
                for (int j = 0; j < col; j++) {
                    Ts[j, i] = value;
                }
            }
            return Ts;
        }
        static void setUniform<T>(T[,] ts, T value) {
            int N = ts.GetLength(0);
            int M = ts.GetLength(1);
            for (int i = 0; i < M; i++) {
                for (int j = 0; j < N; j++) {
                    ts[j, i] = value;
                }
            }
        }

        static int N;
        static void Main() {
            N = int.Parse(Console.ReadLine());
            int[] Keys;
            var reachable = new bool[N, N];
            for (int i = 0; i < N - 1; i++) {
                Keys = getKeys();
                reachable[Keys[0] - 1, Keys[1] - 1] = true;
                reachable[Keys[1] - 1, Keys[0] - 1] = true;
            }
            try {
                var fromF = WFS(reachable, 0);
                var fromS = WFS(reachable, N - 1);
                int f = 0, s = 0;
                for (int i = 0; i < N; i++) {
                    if (fromF[i] <= fromS[i]) {
                        f++;
                    } else {
                        s++;
                    }
                }
            } catch {
                return;
            }
            Console.WriteLine(f > s ? "Fennec" : "Snuke");
        }

        static int[] WFS(bool[,] map, int from) {
            var visited = new bool[N];
            var distance = new int[N];
            Queue<Tuple<int, int>> vs = new Queue<Tuple<int, int>>();
            vs.Enqueue(new Tuple<int, int>(from, 0));
            while (vs.Count() > 0) {
                var n = vs.Dequeue();
                visited[n.Item1] = true;
                distance[n.Item1] = n.Item2;
                for (int i = 0; i < N; i++) {
                    if (!visited[i] && map[i, n.Item1]) {
                        vs.Enqueue(new Tuple<int, int>(i, n.Item2 + 1));
                    }
                }
                return new int[N];
            }
            return distance;
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
	public class Program
	{
		// TLEがないやつ
		// http://abc067.contest.atcoder.jp/submissions/1431970
		// クラスにしたやつ
		// http://abc067.contest.atcoder.jp/submissions/1431941

		static string フェネックの名前 = "Fennec";
		static string すぬけくんの名前 = "Snuke";

		enum マスの色
		{
			透明 = 0,
			黒,
			白,
		};

		enum プレイヤー
		{
			謎の第三者 = マスの色.透明,
			フェネック = マスの色.黒,
			すぬけくん = マスの色.白,
		};

		public static void Main(string[] args)
		{
			var str = Console.ReadLine().Split(' ');
			var マスの数 = int.Parse(str[0]); // 2 ~ 10^5
			var 道の数 = マスの数 - 1;
			var マスの情報 = new List<int>[マスの数 + 1];

			for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
			{
				マスの情報[マスの番号] = new List<int>();
			}

			for (var 道の番号 = 0; 道の番号 < 道の数; 道の番号++)
			{
				var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
				マスの情報[一つの道の情報[0]].Add(一つの道の情報[1]);
				マスの情報[一つの道の情報[1]].Add(一つの道の情報[0]);
			}

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var 合計シミュレート回数 = Math.Min(20000, Math.Max(1, 200000000 / (マスの数 * マスの数) ));
			int 繰り返す数 = 合計シミュレート回数;
			var マスの色の情報 = new マスの色[マスの数 + 1];
			var フェネックの最初のマス = 1;
			var すぬけくんの最初のマス = マスの数;
			var 乱数 = new System.Random(0);
			var フェネックの定跡本 = new List<int>();
			var すぬけくんの定跡本 = new List<int>();

			var 生き延びた最大ターン = -1;
			var フェネックの生き延びた最大ターン = -1;
			var すぬけくんの生き延びた最大ターン = -1;
			var 只今の勝者 = プレイヤー.謎の第三者;

			var 最大ターン数 = 1 + マスの数 / 2;

			var コールド勝ちのルールが有る = 繰り返す数 == 1;
			var コールド勝ちに必要なマスの数 = 15;
			var コールド勝ちに必要なターン = 最大ターン数 / 2;
			var フェネックとすぬけくんが隣接した = false;

			Action<List<int>, int, マスの色> 進めるマスを更新する = (進める箇所, 進むマスの番号, 自分の色) =>
			{
				for (var i = 0; i < 進める箇所.Count; i++)
				{
					if (マスの色の情報[進める箇所[i]] == マスの色.透明) continue;

					if (マスの色の情報[進める箇所[i]] != 自分の色)
					{
						フェネックとすぬけくんが隣接した = true;
					}
					進める箇所.RemoveAt(i);
					i--;
				}

				var 進んだ先のマスの情報 = マスの情報[進むマスの番号];
				for (var i = 0; i < 進んだ先のマスの情報.Count; i++)
				{
					if (マスの色の情報[進んだ先のマスの情報[i]] == マスの色.透明)
					{
						進める箇所.Add(進んだ先のマスの情報[i]);
						continue;
					}

					if (マスの色の情報[進んだ先のマスの情報[i]] != 自分の色)
					{
						フェネックとすぬけくんが隣接した = true;
					}
				}
			};

			Action シミュレート = () =>
			{
				var フェネックの進める箇所 = new List<int>();
				var すぬけくんの進める箇所 = new List<int>();

				var フェネックの今回の選択 = new List<int>();
				var すぬけくんの今回の選択 = new List<int>();

				フェネックとすぬけくんが隣接した = false;

				for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
				{
					マスの色の情報[マスの番号] = マスの色.透明;
				}
				マスの色の情報[フェネックの最初のマス] = マスの色.黒;
				マスの色の情報[すぬけくんの最初のマス] = マスの色.白;

				進めるマスを更新する(フェネックの進める箇所, フェネックの最初のマス, マスの色.黒);
				進めるマスを更新する(すぬけくんの進める箇所, すぬけくんの最初のマス, マスの色.白);

				for (var ターン = 0; ターン < 最大ターン数; ターン++)
				{
					// 先行はフェネック
					bool フェネックが移動していない = true;

					if (フェネックの進める箇所.Count > 1)
					{
						var 次の移動候補で一番優先したいところ = ターン < フェネックの定跡本.Count ? フェネックの定跡本[ターン] : 乱数.Next(0, フェネックの進める箇所.Count);
						var 保存領域 = フェネックの進める箇所[0];
						フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番優先したいところ];
						フェネックの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
					}
					for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
					{
						var 移動候補 = フェネックの進める箇所[移動候補の番号];
						if (マスの色の情報[移動候補] == マスの色.透明)
						{
							フェネックの今回の選択.Add(移動候補の番号);
							マスの色の情報[移動候補] = マスの色.黒;
							進めるマスを更新する(フェネックの進める箇所, 移動候補, マスの色.黒);
							フェネックが移動していない = false;
							break;
						}
						フェネックの進める箇所.RemoveAt(移動候補の番号);
						移動候補の番号--;
					}

					if (フェネックが移動していない)
					{
						if (生き延びた最大ターン < ターン)
						{
							只今の勝者 = プレイヤー.すぬけくん;
							生き延びた最大ターン = ターン;
						}
						if (すぬけくんの生き延びた最大ターン < ターン)
						{
							すぬけくんの生き延びた最大ターン = ターン;
							フェネックの定跡本.Clear();
							すぬけくんの定跡本 = すぬけくんの今回の選択;
						}
						break;
					}

					bool すぬけくんが移動していない = true;
					if (すぬけくんの進める箇所.Count > 1)
					{
						var 次の移動候補で一番優先したいところ = ターン < すぬけくんの定跡本.Count ? すぬけくんの定跡本[ターン] : 乱数.Next(0, すぬけくんの進める箇所.Count);
						var 保存領域 = すぬけくんの進める箇所[0];
						すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番優先したいところ];
						すぬけくんの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
					}
					for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
					{
						var 移動候補 = すぬけくんの進める箇所[移動候補の番号];
						if (マスの色の情報[移動候補] == マスの色.透明)
						{
							すぬけくんの今回の選択.Add(移動候補の番号);
							マスの色の情報[移動候補] = マスの色.白;
							進めるマスを更新する(すぬけくんの進める箇所, 移動候補, マスの色.白);
							すぬけくんが移動していない = false;
							break;
						}
						すぬけくんの進める箇所.RemoveAt(移動候補の番号);
						移動候補の番号--;
					}

					if (すぬけくんが移動していない)
					{
						if (生き延びた最大ターン < ターン)
						{
							只今の勝者 = プレイヤー.フェネック;
							生き延びた最大ターン = ターン;
						}
						if (フェネックの生き延びた最大ターン < ターン)
						{
							フェネックの生き延びた最大ターン = ターン;
							フェネックの定跡本 = フェネックの今回の選択;
							すぬけくんの定跡本.Clear();
						}
						break;
					}

					// 進める箇所がいっぱいあったらコールド勝ち
					// 隣接してたら最後まで続ける
					if (コールド勝ちのルールが有る && コールド勝ちに必要なターン > ターン && !フェネックとすぬけくんが隣接した)
					{
						if (フェネックの進める箇所.Count > すぬけくんの進める箇所.Count)
						{
							if (フェネックの進める箇所.Count > コールド勝ちに必要なマスの数)
							{
								只今の勝者 = プレイヤー.フェネック;
								break;
							}
						}
						else
						{
							if (すぬけくんの進める箇所.Count > コールド勝ちに必要なマスの数)
							{
								只今の勝者 = プレイヤー.すぬけくん;
								break;
							}
						}
					}
				}
			};

			for (var 世代 = 0; 世代 < 繰り返す数; 世代++)
			{
				シミュレート();
			}

			Console.WriteLine(只今の勝者 == プレイヤー.フェネック ? フェネックの名前 : すぬけくんの名前);
		}
	}
}

