namespace AIZU {
	class Program {
		#region Reserve
		static int cin() { return cin(-1); }
		static int cin(int D) {
			string s = Console.ReadLine();
			if (string.IsNullOrEmpty(s))
				return D;
			return int.Parse(s);
		}
		static int[] cins(char spliter) {
			string s = Console.ReadLine();
			if (string.IsNullOrEmpty(s))
				return new int[] { };
			string[] ss = s.Split(spliter);
			var Res = new int[ss.Length];
			for (int i = 0; i < ss.Length; i++)
				Res[i] = int.Parse(ss[i]);
			return Res;
		}
		static int[] cins() { return cins(' '); }
		static void print(object j) { Console.WriteLine(j.ToString()); }
		static void print(string j) { Console.WriteLine(j); }
		#endregion

		static void Main(string[] args) {
			int N = cin();
			var F = new List<int>[N];
			for (int i = 0; i < N; i++) F[i] = new List<int>();
			for (int i = 0; i < N-1; i++) {
				int[] I = cins();
				F[I[0]-1].Add(I[1]-1);
				F[I[1]-1].Add(I[0]-1);
			}
			int h=0;
			Stack<int> J = new Stack<int>();
			HashSet<int> Hist = new HashSet<int>();
			J.Push(h);
			Hist.Add(h);
			while (J.Count != 0) {
				h = J.Pop();
				foreach (int f in F[h]) {
					if (f == N-1) continue;
					if (Hist.Contains(f)) continue;
					J.Push(f);
					Hist.Add(f);
				}
			}
			int ap = Hist.Count;
			Hist.Clear();
			h = N - 1;
			J.Push(h);
			Hist.Add(h);
			while (J.Count != 0) {
				h = J.Pop();
				foreach (int f in F[h]) {
					if (f == 0) continue;
					if (Hist.Contains(f)) continue;
					J.Push(f);
					Hist.Add(f);
				}
			}
			int bp = Hist.Count;
			int bridge = ap + bp - N;
			ap -= (bridge & 1) == 1 ? 1 : 0;
			print(ap > bp ? "Fennec" : "Snuke");
			Console.Read();
		}

	}
}

