static class MainClass
{
    public static void Main(string[] args)
    {
        var n = Console.ReadLine().ToInt32();
        var nodes = new List<int>[n];
        for (int i = 0; i < n; i++)
        {
            nodes[i] = new List<int>();
        }

        for (int i = 0; i < n - 1; i++)
        {
            var ab = Console.ReadLine().SplittedStringToInt32List();
            var a = ab[0] - 1;
            var b = ab[1] - 1;
            nodes[a].Add(b);
            nodes[b].Add(a);
        }
        var queue = new Queue<int>();
        var dists = new int[n];
        queue.Enqueue(0);
        while (queue.Count > 0)
        {
            var point = queue.Dequeue();
            var todest = nodes[point];
            foreach (var item in todest)
            {
                if (dists[item] != 0)
                    continue;
                dists[item] = dists[point] + 1;
                queue.Enqueue(item);
            }
        }
        var tondist = dists[n - 1];
        dists[0] = 0;
        var keiro = new List<int>();
        var current = n - 1;
        while (tondist > 0)
        {
            var tozero = nodes[current];
            foreach (var item in tozero)
            {
                if (dists[item] == tondist - 1)
                {
                    tondist--;
                    keiro.Add(item);
                    current = item;
                    break;
                }
            }
        }
        keiro.Reverse();
        keiro.Add(n - 1);
        var limfennec = keiro[(int)Math.Ceiling(keiro.Count / 2.0) - 1];
        var colorofnode = new bool?[n];
        colorofnode[0] = true;
        colorofnode[n - 1] = false;
        colorofnode[limfennec] = true;
        queue.Clear();
        queue.Enqueue(0);
        while (queue.Count > 0)
        {
            var item = queue.Dequeue();
            var es = nodes[item];
            foreach (var item2 in es)
            {
                if (item2 != limfennec && colorofnode[item2] == null)
                {
                    colorofnode[item2] = true;
                    queue.Enqueue(item2);
                }
            }
        }
        var count = 0;
        foreach (var item in colorofnode)
        {
            if (item == true)
                count++;
        }
        var fennec = count;
        var snuke = n - count;
        if (fennec == snuke)
            Console.WriteLine("Snuke");
        else if (fennec > snuke)
            Console.WriteLine("Fennec");
        else
            Console.WriteLine("Snuke");

        Console.ReadLine();
    }



    #region
    public static int ParentCount;

    public static int[] Parents;
    public static int[] IfParentsChildrenCount;

    public static int[] Ranks;

    public static void InitializeUnionFind(int N)
    {
        Parents = new int[N];
        Ranks = new int[N];
        IfParentsChildrenCount = new int[N];
        for (int i = 0; i < N; i++)
        {
            Parents[i] = i;
            Ranks[i] = 0;
            IfParentsChildrenCount[i] = 1;
        }
        ParentCount = N + 1;
    }

    public static int Root(int a)
    {
        if (Parents[a] == a)
        {
            return a;
        }
        else
        {
            Parents[a] = Root(Parents[a]);
            return Parents[a];
        }
    }

    public static bool Same(int a, int b)
    {
        return Root(a) == Root(b);
    }

    public static void Unite(int a, int b)
    {
        var parentA = Root(a);
        var parentB = Root(b);
        if (parentA == parentB)
            return;
        if (Ranks[parentA] < Ranks[parentB])
        {
            Parents[parentA] = parentB;
            IfParentsChildrenCount[parentB] += IfParentsChildrenCount[parentA];
            ParentCount -= IfParentsChildrenCount[parentA];

            IfParentsChildrenCount[parentA] = 0;
        }
        else
        {
            Parents[parentB] = parentA;
            if (Ranks[parentA] == Ranks[parentB])
            {
                Ranks[parentA]++;
            }
            IfParentsChildrenCount[parentA] += IfParentsChildrenCount[parentB];
            ParentCount -= IfParentsChildrenCount[parentB];
            IfParentsChildrenCount[parentB] = 0;
        }
    }
