    public static void WarshallFloyd(char[,] d, int v)
    {
	for (int k = 0; k < v; k++)
	    for (int i = 0; i < v; i++)
		for (int j = 0; j < v; j++)
		    d[i, j] = (char) Math.Min(d[i, j], d[i, k] + d[k, j]);
    }
