class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var g = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            g[i] = new List<int>();
        }
        for (int i = 0; i < N - 1; i++)
        {
            var a = sc.ReadInt() - 1;
            var b = sc.ReadInt() - 1;
            g[a].Add(b);
            g[b].Add(a);
        }

        var color = new int[N];
        color[0] = 1;
        color[N - 1] = 2;

        var q1 = new Queue<int>();
        q1.Enqueue(0);
        var q2 = new Queue<int>();
        q2.Enqueue(N - 1);
        while (q1.Count > 0 || q2.Count > 0)
        {
            if (q1.Count > 0)
            {
                var now = q1.Dequeue();
                foreach (var next in g[now])
                {
                    if (color[next] != 0) continue;
                    color[next] = 1;
                    q1.Enqueue(next);
                }
            }
            if (q2.Count > 0)
            {
                var now = q2.Dequeue();
                foreach (var next in g[now])
                {
                    if (color[next] != 0) continue;
                    color[next] = 2;
                    q2.Enqueue(next);
                }
            }
        }

        var c1 = color.Count(c => c == 1);
        var c2 = N - c1;
        if (c1 > c2)
        {
            Console.WriteLine("Fennec");
        }
        else
        {
            Console.WriteLine("Snuke");
        }

    }

    static Scanner sc = new Scanner();
