static class Program
{
    public static void Main()
    {
#if !DEBUG
        Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
#endif
        Solve(new IO());
        Console.Out.Flush();
    }

    public static void Solve(IO io)
    {
        io.R();
        var n = io.I;

        var tree = new HashSet<int>[n + 1];
        for (var i = 1; i <= n; i++) tree[i] = new HashSet<int>();

        for (var i = 0; i < n - 1; i++)
        {
            io.R();
            var a = io.I;
            var b = io.I;
            tree[a].Add(b);
            tree[b].Add(a);
        }

        var path = Search(n, new HashSet<int>() { n }, tree);

        var black = 0;
        var white = 0;

        var top = 0;
        var last = path.Count - 1;
        var turn = Turn.Black;

        while (top < last)
        {
            if (turn == Turn.Black)
            {
                black++;
                black += GetChildren(path.ElementAt(top), new HashSet<int>(), tree, path.ElementAt(top), path.ElementAt(top + 1));
            }
            else
            {
                white++;
                white += GetChildren(path.ElementAt(last), new HashSet<int>(), tree, path.ElementAt(last), path.ElementAt(last - 1));
            }
        }

        if (black > white) io.Write("Fennec");
        else io.Write("Snuke");
    }

    enum Turn { Black, White };

    static HashSet<int> Search(int current, HashSet<int> path, HashSet<int>[] tree)
    {
        if (current == 1) return path;
        var t = new HashSet<int>(path);
        foreach (var p in tree[current])
        {
            if (t.Add(p)) return Search(p, t, tree);
        }
        return null;
    }

    static int GetChildren(int current, HashSet<int> nodes, HashSet<int>[] tree, int parent, int except)
    {
        foreach (var x in tree[current].Where(x => x != parent && x != except))
        {
            if (nodes.Add(x)) return GetChildren(x, nodes, tree, parent, except);
        }
        return nodes.Count;
    }
}

