using System.Collections.Generic;
using System.Linq;
using System;

class D
{
    static int N;
    static List<int>[] e;
    static void Main()
    {
        N = int.Parse(Console.ReadLine());
        e = new List<int>[N];
        if (N == 2)
        {
            Console.WriteLine("Snuke");
            return;
        }

        for (int i = 0; i < N; i++) e[i] = new List<int>();
        for (long i = 0; i < N - 1; i++)
        {
            var XY = Console.ReadLine().Split(' ').Select(x => int.Parse(x) - 1);
            e[XY.ElementAt(0)].Add(XY.ElementAt(1));
            e[XY.ElementAt(1)].Add(XY.ElementAt(0));
        }

        var Black = DFS(0, N - 1).Count(x => x);
        var White = DFS(N - 1, 0).Count(x => x);

        if (Black > White)
        {
            Console.WriteLine("Fennec");
        }
        else if (Black < White)
        {
            Console.WriteLine("Snuke");
        }
        else
        {
            var c = Black + White - N;
            if ((c & 1) == 0)
            {
                Console.WriteLine("Fennec");
            }
            else
            {
                Console.WriteLine("Snuke");
            }
        }
    }

    static bool[] DFS(int root, int goal)
    {
        var s = new Stack<int>();
        var v = new bool[N];
        s.Push(root);
        v[root] = true;
        while (s.Count > 0)
        {
            var current = s.Pop();
            foreach (var next in e[current])
            {
                if (!v[next] && next != goal)
                {
                    s.Push(next);
                    v[next] = true;
                }
            }
        }
        return v;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace AIZU {
	class Program {
		#region Reserve
		static int cin() { return cin(-1); }
		static int cin(int D) {
			string s = Console.ReadLine();
			if (string.IsNullOrEmpty(s))
				return D;
			return int.Parse(s);
		}
		static int[] cins(char spliter) {
			string s = Console.ReadLine();
			if (string.IsNullOrEmpty(s))
				return new int[] { };
			string[] ss = s.Split(spliter);
			var Res = new int[ss.Length];
			for (int i = 0; i < ss.Length; i++)
				Res[i] = int.Parse(ss[i]);
			return Res;
		}
		static int[] cins() { return cins(' '); }
		static void print(object j) { Console.WriteLine(j.ToString()); }
		static void print(string j) { Console.WriteLine(j); }
		#endregion

		static void Main(string[] args) {
			int N = cin();
			var F = new List<int>[N];
			for (int i = 0; i < N; i++) F[i] = new List<int>();
			for (int i = 0; i < N-1; i++) {
				int[] I = cins();
				F[I[0]-1].Add(I[1]-1);
				F[I[1]-1].Add(I[0]-1);
			}
			int h=0;
			Stack<int> J = new Stack<int>();
			HashSet<int> Hist = new HashSet<int>();
			J.Push(h);
			Hist.Add(h);
			while (J.Count != 0) {
				h = J.Pop();
				foreach (int f in F[h]) {
					if (f == N-1||f==N) continue;
					if (Hist.Contains(f)) continue;
					J.Push(f);
					Hist.Add(f);
				}
			}
			int ap = Hist.Count;
			Hist.Clear();
			h = N - 1;
			J.Push(h);
			Hist.Add(h);
			while (J.Count != 0) {
				h = J.Pop();
				foreach (int f in F[h]) {
					if (f == 0) continue;
					if (Hist.Contains(f)) continue;
					J.Push(f);
					Hist.Add(f);
				}
			}
			int bp = Hist.Count;
			int bridge = ap + bp - N;
			ap += bridge & 1;
			print(ap > bp ? "Fennec" : "Snuke");
			Console.Read();
		}

	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;
using System.Runtime.CompilerServices;
using static MyUtil;

class MyUtil
{
    public static int[] ReadIntArray()
    {
	return ReadLine().Split().Select(x => int.Parse(x)).ToArray();
    }

    public static void WarshallFloyd(char[,] d, int v)
    {
	for (int k = 0; k < v; k++)
	    for (int i = 0; i < v; i++)
		for (int j = 0; j < v; j++)
		    d[i, j] = (char) Math.Min(d[i, j], d[i, k] + d[k, j]);
    }
}

class Program
{
    public static void Main()
    {
	int n = int.Parse(ReadLine());
	var e = new char[n,n];
	for (int i = 0; i < n; i++)
	    for (int j = 0; j < n; j++)
		e[i, j] = (char) n;

	for (int i = 0; i < n-1; i++)
	{
	    var tmp = ReadIntArray();
	    int a = tmp[0] - 1, b = tmp[1] - 1;
	    e[a,b] = e[b,a] = (char) 1;
	}

	WarshallFloyd(e, n);

	int fmax=0, smax=0; // f: Fennec, s: Snuke

	try{

	for (int i = 1; i < n-1; i++)
	{
	    // calc fmax
	    int flen = (int) e[0, i];
	    int slen = (int) e[n-1, i];
	    if (flen <= slen) // >= because f moves first
	    {
		fmax++;
	    }
	    else
	    {
		smax++;
	    }
	}

	}
	catch
	{ WriteLine(0); } // dummy


	WriteLine(fmax > smax ? "Fennec" : "Snuke");
    }
}

using System;
using System.Collections;
