    {
        N = int.Parse(Console.ReadLine());
        e = new List<int>[N];

        for (int i = 0; i < N; i++) e[i] = new List<int>();
        for (long i = 0; i < N - 1; i++)
        {
            var XY = Console.ReadLine().Split(' ').Select(x => int.Parse(x) - 1);
            e[XY.ElementAt(0)].Add(XY.ElementAt(1));
            e[XY.ElementAt(1)].Add(XY.ElementAt(0));
        }

        var Black = DFS(0, N - 1).Count(x => x);
        var White = DFS(N - 1, 0).Count(x => x);
        var c = Black + White - N;

        if (Black > White)
        {
            Console.WriteLine("Fennec");
        }
        else if (Black < White)
        {
            Console.WriteLine("Snuke");
        }
        else
        {
            if (c == 0)
            {
                Console.WriteLine("Snuke");
            }
            else if ((c & 1) == 0)
            {
                Console.WriteLine("Fennec");
            }
            else
            {
                Console.WriteLine("Snuke");
            }
        }
    }

    static bool[] DFS(int root, int goal)
    {
        var s = new Stack<int>();
        var v = new bool[N];
        s.Push(root);
        v[root] = true;
        while (s.Count > 0)
        {
            var current = s.Pop();
            foreach (var next in e[current])
            {
                if (!v[next] && next != goal)
                {
                    s.Push(next);
                    v[next] = true;
                }
            }
        }
        return v;
    }
}

