class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }


    Scanner cin;


    List<int>[] es;
    int[] color;


    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        es = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            es[i] = new List<int>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int a = cin.nextInt() - 1;
            int b = cin.nextInt() - 1;
            es[a].Add(b);
            es[b].Add(a);
        }
        color = new int[N];
        for (int i = 0; i < N; i++)
        {
            color[i] = -1;
        }

        Queue<int> q = new Queue<int>();
        q.Enqueue(0);
        color[0] = 0;
        q.Enqueue(N - 1);
        color[N - 1] = 1;

        while(q.Count != 0)
        {
            int now = q.Dequeue();
            foreach (var next in es[now])
            {
                if (color[next] != -1) continue;
                color[next] = color[now];
                q.Enqueue(now);
            }
        }

        int A = 0;
        for (int i = 0; i < N; i++)
        {
            if (color[i] == 0) A++;
        }
        int B = N - A;

        if (A > B) Console.WriteLine("Fennec");
        else Console.WriteLine("Snuke");

    }
}



