    struct VertexAndStep
    {
        public readonly int vertex;
        public readonly int step;

        public VertexAndStep(int v, int s)
        {
            this.vertex = v;
            this.step = s;
        }
    }

    /// <summary>
    /// 無方向グラフを隣接リストで扱う
    /// </summary>
    class AdjacencyListUndirectedGraph
    {
        class Node
        {
            public int V { get; }
            private HashSet<int> nexts = new HashSet<int>();

            public Node(int v)
            {
                this.V = v;
            }

            public bool HasNext(int v)
            {
                return this.nexts.Contains(v);
            }
            public bool AddNext(int v)
            {
                if (v == this.V) throw new ArgumentException();
                return this.nexts.Add(v);
            }
            public IReadOnlyCollection<int> AllNexts()
            {
                return this.nexts;
            }
            public bool RemoveNext(int v)
            {
                return this.nexts.Remove(v);
            }
        }

        private readonly IReadOnlyDictionary<int, Node> nodeDic;

        public int VertexCount { get; }

        public AdjacencyListUndirectedGraph(int vertexCount, IEnumerable<Tuple<int, int>> edges)
        {
            if (vertexCount < 0) throw new ArgumentOutOfRangeException(nameof(vertexCount));
            this.VertexCount = vertexCount;

            this.nodeDic = Enumerable.Range(1, vertexCount).ToDictionary(v => v, v => new Node(v));

            foreach (var edge in edges)
            {
                this.AddEdge(edge.Item1, edge.Item2);
            }
        }
        public AdjacencyListUndirectedGraph(int vertexCount, IEnumerable<int[]> edges)
        {
            if (vertexCount < 0) throw new ArgumentOutOfRangeException(nameof(vertexCount));
            this.VertexCount = vertexCount;

            this.nodeDic = Enumerable.Range(1, vertexCount).ToDictionary(v => v, v => new Node(v));

            foreach (var edge in edges)
            {
                if (edge.Length != 2) throw new ArgumentException("invalid edge length " + edge.Length);
                this.AddEdge(edge[0], edge[1]);
            }
        }

        public bool AddEdge(int v1, int v2)
        {
            if (!this.nodeDic[v1].AddNext(v2)) return false;
            if (!this.nodeDic[v2].AddNext(v1))
            {
                throw new InvalidProgramException("invalid state " + v1 + "," + v2);
            }
            return true;
        }
        /// <summary>
        /// すべての点をとおるパスを深さ優先で列挙する
        /// </summary>
        /// <param name="start"></param>
        /// <returns></returns>
        public IEnumerable<int[]> EnumeratePathesDFS(int start)
        {
            return enumeratePathes(start, new int[] { });
        }
        private IEnumerable<int[]> enumeratePathes(int v, int[] accessed)
        {
            accessed = accessed.Concat(new[] { v }).ToArray();
            if (accessed.Length == this.VertexCount)
            {
                yield return accessed;
                yield break;
            }

            var nexts = this.nodeDic[v].AllNexts();

            foreach (var node in nexts)
            {
                if (accessed.Contains(node)) continue;

                foreach (var path in enumeratePathes(node, accessed))
                {
                    yield return path;
                }
            }
        }

        /// <summary>
        /// 指定した始点からの到達点を幅優先で列挙する
        /// </summary>
        /// <param name="start"></param>
        /// <returns></returns>
        public IEnumerable<VertexAndStep> EnumerateVertexesBFS(int start)
        {
            var queue = new Queue<VertexAndStep>();
            queue.Enqueue(new VertexAndStep(start, 0));

            var accessed = new HashSet<int>();

            while(queue.Any())
            {
                var item = queue.Dequeue();
                accessed.Add(item.vertex);
                yield return item;

                var node = this.nodeDic[item.vertex];

                foreach (var next in node.AllNexts())
                {
                    if (accessed.Contains(next)) continue;
                    //if (queue.Any(q => q.vertex == next)) continue;

                    queue.Enqueue(new VertexAndStep(next, item.step + 1));
                }
            }

        }

        public bool HasEdge(int v1, int v2)
        {
            return this.nodeDic[v1].HasNext(v2);
        }


        /// <summary>
        /// グラフが連結かどうかを深さ優先で調べる
        /// </summary>
        /// <returns></returns>
        public bool IsConnectedDFS()
        {
            return isConnectedDfs(1, new HashSet<int>());
        }

        private bool isConnectedDfs(int v, HashSet<int> accessed)
        {
            accessed.Add(v);
            if (accessed.Count == this.VertexCount) return true;

            foreach (var node in this.nodeDic[v].AllNexts())
            {
                if (accessed.Contains(node)) continue;

                if (isConnectedDfs(node, accessed)) return true;
            }
            return false;
        }

        public bool RemoveEdge(int v1, int v2)
        {
            if (this.nodeDic[v1].RemoveNext(v2))
            {
                if (!this.nodeDic[v2].RemoveNext(v1))
                {
                    throw new InvalidProgramException("invalid state " + v1 + "," + v2);
                }
                return true;
            }
            return false;
        }
    }

    static class IOUtils
    {
        public static (int a, int b) Read2Ints()
        {
            var vals = ReadInts();
            return (vals[0], vals[1]);
        }
        public static (int a, int b, int c) Read3Ints()
        {
            var vals = ReadInts();
            return (vals[0], vals[1], vals[2]);
        }
        public static IEnumerable<int[]> ReadIntLines(int count)
        {
            for (int i = 0; i < count; i++)
            {
                yield return ReadInts();
            }
        }
        public static IEnumerable<long[]> ReadLongLines(int count)
        {
            for (int i = 0; i < count; i++)
            {
                yield return ReadLongs();
            }
        }
        public static int ReadInt()
        {
            return int.Parse(Console.ReadLine());
        }
        public static long ReadLong()
        {
            return long.Parse(Console.ReadLine());
        }
        public static ulong ReadUlong()
        {
            return ulong.Parse(Console.ReadLine());
        }
        public static int[] ReadInts()
        {
            return Console.ReadLine().Split(' ').Select(v => int.Parse(v)).ToArray();
        }
        public static long[] ReadLongs()
        {
            return Console.ReadLine().Split(' ').Select(v => long.Parse(v)).ToArray();
        }

        public static void WriteNums(params int[] nums)
        {
            Console.WriteLine(string.Join(" ", nums));
        }
    }



    /// <summary>
    /// ダイクストラ法で最短経路を計算
    /// </summary>
    class Dijkstra
    {
        readonly int vertexCount;
        readonly bool hasDirection;
        readonly IReadOnlyDictionary<int, Node> nodeDic;

        int? start;
        int? goal;

        public struct Edge
        {
            public readonly int dest;
            public readonly int weight;

            public Edge(int dest, int weight)
            {
                this.dest = dest;
                this.weight = weight;
            }
        }

        class Node
        {
            public int V { get; }
            private readonly Dictionary<int, Edge> nextDic = new Dictionary<int, Edge>();

            public Node(int v)
            {
                this.V = v;
            }

            public bool HasNext(int v)
            {
                return this.nextDic.ContainsKey(v);
            }
            public void AddNext(int v, int weight)
            {
                if (v == this.V) throw new ArgumentException("ループには対応していません");
                this.nextDic[v] = new Edge(v, weight);
            }
            public IReadOnlyCollection<Edge> AllNexts()
            {
                return this.nextDic.Values;
            }
            public bool RemoveNext(int v)
            {
                return this.nextDic.Remove(v);
            }
            public int? TryGetWeight(int v)
            {
                Edge res;
                return this.nextDic.TryGetValue(v, out res) ? res.weight : (int?)null;
            }

            public int? CurrentWeight { get; private set; }
            public int? CurrentPreVertex { get; private set; }
            //public bool IsCommitted { get; private set; }
            //public void Commit()
            //{
            //    this.IsCommitted = true;
            //}

            public bool TryUpdateWeight(int weight, int? pre)
            {
//                if (this.IsCommitted) return false;
                if (CurrentWeight == null || weight < CurrentWeight.Value)
                {
                    this.CurrentPreVertex = pre;
                    this.CurrentWeight = weight;
                    return true;
                }
                return false;
            }

        }

        public Dijkstra(int vertexCount, bool hasDirection)
        {
            this.vertexCount = vertexCount;
            this.hasDirection = hasDirection;

            this.nodeDic = Enumerable.Range(1, vertexCount)
                                .ToDictionary(v => v, v => new Node(v));
        }
        public void AddEdge(int v1, int v2, int weight)
        {
            if (weight < 0) throw new ArgumentOutOfRangeException(nameof(weight));
            this.nodeDic[v1].AddNext(v2, weight);
            if (!this.hasDirection)
            {
                this.nodeDic[v2].AddNext(v1, weight);
            }
        }
        public bool RemoveEdge(int v1, int v2)
        {
            if (!this.nodeDic[v1].RemoveNext(v2)) return false;
            if (!this.hasDirection)
            {
                if (!this.nodeDic[v2].RemoveNext(v1))
                {
                    throw new InvalidProgramException("invalid state " + v1 + "," + v2);
                }
            }
            return true;
        }

        public void Calc(int start, int? goal)
        {
            if (this.start.HasValue)
            {
                throw new InvalidOperationException("計算実行済み");
            }
            this.start = start;
            this.goal = goal;

            var queue = new PriorityQueue<Node>(vertexCount, n => (n.CurrentWeight ?? 0) * -1);
            this.nodeDic[start].TryUpdateWeight(0, null);
            queue.Enqueue(this.nodeDic[start]);

            while (queue.Count > 0)
            {
                var pre = queue.Dequeue();
//                pre.Commit();
                if (goal != null && pre.V == goal) break;

                foreach (var edge in pre.AllNexts())
                {
                    var newWeight = pre.CurrentWeight.Value + edge.weight;
                    var nextNode = this.nodeDic[edge.dest];

                    if (nextNode.TryUpdateWeight(newWeight, pre.V))
                    {
                        queue.Enqueue(this.nodeDic[edge.dest]);
                    }
                }
            }
        }

        public int? GetPreVertex(int v)
        {
            if (this.start == null) throw new InvalidOperationException("計算未実行");

            return this.nodeDic[v].CurrentPreVertex;
        }
        public int? GetWeight(int v)
        {
            if (this.start == null) throw new InvalidOperationException("計算未実行");

            return this.nodeDic[v].CurrentWeight;
        }

        public List<int> GetRoute(int v)
        {
            if (this.start == null) throw new InvalidOperationException("計算未実行");

            var revList = new List<int>();
            revList.Add(v);
            var last = v;
            while(true)
            {
                if (last == this.start) break;

                var node = this.nodeDic[last].CurrentPreVertex;
                if (node == null) break;
                last = node.Value;
                revList.Add(node.Value);
            }
            revList.Reverse();
            return revList;
        }


    }

       class PriorityQueue<T>
    {
        readonly T[] array;
        readonly Func<T, int> valueSelector;
        public int Count { get; private set; }


        public PriorityQueue(int capacity, Func<T, int> valueSelector)
        {
            this.array = new T[capacity];
            this.valueSelector = valueSelector;
        }

        public void Enqueue(T item)
        {
            this.array[this.Count] = item;
            this.Count += 1;
            this.UpHeap();
        }

        public T Dequeue()
        {
            // 先頭要素を末尾にして再構成
            this.Swap(0, this.Count - 1);
            this.Count -= 1;
            this.DownHeap();

            return this.array[this.Count];
        }


        private void UpHeap()
        {
            var n = this.Count - 1;
            while (n != 0)
            {
                // 親要素の座標
                var parent = (n - 1) / 2;

                if (this.valueSelector(this.array[n]) > this.valueSelector(this.array[parent]))
                {
                    this.Swap(n, parent);
                    n = parent;
                }
                else
                {
                    break;
                }
            }
        }

        private void DownHeap()
        {
            var parent = 0;
            while (true)
            {
                var child = 2 * parent + 1;
                if (child > this.Count - 1) break;

                if (child < this.Count - 1 && this.valueSelector(this.array[child]) < this.valueSelector(this.array[child + 1]))
                {
                    // 左より右の子のほうが大きい値の場合、右を入れ替え対象にする
                    child += 1;
                }

                if (this.valueSelector(this.array[parent]) < this.valueSelector(this.array[child]))
                {
                    this.Swap(parent, child);
                    parent = child;
                }
                else
                {
                    break;
                }
            }
        }

        private void Swap(int a, int b)
        {
            var tmp = this.array[a];
            this.array[a] = this.array[b];
            this.array[b] = tmp;
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
	public class Program
	{
		// TLEがないやつ
		// http://abc067.contest.atcoder.jp/submissions/1431970
		// クラスにしたやつ
		// http://abc067.contest.atcoder.jp/submissions/1431941

		static string フェネックの名前 = "Fennec";
		static string すぬけくんの名前 = "Snuke";

		enum マスの色
		{
			透明 = 0,
			黒,
			白,
		};

		enum プレイヤー
		{
			謎の第三者 = マスの色.透明,
			フェネック = マスの色.黒,
			すぬけくん = マスの色.白,
		};

		public static void Main(string[] args)
		{
			var str = Console.ReadLine().Split(' ');
			var マスの数 = int.Parse(str[0]); // 2 ~ 10^5
			var 道の数 = マスの数 - 1;
			var マスの情報 = new List<int>[マスの数 + 1];

			for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
			{
				マスの情報[マスの番号] = new List<int>();
			}

			for (var 道の番号 = 0; 道の番号 < 道の数; 道の番号++)
			{
				var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
				マスの情報[一つの道の情報[0]].Add(一つの道の情報[1]);
				マスの情報[一つの道の情報[1]].Add(一つの道の情報[0]);
			}

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var 合計シミュレート回数 = Math.Min(20000, Math.Max(1, 200000000 / (マスの数 * マスの数) ));
			int 繰り返す数 = 合計シミュレート回数;
			var マスの色の情報 = new マスの色[マスの数 + 1];
			var フェネックの最初のマス = 1;
			var すぬけくんの最初のマス = マスの数;
			var 乱数 = new System.Random(0);
			var フェネックの定跡本 = new List<int>();
			var すぬけくんの定跡本 = new List<int>();

			var 生き延びた最大ターン = -1;
			var フェネックの生き延びた最大ターン = -1;
			var すぬけくんの生き延びた最大ターン = -1;
			var 只今の勝者 = プレイヤー.謎の第三者;

			var 最大ターン数 = 1 + マスの数 / 2;

			var コールド勝ちのルールが有る = 繰り返す数 == 1;
			var コールド勝ちに必要なマスの数 = 10;
			var コールド勝ちに必要なターン = 最大ターン数 / 2;
			var フェネックとすぬけくんが隣接した = false;

			Action<List<int>, int, マスの色> 進めるマスを更新する = (進める箇所, 進むマスの番号, 自分の色) =>
			{
				var 進んだ先のマスの情報 = マスの情報[進むマスの番号];
				for (var i = 0; i < 進んだ先のマスの情報.Count; i++)
				{
					if (マスの色の情報[進んだ先のマスの情報[i]] == マスの色.透明)
					{
						進める箇所.Add(進んだ先のマスの情報[i]);
						continue;
					}

					if (マスの色の情報[進んだ先のマスの情報[i]] != 自分の色)
					{
						フェネックとすぬけくんが隣接した = true;
					}
				}
			};

			Action シミュレート = () =>
			{
				var フェネックの進める箇所 = new List<int>();
				var すぬけくんの進める箇所 = new List<int>();

				var フェネックの今回の選択 = new List<int>();
				var すぬけくんの今回の選択 = new List<int>();

				フェネックとすぬけくんが隣接した = false;

				for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
				{
					マスの色の情報[マスの番号] = マスの色.透明;
				}
				マスの色の情報[フェネックの最初のマス] = マスの色.黒;
				マスの色の情報[すぬけくんの最初のマス] = マスの色.白;

				進めるマスを更新する(フェネックの進める箇所, フェネックの最初のマス, マスの色.黒);
				進めるマスを更新する(すぬけくんの進める箇所, すぬけくんの最初のマス, マスの色.白);

				for (var ターン = 0; ターン < 最大ターン数; ターン++)
				{
					// 先行はフェネック
					bool フェネックが移動していない = true;

					if (フェネックの進める箇所.Count > 1)
					{
						var 次の移動候補で一番優先したいところ = ターン < フェネックの定跡本.Count ? フェネックの定跡本[ターン] : 乱数.Next(0, フェネックの進める箇所.Count);
						var 保存領域 = フェネックの進める箇所[0];
						フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番優先したいところ];
						フェネックの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
					}
					for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
					{
						var 移動候補 = フェネックの進める箇所[移動候補の番号];
						if (マスの色の情報[移動候補] == マスの色.透明)
						{
							フェネックの今回の選択.Add(移動候補の番号);
							マスの色の情報[移動候補] = マスの色.黒;
							進めるマスを更新する(フェネックの進める箇所, 移動候補, マスの色.黒);
							フェネックが移動していない = false;
							break;
						}
						フェネックの進める箇所.RemoveAt(移動候補の番号);
						移動候補の番号--;
					}

					if (フェネックが移動していない)
					{
						if (生き延びた最大ターン < ターン)
						{
							只今の勝者 = プレイヤー.すぬけくん;
							生き延びた最大ターン = ターン;
						}
						if (すぬけくんの生き延びた最大ターン < ターン)
						{
							すぬけくんの生き延びた最大ターン = ターン;
							フェネックの定跡本.Clear();
							すぬけくんの定跡本 = すぬけくんの今回の選択;
						}
						break;
					}

					bool すぬけくんが移動していない = true;
					if (すぬけくんの進める箇所.Count > 1)
					{
						var 次の移動候補で一番優先したいところ = ターン < すぬけくんの定跡本.Count ? すぬけくんの定跡本[ターン] : 乱数.Next(0, すぬけくんの進める箇所.Count);
						var 保存領域 = すぬけくんの進める箇所[0];
						すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番優先したいところ];
						すぬけくんの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
					}
					for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
					{
						var 移動候補 = すぬけくんの進める箇所[移動候補の番号];
						if (マスの色の情報[移動候補] == マスの色.透明)
						{
							すぬけくんの今回の選択.Add(移動候補の番号);
							マスの色の情報[移動候補] = マスの色.白;
							進めるマスを更新する(すぬけくんの進める箇所, 移動候補, マスの色.白);
							すぬけくんが移動していない = false;
							break;
						}
						すぬけくんの進める箇所.RemoveAt(移動候補の番号);
						移動候補の番号--;
					}

					if (すぬけくんが移動していない)
					{
						if (生き延びた最大ターン < ターン)
						{
							只今の勝者 = プレイヤー.フェネック;
							生き延びた最大ターン = ターン;
						}
						if (フェネックの生き延びた最大ターン < ターン)
						{
							フェネックの生き延びた最大ターン = ターン;
							フェネックの定跡本 = フェネックの今回の選択;
							すぬけくんの定跡本.Clear();
						}
						break;
					}

					// 進める箇所がいっぱいあったらコールド勝ち
					// 隣接してたら最後まで続ける
					if (コールド勝ちのルールが有る && コールド勝ちに必要なターン < ターン && !フェネックとすぬけくんが隣接した)
					{
						if (フェネックの進める箇所.Count > すぬけくんの進める箇所.Count)
						{
							if (フェネックの進める箇所.Count > コールド勝ちに必要なマスの数)
							{
								只今の勝者 = プレイヤー.フェネック;
								break;
							}
						}
						else
						{
							if (すぬけくんの進める箇所.Count > コールド勝ちに必要なマスの数)
							{
								只今の勝者 = プレイヤー.すぬけくん;
								break;
							}
						}
					}
				}
			};

			for (var 世代 = 0; 世代 < 繰り返す数; 世代++)
			{
				シミュレート();
			}

			Console.WriteLine(只今の勝者 == プレイヤー.フェネック ? フェネックの名前 : すぬけくんの名前);
		}
	}
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Numerics;
using System.Text;
using System.Threading.Tasks;

namespace AtCoder
{
    partial class Program
    {
        static long mod = 1000000007;
        static void Swap<T>(ref T a, ref T b) { T temp = a; a = b; b = temp; }
        static void Main()
        {
            Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Console.Out.Flush();
            Console.ReadKey();
        }

        //ここから
        static void Solve()
        {
            int N = GetInt();
            var ab = GetIntJaggedArray(N-1);
            var A = Enumerable.Range(0, N).ToDictionary(i => i, i => new List<int>());
            for(int i = 0; i < N - 1; i++)
            {
                var a = ab[i][0] - 1;
                var b = ab[i][1] - 1;
                A[a].Add(b);
                A[b].Add(a);
            }

            var queue = new Queue<int>();
            var fennec = Enumerable.Repeat(-1, N).ToArray();
            fennec[0] = 0;
            queue.Enqueue(0);
            while (queue.Count > 0)
            {
                var now = queue.Dequeue();
                foreach(var next in A[now])
                {
                    if (fennec[next] == -1)
                    {
                        fennec[next] = fennec[now] + 1;
                        queue.Enqueue(next);
                    }
                }
            }

            var snuke = Enumerable.Repeat(-1, N).ToArray();
            snuke[N - 1] = 0;
            queue.Enqueue(N - 1);
            while (queue.Count > 0)
            {
                var now = queue.Dequeue();
                foreach(var next in A[now])
                {
                    if (snuke[next] == -1)
                    {
                        snuke[next] = snuke[now] + 1;
                        queue.Enqueue(next);
                    }
                }
            }

            var F = Enumerable.Range(0, N).Count(i => fennec[i] <= snuke[i]);
            var S = N - F;
            var ans = F > S ? "Fennec" : "Snuke";

            Console.WriteLine(ans);
        }


    }

