				var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
				マスの情報[一つの道の情報[0]].Add(一つの道の情報[1]);
				マスの情報[一つの道の情報[1]].Add(一つの道の情報[0]);
			}

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var 合計シミュレート回数 = Math.Min(1000, Math.Max(1, 2000000000 / (マスの数 * マスの数) ));
			int 一回のシミュレート回数 = Math.Max(1, (int)Math.Sqrt(合計シミュレート回数) / 2);
			int 繰り返す数 = Math.Max(1, 合計シミュレート回数 / 一回のシミュレート回数);
			var マスの色の情報 = new マスの色[マスの数 + 1];
			var フェネックの最初のマス = 1;
			var すぬけくんの最初のマス = マスの数;
			var 乱数 = new System.Random();
			var フェネックの定跡本 = new List<int>();
			var すぬけくんの定跡本 = new List<int>();

			var 生き延びた最大ターン = -1;
			var フェネックの生き延びた最大ターン = -1;
			var すぬけくんの生き延びた最大ターン = -1;
			var 只今の勝者 = プレイヤー.謎の第三者;

			Func<int, List<int>, List<int>, プレイヤー> シミュレート = (シミュレート回数, フェネックの定跡, すぬけくんの定跡) =>
			{
				var 新しいフェネックの定跡 = new List<int>();
				var 新しいすぬけくんの定跡 = new List<int>();

				for (var 回数 = 0; 回数 < シミュレート回数; 回数++)
				{
					var フェネックの進める箇所 = new List<int>();
					var すぬけくんの進める箇所 = new List<int>();

					var フェネックの今回の選択 = new List<int>();
					var すぬけくんの今回の選択 = new List<int>();

					for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
					{
						マスの色の情報[マスの番号] = マスの色.透明;
					}
					マスの色の情報[フェネックの最初のマス] = マスの色.黒;
					マスの色の情報[すぬけくんの最初のマス] = マスの色.白;

					フェネックの進める箇所.AddRange(マスの情報[フェネックの最初のマス]);
					すぬけくんの進める箇所.AddRange(マスの情報[すぬけくんの最初のマス]);

					var 最大ターン数 = 1 + マスの数 / 2;
					for (var ターン = 0; ターン < 最大ターン数; ターン++)
					{
						// 先行はフェネック
						bool フェネックが移動していない = true;
						if (フェネックの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < フェネックの定跡.Count ? フェネックの定跡[ターン] : 乱数.Next(0, フェネックの進める箇所.Count);
							var 保存領域 = フェネックの進める箇所[0];
							フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番優先したいところ];
							フェネックの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = フェネックの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								フェネックの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.黒;
								フェネックの進める箇所.AddRange(マスの情報[移動候補]);
								フェネックが移動していない = false;
								break;
							}
							フェネックの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (フェネックが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.すぬけくん;
								生き延びた最大ターン = ターン;
							}
							if (すぬけくんの生き延びた最大ターン < ターン)
							{
								すぬけくんの生き延びた最大ターン = ターン;
								新しいすぬけくんの定跡 = すぬけくんの今回の選択;
							}
							break;
						}

						bool すぬけくんが移動していない = true;
						if (すぬけくんの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < すぬけくんの定跡.Count ? すぬけくんの定跡[ターン] : 乱数.Next(0, すぬけくんの進める箇所.Count);
							var 保存領域 = すぬけくんの進める箇所[0];
							すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番優先したいところ];
							すぬけくんの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = すぬけくんの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								すぬけくんの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.白;
								すぬけくんの進める箇所.AddRange(マスの情報[移動候補]);
								すぬけくんが移動していない = false;
								break;
							}
							すぬけくんの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (すぬけくんが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.フェネック;
								生き延びた最大ターン = ターン;
							}
							if (フェネックの生き延びた最大ターン < ターン)
							{
								フェネックの生き延びた最大ターン = ターン;
								新しいフェネックの定跡 = フェネックの今回の選択;
							}
							break;
						}
					}
				}

				switch (只今の勝者)
				{
					case プレイヤー.フェネック:
						フェネックの定跡 = 新しいフェネックの定跡.Take(新しいフェネックの定跡.Count / 2).ToList();
						break;
					case プレイヤー.すぬけくん:
						すぬけくんの定跡 = 新しいすぬけくんの定跡.Take(新しいすぬけくんの定跡.Count / 2).ToList();
						break;
				}

				return 只今の勝者;
			};

			for (var 世代 = 0; 世代 < 繰り返す数; 世代++)
			{
				シミュレート(一回のシミュレート回数, フェネックの定跡本, すぬけくんの定跡本);
			}

			Console.WriteLine(只今の勝者 == プレイヤー.フェネック ? フェネックの名前 : すぬけくんの名前);
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static string InputPattern = "InputX";

    static List<string> GetInputList()
    {
        var WillReturn = new List<string>();

        if (InputPattern == "Input1") {
            WillReturn.Add("7");
            WillReturn.Add("3 6");
            WillReturn.Add("1 2");
            WillReturn.Add("3 1");
            WillReturn.Add("7 4");
            WillReturn.Add("5 7");
            WillReturn.Add("1 4");
            //Fennec
        }
        else if (InputPattern == "Input2") {
            WillReturn.Add("4");
            WillReturn.Add("1 4");
            WillReturn.Add("4 2");
            WillReturn.Add("2 3");
            //Snuke
        }
        else {
            string wkStr;
            while ((wkStr = Console.ReadLine()) != null) WillReturn.Add(wkStr);
        }
        return WillReturn;
    }

    static int N;

    //移動先のList[移動元]で辺を表現
    static Dictionary<int, List<int>> EdgeDict = new Dictionary<int, List<int>>();

    static void Main()
    {
        List<string> InputList = GetInputList();
        N = int.Parse(InputList[0]);

        foreach (string EachStr in InputList.Skip(1)) {
            int[] wkArr = EachStr.Split(' ').Select(X => int.Parse(X)).ToArray();

            if (EdgeDict.ContainsKey(wkArr[0]) == false) {
                EdgeDict.Add(wkArr[0], new List<int>());
            }
            EdgeDict[wkArr[0]].Add(wkArr[1]);

            if (EdgeDict.ContainsKey(wkArr[1]) == false) {
                EdgeDict.Add(wkArr[1], new List<int>());
            }
            EdgeDict[wkArr[1]].Add(wkArr[0]);
        }
        int[] KyoriArr1 = DeriveKyori(1);
        int[] KyoriArr2 = DeriveKyori(N);

        //for (int I = 1; I <= KyoriArr1.GetUpperBound(0); I++) {
        //    Console.WriteLine("KyoriArr1[{0}]={1}", I, KyoriArr1[I]);
        //}

        int Node1Cnt = 0;
        int Node2Cnt = 0;
        for (int I = 1; I <= N; I++) {
            if (KyoriArr1[I] <= KyoriArr2[I]) Node1Cnt++;
            else Node2Cnt++;
        }
        Console.WriteLine(Node1Cnt > Node2Cnt ? "Fennec" : "Snuke");
    }

    struct JyoutaiDef
    {
        internal int CurrNode;
        internal int Level;
    }

    //始点のノードを引数として、各ノードまでの距離を返す
    static int[] DeriveKyori(int pNode)
    {
        int[] KyoriArr = new int[N + 1];

        var Que = new Queue<JyoutaiDef>();
        JyoutaiDef WillEnqueue;
        WillEnqueue.CurrNode = pNode;
        WillEnqueue.Level = 0;

        Que.Enqueue(WillEnqueue);
        var VisitedSet = new HashSet<int>();

        while (Que.Count > 0) {
            JyoutaiDef Dequeued = Que.Dequeue();

            if (VisitedSet.Add(Dequeued.CurrNode) == false) continue;
            KyoriArr[Dequeued.CurrNode] = Dequeued.Level;

            if (EdgeDict.ContainsKey(Dequeued.CurrNode)) {
                foreach (int EachNode in EdgeDict[Dequeued.CurrNode]) {
                    WillEnqueue.CurrNode = EachNode;
                    WillEnqueue.Level = Dequeued.Level + 1;
                    Que.Enqueue(WillEnqueue);
                }
            }
        }
        return KyoriArr;
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;

namespace CF
{
    internal class Program
    {
        private static void Main(string[] args)
        {
            using (var sr = new InputReader(Console.In))
            //using (var sr = new InputReader(new StreamReader("input.txt")))
            {
                var task = new Task();
                using (var sw = Console.Out) {
                    //using (var sw = new StreamWriter("output.txt")) {
                    task.Solve(sr, sw);
                    //Console.ReadKey();
                }
            }
        }
    }

    internal class Task
    {
        public void Solve(InputReader sr, TextWriter sw)
        {
            var n = sr.NextInt32();
            var graph = new Graph(n);
            for (var i = 0; i < n - 1; i++) {
                var input = sr.ReadArrayOfInt32();
                graph.Insert(input[0] - 1, input[1] - 1);
            }
            sw.WriteLine(graph.Solution());
        }
    }

    class Graph
    {
        private readonly List<int>[] edges;
        private readonly Color[] colors;

        public Graph(int n)
        {
            edges = new List<int>[n];
            colors = new Color[n];
        }

        public void Insert(int x, int y)
        {
            if (edges[x] == null) {
                edges[x] = new List<int>();
            }
            edges[x].Add(y);
            if (edges[y] == null) {
                edges[y] = new List<int>();
            }
            edges[y].Add(x);
        }

        public string Solution()
        {
            var path = new List<int>();
            var visited = new bool[edges.Length];
            DfsVisit(0, visited, path);
            path.RemoveAt(0);
            for (var i = 0; i < path.Count / 2; i++) {
                var v = path[i];
                colors[v] = Color.Black;
                var revV = path.Count - 1 - i;
                colors[revV] = Color.White;
            }
            if (path.Count % 2 == 1) {
                colors[(path.Count - 1) / 2] = Color.Black;
            }
            colors[0] = Color.Black;
            colors[edges.Length - 1] = Color.White;
            var isFennecLast = path.Count % 2 == 1;
            var fennecSteps = 0;
            var snukeSteps = 0;
            for (var i = 0; i < edges.Length; i++) {
                if (colors[i] == Color.Black) {
                    fennecSteps += DfsVisit(i, 0, Color.Black);
                }
            }
            for (var i = 0; i < edges.Length; i++)
            {
                if (colors[i] == Color.White)
                {
                    snukeSteps += DfsVisit(i, 0, Color.White);
                }
            }
            if (isFennecLast) {
                if (fennecSteps >= snukeSteps) {
                    return "Fennec";
                }
                return "Snuke";
            }
            else {
                if (snukeSteps >= fennecSteps) {
                    return "Snuke";
                }

                return "Fennec";
            }
        }

        private int DfsVisit(int v, int curr, Color color)
        {
            colors[v] = color;
            var result = curr;
            for (var i = 0; i < edges[v].Count; i++) {
                if (colors[edges[v][i]] == Color.None) {
                    var next = DfsVisit(edges[v][i], curr + 1, color);
                    result += (next - curr);
                }
            }

            return result;
        }

        private bool DfsVisit(int v, bool[] visited, List<int> path)
        {
            if (v == edges.Length - 1)
                return true;
            visited[v] = true;
            path.Add(v);
            for (var i = 0; i < edges[v].Count; i++) {
                if (!visited[edges[v][i]]) {
                    if (DfsVisit(edges[v][i], visited, path)) {
                        return true;
                    }
                }
            }
            path.RemoveAt(path.Count - 1);
            return false;
        }
    }

    enum Color
    {
        None,
        White,
        Black
    }
}

internal class InputReader : IDisposable
{
    private bool isDispose;
    private readonly TextReader sr;

    public InputReader(TextReader stream)
    {
        sr = stream;
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    public string NextString()
    {
        var result = sr.ReadLine();
        return result;
    }

    public int NextInt32()
    {
        return Int32.Parse(NextString());
    }

    public long NextInt64()
    {
        return Int64.Parse(NextString());
    }

    public string[] NextSplitStrings()
    {
        return NextString()
            .Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
    }

    public T[] ReadArray<T>(Func<string, CultureInfo, T> func)
    {
        return NextSplitStrings()
            .Select(s => func(s, CultureInfo.InvariantCulture))
            .ToArray();
    }

    public int[] ReadArrayOfInt32()
    {
        return ReadArray(Int32.Parse);
    }

    public long[] ReadArrayOfInt64()
    {
        return ReadArray(Int64.Parse);
    }

    public T[] ReadArrayFromString<T>(Func<string, CultureInfo, T> func, string str)
    {
        return
            str.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(s => func(s, CultureInfo.InvariantCulture))
                .ToArray();
    }

    protected void Dispose(bool dispose)
    {
        if (!isDispose) {
            if (dispose)
                sr.Close();
            isDispose = true;
        }
    }

    ~InputReader()
    {
        Dispose(false);
    }
}

