using System.Linq;
using System.Collections;
using System.Collections.Generic;
using static System.Console;
using static System.Math;

namespace AtCorder
{
    class Program
    {
        static void Main(string[] args)
        {
            new Program().Solve(new ConsoleInput(Console.In, ' '));
        }
        public void Solve(ConsoleInput cin)
        {
            var N = cin.ReadInt;
            var Node = new List<int>[N];
            for (int i = 0; i < N; i++)
            {
                Node[i] = new List<int>();
            }
            for (int i = 0; i < N - 1; i++)
            {
                var a = cin.ReadInt;
                var b = cin.ReadInt;
                Node[a - 1].Add(b);
                Node[b - 1].Add(a);
            }
            var from1 = new int[N];
            var Q = new Queue<int>();
            var flag = new bool[N];
            Q.Enqueue(1);
            flag[0] = true;
            Q.Enqueue(0);
            var deep = 0;
            while (true)
            {
                var now = Q.Dequeue();
                if (now == 0)
                {
                    if (Q.Count == 0) break;
                    deep++;
                    Q.Enqueue(0);
                    continue;
                }
                from1[now - 1] = deep;
                flag[now - 1] = true;
                var size = Node[now - 1].Count;
                for (int i = 0; i < size; i++)
                {
                    if (!flag[Node[now - 1][i] - 1])
                    {
                        Q.Enqueue(Node[now - 1][i]);
                    }
                }
            }
            Q.Clear();
            var fromN = new int[N];
            for (int i = 0; i < N; i++)
            {
                flag[i] = false;
            }
            Q.Enqueue(N);
            flag[N - 1] = true;
            Q.Enqueue(0);
            deep = 0;
            while (true)
            {
                var now = Q.Dequeue();
                if (now == 0)
                {
                    if (Q.Count == 0) break;
                    deep++;
                    Q.Enqueue(0);
                    continue;
                }
                fromN[now - 1] = deep;
                flag[now - 1] = true;
                var size = Node[now - 1].Count;
                for (int i = 0; i < size; i++)
                {
                    if (!flag[Node[now - 1][i] - 1])
                    {
                        Q.Enqueue(Node[now - 1][i]);
                    }
                }
            }
            var black = 0;
            var white = 0;
            for (int i = 0; i < N; i++)
            {
                if (from1[i] <= fromN[i])
                {
                    black++;
                }
                else
                {
                    white++;
                }
            }
            if (black > white)
            {
                WriteLine("Fennec");
            }
            else
            {
                WriteLine("Snuke");
            }
        }

