    class Solver
    {
        private long N;
        private long[] A;
        private long[] B;

        public void Solve()
        {
            @in(out N);
            @in(N - 1, out A, out B);


            Dictionary<long, HashSet<long>> tree = new Dictionary<long, HashSet<long>>();
            for (int i = 1; i < N + 1; i++)
            {
                tree.Add(i, new HashSet<long>());
            }


            for (int i = 0; i < N - 1; i++)
            {
                tree[A[i]].Add(B[i]);
                tree[B[i]].Add(A[i]);
            }

            long[] cost1 = new long[N + 1];
            cost1[1] = 0;
            long[] costN = new long[N + 1];
            costN[N] = 0;

            Queue<long> q = new Queue<long>();
            HashSet<long> memo = new HashSet<long>();
            memo.Add(1);
            q.Enqueue(1);
            while (q.Count > 0)
            {
                var c = q.Dequeue();
                foreach (long i in tree[c])
                {
                    if (memo.Contains(i)) continue;
                    memo.Add(i);
                    cost1[i] = cost1[c] + 1;
                    q.Enqueue(i);
                }
            }

            memo = new HashSet<long>();
            memo.Add(N);
            q.Enqueue(N);
            while (q.Count > 0)
            {
                var c = q.Dequeue();
                foreach (long i in tree[c])
                {
                    if (memo.Contains(i)) continue;
                    memo.Add(i);
                    costN[i] = costN[c] + 1;
                    q.Enqueue(i);
                }
            }


            int f = 0;
            int s = 0;
            for (int i = 2; i < N; i++)
            {
                if (cost1[i] <= costN[i])
                {
                    f++;
                }
                else
                {
                    s++;
                }
            }

            Console.WriteLine(f > s ? "Fennec" : "Snuke");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
