using System.Numerics;


#if DEBUG
using Microsoft.VisualStudio.TestTools.UnitTesting;
#endif

namespace competitive_programming
{
    public class Program
    {
        static void Main(string[] args)
        {
#if DEBUG
            var scanner = new IO.StreamScanner(File.Open("input.txt", FileMode.Open));
#else
            var scanner = new IO.StreamScanner(Console.OpenStandardInput());
#endif

            var n = scanner.Integer();
            var graph = new List<Tuple<int, int>>();
            for (int i = 0; i < n - 1; i++)
            {
                graph.Add(new Tuple<int, int>(scanner.Integer(), scanner.Integer()));
            }

            IO.Printer.Out.WriteLine(GetAns(n, graph));
            IO.Printer.Out.Flush();
        }

        static string GetAns(int n, List<Tuple<int, int>> graph)
        {
            var g = Enumerable.Range(0, n).Select(i => new Node()).ToList();
            foreach(var path in graph)
            {
                g[path.Item1 - 1].Next.Add(g[path.Item2 - 1]);
                g[path.Item2 - 1].Next.Add(g[path.Item1 - 1]);
            }

            var whiteNexts = new HashSet<Node>();
            var blackNexts = new HashSet<Node>();

            SetColor("B", g[0], whiteNexts, blackNexts);
            SetColor("W", g[n - 1], whiteNexts, blackNexts);

            Dfs(null, g[0], new HashSet<Node>());

            var wToB = new List<Node>();
            var current = g[n - 1].Parent;
            while(current != null && current != g[0])
            {
                wToB.Add(current);
                current = current.Parent;
            }

            // simulate
            var turn = true;
            var bIdx = wToB.Count() - 1;
            var wIdx = 0;
            while (whiteNexts.Count() > 0 && blackNexts.Count() > 0)
            {
                // no more w->b route
                if (bIdx <= wIdx)
                {
                    if (turn)
                    {
                        var tgt = whiteNexts.First();
                        SetColor("W", tgt, whiteNexts, blackNexts);
                    }
                    else
                    {
                        var tgt = blackNexts.First();
                        SetColor("B", tgt, whiteNexts, blackNexts);
                    }
                }
                else
                {
                    if (turn)
                    {
                        // white
                        SetColor("W", wToB[wIdx], whiteNexts, blackNexts);
                        wIdx++;
                    }
                    else
                    {
                        // black
                        SetColor("B", wToB[bIdx], whiteNexts, blackNexts);
                        bIdx--;
                    }
                }
                turn = !turn;
            }


            return !turn ? "Fennec" : "Snuke";
        }

        static void SetColor(string color, Node node, HashSet<Node> whiteNexts, HashSet<Node> blackNexts)
        {
            node.Color = color;

            if (color == "B") blackNexts.Remove(node);
            else whiteNexts.Remove(node);

            foreach (var n in node.Next)
            {
                if (n.Color != null) continue;

                if (color == "B")
                {
                    blackNexts.Add(n);
                }
                else
                {
                    whiteNexts.Add(n);
                }
            }
        }

        static void Dfs(Node parent, Node current, HashSet<Node> used)
        {
            if (current == null) return;
            used.Add(current);
            current.Parent = parent;
            foreach(var n in current.Next)
            {
                if (used.Contains(n)) continue;
                Dfs(current, n, used);
            }
        }
    }

    public class Node
    {
        public int Depth;
        public Node Parent;
        public List<Node> Next = new List<Node>();
        public string Color;
    }
}

