namespace AtCoderSolve
{
    class Solve
    {
        const int mod = 1000000007;
        const int INF = int.MaxValue / 2;
        const long SINF = long.MaxValue / 2;

        static int N;

        //static char[] s;


        public static void Input()
        {

        }

        static void Main(string[] args)
        {
            //Input();
            //var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            //Console.SetOut(sw);

            var cin = new Scanner();
            N = int.Parse(Console.ReadLine());

            UnionFind U1 = new UnionFind(N);
            UnionFind UN = new UnionFind(N);
            for (var i = 0; i < N - 1; i++)
            {
                var p = cin.SplitReader();
                int a = p[0] - 1;
                int b = p[1] - 1;

                if (a != 0 && b != 0)
                {
                    U1.Unite(a, b);
                }
                if (a != N - 1 && b != N - 1)
                {
                    UN.Unite(a, b);
                }
            }

            int s1 = N - 1 - U1.GetSize(N - 1);
            int sn = N - 1 - UN.GetSize(0);
            int res = N - s1 - sn - 2;

            int fen = ((res + 1) / 2) + s1;
            int snuke = (res / 2) + sn;

            Console.WriteLine(fen > snuke ? "Fennec" : "Snuke");


            //Console.Out.Flush();
        }
    }

    public class Scanner
    {
        public int[] SplitReader()
        {
            int[] array = Console.ReadLine().Split().Select(int.Parse).ToArray();
            return array;
        }
        public long[] SplitReaderL()
        {
            long[] array = Console.ReadLine().Split().Select(long.Parse).ToArray();
            return array;
        }
    }

    public class UnionFind
    {
        public int[] parent;
        public int[] rank;
        public int[] size;
        public UnionFind(int n)
        {
            parent = new int[n];
            rank = new int[n];
            size = new int[n];
            for (var i = 0; i < n; i++)
            {
                parent[i] = i;
                rank[i] = 0;
                size[i] = 1;
            }
        }

        private int Root(int x)
        {
            return parent[x] == x ? x : parent[x] = Root(parent[x]);
        }

        public bool SameRoot(int x, int y)
        {
            return Root(x) == Root(y);
        }

        public void Unite(int x, int y)
        {
            x = Root(x);
            y = Root(y);
            if (x == y) { return; }

            if (rank[x] < rank[y])
            {
                parent[x] = y;
                size[y] += size[x];
                size[x] = 0;
            }
            else
            {
                parent[y] = x;
                if (rank[x] == rank[y]) { rank[x]++; }
                size[x] += size[y];
                size[y] = 0;
            }
        }

        public int GetSize(int x)
        {
            return size[Root(x)];
        }

    }



