public class Solver
{
	private int N;
	private List<int>[] adj = null;

	public Solver()
	{
		N = GetInt();
		adj = new List<int>[N+1];
		for(int i = 1; i <= N; i++)
			adj[i] = new List<int>();
		for(int i = 0; i < N-1; i++)
		{
			int a = GetInt();
			int b = GetInt();
			adj[a].Add(b);
			adj[b].Add(a);
		}
	}

	public void Solve()
	{
		int[] db = new int[N+1];
		int[] dw = new int[N+1];
		for(int i = 1; i <= N; i++)
		{
			db[i] = -1;
			dw[i] = -1;
		}
		db[1] = 0;
		dfs(db, 1);

		dw[N] = 0;
		dfs(dw, N);

		int numBlack = 0;
		for(int i = 1; i <= N; i++)
			if(db[i] <= dw[i])
				numBlack++;
		int numWhite = N - numBlack;
		Console.WriteLine((numBlack > numWhite) ? "Fennec" : "Snuke");		
	}

	private void dfs(int[] d, int v)
	{
		foreach(int u in adj[v])
		{
			if(d[u] != -1)
				continue;
			d[u] = d[v] + 1;
			dfs(d, u);
		}
	}
}



