		/* 問題文
フェネックとすぬけくんがボードゲームで遊んでいます。

このボードゲームには 1 番から N 番までの番号がついた N 個のマスと、マスどうしをつなぐ N−1 本の道が存在しています。
ai 番のマスと bi 番のマスは i 番目の道を介して隣り合っています。
どの 2 つのマスも隣接するマスをいくつか辿って必ず辿り着くことが可能です。
すなわち、グラフ理論の言葉を用いると、マスと道から構成されるグラフは木です。

はじめに 1 番のマスは黒く、N 番のマスは白く塗られています。その他のマスはまだ色が塗られていません。 
先手のフェネックと後手のすぬけくんは残りのマスに交互に色を塗ります。 自分の手番において、2 人はそれぞれ以下のような行動を行います。

フェネック：黒く 塗られたマスに隣接したマスであって、色が塗られていないマスを 1 つ選んで 黒く 塗る。
すぬけくん：白く 塗られたマスに隣接したマスであって、色が塗られていないマスを 1 つ選んで 白く 塗る。
手番のプレイヤーがマスに色を塗ることができなかったとき、敗者となります。フェネックとすぬけくんが最適に行動したとき勝者はどちらか判定してください。

制約
2≤N≤105
1≤ai,bi≤N
与えられるグラフは木
		 */

		static string フェネックの名前 = "Fennec";
		static string すぬけくんの名前 = "Snuke";
		const int 透明 = 0;
		const int 黒 = 1;
		const int 白 = 2;

		public static void Main(string[] args)
		{
			var str = Console.ReadLine().Split(' ');
			var マスの数 = int.Parse(str[0]); // 2 ~ 10^5
			var 道の数 = マスの数 - 1;
			var マスの情報 = new List<int>[マスの数 + 1];

			for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
			{
				マスの情報[マスの番号] = new List<int>();
			}

			for (var 道の番号 = 0; 道の番号 < 道の数; 道の番号++)
			{
				var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
				マスの情報[一つの道の情報[0]].Add(一つの道の情報[1]);
				マスの情報[一つの道の情報[1]].Add(一つの道の情報[0]);
			}

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var シミュレート回数 = 500;
			var シミュレート結果 = 0; // フェネックが勝ったら -1 すぬけくんが勝ったら +1
			var マスの色の情報 = new int[マスの数 + 1];
			var フェネックの最初のマス = 1;
			var すぬけくんの最初のマス = マスの数;
			var 乱数 = new System.Random();
			for (var 回数 = 0; 回数 < シミュレート回数; 回数++)
			{
				var フェネックの進める箇所 = new List<int>();
				var すぬけくんの進める箇所 = new List<int>();

				for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
				{
					マスの色の情報[マスの番号] = 透明;
				}
				マスの色の情報[フェネックの最初のマス] = 黒;
				マスの色の情報[すぬけくんの最初のマス] = 白;

				フェネックの進める箇所.AddRange(マスの情報[フェネックの最初のマス]);
				すぬけくんの進める箇所.AddRange(マスの情報[すぬけくんの最初のマス]);

				var 最大ターン数 = 1 + マスの数 / 2;
				for (var ターン = 0; ターン < 最大ターン数; ターン++)
				{
					// 先行はフェネック
					bool フェネックが移動した = false;
					if (フェネックの進める箇所.Count > 0)
					{
						var 次の移動候補で一番よさげなところ = 乱数.Next(0, フェネックの進める箇所.Count);
						var 保存領域 = フェネックの進める箇所[0];
						フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番よさげなところ];
						フェネックの進める箇所[次の移動候補で一番よさげなところ] = 保存領域;
					}
					for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
					{
						var 移動候補 = フェネックの進める箇所[移動候補の番号];
						if (マスの色の情報[移動候補] == 透明)
						{
							マスの色の情報[移動候補] = 黒;
							フェネックの進める箇所.AddRange(マスの情報[移動候補]);
							フェネックが移動した = true;
							break;
						}
						フェネックの進める箇所.RemoveAt(移動候補の番号);
						移動候補の番号--;
					}

					if (!フェネックが移動した)
					{
						シミュレート結果++;
						break;
					}

					bool すぬけくんが移動した = false;
					if (すぬけくんの進める箇所.Count > 0)
					{
						var 次の移動候補で一番よさげなところ = 乱数.Next(0, すぬけくんの進める箇所.Count);
						var 保存領域 = すぬけくんの進める箇所[0];
						すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番よさげなところ];
						すぬけくんの進める箇所[次の移動候補で一番よさげなところ] = 保存領域;
					}
					for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
					{
						var 移動候補 = フェネックの進める箇所[移動候補の番号];
						if (マスの色の情報[移動候補] == 透明)
						{
							マスの色の情報[移動候補] = 黒;
							すぬけくんの進める箇所.AddRange(マスの情報[移動候補]);
							すぬけくんが移動した = true;
							break;
						}
						すぬけくんの進める箇所.RemoveAt(移動候補の番号);
						移動候補の番号--;
					}

					if (!すぬけくんが移動した)
					{
						シミュレート結果--;
						break;
					}
				}
			}

			var 勝者の名前 = シミュレート結果 < 0 ? フェネックの名前 : すぬけくんの名前;

			Console.WriteLine(勝者の名前);
		}
	}
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;

namespace CF
{
    internal class Program
    {
        private static void Main(string[] args)
        {
            using (var sr = new InputReader(Console.In))
            //using (var sr = new InputReader(new StreamReader("input.txt")))
            {
                var task = new Task();
                using (var sw = Console.Out) {
                    //using (var sw = new StreamWriter("output.txt")) {
                    task.Solve(sr, sw);
                    //Console.ReadKey();
                }
            }
        }
    }

    internal class Task
    {
        public void Solve(InputReader sr, TextWriter sw)
        {
            var n = sr.NextInt32();
            var graph = new Graph(n);
            for (var i = 0; i < n - 1; i++) {
                var input = sr.ReadArrayOfInt32();
                graph.Insert(input[0] - 1, input[1] - 1);
            }
            sw.WriteLine(graph.Solution());
        }
    }

    class Graph
    {
        private readonly List<int>[] edges;
        private readonly Color[] colors;

        public Graph(int n)
        {
            edges = new List<int>[n];
            colors = new Color[n];
        }

        public void Insert(int x, int y)
        {
            if (edges[x] == null) {
                edges[x] = new List<int>();
            }
            edges[x].Add(y);
            if (edges[y] == null) {
                edges[y] = new List<int>();
            }
            edges[y].Add(x);
        }

        public string Solution()
        {
            var path = new List<int>();
            var visited = new bool[edges.Length];
            DfsVisit(0, visited, path);
            path.RemoveAt(0);
            for (var i = 0; i < path.Count / 2; i++) {
                var v = path[i];
                colors[v] = Color.Black;
                var revV = path.Count - 1 - i;
                colors[revV] = Color.White;
            }
            if (path.Count % 2 == 1) {
                colors[path[(path.Count - 1) / 2]] = Color.Black;
            }
            colors[0] = Color.Black;
            colors[edges.Length - 1] = Color.White;
            var isFennecLast = path.Count % 2 == 1;
            var fennecSteps = 0;
            var snukeSteps = 0;
            for (var i = 0; i < edges.Length; i++) {
                if (colors[i] == Color.Black) {
                    fennecSteps += DfsVisit(i, 0, Color.Black);
                }
            }
            for (var i = 0; i < edges.Length; i++)
            {
                if (colors[i] == Color.White)
                {
                    snukeSteps += DfsVisit(i, 0, Color.White);
                }
            }
            if (isFennecLast) {
                if (fennecSteps >= snukeSteps) {
                    return "Fennec";
                }
                return "Snuke";
            }
            else {
                if (snukeSteps >= fennecSteps) {
                    return "Snuke";
                }

                return "Fennec";
            }
        }

        private int DfsVisit(int v, int curr, Color color)
        {
            colors[v] = color;
            var result = curr;
            for (var i = 0; i < edges[v].Count; i++) {
                if (colors[edges[v][i]] == Color.None) {
                    var next = DfsVisit(edges[v][i], curr + 1, color);
                    result += (next - curr);
                }
            }

            return result;
        }

        private bool DfsVisit(int v, bool[] visited, List<int> path)
        {
            if (v == edges.Length - 1)
                return true;
            visited[v] = true;
            path.Add(v);
            for (var i = 0; i < edges[v].Count; i++) {
                if (!visited[edges[v][i]]) {
                    if (DfsVisit(edges[v][i], visited, path)) {
                        return true;
                    }
                }
            }
            path.RemoveAt(path.Count - 1);
            return false;
        }
    }

    enum Color
    {
        None,
        White,
        Black
    }
}

internal class InputReader : IDisposable
{
    private bool isDispose;
    private readonly TextReader sr;

    public InputReader(TextReader stream)
    {
        sr = stream;
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    public string NextString()
    {
        var result = sr.ReadLine();
        return result;
    }

    public int NextInt32()
    {
        return Int32.Parse(NextString());
    }

    public long NextInt64()
    {
        return Int64.Parse(NextString());
    }

    public string[] NextSplitStrings()
    {
        return NextString()
            .Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
    }

    public T[] ReadArray<T>(Func<string, CultureInfo, T> func)
    {
        return NextSplitStrings()
            .Select(s => func(s, CultureInfo.InvariantCulture))
            .ToArray();
    }

    public int[] ReadArrayOfInt32()
    {
        return ReadArray(Int32.Parse);
    }

    public long[] ReadArrayOfInt64()
    {
        return ReadArray(Int64.Parse);
    }

    public T[] ReadArrayFromString<T>(Func<string, CultureInfo, T> func, string str)
    {
        return
            str.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(s => func(s, CultureInfo.InvariantCulture))
                .ToArray();
    }

    protected void Dispose(bool dispose)
    {
        if (!isDispose) {
            if (dispose)
                sr.Close();
            isDispose = true;
        }
    }

    ~InputReader()
    {
        Dispose(false);
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
	public class Program
	{
		// TLEがないやつ
		// http://abc067.contest.atcoder.jp/submissions/1431970
		// クラスにしたやつ
		// http://abc067.contest.atcoder.jp/submissions/1431941

		static string フェネックの名前 = "Fennec";
		static string すぬけくんの名前 = "Snuke";

		enum マスの色
		{
			透明 = 0,
			黒,
			白,
		};

		enum プレイヤー
		{
			謎の第三者 = マスの色.透明,
			フェネック = マスの色.黒,
			すぬけくん = マスの色.白,
		};

		public static void Main(string[] args)
		{
			var str = Console.ReadLine().Split(' ');
			var マスの数 = int.Parse(str[0]); // 2 ~ 10^5
			var 道の数 = マスの数 - 1;
			var マスの情報 = new List<int>[マスの数 + 1];

			for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
			{
				マスの情報[マスの番号] = new List<int>();
			}

			for (var 道の番号 = 0; 道の番号 < 道の数; 道の番号++)
			{
				var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
				マスの情報[一つの道の情報[0]].Add(一つの道の情報[1]);
				マスの情報[一つの道の情報[1]].Add(一つの道の情報[0]);
			}

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var 合計シミュレート回数 = Math.Min(20000, Math.Max(1, 200000000 / (マスの数 * マスの数) ));
			int 繰り返す数 = 合計シミュレート回数;
			var マスの色の情報 = new マスの色[マスの数 + 1];
			var フェネックの最初のマス = 1;
			var すぬけくんの最初のマス = マスの数;
			var 乱数 = new System.Random(0);
			var フェネックの定跡本 = new List<int>();
			var すぬけくんの定跡本 = new List<int>();

			var 生き延びた最大ターン = -1;
			var フェネックの生き延びた最大ターン = -1;
			var すぬけくんの生き延びた最大ターン = -1;
			var 只今の勝者 = プレイヤー.謎の第三者;

			var 最大ターン数 = 1 + マスの数 / 2;

			var コールド勝ちのルールが有る = 繰り返す数 == 1 && false;
			var コールド勝ちに必要なマスの数 = 10;
			var コールド勝ちに必要なターン = 最大ターン数 / 2;
			var フェネックとすぬけくんが隣接した = false;

			Action<List<int>, int, マスの色> 進めるマスを更新する = (進める箇所, 進むマスの番号, 自分の色) =>
			{
				var 進んだ先のマスの情報 = マスの情報[進むマスの番号];
				for (var i = 0; i < 進んだ先のマスの情報.Count; i++)
				{
					if (マスの色の情報[進んだ先のマスの情報[i]] == マスの色.透明)
					{
						進める箇所.Add(進んだ先のマスの情報[i]);
						continue;
					}

					if (マスの色の情報[進んだ先のマスの情報[i]] != 自分の色)
					{
						フェネックとすぬけくんが隣接した = true;
					}
				}
			};

			Action シミュレート = () =>
			{
				var フェネックの進める箇所 = new List<int>();
				var すぬけくんの進める箇所 = new List<int>();

				var フェネックの今回の選択 = new List<int>();
				var すぬけくんの今回の選択 = new List<int>();

				フェネックとすぬけくんが隣接した = false;

				for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
				{
					マスの色の情報[マスの番号] = マスの色.透明;
				}
				マスの色の情報[フェネックの最初のマス] = マスの色.黒;
				マスの色の情報[すぬけくんの最初のマス] = マスの色.白;

				進めるマスを更新する(フェネックの進める箇所, フェネックの最初のマス, マスの色.黒);
				進めるマスを更新する(すぬけくんの進める箇所, すぬけくんの最初のマス, マスの色.白);

				for (var ターン = 0; ターン < 最大ターン数; ターン++)
				{
					// 先行はフェネック
					bool フェネックが移動していない = true;

					if (フェネックの進める箇所.Count > 1)
					{
						var 次の移動候補で一番優先したいところ = ターン < フェネックの定跡本.Count ? フェネックの定跡本[ターン] : 乱数.Next(0, フェネックの進める箇所.Count);
						var 保存領域 = フェネックの進める箇所[0];
						フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番優先したいところ];
						フェネックの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
					}
					for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
					{
						var 移動候補 = フェネックの進める箇所[移動候補の番号];
						if (マスの色の情報[移動候補] == マスの色.透明)
						{
							フェネックの今回の選択.Add(移動候補の番号);
							マスの色の情報[移動候補] = マスの色.黒;
							進めるマスを更新する(フェネックの進める箇所, 移動候補, マスの色.黒);
							フェネックが移動していない = false;
							break;
						}
						フェネックの進める箇所.RemoveAt(移動候補の番号);
						移動候補の番号--;
					}

					if (フェネックが移動していない)
					{
						if (生き延びた最大ターン < ターン)
						{
							只今の勝者 = プレイヤー.すぬけくん;
							生き延びた最大ターン = ターン;
						}
						if (すぬけくんの生き延びた最大ターン < ターン)
						{
							すぬけくんの生き延びた最大ターン = ターン;
							フェネックの定跡本.Clear();
							すぬけくんの定跡本 = すぬけくんの今回の選択;
						}
						break;
					}

					bool すぬけくんが移動していない = true;
					if (すぬけくんの進める箇所.Count > 1)
					{
						var 次の移動候補で一番優先したいところ = ターン < すぬけくんの定跡本.Count ? すぬけくんの定跡本[ターン] : 乱数.Next(0, すぬけくんの進める箇所.Count);
						var 保存領域 = すぬけくんの進める箇所[0];
						すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番優先したいところ];
						すぬけくんの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
					}
					for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
					{
						var 移動候補 = すぬけくんの進める箇所[移動候補の番号];
						if (マスの色の情報[移動候補] == マスの色.透明)
						{
							すぬけくんの今回の選択.Add(移動候補の番号);
							マスの色の情報[移動候補] = マスの色.白;
							進めるマスを更新する(すぬけくんの進める箇所, 移動候補, マスの色.白);
							すぬけくんが移動していない = false;
							break;
						}
						すぬけくんの進める箇所.RemoveAt(移動候補の番号);
						移動候補の番号--;
					}

					if (すぬけくんが移動していない)
					{
						if (生き延びた最大ターン < ターン)
						{
							只今の勝者 = プレイヤー.フェネック;
							生き延びた最大ターン = ターン;
						}
						if (フェネックの生き延びた最大ターン < ターン)
						{
							フェネックの生き延びた最大ターン = ターン;
							フェネックの定跡本 = フェネックの今回の選択;
							すぬけくんの定跡本.Clear();
						}
						break;
					}

					// 進める箇所がいっぱいあったらコールド勝ち
					// 隣接してたら最後まで続ける
					if (コールド勝ちのルールが有る && コールド勝ちに必要なターン < ターン && !フェネックとすぬけくんが隣接した)
					{
						if (フェネックの進める箇所.Count > すぬけくんの進める箇所.Count)
						{
							if (フェネックの進める箇所.Count > コールド勝ちに必要なマスの数)
							{
								只今の勝者 = プレイヤー.フェネック;
								break;
							}
						}
						else
						{
							if (すぬけくんの進める箇所.Count > コールド勝ちに必要なマスの数)
							{
								只今の勝者 = プレイヤー.すぬけくん;
								break;
							}
						}
					}
				}
			};

			for (var 世代 = 0; 世代 < 繰り返す数; 世代++)
			{
				シミュレート();
			}

			Console.WriteLine(只今の勝者 == プレイヤー.フェネック ? フェネックの名前 : すぬけくんの名前);
		}
	}
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var g = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            g[i] = new List<int>();
        }
        for (int i = 0; i < N - 1; i++)
        {
            var a = sc.ReadInt() - 1;
            var b = sc.ReadInt() - 1;
            g[a].Add(b);
            g[b].Add(a);
        }

        var color = new int[N];
        color[0] = 1;
        color[N - 1] = 2;

        var q1 = new Queue<int>();
        q1.Enqueue(0);
        var q2 = new Queue<int>();
        q2.Enqueue(N - 1);
        while (q1.Count > 0 || q2.Count > 0)
        {
            if (q1.Count > 0)
            {
                var now = q1.Dequeue();
                foreach (var next in g[now])
                {
                    if (color[next] != 0) continue;
                    color[next] = 1;
                    q1.Enqueue(next);
                }
            }
            if (q2.Count > 0)
            {
                var now = q2.Dequeue();
                foreach (var next in g[now])
                {
                    if (color[next] != 0) continue;
                    color[next] = 2;
                    q2.Enqueue(next);
                }
            }
        }

        var c1 = color.Count(c => c == 1);
        var c2 = N - c1;
        if (c1 > c2)
        {
            Console.WriteLine("Fennec");
        }
        else
        {
            Console.WriteLine("Sunuke");
        }

    }

    static Scanner sc = new Scanner();
}
