using System;
using System.Linq;
using System.Collections.Generic;
using System.Text;

namespace Program
{
    public class ARC078D
    {
        static public void Main(string[] args)
        {
            var N = NextInt;
            var path = new List<int>[N];
            for (int i = 0; i < N; ++i)
            {
                path[i] = new List<int>();
            }
            for (int i = 0; i < N - 1; ++i)
            {
                var a = NextInt - 1;
                var b = NextInt - 1;
                path[a].Add(b);
                path[b].Add(a);
            }

            var bfs = new Queue<int>();
            bfs.Enqueue(N - 1);
            var dist = new int[N];
            var pred = new int[N];
            var done = new bool[N];
            while (!done[0])
            {
                var v = bfs.Dequeue();
                foreach (var item in path[v])
                {
                    dist[item] = dist[v] + 1;
                    pred[item] = v;
                    done[item] = true;
                    bfs.Enqueue(item);
                }
            }

            var midlength = dist[0] / 2;
            var p = 0;
            var count = 0;
            while (count != midlength)
            {
                p = pred[p];
                ++count;
            }
            foreach (var item in path[p])
            {
                path[item].Remove(p);
            }
            path[p].Clear();

            var queue = new Queue<int>();
            queue.Enqueue(N - 1);
            done = new bool[N];
            var field = 0;
            while (queue.Any())
            {
                var v = queue.Dequeue();
                if (!done[v])
                {
                    done[v] = true;
                    ++field;
                    foreach (var item in path[v])
                    {
                        queue.Enqueue(item);
                    }
                }
            }

            Console.WriteLine(field < (N + 1) / 2 ? "Fennec" : "Snuke");
        }

        static class Console_
        {
            private static Queue<string> param = new Queue<string>();
            public static string NextString()
            {
                if (param.Count == 0) foreach (var item in Console.ReadLine().Split(' ')) param.Enqueue(item);
                return param.Dequeue();
            }
        }
        static int NextInt => int.Parse(Console_.NextString());
        static long NextLong => long.Parse(Console_.NextString());
        static string NextString => Console_.NextString();

        static IEnumerable<long> Prime(long x)
        {
            if (x < 2) yield break;
            yield return 2;
            var halfx = x / 2;
            var table = new bool[halfx + 1];
            var max = (long)(Math.Sqrt(x) / 2);
            for (long i = 1; i <= max; ++i)
            {
                if (table[i]) continue;
                var add = 2 * i + 1;
                yield return add;
                for (long j = 2 * i * (i + 1); j <= halfx; j += add) table[j] = true;
            }
            for (long i = max + 1; i <= halfx; ++i) if (!table[i]) yield return 2 * i + 1;
        }
        static IEnumerable<long> Divisor(long x)
        {
            if (x < 1) yield break;
            var max = (long)Math.Sqrt(x);
            for (long i = 1; i < max; ++i)
            {
                if (x % i != 0) continue;
                yield return i;
                if (i != x / i) yield return x / i;
            }
        }
        static long GCD(long a, long b)
        {
            long tmpa = a, tmpb = b;
            while (tmpb > 0) { var tmp = tmpb; tmpb = tmpa % tmpb; tmpa = tmp; }
            return tmpa;
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
	public class Program
	{
		// TLEがないやつ
		// http://abc067.contest.atcoder.jp/submissions/1431970
		// クラスにしたやつ
		// http://abc067.contest.atcoder.jp/submissions/1431941

		static string フェネックの名前 = "Fennec";
		static string すぬけくんの名前 = "Snuke";

		enum マスの色
		{
			透明 = 0,
			黒,
			白,
		};

		enum プレイヤー
		{
			謎の第三者 = マスの色.透明,
			フェネック = マスの色.黒,
			すぬけくん = マスの色.白,
		};

		public static void Main(string[] args)
		{
			var str = Console.ReadLine().Split(' ');
			var マスの数 = int.Parse(str[0]); // 2 ~ 10^5
			var 道の数 = マスの数 - 1;
			var マスの情報 = new List<int>[マスの数 + 1];

			for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
			{
				マスの情報[マスの番号] = new List<int>();
			}

			for (var 道の番号 = 0; 道の番号 < 道の数; 道の番号++)
			{
				var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
				マスの情報[一つの道の情報[0]].Add(一つの道の情報[1]);
				マスの情報[一つの道の情報[1]].Add(一つの道の情報[0]);
			}

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			int 一回のシミュレート回数 = 1;
			int 繰り返す数 = 60;
			var マスの色の情報 = new マスの色[マスの数 + 1];
			var フェネックの最初のマス = 1;
			var すぬけくんの最初のマス = マスの数;
			var 乱数 = new System.Random();
			var フェネックの定跡本 = new List<int>();
			var すぬけくんの定跡本 = new List<int>();

			var 生き延びた最大ターン = -1;
			var フェネックの生き延びた最大ターン = -1;
			var すぬけくんの生き延びた最大ターン = -1;
			var 只今の勝者 = プレイヤー.謎の第三者;

			Func<int, List<int>, List<int>, プレイヤー> シミュレート = (シミュレート回数, フェネックの定跡, すぬけくんの定跡) =>
			{
				var 新しいフェネックの定跡 = new List<int>();
				var 新しいすぬけくんの定跡 = new List<int>();

				for (var 回数 = 0; 回数 < シミュレート回数; 回数++)
				{
					var フェネックの進める箇所 = new List<int>();
					var すぬけくんの進める箇所 = new List<int>();

					var フェネックの今回の選択 = new List<int>();
					var すぬけくんの今回の選択 = new List<int>();

					for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
					{
						マスの色の情報[マスの番号] = マスの色.透明;
					}
					マスの色の情報[フェネックの最初のマス] = マスの色.黒;
					マスの色の情報[すぬけくんの最初のマス] = マスの色.白;

					フェネックの進める箇所.AddRange(マスの情報[フェネックの最初のマス]);
					すぬけくんの進める箇所.AddRange(マスの情報[すぬけくんの最初のマス]);

					var 最大ターン数 = 1 + マスの数 / 2;
					for (var ターン = 0; ターン < 最大ターン数; ターン++)
					{
						// 先行はフェネック
						bool フェネックが移動していない = true;
						if (フェネックの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < フェネックの定跡.Count ? フェネックの定跡[ターン] : 乱数.Next(0, フェネックの進める箇所.Count);
							var 保存領域 = フェネックの進める箇所[0];
							フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番優先したいところ];
							フェネックの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = フェネックの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								フェネックの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.黒;
								フェネックの進める箇所.AddRange(マスの情報[移動候補]);
								フェネックが移動していない = false;
								break;
							}
							フェネックの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (フェネックが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.すぬけくん;
								生き延びた最大ターン = ターン;
							}
							if (すぬけくんの生き延びた最大ターン < ターン)
							{
								すぬけくんの生き延びた最大ターン = ターン;
								新しいすぬけくんの定跡 = すぬけくんの今回の選択;
							}
							break;
						}

						bool すぬけくんが移動していない = true;
						if (すぬけくんの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < すぬけくんの定跡.Count ? すぬけくんの定跡[ターン] : 乱数.Next(0, すぬけくんの進める箇所.Count);
							var 保存領域 = すぬけくんの進める箇所[0];
							すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番優先したいところ];
							すぬけくんの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = すぬけくんの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								すぬけくんの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.白;
								すぬけくんの進める箇所.AddRange(マスの情報[移動候補]);
								すぬけくんが移動していない = false;
								break;
							}
							すぬけくんの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (すぬけくんが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.フェネック;
								生き延びた最大ターン = ターン;
							}
							if (フェネックの生き延びた最大ターン < ターン)
							{
								フェネックの生き延びた最大ターン = ターン;
								新しいフェネックの定跡 = フェネックの今回の選択;
							}
							break;
						}
					}
				}

				switch (只今の勝者)
				{
					case プレイヤー.フェネック:
						フェネックの定跡 = 新しいフェネックの定跡;
						すぬけくんの定跡.Clear();
						break;
					case プレイヤー.すぬけくん:
						フェネックの定跡.Clear();
						すぬけくんの定跡 = 新しいすぬけくんの定跡;
						break;
				}

				return 只今の勝者;
			};

			for (var 世代 = 0; 世代 < 繰り返す数; 世代++)
			{
				シミュレート(一回のシミュレート回数, フェネックの定跡本, すぬけくんの定跡本);
			}

			Console.WriteLine(只今の勝者 == プレイヤー.フェネック ? フェネックの名前 : すぬけくんの名前);
		}
	}
}

using System;
using System.Text;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using static System.Console;
using static System.Math;
using System.Numerics;

namespace AtCoder
{
    public class Program
    {
        public static void Main(string[] args)
        {
            new Program().Solve(new ConsoleInput(Console.In, ' '));
        }

        public void Solve(ConsoleInput cin)
        {
            var N = cin.ReadInt;
            var abs = new int[N-1].Select(x => cin.ReadLine.Split(' ').Select(y => int.Parse(y)).ToArray());
            var points = new int[N + 1].Select(x => new List<int>()).ToArray(); // 0 は使用しない

            foreach (var ab in abs)
            {
                points[ab[0]].Add(ab[1]);
                points[ab[1]].Add(ab[0]);
            }

            var queOfFennec = new Queue<int>();
            var queOfSnuke = new Queue<int>();

            Func<int, int, List<int>, List<int>> GetRoot = null;
            GetRoot = (int pre, int now, List<int> root) =>
            {
                var newlist = new List<int>(root);
                newlist.Add(now);
                if (now == N) return newlist;

                foreach (var p in points[now])
                {
                    if (p == pre) continue;
                    var wk = GetRoot(now, p, newlist);
                    if (wk.Count != 0) return wk;
                }
                return new List<int>();
            };

            var root = GetRoot(-1, 1, new List<int>());


            //WriteLine("--------- line 1 -----------");
            //root.ForEach(x => WriteLine(x));
            root.ForEach(x => queOfFennec.Enqueue(x));
            root.Reverse();
            //WriteLine("--------- line 2 -----------");
            //root.ForEach(x => WriteLine(x));
            root.ForEach(x => queOfSnuke.Enqueue(x));

            var isRooted = new int[N+1];
            var countOfFennec = 0;
            var countOfSnuke = 0;
            //WriteLine("--------------------");
            while (true) 
            {
                while(true)
                {
                    if (queOfFennec.Count == 0) break;
                    var f = queOfFennec.Dequeue();
                    //WriteLine("f {0} {1}", f, countOfFennec);
                    if (isRooted[f] == 1) continue;
                    foreach (var p in points[f])
                    {
                        queOfFennec.Enqueue(p);
                    }
                    isRooted[f] = 1;
                    countOfFennec++;
                    break;
                }

                while (true)
                {
                    if (queOfSnuke.Count == 0) break;
                    var s = queOfSnuke.Dequeue();
                    //WriteLine("s {0} {1}", s, countOfSnuke);
                    if (isRooted[s] == 1) continue;
                    foreach (var p in points[s])
                    {
                        queOfSnuke.Enqueue(p);
                    }
                    isRooted[s] = 1;
                    countOfSnuke++;
                    break;
                }
                if (countOfSnuke != countOfFennec) break;
            }

            WriteLine(countOfFennec > countOfSnuke ? "Fennec" : "Snuke");
        }

        private BigInteger Lcm(BigInteger a, BigInteger b)
        {
            return (a * b) / Gcd(a, b);
        }

        /// <summary>
        /// 最大公約数計算
        /// </summary>
        /// <param name="a"></param>
        /// <param name="b"></param>
        /// <returns></returns>
        private BigInteger Gcd(BigInteger a, BigInteger b)
        {
            if (a < b) return Gcd(b, a);

            while (b != 0)
            {
                var mod = a % b;
                a = b;
                b = mod;
            }
            return a;
        }
    }

    public class ConsoleInput
    {
        private readonly System.IO.TextReader _stream;
        private char _separator = ' ';
        private Queue<string> inputStream;
        public ConsoleInput(System.IO.TextReader stream, char separator = ' ')
        {
            this._separator = separator;
            this._stream = stream;
            inputStream = new Queue<string>();
        }

        public string Read
        {
            get
            {
                if (inputStream.Count != 0) return inputStream.Dequeue();
                string[] tmp = _stream.ReadLine().Split(_separator);
                for (int i = 0; i < tmp.Length; i++)
                    inputStream.Enqueue(tmp[i]);
                return inputStream.Dequeue();
            }
        }

        public string ReadLine { get { return _stream.ReadLine(); } }
        public int ReadInt { get { return int.Parse(Read); } }
        public long ReadLong { get { return long.Parse(Read); } }
        public double ReadDouble { get { return double.Parse(Read); } }
        public string[] ReadStrArray(long N) { var ret = new string[N]; for (long i = 0; i < N; ++i) ret[i] = Read; return ret; }
        public int[] ReadIntArray(long N) { var ret = new int[N]; for (long i = 0; i < N; ++i) ret[i] = ReadInt; return ret; }
        public long[] ReadLongArray(long N) { var ret = new long[N]; for (long i = 0; i < N; ++i) ret[i] = ReadLong; return ret; }
    }

    /// <summary>
    /// Mod計算用クラス
    /// </summary>
    struct ModInt
    {
        const int M = 1000000007;
        public long V;
        public ModInt(long v) { V = (v %= M) < 0 ? v + M : v; }

        public static implicit operator ModInt(long v) => new ModInt(v);
        public static ModInt operator +(ModInt x) => x;
        public static ModInt operator -(ModInt x) => -x.V;
        public static ModInt operator +(ModInt x, ModInt y) => x.V + y.V;
        public static ModInt operator -(ModInt x, ModInt y) => x.V - y.V;
        public static ModInt operator *(ModInt x, ModInt y) => x.V * y.V;
        public static ModInt operator /(ModInt x, ModInt y) => x.V * y.Inv();

        public ModInt Pow(int i) => MPow(V, i);
        public ModInt Inv() => MPow(V, M - 2);
        public override string ToString() => $"{V}";

        static long MPow(long b, int i)
        {
            for (var r = 1L; ; b = b * b % M)
            {
                if (i % 2 > 0) r = r * b % M;
                if ((i /= 2) < 1) return r;
            }
        }

        public static long MFactorial(int n) { for (long x = 1, i = 1; ; x = x * ++i % M) if (i >= n) return x; }
        public static long MNpr(int n, int r)
        {
            if (n < r) return 0;
            for (long x = 1, i = n - r; ; x = x * ++i % M) if (i >= n) return x;
        }
        public static ModInt MNcr(int n, int r) => n < r ? 0 : n - r < r ? MNcr(n, n - r) : (ModInt)MNpr(n, r) / MFactorial(r);
    }
}

