    class BFS
    {
        int[] dis;
        List<int[]> edge;

        public BFS(int n, List<int[]> edge, int p)
        {
            dis = Enumerable.Repeat(int.MaxValue, n + 1).ToArray();
            this.edge = edge;
            dis[p] = -1;
        }

        public void Seach(int a, int c)
        {
            if (c < dis[a]) { dis[a] = c; c++; }
            else c = dis[a] + 1;
            var chkN = new List<int>();
            var tmp = new List<int[]>();
            foreach (var e in edge)
            {
                if (e[0] == a && c < dis[e[1]])
                {
                    chkN.Add(e[1]);
                }
                else if (e[1] == a && c < dis[e[0]])
                {
                    chkN.Add(e[0]);
                }
                else
                {
                    tmp.Add(e);
                }
            }
            edge = tmp;
            foreach (var n in chkN) Seach(n, c);
        }

        public int Dis(int a)
        {
            return dis[a];
        }
    }
}

