namespace AtCoderTemplate {
    class ProgramD {
        static void Main () {
            int N = NextInt;
            var matrix = Enumerable.Repeat(0, N).Select(_ => new List<int>()).ToArray();
            for (int i = 0; i < N - 1; i++)
            {
                int a = NextInt - 1, b = NextInt - 1;
                matrix[a].Add(b);
                matrix[b].Add(a);
            }

            var queue = new Queue<int>();
            var fennec = Enumerable.Repeat(int.MaxValue, N).ToArray();
            fennec[0] = 0;
            queue.Enqueue(0);
            while (queue.Any())
            {
                var now = queue.Dequeue();
                foreach (var to in matrix[now].Where(to => fennec[to] == int.MaxValue))
                {
                    fennec[to] = fennec[now] + 1;
                    queue.Enqueue(to);
                }
            }

            var sunuke = Enumerable.Repeat(int.MaxValue, N).ToArray();
            sunuke[N - 1] = 0;
            queue.Enqueue(N - 1);
            while (queue.Any())
            {
                var now = queue.Dequeue();
                foreach (var to in matrix[now].Where(to => sunuke[to] == int.MaxValue))
                {
                    sunuke[to] = sunuke[now] + 1;
                    queue.Enqueue(to);
                }
            }

            if(fennec.Zip(sunuke, (f, s) => f - s <= 0).Count(x => x) > N / 2) {
                System.Console.WriteLine("Fennec");
            } else {
                System.Console.WriteLine("Snuke");
            }
        }
    }

