namespace Library {

    class Modular {
        public const int mod = 1000000007;
        public readonly long value;
        public Modular (long value) { this.value = value; }
        public static implicit operator Modular (long a) {
            var m = a % mod;
            return new Modular ((m < 0) ? m + mod : m);
        }
        public static Modular operator + (Modular a, Modular b) {
            return a.value + b.value;
        }
        public static Modular operator - (Modular a, Modular b) {
            return a.value - b.value;
        }
        public static Modular operator * (Modular a, Modular b) {
            return a.value * b.value;
        }
        public static Modular Pow (Modular a, int n) {
            switch (n) {
                case 0:
                    return 1;
                case 1:
                    return a;
                default:
                    var p = Pow (a, n / 2);
                    return p * p * Pow (a, n % 2);
            }
        }
        public static Modular operator / (Modular a, Modular b) {
            return a * Pow (b, mod - 2);
        }
        private static readonly List<int> facs = new List<int> { 1 };
        private static Modular Fac (int n) {
            for (int i = facs.Count; i <= n; ++i) {
                facs.Add ((int) (Math.BigMul (facs.Last (), i) % mod));
            }
            return facs[n];
        }
        public static Modular Ncr (int n, int r) {
            return (n < r) ? 0 :
                (n == r) ? 1 :
                Fac (n) / (Fac (r) * Fac (n - r));
        }
        public static explicit operator int (Modular a) {
            return (int) a.value;
        }
    }

}
namespace Library {
    class MyMath {
        public static long Gcd (long a, long b) {
            return b == 0 ? a : Gcd (b, a % b);
        }

        public static long Sqrt (long n) {
            if (n < 0) return 0;
            long a = 0, tmp = 0, b = 0;
            for (int i = 62; i >= 0; i -= 2) {
                tmp = (b << 1) + 1 <= (n >> i) ? 1 : 0;
                a = a << 1 | tmp;
                n -= (((b << 1) + 1) * tmp) << i;
                b = (b << 1) + tmp + tmp;
            }
            return a;
        }

        public static long Nck (int n, int k) {
            if (k == 0) return 1;
            if (n == 0) return 0;
            return n * Nck (n - 1, k - 1) / k;
        }
    }
}

namespace Library {
        public class PriorityQueue<T> {

        readonly List<T> _heap = new List<T> ();
        readonly Comparison<T> _comparison;

        public PriorityQueue (Comparison<T> comparison) {
            _comparison = comparison;
        }

        public PriorityQueue () : this (Comparer<T>.Default.Compare) { }

        public PriorityQueue (IComparer<T> comparer) : this (comparer.Compare) { }

        public void Enqueue (T item) {
            _heap.Add (item);

            int childID = _heap.Count - 1;
            int parentID = (childID - 1) / 2;

            while (childID > 0 && _comparison (_heap[parentID], _heap[childID]) > 0) {
                Swap (parentID, childID);
                childID = parentID;
                parentID = (parentID - 1) / 2;
            }
        }

        public T Dequeue () {
            var first = _heap.First ();
            _heap[0] = _heap.Last ();
            _heap.RemoveAt (_heap.Count - 1);

            int parentID = 0;
            int childID = parentID * 2 + 2;
            if (childID >= _heap.Count || _comparison (_heap[childID], _heap[childID - 1]) > 0) childID--;

            while (childID < _heap.Count && _comparison (_heap[parentID], _heap[childID]) > 0) {
                Swap (parentID, childID);
                parentID = childID;
                childID = parentID * 2 + 2;
                if (childID >= _heap.Count || _comparison (_heap[childID], _heap[childID - 1]) > 0) childID--;
            }

            return first;
        }

        void Swap (int parent, int child) {
            var tmp = _heap[parent];
            _heap[parent] = _heap[child];
            _heap[child] = tmp;
        }

        public T Peek () { return _heap[0]; }
        public int Count => _heap.Count;
        public bool Any () { return _heap.Any (); }
        public List<T> Data => _heap;
    }
}

namespace Library {

    public class UnionFind {
        public int[] Parents { get; set; }
        public UnionFind (int size) {
            Parents = Enumerable.Repeat (-1, size).ToArray ();
        }

        public int Find (int num) {
            if (Parents[num] < 0) return num;

            Parents[num] = Find (Parents[num]);
            return Parents[num];
        }

        public int Size (int num) {
            return -Parents[Find (num)];
        }

        public bool Same (int a, int b) {
            return Find (a) == Find (b);
        }

        public void Unite (int a, int b) {
            int x = Find (a), y = Find (b);

            if (Size (x) > Size (y)) {
                Parents[x] += Parents[y];
                Parents[y] = x;
            } else {
                Parents[y] += Parents[x];
                Parents[x] = y;
            }
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
	public class Program
	{
		// TLEがないやつ
		// http://abc067.contest.atcoder.jp/submissions/1431970
		// クラスにしたやつ
		// http://abc067.contest.atcoder.jp/submissions/1431941

		static string フェネックの名前 = "Fennec";
		static string すぬけくんの名前 = "Snuke";

		enum マスの色
		{
			透明 = 0,
			黒,
			白,
		};

		enum プレイヤー
		{
			謎の第三者 = マスの色.透明,
			フェネック = マスの色.黒,
			すぬけくん = マスの色.白,
		};

		public static void Main(string[] args)
		{
			var str = Console.ReadLine().Split(' ');
			var マスの数 = int.Parse(str[0]); // 2 ~ 10^5
			var 道の数 = マスの数 - 1;
			var マスの情報 = new List<int>[マスの数 + 1];

			for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
			{
				マスの情報[マスの番号] = new List<int>();
			}

			for (var 道の番号 = 0; 道の番号 < 道の数; 道の番号++)
			{
				var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
				マスの情報[一つの道の情報[0]].Add(一つの道の情報[1]);
				マスの情報[一つの道の情報[1]].Add(一つの道の情報[0]);
			}

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var 合計シミュレート回数 = Math.Min(20000, Math.Max(1, 200000000 / (マスの数 * マスの数) ));
			int 一回のシミュレート回数 = Math.Max(1, (int)Math.Sqrt(合計シミュレート回数) / 2);
			int 繰り返す数 = Math.Max(1, 合計シミュレート回数 / 一回のシミュレート回数);
			var マスの色の情報 = new マスの色[マスの数 + 1];
			var フェネックの最初のマス = 1;
			var すぬけくんの最初のマス = マスの数;
			var 乱数 = new System.Random();
			var フェネックの定跡本 = new List<int>();
			var すぬけくんの定跡本 = new List<int>();

			var 生き延びた最大ターン = -1;
			var フェネックの生き延びた最大ターン = -1;
			var すぬけくんの生き延びた最大ターン = -1;
			var 只今の勝者 = プレイヤー.謎の第三者;

			Func<int, List<int>, List<int>, プレイヤー> シミュレート = (シミュレート回数, フェネックの定跡, すぬけくんの定跡) =>
			{
				var 新しいフェネックの定跡 = new List<int>();
				var 新しいすぬけくんの定跡 = new List<int>();

				for (var 回数 = 0; 回数 < シミュレート回数; 回数++)
				{
					var フェネックの進める箇所 = new List<int>();
					var すぬけくんの進める箇所 = new List<int>();

					var フェネックの今回の選択 = new List<int>();
					var すぬけくんの今回の選択 = new List<int>();

					for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
					{
						マスの色の情報[マスの番号] = マスの色.透明;
					}
					マスの色の情報[フェネックの最初のマス] = マスの色.黒;
					マスの色の情報[すぬけくんの最初のマス] = マスの色.白;

					フェネックの進める箇所.AddRange(マスの情報[フェネックの最初のマス]);
					すぬけくんの進める箇所.AddRange(マスの情報[すぬけくんの最初のマス]);

					var 最大ターン数 = 1 + マスの数 / 2;
					for (var ターン = 0; ターン < 最大ターン数; ターン++)
					{
						// 先行はフェネック
						bool フェネックが移動していない = true;
						if (フェネックの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < フェネックの定跡.Count ? フェネックの定跡[ターン] : 乱数.Next(0, フェネックの進める箇所.Count);
							var 保存領域 = フェネックの進める箇所[0];
							フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番優先したいところ];
							フェネックの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = フェネックの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								フェネックの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.黒;
								フェネックの進める箇所.AddRange(マスの情報[移動候補]);
								フェネックが移動していない = false;
								break;
							}
							フェネックの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (フェネックが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.すぬけくん;
								生き延びた最大ターン = ターン;
							}
							if (すぬけくんの生き延びた最大ターン < ターン)
							{
								すぬけくんの生き延びた最大ターン = ターン;
								新しいすぬけくんの定跡 = すぬけくんの今回の選択;
							}
							break;
						}

						bool すぬけくんが移動していない = true;
						if (すぬけくんの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < すぬけくんの定跡.Count ? すぬけくんの定跡[ターン] : 乱数.Next(0, すぬけくんの進める箇所.Count);
							var 保存領域 = すぬけくんの進める箇所[0];
							すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番優先したいところ];
							すぬけくんの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = すぬけくんの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								すぬけくんの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.白;
								すぬけくんの進める箇所.AddRange(マスの情報[移動候補]);
								すぬけくんが移動していない = false;
								break;
							}
							すぬけくんの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (すぬけくんが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.フェネック;
								生き延びた最大ターン = ターン;
							}
							if (フェネックの生き延びた最大ターン < ターン)
							{
								フェネックの生き延びた最大ターン = ターン;
								新しいフェネックの定跡 = フェネックの今回の選択;
							}
							break;
						}
					}
				}

				switch (只今の勝者)
				{
					case プレイヤー.フェネック:
						フェネックの定跡 = 新しいフェネックの定跡;
						すぬけくんの定跡.Clear();
						break;
					case プレイヤー.すぬけくん:
						フェネックの定跡.Clear();
						すぬけくんの定跡 = 新しいすぬけくんの定跡;
						break;
				}

				return 只今の勝者;
			};

			for (var 世代 = 0; 世代 < 繰り返す数; 世代++)
			{
				シミュレート(一回のシミュレート回数, フェネックの定跡本, すぬけくんの定跡本);
			}

			Console.WriteLine(只今の勝者 == プレイヤー.フェネック ? フェネックの名前 : すぬけくんの名前);
		}
	}
}

