namespace ConsoleApp15
{
    class Class395
    {
        static void Main()
        {
            int N = int.Parse(Console.ReadLine());

            var G = new List<int>[N];
            for (int i = 0; i < N; i++) G[i] = new List<int>();
            for(int i = 0; i < N - 1; i++)
            {
                var ab = Console.ReadLine().Split().Select(_=>int.Parse(_)-1).ToArray();
                G[ab[0]].Add(ab[1]);
                G[ab[1]].Add(ab[0]);
            }

            int[] frags = Enumerable.Repeat(-1, N).ToArray();
            frags[0] = 0;
            frags[N - 1] = 1;
            var que = new Queue<Tuple<int, int>>();
            que.Enqueue(Tuple.Create(0, 0));
            que.Enqueue(Tuple.Create(N - 1, 1));

            while (que.Count > 0)
            {
                var t = que.Dequeue();
                var now = t.Item1;
                var color = t.Item2;

                foreach (var i in G[now])
                {
                    if (frags[i] == -1)
                    {
                        frags[i] = color;
                        que.Enqueue(Tuple.Create(i, color));
                    }
                }
            }

            int fnk = frags.Count(_ => _ == 0);
            int snk = N - fnk;
            Console.WriteLine(fnk>snk?"Fennec":"Snuke");
        }
    }
}

