namespace ProgramingStudying2
{
    class Program
    {

        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());

            var G = new List<List<int>>();

            for (int i = 0; i < n; i++) 
            {
                G.Add(new List<int>());
            }

            for(int i = 0; i < n - 1; i++)
            {
                var ab = Console.ReadLine().Split().Select(int.Parse).ToArray();
                var a = ab[0] - 1;
                var b = ab[1] - 1;

                G[a].Add(b);
                G[b].Add(a);
            }

            //各ノードの色,-1:色なし,1:黒,0:白
            var colors = Enumerable.Repeat(-1, n).ToArray();
            colors[0] = 1;
            colors[n - 1] = 0;

            //BFS回すためのキュー
            var que = new Queue<(int, int)>();
            que.Enqueue((0, 1));
            que.Enqueue((n - 1, 0));

            //BFS
            while (que.Count > 0)
            {
                var (x, color) = que.Dequeue();
                foreach(var nx in G[x])
                {
                    if(colors[nx] == -1)
                    {
                        colors[nx] = color;
                        que.Enqueue((nx, color));
                    }
                }
            }

            //黒白マスの個数をカウント
            var black = colors.Sum();
            var white = n - black;

            /*
            Console.WriteLine(black);
            Console.WriteLine(white);
            */

            Console.WriteLine(black > white ? "Fennec" : "Snuke");
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
	public class Program
	{
		// TLEがないやつ
		// http://abc067.contest.atcoder.jp/submissions/1431970
		// クラスにしたやつ
		// http://abc067.contest.atcoder.jp/submissions/1431941

		static string フェネックの名前 = "Fennec";
		static string すぬけくんの名前 = "Snuke";

		enum マスの色
		{
			透明 = 0,
			黒,
			白,
		};

		enum プレイヤー
		{
			謎の第三者 = マスの色.透明,
			フェネック = マスの色.黒,
			すぬけくん = マスの色.白,
		};

		public static void Main(string[] args)
		{
			var str = Console.ReadLine().Split(' ');
			var マスの数 = int.Parse(str[0]); // 2 ~ 10^5
			var 道の数 = マスの数 - 1;
			var マスの情報 = new List<int>[マスの数 + 1];

			for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
			{
				マスの情報[マスの番号] = new List<int>();
			}

			for (var 道の番号 = 0; 道の番号 < 道の数; 道の番号++)
			{
				var 一つの道の情報 = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
				マスの情報[一つの道の情報[0]].Add(一つの道の情報[1]);
				マスの情報[一つの道の情報[1]].Add(一つの道の情報[0]);
			}

			// ループしない木なので、相手に向かって塗って、その後は自分の面積の大きい方が勝ちみたいな感じにしたい
			// 同点なら後攻のすぬけくんの勝ち
			// よくわかんないのでモンテカルロっぽい何かで挑む
			var 合計シミュレート回数 = 1;
			int 一回のシミュレート回数 = 60;
			int 繰り返す数 = Math.Max(1, 合計シミュレート回数 / 一回のシミュレート回数);
			var マスの色の情報 = new マスの色[マスの数 + 1];
			var フェネックの最初のマス = 1;
			var すぬけくんの最初のマス = マスの数;
			var 乱数 = new System.Random();
			var フェネックの定跡本 = new List<int>();
			var すぬけくんの定跡本 = new List<int>();

			var 生き延びた最大ターン = -1;
			var フェネックの生き延びた最大ターン = -1;
			var すぬけくんの生き延びた最大ターン = -1;
			var 只今の勝者 = プレイヤー.謎の第三者;

			Func<int, List<int>, List<int>, プレイヤー> シミュレート = (シミュレート回数, フェネックの定跡, すぬけくんの定跡) =>
			{
				var 新しいフェネックの定跡 = new List<int>();
				var 新しいすぬけくんの定跡 = new List<int>();

				for (var 回数 = 0; 回数 < シミュレート回数; 回数++)
				{
					var フェネックの進める箇所 = new List<int>();
					var すぬけくんの進める箇所 = new List<int>();

					var フェネックの今回の選択 = new List<int>();
					var すぬけくんの今回の選択 = new List<int>();

					for (var マスの番号 = 0; マスの番号 < マスの数 + 1; マスの番号++)
					{
						マスの色の情報[マスの番号] = マスの色.透明;
					}
					マスの色の情報[フェネックの最初のマス] = マスの色.黒;
					マスの色の情報[すぬけくんの最初のマス] = マスの色.白;

					フェネックの進める箇所.AddRange(マスの情報[フェネックの最初のマス]);
					すぬけくんの進める箇所.AddRange(マスの情報[すぬけくんの最初のマス]);

					var 最大ターン数 = 1 + マスの数 / 2;
					for (var ターン = 0; ターン < 最大ターン数; ターン++)
					{
						// 先行はフェネック
						bool フェネックが移動していない = true;
						if (フェネックの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < フェネックの定跡.Count ? フェネックの定跡[ターン] : 乱数.Next(0, フェネックの進める箇所.Count);
							var 保存領域 = フェネックの進める箇所[0];
							フェネックの進める箇所[0] = フェネックの進める箇所[次の移動候補で一番優先したいところ];
							フェネックの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < フェネックの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = フェネックの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								フェネックの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.黒;
								フェネックの進める箇所.AddRange(マスの情報[移動候補]);
								フェネックが移動していない = false;
								break;
							}
							フェネックの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (フェネックが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.すぬけくん;
								生き延びた最大ターン = ターン;
							}
							if (すぬけくんの生き延びた最大ターン < ターン)
							{
								すぬけくんの生き延びた最大ターン = ターン;
								新しいすぬけくんの定跡 = すぬけくんの今回の選択;
							}
							break;
						}

						bool すぬけくんが移動していない = true;
						if (すぬけくんの進める箇所.Count > 1)
						{
							var 次の移動候補で一番優先したいところ = ターン < すぬけくんの定跡.Count ? すぬけくんの定跡[ターン] : 乱数.Next(0, すぬけくんの進める箇所.Count);
							var 保存領域 = すぬけくんの進める箇所[0];
							すぬけくんの進める箇所[0] = すぬけくんの進める箇所[次の移動候補で一番優先したいところ];
							すぬけくんの進める箇所[次の移動候補で一番優先したいところ] = 保存領域;
						}
						for (var 移動候補の番号 = 0; 移動候補の番号 < すぬけくんの進める箇所.Count; 移動候補の番号++)
						{
							var 移動候補 = すぬけくんの進める箇所[移動候補の番号];
							if (マスの色の情報[移動候補] == マスの色.透明)
							{
								すぬけくんの今回の選択.Add(移動候補の番号);
								マスの色の情報[移動候補] = マスの色.白;
								すぬけくんの進める箇所.AddRange(マスの情報[移動候補]);
								すぬけくんが移動していない = false;
								break;
							}
							すぬけくんの進める箇所.RemoveAt(移動候補の番号);
							移動候補の番号--;
						}

						if (すぬけくんが移動していない)
						{
							if (生き延びた最大ターン < ターン)
							{
								只今の勝者 = プレイヤー.フェネック;
								生き延びた最大ターン = ターン;
							}
							if (フェネックの生き延びた最大ターン < ターン)
							{
								フェネックの生き延びた最大ターン = ターン;
								新しいフェネックの定跡 = フェネックの今回の選択;
							}
							break;
						}
					}
				}

				switch (只今の勝者)
				{
					case プレイヤー.フェネック:
						フェネックの定跡 = 新しいフェネックの定跡;
						すぬけくんの定跡.Clear();
						break;
					case プレイヤー.すぬけくん:
						フェネックの定跡.Clear();
						すぬけくんの定跡 = 新しいすぬけくんの定跡;
						break;
				}

				return 只今の勝者;
			};

			for (var 世代 = 0; 世代 < 繰り返す数; 世代++)
			{
				シミュレート(一回のシミュレート回数, フェネックの定跡本, すぬけくんの定跡本);
			}

			Console.WriteLine(只今の勝者 == プレイヤー.フェネック ? フェネックの名前 : すぬけくんの名前);
		}
	}
}

using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Text;

public class Program
{

	public void Proc()
	{
        int nodeCount = int.Parse(Reader.ReadLine());
        this.NodeList = new TreeNode[nodeCount];

        Dictionary<int, Dictionary<int, bool>> path = new Dictionary<int, Dictionary<int, bool>>();

        for (int i = 0; i < nodeCount; i++) {
            NodeList[i] = new TreeNode(i);
        }
        for (int i = 0; i < nodeCount - 1; i++) {
            int[] inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)-1).ToArray();
            inpt.ToList().ForEach(a=>{
                if(!path.ContainsKey(a)) {
                    path.Add(a, new Dictionary<int, bool>());
                }
            });
            path[inpt[0]].Add(inpt[1], true);
            path[inpt[1]].Add(inpt[0], true);
        }
		Queue<int> que = new Queue<int>();
        path[0].ToList().ForEach(a =>
        {
            NodeList[0].AddItem(NodeList[a.Key]);
            que.Enqueue(a.Key);
        });
        while(que.Count()>0) {
            int current = que.Dequeue();
            path[current].ToList().ForEach(a =>
            {
                if(a.Key != NodeList[current].Parent.Id) {
                    NodeList[current].AddItem(NodeList[a.Key]);
                    que.Enqueue(a.Key);
                }
            });
        }
        NodeList[0].RefreshDepth();
        int feneck = (NodeList.Last().Depth - 1) / 2;
        int sunuke = feneck;
        sunuke += NodeList.Last().GetSubNodeCount();
        feneck = nodeCount - 2 - sunuke;
        string ans = "Snuke";
        if (feneck>sunuke) {
            ans = "Fennec";
        }
        Console.WriteLine(ans);
    }

    private TreeNode[] NodeList;

    private class TreeNode
    {
        public int Id;

        public int Depth = 0;
        public TreeNode Parent;
        public List<TreeNode> Items = new List<TreeNode>();
        public TreeNode(int id)
        {
            this.Id = id;
        }
        public void AddItem(TreeNode child)
        {
            this.Items.Add(child);
            child.Parent = this;
        }

        public int GetSubNodeCount() {
            if(this.Items.Count == 0) {
                return 0;
            }
            int ans = this.Items.Count;
            this.Items.ForEach(a=>{
                ans += a.GetSubNodeCount();
            });
            return ans;
        }
        public void RefreshDepth() {
            if(this.Parent == null) {
                this.Depth = 0;
            } else {
                this.Depth = Parent.Depth + 1;
            }
            this.Items.ForEach(a=>a.RefreshDepth());
        }
    }


    public class Reader
	{
		private static StringReader sr;
		public static bool IsDebug = false;
		public static string ReadLine()
		{
			if (IsDebug)
			{
				if (sr == null)
				{
					sr = new StringReader(InputText.Trim());
				}
				return sr.ReadLine();
			}
			else
			{
				return Console.ReadLine();
			}
		}
