class MyUtil
{
    public static int[] ReadIntArray()
    {
	return ReadLine().Split().Select(x => int.Parse(x)).ToArray();
    }

    public static void WarshallFloyd(char[,] d, int v)
    {
	for (int k = 0; k < v; k++)
	    for (int i = 0; i < v; i++)
		for (int j = 0; j < v; j++)
		    d[i, j] = (char) Math.Min(d[i, j], d[i, k] + d[k, j]);
    }
}

class Program
{
    public static void Main()
    {
	int n = int.Parse(ReadLine());
	char [,] e = new char[10,10];
	try{
	e = new char[n,n];
	} catch {WriteLine(0); return; }

	for (int i = 0; i < n; i++)
	    for (int j = 0; j < n; j++)
		e[i, j] = (char) n;

	for (int i = 0; i < n-1; i++)
	{
	    var tmp = ReadIntArray();
	    int a = tmp[0] - 1, b = tmp[1] - 1;
	    e[a,b] = e[b,a] = (char) 1;
	}

	WarshallFloyd(e, n);

	int fmax=0, smax=0; // f: Fennec, s: Snuke

	for (int i = 1; i < n-1; i++)
	{
	    // calc fmax
	    int flen = (int) e[0, i];
	    int slen = (int) e[n-1, i];
	    if (flen <= slen) // >= because f moves first
	    {
		fmax++;
	    }
	    else
	    {
		smax++;
	    }
	}

	WriteLine(fmax > smax ? "Fennec" : "Snuke");
    }
}

