using System;
using System.Text; 
using System.Collections.Generic;
using System.Linq;

public class Remainder
{
    static Node[] Nodes;
    static long N;

    static public void Main ()
    {
        N = long.Parse(Console.ReadLine());


        Nodes = new Node[N+1];
        //ノードを初期化
        for(int i = 1;i <= N ;i++){
            Nodes[i] = new Node();
        }

        for(int i = 1;i < N ;i++){
            var AB = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
            var A = AB[0];
            var B = AB[1];

            //子ノードを登録
            Nodes[A].child.Add(B);
            Nodes[B].child.Add(A);
        } 

        fwfs();
        swfs();
        var snum = 0;
        var fnum = 0;

        for(int i = 1;i <= N ;i++){
            if(Nodes[i].fnum >= Nodes[i].snum){
                fnum++;
            }else{
                snum++;
            }
        }

        if(fnum > snum){
            Console.WriteLine("Fennec ");
        }else{
            Console.WriteLine("Snuke");
        }


    }

    static void fwfs(){
        var que = new Queue<Node>();
        Nodes[N].fnum = 0;
        que.Enqueue(Nodes[N]);

        while(que.Count > 0){
            var top = que.Dequeue();
            foreach(long child in top.child){
                if(Nodes[child].fnum == long.MaxValue){
                    Nodes[child].fnum = top.fnum+1;
                    que.Enqueue(Nodes[child]);
                }
            }
        }
    }

    static void swfs(){
        var que = new Queue<Node>();
        Nodes[1].snum = 0;
        que.Enqueue(Nodes[1]);

        while(que.Count > 0){
            var top = que.Dequeue();
            foreach(long child in top.child){
                if(Nodes[child].snum == long.MaxValue){
                    Nodes[child].snum = top.snum+1;
                    que.Enqueue(Nodes[child]);
                }
            }
        }
    }



}

public class Node{
    public List<long> child;
    public long fnum = long.MaxValue;
    public long snum = long.MaxValue;
    public Node(){
        this.child = new List<long>();
    } 
}

