        // 領土確認
        private static int GetArea(int iBs, List<List<int>> lstForB)
        {
            int iRet = -1;
            List<int> lstTemp = lstForB[iBs];               // iBsからの先一覧

            Boolean bFen = false;
            Boolean bSnk = false;
            for (int i = 0; i < lstTemp.Count; i++)         // iBsからの先一覧
            {
                if (lstTemp[i] == iFen) { bFen = true; }    // 次にFennecの場合
                if (lstTemp[i] == iSnk) { bSnk = true; }    // 次にSnuke の場合
            }
            if (bFen && bSnk) { iRet = 0; }                 // 境界
            else if (bFen) { iRet = 1; }                    // Fennecの領土
            else if (bSnk) { iRet = 2; }                    // Snuke の領土
            else
            {
                for (int i = 0; i < lstTemp.Count; i++)     // iBsからの先一覧
                {
                    iRet = GetArea(lstTemp[i], lstForB);    // 領土判別
                    if (iRet != -1) { break; }              // 領土判別したら抜ける
                }
            }
            return iRet;
        }

        // 拠点の相手経路判別
        private static void GetForB(List<List<int>> lstForB, List<ClsAtoB> lstRute)
        {
            for (int i = iFen; i <= iSnk; i++)                                              // 10万
            {
                List<int> oneUsr = new List<int>();
                for (int j = 0; j < lstRute.Count; j++)                                     // 20万
                {
                    if (lstRute[j].iA == i) { oneUsr.Add(lstRute[i].iB); }
                }
                lstForB.Add(oneUsr);
            }
        }

        private class ClsAtoB                   // 経路用
        {
            public int iA { get; set; } = 0;
            public int iB { get; set; } = 0;
        }

}

