using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
namespace AtCoder {
    class MainClass {
        public static void Main(string[] args) { new MainClass().solve(); }
        Scanner cin;

        int N;
        int[] a, b;
        void solve() {
            cin = new Scanner();

            N = cin.nextInt();
            a = new int[N - 1];
            b = new int[N - 1];

            for (int i = 0; i < N - 1; i++) {
                a[i] = cin.nextInt();
                b[i] = cin.nextInt();
                a[i]--;
                b[i]--;
            }

            WarshallFloyd wf = new WarshallFloyd();
            int[,] dis = wf.Init(N);

            for (int i = 0; i < N - 1; i++) {
                dis[a[i], b[i]] = dis[b[i], a[i]] = 1;
            }

            dis = wf.Run(dis);
            int black = 0;
            for (int i = 0; i < N; i++)
                if (dis[0, i] <= dis[N - 1, i]) black++;

            Console.WriteLine(black >= (N - black) ? "Fennec" : "Snuke");

        }

        class Scanner {
            string[] nextBuffer; int BufferCnt; char[] cs = new char[] { ' ' };
            public Scanner() { nextBuffer = new string[0]; BufferCnt = 0; }
            public string next() {
                if (BufferCnt < nextBuffer.Length) return nextBuffer[BufferCnt++];
                string st = Console.ReadLine();
                while (st == "") st = Console.ReadLine();
                nextBuffer = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
                BufferCnt = 0;
                return nextBuffer[BufferCnt++];
            }
            public int nextInt() { return int.Parse(next()); }
            public long nextLong() { return long.Parse(next()); }
            public double nextDouble() { return double.Parse(next()); }
        }
        class WarshallFloyd {
            int INF;
            public WarshallFloyd() {
                INF = (int)(1e8);
            }
            public WarshallFloyd(int INF) {
                this.INF = INF;
            }
            public int[,] Run(int[,] m) {
                int edgeLength = m.GetLength(0);
                for (int i = 0; i < edgeLength; i++)
                    for (int j = 0; j < edgeLength; j++)
                        for (int k = 0; k < edgeLength; k++)
                            m[j, k] = Math.Min(m[j, k], m[j, i] + m[i, k]);
                return m;
            }
            public int[,] Init(int n) {
                int[,] m = new int[n, n];
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++)
                        m[i, j] = INF;
                for (int i = 0; i < n; i++)
                    m[i, i] = 0;
                return m;
            }
        }
    }
