var get_distance = function (_from) {
    var visited = new std.set();
    visited.insert(_from);

    var distance = [];
    var to_visit = new std.queue();
    to_visit.push([0,_from]);
    while(!to_visit.empty()){
        var dist_now = to_visit.front();
        to_visit.pop();
        var dist = dist_now[0];
        var now = dist_now[1];
        //print(dist_now);

        visited.insert(now);
        distance[now] = dist;
        for(var i=0;i<d[now].length;i++){
            //if(visited.indexOf(d[now][i])<0){
            if(visited.find(d[now][i])==visited.end()){
                to_visit.push([dist+1,d[now][i]])
            }
        }
    };
    return distance
};




