function Main(input) {
  input = input.split("\n");
  var n = parseInt(input[0]);
  a = new Array(n-1).fill(0);
  b = new Array(n-1).fill(0);
  for(i=0;i<n-1;i++){
    tmp = input[i+1].split(" ");
    a[i]=parseInt(tmp[0])-1;
    b[i]=parseInt(tmp[1])-1;
  }
  d = new Array(n).fill(0);
  d[0]=1;
  d[n-1]=2;

  function f(x,a,b,d){
    for(i=0;i<n-1;i++){
      if(a[i]==x){
        if(d[b[i]]==0){


        d[b[i]]=3;
        var j =i;
        f(b[i],a,b,d);
        i=j;
        }else if(d[b[i]]==2){
          if(d[a[i]]!=1){
            d[a[i]]=4;
          }
        }
      }
      if(b[i]==x){
        if(d[a[i]]==0){


        d[a[i]]=3;
        var j=i;
        f(a[i],a,b,d);
        i=j;
        }else if(d[a[i]]==2){
          if(d[b[i]]!=1){
            d[b[i]]=4;
          }
        }
      }
    }
    return d;
  }
  d = f(0,a,b,d);
  y = new Array(5).fill(0);
  for(i=0;i<n;i++){
    y[d[i]]++;
  }
  var ans="Fennec";
  if(y[0]>y[3]){
    ans="Snuke";
  }
  console.log('%s', ans);
}
