//8:半角SPで結合 9:改行で結合 0:文字なしで結合
function myconv(i,no){try{switch(no){case 1:return parseInt(i);case 2:return i.split(" ");case 4:return i.split(" ").map(Number);case 6:return i.split("");case 7:return i.split("").map(Number);case 8:return i.join(" ");case 9:return i.join("\n");case 0:return i.join("");default:return i;}}catch(e){return i;}}
function Main(){
	var N = nextInt();
	var list = new Array(N);
	for(var i = 0; i < N; i++){
		list[i] = {
			child : new Set(),
			from : null,
			access : false,
			color : null,
			count : 0
		};
	}
	for(var i = 0; i < N - 1; i++){
		var tmp = nextIntArray();
		list[tmp[0] - 1].child.add(tmp[1] - 1);
		list[tmp[1] - 1].child.add(tmp[0] - 1);
	}

	var queue = new Array(100007);
	queue[0] = 0;
	list[0].access = true;
	var mae = 0;
	var ato = 1;
	while(mae != ato){
		var parent = queue[mae];
		mae++;
		if(parent == N - 1){
			break;
		}
		var child = Array.from(list[parent].child);
		for(var i = 0; i < child.length; i++){
			if(!list[child[i]].access){
				list[child[i]].access = true;
				list[child[i]].from = parent;
				queue[ato] = child[i];
				list[child[i]].count = list[parent].count + 1;
				ato++;
			}
		}
	}


	var cut = Math.ceil(list[N - 1].count / 2);
	var now = N - 1;
	while(cut != 0){
		now = list[now].from;
		cut--;
	}
	list[0].color = "BLACK";
	list[N - 1].color = "WHITE";
	list[now].color = "BLACK";
	bfs(0,"BLACK");
	bfs(N - 1,"WHITE");
	var w = 0;
	var b = 0;
	for(var i = 0; i < N; i++){
		if(list[i].color == "WHITE"){
			w++;
		}else{
			b++;
		}
	}
	if(b > w){
		myout("Fennec");
	}else{
		myout("Snuke");
	}
	function bfs(index, color){
		var queue = new Array(100007);
		var mae = 0;
		var ato = 1;
		queue[mae] = index;
		while(mae != ato){
			var parent = queue[mae];
			mae++;
			var child = Array.from(list[parent].child);
			for(var i = 0; i < child.length; i++){
				if(list[child[i]].color == null){
					queue[ato] = child[i];
					ato++;
					list[child[i]].color = color;
				}
			}
		}
	}
}

function Main(input) {
  input = input.split("\n");
  var n = parseInt(input[0]);
  a = new Array(n-1).fill(0);
  b = new Array(n-1).fill(0);
  for(i=0;i<n-1;i++){
    tmp = input[i+1].split(" ");
    a[i]=parseInt(tmp[0])-1;
    b[i]=parseInt(tmp[1])-1;
  }
  d1 = new Array(n).fill(n);
  d1[0]=0;
  d2 = new Array(n).fill(n);
  d2[n-1]=0;
  function f(x,d){
    for(i=0;i<n-1;i++){
      if(a[i]==x&&d[b[i]]>d[a[i]]){
        d[b[i]]=d[a[i]]+1;
        var j =i;
        f(b[i],d);
        i=j;
      }
      if(b[i]==x&&d[a[i]]>d[b[i]]){
        d[a[i]]=d[b[i]]+1;
        var j =i;
        f(a[i],d);
        i=j;
      }
    }
    return d;
  }
  d1=f(0,d1);
  d2=f(n-1,d2);
  var x=0;
  for(i=0;i<n;i++){
    if(i!=0&&i!=n-1){
      if(d1[i]<=d2[i]){
        x++;
      }
    }
  }
  var ans="Fennec";
  if(x<=n-2-x){
    ans="Snuke";
  }

  console.log('%s', ans);
}
