const MOD = int(1e+9) + 7
const INF = 1 << 60

func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	N := sc.nextInt()
	G := make([][]int, N)
	for i := 0; i < N-1; i++ {
		a, b := sc.nextInt()-1, sc.nextInt()-1
		G[a] = append(G[a], b)
		G[b] = append(G[b], a)
	}
	q := &Queue{}
	D1 := make([]int, N)
	D2 := make([]int, N)
	for i := 0; i < N; i++ {
		D1[i] = -1
		D2[i] = -1
	}
	bfs := func(cur int, D []int) {
		for i := 0; i < len(G[cur]); i++ {
			next := G[cur][i]
			if D[next] == -1 {
				D[next] = D[cur] + 1
				q.push(next)
			}
		}
	}
	D1[0] = 0
	q.push(0)
	for !q.isEmpty() {
		bfs(q.pop(), D1)
	}
	D2[N-1] = 0
	q.push(N - 1)
	for !q.isEmpty() {
		bfs(q.pop(), D2)
	}
	black, white := 0, 0
	for i := 0; i < N; i++ {
		if D1[i] <= D2[i] {
			black++
		} else {
			white++
		}
	}

	if black > white {
		fmt.Fprintln(wtr, "Fennec")
	} else {
		fmt.Fprintln(wtr, "Snuke")
	}
}

type Queue struct {
	arr []int
}

func (q *Queue) push(v int) {
	q.arr = append(q.arr, v)
}

func (q *Queue) pop() int {
	res := q.arr[0]
	q.arr = q.arr[1:]
	return res
}

func (q *Queue) isEmpty() bool {
	return len(q.arr) == 0
}

