var sc = bufio.NewScanner(os.Stdin)

func Scanner() string {
	sc.Scan()
	return sc.Text()
}

func main() {
	buf := make([]byte, 0)
	sc.Buffer(buf, 1000000007)
	sc.Split(bufio.ScanWords)
	n, _ := strconv.Atoi(Scanner())
	tree := make([][]int, n)
	for i := 0; i < n-1; i++ {
		a, _ := strconv.Atoi(Scanner())
		b, _ := strconv.Atoi(Scanner())
		a--
		b--
		tree[a] = append(tree[a], b)
		tree[b] = append(tree[b], a)
	}
	fq := []int{0}
	fd := make([]int, n)
	for i := 1; i < n; i++ {
		fd[i] = -1
	}
	for {
		v := fq[0]
		fq = fq[1:]
		for _, j := range tree[v] {
			if fd[j] == -1 {
				fq = append(fq, j)
				fd[j] = fd[v] + 1
			}
		}
		if len(fq) == 0 {
			break
		}
	}
	sq := []int{n - 1}
	sd := make([]int, n)
	for i := 0; i < n-1; i++ {
		sd[i] = -1
	}
	for {
		v := sq[0]
		sq = sq[1:]
		for _, j := range tree[v] {
			if sd[j] == -1 {
				sq = append(sq, j)
				sd[j] = sd[v] + 1
			}
		}
		if len(sq) == 0 {
			break
		}
	}
	path := []int{0}
	tmp := 0
	for {
		if tmp == n-1 {
			break
		} else {
			for _, i := range tree[tmp] {
				if sd[i] == sd[tmp]-1 {
					path = append(path, i)
					tmp = i
					break
				}
			}
		}
	}
	fok := make(map[int]struct{})
	sok := make(map[int]struct{})
	for i := 0; i < len(path); i++ {
		if _, ok := sok[path[i]]; !ok {
			fok[path[i]] = struct{}{}
		}
		if _, ok := fok[path[len(path)-1-i]]; !ok {
			sok[path[len(path)-1-i]] = struct{}{}
		}
	}
	fq = []int{0}
	fd[0] = 1
	for i := 1; i < n; i++ {
		fd[i] = -1
	}
	fc := 1
	for {
		v := fq[0]
		fq = fq[1:]
		for _, j := range tree[v] {
			if _, ok := sok[j]; fd[j] == -1 && !ok {
				fq = append(fq, j)
				fd[j] = 1
				fc++
			}
		}
		if len(fq) == 0 {
			break
		}
	}
	sq = []int{n - 1}
	sd[n-1] = 1
	for i := 0; i < n-1; i++ {
		sd[i] = -1
	}
	sc := 1
	for {
		v := sq[0]
		sq = sq[1:]
		for _, j := range tree[v] {
			if _, ok := fok[j]; sd[j] == -1 && !ok {
				sq = append(sq, j)
				sd[j] = 1
				sc++
			}
		}
		if len(sq) == 0 {
			break
		}
	}
	if fc > sc {
		fmt.Println("Fennec")
	} else {
		fmt.Println("Snuke")
	}
}

