var DEBUG = true

func main() {
	defer Flush()

	N := readi()

	G := make([][]int, N)
	for i := 0; i < N-1; i++ {
		a := readi() - 1
		b := readi() - 1
		G[a] = append(G[a], b)
		G[b] = append(G[b], a)
	}

	fe := bfs(G, 0)
	su := bfs(G, N-1)

	var cf, cs int
	for i := 0; i < N; i++ {
		if fe[i] <= su[i] {
			cf++
		} else {
			cs++
		}
	}

	if cs < cf {
		println("Fennec")
	} else {
		println("Snuke")
	}

}

func bfs(G [][]int, start int) []int {
	N := len(G)

	q := make([]int, 0)
	push := func(x int) {
		q = append(q, x)
	}
	pop := func() int {
		res := q[0]
		q = q[1:]
		return res
	}

	d := make([]int, N)
	for i := range d {
		d[i] = INF
	}
	push(start)
	d[start] = 0

	for len(q) != 0 {
		v := pop()
		for _, u := range G[v] {
			nd := d[v] + 1
			if nd < d[u] {
				d[u] = nd
				push(u)
			}
		}
	}
	return d
}

