func main() {
	var n int
	fmt.Scan(&n)

	g := make([][]int, n)
	var a, b int
	for i := 0; i < n-1; i++ {
		fmt.Scan(&a, &b)
		a--
		b--
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}

	var dfs func(v, p, x int) int
	dfs = func(v, p, x int) int {
		if v == x {
			return 0
		}
		cnt := 1
		for _, u := range g[v] {
			if u != p {
				cnt += dfs(u, v, x)
			}
		}
		return cnt
	}

	c1 := dfs(0, -1, n-1)
	c2 := dfs(n-1, -1, 0)
	if c1 >= c2 {
		fmt.Println("Fennec")
	} else {
		fmt.Println("Snuke")
	}
}

