const INF int = 1000000000

func bfs(graph [][]int, dist []int, start int) {
	q := make([]int, 0)

	push := func(x int) {
		q = append(q, x)
	}
	pop := func() int {
		res := q[0]
		q = q[1:]
		return res
	}

	push(start)
	dist[start] = 0

	for len(q) != 0 {
		u := pop()
		for _, v := range graph[u] {
			if dist[v] != INF {
				continue
			}
			dist[v] = dist[u] + 1
			push(v)
		}
	}
}
func main() {
	var n int
	fmt.Scan(&n)

	var graph = make([][]int, n)
	for i := 0; i < n - 1; i++ {
		var a, b int
		fmt.Scan(&a, &b)
		a--
		b--
		graph[a] = append(graph[a], b)
		graph[b] = append(graph[b], a)
	}

	var distF = make([]int, n)
	var distS = make([]int, n)
	for i := 0; i < n; i++ {
		distS[i] = INF
		distF[i] = INF
	}

	bfs(graph, distF, 0)
	bfs(graph, distS, n - 1)

	var countF, countS int
	for i := 0; i < n; i++ {
		if distF[i] <= distS[i] {
			countF++
		} else {
			countS++
		}
	}

	if countF > countS {
		fmt.Printf("Fennec")
	} else {
		fmt.Println("Snuke")
	}
}

