	tree := make([][]int, N+1)
	for i := 1; i < N + 1; i++ {
		tree[i] = make([]int, 0)
	}
	for i := 0; i < N - 1; i++ {
		var a, b int
		_, _ = fmt.Scan(&a, &b)
		tree[a] = append(tree[a], b)
		tree[b] = append(tree[b], a)
	}
	var q []int
	qq := []int{1}
	dist := 0
	passed := make([]bool, N+1)
	for {
		q = qq
		qq = make([]int, 0)
		dist++
		for i := 0; i < len(q); i++ {
			if len(tree[q[i]]) == 0 {
				continue
			}
			for j := 0; j < len(tree[q[i]]); j++ {
				next := tree[q[i]][j]
				if passed[next] {
					continue
				}
				if next == N {
					if dist % 2 == 0 {
						fmt.Println("Fennec")
					} else {
						fmt.Println("Snuke")
					}
					return
				} else {
					qq = append(qq, next)
					passed[next] = true
				}
			}
		}
	}
}

