/*********** PriorityQueue ***********/
type PriorityQueue struct {
    arr []interface{}
    comps []CompFunc
}
/*
p < q ... -1
p == q ... 0
p > q ...  1
*/
type CompFunc func(p, q interface{}) int

func NewPriorityQueue() *PriorityQueue {
    return new(PriorityQueue)
}

func (pq PriorityQueue) Len() int {
    return len(pq.arr)
}

func (pq PriorityQueue) Swap(i, j int) {
    pq.arr[i], pq.arr[j] = pq.arr[j], pq.arr[i]
}

func (pq PriorityQueue) Less(i, j int) bool{
    for _, comp := range pq.comps {
        result := comp(pq.arr[i], pq.arr[j])
        switch result {
            case -1: return true
            case 1:  return false
            case 0:  continue
        }
    }
    return true
}

func (pq *PriorityQueue) Push(x interface{}) {
    pq.arr = append(pq.arr, x)
}

func (pq *PriorityQueue) Pop() interface{} {
    n := pq.Len()
    item := pq.arr[n - 1]
    pq.arr = pq.arr[:n - 1]
    return item
}

func (pq *PriorityQueue) IsEmpty() bool {
    return pq.Len() == 0
}



/* for dijkstra */
/* type Edge */
type Edge struct {
    to int
    cost int
}

/* type State */
type State struct {
    score int
    node int
}

/* type Graph */
type Graph struct {
    starts []State
    edges [][]Edge
    size int
    comps []CompFunc
    defaultScore int
}

func dijkstra(graph *Graph) []int {
    score := make([]int, graph.size)
    for i := 0; i < graph.size; i++ {
        score[i] = graph.defaultScore
    }
    que := new(PriorityQueue)
    que.comps = graph.comps
    for _, start := range graph.starts {
        score[start.node] = start.score
        heap.Push(que, start)
    }
    for !que.IsEmpty() {
        state := heap.Pop(que).(State)
        for _, edge := range graph.edges[state.node] {
            newScore := state.score + edge.cost
            if score[edge.to] > newScore {
                score[edge.to] = newScore
                heap.Push(que, State{score: newScore, node: edge.to})
            }
        }
    }
    return score
}

