    }
    for i := 0; i < n - 1; i++ {
        a, b := readInt() - 1, readInt() - 1
        edges[a] = append(edges[a], Edge{to:b, cost:1})
        edges[b] = append(edges[b], Edge{to:a, cost:1})
    }
    comp := func(p, q interface{}) int {
        if p.(State).score < q.(State).score {
            return -1
        } else if p.(State).score == q.(State).score {
            return 0
        } else {
            return 1
        }
        return 0
    }
    comps := make([]CompFunc, 0)
    comps = append(comps, comp)
    starts1 := make([]State, 0)
    starts2 := make([]State, 0)
    starts1 = append(starts1, State{score:0, node:0})
    starts2 = append(starts2, State{score:0, node:n - 1})

