	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	list := make([][]int, n)
	for i := 0; i < n; i++ {
		list[i] = make([]int, n)
	}

	for i := 0; i < n-1; i++ {
		a := getNextInt(scanner) - 1
		b := getNextInt(scanner) - 1
		list[a] = append(list[a], b)
		list[b] = append(list[b], a)
	}

	color := make([]int, n)

	q := make([]int, 1)
	q[0] = 0

	for len(q) > 0 {
		p := q[0]
		q = q[1:]
		if p == n-1 {
			continue
		}
		color[p] = 1
		l := len(list[p])
		for i := 0; i < l; i++ {
			if color[list[p][i]] == 1 {
				continue
			}
			q = append(q, list[p][i])
