		q = q[1:]
		if p == 0 {
			continue
		}
		color[p] |= 2
		l := len(list[p])
		for i := 0; i < l; i++ {
			if (color[list[p][i]] & 2) != 0 {
				continue
			}
			q = append(q, list[p][i])
		}
	}

	ans := [4]int{0, 0, 0, 0}
	for i := 0; i < n; i++ {
		ans[color[i]]++
	}
	ans[1]--
	ans[2]--

	out := "Snuke"
