const MOD = int(1e+9) + 7
const INF = 1 << 60

func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	N := sc.nextInt()
	G := make([][]int, N)
	for i := 0; i < N-1; i++ {
		a, b := sc.nextInt()-1, sc.nextInt()-1
		G[a] = append(G[a], b)
		G[b] = append(G[b], a)
	}
	// 0からN-1までのパス
	var R []int
	done := make([]bool, N)
	var dfs func(cur int, root []int)
	dfs = func(cur int, root []int) {
		if cur == N-1 {
			for i := 0; i < len(root); i++ {
				R = append(R, root[i])
			}
		}
		for i := 0; i < len(G[cur]); i++ {
			next := G[cur][i]
			if !done[next] {
				done[next] = true
				dfs(next, append(root, next))
			}
		}
	}
	done[0] = true
	dfs(0, []int{0})
	black := R[ceil(len(R), 2)-1]
	white := R[ceil(len(R), 2)]

	total := 0
	done2 := make([]bool, N)
	var dfs2 func(cur int)
	dfs2 = func(cur int) {
		for i := 0; i < len(G[cur]); i++ {
			next := G[cur][i]
			if next != white && !done2[next] {
				done2[next] = true
				total++
				dfs2(next)
			}
		}
	}
	done2[black] = true
	total++
	dfs2(black)
	bc, wc := total, N-total
	if bc > wc {
		fmt.Fprintln(wtr, "Fennec")
	} else {
		fmt.Fprintln(wtr, "Snuke")
	}
}

