func bfs(n int, s int, adj *[]map[int]struct{}) {
	depth := make([]int, n)
	prev := make([]int, n)
	for i := range prev {
		prev[i] = -1
	}
	queue := []int{s}
	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for v := range (*adj)[u] {
			if prev[v] != -1 {
				continue
			}
			prev[v] = u
			depth[v] = depth[u] + 1
			if v != n-1 {
				queue = append(queue, v)
				continue
			}
			x, y := u, v
			for depth[x] > depth[v]/2 {
				x, y = prev[x], x
			}
			delete((*adj)[x], y)
			delete((*adj)[y], x)
			return
		}
	}
}

func dfs(s int, prev int, adj []map[int]struct{}) int {
	cnt := 1
	for t := range adj[s] {
		if t == prev {
			continue
		}
		cnt += dfs(t, s, adj)
	}
	return cnt
}

