var sc = bufio.NewScanner(os.Stdin)

func Scanner() string {
	sc.Scan()
	return sc.Text()
}

func main() {
	buf := make([]byte, 0)
	sc.Buffer(buf, 1000000007)
	sc.Split(bufio.ScanWords)
	n, _ := strconv.Atoi(Scanner())
	tree := make([][]int, n)
	for i := 0; i < n-1; i++ {
		a, _ := strconv.Atoi(Scanner())
		b, _ := strconv.Atoi(Scanner())
		a--
		b--
		tree[a] = append(tree[a], b)
		tree[b] = append(tree[b], a)
	}
	fq := []int{0}
	fd := make([]int, n)
	for i := 1; i < n; i++ {
		fd[i] = -1
	}
	for {
		v := fq[0]
		fq = fq[1:]
		for _, j := range tree[v] {
			if fd[j] == -1 {
				fq = append(fq, j)
				fd[j] = fd[v] + 1
			}
		}
		if len(fq) == 0 {
			break
		}
	}
	sq := []int{n - 1}
	sd := make([]int, n)
	for i := 0; i < n-1; i++ {
		sd[i] = -1
	}
	for {
		v := sq[0]
		sq = sq[1:]
		for _, j := range tree[v] {
			if sd[j] == -1 {
				sq = append(sq, j)
				sd[j] = sd[v] + 1
			}
		}
		if len(sq) == 0 {
			break
		}
	}
	f, s := -1, -1
	p := int(1e9)
	for i := 1; i < n-1; i++ {
		if (fd[i] == sd[i] || sd[i]-1 == fd[i]) && fd[i] < p {
			f = i
			for _, j := range tree[i] {
				if sd[j] == sd[i]-1 {
					s = j
				}
			}
		}
	}
	fq = []int{0}
	fd[0] = 1
	for i := 1; i < n; i++ {
		fd[i] = -1
	}
	fc := 1
	for {
		v := fq[0]
		fq = fq[1:]
		for _, j := range tree[v] {
			if fd[j] == -1 && j != s {
				fq = append(fq, j)
				fd[j] = 1
				fc++
			}
		}
		if len(fq) == 0 {
			break
		}
	}
	sq = []int{n - 1}
	sd[n-1] = 1
	for i := 0; i < n-1; i++ {
		sd[i] = -1
	}
	sc := 1
	for {
		v := sq[0]
		sq = sq[1:]
		for _, j := range tree[v] {
			if sd[j] == -1 && j != f {
				sq = append(sq, j)
				sd[j] = 1
				sc++
			}
		}
		if len(sq) == 0 {
			break
		}
	}
	if fc > sc {
		fmt.Println("Fennec")
	} else {
		fmt.Println("Snuke")
	}
}

