	}
	for i := 0; i < n-1; i++ {
		tmp = NextIntsLine()
		a, b := tmp[0], tmp[1]
		edges[a][b] = true
		edges[b][a] = true
	}

	snukeHands := [100001]int{}
	fennecHands := [100001]int{}
	for i := 1; i <= n; i++ {
		snukeHands[i] = -1
		fennecHands[i] = -1
	}

	queue := []step{}
	queue = append(queue, step{nodeId: n, times: 0})
	for len(queue) > 0 {
		popped := queue[0]
		queue = queue[1:]
		nid, time := popped.nodeId, popped.times

		// マークする
		snukeHands[nid] = time
		// ノーマークのノードを追加
		for k, _ := range edges[nid] {
			if snukeHands[k] == -1 {
				queue = append(queue, step{nodeId: k, times: time + 1})
			}
		}
	}

	queue = []step{}
	queue = append(queue, step{nodeId: 1, times: 0})
	for len(queue) > 0 {
