		queue = queue[1:]
		nid, time := popped.nodeId, popped.times

		// マークする
		fennecHands[nid] = time
		// ノーマークのノードを追加
		for k, _ := range edges[nid] {
			if fennecHands[k] == -1 {
				queue = append(queue, step{nodeId: k, times: time + 1})
			}
		}
	}

	snukeCount, fennecCount := 0, 0
	for i := 1; i <= n; i++ {
		if fennecHands[i] <= snukeHands[i] {
			fennecCount++
		} else {
			snukeCount++
		}
	}

	if fennecCount > snukeCount {
		fmt.Println("Fennec")
	} else {
		fmt.Println("Snuke")
	}
}

