func main() {
  var n int = NextInt()
  tree = make([][]int,n)
  for i:=0;i<n-1;i++ {
    var a,b int = NextInts()
    a,b = a-1,b-1
    tree[a] = append(tree[a],b)
    tree[b] = append(tree[b],a)
  }
  var df []int = make([]int,n)
  var ds []int = make([]int,n)
  dfs(0,-1,df)
  dfs(n-1,-1,ds)
  var m int
  for i:=0;i<n;i++ {
    if df[i] <= ds[i] { m++ }
  }
  if m > n-m {
    fmt.Println("Fennec")
  } else {
    fmt.Println("Snuke")
  }
}

func dfs(v,p int,d []int) {
  if p != -1 { d[v] = d[p]+1 }
  for _,e := range tree[v] {
    if e == p { continue }
    dfs(e,v,d)
  }
}

