const MOD = int(1e+9) + 7
const INF = 1 << 60

func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	N := sc.nextInt()
	G := make([][]int, N)
	for i := 0; i < N-1; i++ {
		a, b := sc.nextInt()-1, sc.nextInt()-1
		G[a] = append(G[a], b)
		G[b] = append(G[b], a)
	}
	q := &Queue{}
	D := make([]int, N)
	for i := 0; i < N; i++ {
		D[i] = -1
	}
	R := make([][]int, N)
	var root []int
	bfs := func(cur int) {
		for i := 0; i < len(G[cur]); i++ {
			next := G[cur][i]
			if next == N-1 {
				root = append(R[cur], next)
				continue
			}
			if D[next] == -1 {
				D[next] = D[cur] + 1
				R[next] = append(R[cur], next)
				q.push(next)
			}
		}
	}
	D[0] = 0
	R[0] = append(R[0], 0)
	q.push(0)
	for !q.isEmpty() {
		bfs(q.pop())
	}
	//fmt.Fprintln(wtr, "root", root)
	l := len(root)
	black := root[ceil(l, 2)-1]
	white := root[ceil(l, 2)]
	blackCnt := 0
	done := make([]bool, N)
	var dfs func(cur int)
	dfs = func(cur int) {
		for i := 0; i < len(G[cur]); i++ {
			next := G[cur][i]
			if next == white {
				continue
			}
			if !done[next] {
				blackCnt++
				done[next] = true
				dfs(next)
			}
		}
	}
	blackCnt++
	done[black] = true
	dfs(black)
	whiteCnt := N - blackCnt
	//fmt.Fprintln(wtr, "count", blackCnt, whiteCnt)

	if blackCnt > whiteCnt {
		fmt.Fprintln(wtr, "Fennec")
	} else {
		fmt.Fprintln(wtr, "Snuke")
	}
}

type Queue struct {
	arr []int
}

func (q *Queue) push(v int) {
	q.arr = append(q.arr, v)
}

func (q *Queue) pop() int {
	res := q.arr[0]
	q.arr = q.arr[1:]
	return res
}

func (q *Queue) isEmpty() bool {
	return len(q.arr) == 0
}

