import "fmt"

func main() {
	var n int
	fmt.Scan(&n)

	g := make([][]int, n)
	var a, b int
	for i := 0; i < n-1; i++ {
		fmt.Scan(&a, &b)
		a--
		b--
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}

	var dfs func(v, p, x int) int
	dfs = func(v, p, x int) int {
		if v == x {
			return 0
		}
		cnt := 1
		for _, u := range g[v] {
			if u != p {
				cnt += dfs(u, v, x)
			}
		}
		return cnt
	}

	ds := make([]int, n)
	que := make([]int, 0)
	que = append(que, 0)
	ds[0] = 1
	for len(que) > 0 {
		v := que[0]
		que = que[1:]
		for _, u := range g[v] {
			if ds[u] == 0 {
				ds[u] = ds[v] + 1
				que = append(que, u)
			}
		}
	}
	d := ds[n-1]

	c1 := dfs(0, -1, n-1) - (d / 2)
	c2 := dfs(n-1, -1, 0) - ((d + 1) / 2)

	if c1 > c2 {
		fmt.Println("Fennec")
