func dist(start int, g [][]int) []int {
	ds := make([]int, len(g))

	var dfs func(v int)
	dfs = func(v int) {
		for _, u := range g[v] {
			if ds[u] == 0 {
				ds[u] = ds[v] + 1
				dfs(u)
			}
		}
	}

	ds[start] = 1
	dfs(start)

	return ds
}

