		f, t := getInt()-1, getInt()-1
		node[f].to = append(node[f].to, t)
		node[t].to = append(node[t].to, f)
		p[i] = pair{f, t}
	}
	out(N, node)
	out(dfs(0, N-1, -1, node))
	out(route, route[len(route)/2])

	fe := route[1]
	su := route[len(route)-2]

	u := newUnionFind(N)
	for i := 0; i < N-1; i++ {
		if p[i].f == fe || p[i].f == su ||
			p[i].t == fe || p[i].t == su {
			continue
		}
		u.unite(p[i].f, p[i].t)
	}

	ff := u.root(0)
	fcnt := 0
	scnt := 0
	for i := 1; i < N-1; i++ {
		out("i=", i)
		if u.root(i) == ff {
			fcnt++
		} else {
			scnt++
		}
