	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	N := sc.nextInt()
	G := make([][]int, N)
	for i := 0; i < N-1; i++ {
		a, b := sc.nextInt()-1, sc.nextInt()-1
		G[a] = append(G[a], b)
		G[b] = append(G[b], a)
	}
	q := &Queue{}
	D := make([]int, N)
	for i := 0; i < N; i++ {
		D[i] = -1
	}
	R := make([][]int, N)
	bfs := func(cur int) bool {
		for i := 0; i < len(G[cur]); i++ {
			next := G[cur][i]
			if D[next] == -1 {
				D[next] = D[cur] + 1
				R[next] = append(R[cur], next)
				if next == N-1 {
					return true
				}
				q.push(next)
			}
		}
		return false
	}
	D[0] = 0
	R[0] = append(R[0], 0)
	q.push(0)
	for !q.isEmpty() {
		if bfs(q.pop()) {
			break
		}
	}
	root := R[N-1]
	//fmt.Fprintln(wtr, "root", R)
	l := len(root)
	black := root[ceil(l, 2)-1]
	white := root[ceil(l, 2)]
	blackCnt := 0
	done := make([]bool, N)
	var dfs func(cur int)
	dfs = func(cur int) {
		for i := 0; i < len(G[cur]); i++ {
			next := G[cur][i]
			if next == white {
				continue
			}
			if !done[next] {
				blackCnt++
				done[next] = true
				dfs(next)
			}
		}
	}
	blackCnt++
	done[black] = true
	dfs(black)
	whiteCnt := N - blackCnt
	//fmt.Fprintln(wtr, "count", blackCnt, whiteCnt)

	if blackCnt > whiteCnt {
		fmt.Fprintln(wtr, "Fennec")
	} else {
		fmt.Fprintln(wtr, "Snuke")
	}
}

