// readIntSlice(n int) []int
// readLengthAndSlice() []int

func main() {
	defer stdout.Flush()

	N := readInt()
	g := make([][]int, N+1)
	for i := 0; i < N-1; i++ {
		a := readInt()
		b := readInt()
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}

	q := make([]int, 0)
	push := func(x int) {
		q = append(q, x)
	}
	pop := func() int {
		res := q[0]
		q = q[1:]
		return res
	}
	cost := make([]int, N+1)
	for i := range cost {
		cost[i] = math.MaxInt32
	}
	cost[1] = 0
	push(1)
	for len(q) != 0 {
		v := pop()
		for _, u := range g[v] {
			if cost[v]+1 < cost[u] {
				cost[u] = cost[v] + 1
				push(u)
			}
		}
	}

	prev := N
	v := N
	for cost[v] > cost[N]/2 {
		for _, u := range g[v] {
			if cost[u] < cost[v] {
				prev = v
				v = u
				break
			}
		}
	}
	ves := make([]int, 0)
	for _, u := range g[v] {
		if u == prev {
			continue
		}
		ves = append(ves, u)
	}
	g[v] = ves

	var bnodes int
	visited := make([]bool, N+1)
	push(1)
	for len(q) != 0 {
		v := pop()
		if visited[v] {
			continue
		}
		visited[v] = true
		bnodes++
		for _, u := range g[v] {
			push(u)
		}
	}

	if N-bnodes < bnodes {
		println("Fennec")
	} else {
		println("Snuke")
	}
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

var sc = bufio.NewScanner(os.Stdin)

func Scanner() string {
	sc.Scan()
	return sc.Text()
}

func main() {
	buf := make([]byte, 0)
	sc.Buffer(buf, 1000000007)
	sc.Split(bufio.ScanWords)
	n, _ := strconv.Atoi(Scanner())
	tree := make([][]int, n)
	for i := 0; i < n-1; i++ {
		a, _ := strconv.Atoi(Scanner())
		b, _ := strconv.Atoi(Scanner())
		a--
		b--
		tree[a] = append(tree[a], b)
		tree[b] = append(tree[b], a)
	}
	fq := []int{0}
	fd := make([]int, n)
	for i := 1; i < n; i++ {
		fd[i] = -1
	}
	for {
		v := fq[0]
		fq = fq[1:]
		for _, j := range tree[v] {
			if fd[j] == -1 {
				fq = append(fq, j)
				fd[j] = fd[v] + 1
			}
		}
		if len(fq) == 0 {
			break
		}
	}
	sq := []int{n - 1}
	sd := make([]int, n)
	for i := 0; i < n-1; i++ {
		sd[i] = -1
	}
	for {
		v := sq[0]
		sq = sq[1:]
		for _, j := range tree[v] {
			if sd[j] == -1 {
				sq = append(sq, j)
				sd[j] = sd[v] + 1
			}
		}
		if len(sq) == 0 {
			break
		}
	}
	f, s := -1, -1
	for i := 0; i < n; i++ {
		if fd[i] == sd[i] || sd[i]-1 == fd[i] {
			f = i
			for _, j := range tree[i] {
				if sd[j] == sd[i]-1 {
					s = j
				}
			}
			break
		}
	}
	fq = []int{0}
	fd[0] = 1
	for i := 1; i < n; i++ {
		fd[i] = -1
	}
	fc := 1
	for {
		v := fq[0]
		fq = fq[1:]
		for _, j := range tree[v] {
			if fd[j] == -1 && j != s {
				fq = append(fq, j)
				fd[j] = 1
				fc++
			}
		}
		if len(fq) == 0 {
			break
		}
	}
	sq = []int{n - 1}
	sd[n-1] = 1
	for i := 0; i < n-1; i++ {
		sd[i] = -1
	}
	sc := 1
	for {
		v := sq[0]
		sq = sq[1:]
		for _, j := range tree[v] {
			if sd[j] == -1 && j != f {
				sq = append(sq, j)
				sd[j] = 1
				sc++
			}
		}
		if len(sq) == 0 {
			break
		}
	}
	if fc > sc {
		fmt.Println("Fennec")
	} else {
		fmt.Println("Snuke")
	}
}

let dfs g n =
  let que = Queue.create () in
  Queue.push 1 que;
  let reached_p = Array.make (n + 1) false in
  reached_p.(1) <- true;
  let rec doit depth n_p =
    if n_p || Queue.is_empty que then depth
    else begin
      let x = Queue.pop que in
      let n_p = ref false in
      List.iter (fun e ->
        if not reached_p.(e) then begin
          reached_p.(e) <- true;
          Queue.push e que;
          if e = n then n_p := true;
        end)
        g.(x);
      doit (depth + 1) !n_p
    end in
  doit 0 false

let () =
  let n = Scanf.scanf "%d " (fun i -> i) in
  let g = Array.make (n + 1) [] in
  for _ = 1 to n - 1 do
    let (x, y) = Scanf.scanf "%d %d " (fun x y -> (x, y)) in
    g.(x) <- y :: g.(x);
    g.(y) <- x :: g.(y);
  done;
  let x = dfs g n in
  print_endline (if x = 1 then "Snuke" else "Fennec")

let () =
  Scanf.scanf "%d" @@ fun n ->
  let g = Array.init n (fun _ -> []) in
  for _ = 1 to n-1 do
    Scanf.scanf " %d %d" @@ fun a b ->
    g.(a-1) <- b-1 :: g.(a-1);
    g.(b-1) <- a-1 :: g.(b-1)
  done;

  let dists_from s =
    let res = Array.make n n in
    let rec dfs x d =
      res.(x) <- d;
      g.(x) |> List.iter @@ fun y ->
        if d+1 < res.(y) then dfs y (d+1)
    in dfs s 0;
    res
  in

  let f = dists_from 0 in
  let s = dists_from (n-1) in
  let rec loop i v =
    if i >= n then (if v > n/2 then "Fennec" else "Snuke")
    else loop (i+1) (if f.(i) <= s.(i) then v+1 else v)
  in loop 0 0 |> print_endline

