void main()
{
    long N = lread();
    auto G = new long[][](N);
    foreach (i; 0 .. N - 1)
    {
        long a, b;
        scan(a, b);
        a--, b--;
        G[a] ~= b;
        G[b] ~= a;
    }
    auto d0 = new long[](N);
    d0[] = -1;
    auto d1 = new long[](N);
    d1[] = -1;
    alias Tup = Tuple!(long, long);
