        PQ.insert(Tup(0, 0));
        while (!PQ.empty)
        {
            auto t = PQ.front;
            PQ.removeFront();
            if (d0[t[1]] != -1)
                continue;
            d0[t[1]] = t[0];
            foreach (v; G[t[1]])
                PQ.insert(Tup(t[0] + 1, v));
        }
    }
    {
        PQ.insert(Tup(0, N - 1));
        while (!PQ.empty)
        {
            auto t = PQ.front;
            PQ.removeFront();
            if (d1[t[1]] != -1)
