struct Factor
{
    long n;
    long c;
}

//素因数分解
Factor[] factors(long n) pure
{
    Factor[] res;
    for (long i = 2; i ^^ 2 <= n; i++)
    {
        if (n % i != 0)
            continue;

        long c;
        while (n % i == 0)
        {
            n = n / i;
            c++;
        }
        res ~= Factor(i, c);
    }
    if (n != 1)
        res ~= Factor(n, 1);

    return res;
}
//約数をすべて列挙
long[] divisors(long n) pure
{
    long[] list;
    void func(Factor[] fs, long n)
    {
        if(fs.empty){
            list ~= n;
            return;
        }

        foreach(c; 0..fs[0].c+1)
        {
            func(fs[1..$], n * (fs[0].n ^^ c));
        }
    }

    func(factors(n), 1);
    sort(list);
    return list;
}
//nまでの素数のリスト
long[] primes(long n) pure
{
    if(n<2)return [];

    auto table = new long[cast(size_t)n+1];

    long[] res;
    for(size_t i = 2;i<=n;i++)
    {
        if(table[i]==-1) continue;
        for(size_t a = i;a<table.length;a+=i)
        {
            table[a] = -1;
        }
        res ~= i;
    }
    return res;
}
//素数判定
bool isPrime(long n) pure
{
    if (n <= 1)
        return false;
    if (n == 2)
        return true;
    if (n % 2 == 0)
        return false;
    for (long i = 3; i ^^ 2 <= n; i += 2)
        if (n % i == 0)
            return false;
    return true;
}

import std.algorithm, std.conv, std.range, std.stdio, std.string;
import std.container; // SList, DList, BinaryHeap

void main()
{
  auto n = readln.chomp.to!size_t;

  auto edge = new size_t[][](n);
  auto parent = new size_t[](n);

  foreach (_; 0..n-1) {
    auto rd = readln.splitter;
    auto a = rd.front.to!size_t-1; rd.popFront();
    auto b = rd.front.to!size_t-1;
    edge[a] ~= b;
    edge[b] ~= a;
  }

  parent[0] = n;
  auto q = DList!size_t([0]), st = SList!size_t();
  while (!q.empty) {
    auto u = q.front; q.removeFront();
    st.insertFront(u);
    foreach (v; edge[u]) {
      if (parent[u] != v) {
        parent[v] = u;
        q.insertBack(v);
      }
    }
  }

  auto rt = new bool[](n), rtn = [n-1], c = n-1;
  while (c != 0) {
    rt[c] = true;
    c = parent[c];
    rtn ~= c;
  }
  rt[0] = true;
  auto nrtn = rtn.length;

  auto nodes = new int[](n);
  while (!st.empty) {
    auto u = st.front; st.removeFront();
    if (nodes[u] == 0) nodes[u] = 1;
    if (!rt[u]) nodes[parent[u]] += nodes[u];
  }

  auto n1 = rt[0..nrtn/2].sum, n2 = rt[nrtn/2..$].sum;
  if (n1 > n2)
    writeln("Snuke");
  else if (n1 < n2)
    writeln("Fennec");
  else if (nrtn % 2 == 0)
    writeln("Snuke");
  else
    writeln("Fennec");
}

