struct Data{
    long[] list;
}
void main()
{
    auto N = scanElem;

    Data[] list;
    list.length = N+1;

    foreach(i; 0..N-1)
    {
        auto a = scanElem;
        auto b = scanElem;
        list[a].list ~= b;
        list[b].list ~= a;
    }
    auto path = calcPath(list, 1, N).reverse;
    auto siro = path[(path.length-1)/2];
    auto kc = kuroCount(list, N, siro);

    writeln(N-kc>kc?"Fennec" : "Snuke");
}

bool[] kuroPassed;
long kuroCount(Data[] list, long current, long siro){
    kuroPassed.length = list.length;

    if(current==siro) return 0;
    if(kuroPassed[current]) return 0;
    kuroPassed[current] = true;

    long count;
    foreach(node; list[current].list){
        count += kuroCount(list, node, siro);
    }
    return count + 1;
}

bool[] passed;
long[] calcPath(Data[] list, long current, long target){
    passed.length = list.length;

    if(current==target) return [target];
    if(passed[current]) return [];
    passed[current] = true;

    foreach(node; list[current].list){
        auto path = calcPath(list, node, target);
        if(!path.empty){
            return path ~ current;
        }
    }
    return [];
}

long gcd(long a, long b)
{
  if(b == 0) return a;
  return gcd(b, a % b);
}


class UnionFind{
    UnionFind parent = null;

    void merge(UnionFind a)
    {
        if(same(a)) return;
        a.root.parent = this.root;
    }
    UnionFind root()
    {
        if(parent is null)return this;
        return parent = parent.root;
    }
    bool same(UnionFind a)
    {
        return this.root == a.root;
    }
}

