auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto n = input.front.to!( long );
	auto abs = new long[ 2 ][ n - 1 ];
	foreach( ref ab; abs )
	{
		input.popFront;
		ab = input.front.split.to!( long[] );
		ab[] -= 1;
	}
	return tuple( n, abs );
}

auto solve( long n, long[ 2 ][] abs )
{
	const F = 1L;
	const S = -1L;

	auto cs = new long[ n ];
	cs[ 0     ] = F;
	cs[ $ - 1 ] = S;

	auto nss = new long[][ n ];
	foreach( ab; abs )
	{
		nss[ ab[ 0 ] ] ~= ab[ 1 ];
		nss[ ab[ 1 ] ] ~= ab[ 0 ];
	}

	// お互い最善手で塗った結果を計算
	auto fq = make!DList( 0L,    -1L );
	auto sq = make!DList( n - 1, -1L );
	while( !fq.empty || !sq.empty )
	{
		// フェネックのターン
		solve2( cs, fq, nss, F );

		// すぬけくんのターン
		solve2( cs, sq, nss, S );
	}

	// 塗ったマス目 = 自分のターン数 なので、マス目の多いほうが勝ち（同数だったら後手の勝ち）
	auto fc = 0L;
	auto sc = 0L;
	foreach( c; cs )
	{
		fc += ( c == F );
		sc += ( c == S );
	}
	return ( fc <= sc ) ? "Snuke" : "Fennec";
}

void solve2( ref long[] cs, ref DList!( long ) queue, long[][] nss, long c )
{
	while( !queue.empty )
	{
		auto f = queue.front;
		queue.removeFront();

		if( f == -1 )
		{
			if( !queue.empty ) queue.insertBack( -1 );
			break;
		}

		foreach( t; nss[ f ] )
		{
			if( cs[ t ] != 0 ) continue;
			cs[ t ] = c;
			queue.insertBack( t );
		}
	}
}

import std.algorithm, std.conv, std.range, std.stdio, std.string;
import std.container; // SList, DList, BinaryHeap

void main()
{
  auto n = readln.chomp.to!size_t;

  auto edge = new size_t[][](n);
  auto parent = new size_t[](n);

  foreach (_; 0..n-1) {
    auto rd = readln.splitter;
    auto a = rd.front.to!size_t-1; rd.popFront();
    auto b = rd.front.to!size_t-1;
    edge[a] ~= b;
    edge[b] ~= a;
  }

  parent[0] = n;
  auto q = DList!size_t([0]), st = SList!size_t();
  while (!q.empty) {
    auto u = q.front; q.removeFront();
    st.insertFront(u);
    foreach (v; edge[u]) {
      if (parent[u] != v) {
        parent[v] = u;
        q.insertBack(v);
      }
    }
  }

  auto rt = new bool[](n), rtn = [n-1], c = n-1;
  while (c != 0) {
    rt[c] = true;
    c = parent[c];
    rtn ~= c;
  }
  rt[0] = true;
  auto nrtn = rtn.length;

  auto nodes = new int[](n);
  while (!st.empty) {
    auto u = st.front; st.removeFront();
    ++nodes[u];
    if (!rt[u]) nodes[parent[u]] += nodes[u];
  }

  auto n1 = rt[0..nrtn/2].sum, n2 = rt[nrtn/2..$].sum;
  if (n1 > n2)
    writeln("Snuke");
  else if (n1 < n2)
    writeln("Fennec");
  else if (nrtn % 2 == 0)
    writeln("Snuke");
  else
    writeln("Fennec");
}

import std.algorithm, std.container, std.conv, std.math, std.range, std.typecons, std.stdio, std.string;

auto rdsp(){return readln.splitter;}
void pick(R,T)(ref R r,ref T t){t=r.front.to!T;r.popFront;}
void readV(T...)(ref T t){auto r=rdsp;foreach(ref v;t)pick(r,v);}
void readC(T...)(size_t n,ref T t){foreach(ref v;t)v=new typeof(v)(n);foreach(i;0..n){auto r=rdsp;foreach(ref v;t)pick(r,v[i]);}}

void main()
{
  int n; readV(n);
  int[] a, b; readC(n-1, a, b); a[] -= 1; b[] -= 1;

  auto g = Graph!int(n);
  foreach (i; 0..n-1) g.addEdgeB(a[i], b[i]);
  auto t = g.makeTree.rootify(0);

  auto e = n-1, r = [n-1];
  while (e != 0) {
    e = t.parent[e];
    r ~= e;
  }
  r.reverse();
  auto onroute = new bool[](n);
  foreach (ri; r) onroute[ri] = true;

  auto uf = UnionFind!int(n);
  foreach (i; 0..n-1)
    if (!onroute[a[i]] || !onroute[b[i]])
      uf.unite(a[i], b[i]);

  auto nr = r.length.to!int, t1 = 0, t2 = 0;
  foreach (i; 0..nr/2) {
    t1 += uf.countNodesOf(r[i])-1;
    t2 += uf.countNodesOf(r[$-i-1])-1;
  }
  if (nr%2 == 1) t1 += uf.countNodesOf(r[nr/2])-1;

  writeln(t1 > t2 || t1 == t2 && nr%2 == 1 ? "Fennec" : "Snuke");
}

struct Graph(N = int)
{
  alias Node = N;
  Node n;
  Node[][] g;
  alias g this;
  this(Node n) { this.n = n; g = new Node[][](n); }
  void addEdge(Node u, Node v) { g[u] ~= v; }
  void addEdgeB(Node u, Node v) { g[u] ~= v; g[v] ~= u; }
}

struct Tree(Graph)
{
  import std.algorithm, std.container;
  alias Node = Graph.Node;
  Graph g;
  alias g this;
  Node root;
  Node[] parent;
  int[] size, depth;

  this(ref Graph g) { this.g = g; this.n = g.n; }

  ref auto rootify(Node r)
  {
    this.root = r;

    parent = new Node[](g.n);
    depth = new int[](g.n);
    depth[] = -1;

    struct UP { Node u, p; }
    auto st1 = SList!UP(UP(r, r));
    auto st2 = SList!UP();
    while (!st1.empty) {
      auto up = st1.front, u = up.u, p = up.p; st1.removeFront();

      parent[u] = p;
      depth[u] = depth[p] + 1;

      foreach (v; g[u])
        if (v != p) {
          st1.insertFront(UP(v, u));
          st2.insertFront(UP(v, u));
        }
    }

    size = new int[](g.n);
    size[] = 1;

    while (!st2.empty) {
      auto up = st2.front, u = up.u, p = up.p; st2.removeFront();
      size[p] += size[u];
    }

    return this;
  }

  auto children(Node u) { return g[u].filter!(v => v != parent[u]); }
}
ref auto makeTree(Graph)(ref Graph g) { return Tree!Graph(g); }

struct UnionFind(T)
{
  import std.algorithm, std.range;

  T[] p; // parent
  const T s; // sentinel
  const T n;
  T countForests; // number of forests
  T[] countNodes; // number of nodes in forests

  this(T n)
  {
    this.n = n;
    s = n;
    p = new T[](n);
    p[] = s;
    countForests = n;
    countNodes = new T[](n);
    countNodes[] = 1;
  }

  T opIndex(T i)
  {
    if (p[i] == s) {
      return i;
    } else {
      p[i] = this[p[i]];
      return p[i];
    }
  }

  bool unite(T i, T j)
  {
    auto pi = this[i], pj = this[j];
    if (pi != pj) {
      p[pj] = pi;
      --countForests;
      countNodes[pi] += countNodes[pj];
      return true;
    } else {
      return false;
    }
  }

  auto countNodesOf(T i) { return countNodes[this[i]]; }
  bool isSame(T i, T j) { return this[i] == this[j]; }

  auto groups()
  {
    auto g = new T[][](n);
    foreach (i; 0..n) g[this[i]] ~= i;
    return g.filter!(l => !l.empty);
  }
}

void main()
{
    long n = rdElem;

    long[][] tree = new long[][](n);
    foreach (i; 0 .. n-1)
    {
        long a, b;
        rdVals(a, b);
        --a, --b;
        tree[a] ~= b, tree[b] ~= a;
    }

    long[] BFS(long start)
    {
        long[] result = new long[n];
        result[] = -1;
        result[start] = 0;
        long[] que;
        que ~= start;
        while (!que.empty)
        {
            long f = que[0];
            que.popFront;
            foreach (x; tree[f])
            {
                if (result[x] != -1) continue;
                result[x] = result[f] + 1;
                que ~= x;
            }
        }
        return result;
    }

    long[] dist1 = BFS(0), dist2 = BFS(n-1);

    long cnt;
    foreach (x, y; zip(dist1, dist2))
    {
        if (x <= y) ++cnt;
        else --cnt;
    }

    writeln(cnt > 0 ? "Fennec" : "Snuke");
}

