		v[a] ~= b;
		v[b] ~= a;
		v2[a] ~= b;
		v2[b] ~= a;
	}
	auto score = new long[](N+1);
	foreach (i, e; v)
	{
		if (e.length != 1) continue;
		long pos = i, lastPos = -1;
		long s;
		while (v[pos].length <= 2 && pos != 1 && pos != N)
		{
			auto newPos = v[pos][0] == lastPos ? v[pos][1] : v[pos][0];
			lastPos     = pos;
			pos         = newPos;
			++s;
		}
		score[pos] += s;
		v2[pos] = remove!(a => a == lastPos)(v2[pos]);
	}

	auto used = new long[](N+1);
	used[0] = used[N] = 1;
	long pos1 = 1, pos2 = N;
	long lastPos1 = -1, lastPos2 = -1;
	long s1 = score[1], s2 = score[N];
	while (true)
	{
		{
			auto newPos = v2[pos1][0] == lastPos1 ? v2[pos1][1] : v2[pos1][0];
			if (used[newPos] == 1) break;
			lastPos1    = pos1;
			pos1        = newPos;
			s1         += score[pos1];
			used[pos1]  = 1;
		}
		{
			auto newPos = v2[pos2][0] == lastPos2 ? v2[pos2][1] : v2[pos2][0];
			if (used[newPos] == 1) 
			{
				--s2;
				break;
			}
			lastPos2    = pos2;
			pos2        = newPos;
			s2         += score[pos2];
			used[pos2]  = 1;
		}
	}

	writeln(s1 > s2 ? "Fennec" : "Snuke");
	stdout.flush();
}

