import copy

def now_land(land, op):
    tmp = []
    for i in range(len(land)):
        if land[i] == op:
            tmp.append(i)
    return tmp

def nxt_land(route, now):
    tmp = []
    for i in range(len(route)):
        for j in range(len(now)):
            if route[i][0] == now[j] + 1:
                tmp.append(route[i][1])
    return tmp

def chg(land, nxt, op):
    if land[nxt - 1] == -1:
        land[nxt - 1] = op
        return 1, land
    else:
        return 0, land


def wide_search(q, route, op):
    tmp = []
    ct = 0
    while len(q) != 0:
        land = q.pop(0)
        now = now_land(land, op)
        nxt = nxt_land(route, now)
        for i in nxt:
            t_land = copy.deepcopy(land)
            rt, t_land = chg(t_land, i, op)
            if rt == 1:
                tmp.append(t_land)
                ct += 1
    return ct, tmp

def MAIN(land, route):
    q = [copy.deepcopy(land)]
    while True:
        rt, q = wide_search(q, route, 0)
        if rt == 0:
            print "Snuke"
            break
        rt, q = wide_search(q, route, 1)
        if rt == 0:
            print "Fennic"
            break

