def dijkstra(start, nodes, N):
    fixed = {}
    cost = [inf] * (N + 1)
    cost[start] = 0
    q = queue.PriorityQueue()
    q.put((0, start))
    while q.empty() == False:
        w, x = q.get()
        if cost[x] < w: continue
        for y in nodes[x]:
            if cost[x] + paths[x][y] < cost[y]:
                cost[y] = cost[x] + paths[x][y]
                q.put((cost[y], y))
    return cost

