def distance(edge,v):
    n = len(edge)
    visited = [-1]*n
    dist = [0]*n
    que = deque()
    for i in edge[v]:
        que.append([i,1])
        dist[i]=1
        visited[i]=1
    visited[n-1]=1
    visited[0]=1
    while que:
        vertex_=que.popleft()
        d = vertex_[1]
        vertex = vertex_[0]
        visited[vertex]=1

        for next_v in edge[vertex]:
            if visited[next_v]!=-1:continue
            if(next_v==n-1 or next_v==0):
                continue
            dist[next_v]=dist[vertex]+1
            que.append([next_v,dist[next_v]])
    return dist

