                if nv==N-1:
                    break
    d=cost[N-1]
    v=N-1
    for i in range(d+1):
        if i==(d-1)//2:
            sv=v
        elif i==(d+1)//2:
            fv=v
            break
        for nv in edge[v]:
            if cost[nv]==cost[v]-1:
                v=nv
                break

    stack=[sv]
    used=[False]*N
    used[fv]=True
    c=0
    while stack:
        v=stack.pop()
        used[v]=True
        c+=1
        for nv in edge[v]:
            if not used[nv]:
                stack.append(nv)
    if c>=N-c:
        print('Snuke')
    else:
        print('Fennec')


