class Node:
    def __init__(self, id):
        self.id = id
        self._connection = set()

    def add_connection(self, node):
        self._connection.add(node)

    def get_connection(self):
        return self._connection


def get_ln_inputs():
    return input().split()


def get_ln_int_inputs():
    return list(map(int, get_ln_inputs()))


def find_path_in_tree(current_path_list, target_node):
    tip = current_path_list[-1]
    search_targets = tip.get_connection()

    if len(search_targets) == 0:
        return current_path_list, False

    for node in search_targets:
        if node in current_path_list:
            continue

        current_path_list.append(node)
        if node == target_node:
            return current_path_list, True

        result, is_found = find_path_in_tree(current_path_list, target_node)
        if is_found:
            return result, True
        current_path_list.pop()

    return current_path_list, False        


def populate_nodes(own_node, opponent_node):
    new_own_node = set(own_node)
    for node in own_node:
        targets = node.get_connection()
        for target in targets:
            if target in own_node or target in opponent_node:
                continue
            new_own_node.add(target)
            populate_nodes(new_own_node, opponent_node)
    return new_own_node


