            for i in g.neighbor[h]:
                if node[i]==0:
                    t.append(i)
                    node[i] = 1
        head = t

        t = []
        while len(tail)>0:
            h = tail.pop()
            for i in g.neighbor[h]:
                if node[i]==0:
                    t.append(i)
                    node[i] = -1
        tail = t

    ans = sum(node)
