class Unionfind():
    def __init__(self,n):
        self.n=n
        self.parents=[-1]*n
        self.ranks=[0]*n

    def find(self,x):
        if self.parents[x]<0:
            return x
        else:
            self.parents[x]=self.find(self.parents[x])
            return self.parents[x]

    def union(self,x,y):
        x=self.find(x)
        y=self.find(y)
        if x==y:
            return 
        if self.ranks[x]<self.ranks[y]:
            x,y=y,x
        self.parents[x]+=self.parents[y]
        self.parents[y]=x
        if self.ranks[x]==self.ranks[y]:
            self.ranks[x]+=1

    def size(self,x):
        return -self.parents[self.find(x)]

    def issametree(self,x,y):
        return self.find(x)==self.find(y)

    def showroots(self):
        return [x for x in range(self.n) if self.parents[x]<0]

