def get_ln_int_inputs():
    return list(map(int, get_ln_inputs()))


def find_path_in_tree(begin_node, target_node):
    visited_nodes = {begin_node}
    tip = begin_node

    path = [begin_node]
    level_search_cache = [tip.get_connection()]
    while True:
        search_target = level_search_cache[-1]

        if target_node in search_target:
            path.append(target_node)
            return path

        if len(search_target) == 0:
            if len(path) == 1:
                raise Exception("Target node unreacheable.")
            tip = path[-2]
            path.pop()
            level_search_cache.pop()
            continue

        next_node = search_target.pop()
        tip = next_node
        visited_nodes.add(next_node)
        path.append(tip)
        level_search_cache.append(tip.get_connection() - visited_nodes)


def populate_nodes(own_node, opponent_node):
    new_own_node = set(own_node)
    for node in own_node:
        targets = node.get_connection()
        for target in targets:
            if target in own_node or target in opponent_node:
                continue
            new_own_node.add(target)
            populate_nodes(new_own_node, opponent_node)
    return new_own_node


def main():
    N = get_ln_int_inputs()[0]
    edges = []
    for _ in range(N - 1):
        edges.append(get_ln_int_inputs())

    nodes = [Node(i) for i in range(N)]
    for edge in edges:
        e1, e2 = edge
        nodes[e1 - 1].add_connection(nodes[e2 - 1])
        nodes[e2 - 1].add_connection(nodes[e1 - 1])

    path_from_f_to_s = find_path_in_tree(nodes[0], nodes[-1])

    fennec_path = {nodes[0]}
    snuke_path = {nodes[N - 1]}

    for _ in range(len(path_from_f_to_s) // 2):
        snuke_path.add(path_from_f_to_s.pop())
    for node in path_from_f_to_s:
        fennec_path.add(node)

    fennec_nodes = populate_nodes(fennec_path, snuke_path)

    if len(fennec_nodes) > N - len(fennec_nodes):
        print("Fennec")
    else:
        print("Snuke")


main()

