use std::io::stdin;
use std::collections::VecDeque;

fn main() {
    let mut st = String::new();
    stdin().read_line(&mut st).unwrap();
    let n:usize = st.trim().parse().unwrap();
    let mut tree:Vec<Vec<usize>> = Vec::with_capacity(n);
    for _i in 0..n {
        tree.push([].to_vec());
    };

    for _i in 0..(n-1) {
        let mut st = String::new();
        stdin().read_line(&mut st).unwrap();
        let (a, b) = {
            let ab:Vec<usize> = st.trim().split(" ").map(|x| x.parse::<usize>().unwrap()).collect();
            (ab[0]-1, ab[1]-1)
        };
        tree[a].push(b);
        tree[b].push(a);
    };

    let mut s_queue:VecDeque<usize> = VecDeque::with_capacity(100002);
    let mut f_queue:VecDeque<usize> = VecDeque::with_capacity(100002);
    s_queue.push_back(n-1);
    f_queue.push_back(0);

    let mut visit:[i64;100002] = [-1; 100002];
    visit[0] = 0;
    visit[n-1] = 0;
    let mut s:i64 = 1;
    let mut f:i64 = 1;

    while s_queue.len() != 0 && f_queue.len() != 0 {
        if f_queue.len() != 0 {
            let p:usize = f_queue.pop_front().unwrap();
            for i in &tree[p] {
                let num = *i as usize;
                if visit[num] < 0 {
                    visit[num] = 0;
                    f += 1;
                    f_queue.push_back(num);
                };
            };
        };
        if s_queue.len() != 0 {
            let p:usize = s_queue.pop_front().unwrap();
            for i in &tree[p] {
                let num = *i as usize;
                if visit[num] < 0 {
                    visit[num] = 0;
                    s += 1;
                    s_queue.push_back(num);
                };
            };
        };
    };
    if f > s {
        println!("Fennec");
    } else {
        println!("Snuke");
    };
}

use std::collections::BinaryHeap;

macro_rules! scan {
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($t:ty;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };

    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
}

fn wfs(graph: &[Vec<usize>], root: usize, dists: &mut [i64]) {
    let mut q = BinaryHeap::new();

    q.push((0i64, root));
    while let Some((d, r)) = q.pop() {
        if dists[r] != -1 {
            continue;
        }

        dists[r] = d;

        for &b in graph[r].iter() {
            q.push((d + 1, b))
        }
    }
}

fn main() {
    let n = scan!(usize);

    let mut graph = vec![vec![]; n + 1];
    for _ in 0..n - 1 {
        let (a, b) = scan!(usize, usize);
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut dists_f = vec![-1; n + 1];
    wfs(&graph, 1, &mut dists_f);
    let mut dists_s = vec![-1; n + 1];
    wfs(&graph, n, &mut dists_s);

    let (mut s, mut f) = (0, 0);
    for (d0, d1) in dists_f.iter().zip(dists_s.iter()).skip(1) {
        if d1 <= d0 {
            f += 1
        } else {
            s += 1
        }
    }

    println!("{}", if s > f { "Snuke" } else { "Fennec" })
}

