        let b = v[1]-1;
        graph.get_mut(a).unwrap().push(b);
        graph.get_mut(b).unwrap().push(a);
    }
    let mut used: Vec<bool> = Vec::new();
    used.resize(n, false);
    let mut sa = 0;
    let mut sb = 0;

    let mut aque = VecDeque::new();
    let mut bque = VecDeque::new();
    aque.push_back(0);
    bque.push_back(n-1);

    while !aque.is_empty() || !bque.is_empty() {
        let mut aque_new = VecDeque::new();
        while !aque.is_empty() {
            let tar = aque.pop_front().unwrap();
            if !used[tar] {
                used[tar] = true;
                sa += 1;
                for val in graph[tar].iter() {
                    aque_new.push_back(*val);
                }
            }
        }
        aque.append(&mut aque_new);
        let mut bque_new = VecDeque::new();
        while !bque.is_empty() {
            let tar = bque.pop_front().unwrap();
            if !used[tar] {
                sb += 1;
                used[tar] = true;
                for val in graph[tar].iter() {
                    bque_new.push_back(*val);
                }
            }
        }
        bque.append(&mut bque_new);
    }
    if sa > sb {
        println!("Fennec");
    } else {
        println!("Snuke");
    }


}

