type Graph = Vec<Vec<usize>>;

fn main() {
    input! {
        n: usize,
        edges: [(usize1, usize1); n-1],
    }

    let mut graph = vec![vec![]; n];

    for &(f, t) in &edges {
        graph[f].push(t);
        graph[t].push(f);
    }

    let mut queue = BinaryHeap::new();
    let mut color = vec![None; n];
    queue.push((-1, 0));
    queue.push((-2, n-1));

    while !queue.is_empty() {
        let q = queue.pop().unwrap();
        let turn = q.0;
        let cur = q.1;
        if color[cur].is_some() {
            continue;
        }
        color[cur] = Some(turn & 1);

        for &n in &graph[cur] {
            if color[n].is_some() {
                continue;
            }
            queue.push((turn - 2, n));
        }
    }
    let black = color.iter().filter(|c| c.unwrap() == 1).count();
    let white = n - black;

    if black > white {
        println!("Fennec");
    } else {
        println!("Snuke");
    }
}

use std::io::stdin;
use std::collections::VecDeque;

fn main() {
    let mut st = String::new();
    stdin().read_line(&mut st).unwrap();
    let n:usize = st.trim().parse().unwrap();
    let mut tree:Vec<Vec<usize>> = Vec::with_capacity(n);

    for _i in 0..n {tree.push([].to_vec())};

    for _i in 0..(n-1) {
        let mut st = String::new();
        stdin().read_line(&mut st).unwrap();
        let (a, b) = {
            let ab:Vec<usize> = st.trim().split(" ").map(|x| x.parse::<usize>().unwrap()).collect();
            (ab[0]-1, ab[1]-1)
        };
        tree[a].push(b);
        tree[b].push(a);
    };

    let mut f_queue:VecDeque<usize> = VecDeque::with_capacity(n);
    let mut s_queue:VecDeque<usize> = VecDeque::with_capacity(n);

    f_queue.push_back(0);
    s_queue.push_back(n-1);

    let mut visit:[i64;100002] = [-1; 100002];
    visit[0] = 0;
    visit[n-1] = 0;

    let mut f:i64 = 0;
    let mut f_h:bool = true;

    let mut s_h:bool = true;
    let mut s:i64 = 0;

    while s_h || f_h {
        if f_h {
            let mut g:Vec<usize> = Vec::new();
            while f_queue.len() != 0 {
                let p:usize = f_queue.pop_front().unwrap();
                for i in &tree[p] {
                    let num = *i as usize;
                    if visit[num] < 0 {
                        visit[num] = 0;
                        f += 1;
                        g.push(num);
                    };
                };
            };
            if g.len()==0{
                f_h = false;
            } else {
                f_queue = g.into_iter().collect();
            };
        };

        if s_h {
            let mut g:Vec<usize> = Vec::new();
            while s_queue.len() != 0 {
                let p:usize = s_queue.pop_front().unwrap();
                for i in &tree[p] {
                    let num = *i as usize;
                    if visit[num] < 0 {
                        visit[num] = 0;
                        s += 1;
                        g.push(num);
                    };
                };
            };
            if g.len()==0 {
                s_h = false;
            } else {
                s_queue = g.into_iter().collect();
            };
        };
    };
    if f > s {
        println!("Fennec");
    } else {
        println!("Snuke");
    };
}

