       n: usize,
       edges:[(usize1,usize1);n-1],
    }

    let mut map = vec![vec![]; n];
    let mut used: Vec<Option<usize>> = vec![None; n];
    for &(f, t) in &edges {
        map[f].push(t);
        map[t].push(f);
    }

    let mut kouho = VecDeque::new();
    kouho.push_back((0, 0));
    let mut used = vec![None; n];
    used[0] = Some(0);
    let mut d = 0;
    while !kouho.is_empty() {
        let (p, depth) = kouho.pop_front().unwrap();
        if p == n - 1 {
            d = depth;
            break;
        }

        for i in 0..map[p].len() {
            let next = map[p][i];
            if used[next].is_some() {
                continue;
            }
            used[next] = Some(p);
            kouho.push_back((next, depth + 1));
        }
    }
    let mut path = vec![n - 1];
    let mut cur = n - 1;
    while cur != 0 {
        cur = used[cur].unwrap();
        path.push(cur);
    }
    path.reverse();
    let mut used = vec![0; n];
    let mut first = 0;
    for i in 0..path.len() / 2 + 1 {
        let a = path[i];
        if used[a] == 0 {
            used[a] = 1;
            first = i;
        }
        if path.len() > i {
            let b = path[path.len() - i - 1];
            if used[b] == 0 {
                used[b] = 2;
            }
        }
    }
    mydbg!(first, path[first], path, used);
    let mut kouho = VecDeque::new();
    let mut used = vec![0; n];
    used[path[first]] = 1;
    used[path[first + 1]] = 2;
    kouho.push_back((path[first], 0));
    let mut d = 0;
    while !kouho.is_empty() {
        let (p, depth) = kouho.pop_front().unwrap();
        for i in 0..map[p].len() {
            let next = map[p][i];
            if used[next] != 0 {
                continue;
            }
            used[next] = 1;

            kouho.push_back((next, depth + 1));
        }
    }

    mydbg!(used);
    let fenec = used.iter().filter(|x| **x == 1).count();
    let sunuke = n - fenec;
    mydbg!(fenec, sunuke);

    echo!(if fenec > sunuke { "Fennec" } else { "Snuke" });
}

