fn wfs(graph: &[Vec<usize>], root: usize, dists: &mut [i64]) {
    let mut q = BinaryHeap::new();

    q.push((0i64, root));
    while let Some((d, r)) = q.pop() {
        if dists[r] != -1 {
            continue;
        }

        dists[r] = d;

        for &b in graph[r].iter() {
            q.push((d + 1, b))
        }
    }
}

fn main() {
    let n = scan!(usize);

    let mut graph = vec![vec![]; n + 1];
    for _ in 0..n - 1 {
        let (a, b) = scan!(usize, usize);
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut dists0 = vec![-1; n + 1];
    wfs(&graph, 1, &mut dists0);
    let mut dists1 = vec![-1; n + 1];
    wfs(&graph, n, &mut dists1);

    let (mut s, mut f) = (0, 0);
    for (d0, d1) in dists0.iter().zip(dists1.iter()).skip(1) {
        if d1 < d0 {
            s += 1
        } else {
            f += 1
        }
    }

    println!("{}", if s > f { "Snuke" } else { "Fennec" })
}

