fn subtree_size(N:usize,E:&Vec<Vec<usize>>,root:usize) -> Vec<isize>{
    let mut n = vec![-1;N];
    _subtree_size(N,E,&mut n,root,root);
    n
}
fn _subtree_size(N:usize,E:&Vec<Vec<usize>>,n:&mut Vec<isize>,i:usize,p:usize) {
    let mut cnt = 1;
    for &j in &E[i]{
        if j==p{continue;}
        if n[j]==-1 {_subtree_size(N,E,n,j,i);}
        cnt += n[j];
    }
    n[i] = cnt;
}


fn bfs_dist(N:usize,E:&Vec<Vec<usize>>,start:usize) -> Vec<isize>{
    let mut d = vec![-1;N];
    let mut q = VecDeque::new();
    q.push_back(start);
    d[start] = 0;
    while let Some(i) = q.pop_front(){
        for &j in &E[i]{
            if d[j]!= -1{continue;}
            d[j] = d[i]+1;
            q.push_back(j);
        }
    }
    d
}

