fn dfs(g: &Vec<Vec<usize>>, v: usize, cnt: &mut usize, visited: &mut Vec<bool>) {
    visited[v] = true;
    *cnt += 1;

    for node in &g[v] {
        if visited[*node] {
            continue;
        }

        dfs(g, *node, cnt, visited);
    }
}

fn main() {
