        g[a].push(b);
        g[b].push(a);
    }
    let mut max_f = 0;
    for &node in &g[0] {
        if node == n - 1 {
            continue;
        }
        let mut cnt = 0;
        let mut visited = vec![false; n];
        visited[0] = true;
        visited[n - 1] = true;
        dfs(&g, node, &mut cnt, &mut visited);
        max_f = max(max_f, cnt);
    }

    let mut max_s = 0;
    for &node in &g[n - 1] {
        if node == 0 {
            continue;
        }
        let mut cnt = 0;
        let mut visited = vec![false; n];
        visited[n - 1] = true;
        visited[0] = true;
        dfs(&g, node, &mut cnt, &mut visited);
        max_s = max(max_s, cnt);
    }
    println!("{}", if max_f > max_s { "Fennec" } else { "Snuke" });
}

