macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let mut g = vec![vec![]; n];
    for _ in 0..(n - 1) {
        let (a, b): (usize, usize) = parse!(it, 2);
        g[a - 1].push(b - 1);
        g[b - 1].push(a - 1);
    }
    let dfs = |u: usize| {
        let mut stack = vec![u];
        let mut ret = vec![None; n];
        ret[u] = Some(0);
        while let Some(u) = stack.pop() {
            for &v in g[u].iter() {
                if ret[v] == None {
                    ret[v] = Some(ret[u].unwrap() + 1);
                    stack.push(v)
                }
            }
        }
        ret.into_iter().map(|x| x.unwrap()).collect::<Vec<usize>>()
    };
    let da = dfs(0);
    let db = dfs(n - 1);
    let count = da
        .into_iter()
        .zip(db.into_iter())
        .filter(|&(x, y)| x <= y)
        .count();
    println!("{}", if 2 * count > n { "Fennec" } else { "Snuke" });
}

