// 単一始点から目的のノードへの最短経路超を探索
fn dijkstra_to_goal(n: usize, adj_list: &Vec<Vec<(usize, u64)>>, start: usize, goal: usize) -> u64 {
  let mut dist = vec![std::u64::MAX; n];
  let mut p_queue: BinaryHeap<(i64, usize)> = BinaryHeap::new();

  //init
  dist[start] = 0;
  p_queue.push((0, start));

  while !p_queue.is_empty() {
    // 起点となるノード
    let (cost, now)
      = match p_queue.pop() {
        None => break,
        Some(e) => (-e.0 as u64, e.1),
      };

      if now == goal {
        break;
      }

    // 繋がっているノードを探索
    for &edge in &adj_list[now] {
      let next = edge.0;
      let weight = edge.1;

      if dist[next] > weight + cost {
        p_queue.push((-((weight + cost) as i64), next));
        dist[next] = weight + cost;
      }
    }

  }

  dist[goal]
}


fn bfs(n: usize, g: &Vec<Vec<(usize, u64)>>, start: usize, oppsite: usize) -> u64 {
  let mut visit = vec![false; n];
  let mut q = VecDeque::new();
  let mut count = 0;
  //init
  visit[start] = true;
  q.push_back(start);

  while !q.is_empty() {
    let now
      = match q.pop_front() {
        None => 0,
        Some(e) => e,
      };

      for &e in &g[now] {
        if !visit[e.0] && e.0 != oppsite {
          visit[e.0] = true;
          q.push_back(e.0);
          count += 1;
        }
      }
  }

  count
}

macro_rules! scan {
