    let mut d = vec![-1;N];
    let mut q = VecDeque::new();
    q.push_back(start);
    d[start] = 0;
    while let Some(i) = q.pop_front(){
        for &j in &E[i]{
            if d[j]!= -1{continue;}
            d[j] = d[i]+1;
            q.push_back(j);
        }
    }
    d
}

