use std::io::prelude::*;

fn input<T>() -> T
where
    T: std::str::FromStr,
{
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let n: usize = input();
    let ab: Vec<(usize, usize)> = (1..n)
        .map(|_| {
            let a = input();
            let b = input();
            (a, b)
        })
        .collect();

    let mut path = vec![vec![]; n + 1];
    for (a, b) in ab {
        path[a].push(b);
        path[b].push(a);
    }

    let mut d1 = vec![-1; n + 1];
    d1[1] = 0;
    let mut dn = vec![-1; n + 1];
    dn[n] = 0;
    let mut q = std::collections::VecDeque::new();

    q.push_back(1);
    while !q.is_empty() {
        let i = q.pop_front().unwrap();
        for &next in &path[i] {
            if d1[next] >= 0 {
                continue;
            }

            q.push_back(next);
            d1[next] = d1[i] + 1;
        }
    }

    q.push_back(n);
    while !q.is_empty() {
        let i = q.pop_front().unwrap();
        for &next in &path[i] {
            if dn[next] >= 0 {
                continue;
            }

            q.push_back(next);
            dn[next] = dn[i] + 1;
        }
    }

    let mut m = vec![0; n + 1];
    for i in 1..n + 1 {
        if d1[i] <= dn[i] {
            m[i] = 1;
        } else {
            m[i] = 2;
        }
    }

    let c1 = m.iter().filter(|&i| *i == 1).count();
    let c2 = n - c1;

    println!("{}", if c1 > c2 { "Fennec" } else { "Snuke" });
}

