        graph[b].push(a);
    }

    let mut route = vec![n; n];
    let mut que = VecDeque::new();
    que.push_back((0, 0));
    while let Some((node, prev)) = que.pop_front() {
        route[node] = prev;
        for &next in &graph[node] {
            if route[next] == n {
                que.push_back((next, node));
            }
        }
    }

    let mut trunk = VecDeque::new();
    let mut pos = n-1;
    while route[pos] != 0 {
        trunk.push_front(route[pos]);
        pos = route[pos];
    }

    let mut visited = vec![false; n];
    let mut lque = VecDeque::new();
    visited[0] = true;
    lque.push_back(0);
    let mut sque = VecDeque::new();
    visited[n-1] = true;
    sque.push_back(n-1);
    while let Some(node) = trunk.pop_front() {
        visited[node] = true;
        lque.push_back(node);
        if let Some(node) = trunk.pop_back() {
            visited[node] = true;
            sque.push_back(node);
        }
    }

