             cur_v: usize, goal: usize
             , traced_path: &Vec<usize>) -> Vec<usize>{

    if cur_v == goal{
        let mut res = traced_path.clone();
        res.push(cur_v);
        return res;
    }

    for &next_v in &graph[cur_v]{
        //ensure infinit loop
        if traced_path.len() > 0 && *traced_path.last().unwrap() == next_v{
            continue;
        }
        let mut traced_path = traced_path.clone();
        traced_path.push(cur_v);
        let res = find_path(graph, next_v, goal, &traced_path);
        if res.len() > 0{
            return res;
        }
    }
    return vec![];
}

