fn main() {
    input! {
        n: usize,
        ab: [(usize, usize);n-1]
    }
    let mut edges = vec![vec![]; n];
    for i in ab {
        edges[i.0 - 1].push(i.1 - 1);
        edges[i.1 - 1].push(i.0 - 1)
    }

    let mut ldist = vec![0; n];
    let mut stack = Vec::new();
    let mut visited = vec![false; n];
    stack.push((0, 0));
    visited[0] = true;
    while let Some((node, dist)) = stack.pop() {
        ldist[node] = dist;
        for &next in &edges[node] {
            if !visited[next] {
                visited[next] = true;
                stack.push((next, dist + 1));
            }
        }
    }
    let mut rdist = vec![0; n];
    let mut stack = Vec::new();
    let mut visited = vec![false; n];
    stack.push((n - 1, 0));
    visited[n - 1] = true;
    while let Some((node, dist)) = stack.pop() {
        rdist[node] = dist;
        for &next in &edges[node] {
            if !visited[next] {
                visited[next] = true;
                stack.push((next, dist + 1));
            }
        }
    }
    let mut p = 0i64;
    for i in 1..n - 1 {
        if ldist[i] <= rdist[i] {
            p += 1;
        } else {
            p -= 1;
        }
    }
    if p > 0 {
        println!("Fennec");
    } else {
        println!("Snuke");
    }
}

