        edges: [(usize1, usize1); N-1],
    }

    let mut e = vec![Vec::new(); N];
    for &(a, b) in edges.iter() {
        e[a].push(b);
        e[b].push(a);
    }

    let mut is_visited = vec![false; N];
    let mut feneque = VecDeque::new();
    feneque.push_back(0);
    let mut fen_count = 0;
    let mut sunuque = VecDeque::new();   
    sunuque.push_back(N-1);
    let mut sun_count = 0;

    loop {
        let c1 = feneque.len();
        for _ in 0..c1 {
            let v = feneque.pop_front().unwrap();
            if !is_visited[v] {
                fen_count += 1;
                is_visited[v] = true;
                for &vv in e[v].iter() {
                    feneque.push_back(vv);
                }
            }
        }

        let c2 = sunuque.len();
        for _ in 0..c2 {
            let v = sunuque.pop_front().unwrap();
            if !is_visited[v] {
                sun_count += 1;
                is_visited[v] = true;
                for &vv in e[v].iter() {
                    sunuque.push_back(vv);
                }
            }
        }
        if (c1, c2) == (0, 0) { break; }
    }
    if fen_count > sun_count {
        println!("Fennec");
    } else {
        println!("Snuke");
    }
}

