    }
    let D = bfs_dist(N,&E,0);
    let n = dfs_subtree_size(N, &E, 0);
    let d = D[N-1]/2+1;

    let mut i = N-1;
    while D[i] != d{
        for &j in &E[i]{
            if D[j]<D[i]{
                i = j;
                break
            }
