fn dfs_subtree_size(N:usize,E:&Vec<Vec<usize>>,start:usize) -> Vec<isize>{
    let mut n = vec![-1;N];
    let mut q = vec![(start,start)];
    while let Some((i,p)) = q.pop(){
        let mut popped = true;
        let mut cnt = 1;
        for &j in &E[i]{
            if j == p{ continue;}
            if n[j] == -1{
                if popped {
                    q.push((i,p));
                    popped = false;
                }
                q.push((j,i));
            } else {
                cnt += n[j];
            }
        }
        if popped{
            n[i] = cnt;
        }
    }
    n
}


fn bfs_dist(N:usize,E:&Vec<Vec<usize>>,start:usize) -> Vec<isize>{
    let mut d = vec![-1;N];
    let mut q = Vec::new();
    q.push(start);
    d[start] = 0;
    while !q.is_empty(){
        let mut qq = Vec::new();
        for &i in &q{
            for &j in &E[i]{
                if d[j]!= -1{continue;}
                d[j] = d[i]+1;
                qq.push(j);
            }
        }
        q = qq;
    }
    d
}

