fn find_path(graph: &Vec<Vec<usize>>,
             cur_v: usize, goal: usize
             , traced_path: &Vec<usize>) -> Vec<usize>{

    if cur_v == goal{
        let mut res = traced_path.clone();
        res.push(cur_v);
        return res;
    }

    for &next_v in &graph[cur_v]{
        //ensure infinit loop
        if traced_path.len() > 0 && *traced_path.last().unwrap() == next_v{
            continue;
        }
        let mut traced_path = traced_path.clone();
        traced_path.push(cur_v);
        let res = find_path(graph, next_v, goal, &traced_path);
        if res.len() > 0{
            return res;
        }
    }
    return vec![];
}

fn calc_num_nodes(graph: &Vec<Vec<usize>>, cur_v: usize, prev_v: usize) -> usize{
    let mut sum = 1;
    for &next_v in &graph[cur_v]{
        if next_v == prev_v{
            continue;
        }

        sum += calc_num_nodes(graph, next_v, cur_v);
    }
    return sum;

}
