fn bfs(s: usize, g: &Vec<Vec<usize>>) -> Vec<usize> {
    let mut que = VecDeque::new();
    let mut dist = vec![std::usize::MAX; g.len()];
    dist[s] = 0;
    que.push_back(s);
    while let Some(v) = que.pop_front() {
        for &u in &g[v] {
            if dist[u] <= dist[v] { continue; }
            dist[u] = dist[v] + 1;
            que.push_back(u);
        }
    }
    dist
}


