fn make_rooted_tree(N:usize,E:&Vec<Vec<usize>>,root:usize) -> (Vec<Vec<usize>>,Vec<Vec<usize>>){
    let mut Ef = vec![Vec::new();N];
    let mut Eb = vec![Vec::new();N];
    let mut done = vec![false;N];
    let mut q = VecDeque::new();
    q.push_back(root);
    done[root] = true;
    while let Some(i) = q.pop_front(){
        for &j in &E[i]{
            if done[j] {continue;}
            done[j] = true;
            q.push_back(j);
            Ef[i].push(j);
            Eb[j].push(i);
        }
    }
    (Ef,Eb)
}

fn dfs_connect(N:usize,E:&Vec<Vec<usize>>,start:usize) -> Vec<bool>{
    let mut done = vec![false;N];
    done[start] = true;
    let mut q = vec![start];
    while let Some(i) = q.pop(){
        for &j in &E[i]{
            if done[j] {continue;}
            q.push(j);
            done[j] = true;
        }
    }
    done
}

fn bfs_dist(N:usize,E:&Vec<Vec<usize>>,start:usize) -> Vec<isize>{
    let mut d = vec![-1;N];
    let mut q = VecDeque::new();
    q.push_back(start);
    d[start] = 0;
    while let Some(i) = q.pop_front(){
        for &j in &E[i]{
            if d[j]!= -1{continue;}
            d[j] = d[i]+1;
            q.push_back(j);
        }
    }
    d
}

