use std::collections::BinaryHeap;

macro_rules! scan {
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($t:ty;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };

    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
}

fn wfs(graph: &[Vec<usize>], root: usize, dists: &mut [i64]) {
    let mut q = BinaryHeap::new();

    q.push((0i64, root));
    while let Some((d, r)) = q.pop() {
        if dists[r] != -1 {
            continue;
        }

        dists[r] = -d;

        for &b in graph[r].iter() {
            q.push((-(-d + 1), b))
        }
    }
}

fn main() {
    let n = scan!(usize);

    let mut graph = vec![vec![]; n + 1];
    for _ in 0..n - 1 {
        let (a, b) = scan!(usize, usize);
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut dists_f = vec![-1; n + 1];
    wfs(&graph, 1, &mut dists_f);
    let mut dists_s = vec![-1; n + 1];
    wfs(&graph, n, &mut dists_s);

    let (mut s, mut f) = (0, 0);
    for (f0, s0) in dists_f.iter().zip(dists_s.iter()).skip(1) {
        if f0 <= s0 {
            f += 1
        } else {
            s += 1
        }
    }
    println!("{}", if s > f { "Snuke" } else { "Fennec" })
}

use std::fs;
use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let mut g = vec![vec![]; n];
    for _ in 0..(n - 1) {
        let (a, b): (usize, usize) = parse!(it, 2);
        g[a - 1].push(b - 1);
        g[b - 1].push(a - 1);
    }
    let mut parents = vec![None; n];
    let mut stack = vec![0];
    parents[0] = Some(n);
    while let Some(u) = stack.pop() {
        for &v in &g[u] {
            if parents[v] == None {
                parents[v] = Some(u);
                stack.push(v);
            }
        }
    }
    let mut path = vec![];
    let mut cur = n - 1;
    while cur != 0 {
        path.push(cur);
        cur = parents[cur].unwrap();
    }
    path.reverse();
    let block = path[(path.len()) / 2];
    let mut count = 0;
    let mut stack = vec![0];
    let mut seen = vec![false; n];
    seen[block] = true;
    while let Some(u) = stack.pop() {
        count += 1;
        for &v in g[u].iter() {
            if !seen[v] {
                stack.push(v);
                seen[v] = true;
            }
        }
    }
    println!("{}", if 2 * count > n { "Fennec" } else { "Snuke" });
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

