use input::*;
use std::collections::VecDeque;

#[derive(Clone, Copy, Debug)]
enum Edge {
    Fennec,
    Snuke,
}

fn main() {
    let n: usize;
    input!(n);
    let mut result = vec![None; n];
    let mut g = vec![vec![]; n];
    for _ in 1..n {
        let (a, b): (usize, usize);
        input!(a, b);
        g[a - 1].push(b - 1);
        g[b - 1].push(a - 1);
    }

    let mut turn = Edge::Fennec;
    let mut que_fennec = VecDeque::new();
    let mut que_snuke = VecDeque::new();
    que_fennec.push_front(0);
    que_snuke.push_front(n - 1);

    while !que_fennec.is_empty() || !que_snuke.is_empty() {
        let mut que = VecDeque::new();
        if let Edge::Fennec = turn {
            turn = Edge::Snuke;
            while !que_fennec.is_empty() {
                let e = que_fennec.pop_back().unwrap();
                if result[e].is_some() {
                    continue;
                }
                result[e] = Some(Edge::Fennec);
                for e_next in &g[e] {
                    if let None = result[*e_next] {
                        que.push_front(*e_next);
                    }
                }
            }
            que_fennec = que;
        } else {
            turn = Edge::Fennec;
            while !que_snuke.is_empty() {
                let e = que_snuke.pop_back().unwrap();
                if result[e].is_some() {
                    continue;
                }
                result[e] = Some(Edge::Snuke);
                for e_next in &g[e] {
                    if let None = result[*e_next] {
                        que.push_front(*e_next);
                    }
                }
            }
            que_snuke = que;
        }
        //println!("{:?}", &result);
    }
    let mut count_fennec = 0;
    let mut count_snuke = 0;
    for e in result {
        if let Edge::Fennec = e.unwrap() {
            count_fennec += 1;
        } else {
            count_snuke += 1;
        }
    }
    if count_fennec <= count_snuke {
        p("Snuke");
    } else {
        p("Fennec");
    }
}

