fn main() {
    let mut scanner = Scanner::new(stdin());
    let n = scanner.read::<usize>().unwrap();
    let mut adj = AdjacencyList::new(n);
    for _ in 0..(n - 1) {
        let line = scanner.read_vector::<usize>().unwrap();
        let (i, j) = (line[0] - 1, line[1] - 1);
        adj.add(i, j);
        adj.add(j, i);
    }
    if judge(&adj) {
        println!("Fennec");
    } else {
        println!("Snuke");
    }
}

fn judge(adj: &AdjacencyList) -> bool {
    let (p_1, p_2) = find_mid(0, adj.len() - 1, adj);
    let count_1 = bfs(0, p_2, adj);
    let count_2 = bfs(adj.len() - 1, p_1, adj);
    count_1 > count_2
}

fn find_mid(src: usize, snk: usize, adj: &AdjacencyList) -> (usize, usize) {
    let mut path_length = 0;
    let mut queue = VecDeque::new();
    let mut used_queue = vec![];
    queue.push_front((src, src, 0));
    while queue.len() > 0 {
        let (crt, prv, len) = queue.pop_back().unwrap();
        used_queue.push((crt, prv, len));
        if crt == snk {
            path_length = len;
            break;
        } 
        for nxt in adj[crt].iter() {
            if *nxt == prv {
                continue;
            }
            queue.push_front((*nxt, crt, len + 1));
        }
    }
    let mut crt = snk;
    let mut first = 0;
    let mut second = 0;
    loop {
        let (c, prv, len) = used_queue.pop().unwrap();
        if c != crt {
            continue;
        }
        if len == path_length / 2 + 1 {
            second = crt;
        }
        if len == path_length / 2 {
            first = crt;
            break;
        }
        crt = prv;
    }
    (first, second)
}


fn bfs(src: usize, target: usize, adj: &AdjacencyList) -> usize {
    let mut count = 0;
    let mut queue = VecDeque::new();
    queue.push_front((src, src, 0));
    while queue.len() > 0 {
        let (crt, prv, len) = queue.pop_back().unwrap();
        if crt == target {
            continue;
        }
        for nxt in adj[crt].iter() {
            if *nxt == prv {
                continue;
            }
            queue.push_front((*nxt, crt, len + 1));
            count += 1;
        }
    }
    count - 1
}

struct AdjacencyList (Vec<Vec<usize>>);

impl AdjacencyList {
    fn new(n: usize) -> Self {
        AdjacencyList(vec![vec![]; n])
    }
    fn add(&mut self, i: usize, j: usize) {
        self.0[i].push(j);
    }
    fn len(&self) -> usize {
        self.0.len()
    }
}

impl std::ops::Index<usize> for AdjacencyList {
    type Output = Vec<usize>;
    fn index(&self, i: usize) -> &Self::Output {
        &self.0[i]
    }
}

