#[fastout()]
fn main() {
    input! {
        n: usize,
        ab: [(Usize1, Usize1); n-1]
    }

    let mut graph = vec![Vec::new(); n];
    for (a, b) in ab {
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut ldist = vec![0; n];
    let mut stack = Vec::new();
    let mut visited = vec![false; n];
    stack.push((0, 0));
    visited[0] = true;
    while let Some((node, dist)) = stack.pop() {
        ldist[node] = dist;
        for &next in &graph[node] {
            if !visited[next] {
                visited[next] = true;
                stack.push((next, dist+1));
            }
        }
    }

    let mut rdist = vec![0; n];
    let mut stack = Vec::new();
    let mut visited = vec![false; n];
    stack.push((n-1, 0));
    visited[n-1] = true;
    while let Some((node, dist)) = stack.pop() {
        rdist[node] = dist;
        for &next in &graph[node] {
            if !visited[next] {
                visited[next] = true;
                stack.push((next, dist+1));
            }
        }
    }

    let mut p = 0i64;
    for i in 1..n-1 {
        if ldist[i] <= rdist[i] {
            p += 1;
        } else {
            p -= 1;
        }
    }
    if p > 0 {
        println!("Fennec");
    } else {
        println!("Snuke");
    }
}

