// cf. [Rustで競技プログラミングの入力をスッキリ記述するマクロ - Qiita](https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8)
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

use std::collections::HashSet;
fn main() {
    input! {
        N: usize,
        ab: [(usize1, usize1); N-1],
    }
    let mut edges = Vec::with_capacity(N);
    for _ in 0..N {
        edges.push(vec![]);
    }
    for &(a, b) in &ab {
        edges[a].push(b);
        edges[b].push(a);
    }
    use std::collections::{VecDeque, HashSet};
    let mut queue = VecDeque::new();
    let mut visited = HashSet::new();
    queue.push_back((0, vec![]));

    let mut link = vec![];
    while let Some((cur, mut v)) = queue.pop_front() {
        if visited.contains(&cur) {
            continue;
        }
        v.push(cur);
        if cur == N - 1 {
            let l = v.len();
            link = v;
            break;
        }
        visited.insert(cur);

        for &to in &edges[cur] {
            queue.push_back((to, v.clone()));
        }
    }

    let mut f_cnt = 0;
    let mut s_cnt = 0;
    let mid = (link.len() + 1) / 2;
    let mut visited = HashSet::new();
    for i in 0..mid {
        let ex = if i + 1 < link.len() { link[i + 1]} else { 1 << 60 };
        f_cnt += dfs(&edges, ex, &mut visited, link[i]);
    }
    for i in mid..link.len() {
        let ex = if i + 1 < link.len() { link[i + 1]} else { 1 << 60 };
        s_cnt += dfs(&edges, ex, &mut visited, link[i]);
    }

    println!("{}", if f_cnt > s_cnt {"Fennec"} else {"Snuke"});
}

fn dfs(edges: &Vec<Vec<usize>>, exclude: usize, visited: &mut HashSet<usize>, cur: usize) -> usize {
    let mut cnt = 1;
    visited.insert(cur);
    for &to in &edges[cur] {
        if visited.contains(&to) || to == exclude {
            continue;
        }
        cnt += dfs(edges, exclude, visited, to);
    }
    cnt
}

