fn recurse<X, Y>(x: X, f: &Fn(X, &Fn(X) -> Y) -> Y) -> Y {
    f(x, &|x: X| recurse(x, &f))
}
use std::cell::RefCell;
fn main() {
    input! { n, ab: [(usize1, usize1); n-1] };
    let mut graph = vec![vec![]; n];
    for &(a, b) in &ab {
        graph[a].push(b);
        graph[b].push(a);
    }
    let visited1 = RefCell::new(vec![-1; n]);
    visited1.borrow_mut()[0] = 0;
    recurse(0, &|x, f| {
        let d = visited1.borrow()[x];
        for &y in &graph[x] {
            if visited1.borrow()[y] < 0 {
                visited1.borrow_mut()[y] = d + 1;
                f(y);
            }
        }
        false
    });
    let visited2 = RefCell::new(vec![-1; n]);
    visited2.borrow_mut()[n - 1] = 0;
    recurse(n - 1, &|x, f| {
        let d = visited2.borrow()[x];
        for &y in &graph[x] {
            if visited2.borrow()[y] < 0 {
                visited2.borrow_mut()[y] = d + 1;
                f(y);
            }
        }
        false
    });
    let cnt = visited1
        .into_inner()
        .into_iter()
        .zip(visited2.into_inner().into_iter())
        .filter(|(x, y)| x <= y)
        .count();
    if cnt <= n - cnt {
        println!("Snuke");
    } else {
        println!("Fennec");
    }
}

use std::io::stdin;
use std::collections::VecDeque;

fn main() {
    let mut st = String::new();
    stdin().read_line(&mut st).unwrap();
    let n:usize = st.trim().parse().unwrap();
    let mut tree:Vec<Vec<usize>> = Vec::with_capacity(n);
    for _i in 0..n {
        tree.push([].to_vec());
    };

    for _i in 0..(n-1) {
        let mut st = String::new();
        stdin().read_line(&mut st).unwrap();
        let (a, b) = {
            let ab:Vec<usize> = st.trim().split(" ").map(|x| x.parse::<usize>().unwrap()).collect();
            (ab[0]-1, ab[1]-1)
        };
        tree[a].push(b);
        tree[b].push(a);
    };

    let mut s_queue:VecDeque<usize> = VecDeque::with_capacity(n);
    let mut f_queue:VecDeque<usize> = VecDeque::with_capacity(n);
    s_queue.push_back(n-1);
    f_queue.push_back(0);

    let mut visit:[i64;100002] = [-1; 100002];
    visit[0] = 0;
    visit[n-1] = 0;
    let mut s:i64 = 0;
    let mut f:i64 = 0;

    while s_queue.len() != 0 && f_queue.len() != 0 {
        if f_queue.len() != 0 {
            let p:usize = f_queue.pop_front().unwrap();
            for i in &tree[p] {
                let num = *i as usize;
                if visit[num] < 0 {
                    visit[num] = 0;
                    f += 1;
                    f_queue.push_back(num);
                };
            };
        };
        if s_queue.len() != 0 {
            let p:usize = s_queue.pop_front().unwrap();
            for i in &tree[p] {
                let num = *i as usize;
                if visit[num] < 0 {
                    visit[num] = 0;
                    s += 1;
                    s_queue.push_back(num);
                };
            };
        };
    };
    if f > s {
        println!("Fennec");
    } else {
        println!("Snuke");
    };
}

