fn solve() {
    let n = get!(usize);
    let ab = get!(usize, usize;n-1);

    let mut nodes = vec![Vec::new(); n+1];
    for (a,b) in ab {
        nodes[a].push(b);
        nodes[b].push(a);
    }

    let mut queue = VecDeque::new();
    let mut map = BTreeMap::new();
    queue.push_back(1);
    while let Some(node) = queue.pop_front() {
        if node == n {
            break;
        }
        for &next in &nodes[node] {
            if map.contains_key(&next) {
                continue;
            }
            queue.push_back(next);
            map.insert(next, node);
        }
    }

    let mut route = VecDeque::new();
    let mut now = n;
    route.push_front(n);
    while let Some(node) = map.get(&now).cloned() {
        route.push_front(node);
        now = node;
        if node == 1 {
            break;
        }
    }

    let rlen = route.len();
    //black
    let mut queue = VecDeque::new();
    let mut visited = BTreeSet::new();
    let mut count = 0;
    for &node in route.iter().take(rlen-rlen/2) {
        queue.push_back(node);
        visited.insert(node);
        count += 1;
    }
    visited.insert(route[rlen-rlen/2]);

    while let Some(node) = queue.pop_front() {
        for &next in &nodes[node] {
            if visited.contains(&next) {
                continue;
            }
            count += 1;
            queue.push_back(next);
            visited.insert(next);
        }
    }

    let black = count;

    //white
    let mut queue = VecDeque::new();
    let mut visited = BTreeSet::new();
    let mut count = 0;
    for &node in route.iter().skip(rlen-rlen/2) {
        queue.push_back(node);
        visited.insert(node);
        count += 1;
    }
    visited.insert(route[rlen-rlen/2-1]);

    while let Some(node) = queue.pop_front() {
        for &next in &nodes[node] {
            if visited.contains(&next) {
                continue;
            }
            count += 1;
            queue.push_back(next);
            visited.insert(next);
        }
    }

    let white = count;

    if black > white {
        println!("Fennec");
    } else {
        println!("Snuke");
    }
}

