use std::cell::RefCell;
fn main() {
    input! { n, ab: [(usize1, usize1); n-1] };
    let mut graph = vec![vec![]; n];
    for &(a, b) in &ab {
        graph[a].push(b);
        graph[b].push(a);
    }
    let visited = RefCell::new(vec![false; n]);
    let path = RefCell::new(vec![]);
    visited.borrow_mut()[0] = true;
    recurse(0, &|x, f| {
        if x == n - 1 {
            return true;
        }
        for &y in &graph[x] {
            if !visited.borrow()[y] {
                visited.borrow_mut()[y] = true;
                if f(y) {
                    path.borrow_mut().push(y);
                    return true;
                }
            }
        }
        false
    });
    let path = path.into_inner();
    let len = path.len();
    let visited = RefCell::new(vec![false; n]);
    visited.borrow_mut()[0] = true;
    visited.borrow_mut()[path[(len - 1) / 2]] = true;
    let cnt = RefCell::new(0);
    recurse(0, &|x, f| {
        for &y in &graph[x] {
            if !visited.borrow()[y] {
                visited.borrow_mut()[y] = true;
                *cnt.borrow_mut() += 1;
                f(y)
            }
        }
    });
    let cnt = cnt.into_inner();
    if cnt == n - 2 - cnt {
        println!("Snuke");
    } else if cnt < n - 2 - cnt {
        println!("Snuke");
    } else {
        println!("Fennec");
    }
}

