use std::io::*;
use std::str::FromStr;

pub fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn dfs(
    cn: usize,
    map: &Vec<Vec<usize>>,
    depth: usize,
    tn: usize,
    pn: usize,
    root: Vec<usize>,
) -> (usize, Vec<usize>) {
    if cn == tn {
        return (depth, root);
    }

    let mut maxv = 0;
    let mut return_root: Vec<usize> = vec![];

    for i in 0..map[cn].len() {
        let mut rootc = root.clone();
        let mi = map[cn][i];
        if pn == mi {
            continue;
        }
        rootc.push(mi);
        let (result, r_root) = dfs(mi, map, depth + 1, tn, cn, rootc);
        if result > maxv {
            maxv = result;
            return_root = r_root;
        }
    }
    return (maxv, return_root);
}

fn dfs2(cn: usize, map: &Vec<Vec<usize>>, colors: &mut Vec<i64>, color: i64) {
    if (cn != 1 && cn != map.len()) {
        if colors[cn] == 0 {
            colors[cn] = color
        } else {
            return;
        }
    }

    for i in 0..map[cn].len() {
        let mut mi = map[cn][i];
        if colors[mi] != 0 {
            continue;
        }
        dfs2(mi, map, colors, color)
    }
}

fn main() {
    let n: usize = read();
    let mut map: Vec<Vec<usize>> = vec![vec![]; n + 1];
    let mut colors: Vec<i64> = vec![0; n + 1];
    for _ in 0..n - 1 {
        let a: usize = read();
        let b: usize = read();
        map[a].push(b);
        map[b].push(a);
    }
    let mut route = vec![];
    let (result, route) = dfs(1, &map, 0, n, 0, route);
    // -1: black, 1: white
    if result > 1 {
        colors[route[result / 2 - 1]] = -1;
    }
    colors[1] = -1;
    colors[n] = 1;
    dfs2(1, &map, &mut colors, -1);
    dfs2(n, &map, &mut colors, 1);

    let black = colors.iter().filter(|&x| *x == -1).count();
    let white = colors.iter().filter(|&x| *x == 1).count();
    if black > white {
        println!("Fennec")
    } else {
        println!("Snuke")
    }
}

