fn dfs(g: &Vec<Vec<usize>>, v: usize, ng: usize, visited: &mut Vec<bool>) {
    if v == ng {
        return;
    }
    visited[v] = true;

    for node in &g[v] {
        if visited[*node] {
            continue;
        }
