fn bfs(start: usize, n: usize, v: &Vec<Vec<usize>>) -> Vec<usize> {
    let mut dist = vec![usize::max_value(); n];
    dist[start] = 0;
    let mut q = VecDeque::new();
    q.push_back(start);
    while !q.is_empty() {
        let pos = *q.front().unwrap();
        q.pop_front().unwrap();
        for next in v[pos].iter() {
            if dist[*next] <= dist[pos] {
                continue;
            }
            dist[*next] = dist[pos] + 1;
            q.push_back(*next);
        }
    }
    dist
}

