macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let mut g = vec![vec![]; n];
    for _ in 0..(n - 1) {
        let (a, b): (usize, usize) = parse!(it, 2);
        g[a - 1].push(b - 1);
        g[b - 1].push(a - 1);
    }
    let mut parents = vec![None; n];
    let mut stack = vec![0];
    parents[0] = Some(n);
    while let Some(u) = stack.pop() {
        for &v in &g[u] {
            if parents[v] == None {
                parents[v] = Some(u);
                stack.push(v);
            }
        }
    }
    let mut path = vec![];
    let mut cur = n - 1;
    while cur != 0 {
        path.push(cur);
        cur = parents[cur].unwrap();
    }
    path.reverse();
    let block = path[(path.len()) / 2];
    let mut count = 0;
    let mut stack = vec![0];
    let mut seen = vec![false; n];
    seen[0] = true;
    seen[block] = true;
    while let Some(u) = stack.pop() {
        count += 1;
        for &v in g[u].iter() {
            if !seen[v] {
                stack.push(v);
                seen[v] = true;
            }
        }
    }
    println!("{}", if 2 * count > n { "Fennec" } else { "Snuke" });
}

