fn bfs(graph: &[Vec<usize>], root: usize) -> Vec<i64> {
    let mut dists = vec![1 << 60; graph.len()];
    let mut q = vec![(root, 0)];

    while let Some((r, d)) = q.pop() {
        dists[r] = d;
        for &to in graph[r].iter() {
            if dists[to] == 1 << 60 {
                q.push((to, d + 1));
            }
        }
    }
    dists
}

fn main() {
    let n = scan!(usize);
    let mut graph: Vec<Vec<usize>> = (0..n + 1).map(|_| vec![]).collect();
    for _ in 0..n - 1 {
        let (a, b) = scan!(usize, usize);
        graph[a].push(b);
        graph[b].push(a);
    }
    let fen = bfs(&graph, 1);
    let su = bfs(&graph, n);

    let (mut fnum, mut snum) = (0, 0);
    for i in 1..graph.len() {
        if fen[i] <= su[i] {
            fnum += 1
        } else {
            snum += 1
        }
    }

    if fnum < snum {
        println!("Sunuke");
    } else {
        println!("Fennec");
    }
}

