fn main() {
    let n: usize = read();
    let ab: Vec<_> = (0..n - 1)
        .map(|_| (read::<usize>() - 1, read::<usize>() - 1))
        .collect();

    let mut graph: Vec<Vec<usize>> = vec![vec![]; n];
    for (a, b) in ab {
        graph[a].push(b);
        graph[b].push(a);
    }

    let (w, b) = calc_dist(0, n, &graph)
        .iter()
        .zip(calc_dist(n - 1, n, &graph))
        .fold(
            (0, 0),
            |(w, b), (x, y)| if *x <= y { (w + 1, b) } else { (w, b + 1) },
        );

    println!("{}", if w > b { "Fennec" } else { "Snuke" });
}

fn calc_dist(start: usize, n: usize, graph: &Vec<Vec<usize>>) -> Vec<usize> {
    let mut queue = VecDeque::new();
    let mut dist = vec![std::usize::MAX; n];

    dist[start] = 0;
    queue.push_back(start);

    while let Some(v) = queue.pop_front() {
        for &next in &graph[v] {
            if dist[next] <= dist[v] {
                continue;
            }
            dist[next] = dist[v] + 1;
            queue.push_back(next);
        }
    }
    dist
}

