enum Res {
    No,
    Mid(i32),
    Res(usize, usize),
}

fn divide(i: usize, p: usize, n: usize, c: i32, t: &Vec<Vec<usize>>) -> Res {
    if i == n {
        return Res::Mid(c);
    }
    for &j in t[i].iter() {
        if j != p {
            match divide(j, i, n, c+1, t) {
                Res::No => (),
                Res::Res(x, y) => return Res::Res(x, y),
                Res::Mid(d) if d/2 == c => return Res::Res(i, j),
                Res::Mid(d) => return Res::Mid(d)
            }
        }
    }
    Res::No
}

