type Graph = Vec<Vec<usize>>;

fn dfs1(cur: usize, par: usize, end: usize, graph: &Graph) -> usize {
    if cur == end {
        return 1;
    }
    for &n in &graph[cur] {
        if par == n {continue;}
        let r = dfs1(n, cur, end, graph);
        if r > 0 {
            return r + 1;
        }
    }
    return 0;
}

fn dfs2(cur: usize, par: usize, end: usize, graph: &Graph) -> usize {
    if cur == end {
        return 1;
    }
    let mut sum = 0;
    for &n in &graph[cur] {
        if par == n {continue;}

        sum += dfs2(n, cur, end, graph);
    }
    return 1 + sum;
}


