    let mut belongs_to_path = vec![false; n];
    path.iter().for_each(|&x| belongs_to_path[x] = true);

    let fennec = path[0..(path.len() + 1) / 2]
        .iter()
        .map(|&root| {
            fn dfs(x: usize, p: usize, g: &[Vec<usize>]) -> usize {
                1 + g[x]
                    .iter()
                    .copied()
                    .filter(|&y| y != p)
                    .map(|y| dfs(y, x, g))
                    .sum::<usize>()
            }
            1 + g[root]
                .iter()
                .copied()
                .filter(|&subroot| !belongs_to_path[subroot])
                .map(|subroot| dfs(subroot, root, &g))
                .sum::<usize>()
        })
        .sum::<usize>();
    println!("{}", if n < fennec * 2 { "Fennec" } else { "Snuke" });
}

use std::io::*;
use std::str::FromStr;
use std::collections::VecDeque;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

type Weight = i32;
#[allow(dead_code)]
#[derive(Clone, Debug, Eq, PartialEq)]
struct Edge {
    index: usize,
    src: usize,
    dest: usize,
    weight: Weight,
}
#[allow(dead_code)]
impl Edge {
    fn new(index: usize, src: usize, dest: usize, weight: Weight) -> Edge {
        Edge {
            index: index,
            src: src,
            dest: dest,
            weight: weight,
        }
    }
}
impl std::cmp::Ord for Edge {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        (self.weight, self.src, self.dest).cmp(&(other.weight, other.src, other.dest))
    }
}
impl std::cmp::PartialOrd for Edge {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
type Edges = Vec<Edge>;
type Graph = Vec<Edges>;
#[allow(dead_code)]
fn graph_new(n: usize) -> Graph {
    vec![vec![]; n]
}
#[allow(dead_code)]
fn add_bi_edge(graph: &mut Graph, index: &mut usize, src: usize, dest: usize, weight: Weight) {
    graph[src].push(Edge::new(*index, src, dest, weight));
    graph[dest].push(Edge::new(*index, dest, src, weight));
    *index += 1;
}
#[allow(dead_code)]
fn add_uni_edge(graph: &mut Graph, index: &mut usize, src: usize, dest: usize, weight: Weight) {
    graph[src].push(Edge::new(*index, src, dest, weight));
    *index += 1;
}

fn main() {
    let n = read::<usize>();
    let mut graph = graph_new(n);
    let mut e = 0;
    for i in 0..n - 1 {
        let a = read::<usize>() - 1;
        let b = read::<usize>() - 1;
        add_bi_edge(&mut graph, &mut e, a, b, 1);
    }
    let mut cnts = vec![1, 1];
    let mut que = VecDeque::<(usize, usize)>::new();
    let mut visit = vec![false; n];
    que.push_back((0, 0));
    que.push_back((n - 1, 1));
    visit[0] = true;
    visit[n - 1] = true;
    while let Some((from, player)) = que.pop_front() {
        for edge in graph[from].iter() {
            if visit[edge.dest] {
                continue;
            }
            visit[edge.dest] = true;
            que.push_back((edge.dest, player));
            cnts[player] += 1;
        }
    }
    println!("{}", if cnts[0] > cnts[1] { "Fennec" } else { "Snuke" });
}

use std::collections::BinaryHeap;

macro_rules! scan {
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($t:ty;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };

    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
}

fn wfs(graph: &[Vec<usize>], root: usize, dists: &mut [i64]) {
    let mut q = BinaryHeap::new();

    q.push((0i64, root));
    while let Some((d, r)) = q.pop() {
        if dists[r] != -1 {
            continue;
        }

        dists[r] = d;

        for &b in graph[r].iter() {
            q.push((d + 1, b))
        }
    }
}

fn main() {
    let n = scan!(usize);

    let mut graph = vec![vec![]; n + 1];
    for _ in 0..n - 1 {
        let (a, b) = scan!(usize, usize);
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut dists_f = vec![-1; n + 1];
    wfs(&graph, 1, &mut dists0);
    let mut dists_s = vec![-1; n + 1];
    wfs(&graph, n, &mut dists1);

    let (mut s, mut f) = (0, 0);
    for (d0, d1) in dists_f.iter().zip(dists_s.iter()).skip(1) {
        if d1 <= d0 {
            f += 1
        } else {
            s += 1
        }
    }

    println!("{}", if s > f { "Snuke" } else { "Fennec" })
}

use std::io::stdin;
use std::collections::VecDeque;

fn main() {
    let mut st = String::new();
    stdin().read_line(&mut st).unwrap();
    let n:usize = st.trim().parse().unwrap();
    let mut tree:Vec<Vec<usize>> = Vec::with_capacity(n);
    for _i in 0..n {
        tree.push([].to_vec());
    };

    for _i in 0..(n-1) {
        let mut st = String::new();
        stdin().read_line(&mut st).unwrap();
        let (a, b) = {
            let ab:Vec<usize> = st.trim().split(" ").map(|x| x.parse::<usize>().unwrap()).collect();
            (ab[0]-1, ab[1]-1)
        };
        tree[a].push(b);
        tree[b].push(a);
    };

    let mut s_queue:VecDeque<usize> = VecDeque::with_capacity(n);
    let mut f_queue:VecDeque<usize> = VecDeque::with_capacity(n);
    s_queue.push_back(n-1);
    f_queue.push_back(0);

    let mut visit:[i64;100002] = [-1; 100002];
    visit[0] = 0;
    visit[n-1] = 0;
    let mut s:i64 = 1;
    let mut f:i64 = 1;

    while s_queue.len() != 0 || f_queue.len() != 0 {
        if f_queue.len() != 0 {
            let p:usize = f_queue.pop_front().unwrap();
            for i in &tree[p] {
                let num = *i as usize;
                if visit[num] < 0 {
                    visit[num] = 0;
                    f += 1;
                    f_queue.push_back(num);
                };
            };
        };
        if s_queue.len() != 0 {
            let p:usize = s_queue.pop_front().unwrap();
            for i in &tree[p] {
                let num = *i as usize;
                if visit[num] < 0 {
                    visit[num] = 0;
                    s += 1;
                    s_queue.push_back(num);
                };
            };
        };
    };
    if f > s {
        println!("Fennec");
    } else {
        println!("Snuke");
    };
}

use std::collections::VecDeque;
// D
fn main() {
    input! {
        n: usize,
        ab: [(usize, usize);n-1]
    }
    let mut edges = vec![vec![]; n];
    for i in ab {
        edges[i.0 - 1].push(i.1 - 1);
        edges[i.1 - 1].push(i.0 - 1)
    }

    // 1から深さ優先探索でnまでの中間ノードを発見する
    let mut res: Vec<Vec<usize>> = Vec::new();
    let mut reached = vec![false; n];
    reached[0] = true;
    recurse(
        0,
        reached,
        vec![0],
        &mut |current, reached: Vec<bool>, roads, f| {
            if current == n - 1 {
                res.push(roads);
                return;
            }
            for edge in &edges[current] {
                if reached[*edge] {
                    continue;
                }
                let mut _reached = reached.clone();
                _reached[*edge] = true;
                let mut _roads = roads.clone();
                _roads.push(*edge);
                f(*edge, _reached, _roads)
            }
        },
    );
    //
    let road = res.pop().unwrap();
    let med_idx = (road.len() + 1) / 2 - 1;
    let med = road[med_idx];

    // 1から幅優先探索で中間ノードまでに何個濡れるかを数える
    let mut ans: Vec<usize> = vec![0];
    let mut reached = vec![false; n];
    reached[0] = true;
    recurse(
        0,
        reached,
        vec![],
        &mut |current, reached: Vec<bool>, roads: Vec<usize>, f| {
            if current == med {
                return;
            }

            for edge in &edges[current] {
                if reached[*edge] {
                    continue;
                }
                let mut _reached = reached.clone();
                _reached[*edge] = true;
                ans.push(*edge);
                f(*edge, _reached, roads.clone());
            }
        },
    );
    let f_cnt = ans.len();
    let s_cnt = n - f_cnt;
    if f_cnt > s_cnt {
        println!("Fennec");
    } else {
        println!("Snuke");
    }
}

fn recurse<X, Y, A, B>(
    x: X,
    a: A,
    b: B,
    f: &mut FnMut(X, A, B, &mut FnMut(X, A, B) -> Y) -> Y,
) -> Y {
    let fp = f as *mut FnMut(X, A, B, &mut FnMut(X, A, B) -> Y) -> Y;
    let f1 = unsafe { &mut *fp };
    let f2 = unsafe { &mut *fp };
    f1(x, a, b, &mut |x: X, a: A, b: B| recurse(x, a, b, f2))
}

#[macro_export(local_inner_maccros)]
